using System;
using System.Buffers.Binary;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Numerics;
using System.Runtime.CompilerServices;
using System.Text;
using EutherDrive.Core.Savestates;
using ProjectPSX.IO;
using SharpCompress.Archives;

namespace EutherDrive.Core.Arcade.Vegas;

public sealed class GauntletDarkLegacyAdapter : IEmulatorCore, IDisposable
{
    public const string BaselineBringupPresetEnvironmentVariable = "EUTHERDRIVE_GAUNTDL_BRINGUP_BASELINE";
    private const int FrameWidth = 640;
    private const int FrameHeight = 480;
    private const int FrameStride = FrameWidth * 4;
    private const int AudioSampleRate = 44_100;
    private const int AudioChannels = 2;

    private static readonly (string Name, string Value)[] BaselineBringupEnvironment =
    [
        ("EUTHERDRIVE_GAUNTDL_BRINGUP_FAST", "1"),
        ("EUTHERDRIVE_GAUNTDL_CPU_STEPS_PER_FRAME", "200000"),
        ("EUTHERDRIVE_GAUNTDL_FIX_RUNTIME_INTERRUPT_BRIDGE", "1"),
        ("EUTHERDRIVE_GAUNTDL_FIX_RUNTIME_INTERRUPT_SUPPRESS", "0"),
        ("EUTHERDRIVE_GAUNTDL_FIX_RUNTIME_DIAGNOSTIC_EXIT_BRIDGE", "1"),
        ("EUTHERDRIVE_GAUNTDL_FIX_AUDIO_INIT_COUNT_DELAY", "1"),
        ("EUTHERDRIVE_GAUNTDL_FIX_VOODOO_DISPLAY_BUFFER", "1"),
        ("EUTHERDRIVE_GAUNTDL_FIX_VOODOO_FASTFILL_COLOR_MASK", "1"),
        ("EUTHERDRIVE_GAUNTDL_FIX_VOODOO_TEXTURE_BASE_ADDRESS_SHIFT", "1"),
        ("EUTHERDRIVE_GAUNTDL_FIX_VOODOO_TEXTURE_DOWNLOAD_ALIGN32", "1"),
        ("EUTHERDRIVE_GAUNTDL_FIX_VOODOO_TEXTURE_BILINEAR_FILTER", "1"),
        ("EUTHERDRIVE_GAUNTDL_FIX_VOODOO_TEXTURE_COORDINATE_CLAMP", "1"),
        ("EUTHERDRIVE_GAUNTDL_FIX_VOODOO_TEXTURE_T_ORIGIN_FLIP", "0"),
        ("EUTHERDRIVE_GAUNTDL_EXPERIMENT_VOODOO_8BIT_TEXTURE_SAMPLE_REVERSE_LANES", "0"),
        ("EUTHERDRIVE_GAUNTDL_FIX_VOODOO_GAUNTLET_RASTER_Y_ORIGIN", "1"),
        ("EUTHERDRIVE_GAUNTDL_FIX_VOODOO_TEXTURE_SAMPLE_BASE_BIAS", "0"),
        ("EUTHERDRIVE_GAUNTDL_EXPERIMENT_VOODOO_TEXTURE_ALPHA8_MASK", "0"),
        ("EUTHERDRIVE_GAUNTDL_EXPERIMENT_VOODOO_FBZ_COLORPATH_RGB_COMBINE", "1"),
        ("EUTHERDRIVE_GAUNTDL_EXPERIMENT_VOODOO_TEXTURE_MAME_TRIANGLE_LOD", "1"),
        ("EUTHERDRIVE_GAUNTDL_EXPERIMENT_VOODOO_TEXTURE_MAME_SETUP_GRADIENTS", "1"),
        ("EUTHERDRIVE_GAUNTDL_EXPERIMENT_VOODOO_MAME_TEXTURE_FIXED_FETCH", "1"),
        ("EUTHERDRIVE_GAUNTDL_EXPERIMENT_VOODOO_TEXTURE_UPLOAD_TMU_BANKS", "1"),
        ("EUTHERDRIVE_GAUNTDL_EXPERIMENT_VOODOO_SEPARATE_TMU_TEXTURE_MEMORY", "1"),
        ("EUTHERDRIVE_GAUNTDL_EXPERIMENT_VOODOO_TYPE3_PREFER_TMU0_ST", "1"),
        ("EUTHERDRIVE_GAUNTDL_EXPERIMENT_VOODOO_STANDARD_FIFO_GENERATIONS", "1"),
        ("EUTHERDRIVE_GAUNTDL_EXPERIMENT_VOODOO_STANDARD_FIFO_GLOBAL_PACKET_STATE", "1"),
        ("EUTHERDRIVE_GAUNTDL_FIX_VOODOO_TYPE5_SPACE0_CMD_FIFO_RAM", "1"),
        ("EUTHERDRIVE_GAUNTDL_FIX_RUNTIME_BGLOADMODEL_QIO_REQUEST_METADATA", "1"),
        ("EUTHERDRIVE_GAUNTDL_FIX_RUNTIME_BGLOADMODEL_QIO_CREATE_ALIAS", "1"),
        ("EUTHERDRIVE_GAUNTDL_FIX_RUNTIME_BGLOADMODEL_ASSET_NAMES", "1"),
        ("EUTHERDRIVE_GAUNTDL_FIX_RUNTIME_BGLOADMODEL_STATIC_PATH_LIFECYCLE", "0"),
        ("EUTHERDRIVE_GAUNTDL_FIX_RUNTIME_BGLOADMODEL_STATIC_TEXTURE_STREAM", "1"),
        ("EUTHERDRIVE_GAUNTDL_FIX_RUNTIME_BGLOADMODEL_PARTIAL_INDEXED_SOURCE_PAYLOADS", "0"),
        ("EUTHERDRIVE_GAUNTDL_FIX_RUNTIME_BGLOADMODEL_DISTINCT_SOURCE_INDEXED_HEADER_MASK", "0x1fe"),
        ("EUTHERDRIVE_GAUNTDL_EXPERIMENT_RUNTIME_BGLOADMODEL_FULL_INDEXED_SOURCE_PAYLOADS", "0"),
        ("EUTHERDRIVE_GAUNTDL_EXPERIMENT_RUNTIME_BGLOADMODEL_INDEXED_TEXTURE_QIO", "1"),
        ("EUTHERDRIVE_GAUNTDL_FIX_RUNTIME_BGLOADMODEL_INDEXED_TEXTURE_QIO_BODY_READ", "1"),
        ("EUTHERDRIVE_GAUNTDL_EXPERIMENT_RUNTIME_BGLOADMODEL_INDEXED_TEXTURE_QIO_STREAM_LIMIT", "13"),
        ("EUTHERDRIVE_GAUNTDL_EXPERIMENT_RUNTIME_BGLOADMODEL_INDEXED_TEXTURE_QIO_SHORT_READ", "1"),
        ("EUTHERDRIVE_GAUNTDL_EXPERIMENT_RUNTIME_BGLOADMODEL_INDEXED_PREPARE_DETAIL_PRESERVE", "1"),
        ("EUTHERDRIVE_GAUNTDL_FIX_RUNTIME_TEXTURE_EXTENT", "1"),
    ];

    private readonly byte[] _frameBuffer = new byte[FrameHeight * FrameStride];
    private readonly GauntletDarkLegacyMachine _machine = new();
    private readonly bool _skipProbeFrameRender = Environment.GetEnvironmentVariable("EUTHERDRIVE_GAUNTDL_SKIP_FRAME_RENDER") == "1";
    private RomIdentity? _romIdentity;
    private string? _picNvramPath;
    private string? _timekeeperRamPath;
    private long _frameCounter;
    private bool _loaded;

    public RomIdentity? RomIdentity => _romIdentity;
    public long? FrameCounter => _loaded ? _frameCounter : null;
    public string DebugStatus => _machine.GetDebugStatus();
    public double GetTargetFps() => 60.0;

    static GauntletDarkLegacyAdapter()
    {
        ApplyBaselineBringupPresetIfRequested();
    }

    public static void ApplyBaselineBringupPreset()
    {
        foreach ((string name, string value) in BaselineBringupEnvironment)
        {
            if (string.IsNullOrWhiteSpace(Environment.GetEnvironmentVariable(name)))
                Environment.SetEnvironmentVariable(name, value);
        }
    }

    private static bool ApplyBaselineBringupPresetIfRequested()
    {
        if (!IsTruthy(Environment.GetEnvironmentVariable(BaselineBringupPresetEnvironmentVariable)))
            return false;

        ApplyBaselineBringupPreset();
        return true;
    }

    internal static bool IsBringupFixEnabled(string name)
    {
        string? specific = Environment.GetEnvironmentVariable(name);
        if (!string.IsNullOrWhiteSpace(specific))
            return IsTruthy(specific);

        return IsTruthy(Environment.GetEnvironmentVariable("EUTHERDRIVE_GAUNTDL_BRINGUP_FAST"));
    }

    public static bool IsTruthy(string? value)
        => value is not null &&
           (value == "1" ||
            value.Equals("true", StringComparison.OrdinalIgnoreCase) ||
            value.Equals("yes", StringComparison.OrdinalIgnoreCase) ||
            value.Equals("on", StringComparison.OrdinalIgnoreCase));

    public static bool IsSupportedPath(string path)
    {
        if (string.IsNullOrWhiteSpace(path))
            return false;

        string name = Path.GetFileNameWithoutExtension(path).Trim().ToLowerInvariant();
        if (name is "gauntdl" or "gauntdl24")
            return true;

        if (!VirtualFileSystem.DirectoryExists(path))
            return false;

        return VirtualFileSystem.Exists(Path.Combine(path, "gauntdl.zip")) ||
               VirtualFileSystem.Exists(Path.Combine(path, "gauntdl24.7z")) ||
               VirtualFileSystem.Exists(Path.Combine(path, "gauntdl24.zip"));
    }

    public void LoadRom(string path)
    {
        GauntletRomSet romSet = GauntletRomSet.Load(path);
        _romIdentity = romSet.CreateIdentity();
        string saveDirectory = ResolvePersistentSecurityDirectory(romSet.SourcePath);
        string saveName = romSet.SetName;
        _picNvramPath = Path.Combine(saveDirectory, $"{saveName}.picnv");
        _timekeeperRamPath = Path.Combine(saveDirectory, $"{saveName}.timekeeper");
        _machine.Load(
            romSet,
            LoadPersistentBytes(_picNvramPath, 0x100),
            LoadPersistentBytes(_timekeeperRamPath, 0x8000));
        _loaded = true;
        Reset();
    }

    public void Reset()
    {
        _frameCounter = 0;
        _machine.Reset();
        DrawDiagnosticFrame();
    }

    public void RunFrame()
    {
        if (!_loaded)
            return;

        try
        {
            EutherFrameTarget target = _skipProbeFrameRender
                ? new EutherFrameTarget(Array.Empty<byte>(), 0, 0, 0)
                : new EutherFrameTarget(_frameBuffer, FrameWidth, FrameHeight, FrameStride);
            _machine.RunFrame(target);
            _frameCounter++;
            if (!_skipProbeFrameRender && !_machine.Voodoo.HasVideoActivity)
                DrawDiagnosticFrame();
        }
        finally
        {
            FlushPersistentSecurityState();
        }
    }

    public ReadOnlySpan<byte> GetFrameBuffer(out int width, out int height, out int stride)
    {
        if (_machine.Voodoo.HasVideoActivity)
            _machine.RenderFrame(new EutherFrameTarget(_frameBuffer, FrameWidth, FrameHeight, FrameStride));

        width = FrameWidth;
        height = FrameHeight;
        stride = FrameStride;
        return _frameBuffer;
    }

    public ReadOnlySpan<short> GetAudioBuffer(out int sampleRate, out int channels)
    {
        sampleRate = AudioSampleRate;
        channels = AudioChannels;
        return _machine.Audio.GetFrameBuffer();
    }

    public void Dispose() => FlushPersistentSecurityState(force: true);

    public void SetInputState(
        bool up,
        bool down,
        bool left,
        bool right,
        bool a,
        bool b,
        bool c,
        bool start,
        bool x,
        bool y,
        bool z,
        bool mode,
        PadType padType)
    {
        _machine.Input.SetPlayer1(up, down, left, right, fight: a, magic: b, turbo: c, start, coin: mode);
        _machine.Input.SetPlayer2(up: false, down: false, left: false, right: false, fight: false, magic: false, turbo: false, start, coin: mode);
        _machine.Input.SetOperator(service: x, test: y, volumeDown: false, volumeUp: z);
    }

    public void SetPad2InputState(
        bool up,
        bool down,
        bool left,
        bool right,
        bool a,
        bool b,
        bool c,
        bool start,
        bool x,
        bool y,
        bool z,
        bool mode,
        PadType padType)
    {
        _machine.Input.SetPlayer2(up, down, left, right, fight: a, magic: b, turbo: c, start, coin: mode);
    }

    public void SetOperatorInputState(bool service, bool test, bool volumeDown, bool volumeUp)
        => _machine.Input.SetOperator(service, test, volumeDown, volumeUp);

    private void DrawDiagnosticFrame()
    {
        Array.Clear(_frameBuffer);
        uint background = _loaded ? 0xff181818u : 0xff050505u;
        FillRect(0, 0, FrameWidth, FrameHeight, background);

        int barWidth = (int)(_frameCounter % FrameWidth);
        FillRect(0, 0, barWidth, 8, 0xff2aa198u);
        FillRect(20, 28, 600, 120, 0xff242424u);
        FillRect(24, 32, _machine.RomLoaded ? 180 : 40, 16, _machine.RomLoaded ? 0xff4caf50u : 0xffa94442u);
        FillRect(24, 56, _machine.Disk.Attached ? 180 : 40, 16, _machine.Disk.Attached ? 0xff4caf50u : 0xffa94442u);
        FillRect(24, 80, _machine.Voodoo.TraceEnabled ? 180 : 80, 16, _machine.Voodoo.TraceEnabled ? 0xff268bd2u : 0xff666666u);
    }

    private void FillRect(int x, int y, int width, int height, uint bgra)
    {
        int x0 = Math.Clamp(x, 0, FrameWidth);
        int y0 = Math.Clamp(y, 0, FrameHeight);
        int x1 = Math.Clamp(x + width, 0, FrameWidth);
        int y1 = Math.Clamp(y + height, 0, FrameHeight);

        for (int py = y0; py < y1; py++)
        {
            int offset = py * FrameStride + x0 * 4;
            for (int px = x0; px < x1; px++)
            {
                _frameBuffer[offset + 0] = (byte)(bgra & 0xff);
                _frameBuffer[offset + 1] = (byte)((bgra >> 8) & 0xff);
                _frameBuffer[offset + 2] = (byte)((bgra >> 16) & 0xff);
                _frameBuffer[offset + 3] = (byte)((bgra >> 24) & 0xff);
                offset += 4;
            }
        }
    }

    private static byte[]? LoadPersistentBytes(string path, int expectedLength)
    {
        try
        {
            if (!File.Exists(path))
                return null;

            byte[] data = File.ReadAllBytes(path);
            return data.Length == expectedLength ? data : null;
        }
        catch
        {
            return null;
        }
    }

    private static string ResolvePersistentSecurityDirectory(string sourcePath)
    {
        string configured = PersistentStoragePath.ResolveSaveDirectory(sourcePath, "gauntdl");
        if (TryCreateDirectory(configured))
            return configured;

        string fallback = Path.Combine(Directory.GetCurrentDirectory(), "saves", "gauntdl");
        if (TryCreateDirectory(fallback))
            return fallback;

        return Directory.GetCurrentDirectory();
    }

    private static bool TryCreateDirectory(string path)
    {
        try
        {
            Directory.CreateDirectory(path);
            return true;
        }
        catch
        {
            return false;
        }
    }

    private void FlushPersistentSecurityState(bool force = false)
    {
        PersistSnapshotIfDirty(_picNvramPath, _machine.MemoryMap.IoasicPicNvramDirty, _machine.MemoryMap.ExportIoasicPicNvram, _machine.MemoryMap.ClearIoasicPicNvramDirty, force);
        PersistSnapshotIfDirty(_timekeeperRamPath, _machine.MemoryMap.TimekeeperRamDirty, _machine.MemoryMap.ExportTimekeeperRam, _machine.MemoryMap.ClearTimekeeperRamDirty, force);
    }

    private static void PersistSnapshotIfDirty(string? path, bool dirty, Func<byte[]> exportSnapshot, Action clearDirty, bool force)
    {
        if (string.IsNullOrWhiteSpace(path) || (!dirty && !force))
            return;

        try
        {
            File.WriteAllBytes(path, exportSnapshot());
            clearDirty();
        }
        catch
        {
            // Security NVRAM is helpful but save failures must not stop emulation.
        }
    }
}

internal sealed class GauntletDarkLegacyMachine
{
    private int _runtimeTimerTickAccumulator;
    private int _vblankGuestTimerInterruptCountdown;
    private readonly bool _splitVblankCpu = GauntletDarkLegacyAdapter.IsBringupFixEnabled("EUTHERDRIVE_GAUNTDL_SPLIT_VBLANK_CPU");
    private readonly bool _enableVblankTickBridge = GauntletDarkLegacyAdapter.IsBringupFixEnabled("EUTHERDRIVE_GAUNTDL_FIX_VBLANK_TICK_BRIDGE");
    private readonly bool _enableContextPreservingVblankTimerDispatch =
        GauntletDarkLegacyAdapter.IsTruthy(Environment.GetEnvironmentVariable("EUTHERDRIVE_GAUNTDL_EXPERIMENT_VBLANK_GUEST_TIMER_TICK"));
    private readonly bool _enableVblankGuestTimerInterrupt =
        GauntletDarkLegacyAdapter.IsTruthy(Environment.GetEnvironmentVariable("EUTHERDRIVE_GAUNTDL_EXPERIMENT_VBLANK_GUEST_TIMER_IRQ"));
    private readonly int _vblankGuestTimerInterruptInterval =
        ParsePositiveInt("EUTHERDRIVE_GAUNTDL_EXPERIMENT_VBLANK_GUEST_TIMER_IRQ_INTERVAL", 1);
    private readonly bool _enableRuntimeInputPollBridge = GauntletDarkLegacyAdapter.IsBringupFixEnabled("EUTHERDRIVE_GAUNTDL_FIX_RUNTIME_INPUT_POLL_BRIDGE");
    private readonly int _vblankCpuSteps = ParsePositiveInt("EUTHERDRIVE_GAUNTDL_VBLANK_CPU_STEPS", 2048);

    public VegasMemoryMap MemoryMap { get; } = new();
    public MipsR5000Core Cpu { get; }
    public IdeDiskDevice Disk { get; } = new();
    public VegasSioDevice Sio { get; } = new();
    public DcsAudioDevice Audio { get; } = new();
    public VoodooFacade Voodoo { get; } = new();
    public GauntletInputPanel Input { get; } = new();

    public bool RomLoaded { get; private set; }

    public GauntletDarkLegacyMachine()
    {
        MemoryMap.AttachInput(Input);
        Cpu = new MipsR5000Core(MemoryMap);
        Voodoo.SetCpuPcProvider(() => Cpu.Pc);
        Voodoo.SetCpuGprProvider(Cpu.GetGpr);
    }

    public void Load(GauntletRomSet romSet, byte[]? picNvram, byte[]? timekeeperRam)
    {
        RomLoaded = romSet.MainRom.Length == 0x80000;
        Disk.Attach(romSet.ChdPath);
        Sio.LoadBootRom(romSet.VegasSioRom);
        Audio.LoadBootRom(romSet.VegasSioRom);
        MemoryMap.LoadMainBootRom(romSet.MainRom);
        MemoryMap.LoadSecurityPic(romSet.SecurityPic);
        MemoryMap.LoadPersistentSecurityState(picNvram, timekeeperRam);
        MemoryMap.AttachDevices(Sio, Disk, Audio, Voodoo);
    }

    public void Reset()
    {
        MemoryMap.Reset();
        Cpu.Reset();
        Disk.Reset();
        Sio.Reset();
        Audio.Reset();
        Voodoo.Reset();
    }

    public void RunFrame(EutherFrameTarget target)
    {
        Voodoo.OnVblankStart();
        Sio.PulseVblank(state: true);
        if (_enableVblankTickBridge)
            MemoryMap.RecordRuntimeVblankTick();
        if (_enableVblankGuestTimerInterrupt && _vblankGuestTimerInterruptCountdown <= 0)
        {
            MemoryMap.RequestRuntimeTimerInterrupt();
            _vblankGuestTimerInterruptCountdown = _vblankGuestTimerInterruptInterval;
        }
        if (_enableVblankGuestTimerInterrupt)
            _vblankGuestTimerInterruptCountdown--;
        if (_enableContextPreservingVblankTimerDispatch)
        {
            _runtimeTimerTickAccumulator += 1000;
            while (_runtimeTimerTickAccumulator >= 60)
            {
                Cpu.RunRuntimeTimerTickPreservingContext();
                _runtimeTimerTickAccumulator -= 60;
            }
        }
        if (_enableRuntimeInputPollBridge)
            MemoryMap.RecordRuntimeInputPollEffects();
        if (_splitVblankCpu)
        {
            Cpu.RunProbeSteps(_vblankCpuSteps);
            Sio.PulseVblank(state: false);
            Cpu.RunProbeFrameAfterSteps(_vblankCpuSteps);
        }
        else
        {
            Cpu.RunProbeFrame();
            Sio.PulseVblank(state: false);
        }
        if (_enableRuntimeInputPollBridge)
            MemoryMap.RecordRuntimeInputPollEffects();
        MemoryMap.StepFrame();
        Audio.RunFrame();
        if (MemoryMap.ConsumeWatchdogResetRequest())
            Reset();
        RenderFrame(target);
    }

    public void RenderFrame(EutherFrameTarget target)
    {
        Voodoo.RenderFrame(target);
        if (ShouldRenderCpuBootSurface(target))
            RenderCpuBootSurface(target);
    }

    public string GetDebugStatus()
    {
        return $"pc=0x{Cpu.Pc:X16} op=0x{Cpu.LastFetchedInstruction:X8} " +
               $"{Cpu.RuntimeDiagnosticStatus} " +
               $"voodoo={(Voodoo.HasVideoActivity ? "active" : "idle")} {Voodoo.DebugStatus} " +
               $"{MemoryMap.DebugStatus} {Audio.DebugStatus} disk={(Disk.Attached ? "attached" : "missing")}";
    }

    private bool ShouldRenderCpuBootSurface(EutherFrameTarget target)
        => GauntletDarkLegacyAdapter.IsBringupFixEnabled("EUTHERDRIVE_GAUNTDL_RENDER_TILE_BOOT_SURFACE") &&
           target.Buffer is not null &&
           target.Width > 0 &&
           target.Height > 0 &&
           target.Stride >= target.Width * 4 &&
           Cpu.TileWriteCount > 0 &&
           !Voodoo.HasVideoActivity &&
           !Voodoo.HasDrawPackets;

    private void RenderCpuBootSurface(EutherFrameTarget target)
    {
        const ulong surface = 0xffffffff800ed62aUL;
        const int sourceWidth = 640;
        const int sourceHeight = 240;
        const int sourceStride = 2048;

        ClearTarget(target, 0xff000000u);
        int copyWidth = Math.Min(target.Width, sourceWidth);
        int copyHeight = Math.Min(target.Height, sourceHeight);
        for (int y = 0; y < copyHeight; y++)
        {
            ulong sourceRow = surface + (ulong)(y * sourceStride);
            int destination = y * target.Stride;
            for (int x = 0; x < copyWidth; x++)
            {
                ushort rgb = MemoryMap.Read16(sourceRow + (ulong)(x * 2));
                uint bgra = Rgb565ToBgra(rgb);
                target.Buffer[destination + 0] = (byte)(bgra & 0xff);
                target.Buffer[destination + 1] = (byte)((bgra >> 8) & 0xff);
                target.Buffer[destination + 2] = (byte)((bgra >> 16) & 0xff);
                target.Buffer[destination + 3] = 0xff;
                destination += 4;
            }
        }
    }

    private static void ClearTarget(EutherFrameTarget target, uint bgra)
    {
        for (int y = 0; y < target.Height; y++)
        {
            int offset = y * target.Stride;
            for (int x = 0; x < target.Width; x++)
            {
                target.Buffer[offset + 0] = (byte)(bgra & 0xff);
                target.Buffer[offset + 1] = (byte)((bgra >> 8) & 0xff);
                target.Buffer[offset + 2] = (byte)((bgra >> 16) & 0xff);
                target.Buffer[offset + 3] = (byte)((bgra >> 24) & 0xff);
                offset += 4;
            }
        }
    }

    private static uint Rgb565ToBgra(ushort rgb)
    {
        uint r = (uint)((rgb >> 11) & 0x1f);
        uint g = (uint)((rgb >> 5) & 0x3f);
        uint b = (uint)(rgb & 0x1f);
        r = (r << 3) | (r >> 2);
        g = (g << 2) | (g >> 4);
        b = (b << 3) | (b >> 2);
        return 0xff000000u | (r << 16) | (g << 8) | b;
    }

    private static int ParsePositiveInt(string name, int fallback)
    {
        string? raw = Environment.GetEnvironmentVariable(name);
        return TryParsePositiveInt(raw, out int parsed) ? parsed : fallback;
    }

    private static bool TryParsePositiveInt(string? raw, out int parsed)
    {
        parsed = 0;
        if (string.IsNullOrWhiteSpace(raw))
            return false;

        raw = raw.Trim();
        if (raw.StartsWith("0x", StringComparison.OrdinalIgnoreCase))
        {
            return int.TryParse(
                    raw[2..],
                    System.Globalization.NumberStyles.HexNumber,
                    null,
                    out parsed) &&
                parsed > 0;
        }

        return int.TryParse(raw, out parsed) && parsed > 0;
    }
}

internal sealed class GauntletRomSet
{
    private static readonly IReadOnlyDictionary<string, string> DiskBySet = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
    {
        ["gauntdl"] = "gauntdl.chd",
        ["gauntdl24"] = "gauntd24.chd"
    };

    private GauntletRomSet(string setName, string sourcePath, byte[] mainRom, byte[] vegasSioRom, byte[] securityPic, string? chdPath)
    {
        SetName = setName;
        SourcePath = sourcePath;
        MainRom = mainRom;
        VegasSioRom = vegasSioRom;
        SecurityPic = securityPic;
        ChdPath = chdPath;
    }

    public string SetName { get; }
    public string SourcePath { get; }
    public byte[] MainRom { get; }
    public byte[] VegasSioRom { get; }
    public byte[] SecurityPic { get; }
    public string? ChdPath { get; }

    public static GauntletRomSet Load(string path)
    {
        string archivePath = ResolveArchivePath(path);
        string setName = Path.GetFileNameWithoutExtension(archivePath).ToLowerInvariant();
        Dictionary<string, byte[]> entries = ReadEntries(archivePath);

        byte[] mainRom = RequireEntry(entries, "gauntdl.bin", 0x80000);
        byte[] sioRom = RequireEntry(entries, "vegassio.bin", 0x8000);
        byte[] securityPic = RequireEntry(entries, "346_gauntlet-dl.u37", 0x2000);
        string? chdPath = ResolveChdPath(archivePath, setName);

        return new GauntletRomSet(setName, archivePath, mainRom, sioRom, securityPic, chdPath);
    }

    public RomIdentity CreateIdentity()
    {
        using var stream = new MemoryStream();
        stream.Write(MainRom);
        stream.Write(VegasSioRom);
        stream.Write(SecurityPic);

        if (!string.IsNullOrWhiteSpace(ChdPath) && VirtualFileSystem.Exists(ChdPath))
        {
            byte[] pathBytes = System.Text.Encoding.UTF8.GetBytes(Path.GetFileName(ChdPath));
            stream.Write(pathBytes);
        }

        stream.Position = 0;
        return new RomIdentity(SetName, RomIdentity.ComputeSha256(stream), PersistentStoragePath.ResolveSavestateDirectory(SourcePath, "gauntdl"));
    }

    private static string ResolveArchivePath(string path)
    {
        if (VirtualFileSystem.Exists(path))
            return Path.GetFullPath(path);

        if (!VirtualFileSystem.DirectoryExists(path))
            throw new FileNotFoundException("Gauntlet Dark Legacy ROM archive or directory not found.", path);

        string[] candidates =
        {
            Path.Combine(path, "gauntdl24.7z"),
            Path.Combine(path, "gauntdl24.zip"),
            Path.Combine(path, "gauntdl.zip")
        };

        foreach (string candidate in candidates)
        {
            if (VirtualFileSystem.Exists(candidate))
                return Path.GetFullPath(candidate);
        }

        throw new FileNotFoundException("Directory does not contain gauntdl.zip, gauntdl24.7z, or gauntdl24.zip.", path);
    }

    private static Dictionary<string, byte[]> ReadEntries(string archivePath)
    {
        var entries = new Dictionary<string, byte[]>(StringComparer.OrdinalIgnoreCase);
        AddArchiveEntries(archivePath, entries);

        string directory = Path.GetDirectoryName(archivePath) ?? Environment.CurrentDirectory;
        foreach (string sibling in EnumerateSiblingSetArchives(directory, archivePath))
            AddArchiveEntries(sibling, entries);

        return entries;
    }

    private static void AddArchiveEntries(string archivePath, Dictionary<string, byte[]> entries)
    {
        using IArchive archive = RomArchiveExtractor.OpenArchive(archivePath);
        foreach (IArchiveEntry entry in archive.Entries)
        {
            if (entry.IsDirectory)
                continue;

            string name = Path.GetFileName(entry.Key);
            if (entries.ContainsKey(name))
                continue;

            using Stream entryStream = entry.OpenEntryStream();
            using var ms = new MemoryStream();
            entryStream.CopyTo(ms);
            entries[name] = ms.ToArray();
        }
    }

    private static IEnumerable<string> EnumerateSiblingSetArchives(string directory, string primaryArchivePath)
    {
        string primaryFullPath = Path.GetFullPath(primaryArchivePath);
        string[] candidates =
        {
            Path.Combine(directory, "gauntdl24.7z"),
            Path.Combine(directory, "gauntdl24.zip"),
            Path.Combine(directory, "gauntdl.zip")
        };

        foreach (string candidate in candidates)
        {
            if (VirtualFileSystem.Exists(candidate) &&
                !string.Equals(Path.GetFullPath(candidate), primaryFullPath, StringComparison.OrdinalIgnoreCase))
            {
                yield return candidate;
            }
        }
    }

    private static byte[] RequireEntry(Dictionary<string, byte[]> entries, string name, int expectedLength)
    {
        if (!entries.TryGetValue(name, out byte[]? data))
            throw new InvalidDataException($"Gauntlet Dark Legacy ROM archive is missing required entry '{name}'.");
        if (data.Length != expectedLength)
            throw new InvalidDataException($"ROM entry '{name}' has {data.Length} bytes; expected {expectedLength}.");
        return data;
    }

    private static string? ResolveChdPath(string archivePath, string setName)
    {
        string directory = Path.GetDirectoryName(archivePath) ?? Environment.CurrentDirectory;
        if (DiskBySet.TryGetValue(setName, out string? expected))
        {
            string expectedPath = Path.Combine(directory, expected);
            if (VirtualFileSystem.Exists(expectedPath))
                return expectedPath;
        }

        return VirtualFileSystem.GetFiles(directory, "*.chd").FirstOrDefault();
    }
}

