                            {
                                string transform = DescribeZeroBaseUploadDiskWordTransform(diskWord, transformedDiskWord);
                                Console.WriteLine(
                                    $"[GAUNTDL:EXPERIMENT] zero-base-upload-disk-word " +
                                    $"targetWord=0x{packetTargetWord:x8} addr=0x{source:x16} {diskSource} mem=0x{payloadWord:x8}->disk=0x{diskWord:x8}{transform} " +
                                    $"packet={packet} index={index}/{limit} word={word}/{payloadWords}");
                            }

                            payloadWord = transformedDiskWord;
                        }
                    }
                    else if (_experimentZeroBaseUploadZeroDiskWordIndexedSourceMask != 0 &&
                        sourceBase == 0 &&
                        payloadWord == 0 &&
                        (!_experimentZeroBaseUploadZeroDiskWordRunSource.HasValue ||
                            uploadRunSource == _experimentZeroBaseUploadZeroDiskWordRunSource.Value) &&
                        TryReadKnownRuntimeBgLoadModelUploadZeroDiskWord(source, out diskWord, out diskSource))
                    {
                        uint transformedDiskWord = TransformZeroBaseUploadDiskWord(diskWord);
                        if (_textureUploadPayloadDiskWordTraceCount++ < 64)
                        {
                            string transform = DescribeZeroBaseUploadDiskWordTransform(diskWord, transformedDiskWord);
                            Console.WriteLine(
                                $"[GAUNTDL:EXPERIMENT] zero-base-upload-zero-disk-word " +
                                $"addr=0x{source:x16} {diskSource} mem=0x{payloadWord:x8}->disk=0x{diskWord:x8}{transform} " +
                                $"packet={packet} index={index}/{limit} word={word}/{payloadWords}");
                        }

                        payloadWord = transformedDiskWord;
                    }

                    if (_experimentZeroBaseUploadZeroTargetWords.Length != 0 &&
                        sourceBase == 0 &&
                        Array.IndexOf(_experimentZeroBaseUploadZeroTargetWords, (ulong)packetTargetWord) >= 0)
                    {
                        if (_textureUploadPayloadZeroTargetWordTraceCount++ < _experimentZeroBaseUploadZeroTargetWordsTraceLimit &&
                            payloadWord != 0)
                        {
                            Console.WriteLine(
                                $"[GAUNTDL:EXPERIMENT] zero-base-upload-zero-target-word " +
                                $"targetWord=0x{packetTargetWord:x8} addr=0x{source:x16} mem=0x{payloadWord:x8}->zero " +
                                $"packet={packet} index={index}/{limit} word={word}/{payloadWords} " +
                                $"run=0x{uploadRunSource:x16} {DescribeKnownRuntimeBgLoadModelUploadSource(uploadRunSource)}");
                        }

                        payloadWord = 0;
                    }

                    _memory.SetVoodooCommandFifoBulkWriteSource(source, sourceBase, packetSourceAddress, packet, index, limit, word, payloadWords);
                    if (_fixVoodooMameCommandFifoModel)
                    {
                        WriteGlideFifoWord(ref fifo, payloadWord, fifoRingBase, fifoRingBytes);
                    }
                    else
                    {
                        _memory.Write32(fifo, payloadWord);
                        fifo += 4U;
                    }
                    source = SignExtend32((uint)(source + 4UL));
                }

                skippedInstructions += 30UL + (ulong)(payloadWords / 2U) * 9UL;
                writtenPackets++;
            }
        }
        finally
        {
            _memory.ClearVoodooCommandFifoBulkWriteSource();
            _memory.EndVoodooCommandFifoBulkWrite();
        }

        uint updatedRoom = room - writtenPackets * packetBytes;
        _memory.Write32(state + 0x374UL, fifo);
        _memory.Write32(state + 0x37cUL, updatedRoom);

        uint finalIndex = limit + 1U;
        _gpr[2] = 1;
        _gpr[3] = 0x01ffffffUL;
        _gpr[4] = SignExtend32(fifo);
        _gpr[5] = payloadWords;
        _gpr[17] = SignExtend32(unchecked(currentPacketAddress + (packets - 1U) * packetAddressStride));
        _gpr[18] = finalIndex;
        _gpr[19] = packetBytes;
        _gpr[22] = source;
        _gpr[23] = SignExtend32(header);
        _gpr[0] = 0;
        _hasPendingBranch = false;
        _hasImmediatePcOverride = false;
        AdvanceCp0Count(_cp0CountStep * Math.Max(1UL, skippedInstructions));
        _instructionCounter += Math.Max(1UL, skippedInstructions);
        Pc = exit;
        return true;
    }

    private uint TransformZeroBaseUploadDiskWord(uint word)
    {
        return _experimentZeroBaseUploadDiskWordTransform switch
        {
            "be32" or "reverse32" or "byteswap32" => BinaryPrimitives.ReverseEndianness(word),
            "swap16" or "halfswap" => (word << 16) | (word >> 16),
            "reverse16" or "byteswap16" or "swapbytes16" => ((word & 0x00ff00ffU) << 8) | ((word & 0xff00ff00U) >> 8),
            _ => word,
        };
    }

    private bool ShouldKeepZeroBaseUploadMemoryWordForTarget(uint targetWord)
    {
        if (_experimentZeroBaseUploadDiskWordIncludeTargetWords.Length != 0 &&
            !_experimentZeroBaseUploadDiskWordIncludeTargetWords.Contains(targetWord))
        {
            return true;
        }

        return _experimentZeroBaseUploadDiskWordExcludeTargetWords.Length != 0 &&
            _experimentZeroBaseUploadDiskWordExcludeTargetWords.Contains(targetWord);
    }

    private string DescribeZeroBaseUploadDiskWordTransform(uint originalWord, uint transformedWord)
    {
        if (transformedWord == originalWord ||
            string.IsNullOrEmpty(_experimentZeroBaseUploadDiskWordTransform) ||
            _experimentZeroBaseUploadDiskWordTransform == "none" ||
            _experimentZeroBaseUploadDiskWordTransform == "le" ||
            _experimentZeroBaseUploadDiskWordTransform == "little")
        {
            return "";
        }

        return $" transform={_experimentZeroBaseUploadDiskWordTransform}:0x{transformedWord:x8}";
    }

    private bool TryReadKnownRuntimeBgLoadModelUploadZeroDiskWord(
        ulong address,
        out uint word,
        out string sourceDescription)
    {
        const ulong destinationBase = 0xffffffff802e1718UL;
        ulong sourceStride = (ulong)_runtimeBgLoadModelIndexedSourceStride;

        word = 0;
        sourceDescription = "";
        for (ulong index = 1; index <= KnownRuntimeBgLoadModelTexturePayloadMaxIndex; index++)
        {
            if ((_experimentZeroBaseUploadZeroDiskWordIndexedSourceMask & (1UL << (int)index)) == 0 ||
                !TryGetKnownRuntimeBgLoadModelTexturePayload(index, out string code, out ulong byteOffset, out uint textureByteLength))
            {
                continue;
            }

            ulong candidateBase = destinationBase + index * sourceStride;
            ulong candidateEnd = candidateBase + GetKnownRuntimeBgLoadModelSourceSpanByteLength(textureByteLength);
            if (address < candidateBase || address >= candidateEnd)
                continue;

            ulong candidateOffset = address - candidateBase;
            if (candidateOffset < _experimentZeroBaseUploadZeroDiskWordMinOffset ||
                candidateOffset > _experimentZeroBaseUploadZeroDiskWordMaxOffset)
            {
                continue;
            }

            if (!_memory.TryReadDiskByteOffsetWord(byteOffset + candidateOffset, out uint candidateWord) ||
                candidateWord == 0)
            {
                continue;
            }

            word = candidateWord;
            sourceDescription = $"{index}:{code}@0x{candidateOffset:x}";
        }

        return sourceDescription.Length > 0;
    }

    private ulong NormalizeZeroBaseTextureUploadSourceStart(
        ulong source,
        uint sourceBase,
        ulong sourceBytes,
        uint payloadWords,
        uint index,
        uint limit)
    {
        if (sourceBase != 0)
            return source;

        if (_experimentZeroBaseUploadMaskSourceLowBit &&
            (source & 1UL) != 0 &&
            (!_experimentZeroBaseUploadMaskSourceLowBitOnlySource.HasValue ||
                source == _experimentZeroBaseUploadMaskSourceLowBitOnlySource.Value))
        {
            ulong maskedSource = source & ~1UL;
            if (IsMainRamRange(maskedSource, sourceBytes))
            {
                if (_textureUploadPayloadSourceLowBitMaskTraceCount++ < 64)
                {
                    Console.WriteLine(
                        $"[GAUNTDL:EXPERIMENT] zero-base-upload-mask-source-low-bit " +
                        $"source=0x{source:x16}->0x{maskedSource:x16} " +
                        $"only=0x{(_experimentZeroBaseUploadMaskSourceLowBitOnlySource ?? 0UL):x16} " +
                        $"bytes=0x{sourceBytes:x} index={index}/{limit} words={payloadWords} " +
                        $"originalFirst={ReadTraceWord(source):x8}/{ReadTraceWord(source + 0x04UL):x8}/" +
                        $"{ReadTraceWord(source + 0x08UL):x8}/{ReadTraceWord(source + 0x0cUL):x8} " +
                        $"maskedFirst={ReadTraceWord(maskedSource):x8}/{ReadTraceWord(maskedSource + 0x04UL):x8}/" +
                        $"{ReadTraceWord(maskedSource + 0x08UL):x8}/{ReadTraceWord(maskedSource + 0x0cUL):x8}");
                }

                source = maskedSource;
            }
        }

        bool knownSource = IsKnownRuntimeBgLoadModelUploadSourceCandidateForZeroBasePrefix(source);
        if (_experimentZeroBaseUploadDescriptorSourceTableDerivedSource &&
            !knownSource &&
            IsMainRamRange(source + 0x10UL, 4))
        {
            const ulong sourceTable = 0xffffffff802529a0UL;
            uint descriptorKey = _memory.Read32(source + 0x10UL);
            uint sourceIndex = descriptorKey >> 16;
            uint localIndex = descriptorKey & 0xffffU;
            if (sourceIndex < 0x40U &&
                IsMainRamRange(sourceTable + sourceIndex * 4UL, 4))
            {
                uint tableSource = _memory.Read32(sourceTable + sourceIndex * 4UL);
                ulong localOffset = (ulong)localIndex * 0x8cUL + 0x68UL;
                ulong tableDerivedCandidate = SignExtend32(unchecked(tableSource + (uint)localOffset));
                if (tableSource != 0 &&
                    tableDerivedCandidate != source &&
                    IsMainRamRange(tableDerivedCandidate, sourceBytes))
                {
                    if (_traceTextureUploadPayload &&
                        AllowsTextureUploadRunSourceTrace(tableDerivedCandidate) &&
                        _textureUploadPayloadPointerStartTraceCount++ < 64)
                    {
                        Console.WriteLine(
                            $"[GAUNTDL:EXPERIMENT] zero-base-upload-descriptor-source-table-derived-source " +
                            $"source=0x{source:x16}->0x{tableDerivedCandidate:x16} index={sourceIndex} local=0x{localIndex:x} " +
                            $"table=0x{tableSource:x8} localOffset=0x{localOffset:x} " +
                            $"{DescribeKnownRuntimeBgLoadModelUploadSource(tableDerivedCandidate)} " +
                            $"bytes=0x{sourceBytes:x} packets={limit - index + 1U} words={payloadWords} " +
                            $"descriptor={ReadTraceWord(source):x8}/{ReadTraceWord(source + 0x04UL):x8}/" +
                            $"{ReadTraceWord(source + 0x08UL):x8}/{ReadTraceWord(source + 0x0cUL):x8}/" +
                            $"{ReadTraceWord(source + 0x10UL):x8}/{ReadTraceWord(source + 0x14UL):x8}/" +
                            $"{ReadTraceWord(source + 0x18UL):x8}/{ReadTraceWord(source + 0x1cUL):x8}");
                    }

                    return tableDerivedCandidate;
                }
            }
        }

        if (_experimentZeroBaseUploadDescriptorSourceAddOffset.HasValue &&
            !knownSource)
        {
            ulong addOffset = _experimentZeroBaseUploadDescriptorSourceAddOffset.Value;
            if (addOffset is >= 4UL and <= 0x400UL &&
                (addOffset & 3UL) == 0)
            {
                ulong offsetCandidate = SignExtend32(unchecked((uint)(source + addOffset)));
                if (offsetCandidate != source &&
                    IsMainRamRange(offsetCandidate, sourceBytes))
                {
                    if (_traceTextureUploadPayload &&
                        AllowsTextureUploadRunSourceTrace(offsetCandidate) &&
                        _textureUploadPayloadPointerStartTraceCount++ < 64)
                    {
                        Console.WriteLine(
                            $"[GAUNTDL:EXPERIMENT] zero-base-upload-descriptor-source-add-offset " +
                            $"source=0x{source:x16}->0x{offsetCandidate:x16} offset=0x{addOffset:x} " +
                            $"{DescribeKnownRuntimeBgLoadModelUploadSource(offsetCandidate)} " +
                            $"bytes=0x{sourceBytes:x} index={index}/{limit} words={payloadWords} " +
                            $"descriptor={ReadTraceWord(source):x8}/{ReadTraceWord(source + 0x04UL):x8}/" +
                            $"{ReadTraceWord(source + 0x08UL):x8}/{ReadTraceWord(source + 0x0cUL):x8}/" +
                            $"{ReadTraceWord(source + 0x10UL):x8}/{ReadTraceWord(source + 0x14UL):x8}/" +
                            $"{ReadTraceWord(source + 0x18UL):x8}/{ReadTraceWord(source + 0x1cUL):x8} " +
                            $"first={ReadTraceWord(offsetCandidate):x8}/{ReadTraceWord(offsetCandidate + 0x04UL):x8}/" +
                            $"{ReadTraceWord(offsetCandidate + 0x08UL):x8}/{ReadTraceWord(offsetCandidate + 0x0cUL):x8}");
                    }

                    return offsetCandidate;
                }
            }
        }

        if (_experimentZeroBaseUploadDescriptorSourcePointerOffset.HasValue &&
            !knownSource)
        {
            ulong pointerOffset = _experimentZeroBaseUploadDescriptorSourcePointerOffset.Value;
            if (pointerOffset is >= 4UL and <= 0x80UL &&
                (pointerOffset & 3UL) == 0 &&
                IsMainRamRange(source + pointerOffset, 4))
            {
                ulong pointerCandidate = SignExtend32(_memory.Read32(source + pointerOffset));
                if (_experimentZeroBaseUploadDescriptorSourceNodePointerOffset.HasValue &&
                    pointerCandidate != source &&
                    pointerCandidate != 0 &&
                    IsMainRamRange(pointerCandidate, 4))
                {
                    ulong nodePointerOffset = _experimentZeroBaseUploadDescriptorSourceNodePointerOffset.Value;
                    if (nodePointerOffset is <= 0x100UL &&
                        (nodePointerOffset & 3UL) == 0 &&
                        IsMainRamRange(pointerCandidate + nodePointerOffset, 4))
                    {
                        ulong nodePointerCandidate = SignExtend32(_memory.Read32(pointerCandidate + nodePointerOffset));
                        if (nodePointerCandidate != pointerCandidate &&
                            nodePointerCandidate != source &&
                            nodePointerCandidate != 0 &&
                            IsMainRamRange(nodePointerCandidate, sourceBytes))
                        {
                            if (_traceTextureUploadPayload &&
                                AllowsTextureUploadRunSourceTrace(nodePointerCandidate) &&
                                _textureUploadPayloadPointerStartTraceCount++ < 64)
                            {
                                Console.WriteLine(
                                    $"[GAUNTDL:EXPERIMENT] zero-base-upload-descriptor-source-node-pointer " +
                                    $"source=0x{source:x16}->0x{pointerCandidate:x16}->0x{nodePointerCandidate:x16} " +
                                    $"descriptorOffset=0x{pointerOffset:x} nodeOffset=0x{nodePointerOffset:x} " +
                                    $"{DescribeKnownRuntimeBgLoadModelUploadSource(nodePointerCandidate)} " +
                                    $"bytes=0x{sourceBytes:x} index={index}/{limit} words={payloadWords} " +
                                    $"descriptor={ReadTraceWord(source):x8}/{ReadTraceWord(source + 0x04UL):x8}/" +
                                    $"{ReadTraceWord(source + 0x08UL):x8}/{ReadTraceWord(source + 0x0cUL):x8}/" +
                                    $"{ReadTraceWord(source + 0x10UL):x8}/{ReadTraceWord(source + 0x14UL):x8}/" +
                                    $"{ReadTraceWord(source + 0x18UL):x8}/{ReadTraceWord(source + 0x1cUL):x8} " +
                                    $"node={ReadTraceWord(pointerCandidate):x8}/{ReadTraceWord(pointerCandidate + 0x04UL):x8}/" +
                                    $"{ReadTraceWord(pointerCandidate + 0x18UL):x8}/{ReadTraceWord(pointerCandidate + 0x1cUL):x8}/" +
                                    $"{ReadTraceWord(pointerCandidate + 0x20UL):x8}/{ReadTraceWord(pointerCandidate + 0x90UL):x8}");
                            }

                            return nodePointerCandidate;
                        }
                    }
                }

                if (pointerCandidate != source &&
                    pointerCandidate != 0 &&
                    IsMainRamRange(pointerCandidate, sourceBytes))
                {
                    if (_traceTextureUploadPayload &&
                        AllowsTextureUploadRunSourceTrace(pointerCandidate) &&
                        _textureUploadPayloadPointerStartTraceCount++ < 64)
                    {
                        Console.WriteLine(
                            $"[GAUNTDL:EXPERIMENT] zero-base-upload-descriptor-source-pointer " +
                            $"source=0x{source:x16}->0x{pointerCandidate:x16} offset=0x{pointerOffset:x} " +
                            $"{DescribeKnownRuntimeBgLoadModelUploadSource(source)} " +
                            $"bytes=0x{sourceBytes:x} index={index}/{limit} words={payloadWords} " +
                            $"descriptor={ReadTraceWord(source):x8}/{ReadTraceWord(source + 0x04UL):x8}/" +
                            $"{ReadTraceWord(source + 0x08UL):x8}/{ReadTraceWord(source + 0x0cUL):x8}/" +
                            $"{ReadTraceWord(source + 0x10UL):x8}/{ReadTraceWord(source + 0x14UL):x8}/" +
                            $"{ReadTraceWord(source + 0x18UL):x8}/{ReadTraceWord(source + 0x1cUL):x8}");
                    }

                    return pointerCandidate;
                }
            }
        }

        if (_experimentZeroBaseUploadPointerStartUnknown &&
            !knownSource &&
            IsMainRamRange(source + 0x08UL, 4))
        {
            ulong pointerCandidate = SignExtend32(_memory.Read32(source + 0x08UL));
            if (pointerCandidate == source + 0x0cUL &&
                IsMainRamRange(pointerCandidate, sourceBytes))
            {
                if (_traceTextureUploadPayload &&
                    AllowsTextureUploadRunSourceTrace(pointerCandidate) &&
                    _textureUploadPayloadPointerStartTraceCount++ < 64)
                {
                    Console.WriteLine(
                        $"[GAUNTDL:EXPERIMENT] zero-base-upload-pointer-start-unknown " +
                        $"source=0x{source:x16}->0x{pointerCandidate:x16} " +
                        $"{DescribeKnownRuntimeBgLoadModelUploadSource(source)} " +
                        $"bytes=0x{sourceBytes:x} index={index}/{limit} words={payloadWords} " +
                        $"first={ReadTraceWord(source):x8}/{ReadTraceWord(source + 0x04UL):x8}/" +
                        $"{ReadTraceWord(source + 0x08UL):x8}/{ReadTraceWord(source + 0x0cUL):x8}");
                }

                return pointerCandidate;
            }
        }

        if (_experimentZeroBaseUploadSkipUnknownPrefix &&
            !knownSource &&
            TryFindNextKnownRuntimeBgLoadModelUploadSource(
                source,
                source + sourceBytes,
                0x2000UL,
                out ulong nextKnownSource,
                out ulong nextKnownIndex,
                out string nextKnownCode))
        {
            if (_textureUploadPayloadPointerStartTraceCount < 64 &&
                _zeroBaseUploadUnknownPrefixTraceSources.Add(source))
            {
                _textureUploadPayloadPointerStartTraceCount++;
                ulong prefixBytes = nextKnownSource - source;
                Console.WriteLine(
                    $"[GAUNTDL:EXPERIMENT] zero-base-upload-skip-unknown-prefix " +
                    $"source=0x{source:x16}->0x{nextKnownSource:x16} prefix=0x{prefixBytes:x} " +
                    $"index={index}/{limit} words={payloadWords} next={nextKnownIndex}:{nextKnownCode} " +
                    $"runFirst={ReadTraceWord(source):x8}/{ReadTraceWord(source + 0x04UL):x8}/" +
                    $"{ReadTraceWord(source + 0x08UL):x8}/{ReadTraceWord(source + 0x0cUL):x8} " +
                    $"span={FormatKnownRuntimeBgLoadModelUploadSpan(source, nextKnownSource + Math.Min(sourceBytes, 0x2000UL), 8)}");
            }

            return nextKnownSource;
        }

        if (!knownSource || !IsMainRamRange(source + 0x08UL, 4))
        {
            return source;
        }

        ulong candidate = SignExtend32(_memory.Read32(source + 0x08UL));
        if (candidate != source + 0x0cUL ||
            !IsMainRamRange(candidate, sourceBytes))
        {
            return source;
        }

        if (_traceTextureUploadPayload &&
            AllowsTextureUploadRunSourceTrace(candidate) &&
            _textureUploadPayloadPointerStartTraceCount++ < 64)
        {
            Console.WriteLine(
                $"[GAUNTDL:TEXUPLOAD-PTRSTART] " +
                $"source=0x{source:x16}->{candidate:x16} {DescribeKnownRuntimeBgLoadModelUploadSource(source)} " +
                $"bytes=0x{sourceBytes:x} index={index}/{limit} words={payloadWords} " +
                $"first={ReadTraceWord(source):x8}/{ReadTraceWord(source + 0x04UL):x8}/{ReadTraceWord(source + 0x08UL):x8}/{ReadTraceWord(source + 0x0cUL):x8}");
        }

        return candidate;
    }

    private bool TryFindNextKnownRuntimeBgLoadModelUploadSource(
        ulong start,
        ulong end,
        ulong maxUnknownPrefixBytes,
        out ulong source,
        out ulong index,
        out string code)
    {
        const ulong destinationBase = 0xffffffff802e1718UL;
        ulong sourceStride = (ulong)_runtimeBgLoadModelIndexedSourceStride;

        source = 0;
        index = 0;
        code = "";
        if (end <= start)
            return false;

        ulong best = ulong.MaxValue;
        ulong bestIndex = 0;
        string bestCode = "";
        for (ulong candidateIndex = 1; candidateIndex <= KnownRuntimeBgLoadModelTexturePayloadMaxIndex; candidateIndex++)
        {
            if (!TryGetKnownRuntimeBgLoadModelTexturePayload(candidateIndex, out string candidateCode, out _, out _))
                continue;

            ulong candidate = destinationBase + candidateIndex * sourceStride;
            if (candidate <= start ||
                candidate >= end ||
                candidate - start > maxUnknownPrefixBytes ||
                !IsMainRamRange(candidate, 4))
            {
                continue;
            }

            if (candidate < best)
            {
                best = candidate;
                bestIndex = candidateIndex;
                bestCode = candidateCode;
            }
        }

        if (best == ulong.MaxValue)
            return false;

        source = best;
        index = bestIndex;
        code = bestCode;
        return true;
    }

    private bool AllowsTextureUploadRunSourceTrace(ulong source)
        => !_traceTextureUploadRunSource.HasValue ||
           source == CanonicalizeTraceAddress(_traceTextureUploadRunSource.Value);

    private static ulong CanonicalizeTraceAddress(ulong address)
        => (address & 0xffffffff00000000UL) == 0 && (address & 0x80000000UL) != 0
            ? SignExtend32((uint)address)
            : address;

    private static ulong CanonicalizeOptionalTraceAddress(ulong? address, ulong fallback)
        => address.HasValue ? CanonicalizeTraceAddress(address.Value) : fallback;

    private void TraceTextureUploadSourceSelectorSetup(ulong pc, uint op, string phase)
    {
        const ulong defaultPcMin = 0xffffffff800fe180UL;
        const ulong defaultPcMax = 0xffffffff800fe228UL;

        if (!_traceTextureUploadSourceSelectorSetup ||
            _textureUploadSourceSelectorSetupTraceCount >= _traceTextureUploadSourceSelectorSetupLimit)
            return;

        ulong pcMin = _traceTextureUploadSourceSelectorSetupPcMin ?? defaultPcMin;
        ulong pcMax = _traceTextureUploadSourceSelectorSetupPcMax ?? defaultPcMax;
        if (pc < pcMin || pc > pcMax)
            return;

        ulong sp = _gpr[29];
        if (!IsMainRamRange(sp + 0x60UL, 0x1cUL))
            return;

        ulong selectedSource = SignExtend32(ReadTraceWord(sp + 0x6cUL));
        bool decodedStackAccess = TryDecodeTextureUploadSelectorSetupStackAccess(
            op,
            out string stackAccess,
            out int stackOffset,
            out int stackRegister,
            out bool stackWrite);
        bool stackAccessInSelectorRange =
            decodedStackAccess &&
            stackOffset is >= 0x60 and <= 0x78;
        ulong stackRegisterValue = stackRegister >= 0 ? _gpr[stackRegister] : 0UL;

        bool hasTarget = _traceTextureUploadRunSource.HasValue;
        ulong target = _traceTextureUploadRunSource ?? 0UL;
        bool selectorMatchesTarget = hasTarget && selectedSource == target;
        bool stackWriteMatchesTarget =
            hasTarget &&
            stackAccessInSelectorRange &&
            stackWrite &&
            stackRegisterValue == target;
        bool registerMatchesTarget =
            hasTarget &&
            (_gpr[2] == target ||
             _gpr[3] == target ||
             _gpr[4] == target ||
             _gpr[5] == target ||
             _gpr[6] == target ||
             _gpr[7] == target ||
             _gpr[8] == target ||
             _gpr[9] == target ||
             _gpr[10] == target ||
             _gpr[11] == target ||
             _gpr[16] == target ||
             _gpr[17] == target ||
             _gpr[18] == target ||
             _gpr[19] == target ||
             _gpr[20] == target ||
             _gpr[21] == target ||
             _gpr[22] == target ||
             _gpr[23] == target);

        if (hasTarget && !selectorMatchesTarget && !stackWriteMatchesTarget && !registerMatchesTarget)
            return;
        if (!hasTarget && !stackAccessInSelectorRange)
            return;

        string accessText = stackAccessInSelectorRange
            ? $"{stackAccess}@sp+0x{stackOffset:x2}:r{stackRegister}=0x{stackRegisterValue:x16}" +
              (stackWrite ? "" : $":mem=0x{ReadTraceWord(sp + (ulong)stackOffset):x8}")
            : "none";

        _textureUploadSourceSelectorSetupTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:TEXUPLOAD-SOURCE-SETUP] phase={phase} pc=0x{pc:x16} op=0x{op:x8} {DisassembleBrief(op)} " +
            $"match={(selectorMatchesTarget ? "selector," : "")}{(stackWriteMatchesTarget ? "stack-write," : "")}{(registerMatchesTarget ? "register," : "")} " +
            $"target=0x{target:x16} access={accessText} ra=0x{_gpr[31]:x16} sp=0x{sp:x16} " +
            $"selected=0x{selectedSource:x16} {DescribeKnownRuntimeBgLoadModelUploadSource(selectedSource)} " +
            $"v0=0x{_gpr[2]:x16} v1=0x{_gpr[3]:x16} a0=0x{_gpr[4]:x16} a1=0x{_gpr[5]:x16} " +
            $"a2=0x{_gpr[6]:x16} a3=0x{_gpr[7]:x16} t0=0x{_gpr[8]:x16} t1=0x{_gpr[9]:x16} " +
            $"t2=0x{_gpr[10]:x16} t3=0x{_gpr[11]:x16} s0=0x{_gpr[16]:x16} s1=0x{_gpr[17]:x16} " +
            $"s2=0x{_gpr[18]:x16} s3=0x{_gpr[19]:x16} s4=0x{_gpr[20]:x16} s5=0x{_gpr[21]:x16} " +
            $"s6=0x{_gpr[22]:x16} s7=0x{_gpr[23]:x16} " +
            $"selectedOwners={DescribeKnownRuntimeBgLoadModelUploadSourceOwners(selectedSource)} " +
            $"selectedTableOwners={DescribeRuntimeBgLoadModelSourceTableOwners(selectedSource)} " +
            $"sp60={ReadTraceWord(sp + 0x60UL):x8} sp64={ReadTraceWord(sp + 0x64UL):x8} " +
            $"sp68={ReadTraceWord(sp + 0x68UL):x8} sp6c={ReadTraceWord(sp + 0x6cUL):x8} " +
            $"sp70={ReadTraceWord(sp + 0x70UL):x8} sp74={ReadTraceWord(sp + 0x74UL):x8} sp78={ReadTraceWord(sp + 0x78UL):x8} " +
            $"targetFirst={ReadTraceWord(target):x8}/{ReadTraceWord(target + 0x04UL):x8}/" +
            $"{ReadTraceWord(target + 0x08UL):x8}/{ReadTraceWord(target + 0x0cUL):x8}");
    }

    private static bool TryDecodeTextureUploadSelectorSetupStackAccess(
        uint op,
        out string access,
        out int offset,
        out int register,
        out bool write)
    {
        access = "";
        offset = 0;
        register = -1;
        write = false;

        uint opcode = op >> 26;
        int baseRegister = (int)((op >> 21) & 0x1fU);
        if (baseRegister != 29)
            return false;

        string? decodedAccess = opcode switch
        {
            0x20 => "lb",
            0x21 => "lh",
            0x22 => "lwl",
            0x23 => "lw",
            0x24 => "lbu",
            0x25 => "lhu",
            0x26 => "lwr",
            0x27 => "lwu",
            0x28 => "sb",
            0x29 => "sh",
            0x2a => "swl",
            0x2b => "sw",
            0x2e => "swr",
            0x31 => "lwc1",
            0x35 => "ldc1",
            0x37 => "ld",
            0x39 => "swc1",
            0x3d => "sdc1",
            0x3f => "sd",
            _ => null
        };
        if (decodedAccess is null)
            return false;

        access = decodedAccess;
        offset = unchecked((short)(op & 0xffffU));
        register = (int)((op >> 16) & 0x1fU);
        write = opcode is 0x28 or 0x29 or 0x2a or 0x2b or 0x2e or 0x39 or 0x3d or 0x3f;
        return true;
    }

    private void TraceTextureUploadSourceSelector(ulong pc, uint op)
    {
        const ulong sourceSelectorPc = 0x000fe228UL;
        const uint sourceSelectorOp = 0x8fb3006cU; // lw s3,0x6c(sp)

        if (!_traceTextureUploadSourceSelector ||
            _textureUploadSourceSelectorTraceCount >= _traceTextureUploadSourceSelectorLimit)
            return;

        if ((pc & 0x1fffffffUL) != sourceSelectorPc || op != sourceSelectorOp)
            return;

        ulong sp = _gpr[29];
        ulong sourceSlot = sp + 0x6cUL;
        if (!IsMainRamRange(sourceSlot, 4))
            return;

        ulong selectedSource = SignExtend32(_memory.Read32(sourceSlot));
        if (_traceTextureUploadRunSource.HasValue &&
            selectedSource != _traceTextureUploadRunSource.Value)
            return;

        _textureUploadSourceSelectorTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:TEXUPLOAD-SOURCE-SELECT] pc=0x{pc:x16} op=0x{op:x8} " +
            $"ra=0x{_gpr[31]:x16} sp=0x{sp:x16} slot=0x{sourceSlot:x16} " +
            $"selected=0x{selectedSource:x16} {DescribeKnownRuntimeBgLoadModelUploadSource(selectedSource)} " +
            $"a0=0x{_gpr[4]:x16} a1=0x{_gpr[5]:x16} a2=0x{_gpr[6]:x16} a3=0x{_gpr[7]:x16} " +
            $"s0=0x{_gpr[16]:x16} s1=0x{_gpr[17]:x16} s2=0x{_gpr[18]:x16} s3=0x{_gpr[19]:x16} " +
            $"s4=0x{_gpr[20]:x16} s5=0x{_gpr[21]:x16} s6=0x{_gpr[22]:x16} s7=0x{_gpr[23]:x16} " +
            $"selectedOwners={DescribeKnownRuntimeBgLoadModelUploadSourceOwners(selectedSource)} " +
            $"selectedTableOwners={DescribeRuntimeBgLoadModelSourceTableOwners(selectedSource)} " +
            $"sp60={ReadTraceWord(sp + 0x60UL):x8} sp64={ReadTraceWord(sp + 0x64UL):x8} " +
            $"sp68={ReadTraceWord(sp + 0x68UL):x8} sp6c={ReadTraceWord(sp + 0x6cUL):x8} " +
            $"sp70={ReadTraceWord(sp + 0x70UL):x8} sp74={ReadTraceWord(sp + 0x74UL):x8} " +
            $"first={ReadTraceWord(selectedSource):x8}/{ReadTraceWord(selectedSource + 0x04UL):x8}/" +
            $"{ReadTraceWord(selectedSource + 0x08UL):x8}/{ReadTraceWord(selectedSource + 0x0cUL):x8}");
    }

    private void ApplyKnownRuntimeWorldTextureUploadSourceRepair(ulong pc, uint op)
    {
        const ulong sourceSelectorPc = 0xffffffff800fe228UL;
        const uint sourceSelectorOp = 0x8fb3006cU;
        uint descriptorSource = unchecked((uint)(
            ParseOptionalHexUlong("EUTHERDRIVE_GAUNTDL_EXPERIMENT_RUNTIME_WORLD_TEXTURE_UPLOAD_SOURCE_ADDRESS") ??
            0x802e1918UL));
        ulong texturesRomDiskBase =
            ParseOptionalHexUlong("EUTHERDRIVE_GAUNTDL_EXPERIMENT_RUNTIME_WORLD_TEXTURE_UPLOAD_DISK_BASE") ??
            0x00fff000UL;
        ulong textureFileOffset =
            ParseOptionalHexUlong("EUTHERDRIVE_GAUNTDL_EXPERIMENT_RUNTIME_WORLD_TEXTURE_UPLOAD_FILE_OFFSET") ??
            0x00018f20UL;
        const ulong scratch = 0xffffffff80400000UL;
        bool selectorByteOffsets =
            Environment.GetEnvironmentVariable("EUTHERDRIVE_GAUNTDL_EXPERIMENT_RUNTIME_WORLD_TEXTURE_UPLOAD_SELECTOR_BYTE_OFFSETS") == "1";
        const uint surfaceBytes = 0x10000U;
        const uint selLrBytesAfterRecordOffset = 0x1adee0U;
        uint bytes = selectorByteOffsets ? selLrBytesAfterRecordOffset : surfaceBytes;

        if (Environment.GetEnvironmentVariable("EUTHERDRIVE_GAUNTDL_EXPERIMENT_RUNTIME_WORLD_TEXTURE_UPLOAD_SOURCE") != "1" ||
            pc != sourceSelectorPc ||
            op != sourceSelectorOp)
        {
            return;
        }

        ulong sourceSlot = _gpr[29] + 0x6cUL;
        if (!IsMainRamRange(sourceSlot, 4UL) || _memory.Read32(sourceSlot) != descriptorSource)
            return;

        if (!_runtimeWorldTextureUploadSourceScratchHydrated &&
            !_memory.TryReadDiskByteOffsetToMemory(
                texturesRomDiskBase + textureFileOffset,
                scratch,
                bytes,
                out _runtimeWorldTextureUploadSourceScratchFirstWord,
                out string failure))
        {
            Console.WriteLine(
                $"[GAUNTDL:EXPERIMENT] runtime-world-texture-upload-source-failed pc={pc:x16} " +
                $"disk={texturesRomDiskBase + textureFileOffset:x8} bytes={bytes:x8} failure={failure}");
            return;
        }
        _runtimeWorldTextureUploadSourceScratchHydrated = true;

        uint hit = _runtimeWorldTextureUploadSourceRepairHitCount++;
        bool sequentialRows =
            Environment.GetEnvironmentVariable("EUTHERDRIVE_GAUNTDL_EXPERIMENT_RUNTIME_WORLD_TEXTURE_UPLOAD_SEQUENTIAL_ROWS") == "1";
        uint selectorIndex = (uint)((_gpr[5] >> 16) & 0xffUL);
        uint selectorByteOffset = (uint)_gpr[5];
        if (selectorByteOffsets && (ulong)selectorByteOffset + surfaceBytes > bytes)
        {
            if (hit < 8U || (hit & 0xffU) == 0xffU)
            {
                Console.WriteLine(
                    $"[GAUNTDL:EXPERIMENT] runtime-world-texture-upload-source-out-of-range pc={pc:x16} hit={hit} " +
                    $"selector={selectorByteOffset:x8} bytes={bytes:x8}");
            }
            return;
        }

        ulong selectedScratch = selectorByteOffsets
            ? scratch + selectorByteOffset
            : sequentialRows
                ? scratch + selectorIndex * 0x100UL
                : scratch;
        _memory.Write32(sourceSlot, unchecked((uint)selectedScratch));
        if (hit < 8U || (hit & 0xffU) == 0xffU)
        {
            Console.WriteLine(
                $"[GAUNTDL:EXPERIMENT] runtime-world-texture-upload-source pc={pc:x16} hit={hit} selectorIndex={selectorIndex} " +
                $"slot={sourceSlot:x16} source={descriptorSource:x8}->{unchecked((uint)selectedScratch):x8} " +
                $"fileOffset={textureFileOffset:x8} disk={texturesRomDiskBase + textureFileOffset:x8} " +
                $"bytes={bytes:x8} first={_runtimeWorldTextureUploadSourceScratchFirstWord:x8} " +
                $"sequentialRows={(sequentialRows ? 1 : 0)} selectorByteOffsets={(selectorByteOffsets ? 1 : 0)}");
        }
    }

    private void TraceType5ProducerRun(
        ulong pc,
        uint fifo,
        uint fifoBase,
        uint packetAddress,
        ulong source,
        uint sourceBase,
        uint payloadWords,
        uint index,
        uint limit)
    {
        if (!_traceType5ProducerHeads ||
            _type5ProducerHeadTraceCount >= _traceType5ProducerHeadLimit)
        {
            return;
        }

        if ((_traceType5ProducerHeadFifoMin.HasValue && fifo < _traceType5ProducerHeadFifoMin.Value) ||
            (_traceType5ProducerHeadFifoMax.HasValue && fifo > _traceType5ProducerHeadFifoMax.Value))
        {
            return;
        }

        if (_traceType5ProducerHeadSource.HasValue &&
            (uint)source != (uint)_traceType5ProducerHeadSource.Value)
        {
            return;
        }

        uint command = 0xc0000005U | (payloadWords << 3);
        uint targetBytes = unchecked(packetAddress - fifoBase) & 0x01ffffffu;
        uint packets = limit - index + 1U;
        _type5ProducerHeadTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:TYPE5-PRODUCER-RUN] n={_type5ProducerHeadTraceCount} pc=0x{pc:x16} " +
            $"fifo=0x{fifo:x8} fifoBase=0x{fifoBase:x8} cmd=0x{command:x8} count={payloadWords} packets={packets} " +
            $"targetBytes=0x{targetBytes:x8} targetWord=0x{targetBytes >> 2:x6} " +
            $"source=0x{source:x16} sourceBase=0x{sourceBase:x8} sourceWords={FormatTraceWords(source, (int)Math.Min(payloadWords, 8U))} " +
            $"ra=0x{_gpr[31]:x16} sp=0x{_gpr[29]:x16} " +
            $"s0=0x{_gpr[16]:x16} s1=0x{_gpr[17]:x16} s2=0x{_gpr[18]:x16} " +
            $"s3=0x{_gpr[19]:x16} s4=0x{_gpr[20]:x16} s5=0x{_gpr[21]:x16} " +
            $"s6=0x{_gpr[22]:x16} s7=0x{_gpr[23]:x16}");
    }

    private void TraceTextureUploadSourceProducer(ulong pc, uint op, string phase)
    {
        if (!_traceTextureUploadSourceProducer ||
            !_traceTextureUploadRunSource.HasValue ||
            _textureUploadSourceProducerTraceCount >= _traceTextureUploadSourceProducerLimit)
            return;

        if (_traceTextureUploadSourceProducerPcMin.HasValue &&
            pc < _traceTextureUploadSourceProducerPcMin.Value)
            return;
        if (_traceTextureUploadSourceProducerPcMax.HasValue &&
            pc > _traceTextureUploadSourceProducerPcMax.Value)
            return;

        ulong target = CanonicalizeTraceAddress(_traceTextureUploadRunSource.Value);
        ulong sp = _gpr[29];
        uint sp1c = ReadTraceWord(sp + 0x1cUL);
        uint sp4c = ReadTraceWord(sp + 0x4cUL);
        uint sp6c = ReadTraceWord(sp + 0x6cUL);
        bool matchT2 = _gpr[10] == target;
        bool matchS0 = _gpr[16] == target;
        bool matchSp1c = SignExtend32(sp1c) == target;
        bool matchSp4c = SignExtend32(sp4c) == target;
        bool matchSp6c = SignExtend32(sp6c) == target;

        if (!matchT2 && !matchS0 && !matchSp1c && !matchSp4c && !matchSp6c)
            return;

        _textureUploadSourceProducerTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:TEXUPLOAD-SOURCE-PRODUCER] phase={phase} pc=0x{pc:x16} op=0x{op:x8} {DisassembleBrief(op)} " +
            $"match={(matchT2 ? "t2," : "")}{(matchS0 ? "s0," : "")}{(matchSp1c ? "sp1c," : "")}{(matchSp4c ? "sp4c," : "")}{(matchSp6c ? "sp6c," : "")} " +
            $"target=0x{target:x16} ra=0x{_gpr[31]:x16} sp=0x{sp:x16} " +
            $"a0=0x{_gpr[4]:x16} a1=0x{_gpr[5]:x16} a2=0x{_gpr[6]:x16} a3=0x{_gpr[7]:x16} " +
            $"v0=0x{_gpr[2]:x16} v1=0x{_gpr[3]:x16} t0=0x{_gpr[8]:x16} t1=0x{_gpr[9]:x16} " +
            $"t2=0x{_gpr[10]:x16} t3=0x{_gpr[11]:x16} t4=0x{_gpr[12]:x16} " +
            $"s0=0x{_gpr[16]:x16} s1=0x{_gpr[17]:x16} s2=0x{_gpr[18]:x16} s3=0x{_gpr[19]:x16} " +
            $"s4=0x{_gpr[20]:x16} s5=0x{_gpr[21]:x16} s6=0x{_gpr[22]:x16} s7=0x{_gpr[23]:x16} " +
            $"sp1c={sp1c:x8} sp40={ReadTraceWord(sp + 0x40UL):x8} sp44={ReadTraceWord(sp + 0x44UL):x8} " +
            $"sp48={ReadTraceWord(sp + 0x48UL):x8} sp4c={sp4c:x8} sp50={ReadTraceWord(sp + 0x50UL):x8} sp6c={sp6c:x8} " +
            $"s3w={ReadTraceWord(_gpr[19] + 0x00UL):x8}/{ReadTraceWord(_gpr[19] + 0x08UL):x8}/{ReadTraceWord(_gpr[19] + 0x0cUL):x8} " +
            $"first={ReadTraceWord(target):x8}/{ReadTraceWord(target + 0x04UL):x8}/" +
            $"{ReadTraceWord(target + 0x08UL):x8}/{ReadTraceWord(target + 0x0cUL):x8}");
    }

    private void TraceRuntimeBgLoadModelTextureSourceOffsets(ulong pc)
    {
        const ulong sourceOffsetAddPc = 0xffffffff800a7338UL;
        if (!_traceRuntimeBgLoadModelTextureSourceOffsets ||
            pc != sourceOffsetAddPc)
        {
            return;
        }

        ulong sp = _gpr[29];
        if (!IsMainRamRange(sp + 0x70UL, 4UL))
            return;

        uint sourceWord = ReadTraceWord(sp + 0x6cUL);
        ulong source = SignExtend32(sourceWord);
        if (!AllowsTextureUploadRunSourceTrace(source))
            return;
        if (_runtimeBgLoadModelTextureSourceOffsetsTraceCount >= _traceRuntimeBgLoadModelTextureSourceOffsetsLimit)
            return;

        uint priorOffset = ReadTraceWord(sp + 0x20UL);
        uint subtractOffset = ReadTraceWord(sp + 0x70UL);
        uint computedSource = unchecked(sourceWord + priorOffset - subtractOffset);
        string key = $"{priorOffset:x8}:{subtractOffset:x8}:{_gpr[4]:x16}:{_gpr[5]:x16}:{_gpr[6]:x16}:{_gpr[7]:x16}:" +
                     $"{_gpr[16]:x16}:{_gpr[17]:x16}:{_gpr[18]:x16}:{_gpr[19]:x16}";
        if (!_runtimeBgLoadModelTextureSourceOffsetTraceKeys.Add(key))
            return;

        _runtimeBgLoadModelTextureSourceOffsetsTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:BGLOADMODEL-TEXTURE-SOURCE-OFFSET] pc={pc:x16} ra={_gpr[31]:x16} sp={sp:x16} " +
            $"source={sourceWord:x8} priorOffset={priorOffset:x8} subtract={subtractOffset:x8} computed={computedSource:x8} " +
            $"classIn={_gpr[4]:x8} record={_gpr[5]:x16} recordOffset={_gpr[6]:x8} limit={_gpr[7]:x8} " +
            $"s0={_gpr[16]:x16} s1={_gpr[17]:x16} s2={_gpr[18]:x16} s3={_gpr[19]:x16} " +
            $"s3w={ReadTraceWord(_gpr[19]):x8}/{ReadTraceWord(_gpr[19] + 0x08UL):x8}/{ReadTraceWord(_gpr[19] + 0x0cUL):x8}");
    }

    private void TraceTextureUploadSourceProducerLoad(ulong pc, uint op)
    {
        if (!_traceTextureUploadSourceProducerLoads ||
            !_traceTextureUploadRunSource.HasValue ||
            _textureUploadSourceProducerLoadTraceCount >= _traceTextureUploadSourceProducerLoadLimit)
        {
            return;
        }

        ulong pcMin = CanonicalizeOptionalTraceAddress(_traceTextureUploadSourceProducerLoadPcMin, 0UL);
        ulong pcMax = CanonicalizeOptionalTraceAddress(_traceTextureUploadSourceProducerLoadPcMax, ulong.MaxValue);
        if (pc < pcMin || pc > pcMax)
            return;

        if (!TryDecodeGprLoad(op, out string mnemonic, out int baseRegister, out int targetRegister, out int offset, out int bytes, out bool signExtend))
            return;

        ulong target = CanonicalizeTraceAddress(_traceTextureUploadRunSource.Value);
        ulong baseValue = _gpr[baseRegister];
        ulong address = unchecked(baseValue + (ulong)(long)offset);
        if (!IsMainRamRange(address, (ulong)bytes))
            return;

        ulong raw = bytes == 8
            ? _memory.Read64(address)
            : _memory.Read32(address);
        ulong loadedValue = bytes == 8
            ? raw
            : signExtend ? SignExtend32((uint)raw) : (uint)raw;

        if (loadedValue != target)
            return;

        ulong contextAddress = address >= 0x20UL ? address - 0x20UL : address;
        string contextWords = FormatTraceWords(contextAddress, 16);
        string targetWords = FormatTraceWords(target, 8);

        _textureUploadSourceProducerLoadTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:TEXUPLOAD-SOURCE-PRODUCER-LOAD] pc=0x{pc:x16} op=0x{op:x8} {DisassembleBrief(op)} " +
            $"load={mnemonic} r{targetRegister},[r{baseRegister}+0x{offset:x}] " +
            $"target=0x{target:x16} value=0x{loadedValue:x16} raw=0x{raw:x16} " +
            $"addr=0x{address:x16} base=0x{baseValue:x16} ra=0x{_gpr[31]:x16} sp=0x{_gpr[29]:x16} " +
            $"v0=0x{_gpr[2]:x16} v1=0x{_gpr[3]:x16} a0=0x{_gpr[4]:x16} a1=0x{_gpr[5]:x16} " +
            $"a2=0x{_gpr[6]:x16} a3=0x{_gpr[7]:x16} t0=0x{_gpr[8]:x16} t1=0x{_gpr[9]:x16} " +
            $"t2=0x{_gpr[10]:x16} t3=0x{_gpr[11]:x16} s0=0x{_gpr[16]:x16} s1=0x{_gpr[17]:x16} " +
            $"s2=0x{_gpr[18]:x16} s3=0x{_gpr[19]:x16} s4=0x{_gpr[20]:x16} s5=0x{_gpr[21]:x16} " +
            $"owners={DescribeKnownRuntimeBgLoadModelUploadSourceOwners(loadedValue)} " +
            $"context@0x{contextAddress:x16}={contextWords} targetFirst={targetWords}");
    }

    private void TraceMainRamReadWatch(ulong pc, uint op)
    {
        if (!_traceMainRamReadStart.HasValue ||
            _mainRamReadTraceCount >= _traceMainRamReadLimit ||
            !TryDecodeGprLoad(op, out string mnemonic, out int baseRegister, out int targetRegister, out int offset, out int bytes, out _))
        {
            return;
        }

        ulong start = CanonicalizeTraceAddress(_traceMainRamReadStart.Value);
        ulong end = CanonicalizeTraceAddress(_traceMainRamReadEnd ?? (start + 4UL));
        ulong address = CanonicalizeTraceAddress(unchecked(_gpr[baseRegister] + (ulong)(long)offset));
        if (end <= start || address >= end || address + (ulong)bytes <= start || !IsMainRamRange(address, (ulong)bytes))
            return;

        ulong value = bytes == 8 ? _memory.Read64(address) : _memory.Read32(address);
        _mainRamReadTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:MAIN-RAM-READ] n={_mainRamReadTraceCount} pc=0x{pc:x16} op=0x{op:x8} {DisassembleBrief(op)} " +
            $"load={mnemonic} r{targetRegister},[r{baseRegister}+0x{offset:x}] addr=0x{address:x16} bytes={bytes} value=0x{value:x16} " +
            $"ra=0x{_gpr[31]:x16} sp=0x{_gpr[29]:x16} a0=0x{_gpr[4]:x16} a1=0x{_gpr[5]:x16} " +
            $"a2=0x{_gpr[6]:x16} a3=0x{_gpr[7]:x16} s0=0x{_gpr[16]:x16} s1=0x{_gpr[17]:x16} " +
            $"s2=0x{_gpr[18]:x16} s3=0x{_gpr[19]:x16} s4=0x{_gpr[20]:x16} s5=0x{_gpr[21]:x16} s6=0x{_gpr[22]:x16}");
    }

    private void TraceMainRamWriteWatch(ulong pc, uint op, string kind, string detail, ulong address, int bytes, ulong oldValue, ulong newValue)
    {
        if (!_traceMainRamWrites ||
            !_traceMainRamWriteStart.HasValue ||
            _mainRamWriteTraceCount >= _traceMainRamWriteLimit ||
            bytes <= 0 ||
            !IsMainRamRange(address, (ulong)bytes))
        {
            return;
        }

        ulong start = CanonicalizeTraceAddress(_traceMainRamWriteStart.Value);
        ulong end = CanonicalizeTraceAddress(_traceMainRamWriteEnd ?? (start + 4UL));
        if (end <= start)
            end = start + 4UL;

        if (!TryGetMainRamPhysical(address, out uint writePhysical) ||
            !TryGetMainRamPhysical(start, out uint startPhysical) ||
            !TryGetMainRamPhysical(end - 1UL, out uint endLastPhysical))
        {
            return;
        }

        ulong endPhysicalExclusive = (ulong)endLastPhysical + 1UL;
        ulong writeEndPhysical = (ulong)writePhysical + (ulong)bytes;
        if (writeEndPhysical <= startPhysical || writePhysical >= endPhysicalExclusive)
            return;

        _mainRamWriteTraceCount++;
        ulong context = start >= 0x20UL ? start - 0x20UL : start;
        Console.WriteLine(
            $"[GAUNTDL:MAINRAM-WRITE-WATCH] n={_mainRamWriteTraceCount} kind={kind} detail={detail} " +
            $"pc=0x{pc:x16} op=0x{op:x8} {DisassembleBrief(op)} addr=0x{address:x16} bytes={bytes} " +
            $"old=0x{oldValue:x16} new=0x{newValue:x16} watch=0x{start:x16}-0x{end:x16} " +
            $"ra=0x{_gpr[31]:x16} sp=0x{_gpr[29]:x16} a0=0x{_gpr[4]:x16} a1=0x{_gpr[5]:x16} " +
            $"a2=0x{_gpr[6]:x16} a3=0x{_gpr[7]:x16} v0=0x{_gpr[2]:x16} v1=0x{_gpr[3]:x16} " +
            $"t0=0x{_gpr[8]:x16} t1=0x{_gpr[9]:x16} t2=0x{_gpr[10]:x16} t3=0x{_gpr[11]:x16} " +
            $"s0=0x{_gpr[16]:x16} s1=0x{_gpr[17]:x16} s2=0x{_gpr[18]:x16} s3=0x{_gpr[19]:x16} " +
            $"s4=0x{_gpr[20]:x16} s5=0x{_gpr[21]:x16} s6=0x{_gpr[22]:x16} s7=0x{_gpr[23]:x16} " +
            $"owners={DescribeKnownRuntimeBgLoadModelUploadSourceOwners(address)} " +
            $"context@0x{context:x16}={FormatTraceWords(context, 20)}");
    }

    private void TraceMainRamValueTransition(ulong pc)
    {
        if (!_traceMainRamValueTransitionAddress.HasValue ||
            _mainRamValueTransitionTraceCount >= _traceMainRamValueTransitionLimit)
        {
            return;
        }

        ulong address = CanonicalizeTraceAddress(_traceMainRamValueTransitionAddress.Value);
        if (!IsMainRamRange(address, 4))
            return;

        uint value = _memory.Read32(address);
        if (!_mainRamValueTransitionInitialized)
        {
            _mainRamValueTransitionInitialized = true;
            _mainRamValueTransitionLastValue = value;
            _mainRamValueTransitionPreviousPc = pc;
            Console.WriteLine(
                $"[GAUNTDL:MAINRAM-VALUE-TRANSITION] initial addr=0x{address:x16} " +
                $"value=0x{value:x8} pc=0x{pc:x16}");
            return;
        }

        if (value != _mainRamValueTransitionLastValue)
        {
            bool valueMatches =
                (!_traceMainRamValueTransitionMinValue.HasValue || value >= _traceMainRamValueTransitionMinValue.Value) &&
                (!_traceMainRamValueTransitionMaxValue.HasValue || value < _traceMainRamValueTransitionMaxValue.Value);
            if (valueMatches)
            {
                _mainRamValueTransitionTraceCount++;
                Console.WriteLine(
                    $"[GAUNTDL:MAINRAM-VALUE-TRANSITION] n={_mainRamValueTransitionTraceCount} " +
                    $"addr=0x{address:x16} old=0x{_mainRamValueTransitionLastValue:x8} new=0x{value:x8} " +
                    $"writerPc=0x{_mainRamValueTransitionPreviousPc:x16} nextPc=0x{pc:x16} " +
                    $"ra=0x{_gpr[31]:x16} sp=0x{_gpr[29]:x16} a0=0x{_gpr[4]:x16} a1=0x{_gpr[5]:x16} " +
                    $"a2=0x{_gpr[6]:x16} a3=0x{_gpr[7]:x16} s0=0x{_gpr[16]:x16} s1=0x{_gpr[17]:x16} " +
                    $"s2=0x{_gpr[18]:x16} s3=0x{_gpr[19]:x16}");
            }
            _mainRamValueTransitionLastValue = value;
        }

        _mainRamValueTransitionPreviousPc = pc;
    }

    private void TraceMainRamPointerReferences()
    {
        if (_mainRamPointerReferencesTraced || !_traceMainRamPointerReferences.HasValue)
            return;

        _mainRamPointerReferencesTraced = true;
        uint target = (uint)_traceMainRamPointerReferences.Value;
        int count = 0;
        for (uint physical = 0; physical < 32U * 1024U * 1024U; physical += 4U)
        {
            ulong address = 0xffffffff80000000UL + physical;
            if (_memory.Read32(address) != target)
                continue;

            ulong context = address >= 0x20UL ? address - 0x20UL : address;
            Console.WriteLine(
                $"[GAUNTDL:MAINRAM-POINTER-REFERENCE] n={++count} target=0x{target:x8} " +
                $"addr=0x{address:x16} offset=0x{physical:x8} context@0x{context:x16}={FormatTraceWords(context, 16)}");
            if (count >= _traceMainRamPointerReferenceLimit)
                break;
        }

        Console.WriteLine($"[GAUNTDL:MAINRAM-POINTER-REFERENCE-SUMMARY] target=0x{target:x8} count={count}");
    }

    private static bool TryDecodeGprLoad(
        uint op,
        out string mnemonic,
        out int baseRegister,
        out int targetRegister,
        out int offset,
        out int bytes,
        out bool signExtend)
    {
        mnemonic = "";
        baseRegister = -1;
        targetRegister = -1;
        offset = 0;
        bytes = 0;
        signExtend = true;

        uint opcode = op >> 26;
        (string Mnemonic, int Bytes, bool SignExtend)? load = opcode switch
        {
            0x23 => ("lw", 4, true),
            0x27 => ("lwu", 4, false),
            0x37 => ("ld", 8, false),
            _ => null
        };
        if (load is null)
            return false;

        mnemonic = load.Value.Mnemonic;
        bytes = load.Value.Bytes;
        signExtend = load.Value.SignExtend;
        baseRegister = (int)((op >> 21) & 0x1fU);
        targetRegister = (int)((op >> 16) & 0x1fU);
        offset = unchecked((short)(op & 0xffffU));
        return true;
    }

    private bool ShouldSkipRuntimeBgLoadModelHotDescriptorOverwrite(ulong pc, ulong address, uint oldValue, uint value)
    {
        if (!_experimentRuntimeBgLoadModelSkipHotDescriptorOverwrite)
            return false;

        ulong canonicalAddress = CanonicalizeTraceAddress(address);
        ulong canonicalS0 = CanonicalizeTraceAddress(_gpr[16]);
        bool headAddress =
            canonicalAddress == 0xffffffff80312998UL ||
            _experimentRuntimeBgLoadModelSkipHotDescriptorOverwriteExtraHeads.Contains(canonicalAddress);
        bool payloadAddress =
            canonicalS0 == 0xffffffff80312998UL ||
            _experimentRuntimeBgLoadModelSkipHotDescriptorOverwriteExtraHeads.Contains(canonicalS0);
        bool sceneNodeDescriptorHead =
            pc == 0xffffffff8004c850UL &&
            headAddress &&
            value >= 0x8012e000U &&
            value <= 0x80130000U;
        bool sceneNodeDescriptorPayload =
            pc == 0xffffffff8004c858UL &&
            payloadAddress &&
            canonicalAddress == canonicalS0 + 0x08UL &&
            value == unchecked((uint)(canonicalS0 + 0x0cUL));

        if (!sceneNodeDescriptorHead && !sceneNodeDescriptorPayload)
            return false;

        if (_runtimeBgLoadModelSkipHotDescriptorOverwriteTraceCount++ < 16)
        {
            Console.WriteLine(
                $"[GAUNTDL:EXPERIMENT] skip-hot-descriptor-overwrite pc=0x{pc:x16} " +
                $"addr=0x{canonicalAddress:x16} old=0x{oldValue:x8} value=0x{value:x8} " +
                $"kind={(sceneNodeDescriptorHead ? "head" : "payload")} " +
                $"s0=0x{_gpr[16]:x16} s1=0x{_gpr[17]:x16} s2=0x{_gpr[18]:x16} s3=0x{_gpr[19]:x16} " +
                $"ra=0x{_gpr[31]:x16} first={FormatTraceWords(canonicalS0, 8)}");
        }

        return true;
    }

    private bool ShouldSkipRuntimeBgLoadModelSourceTableStore(ulong pc, ulong address, uint oldValue, uint value)
    {
        const ulong writerPc = 0xffffffff800aac18UL;
        const ulong sourceTable = 0xffffffff802529a0UL;
        const ulong sourceTableEnd = sourceTable + 0x40UL * 4UL;

        if (_experimentRuntimeBgLoadModelSourceTableStoreSkipMask == 0 || pc != writerPc)
            return false;

        ulong canonicalAddress = CanonicalizeTraceAddress(address);
        if (canonicalAddress < sourceTable || canonicalAddress >= sourceTableEnd ||
            ((canonicalAddress - sourceTable) & 3UL) != 0)
        {
            return false;
        }

        ulong index = (canonicalAddress - sourceTable) / 4UL;
        if ((_experimentRuntimeBgLoadModelSourceTableStoreSkipMask & (1UL << (int)index)) == 0)
            return false;

        if (_runtimeBgLoadModelSourceTableStoreSkipTraceCount++ < 32)
        {
            const ulong assetTable = 0xffffffff8024f9a0UL;
            const ulong assetStride = 0x30UL;
            ulong assetEntry = assetTable + index * assetStride;
            Console.WriteLine(
                $"[GAUNTDL:EXPERIMENT] bgloadmodel-source-table-store-skip pc={pc:x16} " +
                $"index={index} slot={canonicalAddress:x16}:{oldValue:x8}-/->{value:x8} " +
                $"asset={ReadTraceWord(assetEntry):x8}/{ReadTraceWord(assetEntry + 0x04UL):x8}/" +
                $"{ReadTraceWord(assetEntry + 0x08UL):x8}/\"{ReadAsciiTraceString(assetEntry + 0x10UL, 24)}\" " +
                $"s0={_gpr[16]:x16} s1={_gpr[17]:x16} s2={_gpr[18]:x16} s3={_gpr[19]:x16}");
        }

        return true;
    }

    private void ApplyRuntimeFontStoryGebBacking(ulong pc, ulong address, uint value)
    {
        const ulong descriptor = 0xffffffff80312998UL;
        const ulong payload = descriptor + 0x0cUL;
        const ulong gebPayloadOffset = 0x128cUL;
        bool descriptorWrite =
            pc == 0xffffffff8004c858UL &&
            CanonicalizeTraceAddress(address) == descriptor + 0x08UL &&
            value == unchecked((uint)payload);
        bool uploadSelect =
            pc == 0xffffffff800fe228UL &&
            _memory.Read32(payload) == 0;
        if (!_experimentRuntimeFontStoryGebBacking ||
            (!descriptorWrite && !uploadSelect) ||
            !TryGetKnownRuntimeBgLoadModelTexturePayload(6, out _, out ulong gebDiskOffset, out uint gebBytes) ||
            gebBytes <= gebPayloadOffset)
        {
            return;
        }

        uint copyBytes = (uint)Math.Min(0x10000UL, gebBytes - gebPayloadOffset);
        if (!_memory.TryReadDiskByteOffsetToMemory(
                gebDiskOffset + gebPayloadOffset,
                payload,
                copyBytes,
                out uint firstWord,
                out string failure))
        {
            if (_runtimeFontStoryGebBackingTraceCount++ < 4)
                Console.WriteLine($"[GAUNTDL:EXPERIMENT] font-story-geb-backing-failed reason={failure}");
            return;
        }

        if (_runtimeFontStoryGebBackingTraceCount++ < 4)
        {
            Console.WriteLine(
                $"[GAUNTDL:EXPERIMENT] font-story-geb-backing descriptor={descriptor:x16} " +
                $"payload={payload:x16} disk={gebDiskOffset + gebPayloadOffset:x8} " +
                $"bytes={copyBytes:x8} first={firstWord:x8}");
        }
    }

    private void TraceTextureUploadSourceLimitTable(ulong pc, uint op, string phase)
    {
        const ulong defaultPcMin = 0xffffffff801095b0UL;
        const ulong defaultPcMax = 0xffffffff80109720UL;

        if (!_traceTextureUploadSourceLimitTable ||
            !_traceTextureUploadRunSource.HasValue ||
            _textureUploadSourceLimitTableTraceCount >= _traceTextureUploadSourceLimitTableLimit)
        {
            return;
        }

        ulong pcMin = CanonicalizeOptionalTraceAddress(_traceTextureUploadSourceLimitTablePcMin, defaultPcMin);
        ulong pcMax = CanonicalizeOptionalTraceAddress(_traceTextureUploadSourceLimitTablePcMax, defaultPcMax);
        if (pc < pcMin || pc > pcMax)
            return;

        ulong target = CanonicalizeTraceAddress(_traceTextureUploadRunSource.Value);
        ulong sp = _gpr[29];
        uint sp1c = ReadTraceWord(sp + 0x1cUL);
        uint sp24 = ReadTraceWord(sp + 0x24UL);
        uint sp40 = ReadTraceWord(sp + 0x40UL);
        uint sp44 = ReadTraceWord(sp + 0x44UL);
        uint sp48 = ReadTraceWord(sp + 0x48UL);
        uint sp4c = ReadTraceWord(sp + 0x4cUL);
        uint sp50 = ReadTraceWord(sp + 0x50UL);
        uint sp54 = ReadTraceWord(sp + 0x54UL);
        bool matchS0 = _gpr[16] == target;
        bool matchT2 = _gpr[10] == target;
        bool matchSp1c = SignExtend32(sp1c) == target;
        bool matchSp4c = SignExtend32(sp4c) == target;
        bool matchV0Table = IsMainRamRange(_gpr[2] + 0x04UL, 4) && ReadTraceWord(_gpr[2] + 0x04UL) is 0x20U or 0x100U;
        bool matchLimit = sp24 is 0x1fU or 0xffU;
        if (!matchS0 && !matchT2 && !matchSp1c && !matchSp4c)
            return;

        ulong callerSp = SignExtend32(unchecked((uint)(sp + 0x30UL)));
        string tableWords = IsMainRamRange(_gpr[2], 0x10UL) ? FormatTraceWords(_gpr[2], 4) : "";
        string targetWords = IsMainRamRange(target, 0x20UL) ? FormatTraceWords(target, 8) : "";

        _textureUploadSourceLimitTableTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:TEXUPLOAD-SOURCE-LIMIT] phase={phase} pc=0x{pc:x16} op=0x{op:x8} {DisassembleBrief(op)} " +
            $"match={(matchS0 ? "s0," : "")}{(matchT2 ? "t2," : "")}{(matchSp1c ? "sp1c," : "")}" +
            $"{(matchSp4c ? "sp4c," : "")}{(matchV0Table ? "table," : "")}{(matchLimit ? "limit," : "")} " +
            $"target=0x{target:x16} ra=0x{_gpr[31]:x16} sp=0x{sp:x16} callerSp=0x{callerSp:x16} " +
            $"v0=0x{_gpr[2]:x16} v1=0x{_gpr[3]:x16} a2=0x{_gpr[6]:x16} " +
            $"t0=0x{_gpr[8]:x16} t1=0x{_gpr[9]:x16} t2=0x{_gpr[10]:x16} " +
            $"s0=0x{_gpr[16]:x16} s1=0x{_gpr[17]:x16} s2=0x{_gpr[18]:x16} s3=0x{_gpr[19]:x16} " +
            $"sp1c={sp1c:x8} sp24={sp24:x8} sp40={sp40:x8} sp44={sp44:x8} sp48={sp48:x8} " +
            $"sp4c={sp4c:x8} sp50={sp50:x8} sp54={sp54:x8} " +
            $"caller1c={ReadTraceWord(callerSp + 0x1cUL):x8} caller24={ReadTraceWord(callerSp + 0x24UL):x8} " +
            $"table={tableWords} targetFirst={targetWords}");
    }

    private void TraceTextureUploadPageSelection(ulong pc, uint op)
    {
        if (!_traceTextureUploadPageSelection ||
            _textureUploadPageSelectionTraceCount >= _traceTextureUploadPageSelectionLimit ||
            pc is not (0xffffffff801095c0UL or 0xffffffff80109620UL))
        {
            return;
        }

        ulong source = _gpr[16];
        ulong sourceMin = CanonicalizeOptionalTraceAddress(_traceTextureUploadPageSelectionSourceMin, 0UL);
        ulong sourceMax = CanonicalizeOptionalTraceAddress(_traceTextureUploadPageSelectionSourceMax, ulong.MaxValue);
        if (source < sourceMin || source >= sourceMax)
            return;

        ulong descriptor = _gpr[19];
        ulong strideTable0 = _gpr[20];
        ulong strideTable1 = _gpr[21];
        ulong tableIndex = _gpr[23] & 0xffffffffUL;
        ulong tableOffset = tableIndex * 4UL;
        uint stride0 = ReadTraceWord(strideTable0 + tableOffset);
        uint stride1 = ReadTraceWord(strideTable1 + tableOffset);

        _textureUploadPageSelectionTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:TEXUPLOAD-PAGE-SELECT] n={_textureUploadPageSelectionTraceCount} " +
            $"pc=0x{pc:x16} op=0x{op:x8} {DisassembleBrief(op)} ra=0x{_gpr[31]:x16} " +
            $"source=0x{source:x16} descriptor=0x{descriptor:x16} " +
            $"v0=0x{_gpr[2]:x16} a0=0x{_gpr[4]:x16} a1=0x{_gpr[5]:x16} a2=0x{_gpr[6]:x16} " +
            $"t2=0x{_gpr[10]:x16} s1=0x{_gpr[17]:x16} s2=0x{_gpr[18]:x16} " +
            $"page={tableIndex:x} stride0=0x{stride0:x8} stride1=0x{stride1:x8} " +
            $"desc08=0x{ReadTraceWord(descriptor + 0x08UL):x8} desc0c=0x{ReadTraceWord(descriptor + 0x0cUL):x8} " +
            $"sourceFirst={FormatTraceWords(source, 4)}");
    }

    private void TraceTextureSourceCallA3Producer(ulong pc, uint op)
    {
        if (!_traceTextureSourceCallA3Producer ||
            _textureSourceCallA3ProducerTraceCount >= _traceTextureSourceCallA3ProducerLimit ||
            pc < _traceTextureSourceCallA3ProducerPcMin ||
            pc > _traceTextureSourceCallA3ProducerPcMax)
        {
            return;
        }

        bool matched = false;
        for (int register = 2; register < _gpr.Length; register++)
        {
            if (_gpr[register] == _traceTextureSourceCallA3ProducerTarget)
            {
                matched = true;
                break;
            }
        }
        if (_traceTextureSourceCallA3ProducerRequireMatch && !matched)
            return;

        _textureSourceCallA3ProducerTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:TEXTURE-SOURCE-A3-PRODUCER] n={_textureSourceCallA3ProducerTraceCount} " +
            $"pc=0x{pc:x16} op=0x{op:x8} {DisassembleBrief(op)} target=0x{_traceTextureSourceCallA3ProducerTarget:x16} " +
            $"ra=0x{_gpr[31]:x16} sp=0x{_gpr[29]:x16} " +
            $"v0=0x{_gpr[2]:x16} v1=0x{_gpr[3]:x16} " +
            $"a0=0x{_gpr[4]:x16} a1=0x{_gpr[5]:x16} a2=0x{_gpr[6]:x16} a3=0x{_gpr[7]:x16} " +
            $"t0=0x{_gpr[8]:x16} t1=0x{_gpr[9]:x16} t2=0x{_gpr[10]:x16} t3=0x{_gpr[11]:x16} " +
            $"s0=0x{_gpr[16]:x16} s1=0x{_gpr[17]:x16} s2=0x{_gpr[18]:x16} s3=0x{_gpr[19]:x16} " +
            $"targetFirst={FormatTraceWords(_traceTextureSourceCallA3ProducerTarget, 8)}");
    }

    private readonly struct TextureUploadCallerTransitionSnapshot
    {
        public TextureUploadCallerTransitionSnapshot(
            bool active,
            ulong sp,
            ulong s0,
            ulong s6,
            uint state08,
            uint state374,
            uint state37c,
            uint sp1c,
            uint sp74,
            uint s6Word00,
            uint s6Word04,
            uint s6Word08,
            uint s6Word0c)
        {
            Active = active;
            Sp = sp;
            S0 = s0;
            S6 = s6;
            State08 = state08;
            State374 = state374;
            State37c = state37c;
            Sp1c = sp1c;
            Sp74 = sp74;
            S6Word00 = s6Word00;
            S6Word04 = s6Word04;
            S6Word08 = s6Word08;
            S6Word0c = s6Word0c;
        }

        public bool Active { get; }
        public ulong Sp { get; }
        public ulong S0 { get; }
        public ulong S6 { get; }
        public uint State08 { get; }
        public uint State374 { get; }
        public uint State37c { get; }
        public uint Sp1c { get; }
        public uint Sp74 { get; }
        public uint S6Word00 { get; }
        public uint S6Word04 { get; }
        public uint S6Word08 { get; }
        public uint S6Word0c { get; }
    }

    private TextureUploadCallerTransitionSnapshot CaptureTextureUploadCallerTransitionSnapshot(ulong pc)
    {
        const ulong callerTraceStart = 0x000fe2f0UL;
        const ulong callerTraceEnd = 0x000fe5d4UL;

        if (!_traceTextureUploadPayload || !_traceTextureUploadCallerTransitions)
            return default;

        ulong physicalPc = pc & 0x1fffffffUL;
        if (physicalPc < callerTraceStart || physicalPc > callerTraceEnd)
            return default;

        ulong sp = _gpr[29];
        ulong s0 = _gpr[16];
        ulong s6 = _gpr[22];
        return new TextureUploadCallerTransitionSnapshot(
            true,
            sp,
            s0,
            s6,
            ReadTraceWord(s0 + 0x08UL),
            ReadTraceWord(s0 + 0x374UL),
            ReadTraceWord(s0 + 0x37cUL),
            ReadTraceWord(sp + 0x1cUL),
            ReadTraceWord(sp + 0x74UL),
            ReadTraceWord(s6 + 0x00UL),
            ReadTraceWord(s6 + 0x04UL),
            ReadTraceWord(s6 + 0x08UL),
            ReadTraceWord(s6 + 0x0cUL));
    }

    private bool MatchesTextureUploadRunSourceTrace(TextureUploadCallerTransitionSnapshot snapshot)
    {
        if (!_traceTextureUploadRunSource.HasValue)
            return true;

        ulong target = _traceTextureUploadRunSource.Value;
        return snapshot.S6 == target || SignExtend32(snapshot.S6Word08) == target;
    }

    private static bool HasTextureUploadCallerTransition(
        TextureUploadCallerTransitionSnapshot before,
        TextureUploadCallerTransitionSnapshot after)
        => before.Sp != after.Sp ||
           before.S0 != after.S0 ||
           before.S6 != after.S6 ||
           before.State08 != after.State08 ||
           before.State374 != after.State374 ||
           before.State37c != after.State37c ||
           before.Sp1c != after.Sp1c ||
           before.Sp74 != after.Sp74 ||
           before.S6Word00 != after.S6Word00 ||
           before.S6Word04 != after.S6Word04 ||
           before.S6Word08 != after.S6Word08 ||
           before.S6Word0c != after.S6Word0c;

    private void TraceTextureUploadCallerTransition(
        ulong pc,
        uint op,
        TextureUploadCallerTransitionSnapshot before)
    {
        if (!before.Active || _textureUploadPayloadCallerTransitionTraceCount >= 160)
            return;

        TextureUploadCallerTransitionSnapshot after = CaptureTextureUploadCallerTransitionSnapshot(pc);
        if (!after.Active ||
            !HasTextureUploadCallerTransition(before, after) ||
            (!MatchesTextureUploadRunSourceTrace(before) && !MatchesTextureUploadRunSourceTrace(after)))
        {
            return;
        }

        _textureUploadPayloadCallerTransitionTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:TEXUPLOAD-CALLER-CHANGE] pc=0x{pc:x16} op=0x{op:x8} " +
            $"sp=0x{before.Sp:x16}->0x{after.Sp:x16} s0=0x{before.S0:x16}->0x{after.S0:x16} " +
            $"s6=0x{before.S6:x16}->0x{after.S6:x16} " +
            $"state08={before.State08:x8}->{after.State08:x8} " +
            $"state374={before.State374:x8}->{after.State374:x8} " +
            $"state37c={before.State37c:x8}->{after.State37c:x8} " +
            $"sp1c={before.Sp1c:x8}->{after.Sp1c:x8} sp74={before.Sp74:x8}->{after.Sp74:x8} " +
            $"s6w={before.S6Word00:x8}/{before.S6Word04:x8}/{before.S6Word08:x8}/{before.S6Word0c:x8}->" +
            $"{after.S6Word00:x8}/{after.S6Word04:x8}/{after.S6Word08:x8}/{after.S6Word0c:x8}");
    }

    private void TraceTextureUploadDirectWriterStore(
        ulong pc,
        uint op,
        int rs,
        int rt,
        short simm,
        ulong address,
        uint value)
    {
        if (!_traceTextureUploadDirectWriter ||
            _textureUploadDirectWriterTraceCount >= _traceTextureUploadDirectWriterLimit)
        {
            return;
        }

        ulong physicalPc = pc & 0x1fffffffUL;
        if (physicalPc < _traceTextureUploadDirectWriterPcMin ||
            physicalPc > _traceTextureUploadDirectWriterPcMax)
        {
            return;
        }

        ulong sp = _gpr[29];
        ulong s3 = _gpr[19];
        ulong s6 = _gpr[22];
        ulong traceSource = physicalPc < 0x000fe590UL ? s6 : s3;
        ulong? sourceFilter = _traceTextureUploadDirectWriterSource ?? _traceTextureUploadRunSource;
        if (sourceFilter.HasValue)
        {
            ulong sourceStart = CanonicalizeTraceAddress(sourceFilter.Value);
            ulong sourceEnd = sourceStart + 0x100UL;
            ulong stackSource = CanonicalizeTraceAddress(ReadTraceWord(sp + 0x6cUL));
            ulong[] sourceCandidates = [s3, s6, _gpr[10], stackSource];
            int sourceIndex = Array.FindIndex(
                sourceCandidates,
                candidate => candidate >= sourceStart && candidate < sourceEnd);
            if (sourceIndex < 0)
                return;

            traceSource = sourceCandidates[sourceIndex];
        }

        bool hasTargetFilter = _traceTextureUploadPacketTargetWords.Length > 0;
        uint targetWord = (value & 3U) == 0 ? value / 4U : uint.MaxValue;
        bool targetMatch = !hasTargetFilter ||
            Array.IndexOf(_traceTextureUploadPacketTargetWords, (ulong)targetWord) >= 0;
        bool followMatch = hasTargetFilter && _textureUploadDirectWriterFollowRemaining > 0;
        if (!targetMatch && !followMatch)
            return;

        string reason;
        uint traceTargetWord = targetWord;
        if (targetMatch)
        {
            reason = hasTargetFilter ? "target" : "all";
            if (hasTargetFilter)
            {
                _textureUploadDirectWriterFollowRemaining = Math.Max(0, _traceTextureUploadDirectWriterFollowWords);
                _textureUploadDirectWriterFollowTargetWord = targetWord;
            }
        }
        else
        {
            reason = $"follow:0x{_textureUploadDirectWriterFollowTargetWord:x8}";
            traceTargetWord = _textureUploadDirectWriterFollowTargetWord;
            _textureUploadDirectWriterFollowRemaining--;
        }

        _textureUploadDirectWriterTraceCount++;
        ulong a2 = _gpr[6];
        ulong s0 = _gpr[16];
        Console.WriteLine(
            $"[GAUNTDL:TEXUPLOAD-DIRECT-WRITER] n={_textureUploadDirectWriterTraceCount} reason={reason} " +
            $"pc=0x{pc:x16} op=0x{op:x8} sw=r{rt}->[r{rs}+0x{(ushort)simm:x4}] " +
            $"addr=0x{address:x16} value=0x{value:x8} targetWord=0x{targetWord:x8} " +
            $"ra=0x{_gpr[31]:x16} sp=0x{sp:x16} " +
            $"a0=0x{_gpr[4]:x16} a1=0x{_gpr[5]:x16} a2=0x{a2:x16} a3=0x{_gpr[7]:x16} " +
            $"v0=0x{_gpr[2]:x16} v1=0x{_gpr[3]:x16} " +
            $"t0=0x{_gpr[8]:x16} t1=0x{_gpr[9]:x16} t8=0x{_gpr[24]:x16} t9=0x{_gpr[25]:x16} " +
            $"s0=0x{s0:x16} s1=0x{_gpr[17]:x16} s2=0x{_gpr[18]:x16} s3=0x{s3:x16} " +
            $"s4=0x{_gpr[20]:x16} s5=0x{_gpr[21]:x16} s6=0x{s6:x16} s7=0x{_gpr[23]:x16} " +
            $"traceSrc=0x{traceSource:x16} " +
            $"a2src={DescribeKnownRuntimeBgLoadModelUploadSource(a2)} " +
            $"s0src={DescribeKnownRuntimeBgLoadModelUploadSource(s0)} " +
            $"s3src={DescribeKnownRuntimeBgLoadModelUploadSource(s3)} " +
            $"s6src={DescribeKnownRuntimeBgLoadModelUploadSource(s6)} " +
            $"state08={ReadTraceWord(s0 + 0x08UL):x8} state374={ReadTraceWord(s0 + 0x374UL):x8} " +
            $"state37c={ReadTraceWord(s0 + 0x37cUL):x8} " +
            $"sp1c={ReadTraceWord(sp + 0x1cUL):x8} sp70={ReadTraceWord(sp + 0x70UL):x8} " +
            $"sp74={ReadTraceWord(sp + 0x74UL):x8} " +
            $"a2w={FormatTraceWords(a2, 4)} s0w={FormatTraceWords(s0, 4)} " +
            $"s3w={FormatTraceWords(s3, 4)} " +
            $"s3ctrl={FormatDirectTextureWriterControlGroups(s3)} " +
            $"s3disk={FormatKnownRuntimeBgLoadModelUploadDiskCompare(s3, 4)} " +
            $"s6w={ReadTraceWord(s6 + 0x00UL):x8}/{ReadTraceWord(s6 + 0x04UL):x8}/" +
            $"{ReadTraceWord(s6 + 0x08UL):x8}/{ReadTraceWord(s6 + 0x0cUL):x8}");

        ulong payloadWords = _gpr[20];
        uint payloadWordCount = payloadWords <= uint.MaxValue ? (uint)payloadWords : 0;
        ulong sourceBytes = payloadWords is > 0UL and <= 0x100000UL ? payloadWords * 4UL : 0UL;
        TraceRuntimeBgLoadModelWtrEntryContext(traceSource, traceTargetWord, sourceBytes, payloadWordCount, 0, 0);
    }

    private string FormatDirectTextureWriterControlGroups(ulong source)
    {
        if (!IsMainRamRange(source, 0x20UL))
            return "";

        StringBuilder builder = new();
        for (int group = 0; group < 2; group++)
        {
            ulong groupAddress = source + (ulong)group * 0x10UL;
            if (group > 0)
                builder.Append(';');

            builder.Append('+');
            builder.Append((group * 0x10).ToString("x", CultureInfo.InvariantCulture));
            builder.Append('=');
            for (int word = 0; word < 4; word++)
            {
                if (word > 0)
                    builder.Append('/');

                uint value = ReadTraceWord(groupAddress + (ulong)word * 4UL);
                builder.Append(FormatDirectTextureWriterControlWord(value));
            }
        }

        return builder.ToString();
    }

    private static string FormatDirectTextureWriterControlWord(uint value)
    {
        string hex = value.ToString("x8", CultureInfo.InvariantCulture);
        if (value == 0 || (value & 3U) != 0)
            return hex;

        return $"{hex}(w{value / 4U:x})";
    }

    private void TraceTextureUploadDirectWriterControlTableWrite(
        ulong pc,
        uint op,
        string mnemonic,
        string sourceRegister,
        int rs,
        short simm,
        ulong address,
        uint oldValue,
        uint value)
    {
        if (!ShouldTraceTextureUploadDirectWriterControlTableWrite(address, value))
            return;

        _textureUploadDirectWriterControlTableWriteTraceCount++;
        ulong targetWord = (value & 3U) == 0 ? value / 4U : ulong.MaxValue;
        ulong groupBase = address & ~0x0fUL;
        ulong tableBase = CanonicalizeTraceAddress(_traceTextureUploadDirectWriterControlTableWriteBase);
        ulong sp = _gpr[29];
        ulong s3 = _gpr[19];
        Console.WriteLine(
            $"[GAUNTDL:TEXUPLOAD-DIRECT-WRITER-CTRL-WRITE] n={_textureUploadDirectWriterControlTableWriteTraceCount} " +
            $"pc=0x{pc:x16} op=0x{op:x8} {mnemonic}={sourceRegister}->[r{rs}+0x{(ushort)simm:x4}] " +
            $"addr=0x{address:x16} old=0x{oldValue:x8} value=0x{value:x8} targetWord=0x{targetWord:x8} " +
            $"ra=0x{_gpr[31]:x16} sp=0x{sp:x16} " +
            $"a0=0x{_gpr[4]:x16} a1=0x{_gpr[5]:x16} a2=0x{_gpr[6]:x16} a3=0x{_gpr[7]:x16} " +
            $"v0=0x{_gpr[2]:x16} v1=0x{_gpr[3]:x16} " +
            $"t0=0x{_gpr[8]:x16} t1=0x{_gpr[9]:x16} t8=0x{_gpr[24]:x16} t9=0x{_gpr[25]:x16} " +
            $"s0=0x{_gpr[16]:x16} s1=0x{_gpr[17]:x16} s2=0x{_gpr[18]:x16} s3=0x{s3:x16} " +
            $"s4=0x{_gpr[20]:x16} s5=0x{_gpr[21]:x16} s6=0x{_gpr[22]:x16} s7=0x{_gpr[23]:x16} " +
            $"table=0x{tableBase:x16}:{_traceTextureUploadDirectWriterControlTableWriteBytes:x} " +
            $"group=0x{groupBase:x16}:{FormatDirectTextureWriterControlGroups(groupBase)} " +
            $"table0={FormatDirectTextureWriterControlGroups(tableBase)} " +
            $"s3ctrl={FormatDirectTextureWriterControlGroups(s3)} " +
            $"fprs={FormatCpuFprSummary()}");
    }

    private bool ShouldTraceTextureUploadDirectWriterControlTableWrite(ulong address, uint value)
    {
        if (!_traceTextureUploadDirectWriterControlTableWrites ||
            _textureUploadDirectWriterControlTableWriteTraceCount >= _traceTextureUploadDirectWriterControlTableWriteLimit ||
            !IsMainRamRange(address, 4UL) ||
            !TryGetMainRamPhysical(address, out uint physical) ||
            !TryGetMainRamPhysical(_traceTextureUploadDirectWriterControlTableWriteBase, out uint basePhysical))
        {
            return false;
        }

        ulong start = basePhysical;
        ulong end = start + (ulong)_traceTextureUploadDirectWriterControlTableWriteBytes;
        if (physical < start || physical >= end)
            return false;

        return _traceTextureUploadDirectWriterControlTableWriteValues.Length == 0 ||
            Array.IndexOf(_traceTextureUploadDirectWriterControlTableWriteValues, (ulong)value) >= 0;
    }

    private uint ApplyDirectTextureWriterDiskWordExperiment(
        ulong pc,
        int rt,
        uint value)
    {
        if (!_experimentDirectTextureWriterDiskWords)
            return value;

        ulong physicalPc = pc & 0x1fffffffUL;
        bool hasTargetFilter = _experimentDirectTextureWriterDiskWordTargetWords.Length > 0;
        if (hasTargetFilter && physicalPc == 0x000fe7b0UL && rt == 2 && (value & 3U) == 0)
        {
            uint targetWord = value / 4U;
            if (Array.IndexOf(_experimentDirectTextureWriterDiskWordTargetWords, (ulong)targetWord) >= 0)
            {
                ulong payloadWords = _gpr[20];
                _textureUploadDirectWriterDiskWordTargetFollowRemaining =
                    payloadWords is > 0UL and <= 0x400UL ? (int)payloadWords : 64;
                _textureUploadDirectWriterDiskWordTargetActive = targetWord;
            }

            return value;
        }

        ulong source;
        if (physicalPc == 0x000fe7c4UL && rt == 2)
        {
            source = _gpr[19];
        }
        else if (physicalPc == 0x000fe7ccUL && rt == 3)
        {
            source = _gpr[19] + 4UL;
        }
        else
        {
            return value;
        }

        if (hasTargetFilter)
        {
            if (_textureUploadDirectWriterDiskWordTargetFollowRemaining <= 0)
                return value;

            _textureUploadDirectWriterDiskWordTargetFollowRemaining--;
        }

        if (!TryReadDirectTextureWriterDiskWord(source, out uint diskWord, out string diskSource))
            return value;

        uint transformedDiskWord = TransformZeroBaseUploadDiskWord(diskWord);
        if (_textureUploadDirectWriterDiskWordTraceCount++ < _experimentDirectTextureWriterDiskWordsTraceLimit &&
            value != transformedDiskWord)
        {
            string transform = DescribeZeroBaseUploadDiskWordTransform(diskWord, transformedDiskWord);
            Console.WriteLine(
                $"[GAUNTDL:EXPERIMENT] direct-texture-writer-disk-word " +
                $"pc=0x{pc:x16} rt=r{rt} target=0x{_textureUploadDirectWriterDiskWordTargetActive:x8} " +
                $"source=0x{source:x16} {diskSource} " +
                $"mem=0x{value:x8}->disk=0x{diskWord:x8}{transform}");
        }

        return transformedDiskWord;
    }

    private uint ApplyDirectTextureWriterDiskPayloadRemapExperiment(
        ulong pc,
        int rt,
        uint value)
    {
        if (!_experimentDirectTextureWriterDiskPayloadRemapSource.HasValue ||
            !_experimentDirectTextureWriterDiskPayloadRemapIndex.HasValue)
        {
            return value;
        }

        ulong physicalPc = pc & 0x1fffffffUL;
        bool hasTargetFilter = _experimentDirectTextureWriterDiskPayloadRemapTargetWords.Length > 0;
        if (hasTargetFilter && physicalPc == 0x000fe7b0UL && rt == 2 && (value & 3U) == 0)
        {
            uint targetWord = value / 4U;
            if (Array.IndexOf(_experimentDirectTextureWriterDiskPayloadRemapTargetWords, (ulong)targetWord) >= 0)
            {
                ulong payloadWords = _gpr[20];
                _textureUploadDirectWriterDiskPayloadRemapFollowRemaining =
                    payloadWords is > 0UL and <= 0x400UL ? (int)payloadWords : 64;
                _textureUploadDirectWriterDiskPayloadRemapTargetActive = targetWord;
                if (_textureUploadDirectWriterDiskPayloadRemapTraceCount++ < _experimentDirectTextureWriterDiskPayloadRemapTraceLimit)
                {
                    Console.WriteLine(
                        $"[GAUNTDL:EXPERIMENT] direct-texture-writer-disk-payload-remap-arm " +
                        $"pc=0x{pc:x16} target=0x{targetWord:x8} follow={_textureUploadDirectWriterDiskPayloadRemapFollowRemaining} " +
                        $"source=0x{_gpr[19]:x16} index=0x{_experimentDirectTextureWriterDiskPayloadRemapIndex.Value:x} " +
                        $"offset=0x{_experimentDirectTextureWriterDiskPayloadRemapOffset:x}");
                }
            }

            return value;
        }

        ulong source;
        if (physicalPc == 0x000fe7c4UL && rt == 2)
        {
            source = _gpr[19];
        }
        else if (physicalPc == 0x000fe7ccUL && rt == 3)
        {
            source = _gpr[19] + 4UL;
        }
        else
        {
            return value;
        }

        if (hasTargetFilter)
        {
            if (_textureUploadDirectWriterDiskPayloadRemapFollowRemaining <= 0)
                return value;

            _textureUploadDirectWriterDiskPayloadRemapFollowRemaining--;
        }
        else
        {
            _textureUploadDirectWriterDiskPayloadRemapTargetActive = 0;
        }

        ulong sourceKey = source & 0xffffffffUL;
        ulong remapSourceKey = _experimentDirectTextureWriterDiskPayloadRemapSource.Value & 0xffffffffUL;
        if (sourceKey < remapSourceKey)
            return value;

        ulong sourceOffset = sourceKey - remapSourceKey;
        if (!TryGetKnownRuntimeBgLoadModelTexturePayload(
                _experimentDirectTextureWriterDiskPayloadRemapIndex.Value,
                out string code,
                out ulong byteOffset,
                out uint byteLength))
        {
            return value;
        }

        if (!TryReadDirectTextureWriterDiskPayloadRemapWord(
                byteOffset,
                byteLength,
                sourceOffset,
                out uint diskWord,
                out uint transformedDiskWord,
                out string transform))
        {
            return value;
        }

        if (_textureUploadDirectWriterDiskPayloadRemapTraceCount++ < _experimentDirectTextureWriterDiskPayloadRemapTraceLimit)
        {
            string change = value == transformedDiskWord ? "same" : "changed";
            ulong diskOffset = _experimentDirectTextureWriterDiskPayloadRemapOffset + sourceOffset;
            Console.WriteLine(
                $"[GAUNTDL:EXPERIMENT] direct-texture-writer-disk-payload-remap " +
                $"pc=0x{pc:x16} rt=r{rt} target=0x{_textureUploadDirectWriterDiskPayloadRemapTargetActive:x8} " +
                $"source=0x{source:x16} remapSource=0x{remapSourceKey:x8}+0x{sourceOffset:x} " +
                $"disk={_experimentDirectTextureWriterDiskPayloadRemapIndex.Value}:{code}@0x{diskOffset:x} " +
                $"{change} mem=0x{value:x8}->disk=0x{diskWord:x8}{transform}");
        }

        return transformedDiskWord;
    }

    private bool TryReadDirectTextureWriterDiskPayloadRemapWord(
        ulong payloadByteOffset,
        uint payloadByteLength,
        ulong sourceOffset,
        out uint diskWord,
        out uint transformedWord,
        out string transform)
    {
        diskWord = 0;
        transformedWord = 0;
        transform = "";

        if (IsDirectTextureWriterDiskPayloadRemap4BppTransform(out bool highFirst, out bool scaleNibble))
        {
            ulong packedRelativeOffset = _experimentDirectTextureWriterDiskPayloadRemapOffset + (sourceOffset >> 1);
            if (packedRelativeOffset + 4UL > payloadByteLength ||
                !_memory.TryReadDiskByteOffsetWord(payloadByteOffset + packedRelativeOffset, out diskWord))
            {
                return false;
            }

            uint word = 0;
            for (int lane = 0; lane < 4; lane++)
            {
                ulong outputByteOffset = sourceOffset + (ulong)lane;
                ulong packedByteOffset = _experimentDirectTextureWriterDiskPayloadRemapOffset + (outputByteOffset >> 1);
                if (packedByteOffset >= payloadByteLength ||
                    !_memory.TryReadDiskByteOffsetWord(payloadByteOffset + packedByteOffset, out uint packedWord))
                {
                    return false;
                }

                byte packedByte = (byte)packedWord;
                bool highNibble = ((outputByteOffset & 1UL) != 0) == highFirst;
                byte nibble = highNibble ? (byte)(packedByte >> 4) : (byte)(packedByte & 0x0f);
                byte outputByte = scaleNibble ? (byte)(nibble * 0x11) : nibble;
                word |= (uint)outputByte << (lane * 8);
            }

            transformedWord = word;
            transform = $" transform={_experimentDirectTextureWriterDiskPayloadRemapTransform}:0x{transformedWord:x8}/packed=0x{packedRelativeOffset:x}";
            return true;
        }

        ulong diskOffset = _experimentDirectTextureWriterDiskPayloadRemapOffset + sourceOffset;
        if (diskOffset + 4UL > payloadByteLength ||
            !_memory.TryReadDiskByteOffsetWord(payloadByteOffset + diskOffset, out diskWord))
        {
            return false;
        }

        transformedWord = TransformDirectTextureWriterDiskPayloadRemapWord(diskWord);
        transform = DescribeDirectTextureWriterDiskPayloadRemapTransform(diskWord, transformedWord);
        return true;
    }

    private bool IsDirectTextureWriterDiskPayloadRemap4BppTransform(out bool highFirst, out bool scaleNibble)
    {
        highFirst = false;
        scaleNibble = false;
        switch (_experimentDirectTextureWriterDiskPayloadRemapTransform)
        {
            case "4bpp":
            case "4bpp-low":
            case "4bpp-low-first":
            case "nibble-low":
            case "nibble-low-first":
                return true;
            case "4bpp-high":
            case "4bpp-high-first":
            case "nibble-high":
            case "nibble-high-first":
                highFirst = true;
                return true;
            case "4bpp-scale":
            case "4bpp-low-scale":
            case "4bpp-low-first-scale":
            case "nibble-low-scale":
            case "nibble-low-first-scale":
                scaleNibble = true;
                return true;
            case "4bpp-high-scale":
            case "4bpp-high-first-scale":
            case "nibble-high-scale":
            case "nibble-high-first-scale":
                highFirst = true;
                scaleNibble = true;
                return true;
            default:
                return false;
        }
    }

    private uint TransformDirectTextureWriterDiskPayloadRemapWord(uint word)
    {
        return _experimentDirectTextureWriterDiskPayloadRemapTransform switch
        {
            "be32" or "reverse32" or "byteswap32" => BinaryPrimitives.ReverseEndianness(word),
            "swap16" or "halfswap" => (word << 16) | (word >> 16),
            "reverse16" or "byteswap16" or "swapbytes16" => ((word & 0x00ff00ffU) << 8) | ((word & 0xff00ff00U) >> 8),
            _ => word,
        };
    }

    private string DescribeDirectTextureWriterDiskPayloadRemapTransform(uint originalWord, uint transformedWord)
    {
        if (transformedWord == originalWord ||
            string.IsNullOrEmpty(_experimentDirectTextureWriterDiskPayloadRemapTransform) ||
            _experimentDirectTextureWriterDiskPayloadRemapTransform == "none" ||
            _experimentDirectTextureWriterDiskPayloadRemapTransform == "le" ||
            _experimentDirectTextureWriterDiskPayloadRemapTransform == "little")
        {
            return "";
        }

        return $" transform={_experimentDirectTextureWriterDiskPayloadRemapTransform}:0x{transformedWord:x8}";
    }

