    private bool TryReadDirectTextureWriterDiskWord(
        ulong address,
        out uint word,
        out string sourceDescription)
    {
        word = 0;
        sourceDescription = "";

        if (_textureUploadDirectWriterDiskWordCacheValid &&
            address >= _textureUploadDirectWriterDiskWordCacheStart &&
            address < _textureUploadDirectWriterDiskWordCacheEnd)
        {
            ulong candidateOffset = address - _textureUploadDirectWriterDiskWordCacheStart;
            if (_memory.TryReadDiskByteOffsetWord(_textureUploadDirectWriterDiskWordCacheDiskByteOffset + candidateOffset, out word))
            {
                sourceDescription =
                    $"{_textureUploadDirectWriterDiskWordCacheIndex}:{_textureUploadDirectWriterDiskWordCacheCode}@0x{candidateOffset:x}";
                return true;
            }
        }

        const ulong destinationBase = 0xffffffff802e1718UL;
        ulong sourceStride = (ulong)_runtimeBgLoadModelIndexedSourceStride;
        for (ulong index = 1; index <= KnownRuntimeBgLoadModelTexturePayloadMaxIndex; index++)
        {
            if (!TryGetKnownRuntimeBgLoadModelTexturePayload(index, out string code, out ulong byteOffset, out uint textureByteLength))
                continue;

            ulong candidateBase = destinationBase + index * sourceStride;
            ulong candidateEnd = candidateBase + GetKnownRuntimeBgLoadModelSourceSpanByteLength(textureByteLength);
            if (address < candidateBase || address >= candidateEnd)
                continue;

            ulong candidateOffset = address - candidateBase;
            if (!_memory.TryReadDiskByteOffsetWord(byteOffset + candidateOffset, out word))
                return false;

            _textureUploadDirectWriterDiskWordCacheValid = true;
            _textureUploadDirectWriterDiskWordCacheStart = candidateBase;
            _textureUploadDirectWriterDiskWordCacheEnd = candidateEnd;
            _textureUploadDirectWriterDiskWordCacheDiskByteOffset = byteOffset;
            _textureUploadDirectWriterDiskWordCacheIndex = index;
            _textureUploadDirectWriterDiskWordCacheCode = code;
            sourceDescription = $"{index}:{code}@0x{candidateOffset:x}";
            return true;
        }

        return false;
    }

    private void TraceZeroBaseTextureUploadPointerWord(
        ulong source,
        uint sourceBase,
        uint packet,
        uint index,
        uint limit,
        uint word,
        uint payloadWord)
    {
        if (!_traceTextureUploadPayload ||
            sourceBase != 0 ||
            _textureUploadPayloadPointerTraceCount >= 96 ||
            !IsKnownRuntimeBgLoadModelUploadSourceCandidate(source) ||
            (payloadWord & 3U) != 0 ||
            payloadWord == 0x80000000U ||
            (payloadWord & 0xe0000000U) is not (0x80000000U or 0xa0000000U))
        {
            return;
        }

        ulong pointer = SignExtend32(payloadWord);
        if (!IsMainRamRange(pointer, 0x10UL))
            return;

        _textureUploadPayloadPointerTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:TEXUPLOAD-PTR] source=0x{source:x16} {DescribeKnownRuntimeBgLoadModelUploadSource(source)} " +
            $"packet={packet} index={index}/{limit} word={word} ptr=0x{pointer:x16} " +
            $"ptrWords={ReadTraceWord(pointer):x8}/{ReadTraceWord(pointer + 0x04UL):x8}/" +
            $"{ReadTraceWord(pointer + 0x08UL):x8}/{ReadTraceWord(pointer + 0x0cUL):x8}");
    }

    private void TraceTextureUploadFifoPacket(
        uint packet,
        uint packetSourceAddress,
        ulong source,
        uint sourceBase,
        uint payloadWords,
        uint index,
        uint limit,
        ulong uploadRunSource,
        uint uploadRunStartIndex,
        uint fifo,
        uint fifoBase,
        uint fifoRingBase)
    {
        if (!_traceTextureUploadFifoPacket.HasValue ||
            !AllowsTextureUploadRunSourceTrace(source))
        {
            return;
        }

        uint target = (uint)_traceTextureUploadFifoPacket.Value;
        uint fifoLow = fifo & 0x0003ffffu;
        uint fifoDelta = unchecked(fifo - fifoBase) & 0x0003ffffu;
        uint fifoRingDelta = unchecked(fifo - fifoRingBase) & 0x0003ffffu;
        if (fifoLow != target &&
            fifoDelta != target &&
            fifoRingDelta != target)
        {
            return;
        }

        if (_textureUploadFifoPacketTraceCount++ >= _traceTextureUploadFifoPacketLimit)
            return;

        uint first0 = IsMainRamRange(source + 0x00UL, 4) ? _memory.Read32(source + 0x00UL) : 0;
        uint first1 = IsMainRamRange(source + 0x04UL, 4) ? _memory.Read32(source + 0x04UL) : 0;
        uint first2 = IsMainRamRange(source + 0x08UL, 4) ? _memory.Read32(source + 0x08UL) : 0;
        uint first3 = IsMainRamRange(source + 0x0cUL, 4) ? _memory.Read32(source + 0x0cUL) : 0;
        uint runFirst0 = IsMainRamRange(uploadRunSource + 0x00UL, 4) ? _memory.Read32(uploadRunSource + 0x00UL) : 0;
        uint runFirst1 = IsMainRamRange(uploadRunSource + 0x04UL, 4) ? _memory.Read32(uploadRunSource + 0x04UL) : 0;
        uint runFirst2 = IsMainRamRange(uploadRunSource + 0x08UL, 4) ? _memory.Read32(uploadRunSource + 0x08UL) : 0;
        uint runFirst3 = IsMainRamRange(uploadRunSource + 0x0cUL, 4) ? _memory.Read32(uploadRunSource + 0x0cUL) : 0;
        string text = ReadAsciiTraceString(source, Math.Min((int)payloadWords * 4, 32));
        string diskCompare = FormatKnownRuntimeBgLoadModelUploadDiskCompare(source, 4);
        ulong runDelta = source >= uploadRunSource ? source - uploadRunSource : 0;
        ulong runTraceEnd = source + payloadWords * 4UL;
        string runSpan = FormatKnownRuntimeBgLoadModelUploadSpan(uploadRunSource, runTraceEnd, 12);
        Console.WriteLine(
            $"[GAUNTDL:TEXUPLOAD-FIFO-TARGET] packet={packet} index={index}/{limit} " +
            $"fifo=0x{fifo:x8} fifoLow=0x{fifoLow:x6} fifoBase=0x{fifoBase:x8} fifoDelta=0x{fifoDelta:x6} " +
            $"fifoRingBase=0x{fifoRingBase:x8} fifoRingDelta=0x{fifoRingDelta:x6} " +
            $"packetSource=0x{packetSourceAddress:x8} sourceBase=0x{sourceBase:x8} source=0x{source:x16} " +
            $"runSource=0x{uploadRunSource:x16} runDelta=0x{runDelta:x} runStart={uploadRunStartIndex} " +
            $"runFirst=0x{runFirst0:x8}/0x{runFirst1:x8}/0x{runFirst2:x8}/0x{runFirst3:x8} " +
            $"runSpan={runSpan} words={payloadWords} " +
            $"{DescribeKnownRuntimeBgLoadModelUploadSource(source)} " +
            $"first=0x{first0:x8}/0x{first1:x8}/0x{first2:x8}/0x{first3:x8} disk={diskCompare} text=\"{text}\"");
    }

    private string FormatKnownRuntimeBgLoadModelUploadSpan(ulong start, ulong end, int maxSegments)
    {
        if (end <= start || maxSegments <= 0)
            return "empty";

        ulong cursor = start;
        StringBuilder builder = new();
        int segmentCount = 0;

        while (cursor < end && segmentCount < maxSegments)
        {
            ulong nextBoundary = end;
            string label = DescribeKnownRuntimeBgLoadModelUploadSpanSegment(cursor, out nextBoundary);
            if (nextBoundary <= cursor || nextBoundary > end)
                nextBoundary = end;

            if (segmentCount > 0)
                builder.Append(',');

            builder.Append(label);
            builder.Append("+0x");
            builder.Append((cursor - start).ToString("x"));
            builder.Append("..+0x");
            builder.Append((nextBoundary - start).ToString("x"));

            cursor = nextBoundary;
            segmentCount++;
        }

        if (cursor < end)
            builder.Append(",...");

        return builder.ToString();
    }

    private string FormatKnownRuntimeBgLoadModelUploadDiskCompare(ulong source, int words)
    {
        StringBuilder builder = new();
        for (int i = 0; i < words; i++)
        {
            if (i > 0)
                builder.Append('/');

            builder.Append(DescribeKnownRuntimeBgLoadModelUploadSpanSegment(source + (ulong)i * 4UL, out _));
        }

        return builder.ToString();
    }

    private void TraceTextureUploadPayload(
        uint packet,
        uint packetSourceAddress,
        ulong source,
        uint sourceBase,
        uint payloadWords,
        uint index,
        uint limit)
    {
        bool focusedPacketSource =
            _traceTextureUploadPacketSource.HasValue &&
            packetSourceAddress == (uint)_traceTextureUploadPacketSource.Value;
        if ((!_traceTextureUploadPayload && !focusedPacketSource) ||
            !AllowsTextureUploadRunSourceTrace(source))
        {
            return;
        }

        uint first0 = IsMainRamRange(source + 0x00UL, 4) ? _memory.Read32(source + 0x00UL) : 0;
        uint first1 = IsMainRamRange(source + 0x04UL, 4) ? _memory.Read32(source + 0x04UL) : 0;
        uint first2 = IsMainRamRange(source + 0x08UL, 4) ? _memory.Read32(source + 0x08UL) : 0;
        uint first3 = IsMainRamRange(source + 0x0cUL, 4) ? _memory.Read32(source + 0x0cUL) : 0;
        string text = ReadAsciiTraceString(source, Math.Min((int)payloadWords * 4, 32));
        bool likelyMetadataPayload = IsLikelyTextureMetadataPayload(first0, text);
        if (focusedPacketSource)
        {
            if (_textureUploadPayloadPacketSourceTraceCount++ >= _traceTextureUploadPacketSourceLimit)
                return;
        }
        else if (_textureUploadPayloadTraceCount >= _traceTextureUploadPayloadLimit)
        {
            if (!likelyMetadataPayload || _textureUploadPayloadAsciiTraceCount++ >= 64)
                return;
        }
        else
        {
            _textureUploadPayloadTraceCount++;
        }

        Console.WriteLine(
            $"[GAUNTDL:{(focusedPacketSource ? "TEXUPLOAD-PAYLOAD-TARGET" : "TEXUPLOAD-PAYLOAD")}] packet={packet} index={index}/{limit} " +
            $"packetSource=0x{packetSourceAddress:x8} sourceBase=0x{sourceBase:x8} source=0x{source:x16} words={payloadWords} " +
            $"{DescribeKnownRuntimeBgLoadModelUploadSource(source)} " +
            $"first=0x{first0:x8}/0x{first1:x8}/0x{first2:x8}/0x{first3:x8} text=\"{text}\"");
    }

    private void TraceTextureUploadLink(
        uint packet,
        uint packetSourceAddress,
        ulong source,
        uint sourceBase,
        uint payloadWords,
        uint index,
        uint limit,
        uint fifo,
        uint fifoBase,
        uint fifoRingBase,
        uint fifoRingBytes)
    {
        uint packetSourceOffset = unchecked(packetSourceAddress - fifoBase) & 0x01ffffffU;
        uint targetWord = packetSourceOffset / 4U;
        bool focusedSource = _traceTextureUploadPayload && AllowsTextureUploadRunSourceTrace(source);
        bool focusedPacketSource = _traceTextureUploadPacketSource.HasValue &&
                                   packetSourceAddress == (uint)_traceTextureUploadPacketSource.Value;
        bool focusedPacketTarget = _traceTextureUploadPacketTargetWords.Contains(targetWord);
        if (!focusedSource && !focusedPacketSource && !focusedPacketTarget)
            return;

        if (focusedPacketTarget)
        {
            if (_textureUploadPayloadPacketTargetTraceCount++ >= _traceTextureUploadPacketTargetLimit)
                return;
        }
        else if (_textureUploadPayloadLinkTraceCount++ >= 96)
        {
            return;
        }

        uint fifoLow = fifo & 0x0003ffffU;
        uint fifoDelta = unchecked(fifo - fifoBase) & 0x0003ffffU;
        uint fifoRingDelta = unchecked(fifo - fifoRingBase) & 0x0003ffffU;
        uint first0 = IsMainRamRange(source + 0x00UL, 4) ? _memory.Read32(source + 0x00UL) : 0;
        uint first1 = IsMainRamRange(source + 0x04UL, 4) ? _memory.Read32(source + 0x04UL) : 0;
        uint first2 = IsMainRamRange(source + 0x08UL, 4) ? _memory.Read32(source + 0x08UL) : 0;
        uint first3 = IsMainRamRange(source + 0x0cUL, 4) ? _memory.Read32(source + 0x0cUL) : 0;
        uint swapped0 = BinaryPrimitives.ReverseEndianness(first0);
        uint swapped1 = BinaryPrimitives.ReverseEndianness(first1);
        uint swapped2 = BinaryPrimitives.ReverseEndianness(first2);
        uint swapped3 = BinaryPrimitives.ReverseEndianness(first3);
        uint memHash = 2166136261u;
        uint diskHash = 2166136261u;
        uint diskDecodedHash = 2166136261u;
        int memNonZero = 0;
        int diskNonZero = 0;
        int diskWords = 0;
        int availableWords = IsMainRamRange(source, payloadWords * 4UL) ? (int)payloadWords : 0;
        for (int i = 0; i < availableWords; i++)
        {
            ulong wordAddress = source + (ulong)i * 4UL;
            uint memWord = _memory.Read32(wordAddress);
            memHash ^= memWord;
            memHash *= 16777619u;
            if (memWord != 0)
                memNonZero++;

            if (TryReadKnownRuntimeBgLoadModelUploadDiskWord(wordAddress, out uint diskWord, out _))
            {
                uint transformedDiskWord = TransformZeroBaseUploadDiskWord(diskWord);
                diskHash ^= transformedDiskWord;
                diskHash *= 16777619u;
                uint decodedDiskWord = BinaryPrimitives.ReverseEndianness(transformedDiskWord);
                diskDecodedHash ^= decodedDiskWord;
                diskDecodedHash *= 16777619u;
                if (transformedDiskWord != 0)
                    diskNonZero++;
                diskWords++;
            }
        }

        string diskCompare = FormatKnownRuntimeBgLoadModelUploadDiskCompare(source, 4);
        string diskHashStatus = diskWords > 0
            ? $" diskHash=0x{diskHash:X8}/dec0x{diskDecodedHash:X8}/nz{diskNonZero}/words{diskWords}"
            : " diskHash=-";

        Console.WriteLine(
            $"[GAUNTDL:TEXUPLOAD-LINK] packet={packet} index={index}/{limit} " +
            $"packetSource=0x{packetSourceAddress:x8} packetOffset=0x{packetSourceOffset:x8} targetWord=0x{targetWord:x8} " +
            $"sourceBase=0x{sourceBase:x8} source=0x{source:x16} words={payloadWords} " +
            $"{DescribeKnownRuntimeBgLoadModelUploadSource(source)} " +
            $"fifo=0x{fifo:x8} fifoLow=0x{fifoLow:x6} fifoBase=0x{fifoBase:x8} fifoDelta=0x{fifoDelta:x6} " +
            $"fifoRingBase=0x{fifoRingBase:x8} fifoRingBytes=0x{fifoRingBytes:x8} fifoRingDelta=0x{fifoRingDelta:x6} " +
            $"raw=0x{first0:x8}/0x{first1:x8}/0x{first2:x8}/0x{first3:x8} " +
            $"swap=0x{swapped0:x8}/0x{swapped1:x8}/0x{swapped2:x8}/0x{swapped3:x8} " +
            $"memHash=0x{memHash:X8}/nz{memNonZero}/words{availableWords}{diskHashStatus} " +
            $"disk={diskCompare}");
    }

    private bool IsLikelyTextureMetadataPayload(ulong source, uint payloadWords)
    {
        if (!_traceTextureUploadPayload && !_experimentSkipMetadataTexturePayloads)
            return false;

        uint first = IsMainRamRange(source, 4) ? _memory.Read32(source) : 0;
        string text = ReadAsciiTraceString(source, Math.Min((int)payloadWords * 4, 32));
        return IsLikelyTextureMetadataPayload(first, text);
    }

    private static bool IsLikelyTextureMetadataPayload(uint firstWord, string text)
        => text.Contains("DWF_", StringComparison.Ordinal) ||
           text.Contains("WEAP_", StringComparison.Ordinal) ||
           text.Contains("HOLD", StringComparison.Ordinal) ||
           text.Contains("UPPER", StringComparison.Ordinal) ||
           text.Contains("TORSO", StringComparison.Ordinal) ||
           firstWord is 0x4457465fU or 0x57454150U;

    private void TraceTextureUploadZeroBaseRunClassifier(
        ulong originalSource,
        ulong source,
        uint sourceBase,
        uint currentPacketAddress,
        uint payloadWords,
        uint index,
        uint limit,
        ulong sourceBytes)
    {
        if (!_traceTextureUploadZeroBaseRunClassifier ||
            sourceBase != 0 ||
            _textureUploadZeroBaseRunClassifierTraceCount >= _traceTextureUploadZeroBaseRunClassifierLimit ||
            payloadWords == 0 ||
            index > limit ||
            sourceBytes < 4UL ||
            !IsMainRamRange(source, Math.Min(sourceBytes, 4UL)) ||
            !AllowsTextureUploadRunSourceTrace(source))
        {
            return;
        }

        uint packets = limit - index + 1U;
        string traceKey = $"{source:x16}:{currentPacketAddress:x8}:{packets:x}:{payloadWords:x}";
        if (!_textureUploadZeroBaseRunClassifierKeys.Add(traceKey))
            return;

        _textureUploadZeroBaseRunClassifierTraceCount++;

        int sampleWords = (int)Math.Min(512UL, sourceBytes / 4UL);
        int zeroWords = 0;
        int allOnesWords = 0;
        int pointerWords = 0;
        int floatWords = 0;
        int printableBytes = 0;
        HashSet<uint> uniqueWords = new();
        for (int i = 0; i < sampleWords; i++)
        {
            uint word = _memory.Read32(source + (ulong)i * 4UL);
            uniqueWords.Add(word);
            if (word == 0)
                zeroWords++;
            if (word == 0xffffffffU)
                allOnesWords++;
            if (IsLikelyTracePointerWord(word))
                pointerWords++;
            if (IsLikelyTraceFloatWord(word))
                floatWords++;
            printableBytes += CountPrintableAsciiBytes(word);
        }

        string text = ReadAsciiTraceString(source, Math.Min((int)Math.Min(sourceBytes, 64UL), 64));
        int meaningfulText = CountMeaningfulAscii(text);
        bool knownSource = IsKnownRuntimeBgLoadModelUploadSourceCandidate(source);
        bool knownPayloadSource = knownSource && IsKnownRuntimeBgLoadModelUploadSourceInsidePayload(source);
        bool descriptorLike = IsLikelyZeroBaseUploadDescriptor(originalSource);
        string classification = ClassifyZeroBaseTextureUploadRun(
            knownSource,
            knownPayloadSource,
            descriptorLike,
            meaningfulText,
            sampleWords,
            zeroWords,
            pointerWords,
            floatWords);
        string nextKnown = TryFindNextKnownRuntimeBgLoadModelUploadSource(
                source,
                source + sourceBytes,
                0x40000UL,
                out ulong nextKnownSource,
                out ulong nextKnownIndex,
                out string nextKnownCode)
            ? $"0x{nextKnownSource:x16}:{nextKnownIndex}:{nextKnownCode}/+0x{nextKnownSource - source:x}"
            : "none";

        Console.WriteLine(
            $"[GAUNTDL:TEXUPLOAD-ZEROBASE-CLASS] class={classification} " +
            $"source=0x{source:x16} original=0x{originalSource:x16} {DescribeKnownRuntimeBgLoadModelUploadSource(source)} " +
            $"owners={DescribeKnownRuntimeBgLoadModelUploadSourceOwners(source)} " +
            $"packet=0x{currentPacketAddress:x8} index={index}/{limit} packets={packets} words={payloadWords} bytes=0x{sourceBytes:x} " +
            $"sampleWords={sampleWords} unique={uniqueWords.Count} zero={zeroWords} ones={allOnesWords} " +
            $"ptr={pointerWords} float={floatWords} asciiBytes={printableBytes} text=\"{text.Replace('"', '\'')}\" " +
            $"nextKnown={nextKnown} descriptor={FormatTraceWords(originalSource, 8)} first={FormatTraceWords(source, 8)}");

        TraceRuntimeBgLoadModelWtrEntryContext(source, currentPacketAddress, sourceBytes, payloadWords, index, limit);
    }

    private void TraceRuntimeBgLoadModelWtrEntryContext(
        ulong source,
        uint currentPacketAddress,
        ulong sourceBytes,
        uint payloadWords,
        uint index,
        uint limit)
    {
        if (!_traceRuntimeBgLoadModelWtrEntries ||
            _runtimeBgLoadModelWtrEntriesTraceCount >= _traceRuntimeBgLoadModelWtrEntriesLimit ||
            !TryGetKnownRuntimeBgLoadModelUploadSourceDetails(
                source,
                out ulong qioIndex,
                out string code,
                out ulong header,
                out long sourceOffset,
                out uint bodyOffset,
                out uint countWord,
                out uint strideWord,
                out uint textureByteLength) ||
            qioIndex != 9 ||
            !code.Equals("wtr", StringComparison.OrdinalIgnoreCase))
        {
            return;
        }

        if (!TryReadRuntimeBgLoadModelWtrEntries(
                header,
                bodyOffset,
                countWord,
                out ulong body,
                out List<(int Slot, string Name, uint Target, uint Flags)> entries))
        {
            return;
        }

        long bodyDelta = sourceOffset - bodyOffset;
        int sourceSlot = FindNearestRuntimeBgLoadModelWtrEntry(entries, bodyDelta);
        int packetSlot = FindNearestRuntimeBgLoadModelWtrEntry(entries, currentPacketAddress);
        var sourceEntry = entries[sourceSlot];
        var packetEntry = entries[packetSlot];

        _runtimeBgLoadModelWtrEntriesTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:WTR-ENTRY] n={_runtimeBgLoadModelWtrEntriesTraceCount} " +
            $"source=0x{source:x16} header=0x{header:x16} body=0x{body:x16} " +
            $"sourceOffset=0x{sourceOffset:x} bodyDelta={FormatSignedHex(bodyDelta)} " +
            $"span=0x{sourceBytes:x} packet=0x{currentPacketAddress:x8} index={index}/{limit} words={payloadWords} " +
            $"count={countWord} stride=0x{strideWord:x8} len=0x{textureByteLength:x} " +
            $"sourceNearest={FormatRuntimeBgLoadModelWtrEntry(sourceEntry, bodyDelta)} " +
            $"packetNearest={FormatRuntimeBgLoadModelWtrEntry(packetEntry, currentPacketAddress)} " +
            $"entries={FormatRuntimeBgLoadModelWtrEntryList(entries, 8)}");
    }

    private bool TryGetZeroBaseUploadWtrEntryPacketAddress(
        ulong source,
        uint fallbackPacketAddress,
        out uint packetAddress,
        out string description)
    {
        packetAddress = 0;
        description = "";
        if (string.IsNullOrEmpty(_experimentZeroBaseUploadWtrEntryPacketAddressMode) ||
            _experimentZeroBaseUploadWtrEntryPacketAddressMode is "0" or "false" or "off" or "none")
        {
            return false;
        }

        if (!TryGetKnownRuntimeBgLoadModelUploadSourceDetails(
                source,
                out ulong qioIndex,
                out string code,
                out ulong header,
                out long sourceOffset,
                out uint bodyOffset,
                out uint countWord,
                out _,
                out _) ||
            qioIndex != 9 ||
            !code.Equals("wtr", StringComparison.OrdinalIgnoreCase) ||
            !TryReadRuntimeBgLoadModelWtrEntries(
                header,
                bodyOffset,
                countWord,
                out _,
                out List<(int Slot, string Name, uint Target, uint Flags)> entries))
        {
            return false;
        }

        long bodyDelta = sourceOffset - bodyOffset;
        int sourceSlot = FindNearestRuntimeBgLoadModelWtrEntry(entries, bodyDelta);
        var sourceEntry = entries[sourceSlot];
        long candidate = _experimentZeroBaseUploadWtrEntryPacketAddressMode switch
        {
            "target" or "entry" or "entry-target" => sourceEntry.Target,
            "target-delta" or "target-plus-delta" or "target-body-delta" or "target-plus-body-delta" =>
                (long)sourceEntry.Target + bodyDelta,
            _ => -1,
        };

        if (candidate < 0 ||
            _experimentZeroBaseUploadWtrEntryPacketAddressAdd > long.MaxValue ||
            candidate > long.MaxValue - (long)_experimentZeroBaseUploadWtrEntryPacketAddressAdd)
        {
            return false;
        }

        candidate += (long)_experimentZeroBaseUploadWtrEntryPacketAddressAdd;
        if (_experimentZeroBaseUploadWtrEntryPacketAddressSub > long.MaxValue ||
            candidate < (long)_experimentZeroBaseUploadWtrEntryPacketAddressSub)
        {
            return false;
        }

        candidate -= (long)_experimentZeroBaseUploadWtrEntryPacketAddressSub;
        if (candidate < 0 ||
            candidate > 0x01fffffcL ||
            (candidate & 3L) != 0)
        {
            return false;
        }

        packetAddress = (uint)candidate;
        description =
            $"mode={_experimentZeroBaseUploadWtrEntryPacketAddressMode} " +
            $"add=0x{_experimentZeroBaseUploadWtrEntryPacketAddressAdd:x} sub=0x{_experimentZeroBaseUploadWtrEntryPacketAddressSub:x} " +
            $"sourceOffset=0x{sourceOffset:x} bodyOffset=0x{bodyOffset:x} bodyDelta={FormatSignedHex(bodyDelta)} " +
            $"entry={FormatRuntimeBgLoadModelWtrEntry(sourceEntry, bodyDelta)} fallback=0x{fallbackPacketAddress:x8}";
        return true;
    }

    private bool TryReadRuntimeBgLoadModelWtrEntries(
        ulong header,
        uint bodyOffset,
        uint countWord,
        out ulong body,
        out List<(int Slot, string Name, uint Target, uint Flags)> entries)
    {
        body = header + bodyOffset;
        entries = [];
        if (!IsMainRamRange(body + 0x23UL, 1))
            return false;

        int maxEntries = (int)Math.Min(128U, Math.Max(1U, countWord));
        const ulong entryStride = 0x24UL;
        for (int slot = 0; slot < maxEntries; slot++)
        {
            ulong entry = body + (ulong)slot * entryStride;
            if (!IsMainRamRange(entry + 0x23UL, 1))
                break;

            string name = ReadAsciiTraceString(entry, 16);
            if (!IsLikelyRuntimeBgLoadModelWtrEntryName(name))
            {
                if (entries.Count > 0)
                    break;

                continue;
            }

            uint target = _memory.Read32(entry + 0x1cUL);
            uint flags = _memory.Read32(entry + 0x20UL);
            entries.Add((slot, name, target, flags));
        }

        return entries.Count != 0;
    }

    private static bool IsLikelyRuntimeBgLoadModelWtrEntryName(string name)
    {
        if (name.Length is < 2 or > 15)
            return false;

        foreach (char ch in name)
        {
            if (ch is >= 'A' and <= 'Z' ||
                ch is >= '0' and <= '9' ||
                ch == '_')
            {
                continue;
            }

            return false;
        }

        return true;
    }

    private static int FindNearestRuntimeBgLoadModelWtrEntry(
        List<(int Slot, string Name, uint Target, uint Flags)> entries,
        long value)
    {
        int bestSlot = 0;
        ulong bestDistance = ulong.MaxValue;
        for (int i = 0; i < entries.Count; i++)
        {
            long delta = value - entries[i].Target;
            ulong distance = (ulong)(delta < 0 ? -delta : delta);
            if (distance >= bestDistance)
                continue;

            bestDistance = distance;
            bestSlot = i;
        }

        return bestSlot;
    }

    private static string FormatRuntimeBgLoadModelWtrEntry(
        (int Slot, string Name, uint Target, uint Flags) entry,
        long value)
    {
        uint byteLength = entry.Flags & 0x7fffffffU;
        return $"{entry.Slot}:{entry.Name}@0x{entry.Target:x} flags=0x{entry.Flags:x8} size=0x{byteLength:x} delta={FormatSignedHex(value - entry.Target)}";
    }

    private static string FormatRuntimeBgLoadModelWtrEntryList(
        List<(int Slot, string Name, uint Target, uint Flags)> entries,
        int limit)
    {
        StringBuilder builder = new();
        int count = Math.Min(entries.Count, Math.Max(0, limit));
        for (int i = 0; i < count; i++)
        {
            if (i > 0)
                builder.Append(',');

            var entry = entries[i];
            builder.Append(entry.Slot);
            builder.Append(':');
            builder.Append(entry.Name);
            builder.Append("@0x");
            builder.Append(entry.Target.ToString("x"));
            builder.Append("/0x");
            builder.Append(entry.Flags.ToString("x8"));
        }

        if (entries.Count > count)
            builder.Append(",...");

        return builder.ToString();
    }

    private bool IsLikelyZeroBaseUploadDescriptor(ulong source)
    {
        if (!IsMainRamRange(source + 0x1fUL, 1))
            return false;

        uint word0 = _memory.Read32(source);
        uint word2 = _memory.Read32(source + 0x08UL);
        uint word4 = _memory.Read32(source + 0x10UL);
        ulong pointer = SignExtend32(word2);
        return IsLikelyTracePointerWord(word0) &&
               pointer == source + 0x0cUL &&
               (word4 >> 16) < 0x40U;
    }

    private bool IsLikelyTracePointerWord(uint word)
    {
        if (word == 0 || (word & 3U) != 0)
            return false;

        return IsMainRamRange(SignExtend32(word), 4UL);
    }

    private static bool IsLikelyTraceFloatWord(uint word)
    {
        float value = BitConverter.UInt32BitsToSingle(word);
        if (!float.IsFinite(value))
            return false;

        float magnitude = MathF.Abs(value);
        return magnitude is >= 0.000001f and <= 100000.0f;
    }

    private static int CountPrintableAsciiBytes(uint word)
    {
        int count = 0;
        for (int shift = 0; shift <= 24; shift += 8)
        {
            uint value = (word >> shift) & 0xffU;
            if (value is >= 0x20U and <= 0x7eU)
                count++;
        }

        return count;
    }

    private static int CountMeaningfulAscii(string text)
    {
        int count = 0;
        foreach (char ch in text)
        {
            if (ch is >= '0' and <= '9' ||
                ch is >= 'A' and <= 'Z' ||
                ch is >= 'a' and <= 'z' ||
                ch == '_' ||
                ch == '#')
            {
                count++;
            }
        }

        return count;
    }

    private static string ClassifyZeroBaseTextureUploadRun(
        bool knownSource,
        bool knownPayloadSource,
        bool descriptorLike,
        int meaningfulText,
        int sampleWords,
        int zeroWords,
        int pointerWords,
        int floatWords)
    {
        if (knownSource)
            return knownPayloadSource ? "known-bg" : "known-bg-stride-only";
        if (descriptorLike)
            return "descriptor";
        if (meaningfulText >= 8)
            return "ascii-control";
        if (sampleWords == 0)
            return "empty";
        if (pointerWords >= Math.Max(2, sampleWords / 48))
            return "pointer-control";
        if (floatWords >= Math.Max(8, sampleWords / 8))
            return "float-control";
        if (zeroWords * 2 >= sampleWords)
            return "sparse-zero";

        return "texture-ish";
    }

    private string FormatTraceWords(ulong address, int words)
    {
        if (words <= 0 || !IsMainRamRange(address + (ulong)(words - 1) * 4UL, 4UL))
            return "";

        StringBuilder builder = new();
        for (int i = 0; i < words; i++)
        {
            if (i > 0)
                builder.Append('/');
            builder.Append(_memory.Read32(address + (ulong)i * 4UL).ToString("x8"));
        }

        return builder.ToString();
    }

    private string FormatDiskTraceWords(ulong byteOffset, int words)
    {
        if (words <= 0)
            return "";

        StringBuilder builder = new();
        for (int i = 0; i < words; i++)
        {
            if (i > 0)
                builder.Append('/');

            ulong wordOffset = byteOffset + (ulong)i * 4UL;
            builder.Append(_memory.TryReadDiskByteOffsetWord(wordOffset, out uint word)
                ? word.ToString("x8", CultureInfo.InvariantCulture)
                : "--------");
        }

        return builder.ToString();
    }

    private void TraceRuntimeBgLoadModelHydrationRange(
        string phase,
        ulong destination,
        uint byteCount,
        ulong diskByteOffset,
        string detail)
    {
        if (!_traceRuntimeBgLoadModelHydrationRange ||
            _runtimeBgLoadModelHydrationRangeTraceCount >= _traceRuntimeBgLoadModelHydrationRangeLimit ||
            byteCount == 0 ||
            _traceRuntimeBgLoadModelHydrationRangeBytes <= 0 ||
            !TryGetMainRamPhysical(destination, out uint destinationPhysical) ||
            !TryGetMainRamPhysical(_traceRuntimeBgLoadModelHydrationRangeAddress, out uint targetPhysical))
        {
            return;
        }

        ulong copyStart = destinationPhysical;
        ulong copyEnd = copyStart + byteCount;
        ulong targetStart = targetPhysical;
        ulong targetEnd = targetStart + (ulong)_traceRuntimeBgLoadModelHydrationRangeBytes;
        if (copyEnd <= targetStart || targetEnd <= copyStart)
            return;

        ulong overlapStart = Math.Max(copyStart, targetStart);
        ulong overlapEnd = Math.Min(copyEnd, targetEnd);
        ulong copyOffset = overlapStart - copyStart;
        ulong targetOffset = overlapStart - targetStart;
        ulong overlapAddress = destination + copyOffset;
        ulong wordAddress = overlapAddress & ~3UL;
        ulong diskWordOffset = diskByteOffset + (wordAddress >= destination ? wordAddress - destination : copyOffset);
        int wordCount = Math.Min(8, Math.Max(1, (_traceRuntimeBgLoadModelHydrationRangeBytes + 3) / 4));

        _runtimeBgLoadModelHydrationRangeTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:TRACE] bgloadmodel-hydration-range n={_runtimeBgLoadModelHydrationRangeTraceCount} " +
            $"phase={phase} dest=0x{destination:x16} bytes=0x{byteCount:x8} disk=0x{diskByteOffset:x8} " +
            $"target=0x{_traceRuntimeBgLoadModelHydrationRangeAddress:x16}:0x{_traceRuntimeBgLoadModelHydrationRangeBytes:x} " +
            $"overlapCopy=+0x{copyOffset:x}..+0x{overlapEnd - copyStart:x} " +
            $"overlapTarget=+0x{targetOffset:x}..+0x{overlapEnd - targetStart:x} " +
            $"wordAddress=0x{wordAddress:x16} diskWord=0x{diskWordOffset:x8} " +
            $"ram={FormatTraceWords(wordAddress, wordCount)} diskWords={FormatDiskTraceWords(diskWordOffset, wordCount)} " +
            $"detail={detail}");
    }

    private void TraceTextureUploadPayloadRun(
        ulong pc,
        ulong source,
        uint sourceBase,
        uint currentPacketAddress,
        uint payloadWords,
        uint index,
        uint limit,
        ulong sp,
        ulong state,
        uint fifo,
        uint room)
    {
        if (!_traceTextureUploadPayload ||
            !AllowsTextureUploadRunSourceTrace(source) ||
            _textureUploadPayloadRunTraceCount++ >= 96)
            return;

        uint stackSourceBase = IsMainRamRange(sp + 0x1cUL, 4) ? _memory.Read32(sp + 0x1cUL) : 0;
        uint stackLimit = IsMainRamRange(sp + 0x74UL, 4) ? _memory.Read32(sp + 0x74UL) : 0;
        uint stateFifo = IsMainRamRange(state + 0x374UL, 4) ? _memory.Read32(state + 0x374UL) : 0;
        uint stateRoom = IsMainRamRange(state + 0x37cUL, 4) ? _memory.Read32(state + 0x37cUL) : 0;

        Console.WriteLine(
            $"[GAUNTDL:TEXUPLOAD-RUN] pc=0x{pc:x16} ra=0x{_gpr[31]:x16} " +
            $"source=0x{source:x16} {DescribeKnownRuntimeBgLoadModelUploadSource(source)} " +
            $"sourceBase=0x{sourceBase:x8}/sp1c=0x{stackSourceBase:x8} packet=0x{currentPacketAddress:x8} " +
            $"index={index}/{limit}/sp74={stackLimit} words={payloadWords} " +
            $"s1=0x{_gpr[17]:x16} s2=0x{_gpr[18]:x16} s4=0x{_gpr[20]:x16} s6=0x{_gpr[22]:x16} " +
            $"fifo=0x{fifo:x8}/state=0x{stateFifo:x8} room=0x{room:x8}/state=0x{stateRoom:x8}");

        TraceTextureUploadPayloadSpanComposition(source, sourceBase, payloadWords, index, limit);
    }

    private void TraceTextureUploadPayloadCallerPrep(
        ulong pc,
        uint op,
        bool branchFromPreviousInstruction,
        ulong branchTarget)
    {
        const ulong callerTraceStart = 0x000fe2f0UL;
        const ulong callerTraceEnd = 0x000fe5d4UL;

        if (!_traceTextureUploadPayload || _traceTextureUploadCallerTransitions)
            return;

        ulong physicalPc = pc & 0x1fffffffUL;
        if (physicalPc < callerTraceStart || physicalPc > callerTraceEnd)
            return;

        ulong sp = _gpr[29];
        ulong s6 = _gpr[22];
        if (_traceTextureUploadRunSource.HasValue)
        {
            bool matchesSource = s6 == _traceTextureUploadRunSource.Value;
            if (!matchesSource && IsMainRamRange(s6 + 0x08UL, 4))
                matchesSource = SignExtend32(_memory.Read32(s6 + 0x08UL)) == _traceTextureUploadRunSource.Value;
            if (!matchesSource)
                return;
        }

        bool focusedZeroBase = s6 >= 0xffffffff80300000UL &&
                               IsKnownRuntimeBgLoadModelUploadSourceCandidate(s6) &&
                               ReadTraceWord(sp + 0x1cUL) == 0;
        if (_textureUploadPayloadCallerTraceCount >= 256)
        {
            if (!focusedZeroBase || _textureUploadPayloadFocusedCallerTraceCount++ >= 256)
                return;
        }
        else
        {
            _textureUploadPayloadCallerTraceCount++;
        }

        Console.WriteLine(
            $"[GAUNTDL:TEXUPLOAD-CALLER] pc=0x{pc:x16} op=0x{op:x8} " +
            $"branchPrev={(branchFromPreviousInstruction ? 1 : 0)} branchTarget=0x{branchTarget:x16} " +
            $"ra=0x{_gpr[31]:x16} sp=0x{sp:x16} " +
            $"a0=0x{_gpr[4]:x16} a1=0x{_gpr[5]:x16} a2=0x{_gpr[6]:x16} a3=0x{_gpr[7]:x16} " +
            $"v0=0x{_gpr[2]:x16} v1=0x{_gpr[3]:x16} " +
            $"t0=0x{_gpr[8]:x16} t1=0x{_gpr[9]:x16} t8=0x{_gpr[24]:x16} t9=0x{_gpr[25]:x16} " +
            $"s0=0x{_gpr[16]:x16} s1=0x{_gpr[17]:x16} s2=0x{_gpr[18]:x16} s3=0x{_gpr[19]:x16} " +
            $"s4=0x{_gpr[20]:x16} s5=0x{_gpr[21]:x16} s6=0x{s6:x16} s7=0x{_gpr[23]:x16} " +
            $"{DescribeKnownRuntimeBgLoadModelUploadSource(s6)} " +
            $"state08={ReadTraceWord(_gpr[16] + 0x08UL):x8} state298={ReadTraceWord(_gpr[16] + 0x298UL):x8} " +
            $"state374={ReadTraceWord(_gpr[16] + 0x374UL):x8} state37c={ReadTraceWord(_gpr[16] + 0x37cUL):x8} " +
            $"sp18={ReadTraceWord(sp + 0x18UL):x8} sp1c={ReadTraceWord(sp + 0x1cUL):x8} " +
            $"sp20={ReadTraceWord(sp + 0x20UL):x8} sp24={ReadTraceWord(sp + 0x24UL):x8} " +
            $"sp50={ReadTraceWord(sp + 0x50UL):x8} sp58={ReadTraceWord(sp + 0x58UL):x8} " +
            $"sp60={ReadTraceWord(sp + 0x60UL):x8} sp64={ReadTraceWord(sp + 0x64UL):x8} " +
            $"sp70={ReadTraceWord(sp + 0x70UL):x8} sp74={ReadTraceWord(sp + 0x74UL):x8} " +
            $"sp78={ReadTraceWord(sp + 0x78UL):x8}");
    }

    private bool IsKnownRuntimeBgLoadModelUploadSourceCandidate(ulong source)
    {
        const ulong destinationBase = 0xffffffff802e1718UL;
        ulong sourceStride = (ulong)_runtimeBgLoadModelIndexedSourceStride;

        for (ulong index = 1; index <= KnownRuntimeBgLoadModelTexturePayloadMaxIndex; index++)
        {
            if (!TryGetKnownRuntimeBgLoadModelTexturePayload(index, out _, out _, out uint textureByteLength))
                continue;

            ulong candidateBase = destinationBase + index * sourceStride;
            ulong candidateEnd = candidateBase + GetKnownRuntimeBgLoadModelSourceSpanByteLength(textureByteLength);
            if (source >= candidateBase && source < candidateEnd)
                return true;
        }

        return false;
    }

    private bool IsKnownRuntimeBgLoadModelUploadSourceCandidateForZeroBasePrefix(ulong source)
    {
        if (!IsKnownRuntimeBgLoadModelUploadSourceCandidate(source))
            return false;

        if (_experimentZeroBaseUploadTreatBadHeaderAsUnknown &&
            !TryGetPlausibleKnownRuntimeBgLoadModelUploadHeaderForSource(
                source,
                out _,
                out _,
                out _,
                out _,
                out _,
                out _))
        {
            return false;
        }

        return !_experimentZeroBaseUploadTreatStrideOnlyAsUnknown ||
               IsKnownRuntimeBgLoadModelUploadSourceInsidePayload(source);
    }

    private bool IsKnownRuntimeBgLoadModelUploadSourceInsidePayload(ulong source)
    {
        const ulong destinationBase = 0xffffffff802e1718UL;
        ulong sourceStride = (ulong)_runtimeBgLoadModelIndexedSourceStride;
        source = SignExtend32((uint)source);

        for (ulong index = 1; index <= KnownRuntimeBgLoadModelTexturePayloadMaxIndex; index++)
        {
            if (!TryGetKnownRuntimeBgLoadModelTexturePayload(index, out _, out _, out uint textureByteLength))
                continue;

            ulong candidateBase = destinationBase + index * sourceStride;
            if (source >= candidateBase && source < candidateBase + textureByteLength)
                return true;
        }

        return false;
    }

    private void TraceTextureUploadPayloadSpanComposition(
        ulong source,
        uint sourceBase,
        uint payloadWords,
        uint index,
        uint limit)
    {
        if (!_traceTextureUploadPayload ||
            !AllowsTextureUploadRunSourceTrace(source) ||
            payloadWords == 0 ||
            index > limit ||
            sourceBase != 0 ||
            !IsKnownRuntimeBgLoadModelUploadSourceCandidate(source))
        {
            return;
        }

        if (_textureUploadPayloadSpanTraceCount++ >= 48)
            return;

        uint packets = limit - index + 1U;
        ulong sourceBytes = (ulong)packets * payloadWords * 4UL;
        string segments = FormatKnownRuntimeBgLoadModelUploadSpan(source, source + sourceBytes, 10);

        Console.WriteLine(
            $"[GAUNTDL:TEXUPLOAD-SPAN] source=0x{source:x16} bytes=0x{sourceBytes:x} " +
            $"packets={packets} words={payloadWords} index={index}/{limit} segments={segments}");
    }

    private string DescribeKnownRuntimeBgLoadModelUploadSpanSegment(ulong address, out ulong nextBoundary)
    {
        const ulong destinationBase = 0xffffffff802e1718UL;
        ulong sourceStride = (ulong)_runtimeBgLoadModelIndexedSourceStride;

        nextBoundary = ulong.MaxValue;
        StringBuilder matches = new();
        for (ulong index = 1; index <= KnownRuntimeBgLoadModelTexturePayloadMaxIndex; index++)
        {
            if (!TryGetKnownRuntimeBgLoadModelTexturePayload(index, out string code, out ulong byteOffset, out uint textureByteLength))
                continue;

            ulong candidateBase = destinationBase + index * sourceStride;
            ulong candidateEnd = candidateBase + GetKnownRuntimeBgLoadModelSourceSpanByteLength(textureByteLength);
            if (address >= candidateBase && address < candidateEnd)
            {
                if (matches.Length > 0)
                    matches.Append('|');

                ulong candidateOffset = address - candidateBase;
                matches.Append(index);
                matches.Append(':');
                matches.Append(code);
                matches.Append("@0x");
                matches.Append(candidateOffset.ToString("x"));
                if (_memory.TryReadDiskByteOffsetWord(byteOffset + candidateOffset, out uint diskWord))
                {
                    matches.Append('=');
                    matches.Append(diskWord.ToString("x8"));
                }

                nextBoundary = Math.Min(nextBoundary, candidateEnd);
            }

            if (address < candidateBase)
                nextBoundary = Math.Min(nextBoundary, candidateBase);
        }

        if (matches.Length == 0)
            return "none";

        uint memoryWord = IsMainRamRange(address, 4) ? _memory.Read32(address) : 0;
        matches.Append(";mem=");
        matches.Append(memoryWord.ToString("x8"));
        return matches.ToString();
    }

    private bool TryReadKnownRuntimeBgLoadModelUploadDiskWord(
        ulong address,
        out uint word,
        out string sourceDescription)
    {
        const ulong destinationBase = 0xffffffff802e1718UL;
        const ulong fontStoryPayload = 0xffffffff803129a4UL;
        const ulong gebPayloadOffset = 0x128cUL;
        const ulong fontStoryGebBytes = 0x9ea4UL;
        ulong sourceStride = (ulong)_runtimeBgLoadModelIndexedSourceStride;

        word = 0;
        sourceDescription = "";
        if (address >= fontStoryPayload &&
            address + 4UL <= fontStoryPayload + fontStoryGebBytes &&
            TryGetKnownRuntimeBgLoadModelTexturePayload(6, out _, out ulong gebDiskOffset, out _) &&
            _memory.TryReadDiskByteOffsetWord(
                gebDiskOffset + gebPayloadOffset + (address - fontStoryPayload),
                out word))
        {
            sourceDescription = $"font_story:geb@0x{gebPayloadOffset + address - fontStoryPayload:x}";
            return true;
        }

        uint fallbackWord = 0;
        string fallbackDescription = "";
        bool hasFallback = false;

        for (ulong index = 1; index <= KnownRuntimeBgLoadModelTexturePayloadMaxIndex; index++)
        {
            if (!TryGetKnownRuntimeBgLoadModelTexturePayload(index, out string code, out ulong byteOffset, out uint textureByteLength))
                continue;

            ulong candidateBase = destinationBase + index * sourceStride;
            ulong candidateEnd = candidateBase + GetKnownRuntimeBgLoadModelSourceSpanByteLength(textureByteLength);
            if (address < candidateBase || address >= candidateEnd)
                continue;

            ulong candidateOffset = address - candidateBase;
            if (!_memory.TryReadDiskByteOffsetWord(byteOffset + candidateOffset, out uint candidateWord))
                continue;

            string candidateDescription = $"{index}:{code}@0x{candidateOffset:x}";
            fallbackWord = candidateWord;
            fallbackDescription = candidateDescription;
            hasFallback = true;
            if (candidateWord == 0)
                continue;

            word = candidateWord;
            sourceDescription = candidateDescription;
        }

        if (sourceDescription.Length > 0)
            return true;

        if (!hasFallback)
            return false;

        word = fallbackWord;
        sourceDescription = fallbackDescription;
        return true;
    }

    private string DescribeKnownRuntimeBgLoadModelUploadSource(ulong source)
    {
        const ulong destinationBase = 0xffffffff802e1718UL;
        const ulong fontStoryPayload = 0xffffffff803129a4UL;
        const ulong gebPayloadOffset = 0x128cUL;
        const ulong fontStoryGebBytes = 0x9ea4UL;
        if (source >= fontStoryPayload && source < fontStoryPayload + fontStoryGebBytes)
            return $"bgsrc=font_story:geb+0x{gebPayloadOffset + source - fontStoryPayload:x}";

        ulong sourceStride = (ulong)_runtimeBgLoadModelIndexedSourceStride;
        StringBuilder builder = new();
        int matches = 0;

        for (ulong index = 1; index <= KnownRuntimeBgLoadModelTexturePayloadMaxIndex; index++)
        {
            if (!TryGetKnownRuntimeBgLoadModelTexturePayload(index, out string code, out _, out uint textureByteLength))
                continue;

            ulong candidateBase = destinationBase + index * sourceStride;
            ulong candidateEnd = candidateBase + GetKnownRuntimeBgLoadModelSourceSpanByteLength(textureByteLength);
            if (source < candidateBase || source >= candidateEnd)
                continue;

            if (!IsMainRamRange(candidateBase + 0x64UL, 4))
                continue;

            uint bodyOffset = _memory.Read32(candidateBase + 0x5cUL);
            uint countWord = _memory.Read32(candidateBase + 0x60UL);
            uint strideWord = _memory.Read32(candidateBase + 0x64UL);
            bool plausibleHeader = IsPlausibleKnownRuntimeBgLoadModelUploadHeader(
                bodyOffset,
                countWord,
                strideWord,
                textureByteLength);
            long sourceOffset = unchecked((long)(source - candidateBase));
            long bodyDelta = unchecked(sourceOffset - bodyOffset);
            if (matches++ == 0)
                builder.Append("bgsrc=");
            else
                builder.Append(',');

            builder.Append(index);
            builder.Append(':');
            builder.Append(code);
            builder.Append("+0x");
            builder.Append(sourceOffset.ToString("x"));
            builder.Append("(body=0x");
            builder.Append(bodyOffset.ToString("x"));
            builder.Append('/');
            builder.Append(FormatSignedHex(bodyDelta));
            builder.Append(" len=0x");
            builder.Append(textureByteLength.ToString("x"));
            builder.Append(" hdr60=0x");
            builder.Append(countWord.ToString("x8"));
            builder.Append(" hdr64=0x");
            builder.Append(strideWord.ToString("x8"));
            builder.Append(" hdr=");
            builder.Append(plausibleHeader ? "ok" : "bad");
            builder.Append(')');

            if (matches >= 8)
                break;
        }

        return matches == 0 ? "bgsrc=none" : builder.ToString();
    }

    private string DescribeKnownRuntimeBgLoadModelUploadSourceOwners(ulong source)
    {
        const ulong destinationBase = 0xffffffff802e1718UL;
        source = SignExtend32((uint)source);
        ulong sourceStride = (ulong)_runtimeBgLoadModelIndexedSourceStride;
        StringBuilder builder = new();
        int matches = 0;

        for (ulong index = 1; index <= KnownRuntimeBgLoadModelTexturePayloadMaxIndex; index++)
        {
            if (!TryGetKnownRuntimeBgLoadModelTexturePayload(index, out string code, out ulong byteOffset, out uint textureByteLength))
                continue;

            ulong candidateBase = destinationBase + index * sourceStride;
            ulong spanLength = GetKnownRuntimeBgLoadModelSourceSpanByteLength(textureByteLength);
            ulong candidateEnd = candidateBase + spanLength;
            if (source < candidateBase || source >= candidateEnd)
                continue;

            ulong sourceOffset = source - candidateBase;
            bool insidePayload = sourceOffset < textureByteLength;
            if (matches++ > 0)
                builder.Append(',');

            builder.Append(index);
            builder.Append(':');
            builder.Append(code);
            builder.Append("+0x");
            builder.Append(sourceOffset.ToString("x"));
            builder.Append(insidePayload ? "/payload" : "/stride-only");
            builder.Append("/len=0x");
            builder.Append(textureByteLength.ToString("x"));
            builder.Append("/span=0x");
            builder.Append(spanLength.ToString("x"));

            if (IsMainRamRange(candidateBase + 0x64UL, 4))
            {
                uint bodyOffset = _memory.Read32(candidateBase + 0x5cUL);
                uint countWord = _memory.Read32(candidateBase + 0x60UL);
                uint strideWord = _memory.Read32(candidateBase + 0x64UL);
                bool plausibleHeader = IsPlausibleKnownRuntimeBgLoadModelUploadHeader(
                    bodyOffset,
                    countWord,
                    strideWord,
                    textureByteLength);
                long bodyDelta = unchecked((long)sourceOffset - bodyOffset);
                builder.Append("/body=0x");
                builder.Append(bodyOffset.ToString("x"));
                builder.Append('/');
                builder.Append(FormatSignedHex(bodyDelta));
                builder.Append("/hdr=");
                builder.Append(plausibleHeader ? "ok" : "bad");
            }

            if (insidePayload && _memory.TryReadDiskByteOffsetWord(byteOffset + sourceOffset, out uint diskWord))
            {
                builder.Append("/disk=");
                builder.Append(diskWord.ToString("x8"));
            }

            if (matches >= 8)
                break;
        }

        return matches == 0 ? "none" : builder.ToString();
    }

    private string DescribeRuntimeBgLoadModelSourceTableOwners(ulong source)
    {
        const ulong sourceTable = 0xffffffff802529a0UL;
        const ulong sideTable = 0xffffffff802549a0UL;
        const ulong assetTable = 0xffffffff8024f9a0UL;
        const ulong assetStride = 0x30UL;
        const ulong slotCount = 0x40UL;

        uint sourceWord = unchecked((uint)source);
        StringBuilder builder = new();
        int matches = 0;
        for (ulong index = 0; index < slotCount; index++)
        {
            ulong sourceSlot = sourceTable + index * 4UL;
            if (!IsMainRamRange(sourceSlot, 4UL) || _memory.Read32(sourceSlot) != sourceWord)
                continue;

            ulong sideSlot = sideTable + index * 4UL;
            ulong assetEntry = assetTable + index * assetStride;
            uint assetPointer = IsMainRamRange(assetEntry, assetStride)
                ? _memory.Read32(assetEntry)
                : 0U;
            uint sidePointer = IsMainRamRange(sideSlot, 4UL)
                ? _memory.Read32(sideSlot)
                : 0U;
            string name = IsMainRamRange(assetEntry, assetStride)
                ? ReadAsciiTraceString(assetEntry + 0x10UL, 24)
                : "";

            if (matches++ > 0)
                builder.Append(',');
            builder.Append(index);
            builder.Append(':');
            builder.Append(name.Length == 0 ? "<empty>" : name);
            builder.Append("/asset=");
            builder.Append(assetPointer.ToString("x8", CultureInfo.InvariantCulture));
            builder.Append("/side=");
            builder.Append(sidePointer.ToString("x8", CultureInfo.InvariantCulture));

            if (matches >= 16)
                break;
        }

        return matches == 0 ? "none" : builder.ToString();
    }

    private bool TryGetPlausibleKnownRuntimeBgLoadModelUploadHeaderForSource(
        ulong source,
        out string code,
        out ulong header,
        out long sourceOffset,
        out uint countWord,
        out uint strideWord,
        out uint textureByteLength)
    {
        const ulong destinationBase = 0xffffffff802e1718UL;
        ulong sourceStride = (ulong)_runtimeBgLoadModelIndexedSourceStride;

        code = "";
        header = 0;
        sourceOffset = 0;
        countWord = 0;
        strideWord = 0;
        textureByteLength = 0;

        for (ulong index = 1; index <= KnownRuntimeBgLoadModelTexturePayloadMaxIndex; index++)
        {
            if (!TryGetKnownRuntimeBgLoadModelTexturePayload(index, out string candidateCode, out _, out uint candidateTextureByteLength))
                continue;

            ulong candidateHeader = destinationBase + index * sourceStride;
            ulong candidateEnd = candidateHeader + GetKnownRuntimeBgLoadModelSourceSpanByteLength(candidateTextureByteLength);
            if (source < candidateHeader || source >= candidateEnd)
                continue;

            if (!IsMainRamRange(candidateHeader + 0x64UL, 4))
                continue;

            uint bodyOffset = _memory.Read32(candidateHeader + 0x5cUL);
            uint candidateCountWord = _memory.Read32(candidateHeader + 0x60UL);
            uint candidateStrideWord = _memory.Read32(candidateHeader + 0x64UL);
            if (!IsPlausibleKnownRuntimeBgLoadModelUploadHeader(
                    bodyOffset,
                    candidateCountWord,
                    candidateStrideWord,
                    candidateTextureByteLength))
            {
                continue;
            }

            code = candidateCode;
            header = candidateHeader;
            sourceOffset = unchecked((long)(source - candidateHeader));
            countWord = candidateCountWord;
            strideWord = candidateStrideWord;
            textureByteLength = candidateTextureByteLength;
            return true;
        }

        return false;
    }

