    private static bool IsPlausibleKnownRuntimeBgLoadModelUploadHeader(
        uint bodyOffset,
        uint countWord,
        uint strideWord,
        uint textureByteLength)
    {
        const uint payloadLengthTolerance = 0x400U;

        return bodyOffset > 0 &&
               bodyOffset <= textureByteLength + payloadLengthTolerance &&
               countWord is > 0 and < 0x10000U &&
               strideWord is > 0 and < 0x10000U;
    }

    private ulong GetKnownRuntimeBgLoadModelSourceSpanByteLength(uint textureByteLength)
        => Math.Max((ulong)textureByteLength, (ulong)Math.Max(_runtimeBgLoadModelIndexedSourceStride, 0));

    private static string FormatSignedHex(long value)
    {
        return value < 0 ? $"-0x{(-value):x}" : $"+0x{value:x}";
    }

    private void WriteGlideFifoWord(ref uint fifo, uint value, uint ringBase, uint ringBytes)
    {
        fifo = WrapGlideFifoPointer(fifo, ringBase, ringBytes);
        _memory.Write32(fifo, value);
        fifo = WrapGlideFifoPointer(unchecked(fifo + 4U), ringBase, ringBytes);
    }

    private static uint WrapGlideFifoPointer(uint fifo, uint ringBase, uint ringBytes)
    {
        if (ringBytes == 0)
            return fifo;

        uint offset = unchecked(fifo - ringBase);
        if (offset >= ringBytes)
            offset %= ringBytes;
        return unchecked(ringBase + offset);
    }

    private void TraceGlideFifoOuterPayloadReject(string reason)
    {
        if (!_traceTextureUploadProvenance || _textureUploadProvenanceTraceCount++ >= 32)
            return;

        Console.WriteLine(
            $"[GAUNTDL:FIFO-OUTER] reject {reason} pc={Pc:x16} " +
            $"s0={_gpr[16]:x16} s2={_gpr[18]:x16} s4={_gpr[20]:x16} s6={_gpr[22]:x16} " +
            $"a0={_gpr[4]:x16} sp={_gpr[29]:x16}");
    }

    private void TraceGlideFifoOuterPayloadOddWords(
        uint packet,
        uint packetSourceAddress,
        ulong source,
        uint payloadWords,
        uint header)
    {
        int oddPayloadLimit = Math.Min(_traceVertexFifoFastPathLimit, 64);
        if (!_traceVertexFifoFastPath || _vertexFifoFastPathOddPayloadTraceCount >= oddPayloadLimit)
            return;

        for (uint word = 0; word < payloadWords && word < 64U; word++)
        {
            uint value = _memory.Read32(source + word * 4UL);
            uint type = value & 7U;
            if (type is not (2U or 6U or 7U))
                continue;

            uint next0 = word + 1U < payloadWords ? _memory.Read32(source + (word + 1U) * 4UL) : 0;
            uint next1 = word + 2U < payloadWords ? _memory.Read32(source + (word + 2U) * 4UL) : 0;
            Console.WriteLine(
                $"[GAUNTDL:VERTEX-FIFO] odd-payload packet={packet} packetSource=0x{packetSourceAddress:x8} " +
                $"source=0x{source:x16} word={word} value=0x{value:x8} type={type} " +
                $"next=0x{next0:x8}/0x{next1:x8} payloadWords={payloadWords} header=0x{header:x8} " +
                $"s2={_gpr[18]:x16} limit={_memory.Read32(_gpr[29] + 0x74UL):x8}");
            _vertexFifoFastPathOddPayloadTraceCount++;
            return;
        }
    }

    private void TraceTextureUploadProvenance(ulong pc, ulong destination, ulong source, uint count, uint limit, uint remainingPairs)
    {
        if (!_traceTextureUploadProvenance || _textureUploadProvenanceTraceCount >= 96)
            return;

        uint dest = (uint)destination;
        if (dest is < 0xa8000000U or >= 0xa8400000U)
            return;

        int words = (int)Math.Min((ulong)remainingPairs * 2UL, 128UL);
        for (int i = 0; i + 2 < words && _textureUploadProvenanceTraceCount < 96; i++)
        {
            ulong commandAddress = source + (uint)(i * 4);
            uint command = _memory.Read32(commandAddress);
            if ((command & 7u) != 5u || (command >> 30) != 3u)
                continue;

            int payloadWords = (int)((command >> 3) & 0x7ffffu);
            if (payloadWords <= 0 || i + 1 >= words)
                continue;

            uint target = _memory.Read32(commandAddress + 4UL);
            uint first = i + 2 < words ? _memory.Read32(commandAddress + 8UL) : 0;
            uint second = i + 3 < words ? _memory.Read32(commandAddress + 12UL) : 0;
            int nonZero = 0;
            int sampleWords = Math.Min(payloadWords, Math.Max(0, words - i - 2));
            for (int sample = 0; sample < sampleWords; sample++)
            {
                if (_memory.Read32(commandAddress + 8UL + (uint)(sample * 4)) != 0)
                    nonZero++;
            }

            Console.WriteLine(
                $"[GAUNTDL:TEXSRC] pc={pc:x16} dest=0x{dest:x8} src={source:x16} cmdOff={i} " +
                $"count={count}/{limit} pairs={remainingPairs} type5Words={payloadWords} " +
                $"target=0x{target:x8} first=0x{first:x8} second=0x{second:x8} nzSample={nonZero}/{sampleWords}");
            _textureUploadProvenanceTraceCount++;

            i += 1 + payloadWords;
        }
    }

