        _gpr[2] = result;
        _gpr[3] = invertedMask;
        _gpr[10] = SignExtend32(_memory.Read32(sp + 0x18UL));
        _gpr[11] = SignExtend32(_memory.Read32(sp + 0x1cUL));
        _gpr[12] = signedLimit;
        _gpr[13] = counterBase;
        _gpr[14] = t6;
