    private bool MatchesKnownBootA420Handshake(ulong entry, ulong pc)
    {
        ReadOnlySpan<(ulong Offset, uint Expected)> signature =
        [
            (0x00UL, 0x03e0382dU),
            (0x04UL, 0x3c08a420U),
            (0x08UL, 0x81090000U),
            (0x0cUL, 0x2401fffeU),
            (0x10UL, 0x01214824U),
            (0x14UL, 0xa1090000U),
            (0x18UL, 0x04110074U),
            (0x1cUL, 0x240403e8U),
            (0x20UL, 0x35290001U),
            (0x24UL, 0xa1090000U),
            (0x34UL, 0x0411feabU),
            (0x38UL, 0x00000000U),
            (0x3cUL, 0x1c400006U),
            (0x44UL, 0x256bffffU),
            (0x48UL, 0x1d60fff8U),
            (0x50UL, 0x00e00008U),
            (0x54UL, 0x24020001U),
        ];

        foreach ((ulong offset, uint expected) in signature)
        {
            uint actual = _memory.Read32(entry + offset);
            if (actual == expected)
                continue;

            if (_traceRd0Home && _bootA420HandshakeTraceCount++ < 8)
            {
                Console.WriteLine(
                    $"[GAUNTDL:BOOT] boot-a420-skip pc={pc:x16} " +
                    $"reason=signature off={offset:x2} actual={actual:x8} expected={expected:x8}");
            }
            return false;
        }

        return true;
    }

