        _memory.Write32(objectAddress + 0x14UL, status);
        _memory.Write32(framePointer + 0x24UL, status);
        _gpr[2] = SignExtend32(status);
        _gpr[3] = SignExtend32(status);
        _gpr[0] = 0;
