                 0xffffffff800c86ecUL or 0xffffffff800c86f0UL or
                 0xffffffff800c86f4UL or 0xffffffff800c86f8UL or
                 0xffffffff800c86fcUL or 0xffffffff800c8700UL or
                 0xffffffff800c8704UL or 0xffffffff800c8708UL or
                 0xffffffff800c870cUL or 0xffffffff800c8710UL or
                 0xffffffff800c8714UL or 0xffffffff800c8718UL or
                 0xffffffff800c871cUL or 0xffffffff800c8720UL or
                 0xffffffff800c8724UL or 0xffffffff800c8728UL;

    private void ApplyKnownGauntletSelftestLatchRepair(ulong pc)
    {
        const ulong selftestLatch = 0xffffffff8022814cUL;
        const ulong fallbackSelftestRecord = 0xffffffff801535acUL;
        if (!_enableSelftestLatchRepair ||
            pc is not (0xffffffff800d0668UL or
                       0xffffffff800ddebcUL or
                       0xffffffff800cd418UL))
        {
            return;
        }
        if (_memory.Read32(selftestLatch) != 0x801535acU ||
            _memory.Read32(fallbackSelftestRecord) != 0x800e07e8U)
        {
            return;
        }

        ushort port0 = _memory.Read16(0x00000000a4a00008UL);
        ushort systemPort = _memory.Read16(0x00000000a4a0000aUL);
        if ((port0 & 0x0080) != 0 && (systemPort & 0x0010) != 0)
            return;

        _memory.Write32(selftestLatch, 0);
        if (_traceRd0Home && _selftestLatchRepairTraceCount++ < 4)
        {
            Console.WriteLine(
                $"[GAUNTDL:BOOT] clear-selftest-latch pc={pc:x16} " +
                $"port0={port0:x4} system={systemPort:x4}");
        }
    }

    private bool TryRepairKnownGauntletVolumeNvramSyncCheck(ulong pc)
    {
        const ulong entry = 0xffffffff8001594cUL;
        const ulong callerReturnPc = 0xffffffff80015e54UL;
        if (_enableVolumeNvramSyncRepair && pc == entry)
        {
            if (_memory.Read32(entry) != 0x27bdfb40U ||
                _memory.Read32(entry + 0x04UL) != 0xafb304a4U ||
                _memory.Read32(entry + 0x08UL) != 0x00a0982dU ||
                _memory.Read32(entry + 0x0cUL) != 0xafbe04b8U ||
                _memory.Read32(entry + 0x10UL) != 0x00c0f02dU ||
                _memory.Read32(entry + 0x14UL) != 0xafb204a0U ||
                _gpr[31] != callerReturnPc ||
                _gpr[5] == 0)
            {
                return false;
            }

            ulong destination = _gpr[4];
            uint maxByteCount = (uint)_gpr[5];
            if (!_memory.TryReadGauntletBootElfToMemory(
                    destination,
                    maxByteCount,
                    out uint lba,
                    out uint byteCount,
                    out string reason))
            {
                if (_traceRd0Home && _bootCountDelayTraceCount++ < 16)
                {
                    Console.WriteLine(
                        $"[GAUNTDL:RD0] boot-elf-read-skip pc={pc:x16} " +
                        $"dest={destination:x16} max={maxByteCount:x8} reason={reason}");
                }
                return false;
            }

            if (IsMainRamRange(_gpr[6], 8))
            {
                _memory.Write32(_gpr[6], 0);
                _memory.Write32(_gpr[6] + 4UL, 0);
            }
            if (IsMainRamRange(_gpr[7], 8))
            {
                _memory.Write32(_gpr[7], 0);
                _memory.Write32(_gpr[7] + 4UL, 0);
            }

            _gpr[2] = 0;
            Pc = _gpr[31];
            CompleteFastPathStep();
            if (_traceRd0Home && _bootCountDelayTraceCount++ < 16)
            {
                Console.WriteLine(
                    $"[GAUNTDL:RD0] boot-elf-read pc={pc:x16} " +
                    $"lba={lba:x8} dest={destination:x16} bytes={byteCount:x8}");
            }
            return true;
        }
        return false;
    }

    private bool TryFastPathKnownRuntimeTextStateBlitBody(ulong pc)
    {
        if (pc is < 0xffffffff800e3500UL or > 0xffffffff800e388cUL)
            return false;

        if (_memory.Read32(0xffffffff800e3888UL) != 0x02a0102dU ||
            _memory.Read32(0xffffffff800e388cUL) != 0x8fbf00a4U ||
            _memory.Read32(0xffffffff800e38b4UL) != 0x03e00008U ||
            _memory.Read32(0xffffffff800e38b8UL) != 0x27bd00a8U)
        {
            return false;
        }

        ulong sp = _gpr[29];
        if (!IsMainRamRange(sp + 0x80UL, 0x28UL))
        {
            return false;
        }

        ulong returnAddress = SignExtend32(_memory.Read32(sp + 0xa4UL));
        ulong returnOffset = returnAddress & 0x1fffffffUL;
        if (returnOffset is < 0x000c0000UL or > 0x00110000UL)
        {
            return false;
        }

        _gpr[2] = _gpr[21];
        _gpr[31] = returnAddress;
        _gpr[30] = SignExtend32(_memory.Read32(sp + 0xa0UL));
        _gpr[23] = SignExtend32(_memory.Read32(sp + 0x9cUL));
        _gpr[22] = SignExtend32(_memory.Read32(sp + 0x98UL));
        _gpr[21] = SignExtend32(_memory.Read32(sp + 0x94UL));
        _gpr[20] = SignExtend32(_memory.Read32(sp + 0x90UL));
        _gpr[19] = SignExtend32(_memory.Read32(sp + 0x8cUL));
        _gpr[18] = SignExtend32(_memory.Read32(sp + 0x88UL));
        _gpr[17] = SignExtend32(_memory.Read32(sp + 0x84UL));
        _gpr[16] = SignExtend32(_memory.Read32(sp + 0x80UL));
        _gpr[29] = sp + 0xa8UL;
        _gpr[0] = 0;
        AdvanceCp0Count(_cp0CountStep * 128UL);
        _instructionCounter += 128UL;
        _hasPendingBranch = false;
        _hasImmediatePcOverride = false;
        Pc = returnAddress;
        return true;
    }

    private bool TryFastPathKnownRuntimeTextDrawEntry(ulong pc)
    {
        const ulong entry = 0xffffffff800e3378UL;
        if (pc != entry)
            return false;
        if (_memory.Read32(entry + 0x00UL) != 0x27bdff58U ||
            _memory.Read32(entry + 0x04UL) != 0xafbe00a0U ||
            _memory.Read32(entry + 0x08UL) != 0x0080f02dU ||
            _memory.Read32(entry + 0x0cUL) != 0xafb60098U ||
            _memory.Read32(entry + 0x10UL) != 0x00a0b02dU ||
            _memory.Read32(entry + 0x14UL) != 0xafb00080U ||
            _memory.Read32(entry + 0x18UL) != 0x3c108022U ||
            _memory.Read32(entry + 0x20UL) != 0x2612d8f8U ||
            _memory.Read32(entry + 0x28UL) != 0x30e20003U ||
            _memory.Read32(entry + 0x2cUL) != 0xafbf00a4U ||
            _memory.Read32(entry + 0x64UL) != 0x0c038c26U ||
            _memory.Read32(entry + 0x6cUL) != 0x06c10005U ||
            _memory.Read32(0xffffffff800e3888UL) != 0x02a0102dU ||
            _memory.Read32(0xffffffff800e388cUL) != 0x8fbf00a4U ||
            _memory.Read32(0xffffffff800e38b4UL) != 0x03e00008U ||
            _memory.Read32(0xffffffff800e38b8UL) != 0x27bd00a8U)
        {
            return false;
        }

        ulong returnAddress = _gpr[31];
        ulong returnOffset = returnAddress & 0x1fffffffUL;
        if (returnOffset is < 0x000c0000UL or > 0x00110000UL)
            return false;

        ulong text = _gpr[6];
        int length = 0;
        if (text != 0)
        {
            for (; length < 512; length++)
            {
                if (_memory.Read8(text + (uint)length) == 0)
                    break;
            }
            if (length >= 512)
                return false;
        }

        _gpr[2] = (ulong)(uint)length;
        _gpr[0] = 0;
        AdvanceCp0Count(_cp0CountStep * (ulong)Math.Max(1, length + 16));
        _instructionCounter += (ulong)Math.Max(1, length + 16);
        _hasPendingBranch = false;
        _hasImmediatePcOverride = false;
        Pc = returnAddress;
        return true;
    }

