            _memory.Read32(delayPc) != 0x00000000U ||
            _memory.Read32(resumePc) != 0x8e22371cU ||
            _memory.Read32(callee + 0x00UL) != 0x3c04800aU ||
            _memory.Read32(callee + 0x04UL) != 0x3c05800aU ||
            _memory.Read32(callee + 0x08UL) != 0x8c8377ccU ||
