            _gpr[18] = SignExtend32(_memory.Read32(sp + 0x18UL));
            _gpr[17] = SignExtend32(_memory.Read32(sp + 0x14UL));
            _gpr[16] = SignExtend32(_memory.Read32(sp + 0x10UL));
            _gpr[29] = sp + 0x20UL;
