        ulong returnOffset = returnAddress & 0x1fffffffUL;
        if (returnOffset is < 0x000e0000UL or > 0x000e3000UL)
            return false;

        uint status = atEntry ? _memory.Read32(state + 0x18UL) : (uint)_gpr[2];
        if ((status & 0x80000000u) == 0)
