        ulong start = _gpr[4];
        if (!IsMainRamRange(start, 1))
            return false;

        uint length = 0;
        while (length < 0x10000U && IsMainRamRange(start + length, 1))
        {
            if (_memory.Read8(start + length) == 0)
                break;
            length++;
