    private void ApplyKnownRuntimeBgLoadModelAssetNameRepair(ulong pc)
    {
        if (!_enableRuntimeBgLoadModelAssetNameExperiment ||
            pc is not (0xffffffff800aacb4UL or 0xffffffff800aa958UL))
        {
            return;
        }

        const ulong assetTable = 0xffffffff8024f9a0UL;
        const ulong descriptorStride = 0x30UL;
        const uint repeatedStaticSource = 0x802e1718U;
        uint staticAliasSource = IsMainRamRange(assetTable, 4UL) ? _memory.Read32(assetTable) : repeatedStaticSource;

        int repaired = 0;
        for (ulong index = 1; index <= KnownRuntimeBgLoadModelTexturePayloadMaxIndex; index++)
        {
            ulong entry = assetTable + index * descriptorStride;
            ulong name = entry + 0x10UL;
            if (!IsMainRamRange(entry + 0x2fUL, 1))
                break;

            uint source = _memory.Read32(entry);
            uint distinctSource = unchecked((uint)(0x802e1718UL + index * (ulong)_runtimeBgLoadModelIndexedSourceStride));
            bool repairedStaticAliasSource = false;
            if (_enableRuntimeBgLoadModelAssetStaticAliasSourceRepair &&
                source == staticAliasSource &&
                source != distinctSource &&
                TryGetKnownRuntimeBgLoadModelTexturePayload(index, out _, out _, out _) &&
                IsMainRamRange(SignExtend32(distinctSource), 0x80UL) &&
                !IsKnownRuntimeBgLoadModelSourceWindowEmpty(SignExtend32(distinctSource)))
            {
                _memory.Write32(entry, distinctSource);
                source = distinctSource;
                repairedStaticAliasSource = true;
            }

            if (_memory.Read8(name) != 0)
                continue;
            if (source == repeatedStaticSource || source == distinctSource)
            {
                if (!TryGetKnownRuntimeBgLoadModelTexturePayload(index, out string code, out _, out _))
                    continue;

                WriteAsciiTraceString(name, code, 0x20);
                repaired++;
                if (repairedStaticAliasSource && _runtimeBgLoadModelKnownMissingTextureLookupTraceCount++ < 8)
                {
                    Console.WriteLine(
                        $"[GAUNTDL:FIX] bgloadmodel-asset-static-alias-source pc={pc:x16} " +
                        $"index={index} source={staticAliasSource:x8}->{distinctSource:x8} name={code}");
                }
                continue;
            }

            if (!TryGetKnownRuntimeBgLoadModelTexturePayloadForAssetSource(source, out string bodyCode))
                continue;

            WriteAsciiTraceString(name, bodyCode, 0x20);
            repaired++;
        }

        if (repaired > 0 && _runtimeBgLoadModelKnownMissingTextureLookupTraceCount++ < 8)
        {
            Console.WriteLine(
                $"[GAUNTDL:FIX] bgloadmodel-asset-name-repair pc={pc:x16} repaired={repaired} " +
                $"assetTable={TraceKnownRuntimeBgLoadModelAssetTableSummary(0)}");
        }
    }

    private void ApplyKnownRuntimeBgLoadModelTextureSetDistinctSource(ulong pc)
    {
        const ulong textureSetDescriptorLoadPc = 0xffffffff800aae3cUL;
        const ulong repeatedStaticSource = 0xffffffff802e1718UL;
        if (!_experimentRuntimeBgLoadModelTextureSetDistinctSource ||
            pc != textureSetDescriptorLoadPc ||
            _gpr[18] != repeatedStaticSource ||
            _gpr[16] is < 1UL or > 8UL)
        {
            return;
        }

        ulong index = _gpr[16];
        ulong distinctSource = repeatedStaticSource + index * (ulong)_runtimeBgLoadModelIndexedSourceStride;
        if (!TryGetKnownRuntimeBgLoadModelTexturePayload(index, out string code, out _, out _) ||
            !IsMainRamRange(distinctSource, 0x80UL) ||
            IsKnownRuntimeBgLoadModelSourceWindowEmpty(distinctSource))
        {
            return;
        }

        ulong oldSource = _gpr[18];
        _gpr[18] = distinctSource;
        _gpr[0] = 0;
        if (_runtimeBgLoadModelTextureSetDistinctSourceTraceCount++ < 32)
        {
            Console.WriteLine(
                $"[GAUNTDL:EXPERIMENT] bgloadmodel-texture-set-distinct-source pc={pc:x16} " +
                $"index={index} code={code} source={oldSource:x16}->{distinctSource:x16} " +
                $"tableIndex={ReadTraceWord(distinctSource + 0x60UL):x8} " +
                $"first={FormatTraceWords(distinctSource, 4)}");
        }
    }

    private void TraceKnownRuntimeTextureSetLookup(ulong pc)
    {
        const ulong textureSetLookupPc = 0xffffffff800a92a8UL;
        const ulong renderLookupReturnPc = 0xffffffff800b0800UL;
        const ulong sizeLookupReturnPc = 0xffffffff800a648cUL;
        const ulong textureSetTable = 0xffffffff802545a0UL;
        if (!_traceRuntimeTextureSetLookups ||
            pc is not (textureSetLookupPc or renderLookupReturnPc or sizeLookupReturnPc) ||
            _runtimeTextureSetLookupTraceCount >= _traceRuntimeTextureSetLookupsLimit)
        {
            return;
        }

        if (pc != textureSetLookupPc)
        {
            ulong returnedResult = CanonicalizeTraceAddress(_gpr[2]);
            ulong lookupCaller = _gpr[31];
            if (!_runtimeTextureSetLookupTraceKeys.Add((0xffffffffU, unchecked((uint)returnedResult), pc)))
                return;

            _runtimeTextureSetLookupTraceCount++;
            Console.WriteLine(
                $"[GAUNTDL:TRACE] runtime-texture-set-lookup n={_runtimeTextureSetLookupTraceCount} " +
                $"frame={_memory.VoodooRenderFrameCount} pc={pc:x16} phase=return " +
                $"result={returnedResult:x16} words={(IsMainRamRange(returnedResult, 0x50UL) ? FormatTraceWords(returnedResult, 20) : "-")} " +
                $"v1={_gpr[3]:x16} a0={_gpr[4]:x16} a1={_gpr[5]:x16} ra={lookupCaller:x16}");
            return;
        }

        uint packedIndex = (uint)_gpr[4];
        uint setIndex = packedIndex >> 16;
        uint recordIndex = packedIndex & 0xffffU;
        ulong setSlot = textureSetTable + setIndex * 4UL;
        uint setBase = IsMainRamRange(setSlot, 4UL) ? _memory.Read32(setSlot) : 0;
        ulong result = setBase == 0
            ? 0
            : SignExtend32(unchecked(setBase + recordIndex * 0x50U));
        ulong returnAddress = _gpr[31];
        if (!_runtimeTextureSetLookupTraceKeys.Add((packedIndex, setBase, returnAddress)))
            return;

        _runtimeTextureSetLookupTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:TRACE] runtime-texture-set-lookup n={_runtimeTextureSetLookupTraceCount} " +
            $"frame={_memory.VoodooRenderFrameCount} pc={pc:x16} packed={packedIndex:x8} " +
            $"set={setIndex} record={recordIndex} slot={setSlot:x16} base={setBase:x8} " +
            $"result={result:x16} words={(IsMainRamRange(result, 0x50UL) ? FormatTraceWords(result, 20) : "-")} " +
            $"ra={returnAddress:x16}");
    }

    private void TraceKnownRuntimeRecordListState(ulong pc)
    {
        const ulong listAdvancePc = 0xffffffff800b11d4UL;
        const ulong countAddress = 0xffffffff80228088UL;
        const ulong tableBase = 0xffffffff80255f20UL;
        const ulong recordStride = 0x50UL;
        if (!_traceRuntimeRecordScanAllocate || _runtimeRecordListStateTraced || pc != listAdvancePc)
            return;

        _runtimeRecordListStateTraced = true;
        uint recordCount = _memory.Read32(countAddress);
        uint dumpCount = Math.Min(recordCount, 16U);
        Console.WriteLine(
            $"[GAUNTDL:TRACE] record-list-state pc={pc:x16} count={recordCount} dump={dumpCount} " +
            $"head={_gpr[16]:x16} ra={_gpr[31]:x16} " +
            $"allocator={TraceKnownRuntimeBgLoadModelLookupGlobals()}");
        for (uint index = 0; index < dumpCount; index++)
        {
            ulong record = tableBase + index * recordStride;
            Console.WriteLine(
                $"[GAUNTDL:TRACE] record-list-state index={index} record={record:x16} " +
                $"words={FormatTraceWords(record, 20)}");
        }
    }

    private void TraceKnownRuntimeWorldTextureSelectorCall(ulong pc)
    {
        const ulong primaryCallPc = 0xffffffff800a761cUL;
        const ulong primaryReturnPc = 0xffffffff800a7624UL;
        const ulong secondaryCallPc = 0xffffffff800a7764UL;
        const ulong secondaryReturnPc = 0xffffffff800a776cUL;
        if (!_traceRuntimeWorldTextureSelectorCalls ||
            pc is not (primaryCallPc or primaryReturnPc or secondaryCallPc or secondaryReturnPc) ||
            _runtimeWorldTextureSelectorCallTraceCount >= _traceRuntimeWorldTextureSelectorCallsLimit)
        {
            return;
        }

        uint selector = (uint)_gpr[5];
        ulong record = CanonicalizeTraceAddress(_gpr[18]);
        ulong stack = _gpr[29];
        ulong output = stack + 0x10UL;
        uint source = ReadTraceWord(output + 0x10UL);
        uint loopIndex = ReadTraceWord(stack + 0x28UL);
        uint recordNext = ReadTraceWord(record + 0x0cUL);
        uint recordStatus = ReadTraceWord(record + 0x10UL);
        uint recordSelector = ReadTraceWord(record + 0x1cUL);
        if (_traceTextureUploadRunSource.HasValue &&
            SignExtend32(source) != CanonicalizeTraceAddress(_traceTextureUploadRunSource.Value))
        {
            return;
        }
        if (!_runtimeWorldTextureSelectorCallTraceKeys.Add((pc, selector, record, source)))
            return;

        bool primary = pc is primaryCallPc or primaryReturnPc;
        bool returned = pc is primaryReturnPc or secondaryReturnPc;
        _runtimeWorldTextureSelectorCallTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:TRACE] runtime-world-texture-selector-call n={_runtimeWorldTextureSelectorCallTraceCount} " +
            $"frame={_memory.VoodooRenderFrameCount} pc={pc:x16} ra={_gpr[31]:x16} " +
            $"kind={(primary ? "primary" : "secondary")} phase={(returned ? "return" : "call")} selector={selector:x8} " +
            $"a0={_gpr[4]:x16} a2={_gpr[6]:x16} a3={_gpr[7]:x16} " +
            $"s0={_gpr[16]:x16} s1={_gpr[17]:x16} record={record:x16} s3={_gpr[19]:x16} " +
            $"recordNext={recordNext:x8} recordStatus={recordStatus:x8} recordSelector={recordSelector:x8} " +
                $"recordWords={FormatTraceWords(record, 16)} info={output:x16}:{FormatTraceWords(output, 6)} loopIndex={loopIndex:x8}");
    }

