    private void TraceKnownRuntimeWorldTextureUploadBounds(ulong pc)
    {
        const ulong outerEntryPc = 0xffffffff800a7110UL;
        const ulong aspectBuilderPc = 0xffffffff800a731cUL;
        const ulong drawStateBuiltPc = 0xffffffff800bd180UL;
        const ulong entryPc = 0xffffffff801094f4UL;
        const ulong preparedPc = 0xffffffff8010953cUL;
        const ulong emitterPc = 0xffffffff801096acUL;
        const ulong emitterTablePc = 0xffffffff801096f4UL;
        const ulong lowLevelEntryPc = 0xffffffff800fe1fcUL;
        const ulong lowLevelTablePc = 0xffffffff800fe30cUL;
        const ulong lowLevelGeometryPc = 0xffffffff800fe460UL;
        const ulong lowLevelPacketPc = 0xffffffff800fe5e8UL;
        bool traceDrawState = _traceRuntimeWorldTextureUploadToDraw && pc == drawStateBuiltPc;
        bool traceUploadBounds = _traceRuntimeWorldTextureUploadBounds &&
            pc is (outerEntryPc or aspectBuilderPc or entryPc or preparedPc or emitterPc or emitterTablePc or lowLevelEntryPc or lowLevelTablePc or lowLevelGeometryPc or lowLevelPacketPc);
        if (!traceDrawState && !traceUploadBounds)
        {
            return;
        }

        if (pc == drawStateBuiltPc)
        {
            ulong record = CanonicalizeTraceAddress(_gpr[18]);
            if (record != 0xffffffff802e2158UL || _runtimeWorldTextureDrawStateTraceCount >= 32)
                return;

            ulong owner = CanonicalizeTraceAddress(_gpr[20]);
            _runtimeWorldTextureDrawStateTraceCount++;
            Console.WriteLine(
                $"[GAUNTDL:TRACE] runtime-world-texture-upload-to-draw n={_runtimeWorldTextureDrawStateTraceCount} " +
                $"frame={_memory.VoodooRenderFrameCount} pc={pc:x16} ra={_gpr[31]:x16} " +
                $"record={record:x16}:{FormatTraceWords(record, 8)} owner={owner:x16} " +
                $"ownerLodBias={ReadTraceWord(owner + 0x144UL):x8} globalMode={ReadTraceWord(0xffffffff80162cb4UL):x8} " +
                $"inputMode={_gpr[6]:x16} inputBaseShift={_gpr[7]:x16} " +
                $"builtMode={_gpr[16]:x16} builtLod={_gpr[21]:x16} stateOwner={_gpr[17]:x16}");
            return;
        }

        if (pc == outerEntryPc)
        {
            ulong record = CanonicalizeTraceAddress(_gpr[4]);
            if (record != 0xffffffff802e2158UL || _runtimeWorldTextureUploadBoundsTraceCount >= 64)
                return;

            ulong stack = CanonicalizeTraceAddress(_gpr[29]);
            _runtimeWorldTextureUploadBoundsTraceCount++;
            Console.WriteLine(
                $"[GAUNTDL:TRACE] runtime-world-texture-upload-bounds n={_runtimeWorldTextureUploadBoundsTraceCount} " +
                $"frame={_memory.VoodooRenderFrameCount} phase=outer-entry pc={pc:x16} ra={_gpr[31]:x16} " +
                $"a0={_gpr[4]:x16} a1={_gpr[5]:x16} a2={_gpr[6]:x16} a3={_gpr[7]:x16} " +
                $"record={record:x16}:{FormatTraceWords(record, 16)} " +
                $"callerS1={ReadTraceWord(stack + 0x44UL):x8} callerS3={ReadTraceWord(stack + 0x4cUL):x8} " +
                $"callerS4={ReadTraceWord(stack + 0x50UL):x8} callerFp={ReadTraceWord(stack + 0x60UL):x8} " +
                $"sp={stack:x16}");
            return;
        }

        if (pc == aspectBuilderPc)
        {
            if (_runtimeWorldTextureUploadBoundsTraceCount >= 64)
                return;

            ulong aspectInfo = CanonicalizeTraceAddress(_gpr[29] + 0x10UL);
            ulong record = CanonicalizeTraceAddress(_gpr[18]);
            if (!IsMainRamRange(aspectInfo, 0x14UL) || !IsMainRamRange(record, 0x0cUL))
                return;

            uint aspectSource = ReadTraceWord(record + 0x08UL);
            if (_traceTextureUploadRunSource.HasValue && record != 0xffffffff802e2158UL)
            {
                return;
            }

            _runtimeWorldTextureUploadBoundsTraceCount++;
            Console.WriteLine(
                $"[GAUNTDL:TRACE] runtime-world-texture-upload-bounds n={_runtimeWorldTextureUploadBoundsTraceCount} " +
                $"frame={_memory.VoodooRenderFrameCount} phase=aspect-builder pc={pc:x16} " +
                $"record={record:x16}:{FormatTraceWords(record, 5)} " +
                $"packedDimensions={ReadTraceWord(record + 0x04UL):x8} source={aspectSource:x8} " +
                $"info={aspectInfo:x16}:{FormatTraceWords(aspectInfo, 5)} v0={_gpr[2]:x16} v1={_gpr[3]:x16} " +
                $"a2={_gpr[6]:x16} ra={_gpr[31]:x16}");
            return;
        }

        if (pc is lowLevelEntryPc or lowLevelTablePc or lowLevelGeometryPc or lowLevelPacketPc)
        {
            if (_runtimeWorldTextureUploadLowLevelTraceCount >= 128)
                return;

            ulong stack = CanonicalizeTraceAddress(_gpr[29]);
            ulong sourceAddress = stack + (pc == lowLevelEntryPc ? 0x1cUL : 0x6cUL);
            ulong limitAddress = stack + (pc == lowLevelEntryPc ? 0x24UL : 0x74UL);
            if (!IsMainRamRange(sourceAddress, 4UL) || !IsMainRamRange(limitAddress, 4UL))
                return;

            uint lowLevelSource = ReadTraceWord(sourceAddress);
            uint limit = ReadTraceWord(limitAddress);
            if (_traceTextureUploadRunSource.HasValue &&
                SignExtend32(lowLevelSource) != CanonicalizeTraceAddress(_traceTextureUploadRunSource.Value))
            {
                return;
            }

            if (pc == lowLevelPacketPc &&
                (uint)_gpr[18] != limit &&
                ((uint)_gpr[18] & 0x1fU) != 0)
            {
                return;
            }

            string phase = pc switch
            {
                lowLevelEntryPc => "low-entry",
                lowLevelTablePc => "low-table",
                lowLevelGeometryPc => "low-geometry",
                _ => "low-packet"
            };
            _runtimeWorldTextureUploadLowLevelTraceCount++;
            Console.WriteLine(
                $"[GAUNTDL:TRACE] runtime-world-texture-upload-bounds-low n={_runtimeWorldTextureUploadLowLevelTraceCount} " +
                $"frame={_memory.VoodooRenderFrameCount} phase={phase} pc={pc:x16} " +
                $"source={lowLevelSource:x8} limit={limit:x8} a0={_gpr[4]:x16} a1={_gpr[5]:x16} " +
                $"a2={_gpr[6]:x16} a3={_gpr[7]:x16} s0={_gpr[16]:x16} s1={_gpr[17]:x16} " +
                $"s2={_gpr[18]:x16} s3={_gpr[19]:x16} s4={_gpr[20]:x16} s5={_gpr[21]:x16} " +
                $"s6={_gpr[22]:x16} s7={_gpr[23]:x16} t0={_gpr[8]:x16} t1={_gpr[9]:x16} " +
                $"t2={_gpr[10]:x16} t3={_gpr[11]:x16} sp={stack:x16} ra={_gpr[31]:x16}");
            return;
        }

        if (_runtimeWorldTextureUploadBoundsTraceCount >= 64)
            return;

        if (pc == emitterTablePc)
        {
            ulong stack = CanonicalizeTraceAddress(_gpr[29]);
            if (!IsMainRamRange(stack + 0x4cUL, 4UL))
                return;

            uint stackArg0 = ReadTraceWord(stack + 0x40UL);
            uint emitterSource = ReadTraceWord(stack + 0x1cUL);
            if (_traceTextureUploadRunSource.HasValue &&
                SignExtend32(emitterSource) != CanonicalizeTraceAddress(_traceTextureUploadRunSource.Value))
            {
                return;
            }

            ulong tableEntry = 0xffffffff80158050UL +
                4UL * (9UL * stackArg0 + (uint)_gpr[6]);
            _runtimeWorldTextureUploadBoundsTraceCount++;
            Console.WriteLine(
                $"[GAUNTDL:TRACE] runtime-world-texture-upload-bounds n={_runtimeWorldTextureUploadBoundsTraceCount} " +
                $"frame={_memory.VoodooRenderFrameCount} phase=emitter-table pc={pc:x16} " +
                $"source={emitterSource:x8} table={tableEntry:x16}:{FormatTraceWords(tableEntry, 2)} " +
                $"loadedSecond={_gpr[2]:x16} limit={unchecked((uint)_gpr[2] - 1U):x8} " +
                $"a0={_gpr[4]:x16} a1={_gpr[5]:x16} a2={_gpr[6]:x16} a3={_gpr[7]:x16} " +
                $"sp={stack:x16} ra={_gpr[31]:x16}");
            return;
        }

        if (pc == emitterPc)
        {
            ulong stack = CanonicalizeTraceAddress(_gpr[29]);
            if (!IsMainRamRange(stack + 0x1cUL, 4UL))
                return;

            uint stackArg0 = ReadTraceWord(stack + 0x10UL);
            uint stackArg1 = ReadTraceWord(stack + 0x14UL);
            uint stackArg2 = ReadTraceWord(stack + 0x18UL);
            uint emitterSource = ReadTraceWord(stack + 0x1cUL);
            if (_traceTextureUploadRunSource.HasValue &&
                SignExtend32(emitterSource) != CanonicalizeTraceAddress(_traceTextureUploadRunSource.Value))
            {
                return;
            }

            ulong tableEntry = 0xffffffff80158050UL +
                4UL * (9UL * stackArg0 + (uint)_gpr[6]);
            _runtimeWorldTextureUploadBoundsTraceCount++;
            Console.WriteLine(
                $"[GAUNTDL:TRACE] runtime-world-texture-upload-bounds n={_runtimeWorldTextureUploadBoundsTraceCount} " +
                $"frame={_memory.VoodooRenderFrameCount} phase=emitter pc={pc:x16} " +
                $"a0={_gpr[4]:x16} a1={_gpr[5]:x16} a2={_gpr[6]:x16} a3={_gpr[7]:x16} " +
                $"stack={stack:x16}:{stackArg0:x8}/{stackArg1:x8}/{stackArg2:x8}/{emitterSource:x8} " +
                $"table={tableEntry:x16}:{FormatTraceWords(tableEntry, 2)} ra={_gpr[31]:x16}");
            return;
        }

        ulong info = CanonicalizeTraceAddress(pc == entryPc ? _gpr[7] : _gpr[19]);
        if (!IsMainRamRange(info, 0x18UL))
            return;

        uint source = ReadTraceWord(info + 0x10UL);
        if (_traceTextureUploadRunSource.HasValue &&
            SignExtend32(source) != CanonicalizeTraceAddress(_traceTextureUploadRunSource.Value))
        {
            return;
        }

        _runtimeWorldTextureUploadBoundsTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:TRACE] runtime-world-texture-upload-bounds n={_runtimeWorldTextureUploadBoundsTraceCount} " +
            $"frame={_memory.VoodooRenderFrameCount} phase={(pc == entryPc ? "entry" : "prepared")} " +
            $"pc={pc:x16} info={info:x16}:{FormatTraceWords(info, 6)} " +
            $"a0={_gpr[4]:x16} a1={_gpr[5]:x16} a2={_gpr[6]:x16} a3={_gpr[7]:x16} " +
            $"s0={_gpr[16]:x16} s1={_gpr[17]:x16} s2={_gpr[18]:x16} s3={_gpr[19]:x16} ra={_gpr[31]:x16}");
    }

    private void WriteAsciiTraceString(ulong address, string text, int maxLength)
    {
        if (!IsMainRamRange(address, (ulong)maxLength))
            return;

        int length = Math.Min(text.Length, Math.Max(0, maxLength - 1));
        for (int i = 0; i < length; i++)
            _memory.Write8(address + (ulong)i, (byte)text[i]);
        _memory.Write8(address + (ulong)length, 0);
    }

    private bool TryGetKnownRuntimeBgLoadModelTexturePayloadForAssetSource(
        uint source,
        out string code)
    {
        code = "";
        const ulong destinationBase = 0xffffffff802e1718UL;
        ulong sourceStride = (ulong)_runtimeBgLoadModelIndexedSourceStride;

        for (ulong index = 1; index <= KnownRuntimeBgLoadModelTexturePayloadMaxIndex; index++)
        {
            ulong sourceBase = destinationBase + index * sourceStride;
            if (!IsMainRamRange(sourceBase + 0x5cUL, 4UL))
                continue;

            uint bodyOffset = _memory.Read32(sourceBase + 0x5cUL);
            if (bodyOffset == 0)
                continue;

            ulong body = sourceBase + bodyOffset;
            if ((uint)body != source)
                continue;

            return TryGetKnownRuntimeBgLoadModelTexturePayload(index, out code, out _, out _);
        }

        return false;
    }

    private void ApplyKnownRuntimeBgLoadModelPreserveAssetSource(ulong pc)
    {
        if (_runtimeBgLoadModelPreserveAssetSourceIndexMask == 0 ||
            pc is not (0xffffffff800aae60UL or 0xffffffff800aae98UL))
        {
            return;
        }

        ulong index = _gpr[16] & 0xffffffffUL;
        if (index is 0 or >= 64UL ||
            (_runtimeBgLoadModelPreserveAssetSourceIndexMask & (1UL << (int)index)) == 0)
        {
            return;
        }

        const ulong assetTable = 0xffffffff8024f9a0UL;
        const ulong assetStride = 0x30UL;
        const ulong sourceTable = 0xffffffff802529a0UL;

        ulong assetEntry = assetTable + index * assetStride;
        ulong sourceSlot = sourceTable + index * 4UL;
        if (!IsMainRamRange(assetEntry + 0x2fUL, 1) ||
            !IsMainRamRange(sourceSlot, 4))
        {
            return;
        }

        uint assetSource = _memory.Read32(assetEntry);
        uint assetLength = _memory.Read32(assetEntry + 0x04UL);
        ulong assetSourceAddress = SignExtend32(assetSource);
        if (assetSource == 0 ||
            assetLength == 0 ||
            !IsMainRamRange(assetSourceAddress, 0x80UL))
        {
            return;
        }

        uint oldSlot = _memory.Read32(sourceSlot);
        if (oldSlot == assetSource && _gpr[18] == assetSourceAddress)
            return;

        _memory.Write32(sourceSlot, assetSource);
        _gpr[18] = assetSourceAddress;

        if (_runtimeBgLoadModelPreserveAssetSourceTraceCount++ < 16)
        {
            Console.WriteLine(
                $"[GAUNTDL:EXPERIMENT] bgloadmodel-preserve-asset-source pc={pc:x16} " +
                $"index={index} slot={sourceSlot:x16}:{oldSlot:x8}->{assetSource:x8} " +
                $"asset={assetEntry:x16}:{assetSource:x8}/{assetLength:x8}/" +
                $"{_memory.Read32(assetEntry + 0x08UL):x8}/\"{ReadAsciiTraceString(assetEntry + 0x10UL, 24)}\" " +
                $"s2={_gpr[18]:x16} sourceWords={TraceKnownRuntimeBgLoadModelAssetParserWords(assetSourceAddress)}");
        }
    }

    private void ApplyKnownRuntimeBgLoadModelDistinctSourcesRepair(ulong pc)
    {
        if ((!_enableRuntimeBgLoadModelDistinctSourcesExperiment &&
             !_enableRuntimeBgLoadModelIndexedSourceHeadersRepair &&
             !_enableRuntimeBgLoadModelPartialIndexedSourcePayloadsRepair) ||
            pc is not (0xffffffff800aadf0UL or 0xffffffff800aae98UL or 0xffffffff800aac48UL))
        {
            return;
        }

        const ulong sourceTable = 0xffffffff802529a0UL;
        const uint staticSource = 0x802e1718U;
        ulong index = _gpr[16] & 0xffffffffUL;
        if (index is 0 || index > KnownRuntimeBgLoadModelTexturePayloadMaxIndex)
            return;

        ulong slot = sourceTable + index * 4UL;
        ulong source = 0xffffffff802e1718UL + index * (ulong)_runtimeBgLoadModelIndexedSourceStride;
        if (!IsMainRamRange(slot, 4) || !IsMainRamRange(source, 0x80))
            return;

        uint current = _memory.Read32(slot);
        bool overwriteAllowsIndex = index < 64UL &&
            (_runtimeBgLoadModelOverwriteIndexedSourceMask & (1UL << (int)index)) != 0;
        if (current != 0 && current != staticSource && !overwriteAllowsIndex)
            return;

        bool seededIndexedHeader = TrySeedKnownRuntimeBgLoadModelDistinctSourceIndexedHeader(index, source);
        if ((_enableRuntimeBgLoadModelIndexedSourceHeadersRepair ||
             _enableRuntimeBgLoadModelPartialIndexedSourcePayloadsRepair) &&
            !seededIndexedHeader)
            return;

        _memory.Write32(slot, (uint)source);
        bool clonedSource = !seededIndexedHeader && TryCloneKnownRuntimeBgLoadModelStaticSourceToDistinctSource(source);
        _gpr[18] = source;
