    private bool TrySeedKnownRuntimeBgLoadModelDistinctSourceIndexedHeader(ulong index, ulong destination)
    {
        bool indexedHeaderEnabled = _enableRuntimeBgLoadModelDistinctSourceIndexedHeaderExperiment ||
                                    _enableRuntimeBgLoadModelIndexedSourceHeadersRepair ||
                                    _enableRuntimeBgLoadModelPartialIndexedSourcePayloadsRepair;
        bool indexedTexturePayloadEnabled = _enableRuntimeBgLoadModelIndexedTextureQioExperiment ||
                                            _enableRuntimeBgLoadModelIndexedSourceHeadersRepair ||
                                            _enableRuntimeBgLoadModelPartialIndexedSourcePayloadsRepair;
        bool partialSeedabilityEnabled = _enableRuntimeBgLoadModelPartialIndexedSourceHeadersExperiment ||
                                         _enableRuntimeBgLoadModelPartialIndexedSourcePayloadsRepair;
        uint requestedBytes = 0x120U;
        if (_runtimeBgLoadModelIndexedSourcePayloadBytesOverride.HasValue)
        {
            requestedBytes = (uint)Math.Min(_runtimeBgLoadModelIndexedSourcePayloadBytesOverride.Value, uint.MaxValue);
        }
        else if (_enableRuntimeBgLoadModelFullIndexedSourcePayloadsExperiment &&
            TryGetKnownRuntimeBgLoadModelTexturePayload(index, out _, out _, out uint textureByteLength))
        {
            requestedBytes = textureByteLength;
        }
        else if (partialSeedabilityEnabled ||
                 _enableRuntimeBgLoadModelMinimumIndexedSourcePayloadExperiment)
        {
            requestedBytes = 0x9f60U;
        }

        ulong indexedHeaderMask = _runtimeBgLoadModelDistinctSourceIndexedHeaderMask ??
            (_enableRuntimeBgLoadModelPartialIndexedSourcePayloadsRepair ? 0x2UL : ulong.MaxValue);
        bool maskAllowsIndex = (indexedHeaderMask & (1UL << (int)index)) != 0;
        bool sourceSeedable = partialSeedabilityEnabled
            ? IsKnownRuntimeBgLoadModelIndexedSourceHeaderSeedable(destination)
            : IsKnownRuntimeBgLoadModelSourceWindowEmpty(destination);
        bool overwriteAllowsIndex = (_runtimeBgLoadModelOverwriteIndexedSourceMask & (1UL << (int)index)) != 0;
        bool overlapZeroFillAllowsIndex = (_runtimeBgLoadModelOverlapZeroFillIndexedSourceMask & (1UL << (int)index)) != 0;
        if (!indexedHeaderEnabled ||
            !indexedTexturePayloadEnabled ||
            !maskAllowsIndex)
        {
            TraceKnownRuntimeBgLoadModelIndexedSourceHydration(
                "distinct-source-skip",
                index,
                destination,
                requestedBytes,
                $"indexedHeader={indexedHeaderEnabled} texturePayload={indexedTexturePayloadEnabled} " +
                $"mask={maskAllowsIndex} seedable={sourceSeedable} overwrite={overwriteAllowsIndex} " +
                $"overlapZeroFill={overlapZeroFillAllowsIndex} partial={partialSeedabilityEnabled}");
            return false;
        }

        if (!sourceSeedable && !overwriteAllowsIndex)
        {
            if (overlapZeroFillAllowsIndex &&
                TryHydrateKnownRuntimeBgLoadModelIndexedTextureSourceZeroFill(
                    index,
                    destination,
                    requestedBytes,
                    out string zeroFillCode,
                    out ulong zeroFillTextureByteOffset,
                    out uint zeroFillFirstWord,
                    out uint zeroFilledBytes,
                    out uint zeroFillFirstOffset))
            {
                TraceKnownRuntimeBgLoadModelIndexedSourceHydration(
                    "distinct-source-overlap-zero-fill",
                    index,
                    destination,
                    requestedBytes,
                    $"code={zeroFillCode} disk={zeroFillTextureByteOffset:x8} first={zeroFillFirstWord:x8} " +
                    $"filledBytes={zeroFilledBytes:x8} firstFilledOffset={zeroFillFirstOffset:x8} " +
                    $"minOffset={_runtimeBgLoadModelOverlapZeroFillIndexedSourceMinOffset:x}");
                return true;
            }

            TraceKnownRuntimeBgLoadModelIndexedSourceHydration(
                "distinct-source-skip",
                index,
                destination,
                requestedBytes,
                $"indexedHeader={indexedHeaderEnabled} texturePayload={indexedTexturePayloadEnabled} " +
                $"mask={maskAllowsIndex} seedable={sourceSeedable} overwrite={overwriteAllowsIndex} " +
                $"overlapZeroFill={overlapZeroFillAllowsIndex} partial={partialSeedabilityEnabled}");
            return false;
        }

        if (!TryHydrateKnownRuntimeBgLoadModelIndexedTextureSource(
            index,
            destination,
            requestedBytes,
            out string code,
            out ulong textureByteOffset,
            out uint firstWord))
        {
            TraceKnownRuntimeBgLoadModelIndexedSourceHydration(
                "distinct-source-hydrate-fail",
                index,
                destination,
                requestedBytes,
                "payload-read-failed");
            return false;
        }

        TraceKnownRuntimeBgLoadModelIndexedSourceHydration(
            "distinct-source-hydrate",
            index,
            destination,
            requestedBytes,
            $"code={code} disk={textureByteOffset:x8} first={firstWord:x8} overwrite={overwriteAllowsIndex && !sourceSeedable}");

        if (_runtimeBgLoadModelDistinctSourceIndexedHeaderTraceCount++ < 16)
        {
            string traceKind = (_enableRuntimeBgLoadModelIndexedSourceHeadersRepair ||
                                _enableRuntimeBgLoadModelPartialIndexedSourcePayloadsRepair)
                ? "FIX"
                : "EXPERIMENT";
            Console.WriteLine(
                $"[GAUNTDL:{traceKind}] bgloadmodel-distinct-source-indexed-header " +
                $"index={index} code={code} dest={destination:x16} bytes={requestedBytes:x8} " +
                $"disk={textureByteOffset:x8} first={firstWord:x8} mask={indexedHeaderMask:x} " +
                $"sourceWords={TraceKnownRuntimeBgLoadModelAssetParserWords(destination)}");
        }

        if (index == 6)
            TraceKnownRuntimeBgLoadModelGebSourceState(0, "after-indexed-header");

        return true;
    }

    private bool TryCloneKnownRuntimeBgLoadModelStaticSourceToDistinctSource(ulong destination)
    {
        const ulong staticSource = 0xffffffff802e1718UL;
        const uint sourceBytes = 0x2000U;

        if (!_enableRuntimeBgLoadModelCloneDistinctSourcesExperiment ||
            destination == staticSource ||
            !IsMainRamRange(staticSource, sourceBytes) ||
            !IsMainRamRange(destination, sourceBytes) ||
            _memory.Read32(staticSource) == 0 ||
            _memory.Read32(destination) != 0)
        {
            return false;
        }

        for (uint offset = 0; offset < sourceBytes; offset++)
            _memory.Write8(destination + offset, _memory.Read8(staticSource + offset));

        return true;
    }

    private bool TryFastPathKnownRuntimeBgLoadModelKnownMissingTextureCallerLoop(ulong pc)
    {
        const ulong loop = 0xffffffff800aa958UL;
        const ulong exitTest = 0xffffffff800aa98cUL;
        const ulong fixedStringCompare30 = 0xffffffff800aa898UL;
        bool afterEmptyLookupMiss = pc == loop + 0x1cUL;
        if ((!_enableRuntimeBgLoadModelDispatchFastPath && !_enableRuntimeBgLoadModelExperimentalSkips) ||
            (pc != loop && !afterEmptyLookupMiss))
            return false;

        if (_memory.Read32(loop - 0x28UL) != 0x0271102aU ||
            _memory.Read32(loop - 0x24UL) != 0x14400015U ||
            _memory.Read32(loop - 0x20UL) != 0x3c02800bU ||
            _memory.Read32(loop - 0x1cUL) != 0x2455a898U ||
            _memory.Read32(loop + 0x00UL) != 0x27a40018U ||
            _memory.Read32(loop + 0x04UL) != 0xafb50010U ||
            _memory.Read32(loop + 0x08UL) != 0x8e050000U ||
            _memory.Read32(loop + 0x0cUL) != 0x8e060004U ||
            _memory.Read32(loop + 0x10UL) != 0x0c046d84U ||
            _memory.Read32(loop + 0x14UL) != 0x24070024U ||
            _memory.Read32(loop + 0x18UL) != 0x0040902dU ||
            _memory.Read32(loop + 0x1cUL) != 0x1640001bU ||
            _memory.Read32(loop + 0x24UL) != 0x26310001U ||
            _memory.Read32(loop + 0x28UL) != 0x0271102aU ||
            _memory.Read32(loop + 0x2cUL) != 0x1040fff4U ||
