            $"out10={ReadTraceWord(output + 0x10UL):x8} out18={ReadTraceWord(output + 0x18UL):x8} " +
            $"b171={ReadTraceByte(0xffffffff802171b0UL):x2}/{ReadTraceByte(0xffffffff802171b1UL):x2}/{ReadTraceByte(0xffffffff802171b2UL):x2}");
    }

    private void CaptureKnownRuntimeBgLoadModelIndexedTextureQioBodyReadRequest(ulong pc)
    {
        const ulong requestCreateObjectPc = 0xffffffff800c9678UL;
        const ulong qio = 0xffffffff80217c58UL;
        const uint requestedBytes = 0x2000U;
        const uint callback = 0x800ab4e4U;
        const uint pendingStatus = 0xffffffffU;

        if (!_enableRuntimeBgLoadModelIndexedTextureQioExperiment ||
            !_enableRuntimeBgLoadModelIndexedTextureQioBodyReadExperiment ||
            pc != requestCreateObjectPc ||
            _gpr[16] != requestedBytes ||
            _gpr[17] == 0x188d2303UL)
        {
            return;
        }

        ulong returnSlot = _gpr[30] + 0x20UL;
        if (!IsMainRamRange(returnSlot, 4) ||
            _memory.Read32(returnSlot) != unchecked((uint)qio) ||
            !IsMainRamRange(qio + 0x18UL, 0x40UL) ||
            _memory.Read32(qio + 0x04UL) != callback ||
            _memory.Read32(qio + 0x0cUL) == 0 ||
            _memory.Read32(qio + 0x14UL) != pendingStatus)
        {
            return;
        }

        // The previous QIO destination still points at the short-read source.
        // The guest publishes the body-read output cursor at fp+0x28 before
        // the create helper clears it, so capture that request-owned address.
        ulong outputCursorSlot = _gpr[30] + 0x28UL;
        ulong destination = IsMainRamRange(outputCursorSlot, 4)
            ? SignExtend32(_memory.Read32(outputCursorSlot))
            : 0;
        if (!IsMainRamRange(destination, requestedBytes))
        {
            return;
        }

        ulong fileOffset = _gpr[17];
        if (fileOffset == 0 || fileOffset > 0x01000000UL)
        {
            return;
        }

        _runtimeBgLoadModelPendingIndexedTextureBodyDestination = destination;
        _runtimeBgLoadModelPendingIndexedTextureBodyIndex = _gpr[18];
        _runtimeBgLoadModelPendingIndexedTextureBodyRequestKey = fileOffset;
    }

    private bool TryApplyKnownRuntimeBgLoadModelIndexedTextureQioShortReadRepair(ulong pc)
    {
        const ulong qio = 0xffffffff80217c58UL;
        const ulong destinationBase = 0xffffffff802e1718UL;
        ulong sourceStride = (ulong)_runtimeBgLoadModelIndexedSourceStride;
        const uint requestedBytes = 0x120U;
        const uint callback = 0x800ab4e4U;
        const uint objectStatus = 0x300bU;
        const uint qioCompleteStatus = 2;

        if (!_enableRuntimeBgLoadModelIndexedTextureQioExperiment ||
            !_enableRuntimeBgLoadModelIndexedTextureQioShortReadExperiment ||
            _gpr[16] != requestedBytes ||
            _gpr[17] != requestedBytes ||
            (_gpr[18] < 3UL || _gpr[18] > KnownRuntimeBgLoadModelTexturePayloadMaxIndex))
        {
            return false;
        }

        ulong returnSlot = _gpr[30] + 0x20UL;
        ulong qioObject = _gpr[4];
        if (!IsMainRamRange(returnSlot, 4) ||
            _memory.Read32(returnSlot) != unchecked((uint)qio) ||
            !IsMainRamRange(qio + 0x18UL, 0x40UL) ||
            !IsMainRamRange(qioObject + 0x14UL, 4))
        {
            return false;
        }

        if (_memory.Read32(qio + 0x00UL) != 0 ||
            _memory.Read32(qio + 0x04UL) != 0 ||
            _memory.Read32(qio + 0x08UL) != 0 ||
            _memory.Read32(qio + 0x0cUL) != 0 ||
            _memory.Read32(qio + 0x10UL) != 0 ||
            _memory.Read32(qio + 0x14UL) != qioCompleteStatus)
        {
            return false;
        }

        ulong index = _gpr[18];
        ulong destination = destinationBase + index * sourceStride;
        uint hydratedBytes = (uint)Math.Clamp(
            ParseOptionalHexUlong("EUTHERDRIVE_GAUNTDL_EXPERIMENT_RUNTIME_BGLOADMODEL_INDEXED_TEXTURE_QIO_SHORT_READ_HYDRATE_BYTES") ?? requestedBytes,
            requestedBytes,
            sourceStride);
        if (!IsMainRamRange(destination, requestedBytes) ||
            !IsKnownRuntimeBgLoadModelSourceWindowEmpty(destination) ||
            !TryHydrateKnownRuntimeBgLoadModelIndexedTextureSource(index, destination, hydratedBytes, out string code, out ulong textureByteOffset, out uint firstWord))
        {
            return false;
        }

        bool assignedSourceOwner = TryAssignKnownRuntimeBgLoadModelHydratedSourceOwner(
            index,
            destination,
            out ulong sourceOwnerSlot,
            out uint oldSourceOwner,
            out _);

        _memory.Write32(qio + 0x00UL, unchecked((uint)qioObject));
        _memory.Write32(qio + 0x04UL, callback);
        _memory.Write32(qio + 0x08UL, unchecked((uint)destination));
        _memory.Write32(qio + 0x0cUL, requestedBytes);
        _memory.Write32(qio + 0x10UL, requestedBytes);
        _memory.Write32(qio + 0x14UL, qioCompleteStatus);

        uint oldObjectStatus = _memory.Read32(qioObject + 0x14UL);
        _memory.Write32(qioObject + 0x14UL, (oldObjectStatus & 0xffff0000U) | objectStatus);
        EnsureKnownRuntimeBgLoadModelIndexedTextureQioObjectMetadata(pc, qioObject, "short-read");
        int filledRemaining = 0;
        if (_enableRuntimeBgLoadModelIndexedTextureQioShortReadFillRemainingExperiment)
            filledRemaining = HydrateKnownRuntimeBgLoadModelRemainingIndexedTextureSources(requestedBytes, sourceStride: sourceStride);

        if (_runtimeBgLoadModelIndexedTextureQioShortReadTraceCount++ < 16)
        {
            Console.WriteLine(
                $"[GAUNTDL:EXPERIMENT] bgloadmodel-indexed-texture-qio-short-read pc={pc:x16} " +
                $"index={index} code={code} qio={qio:x16} object={qioObject:x16} " +
                $"dest={destination:x16} bytes={requestedBytes:x8} hydrated={hydratedBytes:x8} disk={textureByteOffset:x8} " +
                $"first={firstWord:x8} fillRemaining={filledRemaining} objectStatus={oldObjectStatus:x8}->{_memory.Read32(qioObject + 0x14UL):x8} " +
                $"sourceOwner={(assignedSourceOwner ? $"{sourceOwnerSlot:x16}:{oldSourceOwner:x8}->{(uint)destination:x8}" : "unchanged")}");
        }

        return true;
    }

    private bool TryAssignKnownRuntimeBgLoadModelHydratedSourceOwner(
        ulong index,
        ulong destination,
        out ulong sourceOwnerSlot,
        out uint oldSourceOwner,
        out uint newSourceOwner)
    {
        const ulong sourceTable = 0xffffffff802529a0UL;
        sourceOwnerSlot = sourceTable + index * 4UL;
        oldSourceOwner = 0;
        newSourceOwner = (uint)destination;
        if (!_experimentRuntimeBgLoadModelHydratedSourceOwner ||
            index >= 64UL ||
            (_experimentRuntimeBgLoadModelHydratedSourceOwnerMask & (1UL << (int)index)) == 0 ||
            !IsMainRamRange(sourceOwnerSlot, 4UL) ||
            !IsMainRamRange(destination + 0x64UL, 4UL) ||
            _memory.Read32(destination + 0x40UL) != 0xf00b0001U ||
            _memory.Read32(destination + 0x5cUL) == 0 ||
            _memory.Read32(destination + 0x60UL) == 0 ||
            _memory.Read32(destination + 0x64UL) == 0)
        {
            return false;
        }

        oldSourceOwner = _memory.Read32(sourceOwnerSlot);
        const uint staticSourceOwner = 0x802e1718U;
        if (oldSourceOwner != 0 &&
            oldSourceOwner != staticSourceOwner &&
            oldSourceOwner != newSourceOwner)
        {
            return false;
        }
        if (oldSourceOwner == newSourceOwner)
            return true;
        _memory.Write32(sourceOwnerSlot, newSourceOwner);
        Console.WriteLine(
            $"[GAUNTDL:EXPERIMENT] bgloadmodel-hydrated-source-owner index={index} " +
            $"slot={sourceOwnerSlot:x16}:{oldSourceOwner:x8}->{newSourceOwner:x8} " +
            $"sourceWords={TraceKnownRuntimeBgLoadModelAssetParserWords(destination)}");
        return true;
    }

    private bool TryApplyKnownRuntimeBgLoadModelIndexedTextureQioBodyReadRepair(ulong pc)
