                $"dest={destination:x16} bytes={requestedBytes:x8} disk={diskByteOffset:x8} " +
                $"first={firstWord:x8} objectStatus={oldObjectStatus:x8}->{_memory.Read32(qioObject + 0x14UL):x8}");
