    private void EnsureKnownRuntimeBgLoadModelIndexedTextureQioObjectMetadata(ulong pc, ulong qioObject, string phase)
    {
        const uint ownerMetadata = 0x80218518U;
        if (!IsMainRamRange(qioObject + 0x20UL, 4))
            return;

        uint oldMetadata = _memory.Read32(qioObject + 0x20UL);
        if (oldMetadata != 0 && oldMetadata != ownerMetadata)
            return;

        if (oldMetadata == ownerMetadata)
            return;

        _memory.Write32(qioObject + 0x20UL, ownerMetadata);
        if (_runtimeBgLoadModelIndexedTextureQioObjectMetadataTraceCount++ < 16)
        {
            Console.WriteLine(
                $"[GAUNTDL:EXPERIMENT] bgloadmodel-indexed-texture-qio-object-metadata pc={pc:x16} " +
                $"phase={phase} object={qioObject:x16} obj20={oldMetadata:x8}->{ownerMetadata:x8}");
        }
    }

    private void ApplyKnownRuntimeBgLoadModelIndexedTextureQioStreamLimitRepair(ulong pc)
    {
        const ulong streamLimitComparePc = 0xffffffff800abe78UL;
        const ulong stateBase = 0xffffffff80210000UL;
        const ulong sourceCursorBase = 0xffffffff802e2158UL;
        const ulong loadedSourceBase = 0xffffffff802e1718UL;
        ulong sourceStride = (ulong)_runtimeBgLoadModelIndexedSourceStride;

        if (!_enableRuntimeBgLoadModelIndexedTextureQioExperiment ||
            _runtimeBgLoadModelIndexedTextureQioStreamLimit <= 0 ||
            pc != streamLimitComparePc ||
            _gpr[16] != stateBase ||
            _gpr[17] != stateBase ||
            _gpr[19] != sourceCursorBase ||
            _gpr[20] == 0 ||
            _gpr[20] >= (ulong)_runtimeBgLoadModelIndexedTextureQioStreamLimit)
        {
            return;
        }

        ulong streamIndex = _gpr[3];
        uint sourceCursor = _memory.Read32(stateBase + 0xf17cUL);
        if (streamIndex < _gpr[20])
            return;

        ulong loadedSource = loadedSourceBase + streamIndex * sourceStride;
        bool knownLoadedSource =
            streamIndex <= KnownRuntimeBgLoadModelTexturePayloadMaxIndex &&
            IsMainRamRange(loadedSource, 0x80UL) &&
            !IsKnownRuntimeBgLoadModelSourceWindowEmpty(loadedSource);
        if (streamIndex > KnownRuntimeBgLoadModelTexturePayloadMaxIndex || !knownLoadedSource)
            return;

        uint sourceOwnedLimit = _memory.Read32(loadedSource + 0x64UL);
        if (sourceOwnedLimit <= _gpr[20] ||
            sourceOwnedLimit > (uint)_runtimeBgLoadModelIndexedTextureQioStreamLimit)
        {
            if (_runtimeBgLoadModelIndexedTextureQioStreamLimitTraceCount++ < 16)
            {
                Console.WriteLine(
                    $"[GAUNTDL:TRACE] bgloadmodel-indexed-texture-qio-stream-limit-reject pc={pc:x16} " +
                    $"streamIndex={streamIndex} sourceCursor={sourceCursor} currentLimit={_gpr[20]} " +
                    $"sourceOwnedLimit={sourceOwnedLimit} configuredMax={_runtimeBgLoadModelIndexedTextureQioStreamLimit} " +
                    $"loadedSource={loadedSource:x16} sourceWords={TraceKnownRuntimeBgLoadModelAssetParserWords(loadedSource)}");
            }
            return;
        }

        ulong oldLimit = _gpr[20];
        _gpr[20] = sourceOwnedLimit;
        _gpr[0] = 0;

        if (_runtimeBgLoadModelIndexedTextureQioStreamLimitTraceCount++ < 16)
        {
            Console.WriteLine(
                $"[GAUNTDL:EXPERIMENT] bgloadmodel-indexed-texture-qio-stream-limit pc={pc:x16} " +
                $"streamIndex={streamIndex} sourceCursor={sourceCursor} limit={oldLimit}->{_gpr[20]} " +
                $"loadedSource={loadedSource:x16}");

            if (Environment.GetEnvironmentVariable("EUTHERDRIVE_GAUNTDL_TRACE_RUNTIME_BGLOADMODEL_SOURCE_RECORD_TABLE") == "1")
                TraceKnownRuntimeBgLoadModelSourceRecordTable(streamIndex, loadedSource, sourceOwnedLimit);
        }
    }

    private void TraceKnownRuntimeBgLoadModelSourceRecordTable(ulong streamIndex, ulong source, uint recordCount)
    {
        uint tableIndex = ReadTraceWord(source + 0x60UL);
        ulong table = source + 0x68UL + (ulong)tableIndex * 0x8cUL;
        uint boundedCount = Math.Min(recordCount, 13U);
        for (uint recordIndex = 0; recordIndex < boundedCount; recordIndex++)
        {
            ulong record = table + recordIndex * 0x50UL;
            var words = new StringBuilder();
            for (ulong offset = 0; offset < 0x50UL; offset += 4UL)
            {
                if (offset != 0)
                    words.Append('/');
                words.Append(ReadTraceWord(record + offset).ToString("x8", CultureInfo.InvariantCulture));
            }

            Console.WriteLine(
                $"[GAUNTDL:TRACE] bgloadmodel-source-record-table streamIndex={streamIndex} " +
                $"source={source:x16} tableIndex={tableIndex} table={table:x16} " +
                $"record={recordIndex}/{recordCount} address={record:x16} words={words}");
        }
    }

    private void TraceKnownRuntimeBgLoadModelTextureChunkReturn(ulong pc)
    {
        const ulong textureChunkCallPc = 0xffffffff800abeb0UL;
        const ulong textureChunkReturnPc = 0xffffffff800abeb8UL;
        bool trace = Environment.GetEnvironmentVariable("EUTHERDRIVE_GAUNTDL_TRACE_RUNTIME_BGLOADMODEL_TEXTURE_CHUNK_RETURN") == "1";
        if (!trace)
            return;

        if (pc == textureChunkCallPc)
        {
            _runtimeBgLoadModelPendingTextureRecord = _gpr[4];
            _runtimeBgLoadModelPendingTextureRecordOffset = ReadTraceWord(_gpr[4] + 0x08UL);
            _runtimeBgLoadModelPendingTextureChunkOffset = ReadTraceWord(0xffffffff8021f180UL);
            return;
        }

        if (pc != textureChunkReturnPc ||
            _runtimeBgLoadModelTextureChunkReturnTraceCount >= 64)
        {
            return;
        }

        _runtimeBgLoadModelTextureChunkReturnTraceCount++;

        ulong buffer = SignExtend32(unchecked((uint)_gpr[2]));
        var words = new StringBuilder();
        for (ulong offset = 0; offset < 0x40UL; offset += 4UL)
        {
            if (offset != 0)
                words.Append('/');
            words.Append(ReadTraceWord(buffer + offset).ToString("x8", CultureInfo.InvariantCulture));
        }

        Console.WriteLine(
            $"[GAUNTDL:TRACE] bgloadmodel-texture-chunk-return pc={pc:x16} " +
            $"buffer={buffer:x16} record={_runtimeBgLoadModelPendingTextureRecord:x16} " +
            $"recordOffset={_runtimeBgLoadModelPendingTextureRecordOffset:x8} " +
            $"fileHandle={ReadTraceWord(0xffffffff8021f178UL):x8} " +
            $"chunkOffset={ReadTraceWord(0xffffffff8021f180UL):x8} " +
            $"a0={_gpr[4]:x16} a1={_gpr[5]:x16} ra={_gpr[31]:x16} words={words}");
    }

    private void TraceKnownRuntimeWorldTextureDescriptor(ulong pc)
    {
        const ulong textureBaseStorePc = 0xffffffff800bd19cUL;
        if (!_traceRuntimeWorldTextureDescriptor ||
            _memory.VoodooRenderFrameCount < _traceRuntimeWorldTextureDescriptorMinFrame ||
            pc != textureBaseStorePc)
        {
            return;
        }

        ulong descriptor = _gpr[18];
        ulong material = _gpr[17];
        ulong owner = _gpr[20];
        var textureSetOwners = new List<string>();
        for (int set = 0; set < 16; set++)
        {
            uint setBase = ReadTraceWord(0xffffffff802545a0UL + (ulong)set * 4UL);
            if (setBase == 0)
                continue;

            ulong canonicalSetBase = SignExtend32(setBase);
            if (descriptor < canonicalSetBase)
                continue;

            ulong delta = descriptor - canonicalSetBase;
            if (delta < 0x10000UL && delta % 0x50UL == 0)
                textureSetOwners.Add($"{set}:{delta / 0x50UL}");
        }
        string textureSetOwner = textureSetOwners.Count == 0 ? "-" : string.Join(',', textureSetOwners);
        var key = (descriptor, material, owner, _gpr[16], _gpr[21], _gpr[2]);
        if (!_runtimeWorldTextureDescriptorTraceKeys.Add(key) ||
            _runtimeWorldTextureDescriptorTraceCount++ >= 64)
        {
            return;
        }

        Console.WriteLine(
            $"[GAUNTDL:TRACE] runtime-world-texture-descriptor n={_runtimeWorldTextureDescriptorTraceCount} " +
            $"frame={_memory.VoodooRenderFrameCount} pc={pc:x16} descriptor={descriptor:x16} " +
            $"textureSetRecord={textureSetOwner} " +
            $"words={FormatTraceWords(descriptor, 20)} " +
            $"mode={_gpr[16]:x16} lod={_gpr[21]:x16} base={_gpr[2]:x16} " +
            $"material={material:x16} materialWords={FormatTraceWords(material, 16)} " +
            $"owner={owner:x16} ownerWords={FormatTraceWords(owner, 16)} " +
            $"textureSetTable={FormatTraceWords(0xffffffff802545a0UL, 16)} ra={_gpr[31]:x16}");
    }

    private void ApplyKnownRuntimeWarFaceTextureBaseExperiment(ulong pc)
    {
        const ulong textureBaseStorePc = 0xffffffff800bd19cUL;
        const ulong warFaceDescriptor = 0xffffffff805b1be4UL;
        const ulong expectedMode = 0xffffffff8c2419cfUL;
        const ulong expectedLod = 0x0600260cUL;

        if (!_experimentRuntimeWarFaceTextureBase.HasValue ||
            pc != textureBaseStorePc ||
            _gpr[18] != warFaceDescriptor ||
            _gpr[16] != expectedMode ||
            _gpr[21] != expectedLod)
        {
            return;
        }

        ulong oldBase = _gpr[2];
        _gpr[2] = _experimentRuntimeWarFaceTextureBase.Value;
        if (!_runtimeWarFaceTextureBaseExperimentLogged)
        {
            _runtimeWarFaceTextureBaseExperimentLogged = true;
            Console.WriteLine(
                $"[GAUNTDL:EXPERIMENT] war-face-texture-base frame={_memory.VoodooRenderFrameCount} " +
                $"pc={pc:x16} descriptor={_gpr[18]:x16} base={oldBase:x8}->{_gpr[2]:x8}");
        }
    }

    private int HydrateKnownRuntimeBgLoadModelRemainingIndexedTextureSources(uint requestedBytes, ulong sourceStride = 0)
    {
        const ulong destinationBase = 0xffffffff802e1718UL;
        if (sourceStride == 0)
            sourceStride = requestedBytes;

        int hydrated = 0;
        for (ulong index = 1; index <= KnownRuntimeBgLoadModelTexturePayloadMaxIndex; index++)
        {
            ulong destination = destinationBase + index * sourceStride;
            uint sourceBytes = requestedBytes;
            if (_enableRuntimeBgLoadModelFullIndexedSourcePayloadsExperiment &&
                TryGetKnownRuntimeBgLoadModelTexturePayload(index, out _, out _, out uint fullPayloadBytes))
            {
                sourceBytes = Math.Min(fullPayloadBytes, (uint)sourceStride);
            }
            if (!IsKnownRuntimeBgLoadModelSourceWindowEmpty(destination))
            {
                TraceKnownRuntimeBgLoadModelIndexedSourceHydration(
                    "remaining-skip-nonempty",
                    index,
                    destination,
                    sourceBytes,
                    $"stride={sourceStride:x}");
                continue;
            }
            if (!TryHydrateKnownRuntimeBgLoadModelIndexedTextureSource(index, destination, sourceBytes, out _, out _, out _))
            {
                TraceKnownRuntimeBgLoadModelIndexedSourceHydration(
                    "remaining-hydrate-fail",
                    index,
                    destination,
                    sourceBytes,
                    $"stride={sourceStride:x}");
                continue;
            }

            TraceKnownRuntimeBgLoadModelIndexedSourceHydration(
                "remaining-hydrate",
                index,
                destination,
                sourceBytes,
                $"stride={sourceStride:x}");
            hydrated++;
        }

        return hydrated;
    }

    private bool TryHydrateKnownRuntimeBgLoadModelIndexedTextureSource(
        ulong index,
        ulong destination,
        uint requestedBytes,
        out string code,
        out ulong textureByteOffset,
        out uint firstWord)
    {
        code = "";
        textureByteOffset = 0;
        firstWord = 0;
        if (!TryGetKnownRuntimeBgLoadModelTexturePayload(index, out code, out textureByteOffset, out uint textureByteLength))
            return false;

        ulong readByteOffset = textureByteOffset;
        uint availableBytes = textureByteLength;
        if (_enableRuntimeBgLoadModelIndexedSourcePayloadFromBodyExperiment && requestedBytes > 0x120U)
        {
            uint headerBytes = Math.Min(0x80U, textureByteLength);
            if (!_memory.TryReadDiskByteOffsetToMemory(textureByteOffset, destination, headerBytes, out _, out _))
                return false;

            uint bodyOffset = IsMainRamRange(destination + 0x5cUL, 4)
                ? _memory.Read32(destination + 0x5cUL)
                : 0;
            if (bodyOffset == 0 || bodyOffset >= textureByteLength)
                return false;

            readByteOffset = textureByteOffset + bodyOffset;
            availableBytes = textureByteLength - bodyOffset;
        }

        if (availableBytes < requestedBytes)
        {
            for (uint offset = 0; offset < requestedBytes; offset++)
                _memory.Write8(destination + offset, 0);
        }

        uint copyBytes = Math.Min(requestedBytes, availableBytes);
        textureByteOffset = readByteOffset;
        if (!_memory.TryReadDiskByteOffsetToMemory(readByteOffset, destination, copyBytes, out firstWord, out _))
            return false;

        TraceRuntimeBgLoadModelHydrationRange(
            "indexed-source",
            destination,
            copyBytes,
            readByteOffset,
            $"index={index}/{code}/requested={requestedBytes:x8}/copy={copyBytes:x8}/first={firstWord:x8}");
        return true;
    }

    private bool TryHydrateKnownRuntimeBgLoadModelIndexedTextureSourceZeroFill(
        ulong index,
        ulong destination,
        uint requestedBytes,
        out string code,
        out ulong textureByteOffset,
        out uint firstWord,
        out uint filledBytes,
        out uint firstFilledOffset)
    {
        code = "";
        textureByteOffset = 0;
        firstWord = 0;
        filledBytes = 0;
        firstFilledOffset = 0;
        if (!TryGetKnownRuntimeBgLoadModelTexturePayload(index, out code, out textureByteOffset, out uint textureByteLength))
            return false;

        uint copyBytes = Math.Min(requestedBytes, textureByteLength);
        if (copyBytes < 4U || !IsMainRamRange(destination, copyBytes))
            return false;

        if (!_memory.TryReadDiskByteOffsetWord(textureByteOffset, out firstWord))
            return false;

        uint startOffset = (uint)Math.Min(_runtimeBgLoadModelOverlapZeroFillIndexedSourceMinOffset, copyBytes - 4U);
        startOffset &= 0xfffffffcU;
        bool sawFirstFill = false;
        for (uint offset = startOffset; offset <= copyBytes - 4U; offset += 4U)
        {
            ulong target = destination + offset;
            if (_memory.Read32(target) != 0)
                continue;

            if (!_memory.TryReadDiskByteOffsetWord(textureByteOffset + offset, out uint diskWord) ||
                diskWord == 0)
            {
                continue;
            }

            _memory.Write32(target, diskWord);
            filledBytes += 4U;
            if (!sawFirstFill)
            {
                firstFilledOffset = offset;
                sawFirstFill = true;
            }
        }

        return filledBytes != 0;
    }

