    private bool IsKnownRuntimeBgLoadModelSourceWindowEmpty(ulong source)
    {
        if (!IsMainRamRange(source, 0x80UL))
            return false;

        for (ulong offset = 0; offset < 0x80UL; offset += 4UL)
        {
            if (_memory.Read32(source + offset) != 0)
                return false;
        }

        return true;
    }

