        ulong index = _gpr[17] & 0xffffffffUL;
        if (_traceRuntimeBgLoadModelAssetConsumerIndex.HasValue &&
            index != (_traceRuntimeBgLoadModelAssetConsumerIndex.Value & 0xffffffffUL))
