            $"branch={(unchecked((uint)_gpr[2]) == 0 ? "skip" : "activate")} " +
            $"entry={assetEntry:x16}:{ReadTraceWord(assetEntry):x8}/{ReadTraceWord(assetEntry + 0x04UL):x8}/" +
            $"{ReadTraceWord(assetEntry + 0x08UL):x8}/\"{ReadAsciiTraceString(assetEntry + 0x10UL, 24)}\" " +
            $"sourceRecord={_gpr[18]:x16} sourceWords={TraceKnownRuntimeBgLoadModelAssetParserWords(_gpr[18])} " +
            $"ra={_gpr[31]:x16} sp={_gpr[29]:x16}");
    }

    private bool TryApplyKnownRuntimeBgLoadModelStaticObjectSizeOwner(ulong pc)
    {
        const ulong entry = 0xffffffff800c8828UL;
        const ulong source = 0xffffffff802e1718UL;
        const uint objectsRom = 0x8013b024U;
        const uint objectByteLength = 0x00067b4cU;

        if ((!_enableRuntimeBgLoadModelStaticObjectBodyRead &&
             !_experimentRuntimeBgLoadModelStaticObjectSizeOwner) ||
            pc != entry ||
            (uint)_gpr[5] != objectsRom ||
            _gpr[6] != 0 ||
            _gpr[7] != 0 ||
            !IsMainRamRange(_gpr[29] + 0x10UL, 4UL) ||
            ReadTraceWord(_gpr[29] + 0x10UL) != 0x802e1718U ||
            !IsMainRamRange(source + 0x43UL, 1UL) ||
            ReadTraceWord(source + 0x40UL) != 0xf00b0001U)
        {
            return false;
        }

        _gpr[2] = objectByteLength;
        _gpr[0] = 0;
        Pc = _gpr[31];
        CompleteFastPathStep();
        Console.WriteLine(
            $"[GAUNTDL:{(_enableRuntimeBgLoadModelStaticObjectBodyRead ? "FIX" : "EXPERIMENT")}] bgloadmodel-static-object-size-owner pc={pc:x16} " +
            $"source={source:x16} bytes={objectByteLength:x8} ra={Pc:x16}");
        return true;
    }

    private bool TryApplyKnownRuntimeBgLoadModelStaticObjectPathOwner(ulong pc)
    {
        const ulong callsite = 0xffffffff800c886cUL;
        const ulong openEntry = 0xffffffff800ec748UL;
        const ulong destination = 0xffffffff80218530UL;
        const ulong format = 0xffffffff8013d8d4UL;
        const ulong emptyDirectory = 0xffffffff80166370UL;
        const ulong objectsRom = 0xffffffff8013b024UL;
        const ulong source = 0xffffffff802e1718UL;
        const string ownedPath = "/d0/static_lr/objects.rom";

        if (_experimentRuntimeBgLoadModelStaticObjectPathOwner &&
            pc == openEntry &&
            _memory.Read32(openEntry) == 0x27bdffd0U &&
            _memory.Read32(openEntry + 0x0cUL) == 0xafb40020U &&
            _gpr[31] == 0xffffffff800c88f8UL &&
            _gpr[4] == 0xffffffff80295750UL &&
            _gpr[5] == destination &&
            _gpr[6] == 0 &&
            ReadAsciiTraceString(destination, 2).Length == 0 &&
            IsMainRamRange(destination, (ulong)ownedPath.Length + 1UL))
        {
            for (int i = 0; i < ownedPath.Length; i++)
                _memory.Write8(destination + (uint)i, (byte)ownedPath[i]);
            _memory.Write8(destination + (uint)ownedPath.Length, 0);
            Console.WriteLine(
                $"[GAUNTDL:EXPERIMENT] bgloadmodel-static-object-path-owner-open-entry pc={pc:x16} " +
                $"path=\"{ReadAsciiTraceString(destination, 96)}\"");
            return false;
        }

        ulong frame = _gpr[30];
        if (!_experimentRuntimeBgLoadModelStaticObjectPathOwner ||
            pc != callsite ||
            _memory.Read32(callsite) != 0x0c047cf0U ||
            _memory.Read32(callsite + 0x04UL) != 0U ||
            _gpr[4] != destination ||
            _gpr[5] != format ||
            _gpr[6] != emptyDirectory ||
            _gpr[7] != objectsRom ||
            !IsMainRamRange(frame + 0x73UL, 1UL) ||
            ReadTraceWord(frame + 0x64UL) != unchecked((uint)objectsRom) ||
            ReadTraceWord(frame + 0x70UL) != unchecked((uint)source) ||
            ReadAsciiTraceString(emptyDirectory, 2).Length != 0 ||
            ReadAsciiTraceString(objectsRom, 16) != "objects.rom" ||
            !IsMainRamRange(destination, (ulong)ownedPath.Length + 1UL))
        {
            return false;
        }

        for (int i = 0; i < ownedPath.Length; i++)
            _memory.Write8(destination + (uint)i, (byte)ownedPath[i]);
        _memory.Write8(destination + (uint)ownedPath.Length, 0);

        _gpr[2] = SignExtend32((uint)ownedPath.Length);
        Pc = callsite + 0x08UL;
        CompleteFastPathStep();
        Console.WriteLine(
            $"[GAUNTDL:EXPERIMENT] bgloadmodel-static-object-path-owner pc={pc:x16} " +
            $"path=\"{ReadAsciiTraceString(destination, 96)}\" next={Pc:x16}");
        return true;
    }

    private void TraceKnownRuntimeBgLoadModelLookupHelpers(ulong pc)
    {
        if (!_traceRuntimeBgLoadModelAssetParser || _runtimeBgLoadModelLookupHelperTraceCount >= 512)
            return;

        string label = pc switch
        {
            0xffffffff800b72fcUL => "size-alloc-entry",
            0xffffffff800b7338UL => "size-alloc-return",
            0xffffffff800c8828UL => "file-size-entry",
            0xffffffff800c886cUL => "file-path-format-call",
            0xffffffff800c8874UL => "file-path-format-return",
            0xffffffff800c8898UL => "file-open-setup",
            0xffffffff800c88ecUL => "file-open-call",
            0xffffffff800c88fcUL => "file-open-return",
            0xffffffff800c890cUL => "file-open-status",
            0xffffffff800c8918UL => "file-stat-call",
            0xffffffff800c8928UL => "file-stat-return",
            0xffffffff800c8938UL => "file-stat-status",
            0xffffffff800c893cUL => "file-size-result-load",
            0xffffffff800ec748UL => "file-open-dispatch-entry",
            0xffffffff800ec7a0UL => "file-open-path-lookup-call",
            0xffffffff800ec7a8UL => "file-open-path-lookup-return",
            0xffffffff800ec7b4UL => "file-open-fallback-lookup-call",
            0xffffffff800ec7bcUL => "file-open-fallback-lookup-return",
            0xffffffff800ec800UL => "file-open-request-alloc-call",
            0xffffffff800ec808UL => "file-open-request-alloc-return",
            0xffffffff800ec81cUL => "file-open-request-enqueue-call",
            0xffffffff800ec824UL => "file-open-request-enqueue-return",
            0xffffffff800ec82cUL => "file-open-request-status-clear",
            0xffffffff800ec834UL => "file-open-callback-call",
            0xffffffff800ec83cUL => "file-open-callback-return",
            0xffffffff800c9088UL => "lookup-entry",
            0xffffffff800c909cUL => "lookup-global-check",
            0xffffffff800c90b4UL => "lookup-index-fold",
            0xffffffff800c90d4UL => "lookup-return",
            _ => ""
        };
        if (label.Length == 0)
            return;
        if (pc == 0xffffffff800b72fcUL &&
            _gpr[31] is not (0xffffffff800aad84UL or 0xffffffff800aae68UL))
        {
            return;
        }
        if (pc == 0xffffffff800c8828UL &&
            (uint)_gpr[5] != 0x8013b024U)
        {
            return;
        }
        if (pc is >= 0xffffffff800c886cUL and <= 0xffffffff800c8938UL)
        {
            ulong frame = _gpr[30];
            if (!IsMainRamRange(frame + 0x73UL, 1) ||
                ReadTraceWord(frame + 0x64UL) != 0x8013b024U)
            {
                return;
            }
        }
        if (pc is >= 0xffffffff800ec748UL and <= 0xffffffff800ec83cUL)
        {
            ulong qioObject = pc == 0xffffffff800ec748UL ? _gpr[4] : _gpr[18];
            string activePath = ReadAsciiTraceString(0xffffffff80218530UL, 96);
            if ((pc == 0xffffffff800ec748UL && _gpr[31] != 0xffffffff800c88f8UL) ||
                !activePath.StartsWith("/d0/", StringComparison.Ordinal) ||
                !IsMainRamRange(qioObject, 0x40UL))
            {
                return;
            }
        }
        if (pc is >= 0xffffffff800c9088UL and <= 0xffffffff800c90d4UL &&
            _gpr[31] != 0xffffffff800aade4UL)
        {
            return;
        }
        if (pc == 0xffffffff800c893cUL)
        {
            ulong frame = _gpr[30];
            if (!IsMainRamRange(frame + 0x73UL, 1) ||
                ReadTraceWord(frame + 0x64UL) != 0x8013b024U)
            {
                return;
            }

            _runtimeBgLoadModelLookupHelperTraceCount++;
            Console.WriteLine(
                $"[GAUNTDL:TRACE] bgloadmodel-lookup-helper {label} pc={pc:x16} " +
                $"ra={_gpr[31]:x16} fp={frame:x16} " +
                $"args={ReadTraceWord(frame + 0x60UL):x8}/{ReadTraceWord(frame + 0x64UL):x8}/" +
                $"{ReadTraceWord(frame + 0x68UL):x8}/{ReadTraceWord(frame + 0x6cUL):x8}/" +
                $"{ReadTraceWord(frame + 0x70UL):x8} " +
                $"result={FormatTraceWords(frame + 0x10UL, 17)} " +
                $"path=\"{ReadAsciiTraceString(0xffffffff80218530UL, 96)}\"");
            return;
        }

        _runtimeBgLoadModelLookupHelperTraceCount++;
        ulong tracedOpenObject = pc is >= 0xffffffff800ec748UL and <= 0xffffffff800ec83cUL
            ? (pc == 0xffffffff800ec748UL ? _gpr[4] : _gpr[18])
            : 0xffffffff80295750UL;
        Console.WriteLine(
            $"[GAUNTDL:TRACE] bgloadmodel-lookup-helper {label} pc={pc:x16} op={_memory.Read32(pc):x8} " +
            $"ra={_gpr[31]:x16} sp={_gpr[29]:x16} v0={_gpr[2]:x16} v1={_gpr[3]:x16} " +
            $"a0={_gpr[4]:x16}({ReadAsciiTraceString(_gpr[4], 48)}) " +
            $"a1={_gpr[5]:x16}({ReadAsciiTraceString(_gpr[5], 48)}) " +
            $"a2={_gpr[6]:x16}({ReadAsciiTraceString(_gpr[6], 48)}) " +
            $"a3={_gpr[7]:x16}({ReadAsciiTraceString(_gpr[7], 48)}) " +
            $"s0={_gpr[16]:x16} s1={_gpr[17]:x16} s2={_gpr[18]:x16} s3={_gpr[19]:x16} s4={_gpr[20]:x16} s5={_gpr[21]:x16} " +
            $"filePath=\"{ReadAsciiTraceString(0xffffffff80218530UL, 96)}\" " +
            $"openObject={TraceKnownRuntimeBgLoadModelQioOneLine(tracedOpenObject)} " +
            $"pathSlot={TraceKnownRuntimeBgLoadModelPathSlot(_gpr[16])} " +
            $"lookupGlobals={TraceKnownRuntimeBgLoadModelLookupGlobals()}");
    }

