    private void ApplyKnownRuntimeBgLoadModelStaticObjectCompanionOwner(ulong pc)
    {
        const ulong calleePc = 0xffffffff800a7094UL;
        const ulong initializeReturn = 0xffffffff800abe54UL;
        const ulong repeatReturn = 0xffffffff800ab3b8UL;
        const ulong source = 0xffffffff802e1718UL;
        const ulong companionHeaderBytes = 4UL;
        const ulong recordTableOffset = 0xb454UL;
        const ulong recordTableBytes = 0xe60UL;
        if (!_experimentRuntimeBgLoadModelStaticObjectOwner ||
            !_experimentRuntimeBgLoadModelStaticObjectCompanionOwner ||
            pc != calleePc ||
            _gpr[31] is not (initializeReturn or repeatReturn) ||
            CanonicalizeTraceAddress(_gpr[5]) != source)
        {
            return;
        }

        ulong record = CanonicalizeTraceAddress(_gpr[4]);
        if (record < source + recordTableOffset || record >= source + recordTableOffset + recordTableBytes)
            return;

        ulong companion = source + _experimentRuntimeBgLoadModelStaticObjectByteLength + companionHeaderBytes;
        if (!IsMainRamRange(companion, _experimentRuntimeBgLoadModelStaticObjectCompanionByteLength))
            return;

        ulong original = _gpr[5];
        _gpr[5] = companion;
        if (_runtimeBgLoadModelStaticObjectCompanionOwnerTraceCount++ < 16)
        {
            Console.WriteLine(
                $"[GAUNTDL:EXPERIMENT] bgloadmodel-static-object-companion-owner pc={pc:x16} " +
                $"record={record:x16} source={original:x16}->{companion:x16} " +
                $"bytes={_experimentRuntimeBgLoadModelStaticObjectCompanionByteLength:x8} " +
                $"first={FormatTraceWords(companion, 4)}");
        }
    }

    private void TraceKnownRuntimeWorldTextureRecordSelection(ulong pc)
    {
        if (!_traceRuntimeWorldTextureRecordSelection ||
            pc is not (0xffffffff800ab2b0UL or 0xffffffff800ab32cUL or 0xffffffff800ab35cUL) ||
            _runtimeWorldTextureRecordSelectionTraceCount >= _traceRuntimeWorldTextureRecordSelectionLimit)
        {
            return;
        }

        if (pc == 0xffffffff800ab2b0UL)
        {
            ulong outer = CanonicalizeTraceAddress(_gpr[16]);
            uint tableIndex = ReadTraceWord(outer + 0x60UL);
            uint recordCount = ReadTraceWord(outer + 0x64UL);
            ulong computedTable = outer + 0x68UL + (ulong)tableIndex * 0x8cUL;
            if (computedTable is not (0xffffffff802e2158UL or 0xffffffff802ecb6cUL))
                return;

            _runtimeWorldTextureRecordSelectionTraceCount++;
            Console.WriteLine(
                $"[GAUNTDL:TRACE] world-texture-record-selection n={_runtimeWorldTextureRecordSelectionTraceCount} " +
                $"phase=outer-setup pc={pc:x16} ra={_gpr[31]:x16} outer={outer:x16} " +
                $"tableIndex={tableIndex:x8} recordCount={recordCount:x8} table={computedTable:x16} " +
                $"a0={_gpr[4]:x16} a1={_gpr[5]:x16} a2={_gpr[6]:x16} a3={_gpr[7]:x16} " +
                $"outerWords={FormatTraceWords(outer, 28)}");
            return;
        }

        ulong table = CanonicalizeTraceAddress(_gpr[30]);
        if (table is not (0xffffffff802e2158UL or 0xffffffff802ecb6cUL))
            return;

        ulong record = CanonicalizeTraceAddress(_gpr[16]);
        string phase = pc == 0xffffffff800ab32cUL ? "record0-return" : "scan-return";
        _runtimeWorldTextureRecordSelectionTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:TRACE] world-texture-record-selection n={_runtimeWorldTextureRecordSelectionTraceCount} " +
            $"phase={phase} pc={pc:x16} ra={_gpr[31]:x16} v0={_gpr[2]:x16} v1={_gpr[3]:x16} " +
            $"table={table:x16} record={record:x16} " +
            $"selectedIndex={_gpr[20]:x16} cursor={_gpr[17]:x16} recordOffset={_gpr[18]:x16} " +
            $"candidate={_gpr[19]:x16} limit={_gpr[21]:x16} phaseReg={_gpr[22]:x16} " +
            $"recordWords={FormatTraceWords(record, 20)}");
    }

    private void TraceKnownRuntimeBgLoadModelQioRequests(ulong pc, string phase)
    {
        if (!_traceRuntimeBgLoadModelQioRequests || _runtimeBgLoadModelQioRequestTraceCount >= _traceRuntimeBgLoadModelQioRequestLimit)
            return;

        string label = pc switch
        {
            0xffffffff800abb10UL => "qio-poll-alias",
            0xffffffff800abbc0UL => "qio-poll-store",
            0xffffffff800ac350UL => "model-create-call",
            0xffffffff800ac3c4UL => "model-create-state",
            0xffffffff800ac4dcUL => "state-qio-done",
            0xffffffff800c9678UL => "qio-create-object",
            0xffffffff800c9944UL => "qio-create-call",
            _ => ""
        };
        if (label.Length == 0)
            return;

        if (_memory.Read32(0xffffffff800abaa0UL) != 0x27bdffd8U)
        {
            return;
        }

        const ulong recordBase = 0xffffffff80252da0UL;
        const ulong recordStride = 0x18UL;
        const ulong qioBase = 0xffffffff80217c58UL;
        const ulong qioStride = 0x118UL;

        ulong record = _gpr[17];
        long recordIndex = GetKnownRuntimeBgLoadModelRecordIndex(record);
        string recordRegister = "s1";
        if (recordIndex < 0 && TryGetKnownRuntimeBgLoadModelRecordFromRegisters(out ulong registerRecord, out ulong registerRecordIndex, out string registerName))
        {
            record = registerRecord;
            recordIndex = unchecked((long)registerRecordIndex);
            recordRegister = registerName;
        }
        long assetIndex = recordIndex >= 0 ? recordIndex :
            _gpr[7] < 0x10000UL ? unchecked((long)_gpr[7]) :
            _gpr[17] < 0x10000UL ? unchecked((long)_gpr[17]) : -1;

        ulong recordQioAt0 = IsMainRamRange(record, 4) ? SignExtend32(_memory.Read32(record)) : 0;
        ulong recordQioAt8 = IsMainRamRange(record + 0x08UL, 4) ? SignExtend32(_memory.Read32(record + 0x08UL)) : 0;
        ulong recordQio = IsMainRamRange(recordQioAt0 + 0x18UL, 4) ? recordQioAt0 : recordQioAt8;
        string recordQioSlot = recordQio == recordQioAt0 ? "+0" : "+8";

        ulong expectedQio = recordIndex >= 0 ? qioBase + (ulong)recordIndex * qioStride : 0;
        ulong qio = IsMainRamRange(recordQio + 0x18UL, 4) ? recordQio :
            IsMainRamRange(expectedQio + 0x18UL, 4) ? expectedQio : 0;
        ulong qioObject = IsMainRamRange(qio, 4) ? SignExtend32(_memory.Read32(qio)) : 0;
        ulong qioDestination = IsMainRamRange(qio + 0x08UL, 4) ? SignExtend32(_memory.Read32(qio + 0x08UL)) : 0;
        ulong returnSlot = _gpr[30] + 0x20UL;
        ulong returnQio = IsMainRamRange(returnSlot, 4) ? SignExtend32(_memory.Read32(returnSlot)) : 0;
        ulong returnQioObject = IsMainRamRange(returnQio, 4) ? SignExtend32(_memory.Read32(returnQio)) : 0;

        _runtimeBgLoadModelQioRequestTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:TRACE] bgloadmodel-qio-request {phase}/{label} pc={pc:x16} op={_memory.Read32(pc):x8} " +
            $"idx={recordIndex} record={recordRegister}:{record:x16} recordQio={recordQioSlot}:{recordQio:x16} expectedQio={expectedQio:x16} " +
            $"qio={TraceKnownRuntimeBgLoadModelQioOneLine(qio)} " +
            $"obj={qioObject:x16}:{ReadTraceWord(qioObject):x8}/{ReadTraceWord(qioObject + 0x14UL):x8} " +
            $"file={TraceKnownRuntimeBgLoadModelQioFileState(qioObject)} " +
            $"dst={qioDestination:x16}:{ReadTraceWord(qioDestination):x8} " +
            $"retFile={TraceKnownRuntimeBgLoadModelQioFileState(returnQioObject)} " +
            $"argFile={TraceKnownRuntimeBgLoadModelQioFileState(_gpr[4])} " +
            $"globals={TraceKnownRuntimeBgLoadModelQioGlobals()} " +
            $"stack={TraceKnownRuntimeBgLoadModelQioStack()} " +
            $"ra={_gpr[31]:x16} sp={_gpr[29]:x16} a0={_gpr[4]:x16}({ReadAsciiTraceString(_gpr[4], 48)}) " +
            $"a1={_gpr[5]:x16}({ReadAsciiTraceString(_gpr[5], 48)}) " +
            $"a2={_gpr[6]:x16}({ReadAsciiTraceString(_gpr[6], 48)}) " +
            $"a3={_gpr[7]:x16}({ReadAsciiTraceString(_gpr[7], 48)}) " +
            $"v0={_gpr[2]:x16}({ReadAsciiTraceString(_gpr[2], 48)}) " +
            $"v1={_gpr[3]:x16} s0={_gpr[16]:x16} s1={_gpr[17]:x16} s2={_gpr[18]:x16} s8={_gpr[30]:x16} " +
            $"s0rec={TraceKnownRuntimeBgLoadModelRecordOneLine(_gpr[16])} " +
            $"s1rec={TraceKnownRuntimeBgLoadModelRecordOneLine(_gpr[17])} " +
            $"retSlot={TraceKnownRuntimeBgLoadModelReturnSlot(returnSlot)} " +
            $"pathTable={TraceKnownRuntimeBgLoadModelPathTableSummary(recordIndex)} " +
            $"assetTable={TraceKnownRuntimeBgLoadModelAssetTableSummary(assetIndex)}");
    }

    private void TraceKnownRuntimeBgLoadModelStreamDescriptorBuilder(ulong pc)
