                $"offset={_runtimeBgLoadModelStreamDescriptorBuilderOffset:x16} " +
                $"count={_runtimeBgLoadModelStreamDescriptorBuilderCount:x16} " +
                $"record={TraceKnownRuntimeBgLoadModelRecordOneLine(_runtimeBgLoadModelStreamDescriptorBuilderRecord)} " +
                $"recordQioSlot={TraceKnownRuntimeBgLoadModelReturnSlot(_runtimeBgLoadModelStreamDescriptorBuilderRecord + 0x04UL)} " +
                $"globals={TraceKnownRuntimeBgLoadModelQioGlobals()} sp={_gpr[29]:x16}");
            return;
        }

        if (pc != callerReturnPc || !_runtimeBgLoadModelStreamDescriptorBuilderActive)
            return;

        _runtimeBgLoadModelStreamDescriptorBuilderActive = false;
        _runtimeBgLoadModelStreamDescriptorBuilderTraceCount++;
        ulong qioSlot = _runtimeBgLoadModelStreamDescriptorBuilderRecord + 0x04UL;
        ulong qio = IsMainRamRange(qioSlot, 4) ? SignExtend32(ReadTraceWord(qioSlot)) : 0;
        ulong qioObject = IsMainRamRange(qio, 4) ? SignExtend32(ReadTraceWord(qio)) : 0;
        ulong destination = IsMainRamRange(qio + 0x08UL, 4) ? SignExtend32(ReadTraceWord(qio + 0x08UL)) : 0;
        Console.WriteLine(
            $"[GAUNTDL:TRACE] bgloadmodel-stream-descriptor-builder phase=return " +
            $"n={_runtimeBgLoadModelStreamDescriptorBuilderTraceCount} pc={pc:x16} v0={_gpr[2]:x16} " +
            $"descriptor={_runtimeBgLoadModelStreamDescriptorBuilderDescriptor:x16}:" +
            $"{FormatTraceWords(_runtimeBgLoadModelStreamDescriptorBuilderDescriptor, 20)} " +
            $"source={_runtimeBgLoadModelStreamDescriptorBuilderSource:x16}:" +
            $"{FormatTraceWords(_runtimeBgLoadModelStreamDescriptorBuilderSource, 20)} " +
            $"offset={_runtimeBgLoadModelStreamDescriptorBuilderOffset:x16} " +
            $"count={_runtimeBgLoadModelStreamDescriptorBuilderCount:x16} " +
            $"record={TraceKnownRuntimeBgLoadModelRecordOneLine(_runtimeBgLoadModelStreamDescriptorBuilderRecord)} " +
            $"qioSlot={qioSlot:x16}:{ReadTraceWord(qioSlot):x8} " +
            $"qio={TraceKnownRuntimeBgLoadModelQioOneLine(qio)} " +
            $"file={TraceKnownRuntimeBgLoadModelQioFileState(qioObject)} " +
            $"destination={destination:x16}:{FormatTraceWords(destination, 8)} " +
            $"globals={TraceKnownRuntimeBgLoadModelQioGlobals()} sp={_gpr[29]:x16} fp={_gpr[30]:x16}");
    }

    private string TraceKnownRuntimeBgLoadModelQioStack()
    {
        ulong sp = _gpr[29];
        ulong fp = _gpr[30];
        return $"sp+00={TraceKnownRuntimeBgLoadModelStackWord(sp, 0x00UL)}/" +
               $"10={TraceKnownRuntimeBgLoadModelStackWord(sp, 0x10UL)}/" +
               $"14={TraceKnownRuntimeBgLoadModelStackWord(sp, 0x14UL)}/" +
               $"18={TraceKnownRuntimeBgLoadModelStackWord(sp, 0x18UL)}/" +
               $"20={TraceKnownRuntimeBgLoadModelStackWord(sp, 0x20UL)}/" +
               $"24={TraceKnownRuntimeBgLoadModelStackWord(sp, 0x24UL)}/" +
               $"78={TraceKnownRuntimeBgLoadModelStackWord(sp, 0x78UL)}/" +
               $"7c={TraceKnownRuntimeBgLoadModelStackWord(sp, 0x7cUL)}/" +
               $"80={TraceKnownRuntimeBgLoadModelStackWord(sp, 0x80UL)}/" +
               $"84={TraceKnownRuntimeBgLoadModelStackWord(sp, 0x84UL)} " +
               $"fp+20={TraceKnownRuntimeBgLoadModelStackWord(fp, 0x20UL)}/" +
               $"24={TraceKnownRuntimeBgLoadModelStackWord(fp, 0x24UL)}";
    }

    private string TraceKnownRuntimeBgLoadModelStackWord(ulong baseAddress, ulong offset)
    {
        ulong address = baseAddress + offset;
        return IsMainRamRange(address, 4) ? $"{ReadTraceWord(address):x8}" : "--------";
    }

    private long GetKnownRuntimeBgLoadModelRecordIndex(ulong record)
    {
        const ulong recordBase = 0xffffffff80252da0UL;
        const ulong recordStride = 0x18UL;
        if (record < recordBase || (record - recordBase) % recordStride != 0)
            return -1;

        return (long)((record - recordBase) / recordStride);
    }

    private bool TryGetKnownRuntimeBgLoadModelRecordFromRegisters(
        out ulong record,
        out ulong recordIndex,
        out string registerName)
    {
        if (TryGetKnownRuntimeBgLoadModelRecordFromRegister(_gpr[17], "s1", out record, out recordIndex, out registerName))
            return true;

        return TryGetKnownRuntimeBgLoadModelRecordFromRegister(_gpr[16], "s0", out record, out recordIndex, out registerName);
    }

    private static bool TryGetKnownRuntimeBgLoadModelRecordFromRegister(
        ulong candidate,
        string candidateRegisterName,
        out ulong record,
        out ulong recordIndex,
        out string registerName)
    {
        const ulong recordBase = 0xffffffff80252da0UL;
        const ulong recordStride = 0x18UL;

        record = 0;
        recordIndex = 0;
        registerName = "";
        if (candidate < recordBase || (candidate - recordBase) % recordStride != 0)
            return false;

        record = candidate;
        recordIndex = (candidate - recordBase) / recordStride;
        registerName = candidateRegisterName;
        return true;
    }

    private string TraceKnownRuntimeBgLoadModelRecordOneLine(ulong record)
    {
        long index = GetKnownRuntimeBgLoadModelRecordIndex(record);
        if (index < 0 || !IsMainRamRange(record + 0x14UL, 4))
            return $"{record:x16}:range";

        return $"{index}:{record:x16}:" +
               $"{_memory.Read32(record + 0x00UL):x8}/" +
               $"{_memory.Read32(record + 0x04UL):x8}/" +
               $"{_memory.Read32(record + 0x08UL):x8}/" +
               $"{_memory.Read32(record + 0x0cUL):x8}/" +
               $"{_memory.Read32(record + 0x10UL):x8}/" +
               $"{_memory.Read32(record + 0x14UL):x8}";
    }

    private string TraceKnownRuntimeBgLoadModelReturnSlot(ulong slot)
    {
        if (!IsMainRamRange(slot, 4))
            return $"{slot:x16}:range";

        ulong qio = SignExtend32(_memory.Read32(slot));
        return $"{slot:x16}->{qio:x16}:{TraceKnownRuntimeBgLoadModelQioOneLine(qio)}";
    }

    private string TraceKnownRuntimeBgLoadModelQioOneLine(ulong qio)
    {
        if (qio == 0 || !IsMainRamRange(qio + 0x18UL, 4))
            return $"{qio:x16}:range";

        return $"{qio:x16}:{_memory.Read32(qio + 0x00UL):x8}/" +
               $"{_memory.Read32(qio + 0x04UL):x8}/" +
               $"{_memory.Read32(qio + 0x08UL):x8}/" +
               $"{_memory.Read32(qio + 0x0cUL):x8}/" +
               $"{_memory.Read32(qio + 0x10UL):x8}/" +
               $"{_memory.Read32(qio + 0x14UL):x8}/" +
               $"{ReadAsciiTraceString(qio + 0x18UL, 48)}";
    }

    private string TraceKnownRuntimeBgLoadModelQioFileState(ulong qioObject)
    {
        if (!IsMainRamRange(qioObject, 4))
            return "range";

        ulong fileState = SignExtend32(_memory.Read32(qioObject));
        if (!IsMainRamRange(fileState + 0x118UL, 4))
            return $"{fileState:x16}:range";

        return $"{fileState:x16}:" +
               $"off={_memory.Read32(fileState + 0x114UL):x8}/" +
               $"lba={_memory.Read32(fileState + 0x118UL):x8}/" +
               $"w110={_memory.Read32(fileState + 0x110UL):x8}/" +
               $"w11c={_memory.Read32(fileState + 0x11cUL):x8}";
    }

    private string TraceKnownRuntimeBgLoadModelQioGlobals()
    {
        const ulong baseAddress = 0xffffffff80210000UL;
        return $"f154={ReadTraceWord(baseAddress + 0xf154UL):x8}/" +
               $"f178={ReadTraceWord(baseAddress + 0xf178UL):x8}/" +
               $"f17c={ReadTraceWord(baseAddress + 0xf17cUL):x8}/" +
               $"f180={ReadTraceWord(baseAddress + 0xf180UL):x8}/" +
               $"f184={ReadTraceWord(baseAddress + 0xf184UL):x8}";
    }

    private string TraceKnownRuntimeBgLoadModelPathTableSummary(long recordIndex)
    {
        const ulong candidateBase = 0xffffffff8025f9b0UL;
        const ulong candidateStride = 0x40UL;

        StringBuilder builder = new();
        long first = recordIndex >= 1 ? recordIndex - 1 : 0;
        for (long i = first; i < first + 4; i++)
        {
            ulong address = candidateBase + (ulong)i * candidateStride;
            string text = ReadAsciiTraceString(address, 48);
            if (text.Length == 0)
                continue;
            if (builder.Length > 0)
                builder.Append(';');
            builder.Append(i);
            builder.Append(':');
            builder.Append(text);
        }

        return builder.ToString();
    }

    private string TraceKnownRuntimeBgLoadModelAssetTableSummary(long recordIndex)
    {
        const ulong candidateBase = 0xffffffff8024f9a0UL;
        const ulong candidateStride = 0x30UL;

        StringBuilder builder = new();
        long first = recordIndex >= 1 ? recordIndex - 1 : 0;
        for (long i = first; i < first + 6; i++)
        {
            ulong address = candidateBase + (ulong)i * candidateStride;
            if (!IsMainRamRange(address + 0x2fUL, 1))
                continue;

            string text = ReadAsciiTraceString(address + 0x10UL, 24);
            uint word0 = _memory.Read32(address + 0x00UL);
            uint word4 = _memory.Read32(address + 0x04UL);
            uint word8 = _memory.Read32(address + 0x08UL);
            if (text.Length == 0 && word0 == 0 && word4 == 0 && word8 == 0)
                continue;

            if (builder.Length > 0)
                builder.Append(';');
            builder.Append(i);
            builder.Append(':');
            builder.Append(word0.ToString("x8"));
            builder.Append('/');
            builder.Append(word4.ToString("x8"));
            builder.Append('/');
            builder.Append(word8.ToString("x8"));
            builder.Append('/');
            builder.Append(text.Length == 0 ? "<empty>" : text);
        }

        return builder.ToString();
    }

    private void TraceKnownRuntimeBgLoadModelRecords(ulong pc)
    {
        if (!_traceRuntimeBgLoadModelRecords || _runtimeBgLoadModelRecordTraceCount >= 96)
            return;

        string label = pc switch
        {
            >= 0xffffffff800abaa0UL and <= 0xffffffff800abbc0UL => "qio-poll",
            >= 0xffffffff800abc60UL and <= 0xffffffff800abe40UL => "stream-dispatch",
            >= 0xffffffff800abec0UL and <= 0xffffffff800abf40UL => "late-stream",
            >= 0xffffffff800ac040UL and <= 0xffffffff800ac13cUL => "global-init",
            >= 0xffffffff800ac1f0UL and <= 0xffffffff800ac248UL => "record-init",
            >= 0xffffffff800ac2d0UL and <= 0xffffffff800ac370UL => "model-create",
            >= 0xffffffff800ac3f0UL and <= 0xffffffff800ac4f0UL => "state-qio",
            >= 0xffffffff800c92f0UL and <= 0xffffffff800c9328UL => "qio-clear",
            >= 0xffffffff800c9600UL and <= 0xffffffff800c9820UL => "qio-create",
            _ => ""
        };
        if (label.Length == 0)
            return;

        if (_memory.Read32(0xffffffff800abaa0UL) != 0x27bdffd8U ||
            _memory.Read32(0xffffffff800ac074UL) != 0xac400004U ||
            _memory.Read32(0xffffffff800ac220UL) != 0xae000000U ||
            _memory.Read32(0xffffffff800c92f4UL) != 0x8fc20010U ||
            _memory.Read32(0xffffffff800c9678UL) != 0x8fc40020U)
        {
            return;
        }

        _runtimeBgLoadModelRecordTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:TRACE] bgloadmodel-records {label} pc={pc:x16} op={_memory.Read32(pc):x8} " +
            $"ra={_gpr[31]:x16} sp={_gpr[29]:x16} a0={_gpr[4]:x16} a1={_gpr[5]:x16} " +
            $"a2={_gpr[6]:x16} a3={_gpr[7]:x16} v0={_gpr[2]:x16} v1={_gpr[3]:x16} " +
            $"s0={_gpr[16]:x16} s1={_gpr[17]:x16} s2={_gpr[18]:x16} s8={_gpr[30]:x16} " +
            $"g8060={ReadTraceWord(0xffffffff80238060UL):x8} g8068={ReadTraceWord(0xffffffff80238068UL):x8} " +
            $"gf154={ReadTraceWord(0xffffffff8021f154UL):x8} gf158={ReadTraceWord(0xffffffff8021f158UL):x8} " +
            $"gf15c={ReadTraceWord(0xffffffff8021f15cUL):x8} gf168={ReadTraceWord(0xffffffff8021f168UL):x8} " +
            $"gf178={ReadTraceWord(0xffffffff8021f178UL):x8} gf17c={ReadTraceWord(0xffffffff8021f17cUL):x8} " +
            $"gf180={ReadTraceWord(0xffffffff8021f180UL):x8} gf184={ReadTraceWord(0xffffffff8021f184UL):x8} " +
            $"records={TraceKnownRuntimeBgLoadModelRecordSummary()} " +
            $"qio={TraceKnownRuntimeBgLoadModelQioSummary()}");
    }

    private void TraceKnownRuntimeBgLoadModelStateDelta(ulong pc, string phase)
    {
        if (!_traceRuntimeBgLoadModelStateDelta || _runtimeBgLoadModelStateDeltaTraceCount >= 96)
            return;
        if (phase == "step" && (_instructionCounter & 0xfffUL) != 0)
            return;

        string snapshot =
            $"g8060={ReadTraceWord(0xffffffff80238060UL):x8} " +
            $"g8068={ReadTraceWord(0xffffffff80238068UL):x8} " +
            $"gf154={ReadTraceWord(0xffffffff8021f154UL):x8} " +
            $"gf158={ReadTraceWord(0xffffffff8021f158UL):x8} " +
            $"gf15c={ReadTraceWord(0xffffffff8021f15cUL):x8} " +
            $"gf168={ReadTraceWord(0xffffffff8021f168UL):x8} " +
            $"gf178={ReadTraceWord(0xffffffff8021f178UL):x8} " +
            $"gf17c={ReadTraceWord(0xffffffff8021f17cUL):x8} " +
            $"gf180={ReadTraceWord(0xffffffff8021f180UL):x8} " +
            $"gf184={ReadTraceWord(0xffffffff8021f184UL):x8} " +
            $"records={TraceKnownRuntimeBgLoadModelRecordSummary()} " +
            $"qio={TraceKnownRuntimeBgLoadModelQioSummary()}";

        if (_runtimeBgLoadModelStateSnapshot == snapshot)
            return;

        _runtimeBgLoadModelStateSnapshot = snapshot;
        _runtimeBgLoadModelStateDeltaTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:TRACE] bgloadmodel-state-delta phase={phase} pc={pc:x16} op={_memory.Read32(pc):x8} " +
            $"ra={_gpr[31]:x16} sp={_gpr[29]:x16} a0={_gpr[4]:x16} a1={_gpr[5]:x16} " +
            $"a2={_gpr[6]:x16} a3={_gpr[7]:x16} v0={_gpr[2]:x16} v1={_gpr[3]:x16} " +
            $"s0={_gpr[16]:x16} s1={_gpr[17]:x16} s2={_gpr[18]:x16} s8={_gpr[30]:x16} " +
            snapshot);
    }

    private string TraceKnownRuntimeBgLoadModelRecordSummary()
    {
        const ulong modelRecordBase = 0xffffffff80252da0UL;
        const ulong modelRecordStride = 0x18UL;

        StringBuilder builder = new();
        for (int index = 0; index < 8; index++)
        {
            ulong record = modelRecordBase + (ulong)index * modelRecordStride;
            if (!IsMainRamRange(record + 0x14UL, 4))
                break;

            if (builder.Length > 0)
                builder.Append(';');
            builder.Append(index);
            builder.Append(':');
            builder.Append(_memory.Read32(record + 0x00UL).ToString("x8"));
            builder.Append('/');
            builder.Append(_memory.Read32(record + 0x04UL).ToString("x8"));
            builder.Append('/');
            builder.Append(_memory.Read32(record + 0x08UL).ToString("x8"));
            builder.Append('/');
            builder.Append(_memory.Read32(record + 0x0cUL).ToString("x8"));
            builder.Append('/');
            builder.Append(_memory.Read32(record + 0x10UL).ToString("x8"));
        }

        return builder.ToString();
    }

    private string TraceKnownRuntimeBgLoadModelQioSummary()
    {
        const ulong qioBase = 0xffffffff80217c58UL;
        const ulong qioStride = 0x118UL;

        StringBuilder builder = new();
        for (int index = 0; index < 4; index++)
        {
            ulong qio = qioBase + (ulong)index * qioStride;
            if (!IsMainRamRange(qio + 0x18UL, 4))
                break;

            if (builder.Length > 0)
                builder.Append(';');
            builder.Append(index);
            builder.Append(':');
            builder.Append(_memory.Read32(qio + 0x00UL).ToString("x8"));
            builder.Append('/');
            builder.Append(_memory.Read32(qio + 0x04UL).ToString("x8"));
            builder.Append('/');
            builder.Append(_memory.Read32(qio + 0x08UL).ToString("x8"));
            builder.Append('/');
            builder.Append(_memory.Read32(qio + 0x0cUL).ToString("x8"));
            builder.Append('/');
            builder.Append(_memory.Read32(qio + 0x10UL).ToString("x8"));
            builder.Append('/');
            builder.Append(_memory.Read32(qio + 0x14UL).ToString("x8"));
            string path = ReadAsciiTraceString(qio + 0x18UL, 32);
            if (path.Length > 0)
            {
                builder.Append('/');
                builder.Append(path);
            }
        }

        return builder.ToString();
    }

    private void TraceKnownLateRenderPump(ulong pc)
    {
        if (!_traceLateRenderPump || _lateRenderPumpTraceCount >= 192)
            return;

        string label = pc switch
        {
            >= 0xffffffff800e3decUL and <= 0xffffffff800e3ea0UL => "diagnostic-draw-pump",
            >= 0xffffffff800b1dc4UL and <= 0xffffffff800b1dd0UL => "global-808c-exchange",
            >= 0xffffffff800b1ba0UL and <= 0xffffffff800b1c20UL => "render-list-walk",
            >= 0xffffffff800e3378UL and <= 0xffffffff800e33f0UL => "runtime-text-draw",
            >= 0xffffffff80121670UL and <= 0xffffffff801216bcUL => "diagnostic-format-line",
            >= 0xffffffff80102520UL and <= 0xffffffff801035c0UL => "runtime-state-bit",
            >= 0xffffffff80103ba0UL and <= 0xffffffff80103c40UL => "runtime-state-present",
            >= 0xffffffff801046a0UL and <= 0xffffffff80104740UL => "runtime-state-select",
            _ => ""
        };
        if (label.Length == 0)
            return;

        _lateRenderPumpTraceCount++;
        ulong textAddress = pc is >= 0xffffffff800e3378UL and <= 0xffffffff800e33f0UL ? _gpr[6] :
            pc is >= 0xffffffff80121670UL and <= 0xffffffff801216bcUL ? _gpr[4] : 0;
        string text = textAddress == 0 ? "" : ReadAsciiTraceString(textAddress, 80);
        Console.WriteLine(
            $"[GAUNTDL:LATE] {label} pc={pc:x16} op={_memory.Read32(pc):x8} " +
            $"ra={_gpr[31]:x16} sp={_gpr[29]:x16} a0={_gpr[4]:x16} a1={_gpr[5]:x16} " +
            $"a2={_gpr[6]:x16} a3={_gpr[7]:x16} v0={_gpr[2]:x16} v1={_gpr[3]:x16} " +
            $"s0={_gpr[16]:x16} s1={_gpr[17]:x16} s2={_gpr[18]:x16} s8={_gpr[30]:x16} " +
            $"d900={ReadTraceWord(0xffffffff8022d900UL):x8} d904={ReadTraceWord(0xffffffff8022d904UL):x8} " +
            $"g819c={ReadTraceWord(0xffffffff8023819cUL):x8} g81a4={ReadTraceWord(0xffffffff802381a4UL):x8} " +
            $"g81b0={ReadTraceWord(0xffffffff802381b0UL):x8} g81c0={ReadTraceWord(0xffffffff802381c0UL):x8} " +
            $"g81c4={ReadTraceWord(0xffffffff802381c4UL):x8} " +
            $"worldSelected={ReadTraceWord(0xffffffff8016c13cUL):x8} worldCount={ReadTraceWord(0xffffffff8016c148UL):x8} " +
            $"worldTable={ReadTraceWord(0xffffffff8016c14cUL):x8} loader08={ReadTraceWord(0xffffffff80227c98UL):x8} " +
            $"loader18={ReadTraceWord(0xffffffff80227ca8UL):x8} loader78={ReadTraceWord(0xffffffff80227d08UL):x8} " +
            $"g808c={ReadTraceWord(0xffffffff8022808cUL):x8} g8134={ReadTraceWord(0xffffffff80228134UL):x8} " +
            $"g71a4={ReadTraceWord(0xffffffff802171a4UL):x8} g71a8={ReadTraceWord(0xffffffff802171a8UL):x8} " +
            $"g3b0c={ReadTraceWord(0xffffffff80163b0cUL):x8} g3b10={ReadTraceWord(0xffffffff80163b10UL):x8} " +
            $"g3b14={ReadTraceWord(0xffffffff80163b14UL):x8} obj2d64={ReadTraceWord(0xffffffff80262d64UL):x8} " +
            $"text=\"{text}\"");
    }

    private void ApplyKnownRuntimeRenderListSaturationRepair(ulong pc)
    {
        if (!_enableDiagnosticRuntimeFastPaths)
            return;

        const ulong entry = 0xffffffff800b1ba0UL;
        const ulong listCount = 0xffffffff80213600UL;
        if (pc != entry)
            return;

        if (_memory.Read32(entry + 0x00UL) != 0x27bdffd0U ||
            _memory.Read32(entry + 0x08UL) != 0x3c138021U ||
            _memory.Read32(entry + 0x0cUL) != 0x8e623600U ||
            _memory.Read32(entry + 0x34UL) != 0x2842012bU ||
            _memory.Read32(entry + 0x38UL) != 0x10400045U)
        {
            return;
        }

        uint count = _memory.Read32(listCount);
        if (count < 0x12bU)
            return;

        _memory.Write32(listCount, 0);
        if (_runtimeRenderListSaturationRepairTraceCount++ < 8)
        {
            Console.WriteLine(
                $"[GAUNTDL:FIX] render-list-saturation pc={pc:x16} " +
                $"count={count:x8}->00000000 frameTick={ReadTraceWord(0xffffffff80228114UL):x8}");
        }
    }

    private void TraceKnownRuntimeLoadingResetHelper(ulong pc)
    {
        if (!_traceRuntimeLoadingResetHelper ||
            _runtimeLoadingResetHelperTraceCount >= _traceRuntimeLoadingResetHelperLimit)
        {
            return;
        }

        const ulong helper = 0xffffffff800c8400UL;
        const ulong caller = 0xffffffff800c843cUL;
        if (pc != caller &&
            pc != caller + 0x14UL &&
            pc != helper + 0x20UL &&
            pc != helper + 0x24UL &&
            pc != helper + 0x2cUL &&
            pc != helper + 0x38UL &&
            pc != caller + 0x1cUL)
        {
            return;
        }

        if (_memory.Read32(helper + 0x00UL) != 0x24030027U ||
            _memory.Read32(helper + 0x08UL) != 0x244271b8U ||
            _memory.Read32(helper + 0x10UL) != 0xa0400000U ||
            _memory.Read32(helper + 0x18UL) != 0x0461fffdU ||
            _memory.Read32(helper + 0x24UL) != 0xa04071b0U ||
            _memory.Read32(helper + 0x2cUL) != 0xa04071b1U ||
            _memory.Read32(helper + 0x38UL) != 0xa04071b2U ||
            _memory.Read32(caller + 0x00UL) != 0x27bdffe8U ||
            _memory.Read32(caller + 0x0cUL) != 0x0c032100U ||
            _memory.Read32(caller + 0x14UL) != 0x3c038023U ||
            _memory.Read32(caller + 0x1cUL) != 0x24020008U)
        {
            return;
        }

        _runtimeLoadingResetHelperTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:TRACE] loading-reset-helper pc={pc:x16} " +
            $"ra={_gpr[31]:x16} v0={_gpr[2]:x16} v1={_gpr[3]:x16} " +
            $"b171b0={ReadTraceByte(0xffffffff802171b0UL):x2} " +
            $"b171b1={ReadTraceByte(0xffffffff802171b1UL):x2} " +
            $"b171b2={ReadTraceByte(0xffffffff802171b2UL):x2} " +
            $"w171b8={ReadTraceWord(0xffffffff802171b8UL):x8} " +
            $"w17338={ReadTraceWord(0xffffffff80217338UL):x8} " +
            $"w17738={ReadTraceWord(0xffffffff80217738UL):x8} " +
            $"w17b78={ReadTraceWord(0xffffffff80217b78UL):x8} " +
            $"w380dc={ReadTraceWord(0xffffffff802380dcUL):x8}");
    }

    private void ApplyKnownRuntimeDiagnosticOverlaySuppress(ulong pc)
    {
        if (!_experimentRuntimeDiagnosticOverlaySuppress)
            return;

        const ulong entry = 0xffffffff800c7c10UL;
        if (pc != entry)
            return;

        if (_memory.Read32(entry + 0x00UL) != 0x0200202dU ||
            _memory.Read32(entry + 0x04UL) != 0x0c02c771U ||
            _memory.Read32(entry + 0x08UL) != 0x0040802dU ||
            _memory.Read32(entry + 0x0cUL) != 0x12000014U)
        {
            return;
        }

        const ulong overlay0 = 0xffffffff80163b0cUL;
        const ulong overlay1 = 0xffffffff80163b10UL;
        const ulong overlay2 = 0xffffffff80163b14UL;
        const ulong overlay3 = 0xffffffff80163b18UL;
        uint flag0 = _memory.Read32(overlay0);
        uint flag1 = _memory.Read32(overlay1);
        uint flag2 = _memory.Read32(overlay2);
        uint flag3 = _memory.Read32(overlay3);
        if ((flag0 | flag1 | flag2 | flag3) == 0)
            return;

        _memory.Write32(overlay0, 0);
        _memory.Write32(overlay1, 0);
        _memory.Write32(overlay2, 0);
        _memory.Write32(overlay3, 0);
        if (_runtimeDiagnosticOverlaySuppressTraceCount++ < 8)
        {
            Console.WriteLine(
                $"[GAUNTDL:EXPERIMENT] diagnostic-overlay-suppress pc={pc:x16} " +
                $"flags={flag0:x8}/{flag1:x8}/{flag2:x8}/{flag3:x8}->00000000/00000000/00000000/00000000");
        }
    }

    private uint ReadTraceWord(ulong address)
        => IsMainRamRange(address, 4) ? _memory.Read32(address) : 0xffffffffU;

    private uint ReadTraceByte(ulong address)
        => IsMainRamRange(address, 1) ? _memory.Read8(address) : 0xffU;

    private bool TryFastPathKnownRuntimeBgLoadModelDispatchPrologue(ulong pc)
    {
        const ulong entry = 0xffffffff8011d590UL;
        if (!_enableRuntimeBgLoadModelDispatchFastPath || pc != entry)
            return false;

        if (_memory.Read32(entry + 0x00UL) != 0x27bdffc8U ||
            _memory.Read32(entry + 0x04UL) != 0xafb10014U ||
            _memory.Read32(entry + 0x08UL) != 0x0080882dU ||
            _memory.Read32(entry + 0x0cUL) != 0xafbe0030U ||
            _memory.Read32(entry + 0x10UL) != 0x00a0f02dU ||
            _memory.Read32(entry + 0x14UL) != 0xafbf0034U ||
            _memory.Read32(entry + 0x18UL) != 0xafb7002cU ||
            _memory.Read32(entry + 0x1cUL) != 0xafb60028U ||
            _memory.Read32(entry + 0x20UL) != 0xafb50024U ||
            _memory.Read32(entry + 0x24UL) != 0xafb40020U ||
            _memory.Read32(entry + 0x28UL) != 0xafb3001cU ||
            _memory.Read32(entry + 0x2cUL) != 0xafb20018U ||
            _memory.Read32(entry + 0x30UL) != 0x12200019U ||
            _memory.Read32(entry + 0x34UL) != 0xafb00010U)
        {
            return false;
        }

        ulong newSp = _gpr[29] - 0x38UL;
        if (!IsMainRamRange(newSp + 0x10UL, 0x28UL))
            return false;

        _memory.Write32(newSp + 0x14UL, (uint)_gpr[17]);
        _memory.Write32(newSp + 0x30UL, (uint)_gpr[30]);
        _memory.Write32(newSp + 0x34UL, (uint)_gpr[31]);
        _memory.Write32(newSp + 0x2cUL, (uint)_gpr[23]);
        _memory.Write32(newSp + 0x28UL, (uint)_gpr[22]);
        _memory.Write32(newSp + 0x24UL, (uint)_gpr[21]);
        _memory.Write32(newSp + 0x20UL, (uint)_gpr[20]);
        _memory.Write32(newSp + 0x1cUL, (uint)_gpr[19]);
        _memory.Write32(newSp + 0x18UL, (uint)_gpr[18]);
        _memory.Write32(newSp + 0x10UL, (uint)_gpr[16]);
        _gpr[29] = newSp;
        _gpr[17] = _gpr[4];
        _gpr[30] = _gpr[5];
        Pc = entry + 0x30UL;
        CompleteFastPathStep();
        return true;
    }

    private void ApplyKnownRuntimeBgLoadModelQioCompletion(ulong pc)
    {
        const ulong entry = 0xffffffff800abaa0UL;
        if (!_enableRuntimeBgLoadModelDispatchFastPath || pc is < entry or > 0xffffffff800abab8UL)
            return;

        if (_memory.Read32(entry + 0x00UL) != 0x27bdffd8U ||
            _memory.Read32(entry + 0x04UL) != 0xafb20020U ||
            _memory.Read32(entry + 0x08UL) != 0x3c128023U ||
            _memory.Read32(entry + 0x0cUL) != 0x8e428060U)
        {
            return;
        }

        const ulong modelRecordBase = 0xffffffff80252da0UL;
        const ulong modelRecordStride = 0x18UL;
        const uint qioCompleteStatus = 2;
        const int maxActiveModelRecords = 0x40;

        for (int modelIndex = 0; modelIndex < maxActiveModelRecords; modelIndex++)
        {
            ulong record = modelRecordBase + (ulong)modelIndex * modelRecordStride;
            if (!IsMainRamRange(record + 0x14UL, 4))
                return;

            ulong qio = SignExtend32(_memory.Read32(record + 0x08UL));
            if (!IsMainRamRange(qio + 0x18UL, 4))
                continue;

            uint requestedByteCount = _memory.Read32(qio + 0x0cUL);
            if (requestedByteCount == 0 || requestedByteCount > 0x20000U)
                continue;

            uint objectStatus = 0;
            ulong qioObject = SignExtend32(_memory.Read32(qio + 0x00UL));
            if (IsMainRamRange(qioObject + 0x14UL, 4))
                objectStatus = _memory.Read32(qioObject + 0x14UL);

            uint status = _memory.Read32(qio + 0x14UL);
            if (status == qioCompleteStatus)
                continue;

            uint callback = _memory.Read32(qio + 0x04UL);
            uint pathSignature = _memory.Read32(qio + 0x18UL);
            bool hasPath = pathSignature == 0x2f30642fU; // "/d0/" in little-endian RAM.
            bool knownGauntletBgLoad = requestedByteCount == 0x2000U &&
                                       callback == 0x800ab4e4U &&
                                       (objectStatus & 0xffffU) == 0x300bU;
            bool knownPendingStatus = status == 0 || (status == 0xffffffffU && knownGauntletBgLoad);
            if (!knownPendingStatus || (!hasPath && !knownGauntletBgLoad))
                continue;

            string hydrationStatus = "unmapped";
            string hydrationReason = "";
            if (_enableRuntimeBgLoadModelQioHydration &&
                TryHydrateKnownRuntimeBgLoadModelQio(qio, qioObject, requestedByteCount, out hydrationReason))
                hydrationStatus = $"hydrated:{hydrationReason}";
            else if (!string.IsNullOrWhiteSpace(hydrationReason))
                hydrationStatus = hydrationReason;
            if (IsMainRamRange(qioObject + 0x14UL, 4))
            {
                if ((objectStatus & 0xffU) != 0)
                {
                    uint repairedObjectStatus = objectStatus & 0xffffff00U;
                    if (repairedObjectStatus != 0)
                        _memory.Write32(qioObject + 0x14UL, repairedObjectStatus);
                }
            }

            _memory.Write32(qio + 0x10UL, requestedByteCount);
            _memory.Write32(qio + 0x14UL, qioCompleteStatus);
            if (_runtimeBgLoadModelQioCompleteTraceCount++ < 8)
            {
                Console.WriteLine(
                    $"[GAUNTDL:FIX] bgloadmodel qio-complete index={modelIndex} record={record:x16} " +
                    $"qio={qio:x16} object={qioObject:x16} objectStatus={objectStatus:x8} " +
                    $"bytes={requestedByteCount:x8} data={hydrationStatus}");
            }
        }
    }

    private bool TryHydrateKnownRuntimeBgLoadModelQio(
        ulong qio,
        ulong qioObject,
        uint requestedByteCount,
        out string reason)
    {
        reason = "";
        ulong destination = SignExtend32(_memory.Read32(qio + 0x08UL));
        if (!IsMainRamRange(destination, requestedByteCount))
        {
            reason = $"dest-range:{destination:x16}";
            return false;
        }

        string path = ReadAsciiTraceString(qio + 0x18UL, 0x100);
        uint callback = IsMainRamRange(qio + 0x04UL, 4) ? _memory.Read32(qio + 0x04UL) : 0;
        const ulong qioBase = 0xffffffff80217c58UL;
        const ulong qioStride = 0x118UL;
        ulong qioIndex = qio >= qioBase && (qio - qioBase) % qioStride == 0
            ? (qio - qioBase) / qioStride
            : ulong.MaxValue;

        ulong? directBase = ParseOptionalHexUlong("EUTHERDRIVE_GAUNTDL_FIX_RUNTIME_BGLOADMODEL_QIO_HYDRATE_DIRECT_BASE");
        if (directBase.HasValue &&
            string.IsNullOrEmpty(path) &&
            requestedByteCount == 0x2000U &&
            callback == 0x800ab4e4U &&
            qioIndex is > 0 and < 0x40)
        {
            ulong directOffset = directBase.Value + (qioIndex - 1UL) * requestedByteCount;
            if (!_memory.TryReadDiskByteOffsetToMemory(directOffset, destination, requestedByteCount, out uint directFirstWord, out reason))
                return false;

            TraceRuntimeBgLoadModelHydrationRange(
                "qio-direct",
                destination,
                requestedByteCount,
                directOffset,
                $"index={qioIndex}/first={directFirstWord:x8}");
            reason = $"direct@{directOffset:x8}/index={qioIndex}/first={directFirstWord:x8}";
            return true;
        }

        string indexedTextureCode = "";
        ulong indexedTextureByteOffset = 0;
        uint indexedTextureByteLength = 0;
        bool hasKnownIndexedTexturePayload =
            string.IsNullOrEmpty(path) &&
            requestedByteCount == 0x2000U &&
            callback == 0x800ab4e4U &&
            !GauntletDarkLegacyAdapter.IsTruthy(Environment.GetEnvironmentVariable("EUTHERDRIVE_GAUNTDL_EXPERIMENT_BGLOADMODEL_DISABLE_INDEXED_TEXTURE_PAYLOADS")) &&
            qioIndex is > 0 and < 0x40 &&
            TryGetKnownRuntimeBgLoadModelTexturePayload(qioIndex, out indexedTextureCode, out indexedTextureByteOffset, out indexedTextureByteLength);

        ulong mappedFileBaseLba = path switch
        {
            "/d0/static_lr/textures.rom" => 0x0007d000UL,
            "/d0/static_lr/objects.rom" => 0x0007d970UL,
            _ => requestedByteCount == 0x2000U && callback == 0x800ab4e4U && !hasKnownIndexedTexturePayload ? 0x0007d000UL : 0
        };
        ulong fileState = IsMainRamRange(qioObject, 4) ? SignExtend32(_memory.Read32(qioObject)) : 0;
        if (!IsMainRamRange(fileState + 0x118UL, 4))
        {
            reason = $"state-range:{fileState:x16}";
            return false;
        }

        uint stateLba = _memory.Read32(fileState + 0x118UL);
        bool useStateLba =
            GauntletDarkLegacyAdapter.IsTruthy(Environment.GetEnvironmentVariable("EUTHERDRIVE_GAUNTDL_FIX_RUNTIME_BGLOADMODEL_QIO_HYDRATE_STATE_LBA"));
        ulong fileBaseLba = useStateLba ? stateLba : mappedFileBaseLba;
        if (fileBaseLba == 0)
        {
            reason = $"path:{path}/stateLba={stateLba:x8}";
            return false;
        }

        uint currentOffset = _memory.Read32(fileState + 0x114UL);
        bool useCurrentOffset =
            GauntletDarkLegacyAdapter.IsTruthy(Environment.GetEnvironmentVariable("EUTHERDRIVE_GAUNTDL_FIX_RUNTIME_BGLOADMODEL_QIO_HYDRATE_CURRENT_OFFSET"));
        ulong readOffset = useCurrentOffset
            ? currentOffset
            : currentOffset >= requestedByteCount
                ? currentOffset - requestedByteCount
                : 0UL;
        string offsetMode = useCurrentOffset ? "current" : "previous";
        if (path == "/d0/static_lr/objects.rom" &&
            requestedByteCount == 0x2000U &&
            callback == 0x800ab4e4U)
        {
            readOffset = 0;
            offsetMode = "static-lr-objects";
        }
        else if (path == "/d0/static_lr/textures.rom" &&
            requestedByteCount == 0x2000U &&
            currentOffset is >= 0x00440000U and <= 0x00446000U)
        {
            readOffset = _enableRuntimeBgLoadModelStaticPathLifecycle
                ? 0x001b0600UL
                : 0x001b0830UL;
            offsetMode = _enableRuntimeBgLoadModelStaticPathLifecycle
                ? "static-lr-textures-file"
                : "static-lr-bgmodel";
        }
        else if (string.IsNullOrEmpty(path) &&
                 requestedByteCount == 0x2000U &&
                 callback == 0x800ab4e4U &&
                 !hasKnownIndexedTexturePayload)
        {
            readOffset = 0x001b0830UL;
            offsetMode = "static-lr-bgmodel-callback";
        }

        ulong? forcedReadOffset = ParseOptionalHexUlong("EUTHERDRIVE_GAUNTDL_FIX_RUNTIME_BGLOADMODEL_QIO_HYDRATE_READ_OFFSET");
        if (forcedReadOffset.HasValue)
        {
            readOffset = forcedReadOffset.Value;
            offsetMode = "forced";
        }

        if (hasKnownIndexedTexturePayload)
        {
            if (readOffset >= indexedTextureByteLength)
            {
                reason = $"texture-index={qioIndex}/{indexedTextureCode}/offset-range:{readOffset:x8}/size={indexedTextureByteLength:x8}";
                return false;
            }

            ulong availableBytes = indexedTextureByteLength - readOffset;
            if (availableBytes < requestedByteCount)
            {
                for (uint offset = 0; offset < requestedByteCount; offset++)
                    _memory.Write8(destination + offset, 0);

                requestedByteCount = (uint)availableBytes;
            }

            ulong indexedDiskByteOffset = indexedTextureByteOffset + readOffset;
            if (!_memory.TryReadDiskByteOffsetToMemory(indexedDiskByteOffset, destination, requestedByteCount, out uint indexedFirstWord, out reason))
                return false;

            TraceRuntimeBgLoadModelHydrationRange(
                "qio-indexed-texture",
                destination,
                requestedByteCount,
                indexedDiskByteOffset,
                $"index={qioIndex}/{indexedTextureCode}@{readOffset:x8}/{offsetMode}/first={indexedFirstWord:x8}");
            reason = $"texture-index={qioIndex}/{indexedTextureCode}@{readOffset:x8}/{offsetMode}/byte={indexedDiskByteOffset:x8}/first={indexedFirstWord:x8}";
            return true;
        }

        bool useStaticObjectOwner =
            _experimentRuntimeBgLoadModelStaticObjectOwner &&
            qioIndex == 0 &&
            string.IsNullOrEmpty(path) &&
            requestedByteCount == 0x2000U &&
            callback == 0x800ab4e4U;
        ulong diskByteOffset = useStaticObjectOwner
            ? _experimentRuntimeBgLoadModelStaticObjectDiskBase
            : fileBaseLba * 512UL + readOffset;
        if (!_memory.TryReadDiskByteOffsetToMemory(diskByteOffset, destination, requestedByteCount, out uint firstWord, out reason))
            return false;

        string objectTableStatus = "";
        if (_enableRuntimeBgLoadModelStaticPathLifecycle &&
            path == "/d0/static_lr/textures.rom" &&
            requestedByteCount == 0x2000U &&
            callback == 0x800ab4e4U)
        {
            const uint textureByteLength = 0x000c3674U;
            uint directoryOffset = ReadTraceWord(destination + 0x50UL);
            uint bodyEndOffset = ReadTraceWord(destination + 0x58UL);
            uint payloadEndOffset = ReadTraceWord(destination + 0x5cUL);
            uint directoryStride = ReadTraceWord(destination + 0x60UL);
            uint directoryCount = ReadTraceWord(destination + 0x64UL);
            uint continuationBytes = textureByteLength - requestedByteCount;
            uint continuationFirstWord = 0;
            string continuationFailure = "header";
            if (directoryOffset != 0x0000002cU ||
                bodyEndOffset != 0x000c2bb8U ||
                payloadEndOffset != 0x000c2fd8U ||
                directoryStride != 0x00000188U ||
                directoryCount != 0x0000002fU ||
                payloadEndOffset >= textureByteLength ||
                !IsMainRamRange(destination, textureByteLength) ||
                !_memory.TryReadDiskByteOffsetToMemory(
                    diskByteOffset + requestedByteCount,
                    destination + requestedByteCount,
                    continuationBytes,
                    out continuationFirstWord,
                    out continuationFailure))
            {
                reason =
                    $"static-path-texture-body:{directoryOffset:x8}/{bodyEndOffset:x8}/" +
                    $"{payloadEndOffset:x8}/{directoryStride:x8}/{directoryCount:x8}/{continuationFailure}";
                return false;
            }

            objectTableStatus =
                $"/static-path-texture-body={requestedByteCount:x8}+{continuationBytes:x8}" +
                $"/directory={directoryOffset:x8}/stride={directoryStride:x8}/count={directoryCount:x8}" +
                $"/first={continuationFirstWord:x8}";
            TryReserveKnownRuntimeBgLoadModelStaticPathHeap(destination, textureByteLength, ref objectTableStatus);
        }
        if ((_enableRuntimeBgLoadModelStaticPathLifecycle || _enableRuntimeBgLoadModelStaticObjectBodyRead) &&
            path == "/d0/static_lr/objects.rom" &&
            requestedByteCount == 0x2000U &&
            callback == 0x800ab4e4U)
        {
            const uint objectByteLength = 0x00067b4cU;
            uint signature = ReadTraceWord(destination + 0x40UL);
            uint bodyOffset = ReadTraceWord(destination + 0x5cUL);
            uint tableIndex = ReadTraceWord(destination + 0x60UL);
            uint recordCount = ReadTraceWord(destination + 0x64UL);
            ulong tableOffset = 0x68UL + (ulong)tableIndex * 0x8cUL;
            ulong tableBytes = (ulong)recordCount * 0x50UL;
            uint continuationBytes = objectByteLength - requestedByteCount;
            uint continuationFirstWord = 0;
            string continuationFailure = "header";
            if (signature != 0xf00b0001U ||
                bodyOffset != 0x00067a98U ||
                tableIndex != 0x149U ||
                recordCount != 0x2eU ||
                tableOffset != 0xb454UL ||
                tableOffset + tableBytes > objectByteLength ||
                !IsMainRamRange(destination, objectByteLength) ||
                !_memory.TryReadDiskByteOffsetToMemory(
                    diskByteOffset + requestedByteCount,
                    destination + requestedByteCount,
                    continuationBytes,
                    out continuationFirstWord,
                    out continuationFailure))
            {
                reason =
                    $"static-path-object-body:{signature:x8}/{bodyOffset:x8}/{tableIndex:x8}/" +
                    $"{recordCount:x8}/{tableOffset:x8}/{tableBytes:x8}/{continuationFailure}";
                return false;
            }

            objectTableStatus =
                $"/static-path-object-body={requestedByteCount:x8}+{continuationBytes:x8}" +
                $"/table={tableOffset:x8}+{tableBytes:x8}/first={continuationFirstWord:x8}";
        }
        if (useStaticObjectOwner)
        {
            uint signature = ReadTraceWord(destination + 0x40UL);
            uint tableIndex = ReadTraceWord(destination + 0x60UL);
            uint recordCount = ReadTraceWord(destination + 0x64UL);
            ulong tableOffset = 0x68UL + (ulong)tableIndex * 0x8cUL;
            ulong tableBytes = (ulong)recordCount * 0x50UL;
            uint tableFirstWord = 0;
            string tableFailure = "";
            bool validTable =
                signature == 0xf00b0001U &&
                recordCount is > 0 and <= 0x100U &&
                tableOffset <= 0x100000UL && tableBytes <= 0x10000UL &&
                IsMainRamRange(destination + tableOffset, tableBytes) &&
                _memory.TryReadDiskByteOffsetToMemory(
                    diskByteOffset + tableOffset,
                    destination + tableOffset,
                    (uint)tableBytes,
                    out tableFirstWord,
                    out tableFailure);
            if (!validTable)
            {
                reason = $"static-object-table:{signature:x8}/{tableIndex:x8}/{recordCount:x8}/{tableOffset:x8}/{tableBytes:x8}/{tableFailure}";
                return false;
            }

            objectTableStatus = $"/static-object/table={tableOffset:x8}+{tableBytes:x8}/first={tableFirstWord:x8}";

            if (_experimentRuntimeBgLoadModelStaticObjectCompanionOwner)
            {
                const ulong companionHeaderBytes = 4UL;
                ulong companionDestination =
                    destination + _experimentRuntimeBgLoadModelStaticObjectByteLength + companionHeaderBytes;
                uint companionFirstWord = 0;
                string companionFailure = "range";
                if (!IsMainRamRange(companionDestination, _experimentRuntimeBgLoadModelStaticObjectCompanionByteLength) ||
                    !_memory.TryReadDiskByteOffsetToMemory(
                        _experimentRuntimeBgLoadModelStaticObjectCompanionDiskBase,
                        companionDestination,
                        _experimentRuntimeBgLoadModelStaticObjectCompanionByteLength,
                        out companionFirstWord,
                        out companionFailure))
                {
                    reason = $"static-object-companion:{companionDestination:x8}/{_experimentRuntimeBgLoadModelStaticObjectCompanionByteLength:x8}/{companionFailure}";
                    return false;
                }

                objectTableStatus +=
                    $"/companion={_experimentRuntimeBgLoadModelStaticObjectCompanionDiskBase:x8}" +
                    $"->{companionDestination:x8}+{_experimentRuntimeBgLoadModelStaticObjectCompanionByteLength:x8}" +
                    $"/first={companionFirstWord:x8}";
            }
        }

        TraceRuntimeBgLoadModelHydrationRange(
            "qio-mapped",
            destination,
            requestedByteCount,
            diskByteOffset,
            $"path={path}/readOffset={readOffset:x8}/{offsetMode}/base={fileBaseLba:x8}/{(useStateLba ? "state" : "mapped")}/first={firstWord:x8}");
        reason = useStaticObjectOwner
            ? $"static-objects@{diskByteOffset:x8}/first={firstWord:x8}{objectTableStatus}"
            : $"{path}@{readOffset:x8}/{offsetMode}/base={fileBaseLba:x8}/{(useStateLba ? "state" : "mapped")}/first={firstWord:x8}{objectTableStatus}";
        return true;
    }

    private void TryReserveKnownRuntimeBgLoadModelStaticPathHeap(
        ulong destination,
        uint byteLength,
        ref string status)
    {
        const ulong allocatorActiveAddress = 0xffffffff802280f8UL;
        const ulong allocatorOffsetAddress = 0xffffffff802280fcUL;
        const ulong allocatorLimitAddress = 0xffffffff80228100UL;
        const ulong allocatorBaseAddress = 0xffffffff80228104UL;

        if (!_enableRuntimeBgLoadModelStaticPathReserveHeap ||
            !IsMainRamRange(allocatorActiveAddress, 0x10UL) ||
            _memory.Read32(allocatorActiveAddress) != 1U)
        {
            return;
        }

        uint currentOffset = _memory.Read32(allocatorOffsetAddress);
        uint allocatorLimit = _memory.Read32(allocatorLimitAddress);
        ulong allocatorBase = SignExtend32(_memory.Read32(allocatorBaseAddress));
        ulong end = destination + byteLength;
        if (!IsMainRamRange(allocatorBase, 4UL) ||
            destination < allocatorBase ||
            end <= destination)
        {
            return;
        }

        ulong requiredOffset64 = (end - allocatorBase + 3UL) & ~3UL;
        if (requiredOffset64 > uint.MaxValue ||
            requiredOffset64 > allocatorLimit ||
            requiredOffset64 <= currentOffset)
        {
            return;
        }

        uint requiredOffset = (uint)requiredOffset64;
        _memory.Write32(allocatorOffsetAddress, requiredOffset);
        status += $"/heap={allocatorBase:x8}+{currentOffset:x8}->{requiredOffset:x8}/{allocatorLimit:x8}";
        if (_runtimeBgLoadModelStaticPathReserveHeapTraceCount++ < 8)
        {
            Console.WriteLine(
                $"[GAUNTDL:FIX] bgloadmodel-static-path-reserve-heap " +
                $"destination={destination:x16} bytes={byteLength:x8} end={end:x16} " +
                $"base={allocatorBase:x16} offset={currentOffset:x8}->{requiredOffset:x8} limit={allocatorLimit:x8}");
        }
    }

    private static bool TryGetKnownRuntimeBgLoadModelTexturePayload(
        ulong qioIndex,
        out string code,
        out ulong byteOffset,
        out uint byteLength)
    {
        code = "";
        byteOffset = 0;
        byteLength = 0;

        (string Code, ulong ByteOffset, uint ByteLength) entry = qioIndex switch
        {
            1 => ("gei", 0x14a6f600UL, 0x0000a13cU),
            2 => ("snm", 0x14a54800UL, 0x000091b0U),
            3 => ("stk", 0x15117a00UL, 0x0000a434U),
            4 => ("kjh", 0x15130e00UL, 0x00009ae8U),
            5 => ("pnk", 0x1514da00UL, 0x00009e80U),
            6 => ("geb", 0x15781600UL, 0x0000b130U),
            7 => ("nin", 0x15896000UL, 0x0000b130U),
            8 => ("stg", 0x1585d800UL, 0x0000acccU),
            9 => ("wtr", 0x158b0600UL, 0x0000bca4U),
            10 => ("css", 0x158cc800UL, 0x00009194U),
            11 => ("riz", 0x158ea800UL, 0x00009a00U),
            16 => ("get", 0x13380000UL, 0x00008e9cU),
            17 => ("sch", 0x13458e00UL, 0x0000b528U),
            18 => ("cel", 0x1339d800UL, 0x00014b98U),
            19 => ("gec", 0x12cbb200UL, 0x0000a3b8U),
            20 => ("gem", 0x12cdb000UL, 0x0000a460U),
            21 => ("rat", 0x12cfa600UL, 0x0000a5fcU),
            22 => ("ga2", 0x13bb9400UL, 0x00008ad8U),
            23 => ("gam", 0x13b9ce00UL, 0x0000b2c4U),
            24 => ("ged", 0x13b6ac00UL, 0x000142dcU),
            25 => ("gep", 0x13b82600UL, 0x00009550U),
            26 => ("sum", 0x13b4b600UL, 0x0000a37cU),
            _ => ("", 0, 0)
        };

        if (entry.ByteOffset == 0 || entry.ByteLength == 0)
            return false;

        code = entry.Code;
        byteOffset = entry.ByteOffset;
        byteLength = ApplyKnownRuntimeBgLoadModelTexturePayloadLengthOverride(qioIndex, entry.ByteLength);
        return true;
    }

    private static uint ApplyKnownRuntimeBgLoadModelTexturePayloadLengthOverride(ulong qioIndex, uint defaultLength)
    {
        string indexedName = $"EUTHERDRIVE_GAUNTDL_EXPERIMENT_RUNTIME_BGLOADMODEL_TEXTURE_PAYLOAD_INDEX{qioIndex}_LENGTH";
        ulong? overrideLength = ParseOptionalHexUlong(indexedName);
        if (!overrideLength.HasValue && qioIndex == 1)
            overrideLength = ParseOptionalHexUlong("EUTHERDRIVE_GAUNTDL_EXPERIMENT_RUNTIME_BGLOADMODEL_TEXTURE_PAYLOAD_GEI_LENGTH");

        if (!overrideLength.HasValue ||
            overrideLength.Value <= defaultLength ||
            overrideLength.Value > uint.MaxValue)
        {
            return defaultLength;
        }

        return (uint)overrideLength.Value;
    }

    private void ApplyKnownRuntimeWorldDataAllocationRepair(ulong pc)
    {
        if (!_enableRuntimeBgLoadModelDispatchFastPath)
            return;

        ulong fallbackBuffer = pc switch
        {
            0xffffffff8005d4fcUL => 0xffffffff81000000UL,
            0xffffffff8005d57cUL => 0xffffffff81400000UL,
            0xffffffff8005d5f0UL => 0xffffffff81800000UL,
            _ => 0
        };
        if (fallbackBuffer == 0)
            return;

        uint expectedInstruction = pc switch
        {
            0xffffffff8005d4fcUL => 0xac627cb8U,
            0xffffffff8005d57cUL => 0xac627cacU,
            0xffffffff8005d5f0UL => 0xaca26adcU,
            _ => 0
        };
        if (_memory.Read32(pc) != expectedInstruction)
            return;

        uint byteCount = (uint)_gpr[16];
        if (byteCount == 0 || byteCount > 0x00400000U)
            return;

        ulong allocation = _gpr[2];
        if (allocation != 0 && allocation != 0xffffffffUL && allocation != 0xffffffffffffffffUL)
            return;
        if (!IsMainRamRange(fallbackBuffer, byteCount))
            return;

        _gpr[2] = fallbackBuffer;
        _gpr[0] = 0;
        if (_runtimeWorldDataAllocationRepairTraceCount++ < 8)
        {
            Console.WriteLine(
                $"[GAUNTDL:FIX] world-data-allocation pc={pc:x16} " +
                $"bytes={byteCount:x8} fallback={fallbackBuffer:x16}");
        }
    }

    private void ApplyKnownRuntimeWorldDataReadBufferRepair(ulong pc)
    {
        const ulong branchPc = 0xffffffff8005d6ccUL;
        const ulong worldBufferGlobal = 0xffffffff80227cb8UL;
        const ulong fallbackBuffer = 0xffffffff81000000UL;
        const ulong gauntletWorldDataTestWadByteOffset = 0x0f107b68UL;
        const uint gauntletWorldDataTestWadBytes = 0x2000U;

        if (!_enableRuntimeBgLoadModelDispatchFastPath || pc != branchPc)
            return;
        if (_memory.Read32(branchPc - 0x08UL) != 0x3c138022U ||
            _memory.Read32(branchPc - 0x04UL) != 0x8e627cb8U ||
            _memory.Read32(branchPc) != 0x1040001bU ||
