            hydration = $"test.wad@{gauntletWorldDataTestWadByteOffset:x}/bytes={gauntletWorldDataTestWadBytes:x}/first={firstWord:x8}";
        }
        else if (!string.IsNullOrEmpty(reason))
        {
            hydration = reason;
