    private void ApplyKnownRuntimeWorldSelectionRepair(ulong pc)
    {
        const ulong branchPc = 0xffffffff8004f29cUL;
        const ulong worldGlobal = 0xffffffff8016c130UL;
        const ulong selectedEntryGlobal = 0xffffffff8016c13cUL;
        const ulong staticWorldList = 0xffffffff8015bef4UL;
        const ulong fallbackTable = 0xffffffff802e1000UL;
        const uint staticEntryStride = 0x2c;
        const uint fallbackEntryStride = 0x80;
        const uint selectedWorldIndex = 0;
        const ulong selectedStaticEntry = staticWorldList + selectedWorldIndex * staticEntryStride;
        const ulong selectedFallbackEntry = fallbackTable + selectedWorldIndex * fallbackEntryStride;

        if (!_enableRuntimeWorldSelectionExperiment || pc != branchPc)
            return;
        if (_memory.Read32(branchPc) != 0x14400003U)
            return;
        if (_gpr[2] != 0 || _gpr[18] != selectedStaticEntry)
            return;
        if (_memory.Read32(worldGlobal + 0x18UL) != 13 ||
            _memory.Read32(worldGlobal + 0x1cUL) != unchecked((uint)fallbackTable) ||
            _memory.Read32(selectedEntryGlobal) != 0)
        {
            return;
        }
        if (!IsMainRamRange(selectedFallbackEntry, fallbackEntryStride) ||
            _memory.Read32(selectedFallbackEntry) != selectedWorldIndex + 1U)
            return;

        _memory.Write32(selectedEntryGlobal, unchecked((uint)selectedFallbackEntry));
        _gpr[2] = 1;
        _gpr[0] = 0;
        if (_runtimeWorldSelectionRepairTraceCount++ < 8)
        {
            Console.WriteLine(
                $"[GAUNTDL:FIX] world-selection pc={pc:x16} " +
                $"selected={selectedFallbackEntry:x16} id={_memory.Read32(selectedFallbackEntry):x8} " +
                $"mask={_memory.Read32(selectedFallbackEntry + 0x04UL):x8} " +
                $"name={ReadAsciiTraceString(selectedFallbackEntry + 0x08UL, 32)}");
        }
    }

    private void ApplyKnownRuntimeWorldStaticDataLinkRepair(ulong pc)
    {
        const ulong branchPc = 0xffffffff8004f29cUL;
        const ulong selectedEntryGlobal = 0xffffffff8016c13cUL;
        const ulong fallbackTable = 0xffffffff802e1000UL;
        const ulong staticWorldList = 0xffffffff8015bef4UL;
        const uint staticEntryStride = 0x2c;
        const uint fallbackEntryStride = 0x80;
        const uint castleWorldIndex = 0;
        const uint testWorldIndex = 12;

        if (!_enableRuntimeWorldStaticDataLinkRepair || pc != branchPc)
            return;
        if (_memory.Read32(branchPc) != 0x14400003U)
            return;

        ulong castleStaticEntry = staticWorldList + castleWorldIndex * staticEntryStride;
        ulong castleFallbackEntry = fallbackTable + castleWorldIndex * fallbackEntryStride;
        uint selectedEntry = _memory.Read32(selectedEntryGlobal);
        if (_gpr[18] == castleStaticEntry &&
            selectedEntry == unchecked((uint)castleFallbackEntry) &&
            _memory.Read32(castleStaticEntry) == castleWorldIndex + 1U &&
            _memory.Read32(castleStaticEntry + 0x10UL) == 0 &&
            IsMainRamRange(castleStaticEntry, staticEntryStride) &&
            TryLinkKnownRuntimeWorldStaticData(
                pc,
                "world-selected-static-data-link",
                castleWorldIndex,
                0xffffffff81000000UL,
                0x0f100000UL,
                0x0a04U))
        {
            _gpr[2] = SignExtend32(_memory.Read32(castleStaticEntry + 0x10UL));
            _gpr[0] = 0;
            return;
        }

        ulong staticEntry = staticWorldList + testWorldIndex * staticEntryStride;
        ulong testFallbackEntry = fallbackTable + testWorldIndex * fallbackEntryStride;
        if (selectedEntry != 0 && selectedEntry != unchecked((uint)testFallbackEntry))
            return;

        if (_gpr[18] != staticEntry ||
            _memory.Read32(staticEntry) != testWorldIndex + 1U ||
            _memory.Read32(staticEntry + 0x10UL) != 0 ||
            !IsMainRamRange(staticEntry, staticEntryStride))
        {
            return;
        }

        if (TryLinkKnownRuntimeWorldStaticData(
                pc,
                "world-static-data-link",
                testWorldIndex,
                0xffffffff81000000UL,
                0x0f107e00UL,
                0x0358U))
        {
            _gpr[2] = SignExtend32(_memory.Read32(staticEntry + 0x10UL));
            _gpr[0] = 0;
        }
    }

    private bool EnsureKnownRuntimeFallbackWorldEntry(uint worldIndex)
    {
        const ulong staticWorldList = 0xffffffff8015bef4UL;
        const ulong fallbackTable = 0xffffffff802e1000UL;
        const uint entryStride = 0x80;
        const uint staticEntryStride = 0x2c;

        ulong entry = fallbackTable + worldIndex * entryStride;
        ulong staticEntry = staticWorldList + worldIndex * staticEntryStride;
        if (!IsMainRamRange(entry, entryStride) ||
            !IsMainRamRange(staticEntry, staticEntryStride))
        {
            return false;
        }

        uint expectedWorldId = worldIndex + 1U;
        if (_memory.Read32(entry) == expectedWorldId &&
            _memory.Read32(entry + 0x04UL) == 0xffffffffU)
        {
            return true;
        }

        for (uint offset = 0; offset < entryStride; offset += 4)
            _memory.Write32(entry + offset, 0);

        uint worldId = _memory.Read32(staticEntry + 0x00UL);
        if (worldId == 0)
        {
            worldId = expectedWorldId;
            _memory.Write32(staticEntry + 0x00UL, worldId);
        }
        _memory.Write32(entry + 0x00UL, worldId);
        _memory.Write32(entry + 0x04UL, 0xffffffffU);
        for (uint offset = 0; offset < staticEntryStride - 4U; offset++)
            _memory.Write8(entry + 0x08UL + offset, _memory.Read8(staticEntry + 0x04UL + offset));

        return true;
    }

    private bool TryLinkKnownRuntimeWorldStaticData(
        ulong pc,
        string traceLabel,
        uint worldIndex,
        ulong worldDataBuffer,
        ulong wadByteOffset,
        uint wadBytes)
    {
        const ulong staticWorldList = 0xffffffff8015bef4UL;
        const uint staticEntryStride = 0x2c;

        ulong staticEntry = staticWorldList + worldIndex * staticEntryStride;
        if (!IsMainRamRange(staticEntry, staticEntryStride) ||
            !IsMainRamRange(worldDataBuffer, wadBytes))
        {
            return false;
        }

        if (_memory.Read32(staticEntry) == 0)
            _memory.Write32(staticEntry, worldIndex + 1U);

        string reason = "";
        if (!_memory.TryReadDiskByteOffsetToMemory(
                wadByteOffset,
                worldDataBuffer,
                wadBytes,
                out uint firstWord,
                out reason))
        {
            if (_runtimeWorldStaticDataLinkTraceCount++ < 8)
            {
                Console.WriteLine(
                    $"[GAUNTDL:FIX] {traceLabel} pc={pc:x16} " +
                    $"failed={reason}");
            }
            return false;
        }

        uint worldRecordCount = _memory.Read32(worldDataBuffer + 0x04UL);
        if (worldRecordCount == 0 || worldRecordCount > 0x100U)
            worldRecordCount = 1;

        _memory.Write32(staticEntry + 0x10UL, unchecked((uint)worldDataBuffer));
        _memory.Write32(staticEntry + 0x14UL, worldRecordCount);
        _memory.Write32(staticEntry + 0x28UL, 0);
        if (_runtimeWorldStaticDataLinkTraceCount++ < 8)
        {
            Console.WriteLine(
                $"[GAUNTDL:FIX] {traceLabel} pc={pc:x16} " +
                $"index={worldIndex} entry={staticEntry:x16} data={worldDataBuffer:x16} " +
                $"offset={wadByteOffset:x} bytes={wadBytes:x} first={firstWord:x8} count={worldRecordCount:x8}");
        }

        return true;
    }

    private void ApplyKnownRuntimeWorldSelectedPointerRepair(ulong pc)
    {
        const ulong worldGlobal = 0xffffffff8016c130UL;
        const ulong selectedEntryGlobal = 0xffffffff8016c13cUL;
        const ulong fallbackTable = 0xffffffff802e1000UL;
        const uint fallbackEntryStride = 0x80;
        const uint selectedWorldIndex = 0;
        const ulong selectedFallbackEntry = fallbackTable + selectedWorldIndex * fallbackEntryStride;

        if (!_enableRuntimeWorldSelectionExperiment)
            return;
        if (pc is not (0xffffffff800b1dc4UL or 0xffffffff800e3decUL or 0xffffffff80102520UL or 0xffffffff80103574UL))
            return;
        if (_memory.Read32(worldGlobal + 0x18UL) != 13 ||
            _memory.Read32(worldGlobal + 0x1cUL) != unchecked((uint)fallbackTable) ||
            _memory.Read32(selectedEntryGlobal) != 0)
        {
            return;
        }
        EnsureKnownRuntimeFallbackWorldEntry(selectedWorldIndex);

        if (!IsMainRamRange(selectedFallbackEntry, fallbackEntryStride) ||
            _memory.Read32(selectedFallbackEntry) != selectedWorldIndex + 1U ||
            _memory.Read32(selectedFallbackEntry + 0x04UL) != 0xffffffffU)
        {
            return;
        }

        _memory.Write32(selectedEntryGlobal, unchecked((uint)selectedFallbackEntry));
        if (_runtimeWorldSelectionRepairTraceCount++ < 8)
        {
            Console.WriteLine(
                $"[GAUNTDL:FIX] world-selected-pointer pc={pc:x16} " +
                $"selected={selectedFallbackEntry:x16} id={_memory.Read32(selectedFallbackEntry):x8} " +
                $"name={ReadAsciiTraceString(selectedFallbackEntry + 0x08UL, 32)}");
        }
    }

    private void ApplyKnownRuntimeWorldValidityBitsetRepair(ulong pc)
    {
        const ulong entry = 0xffffffff800cea48UL;
        const ulong table = 0xffffffff80145a18UL;
        const ulong primaryBitset = 0xffffffff80228668UL;
        const ulong secondaryBitset = 0xffffffff802286f0UL;
        const uint bitsetBytes = 0x98U;

        if (!_enableRuntimeBgLoadModelDispatchFastPath || pc is < entry or > 0xffffffff800ceb18UL)
            return;
        if (_memory.Read32(entry + 0x00UL) != 0x2402ffffU ||
            _memory.Read32(entry + 0x04UL) != 0x24635a18U ||
            _memory.Read32(entry + 0x10UL) != 0x8c460000U ||
            _memory.Read32(entry + 0x20UL) != 0x30440007U ||
            _memory.Read32(entry + 0x30UL) != 0x10400010U ||
            _memory.Read32(entry + 0x3cUL) != 0x24428668U ||
            _memory.Read32(entry + 0xb8UL) != 0x3c028022U ||
            _memory.Read32(entry + 0xbcUL) != 0x244286f0U)
        {
            return;
        }
        if (!IsMainRamRange(table, 0x140UL) ||
            !IsMainRamRange(primaryBitset, bitsetBytes) ||
            !IsMainRamRange(secondaryBitset, bitsetBytes))
        {
            return;
        }
        if (!IsZeroFilled(primaryBitset, bitsetBytes) || !IsZeroFilled(secondaryBitset, bitsetBytes))
            return;

        FillBytes(primaryBitset, bitsetBytes, 0xff);
        FillBytes(secondaryBitset, bitsetBytes, 0xff);
        if (_runtimeWorldValidityRepairTraceCount++ < 8)
        {
            Console.WriteLine(
                $"[GAUNTDL:FIX] world-validity-bitsets pc={pc:x16} " +
                $"primary={primaryBitset:x16} secondary={secondaryBitset:x16} bytes={bitsetBytes:x}");
        }
    }

    private bool IsZeroFilled(ulong address, uint byteCount)
    {
        for (uint offset = 0; offset < byteCount; offset++)
        {
            if (_memory.Read8(address + offset) != 0)
                return false;
        }

        return true;
    }

    private void FillBytes(ulong address, uint byteCount, byte value)
    {
        for (uint offset = 0; offset < byteCount; offset++)
            _memory.Write8(address + offset, value);
    }

