        const int skippedInstructions = 13;
        if (_remainingProbeSteps < skippedInstructions)
            return false;

        if (!IsMainRamRange(_gpr[11] + 4UL, 4) ||
            !IsMainRamRange(0xffffffff800b2e0cUL, 4) ||
            !IsMainRamRange(0xffffffff800b2e24UL, 4))
        {
