        uint rowSource = (uint)_memory.Read32(_gpr[11] + 4UL);
        uint rowStart = rowSource + (uint)_gpr[30];
        uint rowSpan = (uint)_memory.Read32(0xffffffff800b2e0cUL) - (uint)_gpr[23];

