        _gpr[17] = 0;
        _gpr[4] = 0x800b0000UL;
        _gpr[16] = 0;
        _gpr[14] = 0x800b0000UL;
        _gpr[2] = SignExtend32(rowSpan);
        _gpr[3] = SignExtend32(_memory.Read32(0xffffffff800b2e24UL));
        _gpr[18] = SignExtend32(rowStart);
        _gpr[21] = _gpr[18];
        _gpr[10] = SignExtend32(rowSpan << 11);

        FinishKnownRuntimeBudgetedFastPath(
            skippedInstructions,
            skippedInstructions - 1,
            unchecked((int)rowSpan) <= 0 ? 0xffffffff8001950cUL : 0xffffffff800192c8UL);
        return true;
    }

    private bool TryFastPathKnownRuntimeMaskedTileSkip(ulong pc)
    {
        const ulong branchPc = 0xffffffff80019318UL;
        if (pc != branchPc)
            return false;
        if (_gpr[2] != 0)
            return false;
        return TryFinishKnownRuntimeMaskedTileSkip(0);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private void WriteProfiledTilePixel16(ulong address, ushort value)
    {
        _memory.Write16(address, value);
        if (!_trackTileWrites)
            return;

        _tileWriteCount++;
        _tileWriteMin = Math.Min(_tileWriteMin, address);
        _tileWriteMax = Math.Max(_tileWriteMax, address);
    }

    private string GetTileWriteStatus()
    {
        if (!_profileTileWrites || _tileWriteCount == 0)
            return "";

        return $" tilew={_tileWriteCount}@0x{_tileWriteMin:x16}-0x{_tileWriteMax:x16}";
    }

    private bool TryFinishKnownRuntimeMaskedTileSkip(int leadingSkippedInstructions)
    {
        const ulong branchPc = 0xffffffff80019318UL;
        if (_memory.Read32(branchPc) != 0x50400076U ||
            _memory.Read32(branchPc + 0x04UL) != 0x26100001U ||
            _memory.Read32(0xffffffff800194f4UL) != 0x00118840U ||
            _memory.Read32(0xffffffff800194f8UL) != 0x3c04800bU ||
            _memory.Read32(0xffffffff800194fcUL) != 0x8c822e24U ||
            _memory.Read32(0xffffffff80019500UL) != 0x0202102aU ||
            _memory.Read32(0xffffffff80019504UL) != 0x1440ff70U ||
            _memory.Read32(0xffffffff80019508UL) != 0x26730002U ||
            _memory.Read32(0xffffffff8001950cUL) != 0x27de000cU ||
            _memory.Read32(0xffffffff80019510UL) != 0x3c02800bU ||
            _memory.Read32(0xffffffff80019514UL) != 0x8c422e1cU ||
            _memory.Read32(0xffffffff80019518UL) != 0x26d60001U ||
            _memory.Read32(0xffffffff8001951cUL) != 0x02c2102aU ||
            _memory.Read32(0xffffffff80019520UL) != 0x1440ff5cU ||
            _memory.Read32(0xffffffff80019524UL) != 0x26f70008U)
        {
            return false;
        }

        ulong columnLimit = SignExtend32(_memory.Read32(0xffffffff800b2e24UL));
        ulong nextColumn = (ulong)((long)_gpr[16] + 1L);
        bool staysInRow = unchecked((long)nextColumn) < unchecked((long)columnLimit);
        int skippedInstructions = (staysInRow ? 8 : 15) + leadingSkippedInstructions;
        if (_remainingProbeSteps < skippedInstructions)
            return false;

        _gpr[16] = nextColumn;
        _gpr[17] = (uint)_gpr[17] << 1;
        _gpr[4] = 0x800b0000UL;
        _gpr[2] = staysInRow ? 1UL : 0UL;
        _gpr[19] = (ulong)((long)_gpr[19] + 2L);
        if (staysInRow)
        {
            FinishKnownRuntimeBudgetedFastPath(skippedInstructions, 0xffffffff800192c8UL);
            return true;
        }

        ulong rowLimit = SignExtend32(_memory.Read32(0xffffffff800b2e1cUL));
        _gpr[30] = (ulong)((long)_gpr[30] + 0x0cL);
        _gpr[22] = (ulong)((long)_gpr[22] + 1L);
        _gpr[2] = unchecked((long)_gpr[22]) < unchecked((long)rowLimit) ? 1UL : 0UL;
        _gpr[23] = (ulong)((long)_gpr[23] + 8L);
        FinishKnownRuntimeBudgetedFastPath(
            skippedInstructions,
            _gpr[2] != 0 ? 0xffffffff80019294UL : 0xffffffff80019528UL);
        return true;
    }

    private bool TryFastPathKnownRuntimeTileMaskBranch(ulong pc)
    {
        const ulong entry = 0xffffffff800192c8UL;
        if (pc != entry || _gpr[17] == 0)
            return false;
        if (_memory.Read32(entry) != 0x16200013U ||
            _memory.Read32(entry + 0x04UL) != 0x02911024U ||
            _memory.Read32(0xffffffff80019318UL) != 0x50400076U)
        {
            return false;
        }

        if (_remainingProbeSteps < 2)
            return false;

        ulong maskResult = _gpr[20] & _gpr[17];
        if (maskResult == 0 && TryFastPathKnownRuntimeMaskedTileSkipRun())
            return true;
        if (maskResult == 0 && TryFinishKnownRuntimeMaskedTileSkip(2))
            return true;
        if (TryFinishKnownRuntimeTilePointerPreamble(maskResult, leadingSkippedInstructions: 2))
            return true;

        _gpr[2] = maskResult;
        FinishKnownRuntimeBudgetedFastPath(2, 0xffffffff80019318UL);
        return true;
    }

    private bool TryFastPathKnownRuntimeMaskedTileSkipRun()
    {
        const ulong entry = 0xffffffff800192c8UL;
        uint mask = (uint)_gpr[17];
        if (mask == 0)
            return false;

        uint tileWord = (uint)_gpr[20];
        ulong columnLimit = SignExtend32(_memory.Read32(0xffffffff800b2e24UL));
        ulong column = _gpr[16];
        ulong pixel = _gpr[19];
        int skippedTiles = 0;
        while (mask != 0)
        {
            ulong nextColumn = (ulong)((long)column + 1L);
            if (unchecked((long)nextColumn) >= unchecked((long)columnLimit))
                break;
            if ((tileWord & mask) != 0)
                break;

            skippedTiles++;
            column = nextColumn;
            mask <<= 1;
            pixel = (ulong)((long)pixel + 2L);
        }

        if (skippedTiles < 2)
            return false;

        int skippedInstructions = skippedTiles * 10;
        if (_remainingProbeSteps < skippedInstructions)
            return false;

        _gpr[16] = column;
        _gpr[17] = mask;
        _gpr[4] = 0x800b0000UL;
        _gpr[2] = 1;
        _gpr[19] = pixel;
        FinishKnownRuntimeBudgetedFastPath(skippedInstructions, skippedInstructions - 1, entry);
        TryContinueKnownRuntimeTileLoopOnce();
        return true;
    }

    private bool TryFastPathKnownRuntimeTileOuterTail(ulong pc)
    {
        const ulong tailPc = 0xffffffff800194f0UL;
        if (pc != tailPc)
            return false;
        if (!TryPlanKnownRuntimeTileOuterTail(
                verifySignature: true,
                out bool staysInRow,
                out ulong rowLimit,
                out int skippedInstructions))
            return false;

        FinishKnownRuntimeTileOuterTail(
            staysInRow,
            rowLimit,
            skippedInstructions,
            extraProbeStepDebt: 0);
        return true;
    }

    private bool TryPlanKnownRuntimeTileOuterTail(
        bool verifySignature,
        out bool staysInRow,
        out ulong rowLimit,
        out int skippedInstructions)
    {
        const ulong tailPc = 0xffffffff800194f0UL;
        staysInRow = false;
        rowLimit = 0;
        skippedInstructions = 0;
        if (verifySignature &&
            (_memory.Read32(tailPc) != 0x26100001U ||
            _memory.Read32(tailPc + 0x04UL) != 0x00118840U ||
            _memory.Read32(tailPc + 0x08UL) != 0x3c04800bU ||
            _memory.Read32(tailPc + 0x0cUL) != 0x8c822e24U ||
            _memory.Read32(tailPc + 0x10UL) != 0x0202102aU ||
            _memory.Read32(tailPc + 0x14UL) != 0x1440ff70U ||
            _memory.Read32(tailPc + 0x18UL) != 0x26730002U ||
            _memory.Read32(tailPc + 0x1cUL) != 0x27de000cU ||
            _memory.Read32(tailPc + 0x20UL) != 0x3c02800bU ||
            _memory.Read32(tailPc + 0x24UL) != 0x8c422e1cU ||
            _memory.Read32(tailPc + 0x28UL) != 0x26d60001U ||
            _memory.Read32(tailPc + 0x2cUL) != 0x02c2102aU ||
            _memory.Read32(tailPc + 0x30UL) != 0x1440ff5cU ||
            _memory.Read32(tailPc + 0x34UL) != 0x26f70008U))
        {
            return false;
        }

        ulong columnLimit = SignExtend32(_memory.Read32(0xffffffff800b2e24UL));
        staysInRow = unchecked((long)((ulong)((long)_gpr[16] + 1L))) < unchecked((long)columnLimit);
        skippedInstructions = staysInRow ? 7 : 14;
        if (_remainingProbeSteps < skippedInstructions)
            return false;

        if (!staysInRow)
            rowLimit = SignExtend32(_memory.Read32(0xffffffff800b2e1cUL));
        return true;
    }

    private void FinishKnownRuntimeTileOuterTail(
        bool staysInRow,
        ulong rowLimit,
        int skippedInstructions,
        int extraProbeStepDebt)
    {
        _gpr[16] = (ulong)((long)_gpr[16] + 1L);
        _gpr[17] = (uint)_gpr[17] << 1;
        _gpr[4] = 0x800b0000UL;
        _gpr[2] = staysInRow ? 1UL : 0UL;
        _gpr[19] = (ulong)((long)_gpr[19] + 2L);
        if (staysInRow)
        {
            FinishKnownRuntimeBudgetedFastPath(
                skippedInstructions,
                skippedInstructions - 1 + extraProbeStepDebt,
                0xffffffff800192c8UL);
            TryContinueKnownRuntimeTileLoopOnce();
            return;
        }

        _gpr[30] = (ulong)((long)_gpr[30] + 0x0cL);
        _gpr[22] = (ulong)((long)_gpr[22] + 1L);
        _gpr[2] = unchecked((long)_gpr[22]) < unchecked((long)rowLimit) ? 1UL : 0UL;
        _gpr[23] = (ulong)((long)_gpr[23] + 8L);
        FinishKnownRuntimeBudgetedFastPath(
            skippedInstructions,
            skippedInstructions - 1 + extraProbeStepDebt,
            _gpr[2] != 0 ? 0xffffffff80019294UL : 0xffffffff80019528UL);
        TryContinueKnownRuntimeTileLoopOnce();
    }

    private void TryContinueKnownRuntimeTileLoopOnce()
    {
        if (_isContinuingKnownRuntimeTileLoop || _remainingProbeSteps <= _probeStepDebt + 256)
            return;

        _isContinuingKnownRuntimeTileLoop = true;
        try
        {
            if (Pc == 0xffffffff800192c8UL)
            {
                if (TryFastPathKnownRuntimeTileMaskBranch(Pc))
                    return;
                _ = TryFastPathKnownRuntimeEmptyTileSpan(Pc);
                return;
            }

            if (Pc == 0xffffffff800194f0UL)
                _ = TryFastPathKnownRuntimeTileOuterTail(Pc);
        }
        finally
        {
            _isContinuingKnownRuntimeTileLoop = false;
        }
    }

    private void FinishKnownRuntimeBudgetedFastPath(int skippedInstructions, ulong nextPc)
        => FinishKnownRuntimeBudgetedFastPath(skippedInstructions, skippedInstructions - 1, nextPc);

    private void FinishKnownRuntimeBudgetedFastPath(int skippedInstructions, int probeStepDebt, ulong nextPc)
    {
        _gpr[0] = 0;
        AdvanceCp0Count(_cp0CountStep * (ulong)skippedInstructions);
        _instructionCounter += (ulong)skippedInstructions;
        _probeStepDebt += probeStepDebt;
        _hasPendingBranch = false;
        _hasImmediatePcOverride = false;
        Pc = nextPc;
    }

    private bool TryFastPathKnownRuntimeTileDepthPointerHelper(ulong pc)
    {
        const ulong helperPc = 0xffffffff8003878cUL;
        if (pc != helperPc)
            return false;
        if (_memory.Read32(helperPc) != 0x3c02a800U ||
            _memory.Read32(helperPc + 0x04UL) != 0x3c03a900U ||
            _memory.Read32(helperPc + 0x08UL) != 0x03e00008U ||
            _memory.Read32(helperPc + 0x0cUL) != 0x0064100bU)
        {
            return false;
