            _memory.Read32(pc + 24) != 0x8c42037cU ||
            _memory.Read32(pc + 28) != 0x2842003cU ||
            _memory.Read32(pc + 56) != 0x8e04000cU ||
            _memory.Read32(pc + 60) != 0x3c030e3fU ||
