    private bool TryFindVoodooRetraceDeltaWaitLoop(ulong pc, out ulong loopStart)
    {
        for (ulong back = 0; back <= 0x14UL; back += 4UL)
        {
            ulong candidate = pc - back;
            if (_memory.Read32(candidate) == 0x8e220000U &&
                _memory.Read32(candidate + 0x04UL) == 0x8e230000U &&
                _memory.Read32(candidate + 0x08UL) == 0x304507ffU &&
                _memory.Read32(candidate + 0x0cUL) == 0x306307ffU &&
                _memory.Read32(candidate + 0x10UL) == 0x10a3fffbU &&
                _memory.Read32(candidate + 0x14UL) == 0x00c5102bU)
            {
                loopStart = candidate;
                return true;
            }
        }

        loopStart = 0;
        return false;
    }

    private static bool IsMainRamRange(ulong address, ulong byteLength)
    {
        if (byteLength == 0 || !TryGetMainRamPhysical(address, out uint physical))
            return false;

        return byteLength <= 32UL * 1024UL * 1024UL - physical;
    }

    private static bool TryGetMainRamPhysical(ulong address, out uint physical)
    {
        if (address >= 0xffffffff80000000UL && address <= 0xffffffffbfffffffUL)
            physical = (uint)(address & 0x1fffffffUL);
        else if (address >= 0x80000000UL && address <= 0xbfffffffUL)
            physical = (uint)(address & 0x1fffffffUL);
        else if (address <= 0x1fffffffUL)
            physical = (uint)address;
        else
        {
            physical = 0;
            return false;
        }

        return physical < 32UL * 1024UL * 1024UL;
    }

    private bool FastPathInlineBiosText()
    {
        ulong cursor = _gpr[31];
        if (!TryScanNullTerminatedBytes(ref cursor, 4096))
            return false;

        Pc = (cursor + 7UL) & ~7UL;
        CompleteFastPathStep();
        return true;
    }

    private bool FastPathPointerBiosText()
    {
        ulong cursor = _gpr[4];
        if (!TryScanNullTerminatedBytes(ref cursor, 4096))
            return false;

        _gpr[4] = 0;
        _gpr[7] = cursor;
        Pc = _gpr[31];
        CompleteFastPathStep();
        return true;
    }

    private bool TryScanNullTerminatedBytes(ref ulong cursor, int maxLength)
    {
        for (int i = 0; i < maxLength; i++, cursor++)
        {
            if (_memory.Read8(cursor) == 0)
                return true;
        }

        return false;
    }

    private bool TryReadNullTerminatedAscii(ulong address, int maxLength, out string text)
    {
        Span<byte> buffer = stackalloc byte[Math.Min(maxLength, 128)];
        int length = 0;
        for (; length < buffer.Length; length++)
        {
            byte value = _memory.Read8(address + (uint)length);
            if (value == 0)
            {
                text = Encoding.ASCII.GetString(buffer[..length]);
                return true;
            }
            if (value < 0x20 || value >= 0x7f)
                break;

            buffer[length] = value;
        }

        text = string.Empty;
        return false;
    }

    private void CompleteFastPathStep()
    {
        _gpr[0] = 0;
        AdvanceCp0Count(_cp0CountStep);
        _instructionCounter++;
        _hasPendingBranch = false;
        _hasImmediatePcOverride = false;
    }

    private bool TrySetKnownGlideFifoGuestWriteSource(ulong pc, ulong destination)
    {
        const ulong headerStore = 0xffffffff800fe5e8UL;
        const ulong targetStore = 0xffffffff800fe5f8UL;
        const ulong payloadLowStore = 0xffffffff800fe60cUL;
        const ulong payloadHighStore = 0xffffffff800fe614UL;
        if (pc is not (headerStore or targetStore or payloadLowStore or payloadHighStore) ||
            destination is < 0xffffffffa8000000UL or > 0xffffffffa83ffff8UL)
        {
            return false;
        }

        ulong stack = _gpr[29];
        ulong source = _gpr[22];
        uint payloadWords = (uint)_gpr[20];
        uint index = (uint)_gpr[18];
        if (!IsMainRamRange(stack + 0x1cUL, 4) ||
            !IsMainRamRange(stack + 0x74UL, 4) ||
            payloadWords == 0 ||
            payloadWords > 0x400U)
        {
            return false;
        }

        uint sourceBase = _memory.Read32(stack + 0x1cUL);
        uint limit = _memory.Read32(stack + 0x74UL);
        uint packetSourceAddress = (uint)_gpr[17];
        uint packet = index;
        uint word;
        if (pc == headerStore)
        {
            word = uint.MaxValue;
        }
        else if (pc == targetStore)
        {
            word = uint.MaxValue - 1U;
        }
        else
        {
            uint pairWord = (uint)_gpr[5];
            word = pc == payloadLowStore ? pairWord : pairWord + 1U;
            if (pc == payloadHighStore)
                source += 4UL;
        }

        _memory.SetVoodooCommandFifoBulkWriteSource(
            source,
            sourceBase,
            packetSourceAddress,
            packet,
            index,
            limit,
            word,
            payloadWords);
        return true;
    }

    private uint ApplyStaticLrRecord0CleanDiskPayloadExperiment(ulong pc, uint value)
    {
        if (!_experimentStaticLrRecord0CleanDiskPayload ||
            pc is not (0xffffffff800fe60cUL or 0xffffffff800fe614UL))
        {
            return value;
        }

        const uint sourceBase = 0x802e1719U;
        const uint sourceEnd = sourceBase + 0x2000U;
        const ulong diskBase = 0x0fbb0830UL;
        uint payloadWords = (uint)_gpr[20];
        uint index = (uint)_gpr[18];
        ulong stack = _gpr[29];
        if (payloadWords != 64U || index > 31U || !IsMainRamRange(stack + 0x74UL, 4) ||
            _memory.Read32(stack + 0x74UL) != 31U)
        {
            return value;
        }

        uint word = (uint)_gpr[5] + (pc == 0xffffffff800fe614UL ? 1U : 0U);
        uint source = unchecked((uint)_gpr[22] + (pc == 0xffffffff800fe614UL ? 4U : 0U));
        uint runRoot = unchecked(source - index * payloadWords * 4U - word * 4U);
        if (runRoot != sourceBase || source < sourceBase || source > sourceEnd - 4U ||
            !_memory.TryReadDiskByteOffsetWord(diskBase + source - 0x802e1718U, out uint diskWord))
        {
            return value;
        }

        if (value != diskWord && _staticLrRecord0CleanDiskPayloadTraceCount++ < 64)
        {
            Console.WriteLine(
                $"[GAUNTDL:EXPERIMENT] static-lr-record0-clean-disk-payload " +
                $"source=0x{source:x8} offset=0x{source - sourceBase:x4} " +
                $"packet={index}/31 word={word}/64 " +
                $"mem=0x{value:x8}->disk=0x{diskWord:x8}");
        }

        return diskWord;
    }

    private void Execute(ulong pc, uint op)
    {
        if (op == 0)
            return;

        uint opcode = op >> 26;
        int rs = (int)((op >> 21) & 0x1f);
        int rt = (int)((op >> 16) & 0x1f);
        int rd = (int)((op >> 11) & 0x1f);
        short simm = unchecked((short)(op & 0xffff));
        ushort uimm = (ushort)(op & 0xffff);

        switch (opcode)
        {
            case 0x00:
                ExecuteSpecial(pc, op, rs, rt, rd);
                break;
            case 0x01:
                ExecuteRegImm(pc, op, rs, rt, simm);
                break;
            case 0x02:
                QueueBranch((pc & 0xfffffffff0000000UL) | (((ulong)op & 0x03ffffffUL) << 2));
                break;
            case 0x03:
                _gpr[31] = CanonicalizeCodeAddress(pc + 8);
                QueueBranch((pc & 0xfffffffff0000000UL) | (((ulong)op & 0x03ffffffUL) << 2));
                break;
            case 0x04:
                if (_gpr[rs] == _gpr[rt])
                    QueueBranch(pc + 4 + ((ulong)(long)simm << 2));
                break;
            case 0x05:
                if (_gpr[rs] != _gpr[rt])
                    QueueBranch(pc + 4 + ((ulong)(long)simm << 2));
                break;
            case 0x06:
                if (unchecked((long)_gpr[rs]) <= 0)
                    QueueBranch(pc + 4 + ((ulong)(long)simm << 2));
                break;
            case 0x07:
                if (unchecked((long)_gpr[rs]) > 0)
                    QueueBranch(pc + 4 + ((ulong)(long)simm << 2));
                break;
            case 0x08:
            case 0x09:
                _gpr[rt] = SignExtend32((uint)_gpr[rs] + (uint)simm);
                break;
            case 0x0a:
                _gpr[rt] = unchecked((long)_gpr[rs]) < simm ? 1UL : 0UL;
                break;
            case 0x0b:
                _gpr[rt] = _gpr[rs] < unchecked((ulong)(long)simm) ? 1UL : 0UL;
                break;
            case 0x0c:
                _gpr[rt] = _gpr[rs] & uimm;
                break;
            case 0x0d:
                _gpr[rt] = _gpr[rs] | uimm;
                break;
            case 0x0e:
                _gpr[rt] = _gpr[rs] ^ uimm;
                break;
            case 0x0f:
                _gpr[rt] = SignExtend32((uint)uimm << 16);
                break;
            case 0x10:
                ExecuteCop0(op, rs, rt, rd);
                break;
            case 0x11:
                ExecuteCop1(pc, op, rs, rt, rd);
                break;
            case 0x13:
                ExecuteCop1X(pc, op, rs, rt);
                break;
            case 0x18:
            case 0x19:
                _gpr[rt] = unchecked((ulong)((long)_gpr[rs] + simm));
                break;
            case 0x20:
                _gpr[rt] = unchecked((ulong)(sbyte)_memory.Read8(_gpr[rs] + (ulong)(long)simm));
                break;
            case 0x21:
                _gpr[rt] = unchecked((ulong)(short)_memory.Read16(_gpr[rs] + (ulong)(long)simm));
                break;
            case 0x22:
                _gpr[rt] = LoadWordLeft(_gpr[rs] + (ulong)(long)simm, _gpr[rt]);
                break;
            case 0x23:
                _gpr[rt] = unchecked((ulong)(int)_memory.Read32(_gpr[rs] + (ulong)(long)simm));
                break;
            case 0x24:
                _gpr[rt] = _memory.Read8(_gpr[rs] + (ulong)(long)simm);
                break;
            case 0x25:
                _gpr[rt] = _memory.Read16(_gpr[rs] + (ulong)(long)simm);
                break;
            case 0x26:
                _gpr[rt] = LoadWordRight(_gpr[rs] + (ulong)(long)simm, _gpr[rt]);
                break;
            case 0x27:
                _gpr[rt] = _memory.Read32(_gpr[rs] + (ulong)(long)simm);
                break;
            case 0x28:
                {
                    ulong address = _gpr[rs] + (ulong)(long)simm;
                    byte oldValue = IsMainRamRange(address, 1) ? _memory.Read8(address) : (byte)0;
                    byte value = (byte)_gpr[rt];
                    _memory.Write8(address, value);
                    TraceMainRamWriteWatch(pc, op, "sb", $"r{rt}->[r{rs}+0x{simm:x4}]", address, 1, oldValue, value);
                }
                break;
            case 0x29:
                {
                    ulong address = _gpr[rs] + (ulong)(long)simm;
                    ushort oldValue = IsMainRamRange(address, 2) ? _memory.Read16(address) : (ushort)0;
                    ushort value = (ushort)_gpr[rt];
                    _memory.Write16(address, value);
                    TraceMainRamWriteWatch(pc, op, "sh", $"r{rt}->[r{rs}+0x{simm:x4}]", address, 2, oldValue, value);
                }
                break;
            case 0x2a:
                StoreWordLeft(pc, op, rs, rt, simm, _gpr[rs] + (ulong)(long)simm, _gpr[rt]);
                break;
            case 0x2b:
                {
                    ulong address = _gpr[rs] + (ulong)(long)simm;
                    uint value = (uint)_gpr[rt];
                    uint oldValue = IsMainRamRange(address, 4) ? _memory.Read32(address) : 0;
                    value = ApplyKnownRuntimeBgLoadModelTextureSourceLimitStackRemap(pc, rt, address, value);
                    value = ApplyDirectTextureWriterDiskPayloadRemapExperiment(pc, rt, value);
                    value = ApplyDirectTextureWriterDiskWordExperiment(pc, rt, value);
                    value = ApplyDirectTextureWriterZeroWordExperiment(pc, rt, value);
                    value = ApplyStaticLrRecord0CleanDiskPayloadExperiment(pc, value);
                    TraceTextureUploadDirectWriterStore(pc, op, rs, rt, simm, address, value);
                    if (ShouldSkipRuntimeBgLoadModelSourceTableStore(pc, address, oldValue, value))
                        break;
                    if (ShouldSkipRuntimeBgLoadModelHotDescriptorOverwrite(pc, address, oldValue, value))
                        break;
                    bool hasGlideFifoSource = TrySetKnownGlideFifoGuestWriteSource(pc, address);
                    try
                    {
                        _memory.Write32(address, value);
                    }
                    finally
                    {
                        if (hasGlideFifoSource)
                            _memory.ClearVoodooCommandFifoBulkWriteSource();
                    }
                    ApplyRuntimeFontStoryGebBacking(pc, address, value);
                    TraceMainRamWriteWatch(pc, op, "sw", $"r{rt}->[r{rs}+0x{simm:x4}]", address, 4, oldValue, value);
                    TraceRuntimeVertexSourceWrite(pc, op, "sw", $"r{rt}->[r{rs}+0x{simm:x4}]", address, oldValue, value);
                    TraceTextureUploadDirectWriterControlTableWrite(pc, op, "sw", $"r{rt}", rs, simm, address, oldValue, value);
                }
                break;
            case 0x2e:
                StoreWordRight(pc, op, rs, rt, simm, _gpr[rs] + (ulong)(long)simm, _gpr[rt]);
                break;
            case 0x2f:
                break;
            case 0x31:
                _fpr[rt] = _memory.Read32(_gpr[rs] + (ulong)(long)simm);
                break;
            case 0x35:
                _fpr[rt] = _memory.Read64(_gpr[rs] + (ulong)(long)simm);
                break;
            case 0x37:
                _gpr[rt] = _memory.Read64(_gpr[rs] + (ulong)(long)simm);
                break;
            case 0x39:
                {
                    ulong address = _gpr[rs] + (ulong)(long)simm;
                    uint oldValue = IsMainRamRange(address, 4) ? _memory.Read32(address) : 0;
                    uint value = (uint)_fpr[rt];
                    _memory.Write32(address, value);
                    TraceMainRamWriteWatch(pc, op, "swc1", $"f{rt}->[r{rs}+0x{simm:x4}]", address, 4, oldValue, value);
                    TraceRuntimeVertexSourceWrite(pc, op, "swc1", $"f{rt}->[r{rs}+0x{simm:x4}]", address, oldValue, value);
                    TraceTextureUploadDirectWriterControlTableWrite(pc, op, "swc1", $"f{rt}", rs, simm, address, oldValue, value);
                }
                break;
            case 0x3d:
                {
                    ulong address = _gpr[rs] + (ulong)(long)simm;
                    ulong oldValue = IsMainRamRange(address, 8) ? _memory.Read64(address) : 0;
                    ulong value = _fpr[rt];
                    _memory.Write64(address, value);
                    TraceMainRamWriteWatch(pc, op, "sdc1", $"f{rt}->[r{rs}+0x{simm:x4}]", address, 8, oldValue, value);
                    TraceRuntimeVertexSourceWrite64(pc, op, "sdc1", $"f{rt}->[r{rs}+0x{simm:x4}]", address, oldValue, value);
                }
                break;
            case 0x3f:
                {
                    ulong address = _gpr[rs] + (ulong)(long)simm;
                    ulong oldValue = IsMainRamRange(address, 8) ? _memory.Read64(address) : 0;
                    ulong value = _gpr[rt];
                    _memory.Write64(address, value);
                    TraceMainRamWriteWatch(pc, op, "sd", $"r{rt}->[r{rs}+0x{simm:x4}]", address, 8, oldValue, value);
                    TraceRuntimeVertexSourceWrite64(pc, op, "sd", $"r{rt}->[r{rs}+0x{simm:x4}]", address, oldValue, value);
                }
                break;
            case 0x14:
                ExecuteBranchLikely(pc, simm, _gpr[rs] == _gpr[rt]);
                break;
            case 0x15:
                ExecuteBranchLikely(pc, simm, _gpr[rs] != _gpr[rt]);
                break;
            case 0x16:
                ExecuteBranchLikely(pc, simm, unchecked((long)_gpr[rs]) <= 0);
                break;
            case 0x17:
                ExecuteBranchLikely(pc, simm, unchecked((long)_gpr[rs]) > 0);
                break;
            default:
                HaltUnsupported(pc, op, $"opcode {opcode:x2}");
                break;
        }
    }

    private void ExecuteSpecial(ulong pc, uint op, int rs, int rt, int rd)
    {
        int sa = (int)((op >> 6) & 0x1f);
        uint funct = op & 0x3f;
        switch (funct)
        {
            case 0x00:
                _gpr[rd] = SignExtend32((uint)_gpr[rt] << sa);
                break;
            case 0x01:
                if (GetCop1Condition((rt >> 2) & 0x07) == ((rt & 1) != 0))
                    _gpr[rd] = _gpr[rs];
                break;
            case 0x02:
                _gpr[rd] = SignExtend32((uint)_gpr[rt] >> sa);
                break;
            case 0x03:
                _gpr[rd] = SignExtend32((uint)((int)(uint)_gpr[rt] >> sa));
                break;
            case 0x04:
                _gpr[rd] = SignExtend32((uint)_gpr[rt] << (int)(_gpr[rs] & 0x1f));
                break;
            case 0x06:
                _gpr[rd] = SignExtend32((uint)_gpr[rt] >> (int)(_gpr[rs] & 0x1f));
                break;
            case 0x07:
                _gpr[rd] = SignExtend32((uint)((int)(uint)_gpr[rt] >> (int)(_gpr[rs] & 0x1f)));
                break;
            case 0x08:
                QueueBranch(_gpr[rs]);
                break;
            case 0x09:
                _gpr[rd == 0 ? 31 : rd] = CanonicalizeCodeAddress(pc + 8);
                QueueBranch(_gpr[rs]);
                break;
            case 0x0a:
                if (_gpr[rt] == 0)
                    _gpr[rd] = _gpr[rs];
                break;
            case 0x0b:
                if (_gpr[rt] != 0)
                    _gpr[rd] = _gpr[rs];
                break;
            case 0x0f:
                break;
            case 0x10:
                _gpr[rd] = _hi;
                break;
            case 0x11:
                _hi = _gpr[rs];
                break;
            case 0x12:
                _gpr[rd] = _lo;
                break;
            case 0x13:
                _lo = _gpr[rs];
                break;
            case 0x14:
                _gpr[rd] = _gpr[rt] << (int)(_gpr[rs] & 0x3f);
                break;
            case 0x16:
                _gpr[rd] = _gpr[rt] >> (int)(_gpr[rs] & 0x3f);
                break;
            case 0x17:
                _gpr[rd] = (ulong)((long)_gpr[rt] >> (int)(_gpr[rs] & 0x3f));
                break;
            case 0x18:
                {
                    long product = (long)(int)(uint)_gpr[rs] * (int)(uint)_gpr[rt];
                    _lo = (uint)product;
                    _hi = (uint)(product >> 32);
                    break;
                }
            case 0x19:
                {
                    ulong product = (ulong)(uint)_gpr[rs] * (uint)_gpr[rt];
                    _lo = (uint)product;
                    _hi = (uint)(product >> 32);
                    break;
                }
            case 0x1a:
                Divide32(rs, rt, signed: true);
                break;
            case 0x1b:
                Divide32(rs, rt, signed: false);
                break;
            case 0x1c:
                {
                    long left = unchecked((long)_gpr[rs]);
                    long right = unchecked((long)_gpr[rt]);
                    Int128 product = (Int128)left * right;
                    _lo = (ulong)product;
                    _hi = (ulong)(product >> 64);
                    break;
                }
            case 0x1d:
                {
                    UInt128 product = (UInt128)_gpr[rs] * _gpr[rt];
                    _lo = (ulong)product;
                    _hi = (ulong)(product >> 64);
                    break;
                }
            case 0x1e:
                Divide64(rs, rt, signed: true);
                break;
            case 0x1f:
                Divide64(rs, rt, signed: false);
                break;
            case 0x20:
                _gpr[rd] = SignExtend32((uint)(_gpr[rs] + _gpr[rt]));
                break;
            case 0x21:
                _gpr[rd] = SignExtend32((uint)(_gpr[rs] + _gpr[rt]));
                break;
            case 0x22:
                _gpr[rd] = SignExtend32((uint)(_gpr[rs] - _gpr[rt]));
                break;
            case 0x23:
                _gpr[rd] = SignExtend32((uint)(_gpr[rs] - _gpr[rt]));
                break;
            case 0x2d:
                _gpr[rd] = _gpr[rs] + _gpr[rt];
                break;
            case 0x2f:
                _gpr[rd] = _gpr[rs] - _gpr[rt];
                break;
            case 0x24:
                _gpr[rd] = _gpr[rs] & _gpr[rt];
                break;
            case 0x25:
                _gpr[rd] = _gpr[rs] | _gpr[rt];
                break;
            case 0x26:
                _gpr[rd] = _gpr[rs] ^ _gpr[rt];
                break;
            case 0x27:
                _gpr[rd] = ~(_gpr[rs] | _gpr[rt]);
                break;
            case 0x2a:
                _gpr[rd] = unchecked((long)_gpr[rs]) < unchecked((long)_gpr[rt]) ? 1UL : 0UL;
                break;
            case 0x2b:
                _gpr[rd] = _gpr[rs] < _gpr[rt] ? 1UL : 0UL;
                break;
            case 0x38:
                _gpr[rd] = _gpr[rt] << sa;
                break;
            case 0x3a:
                _gpr[rd] = _gpr[rt] >> sa;
                break;
            case 0x3b:
                _gpr[rd] = (ulong)((long)_gpr[rt] >> sa);
                break;
            case 0x3c:
                _gpr[rd] = _gpr[rt] << (sa + 32);
                break;
            case 0x3e:
                _gpr[rd] = _gpr[rt] >> (sa + 32);
                break;
            case 0x3f:
                _gpr[rd] = (ulong)((long)_gpr[rt] >> (sa + 32));
                break;
            default:
                HaltUnsupported(pc, op, $"special {funct:x2}");
                break;
        }
    }

    private void Divide32(int rs, int rt, bool signed)
    {
        uint dividendRaw = (uint)_gpr[rs];
        uint divisorRaw = (uint)_gpr[rt];
        if (divisorRaw == 0)
            return;

        if (signed)
        {
            int dividend = unchecked((int)dividendRaw);
            int divisor = unchecked((int)divisorRaw);
            if (dividend == int.MinValue && divisor == -1)
            {
                _lo = dividendRaw;
                _hi = 0;
                return;
            }

            _lo = (uint)(dividend / divisor);
            _hi = (uint)(dividend % divisor);
            return;
        }

        _lo = dividendRaw / divisorRaw;
        _hi = dividendRaw % divisorRaw;
    }

    private static ulong SignExtend32(uint value)
        => unchecked((ulong)(long)(int)value);

    private static ulong CanonicalizeCodeAddress(ulong address)
        => (address & 0xffffffff00000000UL) == 0 && (address & 0x80000000UL) != 0
            ? SignExtend32((uint)address)
            : address;

    private ulong LoadWordLeft(ulong address, ulong oldValue)
    {
        ulong aligned = address & ~3UL;
        uint mem = _memory.Read32(aligned);
        uint oldWord = (uint)oldValue;
        int shift = 8 * (int)(~address & 3UL);
        uint mask = uint.MaxValue << shift;
        return SignExtend32((oldWord & ~mask) | (mem << shift));
    }

    private ulong LoadWordRight(ulong address, ulong oldValue)
    {
        ulong aligned = address & ~3UL;
        uint mem = _memory.Read32(aligned);
        uint oldWord = (uint)oldValue;
        int shift = 8 * (int)(address & 3UL);
        uint mask = uint.MaxValue >> shift;
        return SignExtend32((oldWord & ~mask) | (mem >> shift));
    }

    private void StoreWordLeft(ulong pc, uint op, int rs, int rt, short simm, ulong address, ulong value)
    {
        ulong aligned = address & ~3UL;
        uint oldMem = _memory.Read32(aligned);
        uint word = (uint)value;
        int shift = 8 * (int)(~address & 3UL);
        uint mask = uint.MaxValue >> shift;
        uint newValue = (oldMem & ~mask) | ((word >> shift) & mask);
        _memory.Write32(aligned, newValue);
        TraceMainRamWriteWatch(pc, op, "swl", $"r{rt}->[r{rs}+0x{simm:x4}]", aligned, 4, oldMem, newValue);
        TraceRuntimeVertexSourceWrite(pc, op, "swl", $"r{rt}->[r{rs}+0x{simm:x4}]", aligned, oldMem, newValue);
        TraceTextureUploadDirectWriterControlTableWrite(pc, op, "swl", $"r{rt}", rs, simm, aligned, oldMem, newValue);
    }

    private void StoreWordRight(ulong pc, uint op, int rs, int rt, short simm, ulong address, ulong value)
    {
        ulong aligned = address & ~3UL;
        uint oldMem = _memory.Read32(aligned);
        uint word = (uint)value;
        int shift = 8 * (int)(address & 3UL);
        uint mask = uint.MaxValue << shift;
        uint newValue = (oldMem & ~mask) | ((word << shift) & mask);
        _memory.Write32(aligned, newValue);
        TraceMainRamWriteWatch(pc, op, "swr", $"r{rt}->[r{rs}+0x{simm:x4}]", aligned, 4, oldMem, newValue);
        TraceRuntimeVertexSourceWrite(pc, op, "swr", $"r{rt}->[r{rs}+0x{simm:x4}]", aligned, oldMem, newValue);
        TraceTextureUploadDirectWriterControlTableWrite(pc, op, "swr", $"r{rt}", rs, simm, aligned, oldMem, newValue);
    }

    private void Divide64(int rs, int rt, bool signed)
    {
        ulong divisorRaw = _gpr[rt];
        if (divisorRaw == 0)
            return;

        if (signed)
        {
            long dividend = unchecked((long)_gpr[rs]);
            long divisor = unchecked((long)divisorRaw);
            if (dividend == long.MinValue && divisor == -1)
            {
                _lo = unchecked((ulong)dividend);
                _hi = 0;
                return;
            }

            _lo = unchecked((ulong)(dividend / divisor));
            _hi = unchecked((ulong)(dividend % divisor));
            return;
        }

        _lo = _gpr[rs] / divisorRaw;
        _hi = _gpr[rs] % divisorRaw;
    }

    private void ExecuteRegImm(ulong pc, uint op, int rs, int rt, short simm)
    {
        long signed = unchecked((long)_gpr[rs]);
        bool take = rt switch
        {
            0x00 => signed < 0,
            0x01 => signed >= 0,
            0x02 => signed < 0,
            0x03 => signed >= 0,
            0x10 => signed < 0,
            0x11 => signed >= 0,
            0x12 => signed < 0,
            0x13 => signed >= 0,
            _ => false
        };

        if (rt is 0x10 or 0x11 or 0x12 or 0x13)
            _gpr[31] = CanonicalizeCodeAddress(pc + 8);

        if (take)
        {
            QueueBranch(pc + 4 + ((ulong)(long)simm << 2));
        }
        else if (rt is 0x02 or 0x03 or 0x12 or 0x13)
        {
            OverrideNextPc(pc + 8);
        }

        if (rt is not (0x00 or 0x01 or 0x02 or 0x03 or 0x10 or 0x11 or 0x12 or 0x13))
            HaltUnsupported(pc, op, $"regimm {rt:x2}");
    }

    private void ExecuteCop0(uint op, int rs, int rt, int rd)
    {
        switch (rs)
        {
            case 0x00: // mfc0
                _gpr[rt] = unchecked((ulong)(long)(int)ReadCp0(rd));
                break;
            case 0x01: // dmfc0
                _gpr[rt] = _cp0[rd];
                break;
            case 0x04: // mtc0
                WriteCp0(rd, unchecked((uint)_gpr[rt]));
                break;
            case 0x05: // dmtc0
                WriteCp0(rd, _gpr[rt]);
                break;
            case 0x10:
                ExecuteCop0Operation(op);
                break;
            default:
                HaltUnsupported(Pc, op, $"cop0 rs={rs:x2}");
                break;
        }
    }

    private ulong ReadCp0(int register)
    {
        return register == 9 ? _cp0[9] : _cp0[register];
    }

    private void AdvanceCp0Count(ulong delta)
    {
        if (delta == 0)
            return;

        _memory.AdvanceNileClock(delta);

        uint oldCount = (uint)_cp0[9];
        uint compare = (uint)_cp0[11];
        ulong ticksUntilCompare = compare >= oldCount
            ? compare - (ulong)oldCount
            : 0x1_0000_0000UL - oldCount + compare;

        _cp0[9] = (uint)(oldCount + delta);
        if (ticksUntilCompare != 0 && delta >= ticksUntilCompare)
            _timerInterruptPending = true;
    }

    private void WriteCp0(int register, ulong value)
    {
        switch (register)
        {
            case 11: // Compare
                _cp0[11] = (uint)value;
                _timerInterruptPending = false;
                UpdateInterruptPendingBits();
                break;
            case 12: // Status
                _cp0[12] = (uint)value & Cp0StatusWriteMask;
                break;
            case 13: // Cause
                _cp0[13] = (_cp0[13] & ~Cp0CauseSoftwareInterruptMask) | (value & Cp0CauseSoftwareInterruptMask);
                break;
            case 14: // EPC
            case 30: // ErrorEPC
                _cp0[register] = CanonicalizeCodeAddress(value);
                break;
            case 16: // Config
                _cp0[16] = (_cp0[16] & ~Cp0ConfigWriteMask) | (value & Cp0ConfigWriteMask);
                break;
            default:
                _cp0[register] = value;
                break;
        }
    }

    private void ExecuteCop0Operation(uint op)
    {
        uint funct = op & 0x3f;
        switch (funct)
        {
            case 0x01: // tlbr
            case 0x02: // tlbwi
            case 0x06: // tlbwr
            case 0x08: // tlbp
                break;
            case 0x18: // eret
                if ((_cp0[12] & Cp0StatusErl) != 0)
                {
                    _cp0[12] &= ~Cp0StatusErl;
                    OverrideNextPc(CanonicalizeCodeAddress(_cp0[30]));
                }
                else
                {
                    _cp0[12] &= ~Cp0StatusExl;
                    OverrideNextPc(CanonicalizeCodeAddress(_cp0[14]));
                }
                break;
            default:
                HaltUnsupported(Pc, op, $"cop0 op {funct:x2}");
                break;
        }
    }

    private bool TryEnterPendingInterrupt(ulong pc)
    {
        const ulong runtimeWorkerQueueHeadAddress = 0xffffffff8021e97cUL;
        ulong softwarePending = _cp0[13] & Cp0CauseSoftwareInterruptMask;
        uint runtimeWorkerQueueHead = 0;
        if (_traceRuntimeWorkerSignal)
            runtimeWorkerQueueHead = _memory.Read32(runtimeWorkerQueueHeadAddress);
        if (softwarePending != 0 && runtimeWorkerQueueHead != 0)
        {
            ulong interruptState =
                ((_cp0[12] & (Cp0StatusIe | Cp0StatusExl | Cp0StatusErl | Cp0StatusInterruptMask)) << 32) |
                (softwarePending << 16) |
                runtimeWorkerQueueHead;
            if (interruptState != _runtimeWorkerSignalLastState && _runtimeWorkerSignalTraceCount++ < 128)
            {
                ulong node = CanonicalizeTraceAddress(runtimeWorkerQueueHead);
                uint worker = IsMainRamRange(node + 0x08UL, 8) ? _memory.Read32(node + 0x08UL) : 0;
                uint context = IsMainRamRange(node + 0x08UL, 8) ? _memory.Read32(node + 0x0cUL) : 0;
                Console.WriteLine(
                    $"[GAUNTDL:WORKER-SIGNAL] state pc={pc:x16} status={_cp0[12]:x16} cause={_cp0[13]:x16} " +
                    $"pending={softwarePending:x4} queueHead={runtimeWorkerQueueHead:x8} worker={worker:x8} context={context:x8}");
                _runtimeWorkerSignalLastState = interruptState;
            }
        }

        if ((_cp0[12] & Cp0StatusIe) == 0 || (_cp0[12] & (Cp0StatusExl | Cp0StatusErl)) != 0)
            return false;

        ulong pending = _cp0[13] & _cp0[12] & Cp0CauseInterruptPendingMask;
        if (pending == 0)
            return false;

        if (_enableRuntimeInterruptSuppress && IsRuntimeCodeAddress(pc))
        {
            _timerInterruptPending = false;
            _cp0[13] &= ~Cp0CauseInterruptPendingMask;
            _memory.SuppressRuntimeBringupInterrupts();
            return false;
        }

        if (_enableRuntimeInterruptBridge && IsRuntimeCodeAddress(pc) &&
            _memory.SuppressOnlyNileTimerInterrupts())
        {
            UpdateInterruptPendingBits();
            pending = _cp0[13] & _cp0[12] & Cp0CauseInterruptPendingMask;
            if (pending == 0)
                return false;
        }

        if (_enableRuntimeInterruptBridge && IsRuntimeCodeAddress(pc) &&
            (pending & ~Cp0CauseTimerInterrupt) == 0)
        {
            // The copied runtime enables Vegas interrupts before the Nile/IOASIC IRQ
            // controller is complete. Suppress only the synthetic timer source here;
            // device IRQs must still enter the runtime handler so IDE/RD0 completions
            // can be driven by hardware state instead of QIO status repair.
            _timerInterruptPending = false;
            _cp0[13] &= ~Cp0CauseTimerInterrupt;
            return false;
        }

        _cp0[14] = CanonicalizeCodeAddress(pc);
        _cp0[13] &= ~Cp0CauseExceptionCodeMask;
        _cp0[12] |= Cp0StatusExl;
        _gpr[0] = 0;
        if (_traceRuntimeWorkerSignal && softwarePending != 0 && runtimeWorkerQueueHead != 0 &&
            _runtimeWorkerSignalTraceCount++ < 128)
        {
            Console.WriteLine(
                $"[GAUNTDL:WORKER-SIGNAL] enter pc={pc:x16} vector=" +
                $"{((_cp0[12] & Cp0StatusBev) != 0 ? 0xffffffffbfc00380UL : 0xffffffff80000180UL):x16} " +
                $"status={_cp0[12]:x16} cause={_cp0[13]:x16} pending={pending:x4} queueHead={runtimeWorkerQueueHead:x8}");
        }
        AdvanceCp0Count(_cp0CountStep);
        _instructionCounter++;
        _hasPendingBranch = false;
        _hasImmediatePcOverride = false;
        Pc = (_cp0[12] & Cp0StatusBev) != 0
            ? 0xffffffffbfc00380UL
            : 0xffffffff80000180UL;
        return true;
    }

    private static bool IsRuntimeCodeAddress(ulong pc)
    {
        ulong physical = pc & 0x1fffffffUL;
        return physical is >= 0x00000000UL and < 0x01000000UL ||
               physical is >= 0x04400000UL and < 0x04500000UL;
    }

    private void UpdateInterruptPendingBits()
    {
        ulong software = _cp0[13] & Cp0CauseSoftwareInterruptMask;
        ulong hardware = _memory.GetCpuInterruptPendingMask() & 0x0000fc00UL;
        if (_timerInterruptPending)
            hardware |= Cp0CauseTimerInterrupt;
        _cp0[13] = (_cp0[13] & ~Cp0CauseInterruptPendingMask) | software | hardware;
    }

    private void ExecuteCop1(ulong pc, uint op, int rs, int rt, int rd)
    {
        int fd = (int)((op >> 6) & 0x1f);
        uint funct = op & 0x3f;
        switch (rs)
        {
            case 0x00: // mfc1
                _gpr[rt] = (uint)_fpr[rd];
                break;
            case 0x01: // dmfc1
                _gpr[rt] = _fpr[rd];
                break;
            case 0x02: // cfc1
                _gpr[rt] = _fcr[rd];
                break;
            case 0x04: // mtc1
                _fpr[rd] = (uint)_gpr[rt];
                break;
            case 0x05: // dmtc1
                _fpr[rd] = _gpr[rt];
                break;
            case 0x06: // ctc1
                _fcr[rd] = (uint)_gpr[rt];
                break;
            case 0x08: // bc1
                ExecuteCop1Branch(pc, rt, unchecked((short)op));
                break;
            case 0x10: // S-format operations
                ExecuteCop1SingleFormat(pc, op, rt, rd, fd, funct);
                break;
            case 0x11: // D-format operations
                ExecuteCop1DoubleFormat(pc, op, rt, rd, fd, funct);
                break;
            case 0x14: // W-format operations
                ExecuteCop1WordFormat(pc, op, rd, fd, funct);
                break;
            default:
                HaltUnsupported(pc, op, $"cop1 rs={rs:x2}");
                break;
        }
    }

    private void ExecuteCop1X(ulong pc, uint op, int rs, int rt)
    {
        int fr = rs;
        int ft = rt;
        int fs = (int)((op >> 11) & 0x1f);
        int fd = (int)((op >> 6) & 0x1f);
        uint funct = op & 0x3f;
        ulong address = _gpr[rs] + _gpr[rt];

        switch (funct)
        {
            case 0x00: // lwxc1
                _fpr[fd] = _memory.Read32(address);
                break;
            case 0x01: // ldxc1
                _fpr[fd] = _memory.Read64(address);
                break;
            case 0x08: // swxc1
                {
                    uint oldValue = IsMainRamRange(address, 4) ? _memory.Read32(address) : 0;
                    uint value = (uint)_fpr[fd];
                    _memory.Write32(address, value);
                    TraceRuntimeVertexSourceWrite(pc, op, "swxc1", $"f{fd}->[r{rs}+r{rt}]", address, oldValue, value);
                }
                break;
            case 0x09: // sdxc1
                {
                    ulong oldValue = IsMainRamRange(address, 8) ? _memory.Read64(address) : 0;
                    ulong value = _fpr[fd];
                    _memory.Write64(address, value);
                    TraceRuntimeVertexSourceWrite64(pc, op, "sdxc1", $"f{fd}->[r{rs}+r{rt}]", address, oldValue, value);
                }
                break;
            case 0x0f: // prefx
                break;
            case 0x20: // madd.s
                WriteCop1XSingle(fd, ReadSingle(fs) * ReadSingle(ft) + ReadSingle(fr));
                break;
            case 0x21: // madd.d
                WriteCop1XDouble(fd, ReadDouble(fs) * ReadDouble(ft) + ReadDouble(fr));
                break;
            case 0x28: // msub.s
                WriteCop1XSingle(fd, ReadSingle(fs) * ReadSingle(ft) - ReadSingle(fr));
                break;
            case 0x29: // msub.d
                WriteCop1XDouble(fd, ReadDouble(fs) * ReadDouble(ft) - ReadDouble(fr));
                break;
            case 0x30: // nmadd.s
                WriteCop1XSingle(fd, -(ReadSingle(fs) * ReadSingle(ft) + ReadSingle(fr)));
                break;
            case 0x31: // nmadd.d
                WriteCop1XDouble(fd, -(ReadDouble(fs) * ReadDouble(ft) + ReadDouble(fr)));
                break;
            case 0x38: // nmsub.s
                WriteCop1XSingle(fd, -(ReadSingle(fs) * ReadSingle(ft) - ReadSingle(fr)));
                break;
            case 0x39: // nmsub.d
                WriteCop1XDouble(fd, -(ReadDouble(fs) * ReadDouble(ft) - ReadDouble(fr)));
                break;
            default:
                HaltUnsupported(pc, op, $"cop1x {funct:x2}");
                break;
        }
    }

    private float ReadSingle(int register)
        => BitConverter.UInt32BitsToSingle((uint)_fpr[register]);

    private double ReadDouble(int register)
        => BitConverter.Int64BitsToDouble(unchecked((long)_fpr[register]));

    private void WriteCop1XSingle(int register, float value)
        => _fpr[register] = BitConverter.SingleToUInt32Bits(value);

    private void WriteCop1XDouble(int register, double value)
        => _fpr[register] = BitConverter.DoubleToUInt64Bits(value);

    private void ExecuteCop1Branch(ulong pc, int rt, short simm)
    {
        bool condition = GetCop1Condition((rt >> 2) & 0x07);
        bool take = condition == ((rt & 1) != 0);

        if (take)
            QueueBranch(pc + 4 + ((ulong)(long)simm << 2));
        else if ((rt & 0x02) != 0)
            OverrideNextPc(pc + 8);
    }

    private void ExecuteCop1SingleFormat(ulong pc, uint op, int ft, int fs, int fd, uint funct)
    {
        float value = BitConverter.UInt32BitsToSingle((uint)_fpr[fs]);
        float other = BitConverter.UInt32BitsToSingle((uint)_fpr[ft]);
        switch (funct)
        {
            case 0x00: // add.s
                _fpr[fd] = BitConverter.SingleToUInt32Bits(value + other);
                break;
            case 0x01: // sub.s
                _fpr[fd] = BitConverter.SingleToUInt32Bits(value - other);
                break;
            case 0x02: // mul.s
                _fpr[fd] = BitConverter.SingleToUInt32Bits(value * other);
                break;
            case 0x03: // div.s
                _fpr[fd] = BitConverter.SingleToUInt32Bits(value / other);
                break;
            case 0x04: // sqrt.s
                _fpr[fd] = BitConverter.SingleToUInt32Bits(MathF.Sqrt(value));
                break;
            case 0x05: // abs.s
                _fpr[fd] = (uint)_fpr[fs] & 0x7fffffffu;
                break;
            case 0x06: // mov.s
                _fpr[fd] = (uint)_fpr[fs];
                break;
            case 0x07: // neg.s
                _fpr[fd] = (uint)_fpr[fs] ^ 0x80000000u;
                break;
            case 0x0c: // round.w.s
                _fpr[fd] = unchecked((uint)(int)MathF.Round(value));
                break;
            case 0x0d: // trunc.w.s
                _fpr[fd] = unchecked((uint)(int)MathF.Truncate(value));
                break;
            case 0x0e: // ceil.w.s
                _fpr[fd] = unchecked((uint)(int)MathF.Ceiling(value));
                break;
            case 0x0f: // floor.w.s
                _fpr[fd] = unchecked((uint)(int)MathF.Floor(value));
                break;
            case 0x11: // movf.s/movt.s
                if (GetCop1Condition((ft >> 2) & 0x07) == ((ft & 1) != 0))
                    _fpr[fd] = (uint)_fpr[fs];
                break;
            case 0x15: // recip.s
                _fpr[fd] = BitConverter.SingleToUInt32Bits(1.0f / value);
                break;
            case 0x20: // cvt.s.s
                _fpr[fd] = (uint)_fpr[fs];
                break;
            case 0x21: // cvt.d.s
                _fpr[fd] = BitConverter.DoubleToUInt64Bits(value);
                break;
            case 0x24: // cvt.w.s
                _fpr[fd] = unchecked((uint)(int)value);
                break;
            case >= 0x30 and <= 0x3f: // c.cond.s
                bool unordered = float.IsNaN(value) || float.IsNaN(other);
                bool equal = !unordered && value == other;
                bool less = !unordered && value < other;
                uint condition = funct & 0x07u;
                bool result =
                    ((condition & 0x01u) != 0 && unordered) ||
                    ((condition & 0x02u) != 0 && equal) ||
                    ((condition & 0x04u) != 0 && less);
                SetCop1Condition((fd >> 2) & 0x07, result);
                break;
            default:
                HaltUnsupported(pc, op, $"cop1 s-fmt {funct:x2}");
                break;
        }
    }

    private void ExecuteCop1DoubleFormat(ulong pc, uint op, int ft, int fs, int fd, uint funct)
    {
        double value = BitConverter.Int64BitsToDouble(unchecked((long)_fpr[fs]));
        double other = BitConverter.Int64BitsToDouble(unchecked((long)_fpr[ft]));
        switch (funct)
        {
            case 0x00: // add.d
                _fpr[fd] = BitConverter.DoubleToUInt64Bits(value + other);
                break;
            case 0x01: // sub.d
                _fpr[fd] = BitConverter.DoubleToUInt64Bits(value - other);
                break;
            case 0x02: // mul.d
                _fpr[fd] = BitConverter.DoubleToUInt64Bits(value * other);
                break;
            case 0x03: // div.d
                _fpr[fd] = BitConverter.DoubleToUInt64Bits(value / other);
                break;
            case 0x04: // sqrt.d
                _fpr[fd] = BitConverter.DoubleToUInt64Bits(Math.Sqrt(value));
                break;
            case 0x05: // abs.d
                _fpr[fd] = _fpr[fs] & 0x7fffffffffffffffUL;
                break;
            case 0x06: // mov.d
                _fpr[fd] = _fpr[fs];
                break;
            case 0x07: // neg.d
                _fpr[fd] = _fpr[fs] ^ 0x8000000000000000UL;
                break;
            case 0x0c: // round.w.d
                _fpr[fd] = unchecked((uint)(int)Math.Round(value));
                break;
            case 0x0d: // trunc.w.d
                _fpr[fd] = unchecked((uint)(int)Math.Truncate(value));
                break;
            case 0x0e: // ceil.w.d
                _fpr[fd] = unchecked((uint)(int)Math.Ceiling(value));
                break;
            case 0x0f: // floor.w.d
                _fpr[fd] = unchecked((uint)(int)Math.Floor(value));
                break;
            case 0x11: // movf.d/movt.d
                if (GetCop1Condition((ft >> 2) & 0x07) == ((ft & 1) != 0))
                    _fpr[fd] = _fpr[fs];
                break;
            case 0x20: // cvt.s.d
                _fpr[fd] = BitConverter.SingleToUInt32Bits((float)value);
                break;
            case 0x21: // cvt.d.d
                _fpr[fd] = _fpr[fs];
                break;
            case 0x24: // cvt.w.d
                _fpr[fd] = unchecked((uint)(int)value);
                break;
            case 0x32: // c.eq.d
                SetCop1Condition((fd >> 2) & 0x07, value == other);
                break;
            case 0x3c: // c.lt.d
                SetCop1Condition((fd >> 2) & 0x07, value < other);
                break;
            case 0x3e: // c.le.d
                SetCop1Condition((fd >> 2) & 0x07, value <= other);
                break;
            default:
                HaltUnsupported(pc, op, $"cop1 d-fmt {funct:x2}");
                break;
        }
    }

    private void SetCop1Condition(bool condition)
        => SetCop1Condition(0, condition);

    private void SetCop1Condition(int conditionCode, bool condition)
    {
        uint mask = conditionCode == 0
            ? 1u << 23
            : 1u << (24 + conditionCode);
        _fcr[31] = condition ? _fcr[31] | mask : _fcr[31] & ~mask;
    }

    private bool GetCop1Condition()
        => GetCop1Condition(0);

    private bool GetCop1Condition(int conditionCode)
    {
        uint mask = conditionCode == 0
            ? 1u << 23
            : 1u << (24 + conditionCode);
        return (_fcr[31] & mask) != 0;
    }

    private void ExecuteCop1WordFormat(ulong pc, uint op, int fs, int fd, uint funct)
    {
        int value = unchecked((int)(uint)_fpr[fs]);
        switch (funct)
        {
            case 0x20: // cvt.s.w
                _fpr[fd] = BitConverter.SingleToUInt32Bits(value);
                break;
            case 0x21: // cvt.d.w
                _fpr[fd] = BitConverter.DoubleToUInt64Bits(value);
                break;
            default:
                HaltUnsupported(pc, op, $"cop1 w-fmt {funct:x2}");
                break;
        }
    }

    private void QueueBranch(ulong target)
    {
        _hasPendingBranch = true;
        _pendingBranchTarget = CanonicalizeCodeAddress(target);
    }

    private void ExecuteBranchLikely(ulong pc, short simm, bool take)
    {
        if (take)
            QueueBranch(pc + 4 + ((ulong)(long)simm << 2));
        else
            OverrideNextPc(pc + 8);
    }

    private void OverrideNextPc(ulong target)
    {
        _hasImmediatePcOverride = true;
        _immediatePcOverride = CanonicalizeCodeAddress(target);
    }

    private void HaltUnsupported(ulong pc, uint op, string reason)
    {
        if (!_continueAfterUnsupported)
            _halted = true;
        Console.WriteLine($"[GAUNTDL:CPU] halt pc={pc:x16} op={op:x8} reason={reason}");
        Console.WriteLine($"[GAUNTDL:CPU] ra={_gpr[31]:x16} sp={_gpr[29]:x16} gp={_gpr[28]:x16} k0={_gpr[26]:x16} k1={_gpr[27]:x16}");
        Console.WriteLine($"[GAUNTDL:CPU] status={_cp0[12]:x16} cause={_cp0[13]:x16} epc={_cp0[14]:x16} errorepc={_cp0[30]:x16}");
    }

    private string FormatCpuFprSummary()
        =>
            $"f0={FormatRuntimeFullrectFloat(ReadSingle(0))}/0x{(uint)_fpr[0]:x8} " +
            $"f1={FormatRuntimeFullrectFloat(ReadSingle(1))}/0x{(uint)_fpr[1]:x8} " +
            $"f2={FormatRuntimeFullrectFloat(ReadSingle(2))}/0x{(uint)_fpr[2]:x8} " +
            $"f3={FormatRuntimeFullrectFloat(ReadSingle(3))}/0x{(uint)_fpr[3]:x8} " +
            $"f4={FormatRuntimeFullrectFloat(ReadSingle(4))}/0x{(uint)_fpr[4]:x8} " +
            $"f20={FormatRuntimeFullrectFloat(ReadSingle(20))}/0x{(uint)_fpr[20]:x8} " +
            $"f21={FormatRuntimeFullrectFloat(ReadSingle(21))}/0x{(uint)_fpr[21]:x8} " +
            $"f22={FormatRuntimeFullrectFloat(ReadSingle(22))}/0x{(uint)_fpr[22]:x8} " +
            $"f23={FormatRuntimeFullrectFloat(ReadSingle(23))}/0x{(uint)_fpr[23]:x8} " +
            $"f24={FormatRuntimeFullrectFloat(ReadSingle(24))}/0x{(uint)_fpr[24]:x8} " +
            $"f25={FormatRuntimeFullrectFloat(ReadSingle(25))}/0x{(uint)_fpr[25]:x8}";

    private void TraceInstruction(ulong pc, uint op)
    {
        TraceRuntimeLogCall(pc);
        if (!ShouldTrace(pc))
            return;

        _traceInstructionCount++;
        string fprSummary = _traceCpuFprs ? $" {FormatCpuFprSummary()}" : "";
        Console.WriteLine(
            $"[GAUNTDL:CPU] #{_instructionCounter} pc={pc:x16} op={op:x8} {DisassembleBrief(op)} " +
            $"a0={_gpr[4]:x16} a1={_gpr[5]:x16} a2={_gpr[6]:x16} a3={_gpr[7]:x16} v0={_gpr[2]:x16} v1={_gpr[3]:x16} " +
            $"t0={_gpr[8]:x16} t1={_gpr[9]:x16} t2={_gpr[10]:x16} t3={_gpr[11]:x16} t4={_gpr[12]:x16} " +
            $"s0={_gpr[16]:x16} s1={_gpr[17]:x16} s2={_gpr[18]:x16} " +
            $"s3={_gpr[19]:x16} s4={_gpr[20]:x16} s5={_gpr[21]:x16} s6={_gpr[22]:x16} s7={_gpr[23]:x16} ra={_gpr[31]:x16} " +
            $"t5={_gpr[13]:x16} t6={_gpr[14]:x16} t7={_gpr[15]:x16} t8={_gpr[24]:x16} gp={_gpr[28]:x16} sp={_gpr[29]:x16} fp={_gpr[30]:x16} " +
            $"st={_cp0[12]:x16} cause={_cp0[13]:x16} epc={_cp0[14]:x16} errorepc={_cp0[30]:x16}{fprSummary}");
    }

    private bool ShouldTrace(ulong pc)
    {
        if (!_traceEnabled)
            return false;
        if (_traceInstructionCount >= _traceInstructionLimit)
            return false;
        if (_tracePcMin.HasValue && pc < _tracePcMin.Value)
            return false;
        if (_tracePcMax.HasValue && pc > _tracePcMax.Value)
            return false;
        if (_traceRa.HasValue && _gpr[31] != _traceRa.Value)
            return false;
        return true;
    }

    private void TraceRuntimeFullrectDescriptor(ulong pc)
    {
        if (!_traceRuntimeFullrectDescriptor ||
            _runtimeFullrectDescriptorTraceCount >= _traceRuntimeFullrectDescriptorLimit)
        {
            return;
        }

        ulong offset = pc & 0x1fffffffUL;
        string stage = offset switch
        {
            0x000b08ecUL => "endpoint-load",
            0x000b0a38UL => "v0-s-store",
            0x000b0a60UL => "v1-s-store",
            0x000b0ab8UL => "v2-s-store",
            0x000b0adcUL => "v3-s-store",
            0x000b0ba4UL => "scaled-s-store",
            0x000b0ba8UL => "scaled-t-store",
            _ => ""
        };
        if (stage.Length == 0)
            return;

        ulong descriptor = _gpr[16];
        if (!IsMainRamRange(descriptor, 0x24UL))
            return;

        uint h04 = _memory.Read16(descriptor + 0x04UL);
        uint h06 = _memory.Read16(descriptor + 0x06UL);
        uint w00 = _memory.Read32(descriptor + 0x00UL);
        uint w08 = _memory.Read32(descriptor + 0x08UL);
        uint w0c = _memory.Read32(descriptor + 0x0cUL);
        uint w10 = _memory.Read32(descriptor + 0x10UL);
        uint w14 = _memory.Read32(descriptor + 0x14UL);
        uint w18 = _memory.Read32(descriptor + 0x18UL);
        uint w1c = _memory.Read32(descriptor + 0x1cUL);
        uint w20 = _memory.Read32(descriptor + 0x20UL);
        _runtimeFullrectDescriptorTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:FULLRECT-DESC] n={_runtimeFullrectDescriptorTraceCount} pc={pc:x16} stage={stage} " +
            $"desc=0x{descriptor:x16} vbase=0x{_gpr[3]:x16} ra=0x{_gpr[31]:x16} sp=0x{_gpr[29]:x16} " +
            $"h04=0x{h04:x4} h06=0x{h06:x4} " +
            $"w00=0x{w00:x8} w08=0x{w08:x8} w0c=0x{w0c:x8} w10=0x{w10:x8} " +
            $"w14=0x{w14:x8}({FormatRuntimeFullrectFloat(w14)}) " +
            $"w18=0x{w18:x8}({FormatRuntimeFullrectFloat(w18)}) " +
            $"w1c=0x{w1c:x8}({FormatRuntimeFullrectFloat(w1c)}) " +
            $"w20=0x{w20:x8}({FormatRuntimeFullrectFloat(w20)}) " +
            $"f20={FormatRuntimeFullrectFloat(ReadSingle(20))}/0x{(uint)_fpr[20]:x8} " +
            $"f21={FormatRuntimeFullrectFloat(ReadSingle(21))}/0x{(uint)_fpr[21]:x8} " +
            $"f22={FormatRuntimeFullrectFloat(ReadSingle(22))}/0x{(uint)_fpr[22]:x8} " +
            $"f23={FormatRuntimeFullrectFloat(ReadSingle(23))}/0x{(uint)_fpr[23]:x8} " +
            $"f0={FormatRuntimeFullrectFloat(ReadSingle(0))}/0x{(uint)_fpr[0]:x8} " +
            $"f1={FormatRuntimeFullrectFloat(ReadSingle(1))}/0x{(uint)_fpr[1]:x8} " +
            $"f2={FormatRuntimeFullrectFloat(ReadSingle(2))}/0x{(uint)_fpr[2]:x8} " +
            $"f3={FormatRuntimeFullrectFloat(ReadSingle(3))}/0x{(uint)_fpr[3]:x8} " +
            $"vtx={FormatRuntimeFullrectVertexWords(_gpr[3])}");
    }

    private void TraceRuntimeFullrectClipper(ulong pc)
    {
        if (!_traceRuntimeFullrectClipper ||
            _runtimeFullrectClipperTraceCount >= _traceRuntimeFullrectClipperLimit)
        {
            return;
        }

        ulong offset = pc & 0x1fffffffUL;
        string stage = offset switch
        {
            0x000b0770UL => "entry",
            0x000b07acUL => "s-store",
            0x000b07c4UL => "exit",
            _ => ""
        };
        if (stage.Length == 0)
            return;

        ulong dst = _gpr[4];
        ulong src = _gpr[5];
        ulong tBits = _gpr[6] & 0xffffffffUL;
        ulong raOffset = _gpr[31] & 0x1fffffffUL;
        string edge = raOffset switch
        {
            0x000b0c0cUL or 0x000b0c20UL => "left",
            0x000b0c50UL or 0x000b0c64UL => "top",
            0x000b0ca0UL or 0x000b0cb4UL => "right",
            0x000b0cf0UL or 0x000b0d04UL => "bottom",
            _ => "unknown"
        };

        _runtimeFullrectClipperTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:FULLRECT-CLIP] n={_runtimeFullrectClipperTraceCount} pc={pc:x16} stage={stage} edge={edge} " +
            $"ra=0x{_gpr[31]:x16} a0=0x{dst:x16} a1=0x{src:x16} " +
            $"a2=0x{tBits:x8}({FormatRuntimeFullrectFloat((uint)tBits)}) " +
            $"f0={FormatRuntimeFullrectFloat(ReadSingle(0))}/0x{(uint)_fpr[0]:x8} " +
            $"f1={FormatRuntimeFullrectFloat(ReadSingle(1))}/0x{(uint)_fpr[1]:x8} " +
            $"f2={FormatRuntimeFullrectFloat(ReadSingle(2))}/0x{(uint)_fpr[2]:x8} " +
            $"dst={FormatRuntimeFullrectVertexWords(dst)} " +
            $"src={FormatRuntimeFullrectVertexWords(src)}");
    }

    private void ApplyRuntimeFullrectRightClipPositiveTExperiment(ulong pc)
    {
        if (!_experimentRuntimeFullrectRightClipPositiveT ||
            (pc & 0x1fffffffUL) != 0x000b077cUL)
        {
            return;
        }

        ulong raOffset = _gpr[31] & 0x1fffffffUL;
        if (raOffset is not (0x000b0ca0UL or 0x000b0cb4UL))
            return;

        uint before = (uint)_fpr[2];
        uint after = before & 0x7fffffffu;
        if (after == before)
            return;

        _fpr[2] = after;
        if (_runtimeFullrectRightClipPositiveTTraceCount++ < _experimentRuntimeFullrectRightClipPositiveTLimit)
        {
            Console.WriteLine(
                $"[GAUNTDL:EXPERIMENT] fullrect-right-clip-positive-t n={_runtimeFullrectRightClipPositiveTTraceCount} " +
                $"pc={pc:x16} ra=0x{_gpr[31]:x16} " +
                $"t=0x{before:x8}({FormatRuntimeFullrectFloat(before)})->0x{after:x8}({FormatRuntimeFullrectFloat(after)}) " +
                $"dst={FormatRuntimeFullrectVertexWords(_gpr[4])} src={FormatRuntimeFullrectVertexWords(_gpr[5])}");
        }
    }

    private static string FormatRuntimeFullrectFloat(uint bits)
        => FormatRuntimeFullrectFloat(BitConverter.UInt32BitsToSingle(bits));

    private static string FormatRuntimeFullrectFloat(float value)
        => float.IsFinite(value) ? value.ToString("G9", CultureInfo.InvariantCulture) : value.ToString(CultureInfo.InvariantCulture);

    private string FormatRuntimeFullrectVertexWords(ulong source)
    {
        if (!IsMainRamRange(source, 0x18UL))
            return "out-of-range";

        return
            $"{_memory.Read32(source + 0x00UL):x8}/" +
            $"{_memory.Read32(source + 0x04UL):x8}/" +
            $"{_memory.Read32(source + 0x08UL):x8}/" +
            $"{_memory.Read32(source + 0x0cUL):x8}/" +
            $"{_memory.Read32(source + 0x10UL):x8}/" +
            $"{_memory.Read32(source + 0x14UL):x8}";
    }

    private void TraceRuntimeLogCall(ulong pc)
    {
        ulong offset = pc & 0x1fffffffUL;
        if (offset is 0x000e30a0UL or 0x000e3378UL)
        {
            _runtimeTextCallCount++;
            _lastRuntimeTextPc = pc;
            _lastRuntimeTextRa = _gpr[31];
            string text = offset == 0x000e30a0UL
                ? ReadAsciiTraceString(_gpr[4], 160)
                : PickRuntimeTextArgument();
            if (LooksLikeRuntimeText(text))
                LastRuntimeText = text;
            if (!_traceRuntimeLog || _runtimeLogTraceCount >= 96)
                return;

            _runtimeLogTraceCount++;
            Console.WriteLine(
                $"[GAUNTDL:TEXT] pc={pc:x16} ra={_gpr[31]:x16} a0={_gpr[4]:x16} a1={_gpr[5]:x16} " +
                $"a2={_gpr[6]:x16} a3={_gpr[7]:x16} text=\"{text}\" stable=\"{LastRuntimeText}\"");
            return;
        }

        if (!_traceRuntimeLog || _runtimeLogTraceCount >= 96)
            return;

        if (offset is not (0x000fb57cUL or 0x000fbcc0UL or 0x000fcf70UL))
            return;

        _runtimeLogTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:LOG] pc={pc:x16} ra={_gpr[31]:x16} a0={_gpr[4]:x16} a1={_gpr[5]:x16} " +
            $"a2={_gpr[6]:x16} a3={_gpr[7]:x16} v0={_gpr[2]:x16} v1={_gpr[3]:x16} " +
            $"s0={_gpr[16]:x16} s1={_gpr[17]:x16} text=\"{ReadAsciiTraceString(_gpr[5], 160)}\"");
    }

    private string PickRuntimeTextArgument()
    {
        for (int register = 4; register <= 7; register++)
        {
            string text = ReadAsciiTraceString(_gpr[register], 160);
            if (LooksLikeRuntimeText(text))
                return text;
        }

        return "";
    }

    private static bool LooksLikeRuntimeText(string text)
    {
        if (string.IsNullOrWhiteSpace(text))
            return false;
        if (text.All(ch => ch is >= '0' and <= '9' or >= 'A' and <= 'F' or >= 'a' and <= 'f'))
            return false;

        int printable = 0;
        foreach (char ch in text)
        {
            if (ch is >= ' ' and <= '~')
                printable++;
        }

        int meaningful = 0;
        foreach (char ch in text)
        {
            if (ch is >= '0' and <= '9' ||
                ch is >= 'A' and <= 'Z' ||
                ch is >= 'a' and <= 'z' ||
                ch == ' ')
            {
                meaningful++;
            }
        }

        return printable >= 4 && meaningful >= 4;
    }

    private static string DisassembleBrief(uint op)
    {
        if (op == 0)
            return "nop";

        uint opcode = op >> 26;
        return opcode switch
        {
            0x00 => $"special.{op & 0x3f:x2}",
            0x01 => ((op >> 16) & 0x1f) switch
            {
                0x00 => "bltz",
                0x01 => "bgez",
                0x02 => "bltzl",
                0x03 => "bgezl",
                0x10 => "bltzal",
                0x11 => "bgezal",
                0x12 => "bltzall",
                0x13 => "bgezall",
                uint rt => $"regimm.{rt:x2}"
            },
            0x02 => "j",
            0x03 => "jal",
            0x04 => "beq",
            0x05 => "bne",
            0x06 => "blez",
            0x07 => "bgtz",
            0x08 => "addi",
            0x09 => "addiu",
            0x0a => "slti",
            0x0b => "sltiu",
            0x0c => "andi",
            0x0d => "ori",
            0x0e => "xori",
            0x0f => "lui",
            0x10 => "cop0",
            0x11 => DisassembleCop1Brief(op),
            0x18 => "daddi",
            0x19 => "daddiu",
            0x20 => "lb",
            0x21 => "lh",
            0x22 => "lwl",
            0x23 => "lw",
            0x24 => "lbu",
            0x25 => "lhu",
            0x26 => "lwr",
            0x27 => "lwu",
            0x28 => "sb",
            0x29 => "sh",
            0x2a => "swl",
            0x2b => "sw",
            0x2e => "swr",
            0x2f => "cache",
            0x31 => DisassembleCop1MemoryBrief("lwc1", op),
            0x35 => DisassembleCop1MemoryBrief("ldc1", op),
            0x37 => "ld",
            0x39 => DisassembleCop1MemoryBrief("swc1", op),
            0x3d => DisassembleCop1MemoryBrief("sdc1", op),
            0x3f => "sd",
            0x14 => "beql",
            0x15 => "bnel",
            0x16 => "blezl",
            0x17 => "bgtzl",
            _ => $"op.{opcode:x2}"
        };
    }

    private static string DisassembleCop1MemoryBrief(string mnemonic, uint op)
    {
        int baseRegister = (int)((op >> 21) & 0x1f);
        int ft = (int)((op >> 16) & 0x1f);
        short offset = unchecked((short)op);
        string signedOffset = offset < 0
            ? $"-0x{unchecked((ushort)-offset):x4}"
            : $"+0x{(ushort)offset:x4}";
        return $"{mnemonic} f{ft},[r{baseRegister}{signedOffset}]";
    }

    private static string DisassembleCop1Brief(uint op)
    {
        int fmt = (int)((op >> 21) & 0x1f);
        int ft = (int)((op >> 16) & 0x1f);
        int fs = (int)((op >> 11) & 0x1f);
        int fd = (int)((op >> 6) & 0x1f);
        uint funct = op & 0x3f;

        return fmt switch
        {
            0x00 => $"mfc1 r{ft},f{fs}",
            0x01 => $"dmfc1 r{ft},f{fs}",
            0x02 => $"cfc1 r{ft},fcr{fs}",
            0x04 => $"mtc1 r{ft},f{fs}",
            0x05 => $"dmtc1 r{ft},f{fs}",
            0x06 => $"ctc1 r{ft},fcr{fs}",
            0x08 => DisassembleCop1BranchBrief(ft, unchecked((short)op)),
            0x10 => DisassembleCop1FormatBrief("s", ft, fs, fd, funct),
            0x11 => DisassembleCop1FormatBrief("d", ft, fs, fd, funct),
            0x14 => DisassembleCop1FormatBrief("w", ft, fs, fd, funct),
            _ => $"cop1.{fmt:x2}"
        };
    }

    private static string DisassembleCop1BranchBrief(int rt, short offset)
    {
        string mnemonic = (rt & 0x03) switch
        {
            0x00 => "bc1f",
            0x01 => "bc1t",
            0x02 => "bc1fl",
            0x03 => "bc1tl",
            _ => "bc1"
        };
        int cc = (rt >> 2) & 0x07;
        return cc == 0 ? $"{mnemonic} {offset}" : $"{mnemonic} cc{cc},{offset}";
    }

    private static string DisassembleCop1FormatBrief(string suffix, int ft, int fs, int fd, uint funct)
    {
        return funct switch
        {
            0x00 => $"add.{suffix} f{fd},f{fs},f{ft}",
            0x01 => $"sub.{suffix} f{fd},f{fs},f{ft}",
            0x02 => $"mul.{suffix} f{fd},f{fs},f{ft}",
            0x03 => $"div.{suffix} f{fd},f{fs},f{ft}",
            0x04 => $"sqrt.{suffix} f{fd},f{fs}",
            0x05 => $"abs.{suffix} f{fd},f{fs}",
            0x06 => $"mov.{suffix} f{fd},f{fs}",
            0x07 => $"neg.{suffix} f{fd},f{fs}",
            0x0c => $"round.w.{suffix} f{fd},f{fs}",
            0x0d => $"trunc.w.{suffix} f{fd},f{fs}",
            0x0e => $"ceil.w.{suffix} f{fd},f{fs}",
            0x0f => $"floor.w.{suffix} f{fd},f{fs}",
            0x11 => $"mov{((ft & 1) == 0 ? "f" : "t")}.{suffix} f{fd},f{fs}",
            0x20 => $"cvt.s.{suffix} f{fd},f{fs}",
            0x21 => $"cvt.d.{suffix} f{fd},f{fs}",
            0x24 => $"cvt.w.{suffix} f{fd},f{fs}",
            0x32 => DisassembleCop1CompareBrief($"c.eq.{suffix}", ft, fs, fd),
            0x3c => DisassembleCop1CompareBrief($"c.lt.{suffix}", ft, fs, fd),
            0x3e => DisassembleCop1CompareBrief($"c.le.{suffix}", ft, fs, fd),
            _ => $"cop1.{suffix}.{funct:x2}"
        };
    }

    private static string DisassembleCop1CompareBrief(string mnemonic, int ft, int fs, int fd)
    {
        int cc = (fd >> 2) & 0x07;
        return cc == 0
            ? $"{mnemonic} f{fs},f{ft}"
            : $"{mnemonic} cc{cc},f{fs},f{ft}";
    }

    private static int ParsePositiveInt(string name, int fallback)
    {
        string? raw = Environment.GetEnvironmentVariable(name);
        return TryParsePositiveInt(raw, out int parsed) ? parsed : fallback;
    }

    private static bool TryParsePositiveInt(string? raw, out int parsed)
    {
        parsed = 0;
        if (string.IsNullOrWhiteSpace(raw))
            return false;

        raw = raw.Trim();
        if (raw.StartsWith("0x", StringComparison.OrdinalIgnoreCase))
        {
            return int.TryParse(
                    raw[2..],
                    System.Globalization.NumberStyles.HexNumber,
                    null,
                    out parsed) &&
                parsed > 0;
        }

        return int.TryParse(raw, out parsed) && parsed > 0;
    }

    private static int ParseStepBudget()
    {
        const int defaultBudget = 2048;
        const int bringupFastBudget = 60_000;
        string? raw = Environment.GetEnvironmentVariable("EUTHERDRIVE_GAUNTDL_CPU_STEPS_PER_FRAME");
        if (int.TryParse(raw, out int parsed) && parsed > 0)
            return parsed;

        return GauntletDarkLegacyAdapter.IsBringupFixEnabled("EUTHERDRIVE_GAUNTDL_CPU_STEPS_PER_FRAME_FAST_DEFAULT")
            ? bringupFastBudget
            : defaultBudget;
    }

    private static ulong ParseGlideConfigInt(string? raw, ulong fallback)
    {
        if (!uint.TryParse(raw, out uint parsed))
            return fallback;

        return parsed;
    }

    private static ulong? ParseOptionalHexUlong(string name)
    {
        string? raw = Environment.GetEnvironmentVariable(name);
        if (string.IsNullOrWhiteSpace(raw))
            return null;

        raw = raw.Trim();
        if (raw.StartsWith("0x", StringComparison.OrdinalIgnoreCase))
            raw = raw[2..];

        return ulong.TryParse(raw, System.Globalization.NumberStyles.HexNumber, null, out ulong parsed)
            ? parsed
            : null;
    }

    private static ulong[] ParseOptionalHexUlongList(string? raw)
    {
        if (string.IsNullOrWhiteSpace(raw))
            return [];

        return raw.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Select(item => item.StartsWith("0x", StringComparison.OrdinalIgnoreCase) ? item[2..] : item)
            .Select(item => ulong.TryParse(item, System.Globalization.NumberStyles.HexNumber, null, out ulong value) ? value : 0)
            .Where(value => value != 0)
            .Distinct()
            .ToArray();
    }
}

