    private string GetTexturePixelLodDebugStatus()
        => _experimentTextureMamePixelLod
            ? $"plod={string.Join('/', _experimentTextureMamePixelLodCounts)} "
            : "";

    private string GetTextureUploadLodDebugStatus()
    {
        if (!_debugTextureUploadLods)
            return "";

        IEnumerable<string> lods = Enumerable.Range(0, _textureUploadLodWriteCounts.Length)
            .Where(lod => _textureUploadLodWriteCounts[lod] != 0)
            .Select(lod =>
            {
                string span = _textureUploadLodPhysicalMin[lod] == uint.MaxValue
                    ? "-"
                    : $"{_textureUploadLodPhysicalMin[lod]:X6}-{_textureUploadLodPhysicalMax[lod]:X6}";
                return $"l{lod}:{_textureUploadLodWriteCounts[lod]}/{_textureUploadLodType5WriteCounts[lod]}/{_textureUploadLodNonZeroWriteCounts[lod]}@{span}";
            });
        return $"twlod={string.Join(',', lods)} ";
    }

    private string GetTextureRangeDebugStatus()
    {
        if (!_debugTextureRangeMin.HasValue || !_debugTextureRangeMax.HasValue)
            return "";

        uint start = (uint)Math.Min(_debugTextureRangeMin.Value, TextureBytes);
        uint end = (uint)Math.Min(_debugTextureRangeMax.Value, TextureBytes);
        uint blockBytes = (uint)Math.Clamp(
            _debugTextureRangeBlockBytes.GetValueOrDefault(0x2000),
            4,
            TextureBytes);
        blockBytes = (blockBytes + 3u) & ~3u;
        if (start >= end)
            return "trange=empty ";

        var blocks = new List<string>();
        for (uint blockStart = start & ~3u; blockStart < end; blockStart += blockBytes)
        {
            uint blockEnd = Math.Min(end, blockStart + blockBytes);
            int nonZeroBytes = 0;
            int nonZeroWords = 0;
            int writerWords = 0;
            for (uint byteAddress = blockStart; byteAddress < blockEnd; byteAddress += 4)
            {
                int wordIndex = (int)(byteAddress >> 2);
                uint word = _textureMemory[wordIndex];
                if (word != 0)
                    nonZeroWords++;
                if ((word & 0x000000ffu) != 0)
                    nonZeroBytes++;
                if ((word & 0x0000ff00u) != 0)
                    nonZeroBytes++;
                if ((word & 0x00ff0000u) != 0)
                    nonZeroBytes++;
                if ((word & 0xff000000u) != 0)
                    nonZeroBytes++;
                if (_textureWordLastWriters.ContainsKey(wordIndex))
                    writerWords++;
            }

            blocks.Add($"{blockStart:X6}-{blockEnd - 1:X6}:{nonZeroBytes}/{nonZeroWords}/{writerWords}");
        }

        return $"trange={string.Join(',', blocks)} ";
    }

    private string GetTextureOverwriteDebugStatus()
        => _traceTextureOverwriteRangeMin.HasValue
            ? $"tovr={_textureOverwriteSeedCount}/{_textureOverwriteReassertedWords.Count}/{_textureOverwriteChangedWords.Count}/{_textureOverwriteSeededWords.Count} "
            : "";

    private uint PeekCommandFifoWord() => ReadCommandFifoWordAt(_cmdFifoReadIndex);

    private string GetCommandFifoDecodeStopDebugStatus()
    {
        if (_commandFifoDecodeStopCount == 0)
            return "";

        string pcStatus = _lastCommandFifoDecodeStopPc != 0 ? $"/pc=0x{_lastCommandFifoDecodeStopPc:X}" : "";
        string triggerStatus = _lastCommandFifoDecodeStopTrigger.Length != 0 ? $"/trig={_lastCommandFifoDecodeStopTrigger}" : "";
        string wordStatus = _lastCommandFifoDecodeStopWord0Debug.Length != 0
            ? $"/w0={_lastCommandFifoDecodeStopWord0Debug}/w1={_lastCommandFifoDecodeStopWord1Debug}"
            : "";
        return
            $"cmdstop={_lastCommandFifoDecodeStopReason}/0x{_lastCommandFifoDecodeStopCommand:X8}/" +
            $"{_lastCommandFifoDecodeStopWordsNeeded}/{_lastCommandFifoDecodeStopDepth}/" +
            $"0x{_lastCommandFifoDecodeStopReadIndex * 4:X}/0x{_lastCommandFifoDecodeStopStorageIndex * 4:X}/" +
            $"v{(_lastCommandFifoDecodeStopReadValid ? 1 : 0)}/lg0x{_lastCommandFifoDecodeStopStoredLogicalIndex * 4:X}/" +
            $"vw{_lastCommandFifoDecodeStopValidWindowWords}/" +
            $"0x{_lastCommandFifoDecodeStopNext1:X8}/0x{_lastCommandFifoDecodeStopNext2:X8}{pcStatus}{triggerStatus}{wordStatus}/" +
            $"last=0x{_lastDecodedCommandFifoCommand:X8}:{_lastDecodedCommandFifoWords}:" +
            $"0x{_lastDecodedCommandFifoPacketStart * 4:X}:0x{_lastDecodedCommandFifoReadAfter * 4:X}/" +
            $"{_commandFifoDecodeStopCount} ";
    }

    public virtual void WriteRegister(uint address, uint value)
    {
        uint target = (address >> 2) & 0xfffu;
        uint register = target & 0xffu;
        value = ApplyRegisterWriteMask(register, value);
        if (_fixDropLeakedType5RegisterHeaders &&
            IsRasterSetupRegister(register) &&
            IsType5TexturePacketHeader(value))
        {
            RecordVoodooEvent($"drop leaked type5 header direct reg[{register:x2}]=0x{value:x8}");
            return;
        }

        bool traceTmuWrite = ShouldTraceTmuRegisterWrite(target, register, value);
        string tmuBefore = traceTmuWrite ? FormatTextureRegisterWriteStatus() : "";
        bool wroteTmuBank = _fixTmuRegisterBanks && TryWriteTmuRegister(target, value);
        if (traceTmuWrite)
            TraceTmuRegisterWrite(target, register, value, wroteTmuBank, tmuBefore);

        if (wroteTmuBank)
        {
            TraceVoodooRegisterWrite(register, value);
            if (IsInterestingEventRegister(register))
                RecordVoodooEvent($"reg[{target:x3}]=0x{value:x8}");
            CountCommandFifoRegisterWritePc(register, value);
            return;
        }

        _registers[register] = value;
        _registerWriteCount++;
        TraceVoodooRegisterWrite(register, value);
        TraceFastFillSwapOrder("reg", register, value);
        if (IsInterestingEventRegister(register))
            RecordVoodooEvent($"reg[{register:x3}]=0x{value:x8}");
        switch (register)
        {
            case RegCmdFifoBaseAddr:
                if (_fixMameCommandFifoModel && _experimentMameCommandFifoRegisterWindow)
                    ApplyMameCommandFifoRegisterWindow();
                else
                {
                    _cmdFifoRamBase = (int)((value & 0x000003ffu) << 12);
                    _cmdFifoRamEnd = Math.Clamp((int)((((value >> 16) & 0x000003ffu) + 1u) << 12), 4, CmdFifoWords * 4);
                }
                _cmdFifoGenerationBaseRegisterResets++;
                _cmdFifoGenerationBaseLastResetPc = CpuPcProvider?.Invoke() ?? 0;
                if (!_experimentStandardCommandFifoGenerations)
                {
                    _cmdFifoWriteGenerationBase = 0;
                    _cmdFifoWriteQueueIndex = 0;
                    _cmdFifoLastWriteStorageIndex = -1;
                }
                TraceCommandFifoModel($"reg base value=0x{value:x8}");
                break;
            case RegTriangleCommand:
                MarkCommandFifoRenderWork();
                DrawIntegerTriangle();
                break;
            case RegFtriangleCommand:
                MarkCommandFifoRenderWork();
                DrawFloatTriangle();
                break;
            case RegFastfillCommand:
                MarkCommandFifoRenderWork();
                FastFill();
                break;
            case RegSwapbufferCommand:
                MarkCommandFifoRenderWork();
                SwapBuffers(value);
                break;
            case RegCmdFifoRdPtr:
                int registerReadIndex = (int)(value >> 2);
                if (!_fixMameCommandFifoModel && _experimentStandardCommandFifoGenerations)
                    registerReadIndex = CommandFifoStorageIndex(registerReadIndex) + _cmdFifoWriteGenerationBase;
                SetCommandFifoReadIndex(DecodeCommandFifoReadIndex(registerReadIndex), "reg-rdptr");
                _cmdFifoReadPointerWritten = true;
                TraceCommandFifoModel($"reg rdptr value=0x{value:x8}");
                if (!_decodingCommandFifo)
                    DecodeCommandFifoPackets("reg-rdptr");
                break;
            case RegCmdFifoAddressMin:
                if (_fixMameCommandFifoModel && _experimentMameCommandFifoRegisterWindow)
                    ApplyMameCommandFifoRegisterWindow();
                else
                    _cmdFifoAddressMin = (int)value;
                TraceCommandFifoModel($"reg amin value=0x{value:x8}");
                DecodeCommandFifoAfterRegisterWrite();
                break;
            case RegCmdFifoAddressMax:
                if (_fixMameCommandFifoModel && _experimentMameCommandFifoRegisterWindow)
                    ApplyMameCommandFifoRegisterWindow();
                else
                    _cmdFifoAddressMax = (int)value;
                TraceCommandFifoModel($"reg amax value=0x{value:x8}");
                DecodeCommandFifoAfterRegisterWrite();
                break;
            case RegCmdFifoDepth:
                _cmdFifoDepth = _fixMameCommandFifoModel && _experimentMameCommandFifoFullDepthHolesRegisters
                    ? unchecked((int)value)
                    : (int)(value & 0xffffu);
                TraceCommandFifoModel($"reg depth value=0x{value:x8}");
                DecodeCommandFifoAfterRegisterWrite();
                break;
            case RegCmdFifoHoles:
                _cmdFifoHoles = _fixMameCommandFifoModel && _experimentMameCommandFifoFullDepthHolesRegisters
                    ? unchecked((int)value)
                    : (int)(value & 0xffffu);
                TraceCommandFifoModel($"reg holes value=0x{value:x8}");
                DecodeCommandFifoAfterRegisterWrite();
                break;
            case 0xa8u:
                MarkCommandFifoRenderWork();
                DrawSetupTriangle();
                break;
            case 0xa9u:
                BeginSetupTriangle();
                break;
        }

        CountCommandFifoRegisterWritePc(register, value);
    }

    private void TraceVoodooRegisterWrite(uint register, uint value)
    {
        if (_traceRegisterWriteTargets.Length == 0 ||
            !_traceRegisterWriteTargets.Contains(register))
        {
            return;
        }

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if (_traceRegisterWritePcs.Length != 0 &&
            !_traceRegisterWritePcs.Contains(pc) &&
            !_traceRegisterWritePcs.Contains(pc & 0xffffffffUL))
        {
            return;
        }
        if (_registerWriteTraceCount >= _traceRegisterWritesLimit)
            return;

        _registerWriteTraceCount++;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        string cpuStatus = CpuGprProvider is null
            ? ""
            : $" ra=0x{CpuGprProvider(31):x16} s3=0x{CpuGprProvider(19):x16} s4=0x{CpuGprProvider(20):x16}";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-REGWRITE] n={_registerWriteTraceCount} reg=0x{register:x2} value=0x{value:x8} " +
            $"decode={(_decodingCommandFifo ? 1 : 0)} cmd=0x{_currentCommandFifoCommand:x8}:{_currentCommandFifoWordsNeeded}:0x{_currentCommandFifoPacketStart * 4:x8}:rd0x{_cmdFifoReadIndex * 4:x8} " +
            $"trigger={_commandFifoDecodeTrigger} depth={_cmdFifoDepth} holes={_cmdFifoHoles} " +
            $"setup=0x{_registers[0x98]:x8} rawxy=0x{_registers[0x99]:x8}/0x{_registers[0x9a]:x8} " +
            $"st=0x{_registers[RegFstartS]:x8}/0x{_registers[RegFstartT]:x8}/0x{_registers[0xa3]:x8}/0x{_registers[0xa4]:x8} " +
            $"fbz=0x{_registers[RegFbzMode]:x8} fbzcp=0x{_registers[RegFbzColorPath]:x8} " +
            $"tmode=0x{ReadTextureSampleRegister(RegTextureMode):x8} tlod=0x{ReadTextureSampleRegister(RegTextureLod):x8} " +
            $"tbase=0x{ReadTextureSampleRegister(RegTextureBaseAddr):x8}{cpuStatus}{pcStatus}");
    }

    private uint ApplyRegisterWriteMask(uint register, uint value)
    {
        if (!_fixVoodooRegisterWriteMasks)
            return value;

        int width = GetRegisterWriteWidth(register);
        if (width <= 0 || width >= 32)
            return value;

        return value & ((1u << width) - 1u);
    }

    private static int GetRegisterWriteWidth(uint register)
        => register switch
        {
            >= 0x02u and <= 0x07u => 16,
            >= 0x08u and <= 0x0au => 24,
            0x0cu => 24,
            >= 0x10u and <= 0x12u => 24,
            >= 0x14u and <= 0x16u => 24,
            RegFbzColorPath => 30,
            0x42u => 8,
            RegFbzMode => 22,
            RegLfbMode => 17,
            RegClipLeftRight or RegClipLowYHighY => 28,
            0x48u => 2,
            RegSwapbufferCommand => 10,
            0x4bu => 24,
            0x4du => 24,
            0x4eu => 29,
            0x4fu => 10,
            0x61u => 26,
            0x62u or 0x63u or 0x65u => 25,
            0x66u or 0x67u => 31,
            0x98u => 20,
            0xa8u or 0xa9u => 1,
            >= 0xb0u and <= 0xb2u => 22,
            0xb5u or 0xb6u => 26,
            0xbau => 16,
            RegTextureDetail => 22,
            RegTextureBaseAddr or RegTextureBaseAddr1 or RegTextureBaseAddr2 or RegTextureBaseAddr38 => 19,
            _ => 32
        };

    private void DecodeCommandFifoAfterRegisterWrite()
    {
        if (!_fixMameCommandFifoModel ||
            !_experimentMameCommandFifoDecodeOnRegisterWrite ||
            _decodingCommandFifo)
        {
            return;
        }

        DecodeCommandFifoPacketsIfNotPending("reg-write");
    }

    private void ApplyMameCommandFifoRegisterWindow()
    {
        uint baseValue = _registers[RegCmdFifoBaseAddr];
        _cmdFifoRamBase = (int)((baseValue & 0x000003ffu) << 12);
        _cmdFifoRamEnd = (int)((((baseValue >> 16) & 0x000003ffu) + 1u) << 12);
        _cmdFifoAddressMin = (int)_registers[RegCmdFifoAddressMin];
        _cmdFifoAddressMax = (int)_registers[RegCmdFifoAddressMax];
    }

    private void MarkCommandFifoRenderWork()
    {
        if (_decodingCommandFifo)
            _commandFifoPacketIssuedRenderWork = true;
    }

    private bool IsCommandFifoOperationPending()
        => _fixMameCommandFifoModel &&
           _experimentMameCommandFifoOperationPendingGate &&
           _commandFifoOperationPending;

    public virtual uint ReadRegister(uint address)
    {
        uint register = (address >> 2) & 0xffu;
        uint value = register switch
        {
            RegCmdFifoRdPtr => (uint)(_cmdFifoReadIndex << 2),
            RegCmdFifoDepth => _fixMameCommandFifoModel && _experimentMameCommandFifoFullDepthHolesRegisters
                ? unchecked((uint)_cmdFifoDepth)
                : (uint)Math.Clamp(_cmdFifoDepth, 0, 0xffff),
            RegCmdFifoHoles => _fixMameCommandFifoModel && _experimentMameCommandFifoFullDepthHolesRegisters
                ? unchecked((uint)_cmdFifoHoles)
                : (uint)Math.Clamp(_cmdFifoHoles, 0, 0xffff),
            _ => _registers[register]
        };
        CountCommandFifoRegisterReadPc(register, value);
        return value;
    }

    public virtual void WriteFifo(uint wordOffset, uint value)
    {
        int index = (int)(wordOffset & CmdFifoMask);
        int storageIndex = _fixMameCommandFifoModel && !_experimentMameCommandFifoWriteQueue
            ? CommandFifoStorageIndex((_cmdFifoRamBase >> 2) + index)
            : index;
        int logicalWriteIndex = _fixMameCommandFifoModel && _experimentMameCommandFifoWriteQueue
            ? DecodeCommandFifoReadIndex(_cmdFifoWriteQueueIndex++)
            : GetMameCommandFifoLogicalWriteIndex(index, storageIndex);
        if (_fixMameCommandFifoModel && _experimentMameCommandFifoWriteQueue)
            storageIndex = CommandFifoStorageIndex(logicalWriteIndex);
        int address = logicalWriteIndex * 4;
        if (_cmdFifoBulkFirstWritePending)
        {
            Array.Clear(_cmdFifoValid);
            ClearCommandFifoStorageLastWriters();
            _cmdFifoValidCount = 0;
            SetCommandFifoReadIndex(_fixMameCommandFifoModel ? DecodeCommandFifoReadIndex(logicalWriteIndex) : storageIndex, "bulk-first-write");
            _cmdFifoDepth = 0;
            _cmdFifoHoles = 0;
            _cmdFifoDepthWordsAdded = 0;
            _cmdFifoDepthWordsDecoded = 0;
            _cmdFifoDepthWordsStreamed = 0;
            _cmdFifoWriteGenerationBase = logicalWriteIndex & ~CmdFifoMask;
            _cmdFifoGenerationBaseBulkResets++;
            _cmdFifoGenerationBaseLastResetPc = CpuPcProvider?.Invoke() ?? 0;
            _cmdFifoWriteQueueIndex = logicalWriteIndex;
            _cmdFifoLastWriteStorageIndex = storageIndex;
            _cmdFifoReadPointerWritten = true;
            _cmdFifoJumped = false;
            _cmdFifoBulkFirstWritePending = false;
        }
        if (_cmdFifoBulkWriteDepth > 0)
        {
            if (!_cmdFifoBulkSawWrite)
            {
                _cmdFifoBulkStartIndex = UseMameCommandFifoBulkLogicalWindow() ? logicalWriteIndex : storageIndex;
                _cmdFifoBulkSawWrite = true;
            }
            _cmdFifoBulkLastIndex = UseMameCommandFifoBulkLogicalWindow() ? logicalWriteIndex : storageIndex;
            _cmdFifoBulkWriteWordCount++;
        }

        bool mameWrapInvalidRead =
            _fixMameCommandFifoModel &&
            _experimentMameCommandFifoWrapClearInvalidRead &&
            !_cmdFifoValid[CommandFifoStorageIndex(_cmdFifoReadIndex)];
        if (((!_fixMameCommandFifoModel && !_experimentStandardCommandFifoGenerations) ||
             _experimentMameCommandFifoWrapClear ||
             mameWrapInvalidRead) &&
            storageIndex == 0 &&
            _cmdFifoReadPointerWritten &&
            _cmdFifoReadIndex != 0)
        {
            Array.Clear(_cmdFifoValid);
            ClearCommandFifoStorageLastWriters();
            _cmdFifoValidCount = 0;
            SetCommandFifoReadIndex(_fixMameCommandFifoModel ? address >> 2 : 0, "wrap-clear");
            _cmdFifoDepth = 0;
            _cmdFifoHoles = 0;
            _cmdFifoDepthWordsAdded = 0;
            _cmdFifoDepthWordsDecoded = 0;
            _cmdFifoDepthWordsStreamed = 0;
            _cmdFifoAddressMin = _cmdFifoRamBase - 4;
            _cmdFifoAddressMax = _cmdFifoRamBase - 4;
            _cmdFifoWriteGenerationBase = 0;
            _cmdFifoGenerationBaseWrapClearResets++;
            _cmdFifoGenerationBaseLastResetPc = CpuPcProvider?.Invoke() ?? 0;
            _cmdFifoWriteQueueIndex = 0;
            _cmdFifoLastWriteStorageIndex = -1;
            _cmdFifoJumped = false;
        }

        bool storageWasValid = _cmdFifoValid[storageIndex];
        CaptureCommandFifoProducerBoundaryWrite(storageIndex, logicalWriteIndex, address, value, storageWasValid);
        TrackStandardCommandFifoPacketMapWrite(storageIndex, logicalWriteIndex, value);
        TrackCommandFifoType1ProducerWord(storageIndex, value);
        TrackCommandFifoType3ProducerWord(storageIndex, value);
        TrackCommandFifoType4ProducerWord(storageIndex, value);
        TrackCommandFifoType5ProducerWord(storageIndex, value);
        _cmdFifoRam[storageIndex] = value;
        _cmdFifoStorageLogicalIndex[storageIndex] = logicalWriteIndex;
        RecordCommandFifoStorageLastWrite(
            storageIndex,
            logicalWriteIndex,
            address,
            value,
            CmdFifoStorageWriteSourceFifo);
        if (_fixMameCommandFifoModel)
            TrackMameCommandFifoWrite(address, value);
        else if (!storageWasValid)
            _cmdFifoDepth = Math.Min(0xffff, _cmdFifoDepth + 1);
        if (!storageWasValid)
            _cmdFifoValidCount++;
        _cmdFifoValid[storageIndex] = true;
        _fifoWriteCount++;
        TraceCommandFifoValidity("write", storageIndex);
        TraceCommandFifoAssemblyWrite(wordOffset, storageIndex, logicalWriteIndex, address, value, storageWasValid);
        if (!_fixMameCommandFifoModel)
            TraceCommandFifoStorageWrite(address, value);

        if (!_cmdFifoReadPointerWritten)
        {
            SetCommandFifoReadIndex(_fixMameCommandFifoModel ? DecodeCommandFifoReadIndex(logicalWriteIndex) : storageIndex, "first-read-pointer");
            _cmdFifoReadPointerWritten = true;
        }

        ulong writePc = CpuPcProvider?.Invoke() ?? 0;
        bool deferWriteDecodeForPc = _experimentCommandFifoDeferWriteDecodePcs.Any(
            candidate => (candidate & 0xffffffffUL) == (writePc & 0xffffffffUL));
        if (_cmdFifoBulkWriteDepth == 0 &&
            !deferWriteDecodeForPc &&
            (!_fixMameCommandFifoModel || !_experimentMameCommandFifoDeferWriteDecode))
        {
            if (ShouldResyncCommandFifoOutsideStaleWriteRead(out string outsideStaleWriteResyncReason))
            {
                int oldReadIndex = _cmdFifoReadIndex;
                uint oldReadWord = ReadCommandFifoWordAt(oldReadIndex);
                SetCommandFifoReadIndex(_cmdFifoBulkStartIndex, "write-outside-stale");
                _cmdFifoDepth = Math.Max(_cmdFifoDepth, _cmdFifoBulkWriteWordCount);
                TraceCommandFifoBulkResync("write-outside-stale", outsideStaleWriteResyncReason, oldReadIndex, oldReadWord);
                DecodeCommandFifoPacketsIfNotPending("write");
            }
            else if (ShouldGateCommandFifoStaleWriteRead(out string staleWriteReason))
                TraceCommandFifoBulkDecodeGate($"stale-write:{staleWriteReason}", _cmdFifoReadIndex, ReadCommandFifoWordAt(_cmdFifoReadIndex));
            else if (ShouldGateCommandFifoOutsideStaleWriteRead(out string outsideStaleWriteReason))
                TraceCommandFifoBulkDecodeGate($"outside-stale-write:{outsideStaleWriteReason}", _cmdFifoReadIndex, ReadCommandFifoWordAt(_cmdFifoReadIndex));
            else
                DecodeCommandFifoPacketsIfNotPending("write");
        }
    }

    private int GetMameCommandFifoLogicalWriteIndex(int localIndex, int storageIndex)
    {
        int baseLocalIndex = (_cmdFifoRamBase >> 2) + localIndex;
        if (_fixMameCommandFifoModel &&
            _experimentMameCommandFifoAlignWritesToReadGeneration &&
            _cmdFifoReadPointerWritten &&
            baseLocalIndex < _cmdFifoReadIndex)
        {
            int generationDelta = _cmdFifoReadIndex - baseLocalIndex;
            int generations = (generationDelta + CmdFifoWords - 1) / CmdFifoWords;
            return baseLocalIndex + generations * CmdFifoWords;
        }

        if (!_fixMameCommandFifoModel && !_experimentStandardCommandFifoGenerations)
            return baseLocalIndex;
        if (_fixMameCommandFifoModel && !_experimentMameCommandFifoTrackWriteGeneration)
            return baseLocalIndex;

        if (_cmdFifoLastWriteStorageIndex >= 0 &&
            storageIndex < _cmdFifoLastWriteStorageIndex &&
            _cmdFifoLastWriteStorageIndex - storageIndex > CmdFifoWords / 2)
        {
            _cmdFifoWriteGenerationBase += CmdFifoWords;
            _cmdFifoGenerationBaseWrapAdvances++;
        }

        _cmdFifoLastWriteStorageIndex = storageIndex;
        return baseLocalIndex + _cmdFifoWriteGenerationBase;
    }

    private void TrackStandardCommandFifoPacketMapWrite(int storageIndex, int logicalWriteIndex, uint value)
    {
        if (_fixMameCommandFifoModel || !_experimentStandardCommandFifoGenerations)
            return;

        ulong producer = CpuPcProvider?.Invoke() ?? 0;
        if (_experimentStandardCommandFifoGlobalPacketState)
        {
            // FIFO packet ownership follows contiguous logical write order,
            // not the individual store instruction. Glide's bulk writers use
            // several alternating store PCs for one header/body stream.
            producer = 0UL;
        }
        _cmdFifoPacketMapProducerStates.TryGetValue(producer, out PacketMapProducerState state);
        int normalized = CommandFifoStorageIndex(storageIndex);
        if (_cmdFifoStoragePacketOwnerValid[normalized])
            _cmdFifoCompletePacketHeaders.Remove(_cmdFifoStoragePacketOwnerHeaderLogicalIndex[normalized]);
        bool sequentialBody = logicalWriteIndex == state.NextLogicalIndex &&
                              state.BodyWordsRemaining > 0;
        if (sequentialBody)
        {
            _cmdFifoPacketMapBodyWrites++;
            _cmdFifoStoragePacketHeader[normalized] = false;
            _cmdFifoStoragePacketEndLogicalIndex[normalized] = state.PacketEndLogicalIndex;
            _cmdFifoStoragePacketOwnerValid[normalized] = true;
            _cmdFifoStoragePacketOwnerHeaderLogicalIndex[normalized] = state.HeaderLogicalIndex;
            state = state with { BodyWordsRemaining = state.BodyWordsRemaining - 1 };
            if (state.BodyWordsRemaining == 0)
                _cmdFifoCompletePacketHeaders.Add(state.HeaderLogicalIndex);
        }
        else
        {
            int wordsNeeded = Math.Max(1, GetFifoPacketWordsNeeded(value));
            bool plausibleHeader = (value & 7u) <= 5u &&
                                   !IsImplausibleCommandFifoPacket(value, wordsNeeded) &&
                                   wordsNeeded <= CmdFifoWords;
            _cmdFifoStoragePacketHeader[normalized] = plausibleHeader;
            if (plausibleHeader)
            {
                _cmdFifoPacketMapHeaderWrites++;
                int packetEnd = logicalWriteIndex + wordsNeeded - 1;
                state = state with { BodyWordsRemaining = wordsNeeded - 1, PacketEndLogicalIndex = packetEnd, HeaderLogicalIndex = logicalWriteIndex };
                _cmdFifoStoragePacketEndLogicalIndex[normalized] = packetEnd;
                _cmdFifoStoragePacketOwnerValid[normalized] = true;
                _cmdFifoStoragePacketOwnerHeaderLogicalIndex[normalized] = logicalWriteIndex;
                if (wordsNeeded == 1)
                    _cmdFifoCompletePacketHeaders.Add(logicalWriteIndex);
            }
            else
            {
                state = state with { BodyWordsRemaining = 0 };
                _cmdFifoStoragePacketEndLogicalIndex[normalized] = logicalWriteIndex;
                _cmdFifoStoragePacketOwnerValid[normalized] = false;
            }
        }

        state = state with { NextLogicalIndex = logicalWriteIndex + 1 };
        _cmdFifoPacketMapProducerStates[producer] = state;
    }

    private void TrackCommandFifoType3ProducerWord(int storageIndex, uint value)
    {
        if (!_experimentCommandFifoGateType3ProducerBodyHeader &&
            !_experimentCommandFifoAdvanceType3ProducerBodyHeader)
            return;

        int normalized = CommandFifoStorageIndex(storageIndex);
        uint type = value & 7u;
        uint code = (value >> 3) & 7u;
        uint vertices = (value >> 6) & 0x0fu;
        bool type3Header = type == 3u && code <= 2u && vertices > 0;
        ulong writePc = CpuPcProvider?.Invoke() ?? 0;
        bool explicitHeaderPc = _experimentCommandFifoType3ProducerHeaderPcs.Length == 0 ||
                                _experimentCommandFifoType3ProducerHeaderPcs.Any(
                                    candidate => (candidate & 0xffffffffUL) == (writePc & 0xffffffffUL));
        bool resyncHeader = type3Header && explicitHeaderPc;
        bool body = normalized == _cmdFifoType3ProducerNextStorageIndex &&
                    _cmdFifoType3ProducerBodyWordsRemaining > 0;
        if (resyncHeader)
        {
            _cmdFifoStorageType3Body[normalized] = false;
            _cmdFifoType3ProducerBodyWordsRemaining = GetFifoType3WordsNeeded(value) - 1;
            _cmdFifoType3ProducerPacketEnd = CommandFifoStorageIndex(normalized + _cmdFifoType3ProducerBodyWordsRemaining);
        }
        else if (body)
        {
            _cmdFifoStorageType3Body[normalized] = true;
            _cmdFifoStorageType3PacketEnd[normalized] = _cmdFifoType3ProducerPacketEnd;
            _cmdFifoType3ProducerBodyWordsRemaining--;
        }
        else
        {
            _cmdFifoStorageType3Body[normalized] = false;
            _cmdFifoType3ProducerBodyWordsRemaining = 0;
        }

        _cmdFifoType3ProducerNextStorageIndex = CommandFifoStorageIndex(normalized + 1);
    }

    private void TrackCommandFifoType1ProducerWord(int storageIndex, uint value)
    {
        if (!_experimentCommandFifoGateType1ProducerBodyHeader &&
            !_experimentCommandFifoAdvanceType1ProducerBodyHeader)
            return;

        int normalized = CommandFifoStorageIndex(storageIndex);
        bool body = normalized == _cmdFifoType1ProducerNextStorageIndex &&
                    _cmdFifoType1ProducerBodyWordsRemaining > 0;
        if (body)
        {
            _cmdFifoStorageType1Body[normalized] = true;
            _cmdFifoStorageType1PacketEnd[normalized] = _cmdFifoType1ProducerPacketEnd;
            _cmdFifoType1ProducerBodyWordsRemaining--;
        }
        else if ((value & 7u) == 1u)
        {
            _cmdFifoStorageType1Body[normalized] = false;
            _cmdFifoType1ProducerBodyWordsRemaining = GetFifoPacketWordsNeeded(value) - 1;
            _cmdFifoType1ProducerPacketEnd = CommandFifoStorageIndex(normalized + _cmdFifoType1ProducerBodyWordsRemaining);
        }
        else
        {
            _cmdFifoStorageType1Body[normalized] = false;
            _cmdFifoType1ProducerBodyWordsRemaining = 0;
        }

        _cmdFifoType1ProducerNextStorageIndex = CommandFifoStorageIndex(normalized + 1);
    }

    private void TrackCommandFifoType5ProducerWord(int storageIndex, uint value)
    {
        if (!_experimentCommandFifoGateType5ProducerBodyHeader &&
            !_experimentCommandFifoAdvanceType5ProducerBodyHeader)
            return;

        int normalized = CommandFifoStorageIndex(storageIndex);
        if (IsType5TexturePacketHeader(value))
        {
            _cmdFifoStorageType5Body[normalized] = false;
            _cmdFifoType5ProducerBodyWordsRemaining = GetFifoPacketWordsNeeded(value) - 1;
            _cmdFifoType5ProducerPacketEnd = CommandFifoStorageIndex(normalized + _cmdFifoType5ProducerBodyWordsRemaining);
        }
        else
        {
            bool body = normalized == _cmdFifoType5ProducerNextStorageIndex &&
                        _cmdFifoType5ProducerBodyWordsRemaining > 0;
            _cmdFifoStorageType5Body[normalized] = body;
            if (body)
            {
                _cmdFifoStorageType5PacketEnd[normalized] = _cmdFifoType5ProducerPacketEnd;
                _cmdFifoType5ProducerBodyWordsRemaining--;
            }
            else
            {
                _cmdFifoType5ProducerBodyWordsRemaining = 0;
            }
        }

        _cmdFifoType5ProducerNextStorageIndex = CommandFifoStorageIndex(normalized + 1);
    }

    private void TrackCommandFifoType4ProducerWord(int storageIndex, uint value)
    {
        if (!_experimentCommandFifoGateType4ProducerBodyHeader &&
            !_experimentCommandFifoAdvanceType4ProducerBodyHeader)
            return;

        int normalized = CommandFifoStorageIndex(storageIndex);
        bool body = normalized == _cmdFifoType4ProducerNextStorageIndex &&
                    _cmdFifoType4ProducerBodyWordsRemaining > 0;
        if (body)
        {
            _cmdFifoStorageType4Body[normalized] = true;
            _cmdFifoStorageType4PacketEnd[normalized] = _cmdFifoType4ProducerPacketEnd;
            _cmdFifoType4ProducerBodyWordsRemaining--;
        }
        else if ((value & 7u) == 4u)
        {
            _cmdFifoStorageType4Body[normalized] = false;
            _cmdFifoType4ProducerBodyWordsRemaining = GetFifoPacketWordsNeeded(value) - 1;
            _cmdFifoType4ProducerPacketEnd = CommandFifoStorageIndex(normalized + _cmdFifoType4ProducerBodyWordsRemaining);
        }
        else
        {
            _cmdFifoStorageType4Body[normalized] = false;
            _cmdFifoType4ProducerBodyWordsRemaining = 0;
        }

        _cmdFifoType4ProducerNextStorageIndex = CommandFifoStorageIndex(normalized + 1);
    }

    private void ClearCommandFifoStorageLastWriters()
    {
        Array.Clear(_cmdFifoStoragePacketHeader);
        Array.Clear(_cmdFifoStoragePacketEndLogicalIndex);
        Array.Clear(_cmdFifoStoragePacketOwnerValid);
        Array.Clear(_cmdFifoStoragePacketOwnerHeaderLogicalIndex);
        _cmdFifoCompletePacketHeaders.Clear();
        Array.Clear(_cmdFifoStorageLastWritePc);
        Array.Clear(_cmdFifoStorageLastWriteValue);
        Array.Clear(_cmdFifoStorageLastWriteLogicalIndex);
        Array.Clear(_cmdFifoStorageLastWriteAddress);
        Array.Clear(_cmdFifoStorageLastWriteSequence);
        Array.Clear(_cmdFifoStorageLastWriteSource);
        Array.Clear(_cmdFifoStorageType1Body);
        Array.Clear(_cmdFifoStorageType1PacketEnd);
        Array.Clear(_cmdFifoStorageType3Body);
        Array.Clear(_cmdFifoStorageType3PacketEnd);
        Array.Clear(_cmdFifoStorageType4Body);
        Array.Clear(_cmdFifoStorageType4PacketEnd);
        Array.Clear(_cmdFifoStorageType5Body);
        Array.Clear(_cmdFifoStorageType5PacketEnd);
        _cmdFifoStorageBulkWriteSources.Clear();
        _cmdFifoLogicalPacketBulkWriteSources.Clear();
        _cmdFifoStorageWriteSequence = 0;
        _cmdFifoPacketMapProducerStates.Clear();
        _cmdFifoPacketMapHeaderWrites = 0;
        _cmdFifoPacketMapBodyWrites = 0;
        _cmdFifoPacketMapResyncs = 0;
        _cmdFifoPacketMapResyncMisses = 0;
        _cmdFifoType1ProducerNextStorageIndex = -1;
        _cmdFifoType1ProducerBodyWordsRemaining = 0;
        _cmdFifoType1ProducerPacketEnd = 0;
        _cmdFifoType3ProducerNextStorageIndex = -1;
        _cmdFifoType3ProducerBodyWordsRemaining = 0;
        _cmdFifoType3ProducerPacketEnd = 0;
        _cmdFifoType4ProducerNextStorageIndex = -1;
        _cmdFifoType4ProducerBodyWordsRemaining = 0;
        _cmdFifoType4ProducerPacketEnd = 0;
        _cmdFifoType5ProducerNextStorageIndex = -1;
        _cmdFifoType5ProducerBodyWordsRemaining = 0;
        _cmdFifoType5ProducerPacketEnd = 0;
    }

    private void RecordCommandFifoStorageLastWrite(
        int storageIndex,
        int logicalWriteIndex,
        int address,
        uint value,
        byte source)
    {
        int normalizedStorageIndex = CommandFifoStorageIndex(storageIndex);
        _cmdFifoStorageWriteSequence++;
        _cmdFifoStorageLastWriteSequence[normalizedStorageIndex] = _cmdFifoStorageWriteSequence;
        _cmdFifoStorageLastWritePc[normalizedStorageIndex] = CpuPcProvider?.Invoke() ?? 0;
        _cmdFifoStorageLastWriteLogicalIndex[normalizedStorageIndex] = logicalWriteIndex;
        _cmdFifoStorageLastWriteAddress[normalizedStorageIndex] = address;
        _cmdFifoStorageLastWriteValue[normalizedStorageIndex] = value;
        _cmdFifoStorageLastWriteSource[normalizedStorageIndex] = source;
        if (_cmdFifoBulkWriteSourceActive && source == CmdFifoStorageWriteSourceFifo)
        {
            _cmdFifoStorageBulkWriteSources[normalizedStorageIndex] = _cmdFifoBulkWriteSource;
            if (_cmdFifoBulkWriteSource.Word == uint.MaxValue &&
                (_traceTexturedTriangleSampleWriters ||
                 _traceTextureSampleWriters ||
                 _traceTexturedTriangleSampleSummaryRequireWriter))
            {
                _cmdFifoLogicalPacketBulkWriteSources[logicalWriteIndex] = _cmdFifoBulkWriteSource;
            }
        }
        else
            _cmdFifoStorageBulkWriteSources.Remove(normalizedStorageIndex);
    }

    private void SetCommandFifoReadIndex(int readIndex, string reason, uint command = 0, int wordsNeeded = 0)
    {
        int oldReadIndex = _cmdFifoReadIndex;
        _cmdFifoReadIndex = readIndex;
        TraceCommandFifoReadIndexChange(reason, oldReadIndex, readIndex, command, wordsNeeded);
    }

    private void TraceCommandFifoReadIndexChange(string reason, int oldReadIndex, int newReadIndex, uint command, int wordsNeeded)
    {
        if (!_traceCommandFifoReadIndex || oldReadIndex == newReadIndex)
            return;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if (_traceCommandFifoReadIndexPcs.Length != 0 && !_traceCommandFifoReadIndexPcs.Contains(pc))
            return;

        int oldStorage = CommandFifoReadStorageIndex(oldReadIndex);
        int newStorage = CommandFifoReadStorageIndex(newReadIndex);
        if (_traceCommandFifoReadIndexStorageOffsets.Length != 0 &&
            !_traceCommandFifoReadIndexStorageOffsets.Contains((ulong)(oldStorage * 4)) &&
            !_traceCommandFifoReadIndexStorageOffsets.Contains((ulong)(newStorage * 4)))
        {
            return;
        }

        if (_commandFifoReadIndexTraceCount >= _traceCommandFifoReadIndexLimit)
            return;

        _commandFifoReadIndexTraceCount++;
        uint oldWord = _cmdFifoRam[oldStorage];
        uint newWord = _cmdFifoRam[newStorage];
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        string commandStatus = command != 0 || wordsNeeded != 0
            ? $" command=0x{command:x8}:{wordsNeeded}"
            : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-CMDFIFO-READ] n={_commandFifoReadIndexTraceCount} reason={reason} " +
            $"old=0x{oldReadIndex * 4:x8}/0x{oldStorage * 4:x5} new=0x{newReadIndex * 4:x8}/0x{newStorage * 4:x5} " +
            $"oldWord=0x{oldWord:x8} newWord=0x{newWord:x8} oldValid={(_cmdFifoValid[oldStorage] ? 1 : 0)} newValid={(_cmdFifoValid[newStorage] ? 1 : 0)} " +
            $"depth={_cmdFifoDepth} holes={_cmdFifoHoles} valid={_cmdFifoValidCount} " +
            $"amin=0x{_cmdFifoAddressMin:x8} amax=0x{_cmdFifoAddressMax:x8} trigger={_commandFifoDecodeTrigger}{commandStatus} " +
            $"current=0x{_currentCommandFifoCommand:x8}:{_currentCommandFifoWordsNeeded}:0x{_currentCommandFifoPacketStart * 4:x8} " +
            $"bulk=0x{_cmdFifoBulkStartIndex * 4:x8}:0x{_cmdFifoBulkLastIndex * 4:x8}:{_cmdFifoBulkWriteWordCount} " +
            $"oldDbg={FormatCommandFifoStorageIndexDebug(oldStorage)} " +
            $"newDbg={FormatCommandFifoStorageIndexDebug(newStorage)}{pcStatus}");
    }

    private void TraceCommandFifoModel(string message, uint? value = null)
    {
        if (!_traceCommandFifoModel)
            return;
        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if (_traceCommandFifoModelPcs.Length != 0 && !_traceCommandFifoModelPcs.Contains(pc))
            return;
        if (value.HasValue &&
            _traceCommandFifoModelCommands.Length != 0 &&
            !_traceCommandFifoModelCommands.Contains(value.Value))
        {
            return;
        }
        if (_commandFifoModelTraceCount++ >= _traceCommandFifoModelLimit)
            return;

        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-CMDFIFO] {message} " +
            $"base=0x{_cmdFifoRamBase:x5} end=0x{_cmdFifoRamEnd:x5} rd=0x{_cmdFifoReadIndex * 4:x5} " +
            $"amin=0x{_cmdFifoAddressMin:x5} amax=0x{_cmdFifoAddressMax:x5} depth={_cmdFifoDepth} holes={_cmdFifoHoles} valid={_cmdFifoValidCount} " +
            $"fbi7=0x{_registers[RegFbiInit7]:x8}{pcStatus}");
    }

    private void TraceCommandFifoValidity(string reason, int storageIndex)
    {
        if (!_traceCommandFifoValidity || !_fixMameCommandFifoModel)
            return;

        int readStorage = CommandFifoStorageIndex(_cmdFifoReadIndex);
        bool readValid = _cmdFifoValid[readStorage];
        int excessDepth = _cmdFifoDepth - _cmdFifoValidCount;
        if (_cmdFifoDepth == 0 && _cmdFifoValidCount == 0)
            return;
        if (!readValid && _cmdFifoDepth <= 0)
            return;
        if (readValid && excessDepth <= 64)
            return;
        if (_commandFifoValidityTraceCount++ >= _traceCommandFifoValidityLimit)
            return;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-CMDFIFO-VALID] n={_commandFifoValidityTraceCount} reason={reason} " +
            $"rd=0x{_cmdFifoReadIndex * 4:x8} storage=0x{readStorage * 4:x5} readValid={(readValid ? 1 : 0)} " +
            $"touched=0x{CommandFifoStorageIndex(storageIndex) * 4:x5} depth={_cmdFifoDepth} holes={_cmdFifoHoles} valid={_cmdFifoValidCount} excess={excessDepth} " +
            $"amin=0x{_cmdFifoAddressMin:x8} amax=0x{_cmdFifoAddressMax:x8} " +
            $"fifoPackets={_fifoPacketCount} drawPackets={_fifoDrawPacketCount}{pcStatus}");
    }

    private void TrackMameCommandFifoWrite(int address, uint value)
    {
        if (!_experimentMameCommandFifoTrackWriteGeneration && (uint)address >= (uint)_cmdFifoRamEnd)
        {
            CountCommandFifoWritePc(0, 0, 0, address, value);
            return;
        }
        if (((_registers[RegFbiInit7] >> 10) & 1u) != 0)
        {
            CountCommandFifoWritePc(1, 0, 0, address, value);
            return;
        }
        if (_cmdFifoDepth == 0 && _cmdFifoHoles == 0 && _cmdFifoAddressMin < _cmdFifoRamBase)
        {
            _cmdFifoAddressMin = address - 4;
            _cmdFifoAddressMax = address - 4;
        }

        int depthBefore = _cmdFifoDepth;
        int holesBefore = _cmdFifoHoles;
        int mode;
        if (_cmdFifoHoles == 0 && address == _cmdFifoAddressMin + 4)
        {
            mode = 2;
            if (_experimentMameCommandFifoExactHoleAccounting || !_experimentMameCommandFifoAccumulateAddressWindow)
                _cmdFifoAddressMin = address;
            _cmdFifoAddressMax = address;
            _cmdFifoDepth++;
            _cmdFifoDepthWordsAdded++;
        }
        else if (address < _cmdFifoAddressMin)
        {
            mode = 3;
            _cmdFifoHoles += _experimentMameCommandFifoExactHoleAccounting
                ? (address - _cmdFifoRamBase) / 4
                : Math.Max(0, (address - _cmdFifoRamBase) / 4);
            _cmdFifoAddressMin = _cmdFifoRamBase;
            _cmdFifoAddressMax = address;
            _cmdFifoDepth++;
            _cmdFifoDepthWordsAdded++;
        }
        else if (address < _cmdFifoAddressMax)
        {
            mode = 4;
            if (_experimentMameCommandFifoExactHoleAccounting || _cmdFifoHoles > 0)
                _cmdFifoHoles--;
            if (_cmdFifoHoles == 0)
            {
                _cmdFifoDepth += _experimentMameCommandFifoExactHoleAccounting
                    ? (_cmdFifoAddressMax - _cmdFifoAddressMin) / 4
                    : Math.Max(0, (_cmdFifoAddressMax - _cmdFifoAddressMin) / 4);
                _cmdFifoDepthWordsAdded += _experimentMameCommandFifoExactHoleAccounting
                    ? (_cmdFifoAddressMax - _cmdFifoAddressMin) / 4
                    : Math.Max(0, (_cmdFifoAddressMax - _cmdFifoAddressMin) / 4);
                _cmdFifoAddressMin = _cmdFifoAddressMax;
            }
        }
        else
        {
            mode = 5;
            _cmdFifoHoles += _experimentMameCommandFifoExactHoleAccounting
                ? (address - _cmdFifoAddressMax) / 4 - 1
                : Math.Max(0, (address - _cmdFifoAddressMax) / 4 - 1);
            _cmdFifoAddressMax = address;
        }
        CountCommandFifoWritePc(mode, _cmdFifoDepth - depthBefore, _cmdFifoHoles - holesBefore, address, value);
        if (_traceCommandFifoModelStorageOffsets.Length == 0)
            TraceCommandFifoModel($"write addr=0x{address:x5} value=0x{value:x8}", value);
        TraceCommandFifoStorageWrite(address, value);
    }

    private void TraceCommandFifoStorageWrite(int address, uint value)
    {
        if (!_traceCommandFifoModel || _traceCommandFifoModelStorageOffsets.Length == 0)
            return;

        int storageByteOffset = CommandFifoStorageIndex(address >> 2) * 4;
        if (!_traceCommandFifoModelStorageOffsets.Contains((ulong)storageByteOffset))
            return;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if (_traceCommandFifoModelPcs.Length != 0 && !_traceCommandFifoModelPcs.Contains(pc))
            return;
        if (_commandFifoModelTraceCount++ >= _traceCommandFifoModelLimit)
            return;

        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-CMDFIFO] storage-write storage=0x{storageByteOffset:x5} " +
            $"addr=0x{address:x8} value=0x{value:x8} " +
            $"base=0x{_cmdFifoRamBase:x5} end=0x{_cmdFifoRamEnd:x5} rd=0x{_cmdFifoReadIndex * 4:x8} " +
            $"amin=0x{_cmdFifoAddressMin:x8} amax=0x{_cmdFifoAddressMax:x8} depth={_cmdFifoDepth} holes={_cmdFifoHoles} valid={_cmdFifoValidCount} " +
            $"fbi7=0x{_registers[RegFbiInit7]:x8}{pcStatus}");
    }

    private void TraceCommandFifoAssemblyWrite(
        uint wordOffset,
        int storageIndex,
        int logicalWriteIndex,
        int address,
        uint value,
        bool storageWasValid)
    {
        if (!_traceCommandFifoAssembly)
            return;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if (_traceCommandFifoAssemblyPcs.Length != 0 && !_traceCommandFifoAssemblyPcs.Contains(pc))
            return;
        if (_traceCommandFifoAssemblyCommands.Length != 0 && !_traceCommandFifoAssemblyCommands.Contains(value))
            return;
        if (_commandFifoAssemblyTraceCount++ >= _traceCommandFifoAssemblyLimit)
            return;

        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        string word0 = FormatCommandFifoStorageIndexDebug(storageIndex);
        string word1 = FormatCommandFifoStorageIndexDebug(logicalWriteIndex + 1);
        string wordPrev = FormatCommandFifoStorageIndexDebug(logicalWriteIndex - 1);
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-CMDFIFO-ASSEMBLY] n={_commandFifoAssemblyTraceCount} " +
            $"wordOffset=0x{wordOffset:x5} addr=0x{address:x8} storage=0x{storageIndex * 4:x5} " +
            $"logical=0x{logicalWriteIndex * 4:x8} value=0x{value:x8} validBefore={(storageWasValid ? 1 : 0)} " +
            $"rd=0x{_cmdFifoReadIndex * 4:x8} depth={_cmdFifoDepth} holes={_cmdFifoHoles} valid={_cmdFifoValidCount} " +
            $"bulk={_cmdFifoBulkWriteDepth}/0x{_cmdFifoBulkStartIndex * 4:x8}/0x{_cmdFifoBulkLastIndex * 4:x8}/{_cmdFifoBulkWriteWordCount}/{(_cmdFifoBulkSawWrite ? 1 : 0)} " +
            $"prev={wordPrev} w0={word0} w1={word1}{pcStatus}");
    }

    private void CaptureCommandFifoProducerBoundaryWrite(
        int storageIndex,
        int logicalWriteIndex,
        int address,
        uint value,
        bool storageWasValid)
    {
        if (!_traceCommandFifoProducerBoundary || _cmdFifoBulkWriteDepth <= 0)
            return;

        if (_cmdFifoBulkProducerWordTraceCount >= _cmdFifoBulkProducerWordValues.Length)
            return;

        int slot = _cmdFifoBulkProducerWordTraceCount++;
        _cmdFifoBulkProducerWordValues[slot] = value;
        _cmdFifoBulkProducerWordStorageIndexes[slot] = CommandFifoStorageIndex(storageIndex);
        _cmdFifoBulkProducerWordLogicalIndexes[slot] = logicalWriteIndex;
        _cmdFifoBulkProducerWordAddresses[slot] = address;
        _cmdFifoBulkProducerWordValidBefore[slot] = storageWasValid;
    }

    public void BeginCommandFifoBulkWrite()
    {
        if (_cmdFifoBulkWriteDepth++ == 0 && _experimentResetCommandFifoOnBulkWrite)
            _cmdFifoBulkFirstWritePending = true;
        if (_cmdFifoBulkWriteDepth == 1)
        {
            _cmdFifoBulkSawWrite = false;
            _cmdFifoBulkStartIndex = 0;
            _cmdFifoBulkLastIndex = 0;
            _cmdFifoBulkWriteWordCount = 0;
            _cmdFifoBulkBeginReadIndex = _cmdFifoReadIndex;
            _cmdFifoBulkBeginDepth = _cmdFifoDepth;
            _cmdFifoBulkBeginHoles = _cmdFifoHoles;
            _cmdFifoBulkBeginValidCount = _cmdFifoValidCount;
            _cmdFifoBulkBeginAddressMin = _cmdFifoAddressMin;
            _cmdFifoBulkBeginAddressMax = _cmdFifoAddressMax;
            _cmdFifoBulkProducerWordTraceCount = 0;
        }
    }

    public void EndCommandFifoBulkWrite()
    {
        if (_cmdFifoBulkWriteDepth > 0)
            _cmdFifoBulkWriteDepth--;
        if (_cmdFifoBulkWriteDepth == 0)
            _cmdFifoBulkFirstWritePending = false;
        if (_cmdFifoBulkWriteDepth == 0 &&
            _experimentRewindCommandFifoOnBulkWrite &&
            _cmdFifoBulkSawWrite &&
            IsCommandFifoReadIndexInsideBulkWrite() &&
            IsType5TexturePacketHeader(_cmdFifoRam[CommandFifoStorageIndex(_cmdFifoBulkStartIndex)]))
        {
            SetCommandFifoReadIndex(_cmdFifoBulkStartIndex, "bulk-rewind");
        }
        if (_cmdFifoBulkWriteDepth == 0 &&
            _fixMameCommandFifoModel &&
            _experimentMameCommandFifoBulkResyncInvalidRead &&
            _cmdFifoBulkSawWrite &&
            _cmdFifoDepth > 0 &&
            !_cmdFifoValid[CommandFifoStorageIndex(_cmdFifoReadIndex)])
        {
            SetCommandFifoReadIndex(_cmdFifoBulkStartIndex, "bulk-invalid-read");
        }
        if (_cmdFifoBulkWriteDepth == 0 &&
            _experimentCommandFifoBulkDecodeWindow &&
            _cmdFifoBulkSawWrite &&
            IsType5TexturePacketHeader(_cmdFifoRam[CommandFifoStorageIndex(_cmdFifoBulkStartIndex)]))
        {
            SetCommandFifoReadIndex(_cmdFifoBulkStartIndex, "bulk-decode-window");
            _cmdFifoBulkDecodeRemainingWords = _cmdFifoBulkWriteWordCount;
        }
        if (_cmdFifoBulkWriteDepth == 0 &&
            _experimentCommandFifoBulkResyncLowRead &&
            _cmdFifoBulkSawWrite &&
            ShouldResyncCommandFifoReadToBulkStart())
        {
            SetCommandFifoReadIndex(_cmdFifoBulkStartIndex, "bulk-low-read");
            _cmdFifoDepth = Math.Max(_cmdFifoDepth, _cmdFifoBulkWriteWordCount);
        }
        if (_cmdFifoBulkWriteDepth == 0 &&
            _experimentCommandFifoBulkResyncStalePacket &&
            _cmdFifoBulkSawWrite &&
            ShouldResyncCommandFifoStalePacketReadToBulkStart(out string stalePacketReason))
        {
            int oldReadIndex = _cmdFifoReadIndex;
            uint oldReadWord = ReadCommandFifoWordAt(oldReadIndex);
            SetCommandFifoReadIndex(_cmdFifoBulkStartIndex, $"bulk-stale-packet:{stalePacketReason}");
            _cmdFifoDepth = Math.Max(_cmdFifoDepth, _cmdFifoBulkWriteWordCount);
            TraceCommandFifoBulkResync("stale-packet", stalePacketReason, oldReadIndex, oldReadWord);
        }
        if (_cmdFifoBulkWriteDepth == 0 &&
            _experimentCommandFifoBulkResyncWrapTail &&
            _cmdFifoBulkSawWrite &&
            ShouldResyncCommandFifoWrappedBulkTailToStart())
        {
            int oldReadIndex = _cmdFifoReadIndex;
            uint oldReadWord = ReadCommandFifoWordAt(oldReadIndex);
            SetCommandFifoReadIndex(_cmdFifoBulkStartIndex, "bulk-wrap-tail");
            _cmdFifoDepth = Math.Max(_cmdFifoDepth, _cmdFifoBulkWriteWordCount);
            TraceCommandFifoBulkResync("wrap-tail", "type5", oldReadIndex, oldReadWord);
        }
        if (_cmdFifoBulkWriteDepth == 0 &&
            _experimentCommandFifoBulkResyncPayloadToHead &&
            _cmdFifoBulkSawWrite &&
            TryFindCurrentBulkPacketBodyHead(_cmdFifoReadIndex, out int packetHeadIndex, out int packetHeadBulkOffset))
        {
            int oldReadIndex = _cmdFifoReadIndex;
            uint oldReadWord = ReadCommandFifoWordAt(oldReadIndex);
            SetCommandFifoReadIndex(packetHeadIndex, "bulk-payload-head");
            _cmdFifoDepth = Math.Max(_cmdFifoDepth, _cmdFifoBulkWriteWordCount - packetHeadBulkOffset);
            TraceCommandFifoBulkResync("payload-head", "body", oldReadIndex, oldReadWord);
        }
        if (_cmdFifoBulkWriteDepth == 0 &&
            _experimentCommandFifoBulkAdvancePayloadToNextHead &&
            _cmdFifoBulkSawWrite &&
            TryFindCurrentBulkType5PayloadNextHead(
                _cmdFifoReadIndex,
                out int nextPacketHeadIndex,
                out int nextPacketHeadBulkOffset,
                out int readPacketOffset,
                out int packetWords))
        {
            int oldReadIndex = _cmdFifoReadIndex;
            uint oldReadWord = ReadCommandFifoWordAt(oldReadIndex);
            SetCommandFifoReadIndex(nextPacketHeadIndex, "bulk-payload-next-head");
            _cmdFifoDepth = Math.Max(_cmdFifoDepth, _cmdFifoBulkWriteWordCount - nextPacketHeadBulkOffset);
            TraceCommandFifoBulkResync(
                "payload-next-head",
                $"type5:off{readPacketOffset}/{packetWords}",
                oldReadIndex,
                oldReadWord);
        }
        if (_cmdFifoBulkWriteDepth == 0 &&
            _experimentCommandFifoBulkInvalidatePayloadRemainder &&
            _cmdFifoBulkSawWrite &&
            TryFindCurrentBulkType5PayloadNextHead(
                _cmdFifoReadIndex,
                out _,
                out _,
                out int invalidateReadPacketOffset,
                out int invalidatePacketWords))
        {
            int oldReadIndex = _cmdFifoReadIndex;
            uint oldReadWord = ReadCommandFifoWordAt(oldReadIndex);
            int invalidated = InvalidateCommandFifoWords(oldReadIndex, invalidatePacketWords - invalidateReadPacketOffset);
            TraceCommandFifoBulkResync(
                "payload-invalidate",
                $"type5:off{invalidateReadPacketOffset}/{invalidatePacketWords}:invalid{invalidated}",
                oldReadIndex,
                oldReadWord);
        }
        bool skipBulkEndDecode = false;
        string bulkEndDecodeGateReason = "";
        if (_cmdFifoBulkWriteDepth == 0 && _cmdFifoBulkSawWrite)
        {
            if (_experimentCommandFifoBulkGatePayloadRead &&
                IsCommandFifoReadInCurrentBulkPacketBody())
            {
                skipBulkEndDecode = true;
                bulkEndDecodeGateReason = "payload-read";
            }
            else if (_experimentCommandFifoBulkGateStaleRead &&
                     ShouldResyncCommandFifoStalePacketReadToBulkStart(out string staleReadReason))
            {
                skipBulkEndDecode = true;
                bulkEndDecodeGateReason = $"stale-read:{staleReadReason}";
            }
            else if (ShouldGateCommandFifoOutsideStaleBulkChain(out string outsideStaleChainReason))
            {
                skipBulkEndDecode = true;
                bulkEndDecodeGateReason = $"outside-stale-chain:{outsideStaleChainReason}";
            }
        }
        if (skipBulkEndDecode)
            TraceCommandFifoBulkDecodeGate(bulkEndDecodeGateReason, _cmdFifoReadIndex, ReadCommandFifoWordAt(_cmdFifoReadIndex));
        if (_cmdFifoBulkWriteDepth == 0)
            TraceCommandFifoProducerBoundary();
        if (_cmdFifoBulkWriteDepth == 0)
            TraceCommandFifoSourceChain();
        if (_cmdFifoBulkWriteDepth == 0)
            TraceCommandFifoBulkEnd();
        if (_cmdFifoBulkWriteDepth == 0 && !skipBulkEndDecode)
            DecodeCommandFifoPacketsIfNotPending("bulk-end");
        if (_cmdFifoBulkWriteDepth == 0)
            _cmdFifoBulkDecodeRemainingWords = 0;
    }

    public virtual void SetCommandFifoBulkWriteSource(
        ulong source,
        uint sourceBase,
        uint packetSourceAddress,
        uint packet,
        uint index,
        uint limit,
        uint word,
        uint payloadWords)
    {
        _cmdFifoBulkWriteSourceActive = true;
        _cmdFifoBulkWriteSource = new CommandFifoStorageBulkWriteSource(
            source,
            sourceBase,
            packetSourceAddress,
            packet,
            index,
            limit,
            word,
            payloadWords);
    }

    public virtual void ClearCommandFifoBulkWriteSource()
    {
        _cmdFifoBulkWriteSourceActive = false;
        _cmdFifoBulkWriteSource = default;
    }

    private bool ShouldResyncCommandFifoReadToBulkStart()
    {
        if (IsCommandFifoReadIndexInsideBulkWrite())
            return false;
        if (CommandFifoStorageIndex(_cmdFifoReadIndex) >= 0x40)
            return false;

        uint startWord = ReadCommandFifoWordAt(_cmdFifoBulkStartIndex);
        return startWord != 0 && GetFifoPacketWordsNeeded(startWord) > 1;
    }

    private bool ShouldResyncCommandFifoStalePacketReadToBulkStart(out string reason)
    {
        reason = "";
        if (IsCommandFifoReadIndexInsideBulkWrite())
            return false;

        uint startWord = ReadCommandFifoWordAt(_cmdFifoBulkStartIndex);
        if (!IsType5TexturePacketHeader(startWord))
            return false;

        uint readWord = ReadCommandFifoWordAt(_cmdFifoReadIndex);
        int wordsNeeded = GetFifoPacketWordsNeeded(readWord);
        if (IsKnownGauntletRuntimeMisalignedFifoWord(readWord, wordsNeeded))
            wordsNeeded = 1;
        if (wordsNeeded <= 0)
            wordsNeeded = 1;

        if (IsImplausibleCommandFifoPacket(readWord, wordsNeeded))
        {
            reason = "implausible";
            return true;
        }

        if (wordsNeeded > _cmdFifoBulkWriteWordCount + 64)
        {
            reason = "oversized";
            return true;
        }

        if (wordsNeeded <= 1024 && !HasCommandFifoWords(_cmdFifoReadIndex, wordsNeeded))
        {
            reason = "invalid-window";
            return true;
        }

        return false;
    }

    private bool ShouldGateCommandFifoStaleWriteRead(out string reason)
    {
        reason = "";
        return _experimentCommandFifoWriteGateStaleRead &&
               !_decodingCommandFifo &&
               ShouldResyncCommandFifoStalePacketReadToBulkStart(out reason);
    }

    private bool ShouldGateCommandFifoOutsideStaleBulkChain(out string reason)
    {
        reason = "";
        return _experimentCommandFifoBulkGateOutsideStaleChain &&
               IsCommandFifoOutsideStaleBulkChain(out reason);
    }

    private bool ShouldGateCommandFifoOutsideStaleWriteRead(out string reason)
    {
        reason = "";
        return _experimentCommandFifoWriteGateOutsideStaleChain &&
               !_decodingCommandFifo &&
               IsCommandFifoOutsideStaleBulkChain(out reason);
    }

    private bool ShouldResyncCommandFifoOutsideStaleWriteRead(out string reason)
    {
        reason = "";
        return _experimentCommandFifoWriteResyncOutsideStaleChain &&
               !_decodingCommandFifo &&
               IsType5TexturePacketHeader(ReadCommandFifoWordAt(_cmdFifoBulkStartIndex)) &&
               IsCommandFifoOutsideStaleBulkChain(out reason);
    }

    private bool IsCommandFifoOutsideStaleBulkChain(out string reason)
    {
        reason = "";
        if (!_cmdFifoBulkSawWrite ||
            _cmdFifoBulkWriteWordCount <= 0)
        {
            return false;
        }

        string bulkPosition = FormatCommandFifoBulkPacketPosition(_cmdFifoReadIndex).TrimStart();
        if (!bulkPosition.StartsWith("scan=outside", StringComparison.Ordinal))
            return false;

        int storageIndex = CommandFifoReadStorageIndex(_cmdFifoReadIndex);
        if (_cmdFifoStorageLastWriteSource[storageIndex] != CmdFifoStorageWriteSourceFifo ||
            (_cmdFifoStorageLastWritePc[storageIndex] & 0xffffffffUL) != 0x800fe5d4UL)
        {
            return false;
        }

        reason = bulkPosition;
        return true;
    }

    private bool ShouldResyncCommandFifoWrappedBulkTailToStart()
    {
        if (_cmdFifoBulkStartIndex <= _cmdFifoBulkLastIndex)
            return false;

        uint startWord = ReadCommandFifoWordAt(_cmdFifoBulkStartIndex);
        if (!IsType5TexturePacketHeader(startWord))
            return false;

        int readStorage = CommandFifoStorageIndex(_cmdFifoReadIndex);
        int lastStorage = CommandFifoStorageIndex(_cmdFifoBulkLastIndex);
        if (readStorage > lastStorage)
            return false;

        uint readWord = ReadCommandFifoWordAt(_cmdFifoReadIndex);
        return !IsType5TexturePacketHeader(readWord);
    }

    private bool TryFindCurrentBulkPacketBodyHead(int readIndex, out int packetHeadIndex, out int packetHeadBulkOffset)
    {
        packetHeadIndex = 0;
        packetHeadBulkOffset = 0;
        if (!_cmdFifoBulkSawWrite || _cmdFifoBulkWriteWordCount <= 0)
            return false;

        int storageWords = CommandFifoStorageWords();
        int startStorage = CommandFifoStorageIndex(_cmdFifoBulkStartIndex);
        int readStorage = CommandFifoStorageIndex(readIndex);
        int bulkWords = Math.Min(_cmdFifoBulkWriteWordCount, storageWords);
        int readBulkOffset = CommandFifoStorageDistance(startStorage, readStorage, storageWords);
        if (readBulkOffset >= bulkWords)
            return false;

        int cursor = _cmdFifoBulkStartIndex;
        int consumed = 0;
        int packetIndex = 0;
        while (consumed < bulkWords && packetIndex++ < 512)
        {
            int packetStorage = CommandFifoStorageIndex(cursor);
            uint command = ReadCommandFifoWordAt(cursor);
            int wordsNeeded = GetFifoPacketWordsNeeded(command);
            if (IsKnownGauntletRuntimeMisalignedFifoWord(command, wordsNeeded))
                wordsNeeded = 1;
            if (wordsNeeded <= 0)
                wordsNeeded = 1;

            int readPacketOffset = CommandFifoStorageDistance(packetStorage, readStorage, storageWords);
            if (readPacketOffset < wordsNeeded)
            {
                if (readPacketOffset == 0)
                    return false;
                packetHeadIndex = cursor;
                packetHeadBulkOffset = consumed;
                return true;
            }

            if (consumed + wordsNeeded > bulkWords)
                return false;

            consumed += wordsNeeded;
            cursor += wordsNeeded;
        }

        return false;
    }

    private bool TryFindCurrentBulkType5PayloadNextHead(
        int readIndex,
        out int nextPacketHeadIndex,
        out int nextPacketHeadBulkOffset,
        out int readPacketOffset,
        out int packetWords)
    {
        nextPacketHeadIndex = 0;
        nextPacketHeadBulkOffset = 0;
        readPacketOffset = 0;
        packetWords = 0;
        if (!_cmdFifoBulkSawWrite || _cmdFifoBulkWriteWordCount <= 0)
            return false;

        int storageWords = CommandFifoStorageWords();
        int startStorage = CommandFifoStorageIndex(_cmdFifoBulkStartIndex);
        int readStorage = CommandFifoStorageIndex(readIndex);
        int bulkWords = Math.Min(_cmdFifoBulkWriteWordCount, storageWords);
        int readBulkOffset = CommandFifoStorageDistance(startStorage, readStorage, storageWords);
        if (readBulkOffset >= bulkWords)
            return false;

        int cursor = _cmdFifoBulkStartIndex;
        int consumed = 0;
        int packetIndex = 0;
        while (consumed < bulkWords && packetIndex++ < 512)
        {
            int packetStorage = CommandFifoStorageIndex(cursor);
            uint command = ReadCommandFifoWordAt(cursor);
            int wordsNeeded = GetFifoPacketWordsNeeded(command);
            if (IsKnownGauntletRuntimeMisalignedFifoWord(command, wordsNeeded))
                wordsNeeded = 1;
            if (wordsNeeded <= 0)
                wordsNeeded = 1;

            int readOffsetInPacket = CommandFifoStorageDistance(packetStorage, readStorage, storageWords);
            if (readOffsetInPacket < wordsNeeded)
            {
                if (!IsType5TexturePacketHeader(command) || readOffsetInPacket < 2)
                    return false;

                int nextBulkOffset = consumed + wordsNeeded;
                if (nextBulkOffset >= bulkWords)
                    return false;

                nextPacketHeadIndex = cursor + wordsNeeded;
                nextPacketHeadBulkOffset = nextBulkOffset;
                readPacketOffset = readOffsetInPacket;
                packetWords = wordsNeeded;
                return true;
            }

            if (consumed + wordsNeeded > bulkWords)
                return false;

            consumed += wordsNeeded;
            cursor += wordsNeeded;
        }

        return false;
    }

    private bool IsCommandFifoReadInCurrentBulkPacketBody()
    {
        if (!_cmdFifoBulkSawWrite || _cmdFifoBulkWriteWordCount <= 0)
            return false;

        int storageWords = CommandFifoStorageWords();
        int startStorage = CommandFifoStorageIndex(_cmdFifoBulkStartIndex);
        int readStorage = CommandFifoStorageIndex(_cmdFifoReadIndex);
        int bulkWords = Math.Min(_cmdFifoBulkWriteWordCount, storageWords);
        int readBulkOffset = CommandFifoStorageDistance(startStorage, readStorage, storageWords);
        if (readBulkOffset >= bulkWords)
            return false;

        int cursor = _cmdFifoBulkStartIndex;
        int consumed = 0;
        int packetIndex = 0;
        while (consumed < bulkWords && packetIndex++ < 512)
        {
            int packetStorage = CommandFifoStorageIndex(cursor);
            uint command = ReadCommandFifoWordAt(cursor);
            int wordsNeeded = GetFifoPacketWordsNeeded(command);
            if (IsKnownGauntletRuntimeMisalignedFifoWord(command, wordsNeeded))
                wordsNeeded = 1;
            if (wordsNeeded <= 0)
                wordsNeeded = 1;

            int readPacketOffset = CommandFifoStorageDistance(packetStorage, readStorage, storageWords);
            if (readPacketOffset < wordsNeeded)
                return readPacketOffset > 0;

            if (consumed + wordsNeeded > bulkWords)
                return false;

            consumed += wordsNeeded;
            cursor += wordsNeeded;
        }

        return false;
    }

    private void TraceCommandFifoBulkResync(string kind, string reason, int oldReadIndex, uint oldReadWord)
    {
        if (!_traceCommandFifoBulkEnd ||
            _commandFifoBulkResyncTraceCount >= _traceCommandFifoBulkEndLimit)
        {
            return;
        }

        _commandFifoBulkResyncTraceCount++;
        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        int oldReadStorage = CommandFifoStorageIndex(oldReadIndex);
        int newReadStorage = CommandFifoStorageIndex(_cmdFifoReadIndex);
        int startStorage = CommandFifoStorageIndex(_cmdFifoBulkStartIndex);
        int lastStorage = CommandFifoStorageIndex(_cmdFifoBulkLastIndex);
        uint startWord = ReadCommandFifoWordAt(_cmdFifoBulkStartIndex);
        uint lastWord = ReadCommandFifoWordAt(_cmdFifoBulkLastIndex);
        string packetStatus = FormatCommandFifoBulkPacketPosition(oldReadIndex);
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-CMDFIFO-BULK-RESYNC] n={_commandFifoBulkResyncTraceCount} kind={kind} reason={reason} " +
            $"oldRd=0x{oldReadIndex * 4:x8}/0x{oldReadStorage * 4:x5} newRd=0x{_cmdFifoReadIndex * 4:x8}/0x{newReadStorage * 4:x5} " +
            $"bulk=0x{_cmdFifoBulkStartIndex * 4:x8}-0x{_cmdFifoBulkLastIndex * 4:x8} storage=0x{startStorage * 4:x5}-0x{lastStorage * 4:x5} " +
            $"words={_cmdFifoBulkWriteWordCount} depth={_cmdFifoDepth} holes={_cmdFifoHoles} valid={_cmdFifoValidCount} " +
            $"oldWord=0x{oldReadWord:x8} start=0x{startWord:x8} last=0x{lastWord:x8}{packetStatus}{pcStatus}");
    }

