        }

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if (_traceCommandFifoProducerBoundaryPcs.Length != 0 && !_traceCommandFifoProducerBoundaryPcs.Contains(pc))
            return;

        int read = _cmdFifoReadIndex;
        int readStorage = CommandFifoStorageIndex(read);
        int beginReadStorage = CommandFifoStorageIndex(_cmdFifoBulkBeginReadIndex);
        int startStorage = CommandFifoStorageIndex(_cmdFifoBulkStartIndex);
        int lastStorage = CommandFifoStorageIndex(_cmdFifoBulkLastIndex);
        if (!ShouldTraceCommandFifoStorageOffsets(_traceCommandFifoProducerBoundaryStorageOffsets, readStorage, startStorage, lastStorage))
            return;

        _commandFifoProducerBoundaryTraceCount++;
        uint beginReadWord = ReadCommandFifoWordAt(_cmdFifoBulkBeginReadIndex);
        uint readWord = ReadCommandFifoWordAt(read);
        uint startWord = ReadCommandFifoWordAt(_cmdFifoBulkStartIndex);
        uint lastWord = ReadCommandFifoWordAt(_cmdFifoBulkLastIndex);
        bool readInsideBulk = IsCommandFifoReadIndexInsideBulkWrite();
        string packetStatus = FormatCommandFifoBulkPacketPosition(read).TrimStart();
        string packetHeads = FormatCommandFifoBulkPacketHeads(_traceCommandFifoSourceChainPacketLimit);
        string focus = FormatCommandFifoStorageFocus(_traceCommandFifoProducerBoundaryStorageOffsets);
        string words = FormatCommandFifoProducerBoundaryWords(_traceCommandFifoProducerBoundaryWordLimit);
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-CMDFIFO-PRODUCER] n={_commandFifoProducerBoundaryTraceCount} " +
            $"beginRd=0x{_cmdFifoBulkBeginReadIndex * 4:x8}/0x{beginReadStorage * 4:x5} beginWord=0x{beginReadWord:x8} " +
            $"rd=0x{read * 4:x8}/0x{readStorage * 4:x5} word=0x{readWord:x8} " +
            $"bulk=0x{_cmdFifoBulkStartIndex * 4:x8}-0x{_cmdFifoBulkLastIndex * 4:x8} storage=0x{startStorage * 4:x5}-0x{lastStorage * 4:x5} " +
            $"bulkWords={_cmdFifoBulkWriteWordCount} inside={(readInsideBulk ? 1 : 0)} " +
            $"beginDepth={_cmdFifoBulkBeginDepth} beginHoles={_cmdFifoBulkBeginHoles} beginValid={_cmdFifoBulkBeginValidCount} " +
            $"beginAmin=0x{_cmdFifoBulkBeginAddressMin:x8} beginAmax=0x{_cmdFifoBulkBeginAddressMax:x8} " +
            $"endDepth={_cmdFifoDepth} endHoles={_cmdFifoHoles} endValid={_cmdFifoValidCount} " +
            $"endAmin=0x{_cmdFifoAddressMin:x8} endAmax=0x{_cmdFifoAddressMax:x8} " +
            $"start=0x{startWord:x8} last=0x{lastWord:x8} position={packetStatus} heads={packetHeads} first={words} focus={focus}{pcStatus}");
    }

    private string FormatCommandFifoProducerBoundaryWords(int maxWords)
    {
        int count = Math.Min(Math.Min(maxWords, _cmdFifoBulkProducerWordTraceCount), _cmdFifoBulkProducerWordValues.Length);
        if (count <= 0)
            return "none";

        StringBuilder builder = new(count * 80);
        for (int i = 0; i < count; i++)
        {
            if (i > 0)
                builder.Append('|');

            uint value = _cmdFifoBulkProducerWordValues[i];
            builder
                .Append('w').Append(i.ToString(CultureInfo.InvariantCulture))
                .Append("@0x").Append((_cmdFifoBulkProducerWordStorageIndexes[i] * 4).ToString("x5", CultureInfo.InvariantCulture))
                .Append("/lg0x").Append((_cmdFifoBulkProducerWordLogicalIndexes[i] * 4).ToString("x8", CultureInfo.InvariantCulture))
                .Append("/addr0x").Append(_cmdFifoBulkProducerWordAddresses[i].ToString("x8", CultureInfo.InvariantCulture))
                .Append(":0x").Append(value.ToString("x8", CultureInfo.InvariantCulture))
                .Append(":t").Append((value & 7u).ToString(CultureInfo.InvariantCulture))
                .Append(":v").Append(_cmdFifoBulkProducerWordValidBefore[i] ? '1' : '0');
        }

        return builder.ToString();
    }

    private void TraceCommandFifoSourceChain()
    {
        if (!_traceCommandFifoSourceChain ||
            !_cmdFifoBulkSawWrite ||
            _commandFifoSourceChainTraceCount >= _traceCommandFifoSourceChainLimit)
        {
            return;
        }

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if (_traceCommandFifoSourceChainPcs.Length != 0 && !_traceCommandFifoSourceChainPcs.Contains(pc))
            return;

        int read = _cmdFifoReadIndex;
        int readStorage = CommandFifoStorageIndex(read);
        int startStorage = CommandFifoStorageIndex(_cmdFifoBulkStartIndex);
        int lastStorage = CommandFifoStorageIndex(_cmdFifoBulkLastIndex);
        if (!ShouldTraceCommandFifoSourceChainStorage(readStorage, startStorage, lastStorage))
            return;

        _commandFifoSourceChainTraceCount++;
        uint readWord = ReadCommandFifoWordAt(read);
        uint startWord = ReadCommandFifoWordAt(_cmdFifoBulkStartIndex);
        uint lastWord = ReadCommandFifoWordAt(_cmdFifoBulkLastIndex);
        int wordsNeeded = GetCommandFifoTraceWordsNeeded(readWord);
        int validWindowWords = CountCommandFifoValidWindowWords(read, Math.Min(wordsNeeded, 64));
        bool readInsideBulk = IsCommandFifoReadIndexInsideBulkWrite();
        bool readValid = IsCommandFifoWordValidForRead(read);
        string packetStatus = FormatCommandFifoBulkPacketPosition(read).TrimStart();
        string packetHeads = FormatCommandFifoBulkPacketHeads(_traceCommandFifoSourceChainPacketLimit);
        string focus = FormatCommandFifoSourceChainFocus();
        string window = FormatCommandFifoSourceChainWindow(read, before: 2, after: 4);
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-CMDFIFO-SOURCE] n={_commandFifoSourceChainTraceCount} " +
            $"rd=0x{read * 4:x8}/0x{readStorage * 4:x5} word=0x{readWord:x8} type={readWord & 7u} words={wordsNeeded} " +
            $"readValid={(readValid ? 1 : 0)} validWindow={validWindowWords}/{Math.Min(wordsNeeded, 64)} " +
            $"bulk=0x{_cmdFifoBulkStartIndex * 4:x8}-0x{_cmdFifoBulkLastIndex * 4:x8} storage=0x{startStorage * 4:x5}-0x{lastStorage * 4:x5} " +
            $"bulkWords={_cmdFifoBulkWriteWordCount} inside={(readInsideBulk ? 1 : 0)} depth={_cmdFifoDepth} holes={_cmdFifoHoles} valid={_cmdFifoValidCount} " +
            $"start=0x{startWord:x8} last=0x{lastWord:x8} amin=0x{_cmdFifoAddressMin:x8} amax=0x{_cmdFifoAddressMax:x8} " +
            $"lastDecoded=0x{_lastDecodedCommandFifoCommand:x8}:{_lastDecodedCommandFifoWords}:0x{_lastDecodedCommandFifoPacketStart * 4:x8}->0x{_lastDecodedCommandFifoReadAfter * 4:x8} " +
            $"position={packetStatus} heads={packetHeads} focus={focus} window={window}{pcStatus}");
    }

    private bool ShouldTraceCommandFifoSourceChainStorage(int readStorage, int startStorage, int lastStorage)
        => ShouldTraceCommandFifoStorageOffsets(_traceCommandFifoSourceChainStorageOffsets, readStorage, startStorage, lastStorage);

    private bool ShouldTraceCommandFifoStorageOffsets(ulong[] offsets, int readStorage, int startStorage, int lastStorage)
    {
        if (offsets.Length == 0)
            return true;

        int storageWords = CommandFifoStorageWords();
        int bulkWords = Math.Min(_cmdFifoBulkWriteWordCount, storageWords);
        for (int i = 0; i < offsets.Length; i++)
        {
            int storage = CommandFifoStorageIndex(unchecked((int)(offsets[i] >> 2)));
            if (readStorage == storage || startStorage == storage || lastStorage == storage)
                return true;
            if (IsCommandFifoStorageInsideBulkWindow(storage, startStorage, bulkWords, storageWords))
                return true;
        }

        return false;
    }

    private static bool IsCommandFifoStorageInsideBulkWindow(int storage, int startStorage, int bulkWords, int storageWords)
    {
        if (bulkWords <= 0)
            return false;
        return CommandFifoStorageDistance(startStorage, storage, storageWords) < bulkWords;
    }

    private string FormatCommandFifoBulkPacketHeads(int maxPackets)
    {
        if (!_cmdFifoBulkSawWrite || _cmdFifoBulkWriteWordCount <= 0 || maxPackets <= 0)
            return "none";

        int storageWords = CommandFifoStorageWords();
        int bulkWords = Math.Min(_cmdFifoBulkWriteWordCount, storageWords);
        int cursor = _cmdFifoBulkStartIndex;
        int consumed = 0;
        int packetIndex = 0;
        StringBuilder builder = new(maxPackets * 72);
        while (consumed < bulkWords && packetIndex < maxPackets)
        {
            int packetStorage = CommandFifoStorageIndex(cursor);
            uint command = ReadCommandFifoWordAt(cursor);
            int wordsNeeded = GetCommandFifoTraceWordsNeeded(command);
            int validWindowWords = CountCommandFifoValidWindowWords(cursor, Math.Min(wordsNeeded, 8));
            if (packetIndex > 0)
                builder.Append('|');
            builder
                .Append('p').Append(packetIndex.ToString(CultureInfo.InvariantCulture))
                .Append("@0x").Append((cursor * 4).ToString("x8", CultureInfo.InvariantCulture))
                .Append("/0x").Append((packetStorage * 4).ToString("x5", CultureInfo.InvariantCulture))
                .Append(":cmd=0x").Append(command.ToString("x8", CultureInfo.InvariantCulture))
                .Append(":t=").Append((command & 7u).ToString(CultureInfo.InvariantCulture))
                .Append(":w=").Append(wordsNeeded.ToString(CultureInfo.InvariantCulture))
                .Append(":v=").Append(validWindowWords.ToString(CultureInfo.InvariantCulture))
                .Append('/').Append(Math.Min(wordsNeeded, 8).ToString(CultureInfo.InvariantCulture));

            if (consumed + wordsNeeded > bulkWords)
            {
                builder.Append(":partial");
                break;
            }

            consumed += wordsNeeded;
            cursor += wordsNeeded;
            packetIndex++;
        }

        if (consumed < bulkWords)
        {
            if (builder.Length > 0)
                builder.Append('|');
            builder
                .Append("...rel=")
                .Append(consumed.ToString(CultureInfo.InvariantCulture))
                .Append('/')
                .Append(bulkWords.ToString(CultureInfo.InvariantCulture));
        }

        return builder.Length == 0 ? "none" : builder.ToString();
    }

    private string FormatCommandFifoSourceChainFocus()
    {
        return FormatCommandFifoStorageFocus(_traceCommandFifoSourceChainStorageOffsets);
    }

    private string FormatCommandFifoStorageFocus(ulong[] traceOffsets)
    {
        ulong[] offsets = traceOffsets.Length != 0
            ? traceOffsets
            : DefaultCommandFifoSourceChainStorageOffsets;
        StringBuilder builder = new(offsets.Length * 96);
        for (int i = 0; i < offsets.Length; i++)
        {
            int storage = CommandFifoStorageIndex(unchecked((int)(offsets[i] >> 2)));
            if (i > 0)
                builder.Append('|');
            builder
                .Append("0x")
                .Append((storage * 4).ToString("x5", CultureInfo.InvariantCulture))
                .Append('=')
                .Append(FormatCommandFifoStorageIndexDebug(storage));
        }

        return builder.Length == 0 ? "none" : builder.ToString();
    }

    private string FormatCommandFifoSourceChainWindow(int readIndex, int before, int after)
    {
        StringBuilder builder = new((before + after + 1) * 104);
        for (int delta = -before; delta <= after; delta++)
        {
            if (builder.Length > 0)
                builder.Append('|');
            if (delta == 0)
                builder.Append('*');
            builder.Append(delta >= 0 ? "+" : "");
            builder
                .Append(delta.ToString(CultureInfo.InvariantCulture))
                .Append('=')
                .Append(FormatCommandFifoStorageWordDebug(readIndex + delta));
        }

        return builder.ToString();
    }

    private int GetCommandFifoTraceWordsNeeded(uint command)
    {
        int wordsNeeded = GetFifoPacketWordsNeeded(command);
        if (IsKnownGauntletRuntimeMisalignedFifoWord(command, wordsNeeded))
            wordsNeeded = 1;
        if (wordsNeeded <= 0)
            wordsNeeded = 1;
        return wordsNeeded;
    }

    private string FormatCommandFifoBulkPacketPosition(int readIndex)
    {
        if (!_cmdFifoBulkSawWrite || _cmdFifoBulkWriteWordCount <= 0)
            return "";

        int storageWords = CommandFifoStorageWords();
        int startStorage = CommandFifoStorageIndex(_cmdFifoBulkStartIndex);
        int readStorage = CommandFifoStorageIndex(readIndex);
        int bulkWords = Math.Min(_cmdFifoBulkWriteWordCount, storageWords);
        int readBulkOffset = CommandFifoStorageDistance(startStorage, readStorage, storageWords);
        if (readBulkOffset >= bulkWords)
            return $" scan=outside:rel{readBulkOffset}/{bulkWords}";

        int cursor = _cmdFifoBulkStartIndex;
        int consumed = 0;
        int packetIndex = 0;
        while (consumed < bulkWords && packetIndex < 512)
        {
            int packetStorage = CommandFifoStorageIndex(cursor);
            uint command = ReadCommandFifoWordAt(cursor);
            int wordsNeeded = GetFifoPacketWordsNeeded(command);
            if (IsKnownGauntletRuntimeMisalignedFifoWord(command, wordsNeeded))
                wordsNeeded = 1;
            if (wordsNeeded <= 0)
                wordsNeeded = 1;

            int readPacketOffset = CommandFifoStorageDistance(packetStorage, readStorage, storageWords);
            if (readPacketOffset < wordsNeeded)
            {
                string relation = readPacketOffset == 0
                    ? "head"
                    : (command & 7u) == 5u && readPacketOffset >= 2
                        ? "type5-data"
                        : "body";
                string partial = consumed + wordsNeeded > bulkWords ? ":partial" : "";
                return
                    $" scan={relation}{partial}:rel{readBulkOffset}/{bulkWords}:pkt{packetIndex}:off{readPacketOffset}/{wordsNeeded}:" +
                    $"cmd=0x{command:x8}:type={command & 7u}";
            }

            if (consumed + wordsNeeded > bulkWords)
            {
                return
                    $" scan=after-partial:rel{readBulkOffset}/{bulkWords}:pkt{packetIndex}:off{readPacketOffset}/{wordsNeeded}:" +
                    $"cmd=0x{command:x8}:type={command & 7u}";
            }

            consumed += wordsNeeded;
            cursor += wordsNeeded;
            packetIndex++;
        }

        return $" scan=after:rel{readBulkOffset}/{bulkWords}:scanned{consumed}:pkts{packetIndex}";
    }

    private static int CommandFifoStorageDistance(int fromStorage, int toStorage, int storageWords)
    {
        int distance = toStorage - fromStorage;
        if (distance < 0)
            distance += storageWords;
        return distance;
    }

    private bool IsCommandFifoReadIndexInsideBulkWrite()
        => IsCommandFifoIndexInsideBulkWrite(_cmdFifoReadIndex);

    private bool IsCommandFifoIndexInsideBulkWrite(int readIndex)
    {
        if (!_cmdFifoBulkSawWrite)
            return false;
        if (UseMameCommandFifoBulkLogicalWindow())
            return readIndex >= _cmdFifoBulkStartIndex && readIndex <= _cmdFifoBulkLastIndex;
        if (_cmdFifoBulkStartIndex <= _cmdFifoBulkLastIndex)
            return readIndex >= _cmdFifoBulkStartIndex && readIndex <= _cmdFifoBulkLastIndex;
        return readIndex >= _cmdFifoBulkStartIndex || readIndex <= _cmdFifoBulkLastIndex;
    }

    private bool UseMameCommandFifoBulkLogicalWindow()
        => _fixMameCommandFifoModel && _experimentMameCommandFifoBulkLogicalWindow;

    private static bool IsType5TexturePacketHeader(uint command)
        => (command & 7u) == 5u && (command >> 30) == 3u && ((command >> 3) & 0x7ffffu) > 0;

    public uint ReadStatus(bool vblank)
    {
        _statusReadCount++;
        CountStatusPc();
        if (IsCommandFifoOperationPending())
        {
            _commandFifoOperationPending = false;
            DecodeCommandFifoPacketsIfNotPending("status");
        }
        if (!_fixMameVblankSwapTiming && vblank && _pendingSwapCount > 0)
        {
            ExecuteSwapBuffers(DequeuePendingSwapCommand());
            RecordVoodooEvent($"status swap-drain vblank={(vblank ? 1 : 0)} pend={_pendingSwapCount}");
        }

        uint status = 0x0ffff03fu | ((uint)(_frontBufferIndex & 3) << 10);
        if (vblank)
            status |= 0x40u;
        status |= (uint)Math.Clamp(_pendingSwapCount, 0, 7) << 28;
        if (_recordVoodooEvents && (_statusReadCount <= 16 || _pendingSwapCount > 0 || (_statusReadCount & 0x3ff) == 0))
            RecordVoodooEvent($"status read value=0x{status:x8} vblank={(vblank ? 1 : 0)} pend={_pendingSwapCount}");
        return status;
    }

    public void OnVblankStart()
    {
        if (!_fixMameVblankSwapTiming || _pendingSwapCount <= 0)
            return;

        ExecuteSwapBuffers(DequeuePendingSwapCommand());
        RecordVoodooEvent($"vblank swap-drain pend={_pendingSwapCount}");
    }

    private uint DequeuePendingSwapCommand()
    {
        if (_pendingSwapCount <= 0)
            return 0;

        uint command = _pendingSwapCommands[0];
        _pendingSwapCount--;
        if (_pendingSwapCount > 0)
            Array.Copy(_pendingSwapCommands, 1, _pendingSwapCommands, 0, _pendingSwapCount);
        _pendingSwapCommands[_pendingSwapCount] = 0;
        return command;
    }

    public virtual uint ReadLfb32(uint offset)
    {
        uint lfbMode = _registers[RegLfbMode];
        int pixel = GetLfbPixelOffset(offset, IsTwoPixelLfbFormat((int)(lfbMode & 0x0fu)), lfbMode);
        ushort[] buffer = GetLfbReadBuffer(lfbMode);
        ushort low = buffer[pixel & (LfbPixels - 1)];
        ushort high = buffer[(pixel + 1) & (LfbPixels - 1)];
        uint value = (uint)(low | (high << 16));
        if (((lfbMode >> 15) & 1u) != 0)
            value = (value << 16) | (value >> 16);
        if (((lfbMode >> 16) & 1u) != 0)
            value = BinaryPrimitives.ReverseEndianness(value);
        return value;
    }

    public virtual void WriteLfb32(uint offset, uint value)
    {
        MirrorLfbWriteToCommandFifoStorage(offset, value);
        uint lfbMode = _registers[RegLfbMode];
        if (lfbMode == 0x00002011u)
        {
            WriteLfb32Mode2011(offset, value);
            return;
        }

        if (((lfbMode >> 12) & 1u) != 0)
            value = BinaryPrimitives.ReverseEndianness(value);
        if (((lfbMode >> 11) & 1u) != 0)
            value = (value << 16) | (value >> 16);

        int format = (int)(lfbMode & 0x0fu);
        int rgbaLanes = (int)((lfbMode >> 9) & 0x03u);
        bool twoPixels = IsTwoPixelLfbFormat(format);
        int pixel = GetLfbPixelOffset(offset, twoPixels, lfbMode);
        WriteLfbDepth(value, format, pixel);
        if (format == 15)
        {
            _lfbWriteCount++;
            return;
        }

        int bufferIndex = GetLfbWriteBufferIndex(lfbMode);
        InvalidateFastFillCache(bufferIndex);
        ushort[] buffer = _colorBuffers[bufferIndex];

        bool wroteFirst = false;
        bool wroteSecond = false;
        ushort first = 0;
        ushort second = 0;
        if (TryExpandLfbPixel(value, format, rgbaLanes, highHalf: false, out first))
        {
            buffer[pixel & (LfbPixels - 1)] = first;
            TrackPixelLastWriterByPixel(bufferIndex, pixel, GetPixelLastWriterId("lfb", "normal", first));
            wroteFirst = true;
        }
        if (twoPixels && TryExpandLfbPixel(value, format, rgbaLanes, highHalf: true, out second))
        {
            buffer[(pixel + 1) & (LfbPixels - 1)] = second;
            TrackPixelLastWriterByPixel(bufferIndex, pixel + 1, GetPixelLastWriterId("lfb", "normal", second));
            wroteSecond = true;
        }
        TraceLfbWriteDetail("normal", offset, value, lfbMode, format, rgbaLanes, bufferIndex, pixel, wroteFirst, first, wroteSecond, second);
        _lfbWriteCount++;
    }

    private void WriteLfb32Mode2011(uint offset, uint value)
    {
        uint pixelOffset = ((offset & (LfbBytes - 1u)) >> 2) << 1;
        int x = (int)(pixelOffset & (LfbRowPixels - 1));
        int sourceY = (int)((pixelOffset >> 10) & 0x3ff);
        int origin = (int)((_registers[RegFbiInit3] >> 22) & 0x3ff);
        int y = (origin > 0 ? Math.Min(origin, LfbRows - 1) : 479) - sourceY;
        if ((uint)y >= LfbRows)
            y = y < 0 ? 0 : LfbRows - 1;

        int bufferIndex = _backBufferIndex;
        _lastFastFillValid[bufferIndex] = false;
        ushort[] buffer = _colorBuffers[bufferIndex];
        int pixel = y * LfbRowPixels + x;
        ushort first = ConvertXrgb1555Lane0((ushort)value);
        ushort second = ConvertXrgb1555Lane0((ushort)(value >> 16));
        buffer[pixel & (LfbPixels - 1)] = first;
        buffer[(pixel + 1) & (LfbPixels - 1)] = second;
        TrackPixelLastWriterByPixel(bufferIndex, pixel, GetPixelLastWriterId("lfb", "mode2011", first));
        TrackPixelLastWriterByPixel(bufferIndex, pixel + 1, GetPixelLastWriterId("lfb", "mode2011", second));
        TraceLfbWriteDetail("mode2011", offset, value, _registers[RegLfbMode], 0x11, 0, bufferIndex, pixel, firstValid: true, first, secondValid: true, second);
        _lfbWriteCount++;
    }

    private void TraceLfbWriteDetail(
        string path,
        uint offset,
        uint value,
        uint lfbMode,
        int format,
        int rgbaLanes,
        int bufferIndex,
        int pixel,
        bool firstValid,
        ushort first,
        bool secondValid,
        ushort second)
    {
        if (!_traceLfbDetail || _lfbDetailTraceCount++ >= _traceLfbDetailLimit)
            return;

        int normalizedPixel = pixel & (LfbPixels - 1);
        int x = normalizedPixel & (LfbRowPixels - 1);
        int y = normalizedPixel / LfbRowPixels;
        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-LFB-DETAIL] n={_lfbDetailTraceCount} path={path} off=0x{offset:x6} value=0x{value:x8} " +
            $"mode=0x{lfbMode:x8} fmt={format} rgba={rgbaLanes} buf={bufferIndex} pix={normalizedPixel} xy={x},{y} " +
            $"rgb={(firstValid ? $"0x{first:x4}" : "-")}/{(secondValid ? $"0x{second:x4}" : "-")} " +
            $"front={_frontBufferIndex} back={_backBufferIndex} fbz=0x{_registers[RegFbzMode]:x8}{pcStatus}");
    }

    private void MirrorLfbWriteToCommandFifoStorage(uint offset, uint value)
    {
        if (!_fixMameCommandFifoModel ||
            !_experimentMameCommandFifoFramebufferStorage ||
            !_experimentMameCommandFifoMirrorLfbWrites)
        {
            return;
        }

        int logicalIndex = (int)(offset >> 2);
        int storageIndex = CommandFifoStorageIndex(logicalIndex);
        _cmdFifoRam[storageIndex] = value;
        RecordCommandFifoStorageLastWrite(
            storageIndex,
            logicalIndex,
            logicalIndex * 4,
            value,
            CmdFifoStorageWriteSourceLfbMirror);
    }

    public virtual void WriteTexture32(uint offset, uint value)
        => WriteTexturePort32((offset >> 2) & (TextureWords - 1), value);

    private void WriteTexturePort32(uint wordOffset, uint value)
    {
        uint lod = (wordOffset >> 15) & 0x0fu;
        if (lod > 8)
            return;

        int lodIndex = (int)lod;
        if (_debugTextureUploadLods)
        {
            _textureUploadLodWriteCounts[lodIndex]++;
            if (_currentType5TextureWriteActive)
                _textureUploadLodType5WriteCounts[lodIndex]++;
            if (value != 0)
                _textureUploadLodNonZeroWriteCounts[lodIndex]++;
        }

        int tmu = (int)((wordOffset >> 19) & 0x03u);
        uint mode = ReadTextureUploadRegister(tmu, RegTextureMode);
        uint texLod = ReadTextureUploadRegister(tmu, RegTextureLod);
        uint textureBase = ReadTextureUploadRegister(tmu, RegTextureBaseAddr);
        if (((texLod >> 25) & 1u) != 0)
            value = BinaryPrimitives.ReverseEndianness(value);
        if (((texLod >> 26) & 1u) != 0)
            value = (value >> 16) | (value << 16);

        uint seqMode = _experimentTextureUploadTmuBanks
            ? ReadTextureRegisterForTmu(0, RegTextureMode)
            : mode;
        int bytesPerTexel = GetTextureFormatBytesPerTexel((int)((mode >> 8) & 0x0fu));
        bool seq8Downld = ((seqMode >> 31) & 1u) != 0 || (_fixSequential8BitTextureDownload && bytesPerTexel == 1);
        BeginTextureWriteContext(value, mode, texLod, textureBase, lod, bytesPerTexel, seq8Downld);
        try
        {
            if (_fixLinearTextureDownloadAddressing)
            {
                TrackTextureUploadLodPhysicalSpan(lodIndex, MapTextureBankByteAddress(tmu, wordOffset << 2));
                WriteTextureLinear32(wordOffset, value, bytesPerTexel, tmu);
                _textureWriteCount++;
                return;
            }

            uint tt = (wordOffset >> 7) & 0xffu;
            uint ts = (wordOffset << ((seq8Downld && bytesPerTexel == 1) ? 2 : 1)) & 0xffu;
            uint width = GetTextureWidth(texLod);
            uint height = GetTextureHeight(texLod);
            uint xMask = Math.Max(1u, width >> (int)lod) - 1u;
            uint yMask = Math.Max(1u, height >> (int)lod) - 1u;
            uint texel = (tt & yMask) * (xMask + 1u) + (ts & xMask);
            uint byteOffset = (GetTextureLodOffset((int)lod, bytesPerTexel, texLod, textureBase) + texel * (uint)bytesPerTexel) & (TextureBytes - 1u);
            if (_fixTextureDownloadAlign32)
                byteOffset &= ~3u;
            bool traceMameWritePtr = ShouldTraceTextureUploadMameWritePtr(wordOffset);
            bool applyMameWritePtr = ShouldApplyTextureUploadMameWritePtr(wordOffset);
            if (traceMameWritePtr || applyMameWritePtr)
            {
                uint mameByteOffset = GetMameTextureWritePtrByteOffset(
                    (int)lod,
                    bytesPerTexel,
                    texLod,
                    textureBase,
                    ReadTextureUploadRegister(tmu, RegTextureBaseAddr1),
                    ReadTextureUploadRegister(tmu, RegTextureBaseAddr2),
                    ReadTextureUploadRegister(tmu, RegTextureBaseAddr38),
                    ts,
                    tt);
                if (traceMameWritePtr)
                    TraceTextureUploadMameWritePtr(wordOffset, byteOffset, mameByteOffset, mode, texLod, textureBase, lod, ts, tt, bytesPerTexel, seq8Downld);
                if (applyMameWritePtr)
                    byteOffset = mameByteOffset;
            }
            if (TryGetType5Seq8PacketBlockLayoutByteOffset(
                byteOffset,
                mode,
                texLod,
                textureBase,
                lod,
                bytesPerTexel,
                seq8Downld,
                out uint packetBlockByteOffset))
            {
                byteOffset = packetBlockByteOffset;
            }
            byteOffset = MapTextureBankByteAddress(tmu, byteOffset);
            TrackTextureUploadLodPhysicalSpan(lodIndex, byteOffset);
            if (_currentType5TextureWriteActive)
            {
                int physicalWord = (int)((byteOffset & (TextureBytes - 1u)) >> 2);
                if (_currentType5TextureWritePhysicalMinWord < 0 || physicalWord < _currentType5TextureWritePhysicalMinWord)
                    _currentType5TextureWritePhysicalMinWord = physicalWord;
                if (physicalWord > _currentType5TextureWritePhysicalMaxWord)
                    _currentType5TextureWritePhysicalMaxWord = physicalWord;
            }
            TraceTextureWriteBucket(wordOffset, byteOffset, value, mode, texLod, textureBase, lod, ts, tt, bytesPerTexel, seq8Downld);

            if (bytesPerTexel == 1)
            {
                bool previousSuppressZero = _suppressZeroTextureBytesForCurrentWrite;
                _suppressZeroTextureBytesForCurrentWrite = _fixSparse8BitTextureUpload;
                try
                {
                    WriteTextureByte(byteOffset + 0u, (byte)value);
                    WriteTextureByte(byteOffset + 1u, (byte)(value >> 8));
                    WriteTextureByte(byteOffset + 2u, (byte)(value >> 16));
                    WriteTextureByte(byteOffset + 3u, (byte)(value >> 24));
                }
                finally
                {
                    _suppressZeroTextureBytesForCurrentWrite = previousSuppressZero;
                }
            }
            else
            {
                WriteTextureUInt16(byteOffset + 0u, (ushort)value);
                WriteTextureUInt16(byteOffset + 2u, (ushort)(value >> 16));
            }

            _textureWriteCount++;
        }
        finally
        {
            EndTextureWriteContext();
        }
    }

    private void TrackTextureUploadLodPhysicalSpan(int lod, uint byteOffset)
    {
        if (!_debugTextureUploadLods)
            return;

        uint physicalAddress = byteOffset & (TextureBytes - 1u);
        if (physicalAddress < _textureUploadLodPhysicalMin[lod])
            _textureUploadLodPhysicalMin[lod] = physicalAddress;
        if (physicalAddress > _textureUploadLodPhysicalMax[lod])
            _textureUploadLodPhysicalMax[lod] = physicalAddress;
    }

    private void BeginTextureWriteContext(
        uint value,
        uint mode,
        uint texLod,
        uint textureBase,
        uint lod,
        int bytesPerTexel,
        bool seq8Downld)
    {
        if (!_traceTexturedTriangleSampleWriters &&
            !_traceTextureSampleWriters &&
            !_traceTexturedTriangleSampleSummaryRequireWriter &&
            !_experimentFullrectSampleWriterLayout &&
            !_debugTextureRangeMin.HasValue &&
            !_traceTextureOverwriteRangeMin.HasValue)
        {
            return;
        }

        _currentTextureWriteActive = true;
        _currentTextureWriteValue = value;
        _currentTextureWriteMode = mode;
        _currentTextureWriteTexLod = texLod;
        _currentTextureWriteBase = textureBase;
        _currentTextureWriteLod = lod;
        _currentTextureWriteBytesPerTexel = bytesPerTexel;
        _currentTextureWriteSeq8 = seq8Downld;
    }

    private void EndTextureWriteContext()
    {
        if (!_traceTexturedTriangleSampleWriters &&
            !_traceTextureSampleWriters &&
            !_traceTexturedTriangleSampleSummaryRequireWriter &&
            !_experimentFullrectSampleWriterLayout &&
            !_debugTextureRangeMin.HasValue &&
            !_traceTextureOverwriteRangeMin.HasValue)
        {
            return;
        }

        _currentTextureWriteActive = false;
    }

    private void TraceTextureWriteBucket(
        uint wordOffset,
        uint byteOffset,
        uint value,
        uint mode,
        uint texLod,
        uint textureBase,
        uint lod,
        uint ts,
        uint tt,
        int bytesPerTexel,
        bool seq8Downld)
    {
        if (_traceTextureWriteBuckets.Length == 0 || _textureWriteBucketTraceCount >= _traceTextureWriteBucketsLimit)
            return;

        uint bucket = (byteOffset & (TextureBytes - 1u)) >> TextureZeroSampleBucketShift;
        if (!_traceTextureWriteBuckets.Contains(bucket))
            return;
        int bucketIndex = (int)bucket;
        if (_traceTextureWriteBucketsPerBucketLimit > 0 &&
            _textureWriteBucketTraceCounts[bucketIndex] >= _traceTextureWriteBucketsPerBucketLimit)
            return;
        int bucketTraceCount = ++_textureWriteBucketTraceCounts[bucketIndex];

        int nonZeroBytes = 0;
        if ((byte)value != 0)
            nonZeroBytes++;
        if ((byte)(value >> 8) != 0)
            nonZeroBytes++;
        if ((byte)(value >> 16) != 0)
            nonZeroBytes++;
        if ((byte)(value >> 24) != 0)
            nonZeroBytes++;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        string type5Status = _currentType5TextureWriteActive
            ? $" type5=cmd=0x{_currentType5TextureWriteCommand:X8}:space={_currentType5TextureWriteSpace}:targetStart=0x{_currentType5TextureWriteTargetStart:X6}:target=0x{_currentType5TextureWriteTargetWord:X6}:i={_currentType5TextureWriteIndex}/{_currentType5TextureWriteCount}:packet=0x{_currentCommandFifoPacketStart * 4:X8}:rd=0x{_currentType5TextureWriteReadIndex * 4:X8}:stream={(_currentType5TextureWriteStreaming ? 1 : 0)}"
            : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-TEXWRITE] n={++_textureWriteBucketTraceCount} bn={bucketTraceCount} bucket=0x{bucket << TextureZeroSampleBucketShift:X6} " +
            $"word=0x{wordOffset:X6} addr=0x{byteOffset:X6} value=0x{value:X8} nzb={nonZeroBytes} " +
            $"lod={lod} ts=0x{ts:X2} tt=0x{tt:X2} bpp={bytesPerTexel} seq8={(seq8Downld ? 1 : 0)} " +
            $"mode=0x{mode:X8} tlod=0x{texLod:X8} tbase=0x{textureBase:X8} " +
            $"global=0x{_registers[RegTextureMode]:X8}/0x{_registers[RegTextureLod]:X8}/0x{_registers[RegTextureBaseAddr]:X8} " +
            $"tmu0={FormatTmuDebugStatus(0)} tmu1={FormatTmuDebugStatus(1)}{type5Status}{pcStatus}");
    }

    private uint ReadTextureUploadRegister(int tmu, int register)
        => _experimentTextureUploadTmuBanks && tmu <= 1
            ? ReadTextureRegisterForTmu(tmu, register)
            : ReadTextureRegister(register);

    private uint GetMameTextureWritePtrByteOffset(
        int targetLod,
        int bytesPerTexel,
        uint textureLod,
        uint textureBase,
        uint textureBase1,
        uint textureBase2,
        uint textureBase38,
        uint s,
        uint t)
    {
        targetLod = Math.Clamp(targetLod, 0, 8);

        uint widthMask = 0xffu;
        uint heightMask = 0xffu;
        int aspect = (int)((textureLod >> 21) & 0x03u);
        if (((textureLod >> 20) & 1u) != 0)
            heightMask >>= aspect;
        else
            widthMask >>= aspect;

        uint lodMask = 0x1ffu;
        if (((textureLod >> 19) & 1u) != 0)
            lodMask = ((textureLod >> 18) & 1u) != 0 ? 0x0aau : 0x155u;

        int bppShift = bytesPerTexel == 1 ? 0 : 1;
        uint baseAddress = GetTextureBaseAddress(textureBase);
        uint lodOffset0 = baseAddress & (TextureBytes - 1u);
        uint lodOffset1;
        uint lodOffset2;
        uint lodOffset3;
        bool multiBase = ((textureLod >> 24) & 1u) != 0 && ((textureLod >> 28) & 0x0fu) == 0;
        if (multiBase)
        {
            lodOffset1 = GetTextureBaseAddress(textureBase1);
            lodOffset2 = GetTextureBaseAddress(textureBase2);
            baseAddress = GetTextureBaseAddress(textureBase38);
            lodOffset3 = baseAddress & (TextureBytes - 1u);
        }
        else
        {
            if ((lodMask & (1u << 0)) != 0)
                baseAddress += ((widthMask >> 0) + 1u) * ((heightMask >> 0) + 1u) << bppShift;
            lodOffset1 = baseAddress & (TextureBytes - 1u);
            if ((lodMask & (1u << 1)) != 0)
                baseAddress += ((widthMask >> 1) + 1u) * ((heightMask >> 1) + 1u) << bppShift;
            lodOffset2 = baseAddress & (TextureBytes - 1u);
            if ((lodMask & (1u << 2)) != 0)
                baseAddress += ((widthMask >> 2) + 1u) * ((heightMask >> 2) + 1u) << bppShift;
            lodOffset3 = baseAddress & (TextureBytes - 1u);
        }

        uint lodOffset = targetLod switch
        {
            0 => lodOffset0,
            1 => lodOffset1,
            2 => lodOffset2,
            3 => lodOffset3,
            _ => 0
        };
        for (int lod = 4; lod <= 8; lod++)
        {
            if ((lodMask & (1u << (lod - 1))) != 0)
            {
                uint size = ((widthMask >> (lod - 1)) + 1u) * ((heightMask >> (lod - 1)) + 1u);
                if (size < 4u)
                    size = 4u;
                baseAddress += size << bppShift;
            }
            if (targetLod == lod)
            {
                lodOffset = baseAddress & (TextureBytes - 1u);
                break;
            }
        }

        uint texelOffset = t * ((widthMask >> targetLod) + 1u) + s;
        return (lodOffset + ((uint)bytesPerTexel * texelOffset & ~3u)) & (TextureBytes - 1u);
    }

    private bool ShouldApplyTextureUploadMameWritePtr(uint wordOffset)
        => _experimentTextureUploadMameWritePtr &&
           MatchesTextureUploadMameWritePtrFilters(
               wordOffset,
               _experimentTextureUploadMameWritePtrPcs,
               _experimentTextureUploadMameWritePtrTargetWords);

    private bool ShouldTraceTextureUploadMameWritePtr(uint wordOffset)
        => _traceTextureUploadMameWritePtr &&
           MatchesTextureUploadMameWritePtrFilters(
               wordOffset,
               _traceTextureUploadMameWritePtrPcs,
               _traceTextureUploadMameWritePtrTargetWords);

    private bool TryGetType5Seq8PacketBlockLayoutByteOffset(
        uint currentByteOffset,
        uint mode,
        uint texLod,
        uint textureBase,
        uint lod,
        int bytesPerTexel,
        bool seq8Downld,
        out uint byteOffset)
    {
        byteOffset = 0;
        if (!_experimentType5Seq8PacketBlockLayout ||
            !_currentType5TextureWriteActive ||
            _currentType5TextureWriteSpace != 3 ||
            _currentType5TextureWriteCount != 64 ||
            bytesPerTexel != 1 ||
            !seq8Downld)
        {
            return false;
        }

        ulong targetStart = _currentType5TextureWriteTargetStart;
        ulong baseTarget = _experimentType5Seq8PacketBlockLayoutBaseTarget;
        ulong targetSpan = _experimentType5Seq8PacketBlockLayoutTargetSpan;
        if (targetStart < baseTarget || targetStart >= baseTarget + targetSpan)
            return false;

        ulong targetDelta = targetStart - baseTarget;
        if ((targetDelta & 0x3fUL) != 0)
            return false;

        ulong packetIndex = targetDelta >> 6;
        uint packetBaseWord = (uint)baseTarget;
        uint packetBaseTt = (packetBaseWord >> 7) & 0xffu;
        uint packetBaseTs = (packetBaseWord << 2) & 0xffu;
        uint width = GetTextureWidth(texLod);
        uint height = GetTextureHeight(texLod);
        uint xMask = Math.Max(1u, width >> (int)lod) - 1u;
        uint yMask = Math.Max(1u, height >> (int)lod) - 1u;
        uint packetBaseTexel = (packetBaseTt & yMask) * (xMask + 1u) + (packetBaseTs & xMask);
        uint packetBaseByteOffset = (GetTextureLodOffset((int)lod, bytesPerTexel, texLod, textureBase) + packetBaseTexel) & (TextureBytes - 1u);
        if (_fixTextureDownloadAlign32)
            packetBaseByteOffset &= ~3u;

        ulong layoutByteOffset =
            (ulong)packetBaseByteOffset +
            packetIndex * _experimentType5Seq8PacketBlockLayoutBlockBytes +
            (ulong)Math.Max(0, _currentType5TextureWriteIndex) * 4UL;
        byteOffset = (uint)(layoutByteOffset & (TextureBytes - 1u));

        if (_type5Seq8PacketBlockLayoutTraceCount++ < _experimentType5Seq8PacketBlockLayoutTraceLimit &&
            currentByteOffset != byteOffset)
        {
            ulong pc = CpuPcProvider?.Invoke() ?? 0;
            string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
            Console.WriteLine(
                $"[GAUNTDL:EXPERIMENT] type5-seq8-packet-block-layout " +
                $"targetStart=0x{_currentType5TextureWriteTargetStart:X6} target=0x{_currentType5TextureWriteTargetWord:X6} " +
                $"i={_currentType5TextureWriteIndex}/{_currentType5TextureWriteCount} packetIndex={packetIndex} " +
                $"current=0x{currentByteOffset:X6}->block=0x{byteOffset:X6} base=0x{packetBaseByteOffset:X6} " +
                $"blockBytes=0x{_experimentType5Seq8PacketBlockLayoutBlockBytes:X} mode=0x{mode:X8} tlod=0x{texLod:X8} " +
                $"tbase=0x{textureBase:X8}{pcStatus}");
        }

        return true;
    }

    private bool MatchesTextureUploadMameWritePtrFilters(uint wordOffset, ulong[] pcs, ulong[] targetWords)
    {
        if (pcs.Length != 0)
        {
            ulong pc = CpuPcProvider?.Invoke() ?? 0;
            if (!MatchesTracePc(pcs, pc))
                return false;
        }

        if (targetWords.Length == 0)
            return true;

        if (targetWords.Contains(wordOffset))
            return true;

        return _currentType5TextureWriteActive &&
            (targetWords.Contains(_currentType5TextureWriteTargetWord) ||
             targetWords.Contains(_currentType5TextureWriteTargetStart));
    }

    private void TraceTextureUploadMameWritePtr(
        uint wordOffset,
        uint currentByteOffset,
        uint mameByteOffset,
        uint mode,
        uint texLod,
        uint textureBase,
        uint lod,
        uint ts,
        uint tt,
        int bytesPerTexel,
        bool seq8Downld)
    {
        if (!_traceTextureUploadMameWritePtr ||
            (currentByteOffset == mameByteOffset && _traceTextureUploadMameWritePtrTargetWords.Length == 0) ||
            _textureUploadMameWritePtrTraceCount >= _traceTextureUploadMameWritePtrLimit)
        {
            return;
        }

        uint width = GetTextureWidth(texLod);
        uint height = GetTextureHeight(texLod);
        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        string type5Status = _currentType5TextureWriteActive
            ? $" type5=cmd=0x{_currentType5TextureWriteCommand:X8}:space={_currentType5TextureWriteSpace}:targetStart=0x{_currentType5TextureWriteTargetStart:X6}:target=0x{_currentType5TextureWriteTargetWord:X6}:i={_currentType5TextureWriteIndex}/{_currentType5TextureWriteCount}:packet=0x{_currentCommandFifoPacketStart * 4:X8}:rd=0x{_currentType5TextureWriteReadIndex * 4:X8}:stream={(_currentType5TextureWriteStreaming ? 1 : 0)}"
            : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-TEXUPLOAD-MAMEPTR] n={++_textureUploadMameWritePtrTraceCount} " +
            $"word=0x{wordOffset:X6} current=0x{currentByteOffset:X6} mame=0x{mameByteOffset:X6} " +
            $"match={(currentByteOffset == mameByteOffset ? 1 : 0)} " +
            $"lod={lod} ts=0x{ts:X2} tt=0x{tt:X2} size={width}x{height} bpp={bytesPerTexel} seq8={(seq8Downld ? 1 : 0)} " +
            $"mode=0x{mode:X8} tlod=0x{texLod:X8} tbase=0x{textureBase:X8}{type5Status}{pcStatus}");
    }

    private void WriteTextureLinear32(uint wordOffset, uint value, int bytesPerTexel, int tmu)
    {
        uint byteOffset = MapTextureBankByteAddress(tmu, wordOffset << 2);
        if (bytesPerTexel == 1)
        {
            bool previousSuppressZero = _suppressZeroTextureBytesForCurrentWrite;
            _suppressZeroTextureBytesForCurrentWrite = _fixSparse8BitTextureUpload;
            try
            {
                WriteTextureByte(byteOffset + 0u, (byte)value);
                WriteTextureByte(byteOffset + 1u, (byte)(value >> 8));
                WriteTextureByte(byteOffset + 2u, (byte)(value >> 16));
                WriteTextureByte(byteOffset + 3u, (byte)(value >> 24));
            }
            finally
            {
                _suppressZeroTextureBytesForCurrentWrite = previousSuppressZero;
            }
        }
        else
        {
            WriteTextureUInt16(byteOffset + 0u, (ushort)value);
            WriteTextureUInt16(byteOffset + 2u, (ushort)(value >> 16));
        }
    }

    private void WriteTextureByte(uint byteOffset, byte value)
    {
        uint physicalAddress = byteOffset & (TextureBytes - 1u);
        uint wordOffset = physicalAddress >> 2;
        if (_experimentPreserveTexturePhysicalMin.HasValue &&
            _experimentPreserveTexturePhysicalMax.HasValue &&
            physicalAddress >= _experimentPreserveTexturePhysicalMin.Value &&
            physicalAddress < _experimentPreserveTexturePhysicalMax.Value)
        {
            TrackTextureMappedWrite((int)wordOffset, value);
            return;
        }

        if (ShouldPreserveTextureOwner((int)wordOffset, byteOffset, value))
        {
            if (_experimentPreserveTextureOwnerRebuildMissingOwner &&
                !_textureWordLastWriters.ContainsKey((int)wordOffset))
            {
                TrackTextureLastWriter((int)wordOffset);
            }
            TrackTextureMappedWrite((int)wordOffset, value);
            return;
        }

        int shift = (int)((byteOffset & 3u) * 8u);
        uint mask = 0xffu << shift;
        if ((_preserveNonZeroTextureBytes || _suppressZeroTextureBytesForCurrentWrite) &&
            value == 0 &&
            (_textureMemory[wordOffset] & mask) != 0)
        {
            TrackTextureMappedWrite((int)wordOffset, value);
            return;
        }

        uint oldValue = _textureMemory[wordOffset];
        uint newValue = (oldValue & ~mask) | ((uint)value << shift);
        TraceTextureOverwrite((int)wordOffset, byteOffset, oldValue, newValue, mask);
        _textureMemory[wordOffset] = newValue;
        TrackTextureLastWriter((int)wordOffset);
        TrackTextureMappedWrite((int)wordOffset, value);
    }

    private bool ShouldPreserveTextureOwner(int wordOffset, uint byteOffset, byte value)
    {
        if (!_experimentPreserveTextureOwnerTargetMin.HasValue ||
            !_experimentPreserveTextureOwnerTargetMax.HasValue ||
            _experimentPreserveTextureOwnerAgainstPcs.Length == 0 ||
            !_currentType5TextureWriteActive ||
            _currentType5TextureWriteTargetStart < _experimentPreserveTextureOwnerTargetMin.Value ||
            _currentType5TextureWriteTargetStart >= _experimentPreserveTextureOwnerTargetMax.Value)
        {
            return false;
        }

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if (!MatchesTracePc(_experimentPreserveTextureOwnerAgainstPcs, pc))
            return false;

        if (_preserveTextureOwnerTraceCount++ < _experimentPreserveTextureOwnerTraceLimit)
        {
            string previousOwner = _textureWordLastWriters.TryGetValue(wordOffset, out TextureWordLastWriter writer)
                ? FormatTextureWordWriterStatus(writer)
                : "none";
            Console.WriteLine(
                $"[GAUNTDL:EXPERIMENT] preserve-texture-owner n={_preserveTextureOwnerTraceCount} " +
                $"addr=0x{byteOffset & (TextureBytes - 1u):X6}/w0x{wordOffset:X5} value=0x{value:X2} " +
                $"previous={previousOwner} " +
                $"blocked=pc0x{pc & 0xffffffffUL:x8}/cmd0x{_currentType5TextureWriteCommand:X8}@0x{_currentType5TextureWriteTargetStart:X6}:0x{_currentType5TextureWriteTargetWord:X6}");
        }

        return true;
    }

    private void TrackTextureLastWriter(int wordOffset)
    {
        if ((!_traceTexturedTriangleSampleWriters &&
             !_traceTextureSampleWriters &&
             !_traceTexturedTriangleSampleSummaryRequireWriter &&
             !_experimentFullrectSampleWriterLayout &&
             !_debugTextureRangeMin.HasValue &&
             !_traceTextureOverwriteRangeMin.HasValue) ||
            !_currentTextureWriteActive)
        {
            return;
        }

        ulong byteAddress = (ulong)(uint)wordOffset << 2;
        if (_traceTextureSampleWriters &&
            _traceTextureSampleWritersRangeMin.HasValue &&
            _traceTextureSampleWritersRangeMax.HasValue &&
            (byteAddress < _traceTextureSampleWritersRangeMin.Value ||
             byteAddress >= _traceTextureSampleWritersRangeMax.Value))
        {
            return;
        }

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if (_currentType5TextureWriteActive)
        {
            if (_currentType5TextureWritePhysicalMinWord < 0 || wordOffset < _currentType5TextureWritePhysicalMinWord)
                _currentType5TextureWritePhysicalMinWord = wordOffset;
            if (wordOffset > _currentType5TextureWritePhysicalMaxWord)
                _currentType5TextureWritePhysicalMaxWord = wordOffset;
        }

        var writer = new TextureWordLastWriter(
            pc,
            _currentTextureWriteValue,
            _currentTextureWriteMode,
            _currentTextureWriteTexLod,
            _currentTextureWriteBase,
            _currentTextureWriteLod,
            _currentTextureWriteBytesPerTexel,
            _currentTextureWriteSeq8,
            _currentType5TextureWriteActive,
            _currentType5TextureWriteCommand,
            _currentType5TextureWriteSpace,
            _currentType5TextureWriteTargetStart,
            _currentType5TextureWriteTargetWord,
            _currentType5TextureWritePayloadHash,
            _currentType5TextureWritePayloadNonZeroWords,
            _currentType5TextureWritePayloadFloatLikeWords,
            _currentType5TextureWriteIndex,
            _currentType5TextureWriteCount,
            _currentCommandFifoPacketStart,
            _currentType5TextureWriteReadIndex,
            _currentType5TextureWriteStreaming);
        TextureWordSourceProvenance source = default;
        if (_currentType5TextureWriteActive &&
            _cmdFifoLogicalPacketBulkWriteSources.TryGetValue(
                _currentCommandFifoPacketStart,
                out CommandFifoStorageBulkWriteSource bulkSource))
        {
            source = new TextureWordSourceProvenance(
                unchecked((ulong)(long)(int)((uint)bulkSource.Source + (uint)Math.Max(0, _currentType5TextureWriteIndex) * 4U)),
                bulkSource.SourceBase,
                bulkSource.PacketSourceAddress,
                bulkSource.Packet,
                bulkSource.Index,
                bulkSource.Limit,
                bulkSource.Word,
                bulkSource.PayloadWords,
                _renderFrame);
        }

        if (_textureWordLastWriters.TryGetValue(wordOffset, out TextureWordLastWriter previousWriter))
        {
            _textureWordSourceProvenance.TryGetValue(wordOffset, out TextureWordSourceProvenance previousSource);
            bool sameKnownSource = source.Source != 0 && previousSource.Source == source.Source;
            bool distinctOwner = !sameKnownSource &&
                (previousWriter.Pc != writer.Pc ||
                 previousSource.Source != source.Source ||
                 previousWriter.PacketStart != writer.PacketStart ||
                 previousWriter.Type5TargetStart != writer.Type5TargetStart);
            if (distinctOwner)
                _textureWordPreviousWriters[wordOffset] = new TextureWordPreviousWriter(previousWriter, previousSource);
        }

        _textureWordLastWriters[wordOffset] = writer;
        if (source.Source != 0)
        {
            _textureWordSourceProvenance[wordOffset] = source;
        }
        else
        {
            _textureWordSourceProvenance.Remove(wordOffset);
        }
        if (writer.Type5 && writer.Type5Index >= 0)
            _textureTargetIndexWords[new FullrectTargetIndexKey(writer.Type5TargetStart, writer.Type5Index)] = wordOffset;
        _textureWordLastWriterVersion++;
    }

    private void TraceTextureOverwrite(int wordOffset, uint byteOffset, uint oldValue, uint newValue, uint mask)
    {
        if (!_traceTextureOverwriteRangeMin.HasValue ||
            !_traceTextureOverwriteRangeMax.HasValue ||
            !_traceTextureOverwriteSeedTargetMin.HasValue ||
            !_traceTextureOverwriteSeedTargetMax.HasValue ||
            !_currentTextureWriteActive ||
            !_currentType5TextureWriteActive)
        {
            return;
        }

        uint address = byteOffset & (TextureBytes - 1u);
        if (address < _traceTextureOverwriteRangeMin.Value ||
            address >= _traceTextureOverwriteRangeMax.Value)
        {
            return;
        }

        bool seedWrite =
            _currentType5TextureWriteTargetStart >= _traceTextureOverwriteSeedTargetMin.Value &&
            _currentType5TextureWriteTargetStart < _traceTextureOverwriteSeedTargetMax.Value;
        if (seedWrite)
        {
            if (_textureOverwriteSeededWords.Add(wordOffset))
                _textureOverwriteSeedCount++;
            return;
        }

        if (!_textureOverwriteSeededWords.Contains(wordOffset))
            return;

        if (oldValue == newValue)
        {
            _textureOverwriteReassertedWords.Add(wordOffset);
            return;
        }

        _textureOverwriteSeededWords.Remove(wordOffset);
        _textureOverwriteChangedWords.Add(wordOffset);
        if (_textureOverwriteTraceCount >= _traceTextureOverwriteLimit)
            return;

        _textureOverwriteTraceCount++;
        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string previous = _textureWordLastWriters.TryGetValue(wordOffset, out TextureWordLastWriter writer)
            ? FormatTextureWordWriterStatus(writer)
            : "none";
        string previousSource = _textureWordSourceProvenance.TryGetValue(wordOffset, out TextureWordSourceProvenance source)
            ? $"0x{source.Source:x16}/base0x{source.SourceBase:x8}/packet{source.Packet}/index{source.Index}-{source.Limit}/frame{source.RenderFrame}"
            : "-";
        string currentSource = _cmdFifoLogicalPacketBulkWriteSources.TryGetValue(
            _currentCommandFifoPacketStart,
            out CommandFifoStorageBulkWriteSource bulkSource)
            ? $"0x{bulkSource.Source:x16}/root0x{GetType5TextureUploadSequenceSourceRoot(bulkSource):x8}/base0x{bulkSource.SourceBase:x8}/packet{bulkSource.Packet}/index{bulkSource.Index}-{bulkSource.Limit}"
            : "-";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-TEXOVERWRITE] n={_textureOverwriteTraceCount} seeded={_textureOverwriteSeedCount} " +
            $"addr=0x{address:X6} word=0x{wordOffset:X6} mask=0x{mask:X8} old=0x{oldValue:X8} new=0x{newValue:X8} " +
            $"current=pc0x{pc & 0xffffffffUL:x8}/mode0x{_currentTextureWriteMode:X8}/lod0x{_currentTextureWriteTexLod:X8}/" +
            $"base0x{_currentTextureWriteBase:X8}/l{_currentTextureWriteLod}/bpp{_currentTextureWriteBytesPerTexel}/" +
            $"cmd0x{_currentType5TextureWriteCommand:X8}@0x{_currentType5TextureWriteTargetStart:X6}:0x{_currentType5TextureWriteTargetWord:X6}/" +
            $"ph0x{_currentType5TextureWritePayloadHash:X8}/i{_currentType5TextureWriteIndex}-{_currentType5TextureWriteCount}/source={currentSource} " +
            $"previous={previous}/source={previousSource}");
    }

    private void TrackTextureMappedWrite(int wordOffset, uint value)
    {
        _textureMappedWriteCount++;
        if (value == 0)
            _textureMappedZeroWriteCount++;
        else
            _textureMappedNonZeroWriteCount++;

        if (_debugTextureZeroSampleBuckets)
        {
            int bucket = wordOffset >> (TextureZeroSampleBucketShift - 2);
            if ((uint)bucket < _textureZeroWriteBuckets.Length)
            {
                if (value == 0)
                    _textureZeroWriteBuckets[bucket]++;
                else
                    _textureNonZeroWriteBuckets[bucket]++;
            }
        }

        if (!_textureTouchedWords[wordOffset])
        {
            _textureTouchedWords[wordOffset] = true;
            _textureTouchedWordCount++;
            if (_textureTouchedFirstWord < 0 || wordOffset < _textureTouchedFirstWord)
                _textureTouchedFirstWord = wordOffset;
            if (wordOffset > _textureTouchedLastWord)
                _textureTouchedLastWord = wordOffset;
        }
    }

    private void WriteTextureUInt16(uint byteOffset, ushort value)
    {
        uint aligned = byteOffset & ~1u;
        WriteTextureByte(aligned, (byte)value);
        WriteTextureByte(aligned + 1u, (byte)(value >> 8));
    }

    public virtual uint ReadTexture32(uint offset)
        => _textureMemory[(offset >> 2) & (TextureWords - 1)];

    public void RenderFrame(EutherFrameTarget target)
    {
        if (!HasVideoActivity || target.Buffer is null || target.Width <= 0 || target.Height <= 0 || target.Stride < target.Width * 4)
            return;

        _renderFrame++;
        if (!TryRenderLfb(target))
        {
            Clear(target, 0xff080b0fu);
            DrawRegisterBands(target);
        }
        if (_showDebugOverlay)
            DrawViewportOverlay(target);
    }

    private bool TryRenderLfb(EutherFrameTarget target)
    {
        if (_lfbWriteCount == 0)
            return false;

        int copyWidth = Math.Min(target.Width, 640);
        int copyHeight = Math.Min(target.Height, 480);
        int renderBufferIndex = ChooseRenderBufferIndex();
        TraceRenderBufferChoice(renderBufferIndex);
        _lastRenderBufferIndex = renderBufferIndex;
        if (ShouldMaterializePendingClearForRender(renderBufferIndex))
            MaterializePendingClear(renderBufferIndex);
        ushort[] front = _colorBuffers[renderBufferIndex];
        for (int y = 0; y < copyHeight; y++)
        {
            int sourceY = _fixMameMediumResolutionOutput ? y * 384 / copyHeight : y;
            int src = sourceY * 1024;
            int dst = y * target.Stride;
            for (int x = 0; x < copyWidth; x++)
            {
                int sourceX = _fixMameMediumResolutionOutput ? x * 512 / copyWidth : x;
                ushort rgb = front[(src + sourceX) & (LfbPixels - 1)];
                uint bgra = Rgb565ToBgra(rgb);
                target.Buffer[dst + 0] = (byte)(bgra & 0xff);
                target.Buffer[dst + 1] = (byte)((bgra >> 8) & 0xff);
                target.Buffer[dst + 2] = (byte)((bgra >> 16) & 0xff);
                target.Buffer[dst + 3] = 0xff;
                dst += 4;
            }
        }

        return _lfbWriteCount > 0;
    }

    private void TraceRenderBufferChoice(int renderBufferIndex)
    {
        if (!_traceRenderBufferChoice || _renderBufferChoiceTraceCount++ >= _traceRenderBufferChoiceLimit)
            return;

        string[] buffers = new string[_colorBuffers.Length];
        for (int i = 0; i < _colorBuffers.Length; i++)
            buffers[i] = FormatRenderBufferTraceStats(i);

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-RENDER-BUFFER] n={_renderBufferChoiceTraceCount} frame={_renderFrame} " +
            $"front={_frontBufferIndex} back={_backBufferIndex} chosen={renderBufferIndex} " +
            string.Join(" ", buffers) +
            $" lfb={_lfbWriteCount} rast={_solidRasterPixelCount}/{_texturedRasterPixelCount}{pcStatus}");
    }

    private string FormatRenderBufferTraceStats(int index)
    {
        if ((uint)index >= (uint)_colorBuffers.Length)
            return $"b{index}=missing";

        int nonZero = GetBufferNonZeroCount(index);
        int active = GetVisibleBufferActiveColorCount(index);
        int white = GetVisibleBufferWhiteCount(index);
        int unique = GetVisibleBufferUniqueColorCount(index, 128);
        string pending = IsPendingClearBuffer(index)
            ? $"p=1:{_pendingClearX0[index]}-{_pendingClearX1[index]}x{_pendingClearY0[index]}-{_pendingClearY1[index]}:0x{_pendingClearColor[index]:X4}"
            : "p=0";
        return $"b{index}=nz{nonZero}:act{active}:w{white}:u{unique}:{pending}";
    }

    private int ChooseRenderBufferIndex()
    {
        if (!_fixDisplayBufferSelection)
            return _frontBufferIndex;

        int frontCount = GetBufferNonZeroCount(_frontBufferIndex);
        int frontActiveCount = GetVisibleBufferActiveColorCount(_frontBufferIndex);
        int frontWhiteCount = GetVisibleBufferWhiteCount(_frontBufferIndex);
        int frontUniqueCount = GetVisibleBufferUniqueColorCount(_frontBufferIndex, 128);
        bool frontIsWhiteClearDominated =
            frontWhiteCount > 240_000 &&
            frontActiveCount < 32_000 &&
            (frontActiveCount <= 1024 || frontUniqueCount <= 8);
        bool frontIsLowDetailFill = frontUniqueCount <= 8 && frontActiveCount > 240_000;
        bool frontIsUsable = !frontIsWhiteClearDominated && frontCount > 1024 && frontActiveCount > 1024;
        if (frontIsUsable)
            return _frontBufferIndex;

        int bestIndex = _frontBufferIndex;
        int bestCount = frontCount;
        int bestActiveCount = frontActiveCount;
        int bestUniqueCount = frontUniqueCount;
        int fallbackIndex = _backBufferIndex;
        int fallbackActiveCount = 0;
        int fallbackNonWhiteCount = 0;
        int fallbackUniqueCount = 0;
        bool fallbackIsLowDetailFill = true;
        int count = _colorBuffers.Length;
        for (int i = 0; i < count; i++)
        {
            if (i == _frontBufferIndex)
                continue;

            int candidateCount = GetBufferNonZeroCount(i);
            int candidateActiveCount = GetVisibleBufferActiveColorCount(i);
            int candidateWhiteCount = GetVisibleBufferWhiteCount(i);
            int candidateNonWhiteCount = Math.Max(0, candidateCount - candidateWhiteCount);
            int candidateUniqueCount = GetVisibleBufferUniqueColorCount(i, 128);
            bool candidateIsLowDetailFill = candidateUniqueCount <= 8 && candidateActiveCount > 240_000;
            if (IsPendingClearBuffer(i) && candidateActiveCount <= 1024)
                continue;

            if ((fallbackIsLowDetailFill && !candidateIsLowDetailFill) ||
                candidateIsLowDetailFill == fallbackIsLowDetailFill && candidateActiveCount > fallbackActiveCount ||
                candidateIsLowDetailFill == fallbackIsLowDetailFill && candidateActiveCount == fallbackActiveCount && candidateUniqueCount > fallbackUniqueCount ||
                candidateIsLowDetailFill == fallbackIsLowDetailFill && candidateActiveCount == fallbackActiveCount && candidateUniqueCount == fallbackUniqueCount && candidateNonWhiteCount > fallbackNonWhiteCount)
            {
                fallbackIndex = i;
                fallbackActiveCount = candidateActiveCount;
                fallbackNonWhiteCount = candidateNonWhiteCount;
                fallbackUniqueCount = candidateUniqueCount;
                fallbackIsLowDetailFill = candidateIsLowDetailFill;
            }

            if (candidateCount > 1024 &&
                candidateActiveCount > 1024 &&
                (!frontIsUsable ||
                 frontIsLowDetailFill && candidateUniqueCount >= bestUniqueCount + 16 ||
                 !candidateIsLowDetailFill && candidateUniqueCount >= bestUniqueCount + 32 && candidateActiveCount >= bestActiveCount * 2 / 3 ||
                 !candidateIsLowDetailFill && candidateActiveCount > bestActiveCount + 32_768 ||
                 !candidateIsLowDetailFill && candidateActiveCount >= bestActiveCount * 2 ||
                 bestActiveCount <= 1024 && candidateCount > bestCount ||
                 frontIsWhiteClearDominated && candidateActiveCount >= bestActiveCount * 3 / 4))
            {
                bestIndex = i;
                bestCount = candidateCount;
                bestActiveCount = candidateActiveCount;
                bestUniqueCount = candidateUniqueCount;
                frontIsWhiteClearDominated = false;
                frontIsLowDetailFill = false;
            }
        }

        if (frontIsWhiteClearDominated && bestIndex == _frontBufferIndex)
            return fallbackActiveCount > 0 || fallbackNonWhiteCount > 0 ? fallbackIndex : _frontBufferIndex;

        return bestIndex;
    }

    private bool ShouldMaterializePendingClearForRender(int bufferIndex)
    {
        if ((uint)bufferIndex >= (uint)_pendingClearValid.Length || !_pendingClearValid[bufferIndex])
            return false;

        return GetBufferNonZeroCount(bufferIndex) == 0;
    }

    private bool IsPendingClearBuffer(int bufferIndex)
        => (uint)bufferIndex < (uint)_pendingClearValid.Length && _pendingClearValid[bufferIndex];

    private void DrawRegisterBands(EutherFrameTarget target)
    {
        int bandHeight = Math.Max(6, target.Height / 64);
        for (int i = 0; i < 32; i++)
        {
            uint register = i < 16
                ? (0x100u >> 2) + (uint)i
                : (0x200u >> 2) + (uint)(i - 16);
            uint value = _registers[register];
            uint color = 0xff000000u |
                ((value << 3) & 0x00ff0000u) |
                ((value >> 5) & 0x0000ff00u) |
                ((value >> 13) & 0x000000ffu);
            FillRect(target, 0, i * bandHeight, target.Width, bandHeight, color);
        }
    }

    private void DrawViewportOverlay(EutherFrameTarget target)
    {
        uint clipX = _registers[(0x118u >> 2) & 0x3ffu];
        uint clipY = _registers[(0x11cu >> 2) & 0x3ffu];
        int x0 = (int)((clipX >> 16) & 0x7ff);
        int x1 = (int)(clipX & 0x7ff);
        int y0 = (int)((clipY >> 16) & 0x7ff);
        int y1 = (int)(clipY & 0x7ff);
        if (x1 <= x0 || x1 > target.Width)
        {
            uint dimensions = _registers[(0x20cu >> 2) & 0x3ffu];
            x0 = 0;
            x1 = dimensions != 0
                ? Math.Clamp((int)(dimensions & 0x7ff) + 1, 1, target.Width)
                : target.Width;
        }
        if (y1 <= y0 || y1 > target.Height)
        {
            uint dimensions = _registers[(0x20cu >> 2) & 0x3ffu];
            y0 = 0;
            y1 = dimensions != 0
                ? Math.Clamp((int)((dimensions >> 16) & 0x7ff), 1, target.Height)
                : target.Height;
        }

        DrawRect(target, x0, y0, x1 - x0, y1 - y0, 0xffffffffu);

        int sweep = _renderFrame % Math.Max(1, target.Width);
        FillRect(target, sweep, y0, 4, y1 - y0, 0xff00d7ffu);
        FillRect(target, 16, target.Height - 28, Math.Min(target.Width - 32, _registerWriteCount / 32), 8, 0xff39d353u);
        FillRect(target, 16, target.Height - 18, Math.Min(target.Width - 32, (int)Math.Min(int.MaxValue, _lfbWriteCount / 64)), 8, 0xfff7b955u);
        FillRect(target, 16, target.Height - 8, Math.Min(target.Width - 32, (_fifoWriteCount + _fifoPacketCount * 8 + _textureWriteCount) / 256), 6, 0xffc678ddU);
        FillRect(target, target.Width - 24, 16, 8, Math.Min(target.Height - 32, _fifoDrawPacketCount * 4), 0xffff6b6bu);
        FillRect(target, target.Width - 40, 16, 8, Math.Min(target.Height - 32, _fastFillCount * 4), 0xff39d353u);
        FillRect(target, target.Width - 56, 16, 8, Math.Min(target.Height - 32, _swapBufferCount * 4), 0xfff7b955u);
    }

    private void FastFill()
    {
        uint clipX = _registers[0x46];
        uint clipY = _registers[0x47];
        int x0 = Math.Clamp((int)((clipX >> 16) & 0x7ff), 0, 1024);
        int x1 = Math.Clamp((int)(clipX & 0x7ff), 0, 1024);
        int y0 = Math.Clamp((int)((clipY >> 16) & 0x7ff), 0, 1024);
        int y1 = Math.Clamp((int)(clipY & 0x7ff), 0, 1024);
        if (x1 <= x0)
        {
            x0 = 0;
            x1 = 640;
        }
        if (y1 <= y0)
        {
            y0 = 0;
            y1 = 480;
        }

        x1 = Math.Min(x1, 1024);
        y1 = Math.Min(y1, LfbRows);
        ushort color = ArgbToRgb565(_registers[RegColor1]);
        if (color == 0)
            color = ArgbToRgb565(_registers[RegColor0]);
        if (color == 0)
        {
            if (_fixDropLeakedType5RegisterHeaders && IsType5TexturePacketHeader(_registers[RegZaColor]))
            {
                RecordVoodooEvent($"drop leaked type5 fastfill za=0x{_registers[RegZaColor]:x8}");
                return;
            }
            color = (ushort)_registers[RegZaColor];
        }

        TraceDraw($"fastfill clip=({x0},{y0})-({x1},{y1}) color=0x{color:X4} c0=0x{_registers[RegColor0]:X8} c1=0x{_registers[RegColor1]:X8} fbz=0x{_registers[RegFbzMode]:X8}");
        if (_traceNonNeutralFastFill && color != 0 && color != 0xffff && _nonNeutralFastFillTraceCount++ < 64)
        {
            ulong pc = CpuPcProvider?.Invoke() ?? 0;
            string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
            Console.WriteLine(
                $"[GAUNTDL:VOODOO-FILL] clip=({x0},{y0})-({x1},{y1}) color=0x{color:X4} " +
                $"c0=0x{_registers[RegColor0]:X8} c1=0x{_registers[RegColor1]:X8} za=0x{_registers[RegZaColor]:X8} " +
                $"fbz=0x{_registers[RegFbzMode]:X8} " +
                $"cmd=0x{_currentCommandFifoCommand:X8}:{_currentCommandFifoWordsNeeded}:0x{_currentCommandFifoPacketStart * 4:X8}:rd0x{_cmdFifoReadIndex * 4:X8} " +
                $"trigger={_commandFifoDecodeTrigger}{pcStatus}");
        }

        int bufferIndex = GetDrawBufferIndex();
        if ((_experimentSuppressNonNeutralFastFill && color != 0 && color != 0xffff) ||
            (_experimentSuppressWhiteFastFillAfterRaster &&
             color == 0xffff &&
             (uint)bufferIndex < (uint)_rasterBufferPixelCounts.Length &&
             _rasterBufferPixelCounts[bufferIndex] > 0) ||
            (_fixFastFillColorWriteMask && (_registers[RegFbzMode] & 0x400U) == 0) ||
            ShouldSuppressRgbBufferWrite())
        {
            TraceFastFillSwapOrder("fastfill-suppressed", RegFastfillCommand, color);
            if (color == 0xffff)
                _fastFillSuppressedWhiteCount++;
            else if (color == 0)
                _fastFillSuppressedBlackCount++;
            else
                _fastFillSuppressedOtherCount++;
            CountFastFillPc(color, suppressed: true, bufferIndex: -1);
            _fastFillCount++;
            return;
        }

        TraceFastFillSwapOrder("fastfill", RegFastfillCommand, color);
        CountFastFillPc(color, suppressed: false, bufferIndex);
        if ((uint)bufferIndex < (uint)_fastFillBufferCounts.Length)
        {
            _fastFillBufferCounts[bufferIndex]++;
            if (color == 0xffff)
                _fastFillWhiteBufferCounts[bufferIndex]++;
            else if (color == 0)
                _fastFillBlackBufferCounts[bufferIndex]++;
            else
                _fastFillOtherBufferCounts[bufferIndex]++;
        }

        int width = x1 - x0;
        if (!IsCachedFastFill(bufferIndex, x0, x1, y0, y1, color))
        {
            TrackPixelLastWriterRect(bufferIndex, x0, x1, y0, y1, GetPixelLastWriterId("fill", "fastfill", color));
            SetPendingClear(bufferIndex, x0, x1, y0, y1, color);
            CacheFastFill(bufferIndex, x0, x1, y0, y1, color);
        }

        _fastFillCount++;
        _lfbWriteCount += Math.Max(1, (width * (y1 - y0) + 1) / 2);
    }

    private void DecodeCommandFifoPackets(string trigger = "direct")
    {
        if (_decodingCommandFifo)
            return;

        _decodingCommandFifo = true;
        string previousTrigger = _commandFifoDecodeTrigger;
        _commandFifoDecodeTrigger = trigger;
        try
        {
        int guard = 0;
        int decodedThisCall = 0;
        ulong decodeCallPc = CpuPcProvider?.Invoke() ?? 0;
        int decodeCallStartReadIndex = _cmdFifoReadIndex;
        int decodeCallStartDepth = _cmdFifoDepth;
        uint decodeCallFirstCommand = 0;
        uint decodeCallLastCommand = 0;
        uint decodeCallTypeMask = 0;
        int packetLimit = _fixMameCommandFifoModel && _experimentMameCommandFifoDecodePacketLimit > 0
            ? _experimentMameCommandFifoDecodePacketLimit
            : 2048;
        while (guard++ < 2048 && decodedThisCall < packetLimit && IsCommandFifoPacketReady())
        {
            int packetStart = _cmdFifoReadIndex;
            uint command = ReadCommandFifoWordAt(packetStart);
            if ((_experimentCommandFifoGateType1ProducerBodyHeader ||
                 _experimentCommandFifoAdvanceType1ProducerBodyHeader) &&
                _cmdFifoStorageType1Body[CommandFifoReadStorageIndex(packetStart)])
            {
                if (_experimentCommandFifoAdvanceType1ProducerBodyHeader)
                {
                    int startStorage = CommandFifoReadStorageIndex(packetStart);
                    int packetEnd = _cmdFifoStorageType1PacketEnd[startStorage];
                    int wordsToSkip = ((packetEnd - startStorage) & CmdFifoMask) + 1;
                    InvalidateCommandFifoWords(packetStart, wordsToSkip);
                    SetCommandFifoReadIndex(DecodeCommandFifoReadIndex(packetStart + wordsToSkip), "type1-producer-body-advance", command, wordsToSkip);
                    continue;
                }
                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "type1-producer-body-header");
                TraceCommandFifoDecodeStop("type1-producer-body-header", command, GetFifoPacketWordsNeeded(command));
                return;
            }
            if ((_experimentCommandFifoGateType3ProducerBodyHeader ||
                 _experimentCommandFifoAdvanceType3ProducerBodyHeader) &&
                _cmdFifoStorageType3Body[CommandFifoReadStorageIndex(packetStart)])
            {
                if (_experimentCommandFifoAdvanceType3ProducerBodyHeader)
                {
                    int startStorage = CommandFifoReadStorageIndex(packetStart);
                    int packetEnd = _cmdFifoStorageType3PacketEnd[startStorage];
                    int wordsToSkip = ((packetEnd - startStorage) & CmdFifoMask) + 1;
                    InvalidateCommandFifoWords(packetStart, wordsToSkip);
                    SetCommandFifoReadIndex(DecodeCommandFifoReadIndex(packetStart + wordsToSkip), "type3-producer-body-advance", command, wordsToSkip);
                    continue;
                }
                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "type3-producer-body-header");
                TraceCommandFifoDecodeStop("type3-producer-body-header", command, GetFifoPacketWordsNeeded(command));
                return;
            }
            if ((_experimentCommandFifoGateType4ProducerBodyHeader ||
                 _experimentCommandFifoAdvanceType4ProducerBodyHeader) &&
                _cmdFifoStorageType4Body[CommandFifoReadStorageIndex(packetStart)])
            {
                if (_experimentCommandFifoAdvanceType4ProducerBodyHeader)
                {
                    int startStorage = CommandFifoReadStorageIndex(packetStart);
                    int packetEnd = _cmdFifoStorageType4PacketEnd[startStorage];
                    int wordsToSkip = ((packetEnd - startStorage) & CmdFifoMask) + 1;
                    InvalidateCommandFifoWords(packetStart, wordsToSkip);
                    SetCommandFifoReadIndex(DecodeCommandFifoReadIndex(packetStart + wordsToSkip), "type4-producer-body-advance", command, wordsToSkip);
                    continue;
                }
                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "type4-producer-body-header");
                TraceCommandFifoDecodeStop("type4-producer-body-header", command, GetFifoPacketWordsNeeded(command));
                return;
            }
            if ((_experimentCommandFifoGateType5ProducerBodyHeader ||
                 _experimentCommandFifoAdvanceType5ProducerBodyHeader) &&
                _cmdFifoStorageType5Body[CommandFifoReadStorageIndex(packetStart)])
            {
                if (_experimentCommandFifoAdvanceType5ProducerBodyHeader)
                {
                    int startStorage = CommandFifoReadStorageIndex(packetStart);
                    int packetEnd = _cmdFifoStorageType5PacketEnd[startStorage];
                    int wordsToSkip = ((packetEnd - startStorage) & CmdFifoMask) + 1;
                    InvalidateCommandFifoWords(packetStart, wordsToSkip);
                    SetCommandFifoReadIndex(DecodeCommandFifoReadIndex(packetStart + wordsToSkip), "type5-producer-body-advance", command, wordsToSkip);
                    continue;
                }
                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "type5-producer-body-header");
                TraceCommandFifoDecodeStop("type5-producer-body-header", command, GetFifoPacketWordsNeeded(command));
                return;
            }
            if (_fixMameCommandFifoModel &&
                _experimentMameCommandFifoYieldOnType5Boundary &&
                decodedThisCall > 0 &&
                decodeCallTypeMask == (1u << 5) &&
                (command & 7u) != 5u)
            {
                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "type5-boundary");
                return;
            }
            if (_fixMameCommandFifoModel &&
                _experimentMameCommandFifoYieldAfterTextureBatch &&
                decodedThisCall > 0 &&
                (decodeCallTypeMask & (1u << 5)) != 0 &&
                (command & 7u) is 1u or 3u or 4u)
            {
                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "texture-batch");
                return;
            }
            if (decodedThisCall == 0)
                decodeCallFirstCommand = command;
            decodeCallLastCommand = command;
            decodeCallTypeMask |= 1u << (int)(command & 7u);
            if ((_experimentCommandFifoStopOnUnknown ||
                 (_fixMameCommandFifoModel && _experimentMameCommandFifoStopOnUnknown)) &&
                (command & 7u) > 5u)
            {
                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "unknown");
                TraceCommandFifoDecodeStop("unknown", command, 1);
                return;
            }

            int wordsNeeded = GetFifoPacketWordsNeeded(command);
            if (IsKnownGauntletRuntimeMisalignedFifoWord(command, wordsNeeded))
                wordsNeeded = 1;
            if (wordsNeeded <= 0)
                wordsNeeded = 1;
            bool implausiblePacket = IsImplausibleCommandFifoPacket(command, wordsNeeded);
            if (implausiblePacket)
                TraceCommandFifoImplausiblePacket(command, wordsNeeded, packetStart);
            if (ShouldDropImplausibleType1OutsideBulkWindow(command, wordsNeeded, packetStart, implausiblePacket, out string dropOutsideBulkPosition))
            {
                TraceCommandFifoImplausibleType1OutsideBulkWindowDrop(command, wordsNeeded, packetStart, dropOutsideBulkPosition);
                if (TryDropInvalidCommandFifoPacketHeader(packetStart, command, wordsNeeded, "drop-type1-outside-bulk-window"))
                    continue;
            }
            if (ShouldGateImplausibleType1OutsideBulkWindow(command, wordsNeeded, packetStart, implausiblePacket, out string outsideBulkPosition))
            {
                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "type1-outside-bulk-window");
                TraceCommandFifoImplausibleType1OutsideBulkWindowGate(command, wordsNeeded, packetStart, outsideBulkPosition);
                TraceCommandFifoDecodeStop("type1-outside-bulk-window", command, wordsNeeded);
                return;
            }
            if (ShouldGateCollapsedBulkPayloadChain(command, wordsNeeded, packetStart, implausiblePacket))
            {
                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "bulk-collapsed-payload-chain");
                TraceCommandFifoDecodeStop("bulk-collapsed-payload-chain", command, wordsNeeded);
                return;
            }
            if (_experimentStopImplausibleCommandFifoRegisterPackets &&
                implausiblePacket &&
                (_experimentStopImplausibleCommandFifoRegisterPacketCommands.Length == 0 ||
                 _experimentStopImplausibleCommandFifoRegisterPacketCommands.Contains(command)))
            {
                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "implausible-packet");
                TraceCommandFifoDecodeStop("implausible-packet", command, wordsNeeded);
                return;
            }
            if (_experimentDropImplausibleCommandFifoType5Packets &&
                (command & 7u) == 5u &&
                implausiblePacket &&
                TryDropInvalidCommandFifoPacketHeader(packetStart, command, wordsNeeded, "drop-implausible-type5"))
            {
                continue;
            }
            if ((_experimentDropImplausibleCommandFifoRegisterPackets ||
                 (_fixMameCommandFifoModel && _experimentMameCommandFifoDropImplausibleRegisterPacket)) &&
                implausiblePacket &&
                TryDropInvalidCommandFifoPacketHeader(packetStart, command, wordsNeeded, "drop-implausible-packet"))
            {
                continue;
            }
            if (_fixMameCommandFifoModel && _cmdFifoDepth < wordsNeeded)
            {
                if (TryTruncateMameCommandFifoPartialType4(command, wordsNeeded, out int truncatedWordsNeeded))
                    wordsNeeded = truncatedWordsNeeded;
                else if (_experimentMameCommandFifoAllowValidPacketDepthShort &&
                         HasCommandFifoWords(packetStart, wordsNeeded))
                {
                    TraceCommandFifoDecodeStop("depth-short-valid-window", command, wordsNeeded);
                }
                else
                {
                if (TryResyncMameCommandFifoOnPartialType5(command, packetStart, wordsNeeded))
                    continue;

                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "depth");
                TraceCommandFifoDecodeStop("depth", command, wordsNeeded);
                return;
                }
            }
            if (_cmdFifoBulkDecodeRemainingWords > 0 && wordsNeeded > _cmdFifoBulkDecodeRemainingWords)
            {
                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "bulk-window");
                TraceCommandFifoDecodeStop("bulk-window", command, wordsNeeded);
                return;
            }
            if (_fixMameCommandFifoModel &&
                _experimentMameCommandFifoRequirePacketInAddressWindow &&
                _cmdFifoAddressMin >= _cmdFifoRamBase &&
                !IsMameCommandFifoPacketInsideAddressWindow(packetStart, wordsNeeded))
            {
                if (_experimentMameCommandFifoDropInvalidPacketHeader &&
                    TryDropInvalidCommandFifoPacketHeader(packetStart, command, wordsNeeded, "drop-outside-window"))
                {
                    continue;
                }

                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "packet-outside-window");
                TraceCommandFifoDecodeStop("packet-outside-window", command, wordsNeeded);
                return;
            }
            if (_fixMameCommandFifoModel &&
                _experimentMameCommandFifoRequireValidPacketWindow &&
                !HasCommandFifoWords(packetStart, wordsNeeded))
            {
                if (_experimentMameCommandFifoDropInvalidPacketHeader &&
                    TryDropInvalidCommandFifoPacketHeader(packetStart, command, wordsNeeded, "drop-invalid-packet"))
                {
                    continue;
                }

                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "invalid-packet-window");
                TraceCommandFifoDecodeStop("invalid-packet-window", command, wordsNeeded);
                return;
            }
            if (_fixMameCommandFifoModel &&
                _experimentMameCommandFifoRequireValidType5PacketWindow &&
                (command & 7u) == 5u &&
                !HasCommandFifoWords(packetStart, wordsNeeded))
            {
                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "invalid-type5-window");
                TraceCommandFifoDecodeStop("invalid-type5-window", command, wordsNeeded);
                return;
            }
            if (_fixMameCommandFifoModel &&
                _experimentMameCommandFifoDropInvalidType5Header &&
                (command & 7u) == 5u &&
                !HasCommandFifoWords(packetStart, wordsNeeded))
            {
                int validIndex = CommandFifoStorageIndex(packetStart);
                if (_cmdFifoValid[validIndex])
                {
                    _cmdFifoValid[validIndex] = false;
                    _cmdFifoValidCount = Math.Max(0, _cmdFifoValidCount - 1);
                }
                _cmdFifoDepth = Math.Max(0, _cmdFifoDepth - 1);
                _cmdFifoDepthWordsDecoded++;
                SetCommandFifoReadIndex(DecodeCommandFifoReadIndex(packetStart + 1), "drop-invalid-type5", command, wordsNeeded);
                TraceCommandFifoDecodeStop("drop-invalid-type5", command, wordsNeeded);
                continue;
            }
            if (!_fixMameCommandFifoModel && !HasCommandFifoWords(packetStart, wordsNeeded))
            {
                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "invalid-standard-window");
                TraceCommandFifoDecodeStop("invalid-standard-window", command, wordsNeeded);
                return;
            }
            if (ShouldSkipPayloadType1Packet(command, wordsNeeded, packetStart))
            {
                TraceCommandFifoPayloadType1PacketSkip(command, wordsNeeded, packetStart);
                CountCommandFifoPacketPc(command, wordsNeeded, packetStart);
                _fifoPacketCount++;
                decodedThisCall++;
                for (int i = 0; i < wordsNeeded; i++)
                {
                    int validIndex = CommandFifoReadStorageIndex(packetStart + i);
                    if (_cmdFifoValid[validIndex])
                    {
                        _cmdFifoValid[validIndex] = false;
                        _cmdFifoValidCount = Math.Max(0, _cmdFifoValidCount - 1);
                    }
                }

                _cmdFifoDepth = Math.Max(0, _cmdFifoDepth - wordsNeeded);
                _cmdFifoDepthWordsDecoded += wordsNeeded;
                SetCommandFifoReadIndex(DecodeCommandFifoReadIndex(packetStart + wordsNeeded), "skip-payload-type1", command, wordsNeeded);
                _lastDecodedCommandFifoCommand = command;
                _lastDecodedCommandFifoWords = wordsNeeded;
                _lastDecodedCommandFifoPacketStart = packetStart;
                _lastDecodedCommandFifoReadAfter = _cmdFifoReadIndex;
                continue;
            }

            _fifoBuffer.Clear();
            for (int i = 0; i < wordsNeeded; i++)
            {
                _fifoBuffer.Add(ReadCommandFifoWordAt(packetStart + i));
            }

            _cmdFifoJumped = false;
            _commandFifoPacketIssuedRenderWork = false;
            _currentCommandFifoCommand = command;
            _currentCommandFifoPacketStart = packetStart;
            _currentCommandFifoWordsNeeded = wordsNeeded;
            CountCommandFifoPacketPc(command, wordsNeeded, packetStart);
            bool packetConsumedByHandler = false;
            if (_fixMameCommandFifoModel &&
                ShouldStreamCommandFifoPacketWords(command))
            {
                SetCommandFifoReadIndex(DecodeCommandFifoReadIndex(packetStart + 1), "stream-packet-header", command, wordsNeeded);
                _cmdFifoDepth = Math.Max(0, _cmdFifoDepth - 1);
                _cmdFifoDepthWordsStreamed++;
                packetConsumedByHandler = true;
            }
            DecodeFifoPacket(command, wordsNeeded);
            _currentCommandFifoCommand = 0;
            _currentCommandFifoPacketStart = 0;
            _currentCommandFifoWordsNeeded = 0;
            bool packetDidWork = IsCommandFifoPacketWork(command);
            _fifoPacketCount++;
            decodedThisCall++;
            if (!_fixMameCommandFifoModel || !_experimentMameCommandFifoKeepDecodedValid)
            {
                for (int i = 0; i < wordsNeeded; i++)
                {
                    int validIndex = CommandFifoReadStorageIndex(packetStart + i);
                    if (_cmdFifoValid[validIndex])
                    {
                        _cmdFifoValid[validIndex] = false;
                        _cmdFifoValidCount = Math.Max(0, _cmdFifoValidCount - 1);
                    }
                }
            }
            if (!packetConsumedByHandler)
            {
                _cmdFifoDepth = Math.Max(0, _cmdFifoDepth - wordsNeeded);
                _cmdFifoDepthWordsDecoded += wordsNeeded;
            }
            TraceCommandFifoValidity("decode", CommandFifoStorageIndex(packetStart));
            if (_cmdFifoBulkDecodeRemainingWords > 0)
                _cmdFifoBulkDecodeRemainingWords = Math.Max(0, _cmdFifoBulkDecodeRemainingWords - wordsNeeded);
            if (!_cmdFifoJumped && !packetConsumedByHandler)
                SetCommandFifoReadIndex(DecodeCommandFifoReadIndex(packetStart + wordsNeeded), "packet-advance", command, wordsNeeded);
            _lastDecodedCommandFifoCommand = command;
            _lastDecodedCommandFifoWords = wordsNeeded;
            _lastDecodedCommandFifoPacketStart = packetStart;
            _lastDecodedCommandFifoReadAfter = _cmdFifoReadIndex;
            if (_fixMameCommandFifoModel &&
                _experimentMameCommandFifoOperationPendingGate &&
                _commandFifoPacketIssuedRenderWork)
            {
                _commandFifoOperationPending = true;
                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "operation-pending");
                return;
            }
            if (_fixMameCommandFifoModel && _experimentMameCommandFifoYieldOnRenderWork && _commandFifoPacketIssuedRenderWork)
            {
                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "yield-render");
                return;
            }
            if (_fixMameCommandFifoModel && _experimentMameCommandFifoYieldOnWork && packetDidWork)
            {
                CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, "yield-work");
                return;
            }
        }
        CountCommandFifoDecodeCallPc(decodeCallPc, decodedThisCall, decodeCallStartReadIndex, decodeCallStartDepth, _cmdFifoReadIndex, decodeCallFirstCommand, decodeCallLastCommand, decodeCallTypeMask, guard >= 2048 ? "guard" : "ready-empty");
        }
        finally
        {
            _commandFifoDecodeTrigger = previousTrigger;
            _decodingCommandFifo = false;
        }
    }

    private void DecodeCommandFifoPacketsIfNotPending(string trigger = "direct")
    {
        if (IsCommandFifoOperationPending())
            return;

        DecodeCommandFifoPackets(trigger);
    }

    private bool TryDropInvalidCommandFifoPacketHeader(int packetStart, uint command, int wordsNeeded, string reason)
    {
        if (wordsNeeded <= 1)
            return false;

        int validIndex = CommandFifoStorageIndex(packetStart);
        if (_cmdFifoValid[validIndex])
        {
            _cmdFifoValid[validIndex] = false;
            _cmdFifoValidCount = Math.Max(0, _cmdFifoValidCount - 1);
        }

        _cmdFifoDepth = Math.Max(0, _cmdFifoDepth - 1);
        _cmdFifoDepthWordsDecoded++;
        SetCommandFifoReadIndex(DecodeCommandFifoReadIndex(packetStart + 1), reason, command, wordsNeeded);
        TraceCommandFifoDecodeStop(reason, command, wordsNeeded);
        return true;
    }

    private static bool IsImplausibleCommandFifoPacket(uint command, int wordsNeeded)
    {
        uint type = command & 7u;
        if (type == 0u)
        {
            uint function = (command >> 3) & 7u;
            // Voodoo 2 packet type 0 reserves bits 31:29 and only defines
            // NOP/JSR/RET/JMP LOCAL/JMP AGP functions. Vertex coordinates such
            // as 0x44000000 otherwise look like one-word NOP packets and can
            // become false FIFO resynchronization targets.
            return (command >> 29) != 0u || function > 4u;
        }
        if (type == 1u)
            return (command >> 16) > 1024u || wordsNeeded > 1025;
        if (type == 2u)
            return wordsNeeded > 30;
        if (type == 3u)
        {
            uint code = (command >> 3) & 7u;
            uint vertices = (command >> 6) & 0x0fu;
            const uint reservedMask = (3u << 26) | (0x0fu << 18);
            return (command & reservedMask) != 0u || code > 2u || vertices == 0u;
        }
        if (type == 4u)
            return wordsNeeded > 22;
        if (type == 5u)
        {
            uint space = command >> 30;
            uint count = (command >> 3) & 0x7ffffu;
            return space == 2u && count > 0x10000u;
        }
        return false;
    }

    private bool ShouldSkipPayloadType1Packet(uint command, int wordsNeeded, int packetStart)
    {
        if (!_experimentSkipPayloadType1Packets ||
            (command & 7u) != 1u ||
            _commandFifoDecodeTrigger != "bulk-end" ||
            !IsImplausibleCommandFifoPacket(command, wordsNeeded))
        {
            return false;
        }
        if (_experimentSkipPayloadType1PacketsFilter.Length != 0 &&
            !_experimentSkipPayloadType1PacketsFilter.Contains(command))
        {
            return false;
        }

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if ((pc & 0xffffffffUL) != 0x800fe5d4UL)
            return false;

        int storageIndex = CommandFifoReadStorageIndex(packetStart);
        return _cmdFifoValid[storageIndex] &&
               _cmdFifoStorageLastWriteSource[storageIndex] == CmdFifoStorageWriteSourceFifo &&
               (_cmdFifoStorageLastWritePc[storageIndex] & 0xffffffffUL) == 0x800fe5d4UL;
    }

    private void TraceCommandFifoPayloadType1PacketSkip(uint command, int wordsNeeded, int packetStart)
    {
        _commandFifoPayloadType1PacketSkipCount++;
        if (_commandFifoPayloadType1PacketSkipCount > _experimentSkipPayloadType1PacketsTraceLimit)
            return;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        int storageIndex = CommandFifoReadStorageIndex(packetStart);
        int validWindowLimit = Math.Min(wordsNeeded, 64);
        int validWindowWords = CountCommandFifoValidWindowWords(packetStart, validWindowLimit);
        string bulkPosition = FormatCommandFifoBulkPacketPosition(packetStart).TrimStart();
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-PAYLOAD-TYPE1-SKIP] n={_commandFifoPayloadType1PacketSkipCount} " +
            $"cmd=0x{command:x8} words={wordsNeeded} packet=0x{packetStart * 4:x8} rd=0x{_cmdFifoReadIndex * 4:x8} " +
            $"target=0x{(command >> 3) & 0xfffu:x3} count={command >> 16} " +
            $"storage=0x{storageIndex * 4:x5} validWindow={validWindowWords}/{validWindowLimit} " +
            $"depth={_cmdFifoDepth} holes={_cmdFifoHoles} valid={_cmdFifoValidCount} " +
            $"last=0x{_cmdFifoStorageLastWriteValue[storageIndex]:x8}/pc0x{_cmdFifoStorageLastWritePc[storageIndex]:x16} " +
            $"bulk={bulkPosition} trigger={_commandFifoDecodeTrigger}{pcStatus}");
    }

    private bool ShouldGateCollapsedBulkPayloadChain(uint command, int wordsNeeded, int packetStart, bool implausiblePacket)
    {
        if (!_experimentCommandFifoBulkGateCollapsedPayloadChain ||
            _cmdFifoAddressMin != -4 ||
            _cmdFifoAddressMax != -4 ||
            !_cmdFifoBulkSawWrite)
        {
            return false;
        }

        int storageIndex = CommandFifoReadStorageIndex(packetStart);
        if (!_cmdFifoValid[storageIndex] ||
            _cmdFifoStorageLastWriteSource[storageIndex] != CmdFifoStorageWriteSourceFifo)
        {
            return false;
        }

        uint type = command & 7u;
        if (type == 1u && implausiblePacket)
            return _commandFifoDecodeTrigger is "bulk-end" or "write";

        return _commandFifoDecodeTrigger == "bulk-end" &&
               IsCommandFifoIndexInsideBulkWrite(packetStart) &&
               wordsNeeded == 1 &&
               (command == 0 || type > 5u);
    }

    private bool ShouldGateImplausibleType1OutsideBulkWindow(uint command, int wordsNeeded, int packetStart, bool implausiblePacket, out string bulkPosition)
    {
        bulkPosition = "";
        return _experimentGateImplausibleType1OutsideBulkWindow &&
               IsImplausibleType1OutsideBulkWindowCandidate(
                   command,
                   packetStart,
                   implausiblePacket,
                   _experimentGateImplausibleType1OutsideBulkWindowCommands,
                   out bulkPosition);
    }

    private bool ShouldDropImplausibleType1OutsideBulkWindow(uint command, int wordsNeeded, int packetStart, bool implausiblePacket, out string bulkPosition)
    {
        bulkPosition = "";
        return wordsNeeded > 1 &&
               _experimentDropImplausibleType1OutsideBulkWindow &&
               IsImplausibleType1OutsideBulkWindowCandidate(
                   command,
                   packetStart,
                   implausiblePacket,
                   _experimentDropImplausibleType1OutsideBulkWindowCommands,
                   out bulkPosition);
    }

    private bool IsImplausibleType1OutsideBulkWindowCandidate(uint command, int packetStart, bool implausiblePacket, ulong[] commandFilter, out string bulkPosition)
    {
        bulkPosition = "";
        if (!implausiblePacket ||
            (command & 7u) != 1u ||
            _commandFifoDecodeTrigger is not ("bulk-end" or "write") ||
            !_cmdFifoBulkSawWrite ||
            _cmdFifoBulkWriteWordCount <= 0)
        {
            return false;
        }
        if (commandFilter.Length != 0 && !commandFilter.Contains(command))
            return false;

        bulkPosition = FormatCommandFifoBulkPacketPosition(packetStart).TrimStart();
        if (!bulkPosition.StartsWith("scan=outside", StringComparison.Ordinal))
            return false;

        int storageIndex = CommandFifoReadStorageIndex(packetStart);
        return _cmdFifoValid[storageIndex] &&
               _cmdFifoStorageLastWriteSource[storageIndex] == CmdFifoStorageWriteSourceFifo &&
               (_cmdFifoStorageLastWritePc[storageIndex] & 0xffffffffUL) == 0x800fe5d4UL;
    }

