    {
        _commandFifoImplausibleType1OutsideBulkWindowGateCount++;
        if (_commandFifoImplausibleType1OutsideBulkWindowGateCount > _experimentGateImplausibleType1OutsideBulkWindowTraceLimit)
            return;

