    private void TraceCommandFifoImplausiblePacket(uint command, int wordsNeeded, int packetStart)
    {
        if (!_traceCommandFifoImplausiblePackets)
        {
            return;
        }

        uint type = command & 7u;
        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if (_traceCommandFifoImplausiblePacketTypes.Length != 0 &&
            !_traceCommandFifoImplausiblePacketTypes.Contains(type))
        {
            return;
        }
        if (_traceCommandFifoImplausiblePacketCommands.Length != 0 &&
            !_traceCommandFifoImplausiblePacketCommands.Contains(command))
        {
            return;
        }
        if (_traceCommandFifoImplausiblePacketPcs.Length != 0 &&
            !_traceCommandFifoImplausiblePacketPcs.Contains(pc))
        {
            return;
        }
        if (_commandFifoImplausiblePacketTraceCount >= _traceCommandFifoImplausiblePacketsLimit)
        {
            return;
        }

        _commandFifoImplausiblePacketTraceCount++;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        string packetStatus = type switch
        {
            1u => $" target=0x{(command >> 3) & 0xfffu:x3} count={command >> 16} inc={(((command >> 15) & 1u) != 0 ? 1 : 0)}",
            5u => $" space={command >> 30} count={(command >> 3) & 0x7ffffu}",
            _ => ""
        };
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-CMDFIFO-IMPLAUSIBLE] n={_commandFifoImplausiblePacketTraceCount} " +
            $"cmd=0x{command:x8} type={type} words={wordsNeeded}{packetStatus} " +
            $"packetStart=0x{packetStart * 4:x8} rd=0x{_cmdFifoReadIndex * 4:x8} " +
            $"storage=0x{CommandFifoReadStorageIndex(packetStart) * 4:x5} readStorage=0x{CommandFifoReadStorageIndex(_cmdFifoReadIndex) * 4:x5} " +
            $"validWindow={CountCommandFifoValidWindowWords(packetStart, Math.Min(wordsNeeded, 64))}/64 " +
            $"depth={_cmdFifoDepth} holes={_cmdFifoHoles} valid={_cmdFifoValidCount} " +
            $"amin=0x{_cmdFifoAddressMin:x8} amax=0x{_cmdFifoAddressMax:x8} trigger={_commandFifoDecodeTrigger} " +
            $"w0={FormatCommandFifoStorageWordDebug(packetStart)} " +
            $"w1={FormatCommandFifoStorageWordDebug(packetStart + 1)} " +
            $"w2={FormatCommandFifoStorageWordDebug(packetStart + 2)}{pcStatus}");
    }

    private bool IsCommandFifoPacketReady()
    {
        if (!_fixMameCommandFifoModel)
        {
            int storageIndex = CommandFifoStorageIndex(_cmdFifoReadIndex);
            if (!_cmdFifoValid[storageIndex])
                return false;
            if (!_experimentStandardCommandFifoGenerations)
                return true;

            if (_cmdFifoStorageLogicalIndex[storageIndex] == _cmdFifoReadIndex &&
                _cmdFifoStoragePacketHeader[storageIndex])
            {
                if (IsStandardCommandFifoPacketComplete(_cmdFifoReadIndex))
                    return true;

                // The Vegas producer writes a packet header before its body. Once the
                // read head owns a header from the current logical generation, preserve
                // FIFO ordering and wait for the remaining words instead of skipping to
                // a later complete packet. Resync is only appropriate when the current
                // slot cannot be the head of this generation.
                return false;
            }

            return TryResyncStandardCommandFifoToNextPacket();
        }

        if (_cmdFifoDepth <= 0)
        {
            CountCommandFifoReadyPc(false, "depth0");
            return false;
        }

        if (_experimentMameCommandFifoReadyValidPacketWindow)
        {
            uint command = PeekCommandFifoWord();
            int wordsNeeded = GetFifoPacketWordsNeeded(command);
            if (IsKnownGauntletRuntimeMisalignedFifoWord(command, wordsNeeded))
                wordsNeeded = 1;
            if (wordsNeeded <= 0)
                wordsNeeded = 1;
            if (!HasCommandFifoWords(_cmdFifoReadIndex, wordsNeeded))
            {
                CountCommandFifoReadyPc(false, "packet-window");
                return false;
            }
        }

        if (_experimentMameCommandFifoRequireReadInAddressWindow &&
            _cmdFifoAddressMin >= _cmdFifoRamBase &&
            !IsMameCommandFifoReadInsideAddressWindow())
        {
            if (_experimentMameCommandFifoAccumulateAddressWindow &&
                TryResyncMameCommandFifoReadToAddressMin("read-window-resync"))
            {
                CountCommandFifoReadyPc(true, "read-window-resync");
                return true;
            }
            TraceCommandFifoDecodeStop("read-outside-window", PeekCommandFifoWord(), 1);
            CountCommandFifoReadyPc(false, "read-window");
            return false;
        }

        if (_experimentMameCommandFifoRequireStorageGeneration &&
            !IsCommandFifoWordValidForRead(_cmdFifoReadIndex))
        {
            TraceCommandFifoDecodeStop("storage-generation", PeekCommandFifoWord(), 1);
            CountCommandFifoReadyPc(false, "storage-generation");
            return false;
        }

        if ((_experimentMameCommandFifoSkipWrapGapInvalidRead ||
             _experimentMameCommandFifoConsumeWrapGapInvalidRead) &&
            !IsCommandFifoWordValidForRead(_cmdFifoReadIndex))
        {
            int readStorage = CommandFifoStorageIndex(_cmdFifoReadIndex);
            int gapToBase = CmdFifoWords - readStorage;
            if (readStorage != 0 &&
                gapToBase <= 64 &&
                IsCommandFifoWordValidForRead(_cmdFifoReadIndex + gapToBase))
            {
                SetCommandFifoReadIndex(DecodeCommandFifoReadIndex(_cmdFifoReadIndex + gapToBase), "ready-skip-gap");
                if (_experimentMameCommandFifoConsumeWrapGapInvalidRead)
                    _cmdFifoDepth = Math.Max(0, _cmdFifoDepth - gapToBase);
            }
        }

        if (_experimentMameCommandFifoSkipInvalidStorage)
        {
            int skipped = 0;
            while (_cmdFifoDepth > 0 && !IsCommandFifoWordValidForRead(_cmdFifoReadIndex) && skipped++ < CommandFifoStorageWords())
            {
                SetCommandFifoReadIndex(DecodeCommandFifoReadIndex(_cmdFifoReadIndex + 1), "ready-skip-invalid");
                _cmdFifoDepth--;
            }
            if (_cmdFifoDepth <= 0 || !IsCommandFifoWordValidForRead(_cmdFifoReadIndex))
            {
                TraceCommandFifoDecodeStop("skip-invalid-storage", PeekCommandFifoWord(), 1);
                CountCommandFifoReadyPc(false, "skip-invalid");
                return false;
            }
        }

        if (_experimentMameCommandFifoRequireValidStorage && !IsCommandFifoWordValidForRead(_cmdFifoReadIndex))
        {
            if (_experimentMameCommandFifoResyncInvalidStorageToAddressMin && _cmdFifoAddressMin >= _cmdFifoRamBase)
            {
                int addressMinIndex = DecodeCommandFifoReadIndex(_cmdFifoAddressMin >> 2);
                if (IsCommandFifoWordValidForRead(addressMinIndex))
                {
                    TraceCommandFifoDecodeStop("invalid-storage-resync-amin", PeekCommandFifoWord(), 1);
                    SetCommandFifoReadIndex(addressMinIndex, "ready-invalid-storage-amin");
                    return true;
                }
            }

            TraceCommandFifoDecodeStop("invalid-storage", PeekCommandFifoWord(), 1);
            CountCommandFifoReadyPc(false, "invalid-storage");
            return false;
        }

        CountCommandFifoReadyPc(true, "ready");
        return true;
    }

    private bool IsStandardCommandFifoPacketComplete(int headerLogicalIndex)
    {
        int headerStorage = CommandFifoStorageIndex(headerLogicalIndex);
        if (!_cmdFifoValid[headerStorage] ||
            !_cmdFifoStoragePacketHeader[headerStorage] ||
            _cmdFifoStorageLogicalIndex[headerStorage] != headerLogicalIndex)
            return false;

        uint command = _cmdFifoRam[headerStorage];
        int wordsNeeded = Math.Max(1, GetFifoPacketWordsNeeded(command));
        if ((command & 7u) > 5u ||
            IsImplausibleCommandFifoPacket(command, wordsNeeded) ||
            wordsNeeded > CmdFifoWords)
            return false;

        int packetEnd = _cmdFifoStoragePacketEndLogicalIndex[headerStorage];
        if (packetEnd != headerLogicalIndex + wordsNeeded - 1)
            return false;
        for (int logical = headerLogicalIndex; logical <= packetEnd; logical++)
        {
            int storage = CommandFifoStorageIndex(logical);
            if (!_cmdFifoValid[storage] || _cmdFifoStorageLogicalIndex[storage] != logical)
                return false;
        }
        return true;
    }

    private bool TryResyncStandardCommandFifoToNextPacket()
    {
        foreach (int candidate in _cmdFifoCompletePacketHeaders.GetViewBetween(_cmdFifoReadIndex + 1, int.MaxValue))
        {
            if (IsStandardCommandFifoPacketComplete(candidate))
            {
                SetCommandFifoReadIndex(candidate, "standard-generation-next-header");
                _cmdFifoPacketMapResyncs++;
                return true;
            }
        }
        _cmdFifoPacketMapResyncMisses++;
        return false;
    }

    private bool IsMameCommandFifoReadInsideAddressWindow()
        => IsMameCommandFifoWordInsideAddressWindow(_cmdFifoReadIndex);

    private bool TryResyncMameCommandFifoReadToAddressMin(string reason)
    {
        if (_cmdFifoAddressMin < _cmdFifoRamBase)
            return false;

        int addressMinIndex = DecodeCommandFifoReadIndex(_cmdFifoAddressMin >> 2);
        if (addressMinIndex == _cmdFifoReadIndex)
            return false;
        if (!IsCommandFifoWordValidForRead(addressMinIndex))
            return false;

        TraceCommandFifoDecodeStop(reason, PeekCommandFifoWord(), 1);
        SetCommandFifoReadIndex(addressMinIndex, reason);
        return true;
    }

    private bool IsMameCommandFifoPacketInsideAddressWindow(int start, int wordsNeeded)
    {
        for (int i = 0; i < wordsNeeded; i++)
        {
            if (!IsMameCommandFifoWordInsideAddressWindow(start + i))
                return false;
        }

        return true;
    }

    private bool IsMameCommandFifoWordInsideAddressWindow(int wordIndex)
    {
        int readByte = wordIndex * 4;
        if (_cmdFifoAddressMin <= _cmdFifoAddressMax)
            return readByte >= _cmdFifoAddressMin && readByte <= _cmdFifoAddressMax;

        int readStorageByte = CommandFifoStorageIndex(wordIndex) * 4;
        int minStorageByte = CommandFifoStorageIndex(_cmdFifoAddressMin >> 2) * 4;
        int maxStorageByte = CommandFifoStorageIndex(_cmdFifoAddressMax >> 2) * 4;
        return readStorageByte >= minStorageByte || readStorageByte <= maxStorageByte;
    }

    private bool TryResyncMameCommandFifoOnPartialType5(uint command, int packetStart, int wordsNeeded)
    {
        if (!_experimentMameCommandFifoResyncAddressMinOnPartialType5 ||
            !IsType5TexturePacketHeader(command) ||
            _cmdFifoAddressMin < _cmdFifoRamBase)
        {
            return false;
        }

        int addressMinIndex = _cmdFifoAddressMin >> 2;
        if (CommandFifoStorageIndex(addressMinIndex) == CommandFifoStorageIndex(packetStart))
            return false;

        TraceCommandFifoDecodeStop("partial-type5-resync-amin", command, wordsNeeded);
        SetCommandFifoReadIndex(DecodeCommandFifoReadIndex(addressMinIndex), "partial-type5-resync-amin", command, wordsNeeded);
        return true;
    }

    private bool TryTruncateMameCommandFifoPartialType4(uint command, int wordsNeeded, out int truncatedWordsNeeded)
    {
        truncatedWordsNeeded = wordsNeeded;
        if (!_experimentMameCommandFifoTruncatePartialType4 ||
            (command & 7u) != 4u ||
            _cmdFifoDepth <= 1 ||
            _cmdFifoDepth >= wordsNeeded)
        {
            return false;
        }

        truncatedWordsNeeded = _cmdFifoDepth;
        TraceCommandFifoDecodeStop("partial-type4-truncate", command, wordsNeeded);
        return true;
    }

    private int DecodeCommandFifoReadIndex(int value)
    {
        if (_fixMameCommandFifoModel && _experimentMameCommandFifoWrapReadToWindow)
            return WrapCommandFifoReadIndexToWindow(value);
        return ((_fixMameCommandFifoModel && !_experimentMameCommandFifoMaskReadIndex) ||
                (!_fixMameCommandFifoModel && _experimentStandardCommandFifoGenerations))
            ? value
            : CommandFifoStorageIndex(value);
    }

    private uint ReadCommandFifoWordAt(int logicalIndex)
        => _cmdFifoRam[CommandFifoReadStorageIndex(logicalIndex)];

    private int CommandFifoReadStorageIndex(int logicalIndex)
        => CommandFifoStorageIndex(NormalizeCommandFifoReadIndex(logicalIndex));

    private int NormalizeCommandFifoReadIndex(int logicalIndex)
        => _fixMameCommandFifoModel && _experimentMameCommandFifoWrapReadToWindow
            ? WrapCommandFifoReadIndexToWindow(logicalIndex)
            : logicalIndex;

    private int WrapCommandFifoReadIndexToWindow(int value)
    {
        int windowStart = Math.Max(0, _cmdFifoRamBase >> 2);
        int windowEnd = Math.Max(windowStart + 1, _cmdFifoRamEnd >> 2);
        int windowWords = windowEnd - windowStart;
        int relative = value - windowStart;
        relative %= windowWords;
        if (relative < 0)
            relative += windowWords;
        return windowStart + relative;
    }

    private int CommandFifoStorageIndex(int value)
        => value & CommandFifoStorageMask();

    private int CommandFifoStorageMask()
        => _fixMameCommandFifoModel && _experimentMameCommandFifoFramebufferStorage
            ? CmdFifoFramebufferMask
            : CmdFifoMask;

    private int CommandFifoStorageWords()
        => _fixMameCommandFifoModel && _experimentMameCommandFifoFramebufferStorage
            ? CmdFifoFramebufferWords
            : CmdFifoWords;

    private string FormatCommandFifoStorageWordDebug(int logicalIndex)
    {
        int readIndex = NormalizeCommandFifoReadIndex(logicalIndex);
        return FormatCommandFifoStorageIndexDebug(readIndex);
    }

    private string FormatCommandFifoStorageIndexDebug(int storageIndex)
    {
        storageIndex = CommandFifoStorageIndex(storageIndex);
        string lastWriter = FormatCommandFifoStorageLastWriter(storageIndex);
        return
            $"0x{storageIndex * 4:x5}:v{(_cmdFifoValid[storageIndex] ? 1 : 0)}/" +
            $"lg0x{_cmdFifoStorageLogicalIndex[storageIndex] * 4:x8}/" +
            $"cur0x{_cmdFifoRam[storageIndex]:x8}/{lastWriter}";
    }

    private string FormatCommandFifoStorageLastWriter(int storageIndex)
    {
        long sequence = _cmdFifoStorageLastWriteSequence[storageIndex];
        if (sequence == 0)
            return "last=none";

        ulong pc = _cmdFifoStorageLastWritePc[storageIndex];
        string pcStatus = pc != 0 ? $"/pc0x{pc:x16}" : "/pc0";
        string bulkWriteSource = _cmdFifoStorageBulkWriteSources.TryGetValue(storageIndex, out CommandFifoStorageBulkWriteSource source)
            ? $"/{FormatCommandFifoStorageBulkWriteSource(source)}"
            : "";
        return
            $"last={FormatCommandFifoStorageWriteSource(_cmdFifoStorageLastWriteSource[storageIndex])}/" +
            $"seq{sequence}/lg0x{_cmdFifoStorageLastWriteLogicalIndex[storageIndex] * 4:x8}/" +
            $"addr0x{_cmdFifoStorageLastWriteAddress[storageIndex]:x8}/" +
            $"val0x{_cmdFifoStorageLastWriteValue[storageIndex]:x8}{pcStatus}{bulkWriteSource}";
    }

    private static string FormatCommandFifoStorageBulkWriteSource(CommandFifoStorageBulkWriteSource source)
    {
        string word = source.Word == uint.MaxValue
            ? "hdr"
            : source.Word == uint.MaxValue - 1U
            ? "target"
            : $"w{source.Word}";
        return
            $"bulkSrc0x{source.Source:x16}/base0x{source.SourceBase:x8}/pktSrc0x{source.PacketSourceAddress:x8}/" +
            $"p{source.Packet}/idx{source.Index}-{source.Limit}/{word}-{source.PayloadWords}";
    }

    private static string FormatCommandFifoStorageWriteSource(byte source)
        => source switch
        {
            CmdFifoStorageWriteSourceFifo => "fifo",
            CmdFifoStorageWriteSourceLfbMirror => "lfb",
            CmdFifoStorageWriteSourceType5Space0 => "type5s0",
            _ => "unknown"
        };

    private void TraceCommandFifoDecodeStop(string reason, uint command, int wordsNeeded)
    {
        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        _lastCommandFifoDecodeStopReason = reason;
        _lastCommandFifoDecodeStopCommand = command;
        _lastCommandFifoDecodeStopWordsNeeded = wordsNeeded;
        _lastCommandFifoDecodeStopDepth = _cmdFifoDepth;
        _lastCommandFifoDecodeStopReadIndex = _cmdFifoReadIndex;
        _lastCommandFifoDecodeStopStorageIndex = CommandFifoReadStorageIndex(_cmdFifoReadIndex);
        _lastCommandFifoDecodeStopReadValid = _cmdFifoValid[_lastCommandFifoDecodeStopStorageIndex];
        _lastCommandFifoDecodeStopStoredLogicalIndex = _cmdFifoStorageLogicalIndex[_lastCommandFifoDecodeStopStorageIndex];
        _lastCommandFifoDecodeStopValidWindowWords =
            CountCommandFifoValidWindowWords(_cmdFifoReadIndex, Math.Min(wordsNeeded, 64));
        _lastCommandFifoDecodeStopNext1 = ReadCommandFifoWordAt(_cmdFifoReadIndex + 1);
        _lastCommandFifoDecodeStopNext2 = ReadCommandFifoWordAt(_cmdFifoReadIndex + 2);
        _lastCommandFifoDecodeStopPc = pc;
        _lastCommandFifoDecodeStopTrigger = _commandFifoDecodeTrigger;
        if (_traceCommandFifoModel)
        {
            _lastCommandFifoDecodeStopWord0Debug = FormatCommandFifoStorageWordDebug(_cmdFifoReadIndex);
            _lastCommandFifoDecodeStopWord1Debug = FormatCommandFifoStorageWordDebug(_cmdFifoReadIndex + 1);
        }
        else
        {
            _lastCommandFifoDecodeStopWord0Debug = "";
            _lastCommandFifoDecodeStopWord1Debug = "";
        }
        _commandFifoDecodeStopCount++;
        TraceCommandFifoStopWindow(reason, command, wordsNeeded);

        if (!_traceCommandFifoModel)
            return;

        if (_traceCommandFifoModelPcs.Length != 0 && !_traceCommandFifoModelPcs.Contains(pc))
            return;
        if (_traceCommandFifoModelCommands.Length != 0 && !_traceCommandFifoModelCommands.Contains(command))
            return;
        if (_commandFifoModelStallTraceCount++ >= 160)
            return;

        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        int readStorage = CommandFifoReadStorageIndex(_cmdFifoReadIndex);
        bool readValid = _cmdFifoValid[readStorage];
        int storedLogicalIndex = _cmdFifoStorageLogicalIndex[readStorage];
        int validWindowWords = CountCommandFifoValidWindowWords(_cmdFifoReadIndex, Math.Min(wordsNeeded, 64));
        uint next1 = ReadCommandFifoWordAt(_cmdFifoReadIndex + 1);
        uint next2 = ReadCommandFifoWordAt(_cmdFifoReadIndex + 2);
        string word0 = FormatCommandFifoStorageWordDebug(_cmdFifoReadIndex);
        string word1 = FormatCommandFifoStorageWordDebug(_cmdFifoReadIndex + 1);
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-CMDFIFO] stop reason={reason} cmd=0x{command:x8} type={command & 7u} " +
            $"words={wordsNeeded} rd=0x{_cmdFifoReadIndex * 4:x8} storage=0x{readStorage * 4:x5} " +
            $"readValid={(readValid ? 1 : 0)} storedLogical=0x{storedLogicalIndex * 4:x8} " +
            $"validWindow={validWindowWords}/{Math.Min(wordsNeeded, 64)} " +
            $"next=0x{next1:x8}/0x{next2:x8} depth={_cmdFifoDepth} holes={_cmdFifoHoles} valid={_cmdFifoValidCount} " +
            $"w0={word0} w1={word1} " +
            $"amin=0x{_cmdFifoAddressMin:x8} amax=0x{_cmdFifoAddressMax:x8} trigger={_commandFifoDecodeTrigger} " +
            $"fifoPackets={_fifoPacketCount} drawPackets={_fifoDrawPacketCount}{pcStatus}");
    }

    private void TraceCommandFifoStopWindow(string reason, uint command, int wordsNeeded)
    {
        if (!_traceCommandFifoStopWindow)
            return;
        if (_traceCommandFifoStopWindowCommands.Length != 0 && !_traceCommandFifoStopWindowCommands.Contains(command))
            return;
        if (_commandFifoStopWindowTraceCount++ >= _traceCommandFifoStopWindowLimit)
            return;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        int before = Math.Clamp(_traceCommandFifoStopWindowBefore, 0, 32);
        int after = Math.Clamp(_traceCommandFifoStopWindowAfter, 1, 256);
        int validLimit = Math.Min(Math.Max(wordsNeeded, 1), after + 1);
        int validWindowWords = CountCommandFifoValidWindowWords(_cmdFifoReadIndex, validLimit);
        int firstInvalid = validWindowWords < validLimit ? validWindowWords : -1;
        int readStorage = CommandFifoReadStorageIndex(_cmdFifoReadIndex);
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        string bulkPacket =
            _cmdFifoBulkSawWrite
                ? FormatCommandFifoBulkPacketPosition(_cmdFifoReadIndex).TrimStart()
                : "bulk=none";
        string bulkHeads =
            _cmdFifoBulkSawWrite
                ? FormatCommandFifoBulkPacketHeads(8)
                : "heads=none";
        string window = FormatCommandFifoStopWindow(_cmdFifoReadIndex, before, after, firstInvalid);

        Console.WriteLine(
            $"[GAUNTDL:VOODOO-CMDFIFO-STOP-WINDOW] reason={reason} cmd=0x{command:x8} type={command & 7u} " +
            $"words={wordsNeeded} rd=0x{_cmdFifoReadIndex * 4:x8} storage=0x{readStorage * 4:x5} " +
            $"validWindow={validWindowWords}/{validLimit} firstInvalid={firstInvalid} depth={_cmdFifoDepth} " +
            $"holes={_cmdFifoHoles} valid={_cmdFifoValidCount} trigger={_commandFifoDecodeTrigger} " +
            $"{bulkPacket} {bulkHeads}{pcStatus} window={window}");
    }

    private string FormatCommandFifoStopWindow(int readIndex, int before, int after, int firstInvalid)
    {
        StringBuilder builder = new StringBuilder();
        for (int delta = -before; delta <= after; delta++)
        {
            if (builder.Length != 0)
                builder.Append(" | ");

            int logicalIndex = readIndex + delta;
            char marker = delta == 0 ? '*' : delta == firstInvalid ? '!' : ' ';
            builder.Append(marker);
            builder.Append(delta >= 0 ? '+' : "");
            builder.Append(delta.ToString(CultureInfo.InvariantCulture));
            builder.Append(":lg0x");
            builder.Append((logicalIndex * 4).ToString("x8", CultureInfo.InvariantCulture));
            builder.Append('/');
            builder.Append(FormatCommandFifoStorageWordDebug(logicalIndex));
        }

        return builder.ToString();
    }

    private int CountCommandFifoValidWindowWords(int start, int count)
    {
        int valid = 0;
        for (int i = 0; i < count; i++)
        {
            if (!IsCommandFifoWordValidForRead(start + i))
                break;
            valid++;
        }

        return valid;
    }

    private int InvalidateCommandFifoWords(int start, int count)
    {
        int invalidated = 0;
        for (int i = 0; i < count; i++)
        {
            int validIndex = CommandFifoReadStorageIndex(start + i);
            if (!_cmdFifoValid[validIndex])
                continue;

            _cmdFifoValid[validIndex] = false;
            _cmdFifoValidCount = Math.Max(0, _cmdFifoValidCount - 1);
            _cmdFifoDepth = Math.Max(0, _cmdFifoDepth - 1);
            invalidated++;
        }

        return invalidated;
    }

    private bool HasCommandFifoWords(int start, int count)
    {
        for (int i = 0; i < count; i++)
        {
            if (!IsCommandFifoWordValidForRead(start + i))
                return false;
        }

        return true;
    }

    private bool IsCommandFifoWordValidForRead(int logicalIndex)
    {
        int readIndex = NormalizeCommandFifoReadIndex(logicalIndex);
        int storageIndex = CommandFifoStorageIndex(readIndex);
        if (!_cmdFifoValid[storageIndex])
            return false;
        return !_fixMameCommandFifoModel ||
               !_experimentMameCommandFifoRequireStorageGeneration ||
               _cmdFifoStorageLogicalIndex[storageIndex] == readIndex;
    }

    private uint ReadCommandFifoStreamingWord()
    {
        uint value = ReadCommandFifoWordAt(_cmdFifoReadIndex);
        SetCommandFifoReadIndex(DecodeCommandFifoReadIndex(_cmdFifoReadIndex + 1), "stream-word");
        _cmdFifoDepth = Math.Max(0, _cmdFifoDepth - 1);
        _cmdFifoDepthWordsStreamed++;
        return value;
    }

    private bool ShouldStreamCommandFifoPacketWords(uint command)
        => _experimentMameCommandFifoStreamPacketWords
            ? (command & 7u) is 1u or 2u or 3u or 4u or 5u
            : _experimentMameCommandFifoType5Streaming && (command & 7u) == 5u;

    private static bool IsCommandFifoPacketWork(uint command)
        => (command & 7u) is 1u or 2u or 3u or 4u or 5u;

    private void DecodeFifoPacket(uint command, int wordsNeeded)
    {
        _fifoPacketTypeCounts[command & 7u]++;
        TraceOddFifoPacket(command, wordsNeeded);
        RecordInterestingFifoEvent(command, wordsNeeded);
        if (IsKnownGauntletRuntimeNoopFifoPacket(command, wordsNeeded))
            return;

        switch (command & 7u)
        {
            case 0:
                DecodeFifoType0(command);
                break;
            case 1:
                DecodeFifoType1(command);
                break;
            case 2:
                DecodeFifoType2(command);
                break;
            case 3:
                MarkCommandFifoRenderWork();
                _fifoDrawPacketCount++;
                DecodeFifoType3(command, wordsNeeded);
                break;
            case 4:
                DecodeFifoType4(command);
                break;
            case 5:
                DecodeFifoType5(command, wordsNeeded);
                break;
        }
    }

    private void TraceOddFifoPacket(uint command, int wordsNeeded)
    {
        uint type = command & 7u;
        if (!_traceOddFifoPackets || type is not (2u or 6u or 7u) || _oddFifoPacketTraceCount++ >= 96)
            return;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        uint w1 = _fifoBuffer.Count > 1 ? _fifoBuffer[1] : 0;
        uint w2 = _fifoBuffer.Count > 2 ? _fifoBuffer[2] : 0;
        uint w3 = _fifoBuffer.Count > 3 ? _fifoBuffer[3] : 0;
        uint w4 = _fifoBuffer.Count > 4 ? _fifoBuffer[4] : 0;
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-ODD-FIFO] n={_oddFifoPacketTraceCount} type={type} " +
            $"cmd=0x{command:x8} words={wordsNeeded} rd=0x{_cmdFifoReadIndex:x4} " +
            $"fifoPackets={_fifoPacketCount} drawPackets={_fifoDrawPacketCount} " +
            $"w=0x{w1:x8}/0x{w2:x8}/0x{w3:x8}/0x{w4:x8} " +
            $"mame={(_fixMameCommandFifoModel ? 1 : 0)} depth={_cmdFifoDepth} holes={_cmdFifoHoles} " +
            $"base=0x{_cmdFifoRamBase:x5} amin=0x{_cmdFifoAddressMin:x8} amax=0x{_cmdFifoAddressMax:x8} " +
            $"fbz=0x{_registers[RegFbzMode]:x8} lfb=0x{_registers[RegLfbMode]:x8} " +
            $"tmode=0x{ReadTextureRegister(RegTextureMode):x8} tlod=0x{ReadTextureRegister(RegTextureLod):x8} " +
            $"tbase=0x{ReadTextureRegister(RegTextureBaseAddr):x8}{pcStatus}");
    }

    private bool IsKnownGauntletRuntimeNoopFifoPacket(uint command, int wordsNeeded)
        => command == 0x00010241U &&
           wordsNeeded == 2 &&
           _fifoBuffer.Count >= 2 &&
           _fifoBuffer[1] == 0 &&
           _registers[0x48] == 0;

    private bool IsKnownGauntletRuntimeMisalignedFifoWord(uint command, int wordsNeeded)
        => command == _registers[0x41] &&
           command == 0x0c482435U &&
           (command & 7u) == 5u &&
           wordsNeeded > 0x10000;

    private void DecodeFifoType0(uint command)
    {
        int function = (int)((command >> 3) & 7u);
        int target = (int)((command >> 6) & 0x7fffffu);
        int readBefore = _cmdFifoReadIndex;
        int readAfter = readBefore;
        if (function == 3)
        {
            readAfter = DecodeCommandFifoLocalJumpTarget(target);
            SetCommandFifoReadIndex(readAfter, "type0-local-jump", command, 1);
            _cmdFifoJumped = true;
            _cmdFifoLocalJumpCount++;
        }

        TraceType0Packet(command, function, target, readBefore, readAfter);
    }

    private int DecodeCommandFifoLocalJumpTarget(int target)
    {
        if (!_fixMameCommandFifoModel && _experimentStandardCommandFifoGenerations)
        {
            int currentStorage = CommandFifoStorageIndex(_cmdFifoReadIndex);
            int generationBase = _cmdFifoReadIndex & ~CmdFifoMask;
            int targetStorage = CommandFifoStorageIndex(target);
            if (targetStorage < currentStorage && currentStorage - targetStorage > CmdFifoWords / 2)
                generationBase += CmdFifoWords;
            return generationBase + targetStorage;
        }

        // MAME builds a byte target from these bits and divides back to a word index.
        int wordTarget = target;
        return _fixMameCommandFifoModel && _experimentMameCommandFifoMaskLocalJump
            ? CommandFifoStorageIndex(wordTarget)
            : DecodeCommandFifoReadIndex(wordTarget);
    }

    private void TraceType0Packet(uint command, int function, int target, int readBefore, int readAfter)
    {
        if (!_traceType0Packets || (_traceType0JumpsOnly && function != 3) || _type0PacketTraceCount++ >= _traceType0PacketsLimit)
            return;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-TYPE0] n={_type0PacketTraceCount} cmd=0x{command:x8} fn={function} " +
            $"target=0x{target:x6} rdBefore=0x{readBefore * 4:x8} rdAfter=0x{readAfter * 4:x8} " +
            $"storageBefore=0x{CommandFifoStorageIndex(readBefore) * 4:x5} storageAfter=0x{CommandFifoStorageIndex(readAfter) * 4:x5} " +
            $"mame={(_fixMameCommandFifoModel ? 1 : 0)} depth={_cmdFifoDepth} holes={_cmdFifoHoles} " +
            $"base=0x{_cmdFifoRamBase:x5} amin=0x{_cmdFifoAddressMin:x8} amax=0x{_cmdFifoAddressMax:x8} " +
            $"fifoPackets={_fifoPacketCount} drawPackets={_fifoDrawPacketCount}{pcStatus}");
    }

    private void DecodeFifoType1(uint command)
    {
        int count = (int)(command >> 16);
        int increment = ((command >> 15) & 1u) != 0 ? 1 : 0;
        uint target = (command >> 3) & 0xfffu;
        bool streaming = _fixMameCommandFifoModel && ShouldStreamCommandFifoPacketWords(command);
        int available = streaming ? count : Math.Min(count, Math.Max(0, _fifoBuffer.Count - 1));
        TraceCommandFifoType1PacketOwnership(command, target, count, increment, available, streaming);
        TraceCommandFifoType1SelfRegisterPacket(command, target, count, increment, available, streaming);
        bool ignoreSelfRegisterWrites = ShouldIgnoreImplausibleCommandFifoSelfRegisterWrites(command, target, count, increment, streaming);
        if (ignoreSelfRegisterWrites)
            TraceCommandFifoImplausibleSelfRegisterWriteIgnore(command, target, count, increment, available, streaming);

        bool previousIgnoreSelfRegisterWrites = _currentCommandFifoIgnoreImplausibleSelfRegisterWrites;
        _currentCommandFifoIgnoreImplausibleSelfRegisterWrites = ignoreSelfRegisterWrites;
        try
        {
            for (int i = 0; i < available; i++, target += (uint)increment)
            {
                uint value = streaming ? ReadCommandFifoStreamingWord() : _fifoBuffer[1 + i];
                WriteCmdFifoRegister(target, value);
            }
        }
        finally
        {
            _currentCommandFifoIgnoreImplausibleSelfRegisterWrites = previousIgnoreSelfRegisterWrites;
        }
    }

    private bool ShouldIgnoreImplausibleCommandFifoSelfRegisterWrites(uint command, uint target, int count, int increment, bool streaming)
        => _experimentIgnoreImplausibleCommandFifoSelfRegisterWrites &&
           !_fixMameCommandFifoModel &&
           !streaming &&
           IsImplausibleCommandFifoPacket(command, count + 1) &&
           TouchesCommandFifoControlRegister(target, (uint)Math.Max(0, count), (uint)increment);

    private void TraceCommandFifoType1PacketOwnership(uint command, uint target, int count, int increment, int available, bool streaming)
    {
        if (!_traceCommandFifoType1PacketOwnership ||
            _commandFifoType1PacketOwnershipTraceCount >= _traceCommandFifoType1PacketOwnershipLimit ||
            (_traceCommandFifoType1PacketOwnershipCommands.Length != 0 &&
             !_traceCommandFifoType1PacketOwnershipCommands.Contains(command)))
        {
            return;
        }

        _commandFifoType1PacketOwnershipTraceCount++;
        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        int packetStart = _currentCommandFifoPacketStart;
        int packetStorage = CommandFifoReadStorageIndex(packetStart);
        int readStorage = CommandFifoReadStorageIndex(_cmdFifoReadIndex);
        int validWindowLimit = Math.Min(_currentCommandFifoWordsNeeded, 64);
        int validWindowWords = CountCommandFifoValidWindowWords(packetStart, validWindowLimit);
        string bulkPosition = FormatCommandFifoBulkPacketPosition(packetStart).TrimStart();
        if (bulkPosition.Length == 0)
            bulkPosition = "none";
        bool type5Data = bulkPosition.StartsWith("scan=type5-data", StringComparison.Ordinal);
        string words = FormatCommandFifoPacketOwnershipWords(packetStart, Math.Min(_currentCommandFifoWordsNeeded, 8));

        Console.WriteLine(
            $"[GAUNTDL:VOODOO-TYPE1-OWNERSHIP] n={_commandFifoType1PacketOwnershipTraceCount} " +
            $"cmd=0x{command:x8} words={_currentCommandFifoWordsNeeded} target=0x{target:x3} count={count} inc={increment} " +
            $"avail={available} streaming={(streaming ? 1 : 0)} implausible={(IsImplausibleCommandFifoPacket(command, _currentCommandFifoWordsNeeded) ? 1 : 0)} " +
            $"packet=0x{packetStart * 4:x8} rd=0x{_cmdFifoReadIndex * 4:x8} storage=0x{packetStorage * 4:x5} readStorage=0x{readStorage * 4:x5} " +
            $"validWindow={validWindowWords}/{validWindowLimit} depth={_cmdFifoDepth} holes={_cmdFifoHoles} valid={_cmdFifoValidCount} " +
            $"amin=0x{_cmdFifoAddressMin:x8} amax=0x{_cmdFifoAddressMax:x8} trigger={_commandFifoDecodeTrigger} " +
            $"type5Data={(type5Data ? 1 : 0)} bulk={bulkPosition} words={words}{pcStatus}");
    }

    private string FormatCommandFifoPacketOwnershipWords(int packetStart, int count)
    {
        if (count <= 0)
            return "none";

        StringBuilder builder = new(count * 128);
        for (int i = 0; i < count; i++)
        {
            if (i > 0)
                builder.Append('|');
            builder
                .Append('w')
                .Append(i.ToString(CultureInfo.InvariantCulture))
                .Append('=')
                .Append(FormatCommandFifoStorageWordDebug(packetStart + i));
        }

        return builder.ToString();
    }

    private void TraceCommandFifoImplausibleSelfRegisterWriteIgnore(uint command, uint target, int count, int increment, int available, bool streaming)
    {
        if (_commandFifoImplausibleSelfRegisterPacketIgnoreTraceCount >= _experimentIgnoreImplausibleCommandFifoSelfRegisterWritesTraceLimit)
            return;

        _commandFifoImplausibleSelfRegisterPacketIgnoreTraceCount++;
        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        string values = string.Join("/", _fifoBuffer.Skip(1).Take(Math.Min(6, Math.Max(0, available))).Select(value => $"0x{value:x8}"));
        if (values.Length == 0)
            values = "none";

        Console.WriteLine(
            $"[GAUNTDL:VOODOO-CMDFIFO-SELFREG-WRITE-IGNORE] n={_commandFifoImplausibleSelfRegisterPacketIgnoreTraceCount} " +
            $"cmd=0x{command:x8} target=0x{target:x3} count={count} inc={increment} avail={available} streaming={(streaming ? 1 : 0)} " +
            $"words={_currentCommandFifoWordsNeeded} packetStart=0x{_currentCommandFifoPacketStart * 4:x8} rd=0x{_cmdFifoReadIndex * 4:x8} " +
            $"storage=0x{CommandFifoStorageIndex(_currentCommandFifoPacketStart) * 4:x5} readStorage=0x{CommandFifoReadStorageIndex(_cmdFifoReadIndex) * 4:x5} " +
            $"validWindow={CountCommandFifoValidWindowWords(_currentCommandFifoPacketStart, Math.Min(_currentCommandFifoWordsNeeded, 64))}/64 " +
            $"depth={_cmdFifoDepth} holes={_cmdFifoHoles} valid={_cmdFifoValidCount} " +
            $"amin=0x{_cmdFifoAddressMin:x8} amax=0x{_cmdFifoAddressMax:x8} trigger={_commandFifoDecodeTrigger} " +
            $"values={values} " +
            $"w0={FormatCommandFifoStorageWordDebug(_currentCommandFifoPacketStart)} " +
            $"w1={FormatCommandFifoStorageWordDebug(_currentCommandFifoPacketStart + 1)} " +
            $"w2={FormatCommandFifoStorageWordDebug(_currentCommandFifoPacketStart + 2)}{pcStatus}");
    }

    private void TraceCommandFifoType1SelfRegisterPacket(uint command, uint target, int count, int increment, int available, bool streaming)
    {
        if (!_traceCommandFifoSelfRegisterPackets ||
            _commandFifoSelfRegisterPacketTraceCount >= _traceCommandFifoSelfRegisterPacketsLimit ||
            !TouchesCommandFifoControlRegister(target, (uint)Math.Max(0, available), (uint)increment))
        {
            return;
        }

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        string values = string.Join("/", _fifoBuffer.Skip(1).Take(Math.Min(6, Math.Max(0, available))).Select(value => $"0x{value:x8}"));
        if (values.Length == 0)
            values = "none";
        _commandFifoSelfRegisterPacketTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-CMDFIFO-SELFREG] n={_commandFifoSelfRegisterPacketTraceCount} " +
            $"cmd=0x{command:x8} target=0x{target:x3} count={count} inc={increment} avail={available} streaming={(streaming ? 1 : 0)} " +
            $"packetStart=0x{_currentCommandFifoPacketStart * 4:x8} rd=0x{_cmdFifoReadIndex * 4:x8} " +
            $"storage=0x{CommandFifoStorageIndex(_currentCommandFifoPacketStart) * 4:x5} " +
            $"depth={_cmdFifoDepth} holes={_cmdFifoHoles} valid={_cmdFifoValidCount} " +
            $"amin=0x{_cmdFifoAddressMin:x8} amax=0x{_cmdFifoAddressMax:x8} trigger={_commandFifoDecodeTrigger} " +
            $"values={values}{pcStatus}");
    }

    private static bool TouchesCommandFifoControlRegister(uint target, uint count, uint increment)
    {
        if (count == 0)
            return false;

        uint register = target;
        for (uint i = 0; i < count; i++)
        {
            if (IsCommandFifoControlRegister(register & 0xffu))
                return true;
            register += increment;
        }

        return false;
    }

    private static bool IsCommandFifoControlRegister(uint register)
        => register is RegCmdFifoBaseAddr or RegCmdFifoRdPtr or RegCmdFifoAddressMin or RegCmdFifoAddressMax or RegCmdFifoDepth or RegCmdFifoHoles;

    private void DecodeFifoType2(uint command)
    {
        bool streaming = _fixMameCommandFifoModel && ShouldStreamCommandFifoPacketWords(command);
        int source = 1;
        for (uint regbit = 3; regbit <= 31 && (streaming || source < _fifoBuffer.Count); regbit++)
        {
            if (((command >> (int)regbit) & 1u) != 0)
            {
                uint value = streaming ? ReadCommandFifoStreamingWord() : _fifoBuffer[source++];
                WriteCmdFifoRegister(RegBltSrcBaseAddr + regbit - 3u, value);
            }
        }
    }

    private void DecodeFifoType4(uint command)
    {
        uint target = (command >> 3) & 0xfffu;
        TraceCommandFifoType4PacketOwnership(command, target);
        bool streaming = _fixMameCommandFifoModel && ShouldStreamCommandFifoPacketWords(command);
        int source = 1;
        for (int bit = 15; bit <= 28; bit++, target++)
        {
            if (((command >> bit) & 1u) == 0)
                continue;

            if (!streaming && source >= _fifoBuffer.Count)
                return;

            uint value = streaming ? ReadCommandFifoStreamingWord() : _fifoBuffer[source++];
            WriteCmdFifoRegister(target, value);
        }

        if (streaming)
        {
            int dummyWords = (int)(command >> 29);
            for (int i = 0; i < dummyWords; i++)
                _ = ReadCommandFifoStreamingWord();
        }
    }

    private void TraceCommandFifoType4PacketOwnership(uint command, uint target)
    {
        if (!_traceCommandFifoType4PacketOwnership ||
            _commandFifoType4PacketOwnershipTraceCount >= _traceCommandFifoType4PacketOwnershipLimit ||
            (_traceCommandFifoType4PacketOwnershipCommands.Length != 0 &&
             !_traceCommandFifoType4PacketOwnershipCommands.Contains(command)))
        {
            return;
        }

        _commandFifoType4PacketOwnershipTraceCount++;
        uint mask = (command >> 15) & 0x3fffu;
        int packetStart = _currentCommandFifoPacketStart;
        int packetStorage = CommandFifoReadStorageIndex(packetStart);
        int readStorage = CommandFifoReadStorageIndex(_cmdFifoReadIndex);
        bool ownerValid = _cmdFifoStoragePacketOwnerValid[packetStorage];
        int ownerHeader = ownerValid
            ? _cmdFifoStoragePacketOwnerHeaderLogicalIndex[packetStorage]
            : packetStart;
        int ownerEnd = _cmdFifoStoragePacketEndLogicalIndex[packetStorage];
        uint ownerCommand = ReadCommandFifoWordAt(ownerHeader);
        int validWindowLimit = Math.Min(_currentCommandFifoWordsNeeded, 64);
        int validWindowWords = CountCommandFifoValidWindowWords(packetStart, validWindowLimit);
        string bulkPosition = FormatCommandFifoBulkPacketPosition(packetStart).TrimStart();
        if (bulkPosition.Length == 0)
            bulkPosition = "none";
        string words = FormatCommandFifoPacketOwnershipWords(
            packetStart,
            Math.Min(_currentCommandFifoWordsNeeded, 16));
        string precedingWords = FormatCommandFifoPacketOwnershipWords(packetStart - 32, 32);
        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";

        Console.WriteLine(
            $"[GAUNTDL:VOODOO-TYPE4-OWNERSHIP] n={_commandFifoType4PacketOwnershipTraceCount} " +
            $"cmd=0x{command:x8} words={_currentCommandFifoWordsNeeded} target=0x{target:x3} mask=0x{mask:x4} dummy={command >> 29} " +
            $"packet=0x{packetStart * 4:x8} rd=0x{_cmdFifoReadIndex * 4:x8} storage=0x{packetStorage * 4:x5} readStorage=0x{readStorage * 4:x5} " +
            $"owner={(ownerValid ? 1 : 0)}:0x{ownerHeader * 4:x8}-0x{ownerEnd * 4:x8}:0x{ownerCommand:x8} " +
            $"validWindow={validWindowWords}/{validWindowLimit} depth={_cmdFifoDepth} holes={_cmdFifoHoles} valid={_cmdFifoValidCount} " +
            $"amin=0x{_cmdFifoAddressMin:x8} amax=0x{_cmdFifoAddressMax:x8} trigger={_commandFifoDecodeTrigger} " +
            $"bulk={bulkPosition} preceding={precedingWords} words={words}{pcStatus}");
    }

    private void WriteCmdFifoRegister(uint target, uint value)
    {
        uint register = target & 0xffu;
        if (_experimentStandardCommandFifoGenerations && IsCommandFifoControlRegister(register))
        {
            CountCommandFifoTargetRegisterPc(register, value);
            return;
        }
        if (_currentCommandFifoIgnoreImplausibleSelfRegisterWrites &&
            IsCommandFifoControlRegister(register))
        {
            CountCommandFifoTargetRegisterPc(register, value);
            return;
        }
        if (_fixMameCommandFifoModel &&
            _experimentMameCommandFifoIgnoreSelfRegisterWrites &&
            register is RegCmdFifoBaseAddr or RegCmdFifoRdPtr or RegCmdFifoAddressMin or RegCmdFifoAddressMax or RegCmdFifoDepth or RegCmdFifoHoles)
        {
            CountCommandFifoTargetRegisterPc(register, value);
            RecordVoodooEvent($"ignore cmdfifo self-register write reg[{register:x2}]=0x{value:x8}");
            return;
        }
        if (_fixDropLeakedType5RegisterHeaders &&
            IsRasterSetupRegister(register) &&
            IsType5TexturePacketHeader(value))
        {
            RecordVoodooEvent($"drop leaked type5 header reg[{register:x2}]=0x{value:x8}");
            return;
        }
        if (ShouldIgnoreImplausibleCommandFifoRenderStateWrite(register, value))
        {
            CountCommandFifoTargetRegisterPc(register, value);
            TraceCommandFifoImplausibleRenderStateWriteIgnore(target, register, value);
            return;
        }
        if (ShouldSuppressPayloadDirectTriangleCommand(register))
        {
            CountCommandFifoTargetRegisterPc(register, value);
            TraceCommandFifoPayloadDirectTriangleCommandSuppress(target, register, value);
            return;
        }

        CountCommandFifoTargetRegisterPc(register, value);
        TraceCommandFifoRegisterValue(target, value);
        bool traceTmuWrite = ShouldTraceTmuRegisterWrite(target, register, value);
        string tmuBefore = traceTmuWrite ? FormatTextureRegisterWriteStatus() : "";
        bool wroteTmuBank = _fixTmuRegisterBanks && TryWriteTmuRegister(target, value);
        if (traceTmuWrite)
            TraceTmuRegisterWrite(target, register, value, wroteTmuBank, tmuBefore);

        if (wroteTmuBank)
            return;

        WriteRegister(register << 2, value);
    }

    private bool ShouldIgnoreImplausibleCommandFifoRenderStateWrite(uint register, uint value)
    {
        if (!_experimentIgnoreImplausibleCommandFifoRenderStateWrites ||
            (_currentCommandFifoCommand & 7u) != 1u ||
            !IsImplausibleCommandFifoPacket(_currentCommandFifoCommand, _currentCommandFifoWordsNeeded))
        {
            return false;
        }

        if (IsCommandFifoControlRegister(register))
            return false;

        return IsGlobalRenderStateRegister(register) ||
               IsTmuTextureRegister(register) ||
               value == 0x437f0000u;
    }

    private bool ShouldSuppressPayloadDirectTriangleCommand(uint register)
    {
        if (!_experimentSuppressPayloadDirectTriangleCommands ||
            register is not (RegTriangleCommand or RegFtriangleCommand) ||
            !_decodingCommandFifo ||
            (_currentCommandFifoCommand & 7u) != 1u ||
            _commandFifoDecodeTrigger != "bulk-end" ||
            !IsImplausibleCommandFifoPacket(_currentCommandFifoCommand, _currentCommandFifoWordsNeeded))
        {
            return false;
        }
        if (_experimentSuppressPayloadDirectTriangleCommandsFilter.Length != 0 &&
            !_experimentSuppressPayloadDirectTriangleCommandsFilter.Contains(_currentCommandFifoCommand))
        {
            return false;
        }

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if ((pc & 0xffffffffUL) != 0x800fe5d4UL)
            return false;

        int storageIndex = CommandFifoReadStorageIndex(_currentCommandFifoPacketStart);
        return _cmdFifoValid[storageIndex] &&
               _cmdFifoStorageLastWriteSource[storageIndex] == CmdFifoStorageWriteSourceFifo &&
               (_cmdFifoStorageLastWritePc[storageIndex] & 0xffffffffUL) == 0x800fe5d4UL;
    }

    private void TraceCommandFifoPayloadDirectTriangleCommandSuppress(uint target, uint register, uint value)
    {
        _commandFifoPayloadDirectTriangleCommandSuppressCount++;
        if (_commandFifoPayloadDirectTriangleCommandSuppressCount > _experimentSuppressPayloadDirectTriangleCommandsTraceLimit)
            return;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        int storageIndex = CommandFifoReadStorageIndex(_currentCommandFifoPacketStart);
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-PAYLOAD-DIRECT-CMD-SUPPRESS] n={_commandFifoPayloadDirectTriangleCommandSuppressCount} " +
            $"target=0x{target:x3} reg=0x{register:x2} value=0x{value:x8} " +
            $"cmd=0x{_currentCommandFifoCommand:x8} words={_currentCommandFifoWordsNeeded} " +
            $"packet=0x{_currentCommandFifoPacketStart * 4:x8} rd=0x{_cmdFifoReadIndex * 4:x8} " +
            $"storage=0x{storageIndex * 4:x5} last=0x{_cmdFifoStorageLastWriteValue[storageIndex]:x8}/pc0x{_cmdFifoStorageLastWritePc[storageIndex]:x16} " +
            $"depth={_cmdFifoDepth} holes={_cmdFifoHoles} trigger={_commandFifoDecodeTrigger}{pcStatus}");
    }

    private static bool IsGlobalRenderStateRegister(uint register)
        => register is RegFbzColorPath or RegFbzMode or RegLfbMode or
            RegClipLeftRight or RegClipLowYHighY or
            RegColor0 or RegColor1 or RegZaColor or
            RegFastfillCommand or RegSwapbufferCommand;

    private void TraceCommandFifoImplausibleRenderStateWriteIgnore(uint target, uint register, uint value)
    {
        if (_commandFifoImplausibleRenderStateWriteIgnoreTraceCount >= _experimentIgnoreImplausibleCommandFifoRenderStateWritesTraceLimit)
            return;

        _commandFifoImplausibleRenderStateWriteIgnoreTraceCount++;
        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-CMDFIFO-RENDERSTATE-WRITE-IGNORE] n={_commandFifoImplausibleRenderStateWriteIgnoreTraceCount} " +
            $"target=0x{target:x3} reg=0x{register:x2} value=0x{value:x8} " +
            $"cmd=0x{_currentCommandFifoCommand:x8} words={_currentCommandFifoWordsNeeded} " +
            $"packet=0x{_currentCommandFifoPacketStart * 4:x8} rd=0x{_cmdFifoReadIndex * 4:x8} " +
            $"depth={_cmdFifoDepth} holes={_cmdFifoHoles} amin=0x{_cmdFifoAddressMin:x8} amax=0x{_cmdFifoAddressMax:x8}{pcStatus}");
    }

    private bool ShouldTraceTmuRegisterWrite(uint target, uint register, uint value)
    {
        if (!_traceTmuRegisterWrites ||
            _tmuRegisterWriteTraceCount >= _traceTmuRegisterWritesLimit ||
            !IsTmuTextureRegister(register))
        {
            return false;
        }

        if (_traceTmuRegisterWriteTargets.Length != 0 &&
            !_traceTmuRegisterWriteTargets.Contains(target))
        {
            return false;
        }
        if (_traceTmuRegisterWriteRegisters.Length != 0 &&
            !_traceTmuRegisterWriteRegisters.Contains(register))
        {
            return false;
        }
        if (_traceTmuRegisterWriteValues.Length != 0 &&
            !_traceTmuRegisterWriteValues.Contains(value))
        {
            return false;
        }

        return true;
    }

    private void TraceTmuRegisterWrite(uint target, uint register, uint value, bool banked, string before)
    {
        _tmuRegisterWriteTraceCount++;
        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        string storageStatus = _currentCommandFifoPacketStart >= 0
            ? $" storage=hdr[{FormatCommandFifoStorageWordDebug(_currentCommandFifoPacketStart)}]" +
              $" w1[{FormatCommandFifoStorageWordDebug(_currentCommandFifoPacketStart + 1)}]" +
              $" w2[{FormatCommandFifoStorageWordDebug(_currentCommandFifoPacketStart + 2)}]" +
              $" w3[{FormatCommandFifoStorageWordDebug(_currentCommandFifoPacketStart + 3)}]"
            : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-TMU] n={_tmuRegisterWriteTraceCount} target=0x{target:x3} chip=0x{DecodeChipmask(target):x1} " +
            $"reg=0x{register:x2} value=0x{value:x8} banked={(banked ? 1 : 0)} " +
            $"cmd=0x{_currentCommandFifoCommand:x8} packet=0x{_currentCommandFifoPacketStart * 4:x8} rd=0x{_cmdFifoReadIndex * 4:x8} " +
            $"before={before} after={FormatTextureRegisterWriteStatus()}{storageStatus}{pcStatus}");
    }

    private string FormatTextureRegisterWriteStatus()
        => $"global={_registers[RegTextureMode]:X8}/{_registers[RegTextureLod]:X8}/{_registers[RegTextureBaseAddr]:X8}:" +
           $"tmu0={FormatTmuDebugStatus(0)}:" +
           $"tmu1={FormatTmuDebugStatus(1)}";

    private void TraceCommandFifoRegisterValue(uint target, uint value)
    {
        if (!_traceCommandFifoModel ||
            _traceCommandFifoModelCommands.Length == 0 ||
            !_traceCommandFifoModelCommands.Contains(value) ||
            _commandFifoRegisterValueTraceCount++ >= 80)
        {
            return;
        }

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-CMDFIFO] reg-value target=0x{target:x3} reg=0x{target & 0xffu:x2} " +
            $"value=0x{value:x8} packet=0x{_currentCommandFifoCommand:x8} " +
            $"packetType={_currentCommandFifoCommand & 7u} packetStart=0x{_currentCommandFifoPacketStart * 4:x8} " +
            $"words={_currentCommandFifoWordsNeeded} rd=0x{_cmdFifoReadIndex * 4:x8} " +
            $"depth={_cmdFifoDepth} holes={_cmdFifoHoles} amin=0x{_cmdFifoAddressMin:x8} amax=0x{_cmdFifoAddressMax:x8}{pcStatus}");
    }

    private bool TryWriteTmuRegister(uint target, uint value)
    {
        uint register = target & 0xffu;
        if (!IsTmuTextureRegister(register))
            return false;

        uint chipmask = DecodeChipmask(target);
        if ((chipmask & 0x6u) == 0)
            return false;

        int index = (int)register;
        if ((chipmask & 0x2u) != 0)
        {
            WriteTmuRegisterOrPalette(0, index, value);
            RecordTmuRegisterWriter(0, index);
        }
        if ((chipmask & 0x4u) != 0)
        {
            WriteTmuRegisterOrPalette(1, index, value);
            RecordTmuRegisterWriter(1, index);
        }
        _registerWriteCount++;
        RecordVoodooEvent($"tmu[{chipmask:x1}:{register:x2}]=0x{value:x8}");
        return true;
    }

    private void RecordTmuRegisterWriter(int tmu, int register)
    {
        int sequence = ++_tmuRegisterWriterSequence;
        _tmuRegisterLastWriterPc[tmu][register] = CpuPcProvider?.Invoke() ?? 0;
        _tmuRegisterLastWriterCommand[tmu][register] = _currentCommandFifoCommand;
        _tmuRegisterLastWriterPacketStart[tmu][register] = _currentCommandFifoPacketStart;
        _tmuRegisterLastWriterSequence[tmu][register] = sequence;
    }

    private string FormatTmuRegisterWriterStatus(int tmu)
        => $"tmu{tmu}:" +
           FormatTmuRegisterWriter("mode", tmu, RegTextureMode) + "/" +
           FormatTmuRegisterWriter("lod", tmu, RegTextureLod) + "/" +
           FormatTmuRegisterWriter("base", tmu, RegTextureBaseAddr);

    private string FormatTmuRegisterWriter(string name, int tmu, int register)
    {
        int sequence = _tmuRegisterLastWriterSequence[tmu][register];
        if (sequence == 0)
            return $"{name}=none";

        return $"{name}=pc0x{_tmuRegisterLastWriterPc[tmu][register] & 0xffffffffUL:x8}" +
               $":cmd0x{_tmuRegisterLastWriterCommand[tmu][register]:x8}" +
               $":pkt0x{_tmuRegisterLastWriterPacketStart[tmu][register] * 4:x8}:n{sequence}";
    }

    private void WriteTmuRegisterOrPalette(int tmu, int register, uint value)
    {
        if (TryWriteTmuPaletteEntry(tmu, register, value))
            return;

        _tmuRegisters[tmu][register] = value;
        _tmuRegisterValid[tmu][register] = true;
    }

    private bool TryWriteTmuPaletteEntry(int tmu, int register, uint value)
    {
        int regIndex = register - RegNccTable;
        if ((value & 0x80000000u) == 0 ||
            regIndex < 4 ||
            regIndex >= 12)
        {
            return false;
        }

        int paletteIndex = (int)(((value >> 24) & 0x7fu) << 1) | (regIndex & 1);
        int rgbOffset = paletteIndex;
        int argbOffset = 256 + paletteIndex;

        _tmuPaletteRgb565[tmu][rgbOffset] = Rgb888ToRgb565(
            (byte)(value >> 16),
            (byte)(value >> 8),
            (byte)value);
        _tmuPaletteRgb565[tmu][argbOffset] = Rgb888ToRgb565(
            Expand6To8((int)(value >> 12)),
            Expand6To8((int)(value >> 6)),
            Expand6To8((int)value));
        _tmuPaletteValid[tmu][rgbOffset] = true;
        _tmuPaletteValid[tmu][argbOffset] = true;
        return true;
    }

    private static bool IsTmuTextureRegister(uint register)
        => register is >= RegTextureMode and < RegNccTableEnd;

    private static bool IsRasterSetupRegister(uint register)
        => register is
            >= 0x02u and <= 0x2au or
            >= RegFstartS and <= RegFdWdY or
            >= 0x98u and <= 0xa9u or
            RegTriangleCommand or RegFtriangleCommand;

    private static uint DecodeChipmask(uint target)
    {
        uint chipmask = (target >> 8) & 0xfu;
        return chipmask == 0 ? 0xfu : chipmask;
    }

    private uint ReadTextureRegister(int register)
    {
        if (_fixTmuRegisterBanks)
        {
            if (_tmuRegisterValid[0][register])
                return _tmuRegisters[0][register];
            if (_tmuRegisterValid[1][register])
                return _tmuRegisters[1][register];
        }

        return _registers[register];
    }

    private uint ReadTextureRegisterForTmu(int tmu, int register)
    {
        if ((uint)tmu <= 1u && _tmuRegisterValid[tmu][register])
            return _tmuRegisters[tmu][register];
        return _registers[register];
    }

    private uint ReadTextureSampleRegister(int register)
    {
        int tmu = GetTextureSampleTmuIndex();
        uint value = tmu >= 0
            ? ReadTextureRegisterForTmu(tmu, register)
            : ReadTextureRegister(register);
        if (register == RegTextureLod && _experimentTextureSampleLodOrMask.HasValue)
            value |= (uint)_experimentTextureSampleLodOrMask.Value;
        return value;
    }

    private int GetTextureSampleTmuIndex()
    {
        if ((uint)_experimentTextureSampleTmu <= 1u)
            return _experimentTextureSampleTmu;
        if (_fixTmuRegisterBanks)
        {
            if (_tmuRegisterValid[0][RegTextureMode])
                return 0;
            if (_tmuRegisterValid[1][RegTextureMode])
                return 1;
        }
        return -1;
    }

    private uint MapTextureBankByteAddress(int tmu, uint byteAddress)
    {
        if (!_experimentSeparateTmuTextureMemory || (uint)tmu > 1u)
            return byteAddress & (TextureBytes - 1u);

        return (uint)(tmu * TextureBankBytes) + (byteAddress & (TextureBankBytes - 1u));
    }

    private uint MapTextureSampleBankByteAddress(uint byteAddress)
    {
        int tmu = GetTextureSampleTmuIndex();
        return MapTextureBankByteAddress(tmu < 0 ? 0 : tmu, byteAddress);
    }

    private string GetTextureSampleRegisterSourceLabel()
    {
        int tmu = GetTextureSampleTmuIndex();
        if (tmu >= 0)
            return $"tmu{tmu}";
        return "global";
    }

    private void RecordInterestingFifoEvent(uint command, int wordsNeeded)
    {
        if (!_recordVoodooEvents)
            return;

        uint type = command & 7u;
        switch (type)
        {
            case 0:
                RecordVoodooEvent($"fifo type0 cmd=0x{command:x8} words={wordsNeeded} rd=0x{_cmdFifoReadIndex:x4}");
                break;
            case 1:
            {
                int count = (int)(command >> 16);
                uint target = (command >> 3) & 0xfffu;
                if (TouchesInterestingEventRegister(target, (uint)Math.Max(0, count)))
                    RecordVoodooEvent($"fifo type1 cmd=0x{command:x8} target=0x{target:x3} count={count} inc={(command >> 15) & 1u} words={wordsNeeded} rd=0x{_cmdFifoReadIndex:x4}");
                break;
            }
            case 3:
            {
                uint w1 = _fifoBuffer.Count > 1 ? _fifoBuffer[1] : 0;
                uint w2 = _fifoBuffer.Count > 2 ? _fifoBuffer[2] : 0;
                uint w3 = _fifoBuffer.Count > 3 ? _fifoBuffer[3] : 0;
                uint w4 = _fifoBuffer.Count > 4 ? _fifoBuffer[4] : 0;
                uint w5 = _fifoBuffer.Count > 5 ? _fifoBuffer[5] : 0;
                uint w6 = _fifoBuffer.Count > 6 ? _fifoBuffer[6] : 0;
                RecordVoodooEvent(
                    $"fifo type3 cmd=0x{command:x8} count={(command >> 6) & 0xfu} code={(command >> 3) & 7u} " +
                    $"words={wordsNeeded} data=0x{w1:x8}/0x{w2:x8}/0x{w3:x8}/0x{w4:x8}/0x{w5:x8}/0x{w6:x8} rd=0x{_cmdFifoReadIndex:x4}");
                break;
            }
            case 4:
            {
                uint target = (command >> 3) & 0xfffu;
                uint mask = (command >> 15) & 0x3fffu;
                if (TouchesInterestingType4Register(target, mask))
                    RecordVoodooEvent($"fifo type4 cmd=0x{command:x8} target=0x{target:x3} mask=0x{mask:x4} words={wordsNeeded} rd=0x{_cmdFifoReadIndex:x4}");
                break;
            }
            case 5:
            {
                uint target = _fifoBuffer.Count > 1 ? _fifoBuffer[1] : 0;
                uint first = _fifoBuffer.Count > 2 ? _fifoBuffer[2] : 0;
                uint second = _fifoBuffer.Count > 3 ? _fifoBuffer[3] : 0;
                RecordVoodooEvent($"fifo type5 cmd=0x{command:x8} count={(command >> 3) & 0x7ffffu} space={command >> 30} target=0x{target:x8} data=0x{first:x8}/0x{second:x8} words={wordsNeeded} rd=0x{_cmdFifoReadIndex:x4}");
                break;
            }
        }
    }

    private void RecordVoodooEvent(string description)
    {
        if (!_recordVoodooEvents)
            return;

        int sequence = _recentVoodooEventSequence++;
        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        _recentVoodooEvents[sequence & (_recentVoodooEvents.Length - 1)] = $"{sequence}:{description}{pcStatus}";
    }

    private string FormatRecentVoodooEvents()
    {
        int count = Math.Min(_recentVoodooEventSequence, _recentVoodooEvents.Length);
        if (count == 0)
            return "none";

        int start = _recentVoodooEventSequence - count;
        return string.Join(" | ", Enumerable.Range(0, count).Select(i => _recentVoodooEvents[(start + i) & (_recentVoodooEvents.Length - 1)]));
    }

    private void CountFastFillPc(ushort color, bool suppressed, int bufferIndex)
    {
        if (!_profileFastFillSwapPcs)
            return;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if (pc == 0)
            return;

        if (!_fastFillPcStats.TryGetValue(pc, out FastFillPcStats? stats))
        {
            stats = new FastFillPcStats();
            _fastFillPcStats[pc] = stats;
        }

        stats.Total++;
        if (suppressed)
            stats.Suppressed++;
        if (color == 0xffff)
            stats.White++;
        else if (color == 0)
            stats.Black++;
        else
            stats.Other++;
        if ((uint)bufferIndex < (uint)stats.BufferCounts.Length)
            stats.BufferCounts[bufferIndex]++;
        stats.LastColor = color;
        stats.LastFbzMode = _registers[RegFbzMode];
        stats.LastColor0 = _registers[RegColor0];
        stats.LastColor1 = _registers[RegColor1];
        stats.LastZaColor = _registers[RegZaColor];
        stats.LastCommandFifoReadIndex = _cmdFifoReadIndex;
        stats.LastBufferIndex = bufferIndex;
        stats.LastSuppressed = suppressed;
    }

    private void CountSolidTriangle(
        string source,
        ushort color,
        float ax,
        float ay,
        float bx,
        float by,
        float cx,
        float cy,
        float area,
        int minX,
        int maxX,
        int minY,
        int maxY)
        => CountSolidTriangleCore(source, color, ax, ay, bx, by, cx, cy, area, minX, maxX, minY, maxY, false, false, false, 0);

    private void CountSuppressedSolidTriangle(
        string source,
        ushort color,
        float ax,
        float ay,
        float bx,
        float by,
        float cx,
        float cy,
        float area,
        int minX,
        int maxX,
        int minY,
        int maxY,
        bool implausible,
        bool large,
        bool offscreen)
        => CountSolidTriangleCore(source, color, ax, ay, bx, by, cx, cy, area, minX, maxX, minY, maxY, implausible, large, offscreen, 0);

    private void CountDrawnSolidTriangle(
        string source,
        ushort color,
        float ax,
        float ay,
        float bx,
        float by,
        float cx,
        float cy,
        float area,
        int minX,
        int maxX,
        int minY,
        int maxY,
        long drawnPixels)
        => CountSolidTriangleCore(source, color, ax, ay, bx, by, cx, cy, area, minX, maxX, minY, maxY, false, false, false, drawnPixels);

    private void CountSolidTriangleCore(
        string source,
        ushort color,
        float ax,
        float ay,
        float bx,
        float by,
        float cx,
        float cy,
        float area,
        int minX,
        int maxX,
        int minY,
        int maxY,
        bool suppressedImplausible,
        bool suppressedLarge,
        bool suppressedOffscreen,
        long drawnPixels)
    {
        if (!_profileSolidTriangles)
            return;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        long boxPixels = Math.Max(0, maxX - minX) * (long)Math.Max(0, maxY - minY);
        string key = $"{pc:x16}:{source}:{color:X4}:{_registers[RegFbzMode]:X8}:{_registers[RegFbzColorPath]:X8}";
        if (!_solidTriangleStats.TryGetValue(key, out SolidTriangleStats? stats))
        {
            stats = new SolidTriangleStats
            {
                Pc = pc,
                Source = source,
                Color = color,
                FbzMode = _registers[RegFbzMode],
                FbzColorPath = _registers[RegFbzColorPath]
            };
            _solidTriangleStats[key] = stats;
        }

        stats.Total++;
        stats.TotalBoxPixels += boxPixels;
        if (suppressedImplausible)
            stats.SuppressedImplausible++;
        if (suppressedLarge)
            stats.SuppressedLarge++;
        if (suppressedOffscreen)
            stats.SuppressedOffscreen++;
        if (drawnPixels > 0)
        {
            stats.Drawn++;
            stats.DrawnPixels += drawnPixels;
            stats.DrawnBoxPixels += boxPixels;
            if (boxPixels > stats.MaxDrawnBoxPixels)
            {
                stats.MaxDrawnBoxPixels = boxPixels;
                stats.LastDrawnArea = area;
                stats.LastDrawnMinX = minX;
                stats.LastDrawnMaxX = maxX;
                stats.LastDrawnMinY = minY;
                stats.LastDrawnMaxY = maxY;
                stats.LastDrawnAx = ax;
                stats.LastDrawnAy = ay;
                stats.LastDrawnBx = bx;
                stats.LastDrawnBy = by;
                stats.LastDrawnCx = cx;
                stats.LastDrawnCy = cy;
                stats.LastDrawnCommandFifoReadIndex = _cmdFifoReadIndex;
                stats.LastDrawnBufferIndex = GetDrawBufferIndex();
            }
        }
        if (boxPixels >= stats.MaxBoxPixels)
        {
            stats.MaxBoxPixels = boxPixels;
            stats.LastArea = area;
            stats.LastMinX = minX;
            stats.LastMaxX = maxX;
            stats.LastMinY = minY;
            stats.LastMaxY = maxY;
            stats.LastAx = ax;
            stats.LastAy = ay;
            stats.LastBx = bx;
            stats.LastBy = by;
            stats.LastCx = cx;
            stats.LastCy = cy;
            stats.LastCommandFifoReadIndex = _cmdFifoReadIndex;
            stats.LastBufferIndex = GetDrawBufferIndex();
        }
    }

    private string GetSolidTriangleDebugStatus()
    {
        if (!_profileSolidTriangles)
            return "";

        if (_solidTriangleStats.Count == 0)
            return "solidtri=none ";

        string candidates = string.Join(",", _solidTriangleStats
            .OrderByDescending(pair => pair.Value.TotalBoxPixels)
            .ThenByDescending(pair => pair.Value.MaxBoxPixels)
            .ThenBy(pair => pair.Key)
            .Take(6)
            .Select(pair => FormatSolidTriangleStats(pair.Value)));
        string drawn = string.Join(",", _solidTriangleStats
            .Where(pair => pair.Value.Drawn > 0)
            .OrderByDescending(pair => pair.Value.DrawnBoxPixels)
            .ThenByDescending(pair => pair.Value.DrawnPixels)
            .ThenBy(pair => pair.Key)
            .Take(6)
            .Select(pair => FormatSolidTriangleStats(pair.Value)));
        if (drawn.Length == 0)
            drawn = "none";

        return $"solidtri={candidates} solidtriDraw={drawn} ";
    }

    private static string FormatSolidTriangleStats(SolidTriangleStats stats)
    {
        return $"0x{stats.Pc:x16}:{stats.Source}:{stats.Total}/sum{stats.TotalBoxPixels}/max{stats.MaxBoxPixels}" +
               $"/draw{stats.Drawn}/dp{stats.DrawnPixels}/dbox{stats.DrawnBoxPixels}/dmax{stats.MaxDrawnBoxPixels}" +
               $"/dlast{stats.LastDrawnMinX}-{stats.LastDrawnMaxX}x{stats.LastDrawnMinY}-{stats.LastDrawnMaxY}/db{stats.LastDrawnBufferIndex}" +
               $"/dxy{stats.LastDrawnAx:F1},{stats.LastDrawnAy:F1}:{stats.LastDrawnBx:F1},{stats.LastDrawnBy:F1}:{stats.LastDrawnCx:F1},{stats.LastDrawnCy:F1}" +
               $"/darea{stats.LastDrawnArea:F1}/drd{stats.LastDrawnCommandFifoReadIndex:X}" +
               $"/simp{stats.SuppressedImplausible}/slrg{stats.SuppressedLarge}/soff{stats.SuppressedOffscreen}" +
               $"/c{stats.Color:X4}/b{stats.LastBufferIndex}/box{stats.LastMinX}-{stats.LastMaxX}x{stats.LastMinY}-{stats.LastMaxY}" +
               $"/xy{stats.LastAx:F1},{stats.LastAy:F1}:{stats.LastBx:F1},{stats.LastBy:F1}:{stats.LastCx:F1},{stats.LastCy:F1}" +
               $"/area{stats.LastArea:F1}/fbz{stats.FbzMode:X8}/cp{stats.FbzColorPath:X8}/rd{stats.LastCommandFifoReadIndex:X}";
    }

    private void TraceFastFillSwapOrder(string kind, uint register, uint value, string extra = "")
    {
        if (!_traceFastFillSwapOrder || _fastFillSwapOrderTraceCount >= _traceFastFillSwapOrderLimit)
            return;

        if (_renderFrame < _traceFastFillSwapOrderMinRenderFrame)
            return;

        if (_traceFastFillSwapOrderSwapsOnly && !kind.StartsWith("swap", StringComparison.Ordinal))
            return;

        if (kind == "reg" && !IsFastFillSwapOrderRegister(register))
            return;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if (_traceFastFillSwapOrderPcs.Length != 0 && !_traceFastFillSwapOrderPcs.Contains(pc))
            return;

        string extraStatus = extra.Length == 0 ? "" : $" {extra}";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-FILL-SWAP] n={++_fastFillSwapOrderTraceCount} kind={kind} " +
            $"pc=0x{pc:x16} reg=0x{register:x3} value=0x{value:x8} " +
            $"c0=0x{_registers[RegColor0]:x8} c1=0x{_registers[RegColor1]:x8} za=0x{_registers[RegZaColor]:x8} " +
            $"fbz=0x{_registers[RegFbzMode]:x8} lfb=0x{_registers[RegLfbMode]:x8} " +
            $"frame={_renderFrame} front={_frontBufferIndex} back={_backBufferIndex} draw={GetDrawBufferIndex()} rd=0x{_cmdFifoReadIndex:x6} " +
            $"cmd=0x{_currentCommandFifoCommand:x8}:{_currentCommandFifoWordsNeeded}:0x{_currentCommandFifoPacketStart * 4:x8} trigger={_commandFifoDecodeTrigger} " +
            $"depth={_cmdFifoDepth} holes={_cmdFifoHoles} fifoPackets={_fifoPacketCount} draws={_fifoDrawPacketCount} " +
            $"{FormatRenderBufferTraceStats(0)} {FormatRenderBufferTraceStats(1)} {FormatRenderBufferTraceStats(2)} " +
            $"fills={_fastFillCount} swaps={_swapBufferCount}{extraStatus}");
    }

    private static bool IsFastFillSwapOrderRegister(uint register)
        => register is RegFbzColorPath or RegFbzMode or RegLfbMode or RegFastfillCommand or RegSwapbufferCommand or
            RegZaColor or RegColor0 or RegColor1 or RegClipLeftRight or RegClipLowYHighY;

    private static ulong? ParseOptionalHexUlong(string? raw)
    {
        if (string.IsNullOrWhiteSpace(raw))
            return null;

        string value = raw.Trim();
        if (value.StartsWith("0x", StringComparison.OrdinalIgnoreCase))
            value = value[2..];

        return ulong.TryParse(value, System.Globalization.NumberStyles.HexNumber, null, out ulong parsed)
            ? parsed
            : null;
    }

    private static ulong[] ParseOptionalHexUlongList(string? raw)
    {
        if (string.IsNullOrWhiteSpace(raw))
            return [];

        return raw.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Select(item => item.StartsWith("0x", StringComparison.OrdinalIgnoreCase) ? item[2..] : item)
            .Select(item => ulong.TryParse(item, System.Globalization.NumberStyles.HexNumber, null, out ulong value) ? value : 0)
            .Where(value => value != 0)
            .Distinct()
            .ToArray();
    }

    private static int[] ParseOptionalIntList(string? raw)
    {
        if (string.IsNullOrWhiteSpace(raw))
            return [];

        return raw.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Select(item => ParseOptionalInt(item, int.MinValue))
            .Where(value => value != int.MinValue)
            .Distinct()
            .ToArray();
    }

    private static int ParseOptionalPositiveInt(string? raw, int fallback)
        => int.TryParse(raw, out int parsed) && parsed > 0 ? parsed : fallback;

    private static int ParseOptionalInt(string? raw, int fallback)
    {
        if (string.IsNullOrWhiteSpace(raw))
            return fallback;

        string value = raw.Trim();
        if (value.StartsWith("0x", StringComparison.OrdinalIgnoreCase) &&
            int.TryParse(value[2..], System.Globalization.NumberStyles.HexNumber, null, out int hex))
        {
            return hex;
        }

        return int.TryParse(value, out int parsed) ? parsed : fallback;
    }

    private static int ParseOptionalSignedHexInt(string? raw, int fallback)
    {
        if (string.IsNullOrWhiteSpace(raw))
            return fallback;

        string value = raw.Trim();
        int sign = 1;
        if (value.StartsWith("-", StringComparison.Ordinal))
        {
            sign = -1;
            value = value[1..].TrimStart();
        }
        else if (value.StartsWith("+", StringComparison.Ordinal))
        {
            value = value[1..].TrimStart();
        }

        if (value.StartsWith("0x", StringComparison.OrdinalIgnoreCase) &&
            int.TryParse(value[2..], System.Globalization.NumberStyles.HexNumber, null, out int hex))
        {
            return hex * sign;
        }

        return int.TryParse(raw, out int parsed) ? parsed : fallback;
    }

    private static Dictionary<uint, uint> ParseOptionalHexUintMap(string? raw)
    {
        Dictionary<uint, uint> result = [];
        if (string.IsNullOrWhiteSpace(raw))
            return result;

        foreach (string entry in raw.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
        {
            string[] parts = entry.Split(new[] { ':', '=' }, StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
            if (parts.Length != 2 ||
                !TryParseOptionalHexUint(parts[0], out uint from) ||
                !TryParseOptionalHexUint(parts[1], out uint to))
            {
                continue;
            }

            result[from] = to;
        }

        return result;
    }

    private static bool TryParseOptionalHexUint(string raw, out uint value)
    {
        value = 0;
        string token = raw.Trim();
        if (token.StartsWith("0x", StringComparison.OrdinalIgnoreCase))
            token = token[2..];
        return uint.TryParse(token, System.Globalization.NumberStyles.HexNumber, null, out value);
    }

    private void CountSwapPc(uint command, bool dontSwap, bool clearBackBuffer)
    {
        if (!_profileFastFillSwapPcs)
            return;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if (pc == 0)
            return;

        if (!_swapPcStats.TryGetValue(pc, out SwapPcStats? stats))
        {
            stats = new SwapPcStats();
            _swapPcStats[pc] = stats;
        }

        stats.Total++;
        if (clearBackBuffer)
            stats.Clear++;
        if (dontSwap)
            stats.DontSwap++;
        stats.LastCommand = command;
    }

    private string GetFastFillSwapPcDebugStatus()
    {
        if (!_profileFastFillSwapPcs)
            return "";

        return $"ffpc={FormatFastFillPcStats()} swpc={FormatSwapPcStats()} ";
    }

    private string FormatFastFillPcStats()
    {
        if (_fastFillPcStats.Count == 0)
            return "none";

        return string.Join(",", _fastFillPcStats
            .OrderByDescending(pair => pair.Value.Black + pair.Value.Suppressed)
            .ThenByDescending(pair => pair.Value.Total)
            .ThenBy(pair => pair.Key)
            .Take(8)
            .Select(pair =>
                $"0x{pair.Key:x16}:{pair.Value.Total}/w{pair.Value.White}/k{pair.Value.Black}/o{pair.Value.Other}/s{pair.Value.Suppressed}/b{pair.Value.BufferCounts[0]}-{pair.Value.BufferCounts[1]}-{pair.Value.BufferCounts[2]}" +
                $"/last{pair.Value.LastColor:X4}:{(pair.Value.LastSuppressed ? 1 : 0)}:{pair.Value.LastBufferIndex}:fbz{pair.Value.LastFbzMode:X8}:c{pair.Value.LastColor0:X8}-{pair.Value.LastColor1:X8}:za{pair.Value.LastZaColor:X8}:rd{pair.Value.LastCommandFifoReadIndex:X}"));
    }

    private string FormatSwapPcStats()
    {
        if (_swapPcStats.Count == 0)
            return "none";

        return string.Join(",", _swapPcStats
            .OrderByDescending(pair => pair.Value.Clear)
            .ThenByDescending(pair => pair.Value.Total)
            .ThenBy(pair => pair.Key)
            .Take(8)
            .Select(pair =>
                $"0x{pair.Key:x16}:{pair.Value.Total}/c{pair.Value.Clear}/d{pair.Value.DontSwap}/last0x{pair.Value.LastCommand:X8}"));
    }

    private void CountCommandFifoPacketPc(uint command, int wordsNeeded, int packetStart)
    {
        if (!_profileCommandFifoPacketPcs)
            return;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if (pc == 0)
            return;

        if (!_commandFifoPacketPcStats.TryGetValue(pc, out CommandFifoPacketPcStats? stats))
        {
            stats = new CommandFifoPacketPcStats();
            _commandFifoPacketPcStats[pc] = stats;
        }

        uint type = command & 7u;
        stats.Total++;
        stats.Words += wordsNeeded;
        if (type < stats.TypeCounts.Length)
            stats.TypeCounts[type]++;
        stats.LastCommand = command;
        stats.LastWordsNeeded = wordsNeeded;
        stats.LastPacketStart = packetStart;
        stats.LastDepthBefore = _cmdFifoDepth;
        stats.LastHolesBefore = _cmdFifoHoles;
        if (_fixMameCommandFifoModel)
        {
            int storageIndex = CommandFifoStorageIndex(packetStart);
            int storedLogicalIndex = _cmdFifoStorageLogicalIndex[storageIndex];
            if (storedLogicalIndex == packetStart)
                stats.GenerationMatches++;
            else
                stats.GenerationMismatches++;
            stats.LastStorageIndex = storageIndex;
            stats.LastStoredLogicalIndex = storedLogicalIndex;
        }
    }

    private string GetCommandFifoPacketPcDebugStatus()
    {
        if (!_profileCommandFifoPacketPcs)
            return "";

        return $"cmdpc={FormatCommandFifoPacketPcStats()} cmdw={FormatCommandFifoWritePcStats()} cmdreg={FormatCommandFifoRegisterReadPcStats()} cmdwr={FormatCommandFifoRegisterWritePcStats()} cmdtgt={FormatCommandFifoTargetRegisterPcStats()} cmdrdy={FormatCommandFifoReadyPcStats()} ";
    }

    private string FormatCommandFifoPacketPcStats()
    {
        if (_commandFifoPacketPcStats.Count == 0)
            return "none";

        return string.Join(",", _commandFifoPacketPcStats
            .OrderByDescending(pair => pair.Value.TypeCounts[4] + pair.Value.TypeCounts[5])
            .ThenByDescending(pair => pair.Value.Total)
            .ThenBy(pair => pair.Key)
            .Take(10)
            .Select(pair =>
                $"0x{pair.Key:x16}:{pair.Value.Total}/w{pair.Value.Words}" +
                $"/t{string.Join('-', pair.Value.TypeCounts)}" +
                $"/g{pair.Value.GenerationMatches}-{pair.Value.GenerationMismatches}" +
                $"/last0x{pair.Value.LastCommand:X8}:{pair.Value.LastWordsNeeded}:rd{pair.Value.LastPacketStart:X}:st{pair.Value.LastStorageIndex:X}:lg{pair.Value.LastStoredLogicalIndex:X}:d{pair.Value.LastDepthBefore}:h{pair.Value.LastHolesBefore}"));
    }

    private void CountCommandFifoWritePc(int mode, int depthDelta, int holesDelta, int address, uint value)
    {
        if (!_profileCommandFifoPacketPcs)
            return;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if (pc == 0)
            return;

        if (!_commandFifoWritePcStats.TryGetValue(pc, out CommandFifoWritePcStats? stats))
        {
            stats = new CommandFifoWritePcStats();
            _commandFifoWritePcStats[pc] = stats;
        }

        stats.Total++;
        stats.DepthDelta += depthDelta;
        stats.HolesDelta += holesDelta;
        if ((uint)mode < (uint)stats.ModeCounts.Length)
            stats.ModeCounts[mode]++;
        if (!stats.HasAddress)
        {
            stats.HasAddress = true;
            stats.FirstAddress = address;
            stats.MinAddress = address;
            stats.MaxAddress = address;
            stats.LastAddressMin = _cmdFifoAddressMin;
            stats.LastAddressMax = _cmdFifoAddressMax;
        }
        else
        {
            int delta = address - stats.LastAddress;
            if (delta == 4)
                stats.SequentialWrites++;
            else if (delta < 0)
                stats.BackwardJumps++;
            else if (delta > 4)
                stats.ForwardGaps++;
            if (_cmdFifoAddressMin != stats.LastAddressMin ||
                _cmdFifoAddressMax != stats.LastAddressMax)
            {
                stats.WindowChanges++;
            }
            stats.MinAddress = Math.Min(stats.MinAddress, address);
            stats.MaxAddress = Math.Max(stats.MaxAddress, address);
        }
        stats.LastAddress = address;
        stats.LastValue = value;
        stats.LastDepth = _cmdFifoDepth;
        stats.LastHoles = _cmdFifoHoles;
        stats.LastAddressMin = _cmdFifoAddressMin;
        stats.LastAddressMax = _cmdFifoAddressMax;
    }

    private string FormatCommandFifoWritePcStats()
    {
        if (_commandFifoWritePcStats.Count == 0)
            return "none";

        return string.Join(",", _commandFifoWritePcStats
            .OrderByDescending(pair => pair.Value.DepthDelta)
            .ThenByDescending(pair => pair.Value.Total)
            .ThenBy(pair => pair.Key)
            .Take(10)
            .Select(pair =>
                $"0x{pair.Key:x16}:{pair.Value.Total}/dd{pair.Value.DepthDelta}/hd{pair.Value.HolesDelta}" +
                $"/m{string.Join('-', pair.Value.ModeCounts)}" +
                $"/span{pair.Value.FirstAddress:X}-{pair.Value.LastAddress:X}:{pair.Value.MinAddress:X}-{pair.Value.MaxAddress:X}" +
                $"/seq{pair.Value.SequentialWrites}:back{pair.Value.BackwardJumps}:gap{pair.Value.ForwardGaps}:win{pair.Value.WindowChanges}" +
                $"/last0x{pair.Value.LastAddress:X}:0x{pair.Value.LastValue:X8}:d{pair.Value.LastDepth}:h{pair.Value.LastHoles}:a{pair.Value.LastAddressMin:X}-{pair.Value.LastAddressMax:X}"));
    }

    private void CountCommandFifoRegisterReadPc(uint register, uint value)
    {
        if (!_profileCommandFifoPacketPcs ||
            register is not (RegCmdFifoRdPtr or RegCmdFifoDepth or RegCmdFifoHoles))
        {
            return;
        }

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if (pc == 0)
            return;

        if (!_commandFifoRegisterReadPcStats.TryGetValue(pc, out CommandFifoRegisterReadPcStats? stats))
        {
            stats = new CommandFifoRegisterReadPcStats();
            _commandFifoRegisterReadPcStats[pc] = stats;
        }

        stats.Total++;
        int slot = register == RegCmdFifoRdPtr ? 0 : register == RegCmdFifoDepth ? 1 : 2;
        stats.RegisterCounts[slot]++;
        stats.LastRegister = register;
        stats.LastValue = value;
        stats.LastReadIndex = _cmdFifoReadIndex;
        stats.LastDepth = _cmdFifoDepth;
        stats.LastHoles = _cmdFifoHoles;
        if (register == RegCmdFifoDepth)
        {
            stats.DepthReads++;
            stats.LastDepthValue = value;
            stats.MaxDepthValue = Math.Max(stats.MaxDepthValue, value);
        }
    }

    private string FormatCommandFifoRegisterReadPcStats()
    {
        if (_commandFifoRegisterReadPcStats.Count == 0)
            return "none";

        return string.Join(",", _commandFifoRegisterReadPcStats
            .OrderByDescending(pair => pair.Value.Total)
            .ThenByDescending(pair => pair.Value.DepthReads)
            .ThenBy(pair => pair.Key)
            .Take(10)
            .Select(pair =>
                $"0x{pair.Key:x16}:{pair.Value.Total}/r{string.Join('-', pair.Value.RegisterCounts)}" +
                $"/dr{pair.Value.DepthReads}:lastd{pair.Value.LastDepthValue}:maxd{pair.Value.MaxDepthValue}" +
                $"/last{pair.Value.LastRegister:X}:0x{pair.Value.LastValue:X}:rd{pair.Value.LastReadIndex:X}:d{pair.Value.LastDepth}:h{pair.Value.LastHoles}"));
    }

    private void CountCommandFifoRegisterWritePc(uint register, uint value)
    {
        if (!_profileCommandFifoPacketPcs ||
            register is not (RegCmdFifoBaseAddr or RegCmdFifoRdPtr or RegCmdFifoAddressMin or RegCmdFifoAddressMax or RegCmdFifoDepth or RegCmdFifoHoles))
        {
            return;
        }

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if (pc == 0)
            return;

        if (!_commandFifoRegisterWritePcStats.TryGetValue(pc, out CommandFifoRegisterWritePcStats? stats))
        {
            stats = new CommandFifoRegisterWritePcStats();
            _commandFifoRegisterWritePcStats[pc] = stats;
        }

        stats.Total++;
        stats.RegisterCounts[CommandFifoRegisterProfileSlot(register)]++;
        stats.LastRegister = register;
        stats.LastValue = value;
        stats.LastReadIndex = _cmdFifoReadIndex;
        stats.LastAddressMin = _cmdFifoAddressMin;
        stats.LastAddressMax = _cmdFifoAddressMax;
        stats.LastDepth = _cmdFifoDepth;
        stats.LastHoles = _cmdFifoHoles;
        if (register == RegCmdFifoDepth)
        {
            stats.DepthWrites++;
            stats.LastDepthValue = value;
            stats.MaxDepthValue = Math.Max(stats.MaxDepthValue, value);
        }
    }

    private static int CommandFifoRegisterProfileSlot(uint register)
        => register switch
        {
            RegCmdFifoBaseAddr => 0,
            RegCmdFifoRdPtr => 1,
            RegCmdFifoAddressMin => 2,
            RegCmdFifoAddressMax => 3,
            RegCmdFifoDepth => 4,
            RegCmdFifoHoles => 5,
            _ => 6
        };

    private string FormatCommandFifoRegisterWritePcStats()
    {
        if (_commandFifoRegisterWritePcStats.Count == 0)
            return "none";

        return string.Join(",", _commandFifoRegisterWritePcStats
            .OrderByDescending(pair => pair.Value.Total)
            .ThenByDescending(pair => pair.Value.DepthWrites)
            .ThenBy(pair => pair.Key)
            .Take(10)
            .Select(pair =>
                $"0x{pair.Key:x16}:{pair.Value.Total}/r{string.Join('-', pair.Value.RegisterCounts)}" +
                $"/dw{pair.Value.DepthWrites}:lastd{pair.Value.LastDepthValue}:maxd{pair.Value.MaxDepthValue}" +
                $"/last{pair.Value.LastRegister:X}:0x{pair.Value.LastValue:X}:rd{pair.Value.LastReadIndex:X}" +
                $":a{pair.Value.LastAddressMin:X}-{pair.Value.LastAddressMax:X}:d{pair.Value.LastDepth}:h{pair.Value.LastHoles}"));
    }

    private void CountCommandFifoTargetRegisterPc(uint register, uint value)
    {
        if (!_profileCommandFifoPacketPcs)
            return;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if (pc == 0)
            return;

        if (!_commandFifoTargetRegisterPcStats.TryGetValue(pc, out CommandFifoTargetRegisterPcStats? stats))
        {
            stats = new CommandFifoTargetRegisterPcStats();
            _commandFifoTargetRegisterPcStats[pc] = stats;
        }

        stats.Total++;
        stats.LastRegister = register;
        stats.LastValue = value;
        if (IsInterestingEventRegister(register))
            stats.Interesting++;
        if (register is 0xa8u or 0xa9u)
            stats.Setup++;
        if (register is RegTriangleCommand or RegFtriangleCommand)
            stats.Triangle++;
        if (register == RegFastfillCommand)
            stats.FastFill++;
        if (register == RegSwapbufferCommand)
            stats.Swap++;
        if (IsTmuTextureRegister(register))
            stats.Texture++;
        if (register is RegCmdFifoBaseAddr or RegCmdFifoRdPtr or RegCmdFifoAddressMin or RegCmdFifoAddressMax or RegCmdFifoDepth or RegCmdFifoHoles)
            stats.CommandFifo++;
        if (register < stats.LowRegisterCounts.Length)
            stats.LowRegisterCounts[register]++;
    }

    private string FormatCommandFifoTargetRegisterPcStats()
    {
        if (_commandFifoTargetRegisterPcStats.Count == 0)
            return "none";

        return string.Join(",", _commandFifoTargetRegisterPcStats
            .OrderByDescending(pair => pair.Value.Setup + pair.Value.Triangle + pair.Value.FastFill + pair.Value.Swap)
            .ThenByDescending(pair => pair.Value.Interesting)
            .ThenByDescending(pair => pair.Value.Total)
            .ThenBy(pair => pair.Key)
            .Take(10)
            .Select(pair =>
                $"0x{pair.Key:x16}:{pair.Value.Total}/i{pair.Value.Interesting}/su{pair.Value.Setup}/tri{pair.Value.Triangle}" +
                $"/ff{pair.Value.FastFill}/sw{pair.Value.Swap}/tex{pair.Value.Texture}/cf{pair.Value.CommandFifo}" +
                $"/top{FormatTopCommandFifoTargetRegisters(pair.Value)}" +
                $"/last{pair.Value.LastRegister:X}:0x{pair.Value.LastValue:X8}"));
    }

    private static string FormatTopCommandFifoTargetRegisters(CommandFifoTargetRegisterPcStats stats)
        => string.Join("-", stats.LowRegisterCounts
            .Select((count, register) => (count, register))
            .Where(item => item.count != 0)
            .OrderByDescending(item => item.count)
            .ThenBy(item => item.register)
            .Take(4)
            .Select(item => $"{item.register:X}:{item.count}"));

    private void CountCommandFifoReadyPc(bool ready, string reason)
    {
        if (!_profileCommandFifoPacketPcs)
            return;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if (pc == 0)
            return;

        if (!_commandFifoReadyPcStats.TryGetValue(pc, out CommandFifoReadyPcStats? stats))
        {
            stats = new CommandFifoReadyPcStats();
            _commandFifoReadyPcStats[pc] = stats;
        }

        stats.Total++;
        if (ready)
            stats.Ready++;
        else
            stats.NotReady++;
        stats.LastReason = reason;
        stats.LastCommand = PeekCommandFifoWord();
        stats.LastReadIndex = _cmdFifoReadIndex;
        stats.LastDepth = _cmdFifoDepth;
        stats.LastHoles = _cmdFifoHoles;
        stats.LastValid = _cmdFifoValid[CommandFifoStorageIndex(_cmdFifoReadIndex)];
        int reasonSlot = reason switch
        {
            "ready" => 0,
            "depth0" => 1,
            "read-window" => 2,
            "storage-generation" => 3,
            "skip-invalid" => 4,
            "invalid-storage" => 5,
            _ => 6
        };
        stats.ReasonCounts[reasonSlot]++;
    }

    private string FormatCommandFifoReadyPcStats()
    {
        if (_commandFifoReadyPcStats.Count == 0)
            return "none";

        return string.Join(",", _commandFifoReadyPcStats
            .OrderByDescending(pair => pair.Value.Total)
            .ThenByDescending(pair => pair.Value.Ready)
            .ThenBy(pair => pair.Key)
            .Take(10)
            .Select(pair =>
                $"0x{pair.Key:x16}:{pair.Value.Total}/y{pair.Value.Ready}/n{pair.Value.NotReady}" +
                $"/r{string.Join('-', pair.Value.ReasonCounts)}" +
                $"/last{pair.Value.LastReason}:0x{pair.Value.LastCommand:X8}:rd{pair.Value.LastReadIndex:X}:d{pair.Value.LastDepth}:h{pair.Value.LastHoles}:v{(pair.Value.LastValid ? 1 : 0)}"));
    }

    private void CountCommandFifoDecodeCallPc(
        ulong pc,
        int decodedPackets,
        int startReadIndex,
        int startDepth,
        int endReadIndex,
        uint firstCommand,
        uint lastCommand,
        uint typeMask,
        string stopReason)
    {
        if (!_profileCommandFifoPacketPcs || pc == 0)
            return;

        if (!_commandFifoDecodeCallPcStats.TryGetValue(pc, out CommandFifoDecodeCallPcStats? stats))
        {
            stats = new CommandFifoDecodeCallPcStats();
            _commandFifoDecodeCallPcStats[pc] = stats;
        }

        stats.Calls++;
        stats.Packets += decodedPackets;
        stats.MaxPackets = Math.Max(stats.MaxPackets, decodedPackets);
        if (decodedPackets <= 0)
            stats.EmptyCalls++;
        else if (typeMask == (1u << 5))
            stats.Type5OnlyCalls++;
        else if ((typeMask & ~(1u << 5)) != 0 && (typeMask & (1u << 5)) != 0)
            stats.MixedWithType5Calls++;
        else
            stats.NonType5Calls++;
        stats.LastPackets = decodedPackets;
        stats.LastStartReadIndex = startReadIndex;
        stats.LastStartDepth = startDepth;
        stats.LastEndReadIndex = endReadIndex;
        stats.LastFirstCommand = firstCommand;
        stats.LastLastCommand = lastCommand;
        stats.LastTypeMask = typeMask;
        stats.LastStopReason = stopReason;

        string triggerKey = $"{_commandFifoDecodeTrigger}@0x{pc:x16}";
        if (!_commandFifoDecodeTriggerStats.TryGetValue(triggerKey, out CommandFifoDecodeTriggerStats? triggerStats))
        {
            triggerStats = new CommandFifoDecodeTriggerStats();
            _commandFifoDecodeTriggerStats[triggerKey] = triggerStats;
        }
        triggerStats.Calls++;
        triggerStats.Packets += decodedPackets;
        if (decodedPackets <= 0)
            triggerStats.EmptyCalls++;
        else if (typeMask == (1u << 5))
            triggerStats.Type5OnlyCalls++;
        else if ((typeMask & ~(1u << 5)) != 0 && (typeMask & (1u << 5)) != 0)
            triggerStats.MixedWithType5Calls++;
        else
            triggerStats.NonType5Calls++;
        triggerStats.LastPackets = decodedPackets;
        triggerStats.LastStopReason = stopReason;
    }

    private string GetCommandFifoDecodeCallPcDebugStatus()
    {
        if (!_profileCommandFifoPacketPcs)
            return "";

        return $"cmdcall={FormatCommandFifoDecodeCallPcStats()} cmdtrig={FormatCommandFifoDecodeTriggerStats()} cmdtrigc={FormatCommandFifoDecodeTriggerCallStats()} ";
    }

    private string FormatCommandFifoDecodeCallPcStats()
    {
        if (_commandFifoDecodeCallPcStats.Count == 0)
            return "none";

        return string.Join(",", _commandFifoDecodeCallPcStats
            .OrderByDescending(pair => pair.Value.Packets)
            .ThenByDescending(pair => pair.Value.Calls)
            .ThenBy(pair => pair.Key)
            .Take(8)
            .Select(pair =>
                $"0x{pair.Key:x16}:{pair.Value.Calls}/p{pair.Value.Packets}/max{pair.Value.MaxPackets}" +
                $"/c5{pair.Value.Type5OnlyCalls}/mix{pair.Value.MixedWithType5Calls}/oth{pair.Value.NonType5Calls}/empty{pair.Value.EmptyCalls}" +
                $"/last{pair.Value.LastPackets}:rd{pair.Value.LastStartReadIndex:X}->{pair.Value.LastEndReadIndex:X}:d{pair.Value.LastStartDepth}:m{pair.Value.LastTypeMask:X}:f{pair.Value.LastFirstCommand:X8}:l{pair.Value.LastLastCommand:X8}:{pair.Value.LastStopReason}"));
    }

    private string FormatCommandFifoDecodeTriggerStats()
    {
        if (_commandFifoDecodeTriggerStats.Count == 0)
