        return string.Join(",", _commandFifoDecodeTriggerStats
            .OrderByDescending(pair => pair.Value.Packets)
            .ThenByDescending(pair => pair.Value.Calls)
            .ThenBy(pair => pair.Key)
            .Take(8)
            .Select(pair =>
