    private static bool IsInterestingEventRegister(uint register)
        => register is RegTriangleCommand or RegFtriangleCommand or RegFbzColorPath or RegFbzMode or RegLfbMode or
            RegClipLeftRight or RegClipLowYHighY or RegFastfillCommand or RegSwapbufferCommand or
            RegColor0 or RegColor1 or 0x98u or 0x99u or 0x9au or 0x9bu or 0x9cu or 0x9du or 0x9eu or
            RegFstartS or RegFstartT or RegFstartW or 0xa8u or 0xa9u or RegTextureMode or RegTextureLod or RegTextureBaseAddr;

    private void DecodeFifoType3(uint command, int wordsNeeded)
    {
        TraceType3Packet(command, wordsNeeded);
        int count = (int)((command >> 6) & 0xfu);
        int code = (int)((command >> 3) & 7u);
        ushort fallbackColor = GetDrawColor();
        int source = 1;
        ushort color = fallbackColor;
        float s0 = 0;
        float t0 = 0;
        float q0 = 1;
        float s1 = 0;
        float t1 = 0;
        float q1 = 1;
        bool hasTmu0Texture = false;
        bool hasTexture = ((command >> 15) & 1u) != 0 || ((command >> 17) & 1u) != 0;
        bool hasNonFiniteTextureCoordinate = false;

        _registers[0x98] = ((command >> 10) & 0xffu) | (((command >> 22) & 0xfu) << 16);
        for (int vertex = 0; vertex < count && source < wordsNeeded; vertex++)
        {
            if (!TryReadFloat(wordsNeeded, ref source, out float x) ||
                !TryReadFloat(wordsNeeded, ref source, out float y))
            {
                return;
            }

            float skippedWordAsS = float.NaN;
            if (((command >> 28) & 1u) != 0)
            {
                if (((command >> 10) & 3u) != 0)
                {
                    if (!TryReadWord(wordsNeeded, ref source, out uint argb))
                        return;
                    if (((command >> 10) & 1u) != 0)
                        color = PackedColorToRgb565(argb);
                }
            }
            else
            {
                if (((command >> 10) & 1u) != 0)
                {
                    if (!TryReadFloat(wordsNeeded, ref source, out float r) ||
                        !TryReadFloat(wordsNeeded, ref source, out float g) ||
                        !TryReadFloat(wordsNeeded, ref source, out float b))
                    {
                        return;
                    }
                    color = FloatColorToRgb565(r, g, b);
                }
                if (((command >> 11) & 1u) != 0)
                {
                    if (_experimentType3UseSkippedWordAsS || _experimentType3UseSkippedWordAsT)
                    {
                        if (!TryReadFloat(wordsNeeded, ref source, out skippedWordAsS))
                            return;
                    }
                    else if (!SkipWord(wordsNeeded, ref source))
                    {
                        return;
                    }
                }
            }

            if (((command >> 12) & 1u) != 0)
            {
                if (_experimentType3UseSkippedWordAsS || _experimentType3UseSkippedWordAsT)
                {
                    if (!TryReadFloat(wordsNeeded, ref source, out skippedWordAsS))
                        return;
                }
                else if (!SkipWord(wordsNeeded, ref source))
                {
                    return;
                }
            }
            if (((command >> 13) & 1u) != 0)
            {
                if (!TryReadFloat(wordsNeeded, ref source, out float wb))
                    return;
                q0 = wb;
                q1 = wb;
            }
            if (((command >> 14) & 1u) != 0)
            {
                if (!TryReadFloat(wordsNeeded, ref source, out float w0))
                    return;
                q0 = w0;
                q1 = w0;
            }
            if (((command >> 15) & 1u) != 0)
            {
                if (!TryReadFloat(wordsNeeded, ref source, out s0) ||
                    !TryReadFloat(wordsNeeded, ref source, out t0))
                {
                    return;
                }
                s1 = s0;
                t1 = t0;

                if (_experimentType3UseSkippedWordAsS &&
                    float.IsFinite(skippedWordAsS) &&
                    !float.IsFinite(s0))
                {
                    s0 = skippedWordAsS;
                    s1 = s0;
                }
                else if (_experimentType3UseSkippedWordAsT &&
                         float.IsFinite(skippedWordAsS) &&
                         !float.IsFinite(s0))
                {
                    s0 = t0;
                    t0 = skippedWordAsS;
                    s1 = s0;
                    t1 = t0;
                }
                else if (_experimentType3NonFiniteSAsX && !float.IsFinite(s0))
                {
                    s0 = x;
                    s1 = s0;
                }
                hasNonFiniteTextureCoordinate |= !float.IsFinite(s0) || !float.IsFinite(t0);
                hasTmu0Texture = true;
            }
            if (((command >> 16) & 1u) != 0 &&
                !TryReadFloat(wordsNeeded, ref source, out q1))
            {
                return;
            }
            if (((command >> 17) & 1u) != 0)
            {
                if (!TryReadFloat(wordsNeeded, ref source, out s1) ||
                    !TryReadFloat(wordsNeeded, ref source, out t1))
                {
                    return;
                }

                if (!_experimentType3SeparateTmuSt &&
                    (!_experimentType3PreferTmu0St || !hasTmu0Texture))
                {
                    s0 = s1;
                    t0 = t1;
                }
                hasNonFiniteTextureCoordinate |= !float.IsFinite(s1) || !float.IsFinite(t1);
            }

            PushSetupVertex(
                new SetupVertex(
                    SetupVertexCoordinate(x),
                    SetupType3VertexY(y),
                    color,
                    s0,
                    t0,
                    q0,
                    s1,
                    t1,
                    q1,
                    hasTexture),
                code,
                vertex,
                ((command >> 22) & 1u) != 0);
        }

        if (_fixMameCommandFifoModel && ShouldStreamCommandFifoPacketWords(command))
        {
            int dummyWords = (int)(command >> 29);
            for (int i = 0; i < dummyWords; i++)
                _ = ReadCommandFifoStreamingWord();
        }

        if (hasNonFiniteTextureCoordinate)
            TraceType3NonFiniteTexturePacket(command, wordsNeeded);
    }

    private float SetupType3VertexY(float value)
    {
        float y = SetupVertexCoordinate(value);
        return _experimentType3FlipVertexY && float.IsFinite(y)
            ? _experimentType3FlipVertexYHeight - y
            : y;
    }

    private void TraceType3Packet(uint command, int wordsNeeded)
    {
        if (!_traceType3Packets || _renderFrame < _traceType3PacketsMinFrame)
            return;

        if (_traceType3PacketCommands.Length != 0 &&
            !_traceType3PacketCommands.Contains(command))
        {
            return;
        }

        if (_traceType3PacketReadIndexes.Length != 0 &&
            !_traceType3PacketReadIndexes.Contains((ulong)_cmdFifoReadIndex) &&
            !_traceType3PacketReadIndexes.Contains((ulong)_cmdFifoReadIndex * 4UL))
        {
            return;
        }

        uint textureMode = ReadTextureSampleRegister(RegTextureMode);
        uint textureLod = ReadTextureSampleRegister(RegTextureLod);
        uint textureBase = ReadTextureSampleRegister(RegTextureBaseAddr);
        if ((_traceType3TextureModes.Length != 0 && !_traceType3TextureModes.Contains(textureMode)) ||
            (_traceType3TextureLods.Length != 0 && !_traceType3TextureLods.Contains(textureLod)) ||
            (_traceType3TextureBases.Length != 0 && !_traceType3TextureBases.Contains(textureBase)))
        {
            return;
        }
        if (_type3PacketTraceCount >= _traceType3PacketsLimit)
            return;

        _type3PacketTraceCount++;
        string packet = FormatFifoPacketWords(wordsNeeded);
        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        int packetStart = _currentCommandFifoPacketStart;
        int packetStorage = CommandFifoReadStorageIndex(packetStart);
        int readStorage = CommandFifoReadStorageIndex(_cmdFifoReadIndex);
        int validWindowLimit = Math.Min(wordsNeeded, 64);
        int validWindowWords = CountCommandFifoValidWindowWords(packetStart, validWindowLimit);
        string bulkPosition = FormatCommandFifoBulkPacketPosition(packetStart).TrimStart();
        if (bulkPosition.Length == 0)
            bulkPosition = "none";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-TYPE3] cmd=0x{command:x8} words={wordsNeeded} count={(command >> 6) & 0xfu} " +
            $"code={(command >> 3) & 7u} flags=0x{(command >> 10) & 0xffffu:x4} " +
            $"packetStart=0x{packetStart * 4:x8} rd=0x{_cmdFifoReadIndex * 4:x8} " +
            $"storage=0x{packetStorage * 4:x5} readStorage=0x{readStorage * 4:x5} " +
            $"validWindow={validWindowWords}/{validWindowLimit} mame={(_fixMameCommandFifoModel ? 1 : 0)} " +
            $"depth={_cmdFifoDepth} holes={_cmdFifoHoles} valid={_cmdFifoValidCount} bulk={bulkPosition} " +
            $"state={FormatTextureRegisterWriteStatus()} owners={FormatTmuRegisterWriterStatus(0)}:{FormatTmuRegisterWriterStatus(1)} " +
            $"w0={FormatCommandFifoStorageWordDebug(packetStart)} " +
            $"w1={FormatCommandFifoStorageWordDebug(packetStart + 1)} " +
            $"w2={FormatCommandFifoStorageWordDebug(packetStart + 2)} packet=0x{packet}{pcStatus}");
        TraceType3PacketFields(command, wordsNeeded, pcStatus);
    }

    private void TraceType3PacketFields(uint command, int wordsNeeded, string pcStatus)
    {
        if (!_traceType3PacketFields)
            return;

        int count = (int)((command >> 6) & 0xfu);
        int source = 1;
        uint setupFlags = ((command >> 10) & 0xffu) | (((command >> 22) & 0xfu) << 16);
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-TYPE3-FIELDS] cmd=0x{command:x8} words={wordsNeeded} count={count} " +
            $"code={(command >> 3) & 7u} setup=0x{setupFlags:x8} decode=current{pcStatus}");

        for (int vertex = 0; vertex < count; vertex++)
        {
            StringBuilder line = new(320);
            line.Append($"[GAUNTDL:VOODOO-TYPE3-FIELDS] v{vertex}");
            if (!AppendType3Field(line, wordsNeeded, ref source, "x") ||
                !AppendType3Field(line, wordsNeeded, ref source, "y"))
            {
                Console.WriteLine(line);
                return;
            }

            if (((command >> 28) & 1u) != 0)
            {
                if (((command >> 10) & 3u) != 0 &&
                    !AppendType3Field(line, wordsNeeded, ref source, "argb", asFloat: false))
                {
                    Console.WriteLine(line);
                    return;
                }
            }
            else
            {
                if (((command >> 10) & 1u) != 0)
                {
                    if (!AppendType3Field(line, wordsNeeded, ref source, "r") ||
                        !AppendType3Field(line, wordsNeeded, ref source, "g") ||
                        !AppendType3Field(line, wordsNeeded, ref source, "b"))
                    {
                        Console.WriteLine(line);
                        return;
                    }
                }
                if (((command >> 11) & 1u) != 0 &&
                    !AppendType3Field(line, wordsNeeded, ref source, "alpha11"))
                {
                    Console.WriteLine(line);
                    return;
                }
            }

            if (((command >> 12) & 1u) != 0 &&
                !AppendType3Field(line, wordsNeeded, ref source, "z12"))
            {
                Console.WriteLine(line);
                return;
            }
            if (((command >> 13) & 1u) != 0 &&
                !AppendType3Field(line, wordsNeeded, ref source, "wb13"))
            {
                Console.WriteLine(line);
                return;
            }
            if (((command >> 14) & 1u) != 0 &&
                !AppendType3Field(line, wordsNeeded, ref source, "w0_14"))
            {
                Console.WriteLine(line);
                return;
            }
            if (((command >> 15) & 1u) != 0)
            {
                if (!AppendType3Field(line, wordsNeeded, ref source, "s0_15") ||
                    !AppendType3Field(line, wordsNeeded, ref source, "t0_15"))
                {
                    Console.WriteLine(line);
                    return;
                }
            }
            if (((command >> 16) & 1u) != 0 &&
                !AppendType3Field(line, wordsNeeded, ref source, "w1_16"))
            {
                Console.WriteLine(line);
                return;
            }
            if (((command >> 17) & 1u) != 0)
            {
                if (!AppendType3Field(line, wordsNeeded, ref source, "s1_17") ||
                    !AppendType3Field(line, wordsNeeded, ref source, "t1_17"))
                {
                    Console.WriteLine(line);
                    return;
                }
            }

            Console.WriteLine(line);
        }

        int dummyWords = (int)(command >> 29);
        for (int i = 0; i < dummyWords; i++)
        {
            StringBuilder line = new(96);
            line.Append("[GAUNTDL:VOODOO-TYPE3-FIELDS] ");
            if (!AppendType3Field(line, wordsNeeded, ref source, $"dummy{i}", asFloat: false))
            {
                Console.WriteLine(line);
                return;
            }
            Console.WriteLine(line);
        }

        if (source != wordsNeeded)
            Console.WriteLine($"[GAUNTDL:VOODOO-TYPE3-FIELDS] consumed={source}/{wordsNeeded}");
    }

    private bool AppendType3Field(StringBuilder builder, int wordsNeeded, ref int source, string name, bool asFloat = true)
    {
        if (source >= wordsNeeded || source >= _fifoBuffer.Count)
        {
            builder.Append($" w{source}:{name}=<missing>");
            return false;
        }

        uint word = _fifoBuffer[source];
        builder.Append($" w{source}:{name}=0x{word:x8}");
        if (asFloat)
            builder.Append($"({FormatDebugFloat(FloatFromRegister(word))})");
        source++;
        return true;
    }

    private static string FormatDebugFloat(float value)
        => float.IsFinite(value) ? value.ToString("G9", CultureInfo.InvariantCulture) : value.ToString(CultureInfo.InvariantCulture);

    private string FormatFifoPacketWords(int wordsNeeded)
    {
        int count = Math.Min(wordsNeeded, Math.Min(_fifoBuffer.Count, 32));
        Span<char> wordBuffer = stackalloc char[32 * 11];
        int offset = 0;
        for (int i = 0; i < count; i++)
        {
            if (i != 0)
                wordBuffer[offset++] = '/';
            _fifoBuffer[i].TryFormat(wordBuffer[offset..], out int written, "x8");
            offset += written;
        }

        return wordBuffer[..offset].ToString();
    }

    private void TraceType3NonFiniteTexturePacket(uint command, int wordsNeeded)
    {
        if (!_traceType3NonFiniteTexture || _type3NonFiniteTextureTraceCount++ >= _traceType3NonFiniteTextureLimit)
            return;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-TYPE3-NONFINITE-ST] cmd=0x{command:x8} words={wordsNeeded} count={(command >> 6) & 0xfu} " +
            $"code={(command >> 3) & 7u} flags=0x{(command >> 10) & 0xffffu:x4} " +
            $"rd=0x{_cmdFifoReadIndex * 4:x8} depth={_cmdFifoDepth} holes={_cmdFifoHoles} packet=0x{FormatFifoPacketWords(wordsNeeded)} " +
            $"xy=({_setupVertices[0].X:F3},{_setupVertices[0].Y:F3})/({_setupVertices[1].X:F3},{_setupVertices[1].Y:F3})/({_setupVertices[2].X:F3},{_setupVertices[2].Y:F3}) " +
            $"stq=({_setupVertices[0].S:F3},{_setupVertices[0].T:F3},{_setupVertices[0].Q:F6})/({_setupVertices[1].S:F3},{_setupVertices[1].T:F3},{_setupVertices[1].Q:F6})/({_setupVertices[2].S:F3},{_setupVertices[2].T:F3},{_setupVertices[2].Q:F6}){pcStatus}");
    }

    private void DecodeFifoType5(uint command, int wordsNeeded)
    {
        int count = (int)((command >> 3) & 0x7ffffu);
        if (count <= 0 || wordsNeeded < 2 + count)
            return;

        bool streaming = _fixMameCommandFifoModel && ShouldStreamCommandFifoPacketWords(command);
        uint target = (streaming ? ReadCommandFifoStreamingWord() : _fifoBuffer[1]) / 4u;
        uint space = command >> 30;
        _fifoType5SpaceCounts[space & 3u]++;
        _fifoType5SpaceWordCounts[space & 3u] += count;
        TraceType5Payload(command, target, space, count);
        if (ShouldSkipControlLikeType5TexturePayload(command, target, space, count, streaming))
            return;

        uint targetStart = target;
        uint payloadHash = ComputeType5PayloadHash(count);
        int payloadNonZeroWords = CountType5PayloadNonZeroWords(count);
        int payloadFloatLikeWords = CountType5PayloadFloatLikeWords(count);
        _currentType5TextureWritePhysicalMinWord = -1;
        _currentType5TextureWritePhysicalMaxWord = -1;
        try
        {
            for (int i = 0; i < count; i++, target++)
            {
                uint value = streaming ? ReadCommandFifoStreamingWord() : _fifoBuffer[2 + i];
                if (space == 3)
                {
                    _currentType5TextureWriteActive = true;
                    _currentType5TextureWriteCommand = command;
                    _currentType5TextureWriteSpace = space;
                    _currentType5TextureWriteTargetStart = targetStart;
                    _currentType5TextureWriteTargetWord = target;
                    _currentType5TextureWritePayloadHash = payloadHash;
                    _currentType5TextureWritePayloadNonZeroWords = payloadNonZeroWords;
                    _currentType5TextureWritePayloadFloatLikeWords = payloadFloatLikeWords;
                    _currentType5TextureWriteIndex = i;
                    _currentType5TextureWriteCount = count;
                    _currentType5TextureWriteStreaming = streaming;
                    _currentType5TextureWriteReadIndex = _cmdFifoReadIndex;
                    if (_fixType5TextureEndian)
                        value = BinaryPrimitives.ReverseEndianness(value);
                    WriteTexturePort32(target, value);
                }
                else if (space == 0 && (_fixMameCommandFifoModel || _fixType5Space0CommandFifoRam))
                {
                    if (_experimentMameCommandFifoSpace0Endian)
                        value = BinaryPrimitives.ReverseEndianness(value);
                    int storageIndex = CommandFifoStorageIndex((int)target);
                    _cmdFifoRam[storageIndex] = value;
                    RecordCommandFifoStorageLastWrite(
                        storageIndex,
                        (int)target,
                        (int)(target << 2),
                        value,
                        CmdFifoStorageWriteSourceType5Space0);
                }
                else if (space is 0 or 2)
                    WriteLfb32(target << 2, value);
            }

            TraceType5TextureUploadSequence(command, targetStart, space, count, streaming);
            TraceType5PayloadTile(command, targetStart, space, count, streaming, payloadHash, payloadNonZeroWords, payloadFloatLikeWords);
        }
        finally
        {
            _currentType5TextureWriteActive = false;
            _currentType5TextureWritePayloadFloatLikeWords = 0;
        }
    }

    private uint ComputeType5PayloadHash(int count)
    {
        int payloadWords = Math.Min(count, Math.Max(0, _fifoBuffer.Count - 2));
        uint hash = 2166136261u;
        for (int i = 0; i < payloadWords; i++)
        {
            uint value = _fifoBuffer[i + 2];
            if (_fixType5TextureEndian)
                value = BinaryPrimitives.ReverseEndianness(value);
            hash ^= value;
            hash *= 16777619u;
        }

        return hash;
    }

    private int CountType5PayloadNonZeroWords(int count)
    {
        int payloadWords = Math.Min(count, Math.Max(0, _fifoBuffer.Count - 2));
        int nonZero = 0;
        for (int i = 0; i < payloadWords; i++)
        {
            uint value = _fifoBuffer[i + 2];
            if (_fixType5TextureEndian)
                value = BinaryPrimitives.ReverseEndianness(value);
            if (value != 0)
                nonZero++;
        }

        return nonZero;
    }

    private int CountType5PayloadFloatLikeWords(int count)
    {
        int payloadWords = Math.Min(count, Math.Max(0, _fifoBuffer.Count - 2));
        int floatLike = 0;
        for (int i = 0; i < payloadWords; i++)
        {
            uint value = _fifoBuffer[i + 2];
            if (_fixType5TextureEndian)
                value = BinaryPrimitives.ReverseEndianness(value);
            if (IsLikelyPackedFloatWord(value) ||
                IsLikelyPackedFloatWord(BinaryPrimitives.ReverseEndianness(value)))
            {
                floatLike++;
            }
        }

        return floatLike;
    }

    private static bool IsLikelyPackedFloatWord(uint value)
    {
        byte top = (byte)(value >> 24);
        return top is >= 0x3c and <= 0x3f or >= 0xbc and <= 0xbf;
    }

    private void TraceType5TextureUploadSequence(uint command, uint targetStart, uint space, int count, bool streaming)
    {
        if (!_traceType5TextureUploadSequences ||
            space != 3 ||
            _type5TextureUploadSequenceTraceCount >= _traceType5TextureUploadSequenceLimit)
        {
            return;
        }

        if (_traceType5TextureUploadSequenceTargetWords.Length != 0 &&
            !_traceType5TextureUploadSequenceTargetWords.Contains(targetStart))
        {
            return;
        }

        int tmu = (int)((targetStart >> 19) & 0x03u);
        uint textureBase = ReadTextureUploadRegister(tmu, RegTextureBaseAddr);
        if (_traceType5TextureUploadSequenceTextureBase.HasValue &&
            textureBase != (uint)_traceType5TextureUploadSequenceTextureBase.Value)
        {
            return;
        }

        int sourceStorageIndex = CommandFifoReadStorageIndex(_currentCommandFifoPacketStart);
        bool hasBulkSource = _cmdFifoStorageBulkWriteSources.TryGetValue(
            sourceStorageIndex,
            out CommandFifoStorageBulkWriteSource bulkSource);
        if (_traceType5TextureUploadSequenceSource.HasValue &&
            (!hasBulkSource ||
             !MatchesType5TextureUploadSequenceSource(bulkSource, (uint)_traceType5TextureUploadSequenceSource.Value)))
        {
            return;
        }

        if ((_traceType5TextureUploadSequencePhysicalWordMin.HasValue ||
             _traceType5TextureUploadSequencePhysicalWordMax.HasValue) &&
            (_currentType5TextureWritePhysicalMinWord < 0 ||
             (_traceType5TextureUploadSequencePhysicalWordMin.HasValue &&
              (ulong)_currentType5TextureWritePhysicalMaxWord < _traceType5TextureUploadSequencePhysicalWordMin.Value) ||
             (_traceType5TextureUploadSequencePhysicalWordMax.HasValue &&
              (ulong)_currentType5TextureWritePhysicalMinWord > _traceType5TextureUploadSequencePhysicalWordMax.Value)))
        {
            return;
        }

        _type5TextureUploadSequenceTraceCount++;

        int payloadAvailable = Math.Max(0, _fifoBuffer.Count - 2);
        int payloadWords = Math.Min(count, payloadAvailable);
        int nonZero = CountType5PayloadNonZeroWords(count);
        uint hash = ComputeType5PayloadHash(count);
        uint first = 0;
        uint last = 0;
        for (int i = 0; i < payloadWords; i++)
        {
            uint value = _fifoBuffer[i + 2];
            if (_fixType5TextureEndian)
                value = BinaryPrimitives.ReverseEndianness(value);
            if (i == 0)
                first = value;
            last = value;
        }

        string physicalSpan = _currentType5TextureWritePhysicalMinWord < 0
            ? "phys=-"
            : $"phys=0x{_currentType5TextureWritePhysicalMinWord:X5}-0x{_currentType5TextureWritePhysicalMaxWord:X5}";
        string rawWords = payloadWords > 0 && _traceType5TextureUploadSequenceWords > 0
            ? $" rawWords={FormatType5PayloadWordList(count, _traceType5TextureUploadSequenceWords, decoded: false)} decWords={FormatType5PayloadWordList(count, _traceType5TextureUploadSequenceWords, decoded: true)}"
            : "";
        string storageWords = payloadWords > 0
            ? $" storage=hdr[{FormatCommandFifoStorageWordDebug(_currentCommandFifoPacketStart)}] target[{FormatCommandFifoStorageWordDebug(_currentCommandFifoPacketStart + 1)}] first[{FormatCommandFifoStorageWordDebug(_currentCommandFifoPacketStart + 2)}]"
            : "";
        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        string textureState =
            $" tmu={tmu} " +
            $"tmode=0x{ReadTextureUploadRegister(tmu, RegTextureMode):X8} " +
            $"tlod=0x{ReadTextureUploadRegister(tmu, RegTextureLod):X8} " +
            $"tbase=0x{textureBase:X8}";
        string sourceStatus = hasBulkSource
            ? $" source=0x{bulkSource.Source:x16}/root=0x{GetType5TextureUploadSequenceSourceRoot(bulkSource):x8}/base=0x{bulkSource.SourceBase:x8}/packetSource=0x{bulkSource.PacketSourceAddress:x8}/packet={bulkSource.Packet}/index={bulkSource.Index}/{bulkSource.Limit}"
            : " source=-";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-TYPE5-TEXSEQ] n={_type5TextureUploadSequenceTraceCount} " +
            $"cmd=0x{command:X8} target=0x{targetStart:X6}-0x{targetStart + (uint)Math.Max(0, count - 1):X6} " +
            $"count={count} payload={payloadWords} nz={nonZero} hash=0x{hash:X8} first=0x{first:X8} last=0x{last:X8} " +
            $"{physicalSpan} packet=0x{_currentCommandFifoPacketStart * 4:X8} rd=0x{_currentType5TextureWriteReadIndex * 4:X8} " +
            $"stream={(streaming ? 1 : 0)} depth={_cmdFifoDepth} holes={_cmdFifoHoles}{textureState}{sourceStatus}{storageWords}{rawWords}{pcStatus}");
    }

    private static bool MatchesType5TextureUploadSequenceSource(
        CommandFifoStorageBulkWriteSource source,
        uint filter)
        => (uint)source.Source == filter || GetType5TextureUploadSequenceSourceRoot(source) == filter;

    private static uint GetType5TextureUploadSequenceSourceRoot(CommandFifoStorageBulkWriteSource source)
        => unchecked((uint)source.Source - source.Index * source.PayloadWords * 4u);

    private void TraceType5PayloadTile(
        uint command,
        uint targetStart,
        uint space,
        int count,
        bool streaming,
        uint payloadHash,
        int payloadNonZeroWords,
        int payloadFloatLikeWords)
    {
        if (string.IsNullOrWhiteSpace(_traceType5PayloadTilePrefix) ||
            space != 3 ||
            command != 0xc0000205u ||
            count <= 0 ||
            streaming ||
            _type5PayloadTileDumpCount >= _traceType5PayloadTileLimit)
        {
            return;
        }

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if (_traceType5PayloadTilePcs.Length != 0 &&
            !_traceType5PayloadTilePcs.Contains(pc & 0xffffffffUL))
        {
            return;
        }

        if (_traceType5PayloadTileTargetWords.Length != 0 &&
            !_traceType5PayloadTileTargetWords.Contains(targetStart))
        {
            return;
        }

        int payloadWords = Math.Min(count, Math.Max(0, _fifoBuffer.Count - 2));
        if (payloadWords <= 0)
            return;

        uint[] words = new uint[payloadWords];
        for (int i = 0; i < payloadWords; i++)
        {
            uint value = _fifoBuffer[i + 2];
            if (_fixType5TextureEndian)
                value = BinaryPrimitives.ReverseEndianness(value);
            words[i] = value;
        }

        Type5PayloadImageStats stats = ComputeType5PayloadImageStats(words, payloadNonZeroWords, payloadFloatLikeWords);
        if (stats.Score < _traceType5PayloadTileMinScore)
            return;

        _type5PayloadTileCandidateCount++;
        if (_type5PayloadTileCandidateCount <= _traceType5PayloadTileSkip)
            return;

        ulong pcKey = pc & 0xffffffffUL;
        if (_traceType5PayloadTilePerPcLimit > 0)
        {
            _type5PayloadTileDumpCountsByPc.TryGetValue(pcKey, out int pcDumpCount);
            if (pcDumpCount >= _traceType5PayloadTilePerPcLimit)
                return;
            _type5PayloadTileDumpCountsByPc[pcKey] = pcDumpCount + 1;
        }

        _type5PayloadTileDumpCount++;
        string directory = Path.GetDirectoryName(_traceType5PayloadTilePrefix) ?? "";
        if (!string.IsNullOrWhiteSpace(directory))
            Directory.CreateDirectory(directory);

        string path = $"{_traceType5PayloadTilePrefix}-{_type5PayloadTileDumpCount:D3}-pc{pcKey:x8}-t{targetStart:X5}-h{payloadHash:X8}-s{stats.Score}.ppm";
        DumpType5PayloadTileSheet(path, words);
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-TYPE5-PAYLOAD-TILE] n={_type5PayloadTileDumpCount} path={path} " +
            $"score={stats.Score} cmd=0x{command:X8} target=0x{targetStart:X6}-0x{targetStart + (uint)Math.Max(0, count - 1):X6} " +
            $"count={count} payload={stats.PayloadWords} hash=0x{payloadHash:X8} nz={stats.NonZeroWords} flt={stats.FloatLikeWords} " +
            $"uniqB={stats.UniqueBytes} trans={stats.ByteTransitions} zeroB={stats.ZeroBytes} satB={stats.SaturatedBytes} " +
            $"rgbNz={stats.Rgb565NonZero} rgbChg={stats.Rgb565ColorChanges} pc=0x{pc:x16} packet=0x{_currentCommandFifoPacketStart * 4:X8}");
    }

    private static Type5PayloadImageStats ComputeType5PayloadImageStats(uint[] words, int nonZeroWords, int floatLikeWords)
    {
        bool[] seenBytes = new bool[256];
        int uniqueBytes = 0;
        int zeroBytes = 0;
        int saturatedBytes = 0;
        int transitions = 0;
        int previousByte = -1;
        int rgb565NonZero = 0;
        int rgb565ColorChanges = 0;
        ushort previousRgb = 0;
        bool hasPreviousRgb = false;

        for (int i = 0; i < words.Length; i++)
        {
            uint word = words[i];
            for (int lane = 0; lane < 4; lane++)
            {
                int value = (int)((word >> (lane * 8)) & 0xffu);
                if (!seenBytes[value])
                {
                    seenBytes[value] = true;
                    uniqueBytes++;
                }
                if (value == 0)
                    zeroBytes++;
                if (value is 0xff or 0x7f or 0x80)
                    saturatedBytes++;
                if (previousByte >= 0 && value != previousByte)
                    transitions++;
                previousByte = value;
            }

            for (int half = 0; half < 2; half++)
            {
                ushort rgb = (ushort)((word >> (half * 16)) & 0xffffu);
                if (rgb != 0)
                    rgb565NonZero++;
                if (hasPreviousRgb && rgb != previousRgb)
                    rgb565ColorChanges++;
                previousRgb = rgb;
                hasPreviousRgb = true;
            }
        }

        int byteCount = Math.Max(1, words.Length * 4);
        int halfCount = Math.Max(1, words.Length * 2);
        int zeroPenalty = zeroBytes * 120 / byteCount;
        int saturationPenalty = saturatedBytes * 60 / byteCount;
        int floatPenalty = floatLikeWords * 220 / Math.Max(1, words.Length);
        int transitionScore = Math.Min(120, transitions * 160 / byteCount);
        int uniqueScore = Math.Min(160, uniqueBytes * 2);
        int rgbScore = Math.Min(100, rgb565ColorChanges * 140 / halfCount) + Math.Min(80, rgb565NonZero * 100 / halfCount);
        int nonZeroScore = Math.Min(80, nonZeroWords * 120 / Math.Max(1, words.Length));
        int score = uniqueScore + transitionScore + rgbScore + nonZeroScore - zeroPenalty - saturationPenalty - floatPenalty;

        return new Type5PayloadImageStats(
            score,
            words.Length,
            nonZeroWords,
            floatLikeWords,
            uniqueBytes,
            transitions,
            zeroBytes,
            saturatedBytes,
            rgb565NonZero,
            rgb565ColorChanges);
    }

    private static void DumpType5PayloadTileSheet(string path, uint[] words)
    {
        const int width = 128;
        const int height = 96;
        byte[] pixels = new byte[width * height * 3];
        Array.Fill<byte>(pixels, 0x10);

        DrawType5PayloadBytePanel(pixels, width, 0, 0, words, grayscale: false);
        DrawType5PayloadBytePanel(pixels, width, 0, 32, words, grayscale: true);
        DrawType5PayloadRgb565Panel(pixels, width, 0, 64, words, byteSwap: false);
        DrawType5PayloadRgb565Panel(pixels, width, 64, 64, words, byteSwap: true);

        using var stream = File.Create(path);
        using var writer = new StreamWriter(stream, Encoding.ASCII, leaveOpen: true);
        writer.Write($"P6\n{width} {height}\n255\n");
        writer.Flush();
        stream.Write(pixels, 0, pixels.Length);
    }

    private static void DrawType5PayloadBytePanel(byte[] pixels, int stridePixels, int originX, int originY, uint[] words, bool grayscale)
    {
        int byteCount = words.Length * 4;
        for (int i = 0; i < byteCount; i++)
        {
            byte value = (byte)((words[i >> 2] >> ((i & 3) * 8)) & 0xffu);
            byte r;
            byte g;
            byte b;
            if (grayscale)
            {
                r = g = b = value;
            }
            else
            {
                ushort rgb = ConvertRgb332ToRgb565(value);
                Rgb565ToBytes(rgb, out int ri, out int gi, out int bi);
                r = (byte)ri;
                g = (byte)gi;
                b = (byte)bi;
            }

            DrawScaledPixel(pixels, stridePixels, originX + (i & 31) * 4, originY + (i >> 5) * 4, 4, r, g, b);
        }
    }

    private static void DrawType5PayloadRgb565Panel(byte[] pixels, int stridePixels, int originX, int originY, uint[] words, bool byteSwap)
    {
        int halfCount = words.Length * 2;
        for (int i = 0; i < halfCount; i++)
        {
            ushort rgb = (ushort)((words[i >> 1] >> ((i & 1) * 16)) & 0xffffu);
            if (byteSwap)
                rgb = BinaryPrimitives.ReverseEndianness(rgb);
            Rgb565ToBytes(rgb, out int r, out int g, out int b);
            DrawScaledPixel(pixels, stridePixels, originX + (i & 15) * 4, originY + (i >> 4) * 4, 4, (byte)r, (byte)g, (byte)b);
        }
    }

    private static void DrawScaledPixel(byte[] pixels, int stridePixels, int x, int y, int scale, byte r, byte g, byte b)
    {
        for (int dy = 0; dy < scale; dy++)
        {
            int row = (y + dy) * stridePixels * 3;
            for (int dx = 0; dx < scale; dx++)
            {
                int offset = row + (x + dx) * 3;
                if ((uint)offset >= (uint)(pixels.Length - 2))
                    continue;
                pixels[offset] = r;
                pixels[offset + 1] = g;
                pixels[offset + 2] = b;
            }
        }
    }

    private bool ShouldSkipControlLikeType5TexturePayload(uint command, uint targetWord, uint space, int count, bool streaming)
    {
        if (!_experimentSkipControlLikeType5TexturePayloads || space != 3 || count <= 0 || streaming)
            return false;

        if (_experimentSkipControlLikeType5TexturePayloadTargets.Length != 0 &&
            !_experimentSkipControlLikeType5TexturePayloadTargets.Contains(targetWord))
            return false;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if (_experimentSkipControlLikeType5TexturePayloadPcs.Length != 0 &&
            !MatchesTracePc(_experimentSkipControlLikeType5TexturePayloadPcs, pc))
            return false;

        int available = Math.Max(0, _fifoBuffer.Count - 2);
        int words = Math.Min(count, Math.Min(12, available));
        if (words < 6)
            return false;

        int zeroWords = 0;
        int low16Words = 0;
        for (int i = 0; i < words; i++)
        {
            uint value = _fifoBuffer[i + 2];
            if (value == 0)
                zeroWords++;
            if ((value & 0xffff0000u) == 0)
                low16Words++;
        }

        if (low16Words < Math.Max(6, words - 1))
            return false;

        if (_controlLikeType5TexturePayloadSkipTraceCount++ < _experimentSkipControlLikeType5TexturePayloadTraceLimit)
        {
            string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
            Console.WriteLine(
                $"[GAUNTDL:EXPERIMENT] skip-control-like-type5-texture-payload cmd=0x{command:x8} " +
                $"space={space} targetWord=0x{targetWord:x8} count={count} sampledWords={words} " +
                $"low16={low16Words} zero={zeroWords} rawWords={FormatType5PayloadWordList(count, Math.Min(words, 8), decoded: false)}{pcStatus}");
        }

        return true;
    }

    private void TraceType5Payload(uint command, uint targetWord, uint space, int count)
    {
        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        if (!MatchesType5PayloadPcFilter(pc))
            return;

        bool focusedTarget = _traceType5PayloadTargetWords.Contains(targetWord);
        if (!_traceType5Payloads && !focusedTarget)
            return;

        int nonZero = 0;
        uint first = count > 0 && _fifoBuffer.Count > 2 ? _fifoBuffer[2] : 0;
        uint second = count > 1 && _fifoBuffer.Count > 3 ? _fifoBuffer[3] : 0;
        uint last = 0;
        for (int i = 0; i < count && i + 2 < _fifoBuffer.Count; i++)
        {
            uint value = _fifoBuffer[i + 2];
            if (value != 0)
                nonZero++;
            last = value;
        }

        if (_traceType5PayloadDedup && !RememberType5PayloadTrace(pc, command, targetWord, space, count))
            return;

        bool focusedZeroTarget = space == 3 && targetWord == 0 && count == 64;
        bool focusedAfterCap = _type5PayloadTraceCount >= 96;
        if (focusedTarget)
        {
            if (_type5PayloadFocusedTargetTraceCount++ >= _traceType5PayloadTargetLimit)
                return;
        }
        else if (focusedAfterCap)
        {
            if (!focusedZeroTarget || _type5PayloadFocusedZeroTargetTraceCount++ >= 64)
                return;
        }
        else
        {
            _type5PayloadTraceCount++;
        }

        uint decodedFirst = _fixType5TextureEndian ? BinaryPrimitives.ReverseEndianness(first) : first;
        uint decodedSecond = _fixType5TextureEndian ? BinaryPrimitives.ReverseEndianness(second) : second;
        uint decodedLast = _fixType5TextureEndian ? BinaryPrimitives.ReverseEndianness(last) : last;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        uint targetByte = _fifoBuffer.Count > 1 ? _fifoBuffer[1] : targetWord << 2;
        string storageStatus = focusedTarget
            ? $" targetByte=0x{targetByte:x8} " +
              $"w0={FormatCommandFifoStorageWordDebug(_currentCommandFifoPacketStart)} " +
              $"w1={FormatCommandFifoStorageWordDebug(_currentCommandFifoPacketStart + 1)} " +
              $"w2={FormatCommandFifoStorageWordDebug(_currentCommandFifoPacketStart + 2)}"
            : "";
        string wordStatus = focusedTarget && _traceType5PayloadWords > 0
            ? $" rawWords={FormatType5PayloadWordList(count, _traceType5PayloadWords, decoded: false)} decWords={FormatType5PayloadWordList(count, _traceType5PayloadWords, decoded: true)}"
            : "";
        string tag = focusedTarget ? "VOODOO-TYPE5-TARGET" : focusedAfterCap ? "VOODOO-TYPE5-FOCUS" : "VOODOO-TYPE5";
        Console.WriteLine(
            $"[GAUNTDL:{tag}] cmd=0x{command:x8} space={space} targetWord=0x{targetWord:x8} " +
            $"count={count} nz={nonZero} first=0x{first:x8}/dec=0x{decodedFirst:x8} " +
            $"second=0x{second:x8}/dec=0x{decodedSecond:x8} last=0x{last:x8}/dec=0x{decodedLast:x8} " +
            $"packet=0x{_currentCommandFifoPacketStart * 4:x8} rd=0x{_cmdFifoReadIndex * 4:x8} " +
            $"depth={_cmdFifoDepth} holes={_cmdFifoHoles}{storageStatus}{wordStatus}{pcStatus}");
    }

    private bool MatchesType5PayloadPcFilter(ulong pc)
    {
        if (_traceType5PayloadPcs.Length == 0)
            return true;
        if (MatchesTracePc(_traceType5PayloadPcs, pc))
            return true;

        for (int i = 0; i < 3; i++)
        {
            int storageIndex = CommandFifoReadStorageIndex(_currentCommandFifoPacketStart + i);
            if (MatchesTracePc(_traceType5PayloadPcs, _cmdFifoStorageLastWritePc[storageIndex]))
                return true;
        }

        return false;
    }

    private bool RememberType5PayloadTrace(ulong pc, uint command, uint targetWord, uint space, int count)
    {
        string key = $"{pc:x16}/{command:x8}/{space:x}/{targetWord:x8}/{count:x}/{FormatType5PayloadWordList(count, 8, decoded: false)}";
        return _traceType5PayloadDedupKeys.Add(key);
    }

    private static bool MatchesTracePc(ulong[] pcs, ulong pc)
        => pcs.Contains(pc) || pcs.Contains(pc & 0xffffffffUL);

    private string FormatType5PayloadWordList(int count, int limit, bool decoded)
    {
        int words = Math.Min(count, Math.Min(limit, Math.Max(0, _fifoBuffer.Count - 2)));
        StringBuilder builder = new(words * 11);
        for (int i = 0; i < words; i++)
        {
            if (i > 0)
                builder.Append('/');

            uint value = _fifoBuffer[i + 2];
            if (decoded && _fixType5TextureEndian)
                value = BinaryPrimitives.ReverseEndianness(value);
            builder.Append("0x");
            builder.Append(value.ToString("x8", CultureInfo.InvariantCulture));
        }

        if (words < count)
            builder.Append("/...");
        return builder.ToString();
    }

    private void BeginSetupTriangle()
    {
        SetupVertex vertex = ReadCurrentSetupVertex();
        _setupVertices[0] = vertex;
        _setupVertices[1] = vertex;
        _setupVertices[2] = vertex;
        _setupVertexCount = 1;
    }

    private void DrawSetupTriangle()
    {
        _setupTriangleCommandCount++;
        PushSetupVertex(ReadCurrentSetupVertex(), code: 1, vertexIndex: _setupVertexCount == 0 ? 0 : 1, fanMode: IsSetupFanMode());
    }

    private void DrawIntegerTriangle()
    {
        _directTriangleCommandCount++;
        ushort color = GetIntegerDrawColor();
        TraceDraw($"itri color=0x{color:X4} xy=({FixedVertexCoordinate(_registers[0x02]):F1},{FixedVertexCoordinate(_registers[0x03]):F1})/({FixedVertexCoordinate(_registers[0x04]):F1},{FixedVertexCoordinate(_registers[0x05]):F1})/({FixedVertexCoordinate(_registers[0x06]):F1},{FixedVertexCoordinate(_registers[0x07]):F1}) fbz=0x{_registers[RegFbzMode]:X8}");
        if (ShouldSuppressRgbBufferWrite())
            return;
        DrawTriangleWire(
            FixedVertexCoordinate(_registers[0x02]),
            FixedVertexCoordinate(_registers[0x03]),
            FixedVertexCoordinate(_registers[0x04]),
            FixedVertexCoordinate(_registers[0x05]),
            FixedVertexCoordinate(_registers[0x06]),
            FixedVertexCoordinate(_registers[0x07]),
            color,
            "itri");
    }

    private void DrawFloatTriangle()
    {
        _directTriangleCommandCount++;
        ushort color = GetFloatDrawColor();
        TraceDraw($"ftri color=0x{color:X4} xy=({FloatFromRegister(_registers[0x22]):F1},{FloatFromRegister(_registers[0x23]):F1})/({FloatFromRegister(_registers[0x24]):F1},{FloatFromRegister(_registers[0x25]):F1})/({FloatFromRegister(_registers[0x26]):F1},{FloatFromRegister(_registers[0x27]):F1}) rgb=({FloatFromRegister(_registers[0x28]):F3},{FloatFromRegister(_registers[0x29]):F3},{FloatFromRegister(_registers[0x2a]):F3}) fbz=0x{_registers[RegFbzMode]:X8}");
        if (ShouldSuppressRgbBufferWrite())
            return;
        if (_experimentDirectGradientTexture &&
            FillGradientTexturedTriangle(
                FloatFromRegister(_registers[0x22]),
                FloatFromRegister(_registers[0x23]),
                FloatFromRegister(_registers[0x24]),
                FloatFromRegister(_registers[0x25]),
                FloatFromRegister(_registers[0x26]),
                FloatFromRegister(_registers[0x27]),
                color))
        {
            return;
        }

        if (_experimentFloatTriangleColorGradient &&
            FillGradientColorTriangle(
                FloatFromRegister(_registers[0x22]),
                FloatFromRegister(_registers[0x23]),
                FloatFromRegister(_registers[0x24]),
                FloatFromRegister(_registers[0x25]),
                FloatFromRegister(_registers[0x26]),
                FloatFromRegister(_registers[0x27]),
                color))
        {
            return;
        }

        DrawTriangleWire(
            FloatFromRegister(_registers[0x22]),
            FloatFromRegister(_registers[0x23]),
            FloatFromRegister(_registers[0x24]),
            FloatFromRegister(_registers[0x25]),
            FloatFromRegister(_registers[0x26]),
            FloatFromRegister(_registers[0x27]),
            color,
            "ftri");
    }

    private SetupVertex ReadCurrentSetupVertex()
    {
        ushort color = PackedColorToRgb565(_registers[0x9b]);
        if (color == 0)
            color = FloatColorToRgb565(
                FloatFromRegister(_registers[0x9c]),
                FloatFromRegister(_registers[0x9d]),
                FloatFromRegister(_registers[0x9e]));
        if (color == 0)
            color = GetDrawColor();

        float s = SetupFloatOrFallback(RegFstartS, 0xa3);
        float t = SetupFloatOrFallback(RegFstartT, 0xa4);
        float q = _fixSetupRegisterTextureQ || _experimentTexturePerspectiveInterpolate
            ? SetupFloatOrFallback(RegFstartW, 0xa2)
            : 1;

        return new SetupVertex(
            SetupVertexCoordinate(_registers[0x99]),
            SetupVertexCoordinate(_registers[0x9a]),
            color,
            s,
            t,
            q,
            s,
            t,
            q,
            _registers[RegFstartS] != 0 || _registers[RegFstartT] != 0 || _registers[0xa3] != 0 || _registers[0xa4] != 0);
    }

    private float SetupFloatOrFallback(int register, int fallbackRegister)
    {
        float value = FloatFromRegister(_registers[register]);
        if (float.IsFinite(value) && _registers[register] != 0)
            return value;

        float fallback = FloatFromRegister(_registers[fallbackRegister]);
        return float.IsFinite(fallback) ? fallback : value;
    }

    private float SetupVertexCoordinate(uint registerValue)
        => SetupVertexCoordinate(FloatFromRegister(registerValue));

    private float SetupVertexCoordinate(float value)
    {
        if (!_fixSetupVertexCoordinateWrap || !float.IsFinite(value))
            return value;

        return unchecked((short)(int)(value * 16.0f)) / 16.0f;
    }

    private void PushSetupVertex(SetupVertex vertex, int code, int vertexIndex, bool fanMode)
    {
        if ((code == 1 && vertexIndex == 0) || (code == 0 && vertexIndex % 3 == 0) || _setupVertexCount == 0)
        {
            _setupVertices[0] = vertex;
            _setupVertices[1] = vertex;
            _setupVertices[2] = vertex;
            _setupVertexCount = 1;
            return;
        }

        if (!fanMode)
            _setupVertices[0] = _setupVertices[1];
        _setupVertices[1] = _setupVertices[2];
        _setupVertices[2] = vertex;
        if (++_setupVertexCount >= 3)
            DrawSetupTriangleVertices();
    }

    private void DrawSetupTriangleVertices()
    {
        ushort color = _setupVertices[2].Color != 0 ? _setupVertices[2].Color : GetDrawColor();
        bool textured = _setupVertices[0].HasTexture || _setupVertices[1].HasTexture || _setupVertices[2].HasTexture;
        TraceDraw($"stri color=0x{color:X4} xy=({_setupVertices[0].X:F1},{_setupVertices[0].Y:F1})/({_setupVertices[1].X:F1},{_setupVertices[1].Y:F1})/({_setupVertices[2].X:F1},{_setupVertices[2].Y:F1}) st=({_setupVertices[0].S:F1},{_setupVertices[0].T:F1})/({_setupVertices[1].S:F1},{_setupVertices[1].T:F1})/({_setupVertices[2].S:F1},{_setupVertices[2].T:F1}) tex={(textured ? 1 : 0)} tmode=0x{ReadTextureRegister(RegTextureMode):X8} tbase=0x{ReadTextureRegister(RegTextureBaseAddr):X8} setup=0x{_registers[0x98]:X8} fbzcp=0x{_registers[RegFbzColorPath]:X8} fbz=0x{_registers[RegFbzMode]:X8}");
        TraceSetupTriangle(color, textured);
        if (ShouldCullSetupTriangle())
            return;
        if (ShouldSuppressImplausibleSetupTriangle(textured))
            return;
        if (ShouldSuppressRgbBufferWrite() && (!_experimentSetupMameAuxDepth || !textured))
            return;
        if (_experimentDiscardType3Raster &&
            _decodingCommandFifo &&
            (_currentCommandFifoCommand & 7u) == 3u)
        {
            return;
        }
        if (textured)
            _texturedTriangleCount++;
        if (textured && FillTexturedTriangle(_setupVertices[0], _setupVertices[1], _setupVertices[2], color))
        {
            _texturedTriangleCoveredCount++;
            if (_visualizeTexturedTriangleEdges)
            {
                DrawLfbLine(_setupVertices[0].X, _setupVertices[0].Y, _setupVertices[1].X, _setupVertices[1].Y, color);
                DrawLfbLine(_setupVertices[1].X, _setupVertices[1].Y, _setupVertices[2].X, _setupVertices[2].Y, color);
                DrawLfbLine(_setupVertices[2].X, _setupVertices[2].Y, _setupVertices[0].X, _setupVertices[0].Y, color);
            }
            return;
        }

        if (textured)
            _texturedTriangleRejectedCount++;
        if (textured && _treatZeroTextureTexelAsTransparent)
            return;
        DrawTriangleWire(_setupVertices[0].X, _setupVertices[0].Y, _setupVertices[1].X, _setupVertices[1].Y, _setupVertices[2].X, _setupVertices[2].Y, color, "stri");
    }

    private bool ShouldSuppressRgbBufferWrite()
        => _fixRgbBufferMask && (_registers[RegFbzMode] & 0x400u) == 0;

    private bool ShouldCullSetupTriangle()
    {
        if (!_fixSetupCulling || ((_registers[0x98] >> 17) & 1u) == 0)
            return false;

        SetupVertex sv0 = _setupVertices[0];
        SetupVertex sv1 = _setupVertices[1];
        SetupVertex sv2 = _setupVertices[2];
        float divisor = (sv0.X - sv1.X) * (sv0.Y - sv2.Y) - (sv0.X - sv2.X) * (sv0.Y - sv1.Y);
        int cullingSign = (int)((_registers[0x98] >> 18) & 1u);
        bool fanMode = ((_registers[0x98] >> 16) & 1u) != 0;
        bool disablePingPongCorrection = ((_registers[0x98] >> 19) & 1u) != 0;
        if (!fanMode && !disablePingPongCorrection)
            cullingSign ^= (_setupVertexCount - 3) & 1;
        if (_experimentType3FlipVertexY &&
            _decodingCommandFifo &&
            (_currentCommandFifoCommand & 7u) == 3u)
        {
            cullingSign ^= 1;
        }

        int divisorSign = divisor < 0 ? 1 : 0;
        return divisorSign == cullingSign;
    }

    private bool ShouldSuppressImplausibleSetupTriangle(bool textured)
    {
        if (!_experimentSuppressImplausibleSetupTriangles ||
            !_decodingCommandFifo ||
            (_currentCommandFifoCommand & 7u) != 3u)
        {
            return false;
        }

        SetupVertex sv0 = _setupVertices[0];
        SetupVertex sv1 = _setupVertices[1];
        SetupVertex sv2 = _setupVertices[2];
        float minXf = MathF.Min(sv0.X, MathF.Min(sv1.X, sv2.X));
        float maxXf = MathF.Max(sv0.X, MathF.Max(sv1.X, sv2.X));
        float minYf = MathF.Min(sv0.Y, MathF.Min(sv1.Y, sv2.Y));
        float maxYf = MathF.Max(sv0.Y, MathF.Max(sv1.Y, sv2.Y));
        if (!float.IsFinite(minXf) || !float.IsFinite(maxXf) ||
            !float.IsFinite(minYf) || !float.IsFinite(maxYf))
        {
            TraceImplausibleSetupTriangleIgnore(textured, "nonfinite", 0);
            return true;
        }

        GetClip(out int clipX0, out int clipX1, out int clipY0, out int clipY1);
        int minX = Math.Clamp((int)MathF.Floor(minXf), clipX0, clipX1);
        int maxX = Math.Clamp((int)MathF.Ceiling(maxXf), clipX0, clipX1);
        int minY = Math.Clamp((int)MathF.Floor(minYf), clipY0, clipY1);
        int maxY = Math.Clamp((int)MathF.Ceiling(maxYf), clipY0, clipY1);
        long boxPixels = Math.Max(0, maxX - minX) * (long)Math.Max(0, maxY - minY);
        float maxAbsCoordinate = MathF.Max(
            MathF.Max(MathF.Abs(minXf), MathF.Abs(maxXf)),
            MathF.Max(MathF.Abs(minYf), MathF.Abs(maxYf)));
        bool hugeOffscreenCoordinate = maxAbsCoordinate > 8192.0f;
        bool screenFillingFromFarOutside =
            boxPixels >= 640L * 240L &&
            (minXf < -1024.0f || maxXf > 2048.0f || minYf < -1024.0f || maxYf > 2048.0f);
        if (!hugeOffscreenCoordinate && !screenFillingFromFarOutside)
            return false;

        TraceImplausibleSetupTriangleIgnore(textured, hugeOffscreenCoordinate ? "huge-coordinate" : "screen-fill-outside", boxPixels);
        return true;
    }

    private void TraceImplausibleSetupTriangleIgnore(bool textured, string reason, long boxPixels)
    {
        if (_implausibleSetupTriangleIgnoreTraceCount >= _experimentSuppressImplausibleSetupTrianglesTraceLimit)
            return;

        _implausibleSetupTriangleIgnoreTraceCount++;
        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-IMPLAUSIBLE-SETUP-TRI-IGNORE] n={_implausibleSetupTriangleIgnoreTraceCount} " +
            $"reason={reason} tex={(textured ? 1 : 0)} boxPixels={boxPixels} " +
            $"xy=({_setupVertices[0].X:F3},{_setupVertices[0].Y:F3})/({_setupVertices[1].X:F3},{_setupVertices[1].Y:F3})/({_setupVertices[2].X:F3},{_setupVertices[2].Y:F3}) " +
            $"st=({_setupVertices[0].S:F3},{_setupVertices[0].T:F3})/({_setupVertices[1].S:F3},{_setupVertices[1].T:F3})/({_setupVertices[2].S:F3},{_setupVertices[2].T:F3}) " +
            $"cmd=0x{_currentCommandFifoCommand:X8}:{_currentCommandFifoWordsNeeded}:0x{_currentCommandFifoPacketStart * 4:X8}:rd0x{_cmdFifoReadIndex * 4:X8} " +
            $"setup=0x{_registers[0x98]:X8} fbz=0x{_registers[RegFbzMode]:X8} cp=0x{_registers[RegFbzColorPath]:X8}{pcStatus}");
    }

    private void DrawTriangleWire(float ax, float ay, float bx, float by, float cx, float cy, ushort color, string source)
    {
        if (color == 0)
            color = 0xffff;

        bool filled = FillTriangle(ax, ay, bx, by, cx, cy, color, source);
        if (!filled || _experimentDisableTriangleWireEdges)
            return;

        DrawLfbLine(ax, ay, bx, by, color);
        DrawLfbLine(bx, by, cx, cy, color);
        DrawLfbLine(cx, cy, ax, ay, color);
    }

    private bool FillTriangle(float ax, float ay, float bx, float by, float cx, float cy, ushort color, string source)
    {
        if (!float.IsFinite(ax) || !float.IsFinite(ay) ||
            !float.IsFinite(bx) || !float.IsFinite(by) ||
            !float.IsFinite(cx) || !float.IsFinite(cy))
        {
            return false;
        }

        float area = Edge(ax, ay, bx, by, cx, cy);
        if (MathF.Abs(area) < 0.001f)
            return false;

        GetClip(out int clipX0, out int clipX1, out int clipY0, out int clipY1);
        int minX = Math.Clamp((int)MathF.Floor(MathF.Min(ax, MathF.Min(bx, cx))), clipX0, clipX1);
        int maxX = Math.Clamp((int)MathF.Ceiling(MathF.Max(ax, MathF.Max(bx, cx))), clipX0, clipX1);
        int minY = Math.Clamp((int)MathF.Floor(MathF.Min(ay, MathF.Min(by, cy))), clipY0, clipY1);
        int maxY = Math.Clamp((int)MathF.Ceiling(MathF.Max(ay, MathF.Max(by, cy))), clipY0, clipY1);
        if (maxX <= minX || maxY <= minY)
            return false;

        long boxPixels = Math.Max(0, maxX - minX) * (long)Math.Max(0, maxY - minY);
        TraceLargeDirectTriangle(source, color, ax, ay, bx, by, cx, cy, area, minX, maxX, minY, maxY, boxPixels);
        TraceFocusedDirectTriangle(source, color, ax, ay, bx, by, cx, cy, area, minX, maxX, minY, maxY, boxPixels);
        bool suppressImplausible = ShouldSuppressImplausibleBulkDirectTriangle(source, boxPixels);
        if (suppressImplausible)
        {
            CountSuppressedSolidTriangle(source, color, ax, ay, bx, by, cx, cy, area, minX, maxX, minY, maxY, implausible: true, large: false, offscreen: false);
            return false;
        }

        bool suppressOffscreen = ShouldSuppressOffscreenDirectTriangle(source, ax, ay, bx, by, cx, cy, boxPixels);
        if (suppressOffscreen)
        {
            CountSuppressedSolidTriangle(source, color, ax, ay, bx, by, cx, cy, area, minX, maxX, minY, maxY, implausible: false, large: false, offscreen: true);
            return false;
        }

        bool suppressLarge = _experimentSuppressLargeSolidTriangles && boxPixels >= 640L * 480L;
        if (suppressLarge)
        {
            CountSuppressedSolidTriangle(source, color, ax, ay, bx, by, cx, cy, area, minX, maxX, minY, maxY, implausible: false, large: true, offscreen: false);
            return false;
        }

        bool positive = area > 0;
        int bufferIndex = GetDrawBufferIndex();
        _lastDrawBufferIndex = bufferIndex;
        MaterializePendingClear(bufferIndex);
        InvalidateFastFillCache(bufferIndex);
        ushort[] buffer = _colorBuffers[bufferIndex];
        int writerId = GetPixelLastWriterId("solid", source, color);
        long drawnPixels = 0;
        for (int y = minY; y < maxY; y++)
        {
            float py = y + 0.5f;
            int screenY = GetRasterBufferY(y);
            int row = screenY * LfbRowPixels;
            for (int x = minX; x < maxX; x++)
            {
                float px = x + 0.5f;
                float e0 = Edge(bx, by, cx, cy, px, py);
                float e1 = Edge(cx, cy, ax, ay, px, py);
                float e2 = Edge(ax, ay, bx, by, px, py);
                if (positive ? e0 >= 0 && e1 >= 0 && e2 >= 0 : e0 <= 0 && e1 <= 0 && e2 <= 0)
                {
                    buffer[(row + x) & (LfbPixels - 1)] = color;
                    TrackPixelLastWriter(bufferIndex, x, screenY, writerId);
                    drawnPixels++;
                    _solidRasterPixelCount++;
                    if ((uint)bufferIndex < (uint)_rasterBufferPixelCounts.Length)
                        _rasterBufferPixelCounts[bufferIndex]++;
                    _lfbWriteCount++;
                }
            }
        }
        CountDrawnSolidTriangle(source, color, ax, ay, bx, by, cx, cy, area, minX, maxX, minY, maxY, drawnPixels);
        return true;
    }

    private bool ShouldSuppressImplausibleBulkDirectTriangle(string source, long boxPixels)
    {
        if (!_experimentSuppressImplausibleBulkDirectTriangles ||
            (source != "itri" && source != "ftri") ||
            boxPixels < _experimentSuppressImplausibleBulkDirectTrianglesMinBoxPixels ||
            !_decodingCommandFifo ||
            (_currentCommandFifoCommand & 7u) != 1u)
        {
            return false;
        }

        if (IsImplausibleCommandFifoPacket(_currentCommandFifoCommand, _currentCommandFifoWordsNeeded))
            return true;

        if (_commandFifoDecodeTrigger != "bulk-end")
            return false;

        uint target = (_currentCommandFifoCommand >> 3) & 0xfffu;
        int count = (int)(_currentCommandFifoCommand >> 16);
        return target >= 0x400u || count > 0x400;
    }

    private bool ShouldSuppressOffscreenDirectTriangle(
        string source,
        float ax,
        float ay,
        float bx,
        float by,
        float cx,
        float cy,
        long boxPixels)
    {
        if (!_experimentSuppressOffscreenDirectTriangles ||
            (source != "itri" && source != "ftri") ||
            !_decodingCommandFifo ||
            (_currentCommandFifoCommand & 7u) != 1u)
        {
            return false;
        }

        float minX = MathF.Min(ax, MathF.Min(bx, cx));
        float maxX = MathF.Max(ax, MathF.Max(bx, cx));
        float minY = MathF.Min(ay, MathF.Min(by, cy));
        float maxY = MathF.Max(ay, MathF.Max(by, cy));
        if (!float.IsFinite(minX) || !float.IsFinite(maxX) ||
            !float.IsFinite(minY) || !float.IsFinite(maxY))
        {
            return true;
        }

        bool farOutside =
            minX < -1024.0f || maxX > 1664.0f ||
            minY < -1024.0f || maxY > 1504.0f;
        bool screenFillOutside =
            boxPixels >= 640L * 224L &&
            (minX < -64.0f || maxX > 704.0f || minY < -64.0f || maxY > 544.0f);

        return (boxPixels >= 640L * 64L && farOutside) || screenFillOutside;
    }

    private void TraceLargeDirectTriangle(
        string source,
        ushort color,
        float ax,
        float ay,
        float bx,
        float by,
        float cx,
        float cy,
        float area,
        int minX,
        int maxX,
        int minY,
        int maxY,
        long boxPixels)
    {
        if (!_traceLargeDirectTriangles ||
            source != "itri" ||
            boxPixels < 640L * 240L ||
            _largeDirectTriangleTraceCount++ >= _traceLargeDirectTrianglesLimit)
        {
            return;
        }

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-LARGE-ITRI] n={_largeDirectTriangleTraceCount} color=0x{color:X4} " +
            $"box={minX}-{maxX}x{minY}-{maxY} pixels={boxPixels} area={area:F3} " +
            $"xy=({ax:F3},{ay:F3})/({bx:F3},{by:F3})/({cx:F3},{cy:F3}) " +
            $"rawxy=0x{_registers[0x02]:X8}/0x{_registers[0x03]:X8}/0x{_registers[0x04]:X8}/0x{_registers[0x05]:X8}/0x{_registers[0x06]:X8}/0x{_registers[0x07]:X8} " +
            $"fbz=0x{_registers[RegFbzMode]:X8} cp=0x{_registers[RegFbzColorPath]:X8} lfb=0x{_registers[RegLfbMode]:X8} " +
            $"c0=0x{_registers[RegColor0]:X8} c1=0x{_registers[RegColor1]:X8} za=0x{_registers[RegZaColor]:X8} " +
            $"cmd=0x{_currentCommandFifoCommand:X8}:{_currentCommandFifoWordsNeeded}:0x{_currentCommandFifoPacketStart * 4:X8}:rd0x{_cmdFifoReadIndex * 4:X8} " +
            $"decode={(_decodingCommandFifo ? 1 : 0)} trigger={_commandFifoDecodeTrigger} " +
            $"depth={_cmdFifoDepth} holes={_cmdFifoHoles} fifoPackets={_fifoPacketCount} draws={_fifoDrawPacketCount}{pcStatus}");
    }

    private void TraceFocusedDirectTriangle(
        string source,
        ushort color,
        float ax,
        float ay,
        float bx,
        float by,
        float cx,
        float cy,
        float area,
        int minX,
        int maxX,
        int minY,
        int maxY,
        long boxPixels)
    {
        if (_traceDirectTriangleReadIndexes.Length == 0 ||
            (source != "itri" && source != "ftri") ||
            _directTriangleReadTraceCount >= _traceDirectTriangleReadsLimit ||
            !_traceDirectTriangleReadIndexes.Contains(_cmdFifoReadIndex))
        {
            return;
        }

        _directTriangleReadTraceCount++;
        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        string raw = source == "ftri"
            ? $"rawf=0x{_registers[0x22]:X8}/0x{_registers[0x23]:X8}/0x{_registers[0x24]:X8}/0x{_registers[0x25]:X8}/0x{_registers[0x26]:X8}/0x{_registers[0x27]:X8}/rgb0x{_registers[0x28]:X8}/0x{_registers[0x29]:X8}/0x{_registers[0x2A]:X8}"
            : $"rawi=0x{_registers[0x02]:X8}/0x{_registers[0x03]:X8}/0x{_registers[0x04]:X8}/0x{_registers[0x05]:X8}/0x{_registers[0x06]:X8}/0x{_registers[0x07]:X8}/rgb0x{_registers[0x08]:X8}/0x{_registers[0x09]:X8}/0x{_registers[0x0A]:X8}";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-DIRECT-TRI-READ] n={_directTriangleReadTraceCount} source={source} color=0x{color:X4} " +
            $"box={minX}-{maxX}x{minY}-{maxY} pixels={boxPixels} area={area:F3} " +
            $"xy=({ax:F3},{ay:F3})/({bx:F3},{by:F3})/({cx:F3},{cy:F3}) {raw} " +
            $"fbz=0x{_registers[RegFbzMode]:X8} cp=0x{_registers[RegFbzColorPath]:X8} lfb=0x{_registers[RegLfbMode]:X8} " +
            $"cmd=0x{_currentCommandFifoCommand:X8}:{_currentCommandFifoWordsNeeded}:0x{_currentCommandFifoPacketStart * 4:X8}:rd0x{_cmdFifoReadIndex:X} " +
            $"trigger={_commandFifoDecodeTrigger} depth={_cmdFifoDepth} holes={_cmdFifoHoles} packetCount={_fifoPacketCount} drawPackets={_fifoDrawPacketCount}{pcStatus}");
    }

    private static float Edge(float ax, float ay, float bx, float by, float px, float py)
        => (px - ax) * (by - ay) - (py - ay) * (bx - ax);

    private int GetRasterBufferY(int y)
    {
        if (!_fixGauntletRasterYOrigin &&
            (_registers[RegFbzMode] & (1u << 17)) == 0)
        {
            return y;
        }

        int yOrigin = _fixGauntletRasterYOrigin
            ? _fixGauntletRasterYOriginHeight
            : (int)((_registers[RegFbiInit3] >> 22) & 0x3ffu);
        return Math.Clamp(yOrigin - y, 0, LfbRows - 1);
    }

    private bool FillGradientColorTriangle(
        float ax,
        float ay,
        float bx,
        float by,
        float cx,
        float cy,
        ushort fallbackColor)
    {
        if (!float.IsFinite(ax) || !float.IsFinite(ay) ||
            !float.IsFinite(bx) || !float.IsFinite(by) ||
            !float.IsFinite(cx) || !float.IsFinite(cy))
        {
            return false;
        }

        float startR = FloatFromRegister(_registers[RegFstartR]);
        float startG = FloatFromRegister(_registers[RegFstartG]);
        float startB = FloatFromRegister(_registers[RegFstartB]);
        float dRdX = FloatFromRegister(_registers[RegFdRdX]);
        float dGdX = FloatFromRegister(_registers[RegFdGdX]);
        float dBdX = FloatFromRegister(_registers[RegFdBdX]);
        float dRdY = FloatFromRegister(_registers[RegFdRdY]);
        float dGdY = FloatFromRegister(_registers[RegFdGdY]);
        float dBdY = FloatFromRegister(_registers[RegFdBdY]);
        if (!float.IsFinite(startR) || !float.IsFinite(startG) || !float.IsFinite(startB) ||
            !float.IsFinite(dRdX) || !float.IsFinite(dGdX) || !float.IsFinite(dBdX) ||
            !float.IsFinite(dRdY) || !float.IsFinite(dGdY) || !float.IsFinite(dBdY))
        {
            return false;
        }

        float area = Edge(ax, ay, bx, by, cx, cy);
        if (!float.IsFinite(area) || MathF.Abs(area) < 0.001f)
            return false;

        GetClip(out int clipX0, out int clipX1, out int clipY0, out int clipY1);
        int minX = Math.Clamp((int)MathF.Floor(MathF.Min(ax, MathF.Min(bx, cx))), clipX0, clipX1);
        int maxX = Math.Clamp((int)MathF.Ceiling(MathF.Max(ax, MathF.Max(bx, cx))), clipX0, clipX1);
        int minY = Math.Clamp((int)MathF.Floor(MathF.Min(ay, MathF.Min(by, cy))), clipY0, clipY1);
        int maxY = Math.Clamp((int)MathF.Ceiling(MathF.Max(ay, MathF.Max(by, cy))), clipY0, clipY1);
        if (maxX <= minX || maxY <= minY)
            return false;

        bool positive = area > 0;
        int bufferIndex = GetDrawBufferIndex();
        _lastDrawBufferIndex = bufferIndex;
        MaterializePendingClear(bufferIndex);
        InvalidateFastFillCache(bufferIndex);
        ushort[] buffer = _colorBuffers[bufferIndex];
        int writerId = GetPixelLastWriterId("gsolid", "direct", fallbackColor);
        bool coveredAny = false;
        for (int y = minY; y < maxY; y++)
        {
            float py = y + 0.5f;
            int screenY = GetRasterBufferY(y);
            int row = screenY * LfbRowPixels;
            for (int x = minX; x < maxX; x++)
            {
                float px = x + 0.5f;
                float e0 = Edge(bx, by, cx, cy, px, py);
                float e1 = Edge(cx, cy, ax, ay, px, py);
                float e2 = Edge(ax, ay, bx, by, px, py);
                if (!(positive ? e0 >= 0 && e1 >= 0 && e2 >= 0 : e0 <= 0 && e1 <= 0 && e2 <= 0))
                    continue;

                float dx = px - ax;
                float dy = py - ay;
                ushort color = FloatColorToRgb565(
                    startR + dx * dRdX + dy * dRdY,
                    startG + dx * dGdX + dy * dGdY,
                    startB + dx * dBdX + dy * dBdY);
                if (color == 0)
                    color = fallbackColor;

                buffer[(row + x) & (LfbPixels - 1)] = color;
                TrackPixelLastWriter(bufferIndex, x, screenY, writerId);
                coveredAny = true;
                _solidRasterPixelCount++;
                if ((uint)bufferIndex < (uint)_rasterBufferPixelCounts.Length)
                    _rasterBufferPixelCounts[bufferIndex]++;
                _lfbWriteCount++;
            }
        }

        return coveredAny;
    }

    private bool FillTexturedTriangle(SetupVertex a, SetupVertex b, SetupVertex c, ushort fallbackColor)
    {
        if (!float.IsFinite(a.X) || !float.IsFinite(a.Y) ||
            !float.IsFinite(b.X) || !float.IsFinite(b.Y) ||
            !float.IsFinite(c.X) || !float.IsFinite(c.Y))
        {
            _texturedRejectNonFiniteCount++;
            TraceTexturedTriangleReject("nonfinite-xy", a, b, c, fallbackColor, 0.0f, 0, 0, 0, 0, 0, 0, 0, 0);
            return false;
        }
        if (_experimentRejectNonFiniteTextureCoordinates &&
            (!float.IsFinite(a.S) || !float.IsFinite(a.T) ||
             !float.IsFinite(b.S) || !float.IsFinite(b.T) ||
             !float.IsFinite(c.S) || !float.IsFinite(c.T)))
        {
            _texturedRejectNonFiniteCount++;
            TraceTexturedTriangleReject("nonfinite-st", a, b, c, fallbackColor, 0.0f, 0, 0, 0, 0, 0, 0, 0, 0);
            return false;
        }

        float area = Edge(a.X, a.Y, b.X, b.Y, c.X, c.Y);
        if (!float.IsFinite(area))
        {
            _texturedRejectNonFiniteCount++;
            TraceTexturedTriangleReject("nonfinite-area", a, b, c, fallbackColor, area, 0, 0, 0, 0, 0, 0, 0, 0);
            return false;
        }
        if (MathF.Abs(area) < 0.001f)
        {
            _texturedRejectDegenerateCount++;
            TraceTexturedTriangleReject("degenerate", a, b, c, fallbackColor, area, 0, 0, 0, 0, 0, 0, 0, 0);
            return false;
        }

        GetClip(out int clipX0, out int clipX1, out int clipY0, out int clipY1);
        int minX = Math.Clamp((int)MathF.Floor(MathF.Min(a.X, MathF.Min(b.X, c.X))), clipX0, clipX1);
        int maxX = Math.Clamp((int)MathF.Ceiling(MathF.Max(a.X, MathF.Max(b.X, c.X))), clipX0, clipX1);
        int minY = Math.Clamp((int)MathF.Floor(MathF.Min(a.Y, MathF.Min(b.Y, c.Y))), clipY0, clipY1);
        int maxY = Math.Clamp((int)MathF.Ceiling(MathF.Max(a.Y, MathF.Max(b.Y, c.Y))), clipY0, clipY1);
        if (maxX <= minX || maxY <= minY)
        {
            _texturedRejectClipCount++;
            TraceTexturedTriangleReject("clip", a, b, c, fallbackColor, area, minX, maxX, minY, maxY, clipX0, clipX1, clipY0, clipY1);
            return false;
        }
        if (_experimentSuppressLargeNonFiniteSTextureTriangles &&
            !float.IsFinite(a.S) &&
            !float.IsFinite(b.S) &&
            !float.IsFinite(c.S) &&
            (long)(maxX - minX) * (maxY - minY) >= 128L * 128L)
        {
            _texturedRejectNonFiniteCount++;
            TraceTexturedTriangleReject("large-nonfinite-s", a, b, c, fallbackColor, area, minX, maxX, minY, maxY, clipX0, clipX1, clipY0, clipY1);
            return true;
        }

        bool positive = area > 0;
        int bufferIndex = GetDrawBufferIndex();
        _lastDrawBufferIndex = bufferIndex;
        MaterializePendingClear(bufferIndex);
        InvalidateFastFillCache(bufferIndex);
        ushort[] buffer = _colorBuffers[bufferIndex];
        int writerId = GetPixelLastWriterId("tex", "setup", fallbackColor);
        if (ShouldSuppressConstantSFullrectTextureTriangle(
                a,
                b,
                c,
                fallbackColor,
                area,
                minX,
                maxX,
                minY,
                maxY,
                bufferIndex))
        {
            return true;
        }

        bool remapConstantSFullrectS = _experimentConstantSFullrectUseXAsS &&
            IsConstantSFullrectTextureTriangle(a, b, c, minX, maxX, minY, maxY);
        bool remapConstantSFullrectT = _experimentConstantSFullrectUseYAsTSpan > 0 &&
            IsConstantSFullrectTextureTriangle(a, b, c, minX, maxX, minY, maxY);
        float remapConstantSScale = remapConstantSFullrectS && maxX > minX
            ? 256.0f / (maxX - minX)
            : 0.0f;
        float remapConstantTScale = remapConstantSFullrectT && maxY > minY
            ? _experimentConstantSFullrectUseYAsTSpan / (float)(maxY - minY)
            : 0.0f;
        if ((remapConstantSFullrectS || remapConstantSFullrectT) && _constantSFullrectRemapTraceCount++ < 12)
        {
            ulong pc = CpuPcProvider?.Invoke() ?? 0;
            string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
            Console.WriteLine(
                $"[GAUNTDL:EXPERIMENT] constant-s-fullrect-use-x-as-s " +
                $"n={_constantSFullrectRemapTraceCount} color=0x{fallbackColor:X4} area={area:F3} " +
                $"bbox=({minX},{minY})-({maxX},{maxY}) scale={remapConstantSScale:F6} " +
                $"tSpan={_experimentConstantSFullrectUseYAsTSpan} tScale={remapConstantTScale:F6} " +
                $"st=({a.S:F3},{a.T:F3})/({b.S:F3},{b.T:F3})/({c.S:F3},{c.T:F3}) " +
                $"cmd=0x{_currentCommandFifoCommand:X8}:0x{_currentCommandFifoPacketStart * 4:X8}:rd0x{_cmdFifoReadIndex * 4:X8}{pcStatus}");
        }

        bool coveredAny = false;
        int coveredPixels = 0;
        int zeroPixels = 0;
        uint summaryRegisterBase = _traceTexturedTriangleSampleSummaryRegisterBase.HasValue
            ? ReadTextureSampleRegister(RegTextureBaseAddr)
            : 0;
        bool traceSampleSummaryCandidate = _traceTexturedTriangleSampleSummary &&
            _renderFrame >= _traceTextureMinRenderFrame &&
            ShouldTraceTexturedTriangleSampleSummaryBuffer(bufferIndex) &&
            (!_traceTexturedTriangleSampleSummaryRegisterBase.HasValue ||
             summaryRegisterBase == (uint)_traceTexturedTriangleSampleSummaryRegisterBase.Value);
        bool traceSampleSummary = traceSampleSummaryCandidate &&
            _texturedTriangleSampleSummaryCandidateCount++ >= _traceTexturedTriangleSampleSummarySkip &&
            _texturedTriangleSampleSummaryTraceCount < _traceTexturedTriangleSampleSummaryLimit;
        Dictionary<uint, int>? sampleRawBuckets = traceSampleSummary ? [] : null;
        Dictionary<uint, int>? sampleColorBuckets = traceSampleSummary ? [] : null;
        Dictionary<uint, int>? sampleAddressBuckets = traceSampleSummary ? [] : null;
        Dictionary<TextureSampleWriterKey, int>? sampleWriterBuckets =
            traceSampleSummary &&
            (_traceTexturedTriangleSampleWriters || _traceTexturedTriangleSampleSummaryRequireWriter) ? [] : null;
        Dictionary<TextureSampleWriterKey, int>? sampleWrapped64KWriterBuckets =
            sampleWriterBuckets is not null ? [] : null;
        int[]? sampleLodCounts = traceSampleSummary && _experimentTextureMamePixelLod ? new int[9] : null;
        Dictionary<TextureSampleWriterKey, int>[]? sampleLodWriterBuckets = sampleLodCounts is not null
            ? Enumerable.Range(0, 9).Select(_ => new Dictionary<TextureSampleWriterKey, int>()).ToArray()
            : null;
        int sampleCount = 0;
        int sampleCoordCount = 0;
        uint sampleFirstAddress = uint.MaxValue;
        uint sampleLastAddress = 0;
        float sampleMinS = float.PositiveInfinity;
        float sampleMaxS = float.NegativeInfinity;
        float sampleMinT = float.PositiveInfinity;
        float sampleMaxT = float.NegativeInfinity;
        float invArea = 1.0f / area;
        double dx1 = a.Y - c.Y;
        double dx2 = a.Y - b.Y;
        double dy1 = a.X - b.X;
        double dy2 = a.X - c.X;
        // Edge() uses the opposite determinant orientation from the Voodoo
        // setup gradient numerators below.
        double setupDivisor = -1.0 / area;
        const double TextureSetupScale = 65536.0 * 65536.0;
        long startS = MameSetupCastToInt64(a.S * TextureSetupScale);
        long startT = MameSetupCastToInt64(a.T * TextureSetupScale);
        long dSdX = MameSetupCastToInt64(((a.S - b.S) * dx1 - (a.S - c.S) * dx2) * TextureSetupScale * setupDivisor);
        long dTdX = MameSetupCastToInt64(((a.T - b.T) * dx1 - (a.T - c.T) * dx2) * TextureSetupScale * setupDivisor);
        long dSdY = MameSetupCastToInt64(((a.S - c.S) * dy1 - (a.S - b.S) * dy2) * TextureSetupScale * setupDivisor);
        long dTdY = MameSetupCastToInt64(((a.T - c.T) * dy1 - (a.T - b.T) * dy2) * TextureSetupScale * setupDivisor);
        long textureStartW = MameSetupCastToInt64(a.Q * TextureSetupScale);
        long textureDwDx = MameSetupCastToInt64(((a.Q - b.Q) * dx1 - (a.Q - c.Q) * dx2) * TextureSetupScale * setupDivisor);
        long textureDwDy = MameSetupCastToInt64(((a.Q - c.Q) * dy1 - (a.Q - b.Q) * dy2) * TextureSetupScale * setupDivisor);
        float textureS1A = _experimentType3SeparateTmuSt ? a.S1 : a.S;
        float textureT1A = _experimentType3SeparateTmuSt ? a.T1 : a.T;
        float textureQ1A = _experimentType3SeparateTmuSt ? a.Q1 : a.Q;
        float textureS1B = _experimentType3SeparateTmuSt ? b.S1 : b.S;
        float textureT1B = _experimentType3SeparateTmuSt ? b.T1 : b.T;
        float textureQ1B = _experimentType3SeparateTmuSt ? b.Q1 : b.Q;
        float textureS1C = _experimentType3SeparateTmuSt ? c.S1 : c.S;
        float textureT1C = _experimentType3SeparateTmuSt ? c.T1 : c.T;
        float textureQ1C = _experimentType3SeparateTmuSt ? c.Q1 : c.Q;
        long startS1 = MameSetupCastToInt64(textureS1A * TextureSetupScale);
        long startT1 = MameSetupCastToInt64(textureT1A * TextureSetupScale);
        long dS1dX = MameSetupCastToInt64(((textureS1A - textureS1B) * dx1 - (textureS1A - textureS1C) * dx2) * TextureSetupScale * setupDivisor);
        long dT1dX = MameSetupCastToInt64(((textureT1A - textureT1B) * dx1 - (textureT1A - textureT1C) * dx2) * TextureSetupScale * setupDivisor);
        long dS1dY = MameSetupCastToInt64(((textureS1A - textureS1C) * dy1 - (textureS1A - textureS1B) * dy2) * TextureSetupScale * setupDivisor);
        long dT1dY = MameSetupCastToInt64(((textureT1A - textureT1C) * dy1 - (textureT1A - textureT1B) * dy2) * TextureSetupScale * setupDivisor);
        long textureStartW1 = MameSetupCastToInt64(textureQ1A * TextureSetupScale);
        long textureD1wDx = MameSetupCastToInt64(((textureQ1A - textureQ1B) * dx1 - (textureQ1A - textureQ1C) * dx2) * TextureSetupScale * setupDivisor);
        long textureD1wDy = MameSetupCastToInt64(((textureQ1A - textureQ1C) * dy1 - (textureQ1A - textureQ1B) * dy2) * TextureSetupScale * setupDivisor);
        int triangleTargetLod = ComputeAndTraceTexturedTriangleLod(
            a,
            b,
            c,
            dSdX,
            dSdY,
            dTdX,
            dTdY,
            bufferIndex,
            out int triangleLodBase8p8);
        int triangleLodBase1_8p8 = ComputeTextureLodBase8p8(dS1dX, dS1dY, dT1dX, dT1dY);
        int setupAx = unchecked((short)(int)(a.X * 16.0f)) >> 4;
        int setupAy = unchecked((short)(int)(a.Y * 16.0f)) >> 4;
        uint fbzMode = _registers[RegFbzMode];
        bool useMameAuxDepth = _experimentSetupMameAuxDepth;
        bool mameRgbMask = !useMameAuxDepth || (fbzMode & 0x200u) != 0;
        bool mameAuxMask = useMameAuxDepth && (fbzMode & 0x400u) != 0;
        bool mameDepthTest = useMameAuxDepth && (fbzMode & 0x10u) != 0;
        bool mameAlphaPlanes = useMameAuxDepth && (fbzMode & 0x40000u) != 0;
        bool alpha8Mask = _experimentTextureAlpha8Mask &&
            ((ReadTextureSampleRegister(RegTextureMode) >> 8) & 0x0fu) == 2u;
        ushort zaColor = (ushort)_registers[RegZaColor];
        int setupStartZ = unchecked((int)_registers[RegFstartZ]);
        int setupDzDx = unchecked((int)_registers[RegFdZdX]);
        int setupDzDy = unchecked((int)_registers[RegFdZdY]);
        long setupStartW = MameFloatToInt64(_registers[RegFstartW], 32);
        long setupDwDx = MameFloatToInt64(_registers[RegFdWdX], 32);
        long setupDwDy = MameFloatToInt64(_registers[RegFdWdY], 32);
        for (int y = minY; y < maxY; y++)
        {
            float py = y + 0.5f;
            int screenY = GetRasterBufferY(y);
            int row = screenY * LfbRowPixels;
            for (int x = minX; x < maxX; x++)
            {
                float px = x + 0.5f;
                float e0 = Edge(b.X, b.Y, c.X, c.Y, px, py);
                float e1 = Edge(c.X, c.Y, a.X, a.Y, px, py);
                float e2 = Edge(a.X, a.Y, b.X, b.Y, px, py);
                if (!(positive ? e0 >= 0 && e1 >= 0 && e2 >= 0 : e0 <= 0 && e1 <= 0 && e2 <= 0))
                    continue;

                int pixel = (row + x) & (LfbPixels - 1);
                int depthValue = 0;
                if (useMameAuxDepth)
                {
                    int setupDx = x - setupAx;
                    int setupDy = y - setupAy;
                    int iterZ = unchecked(setupStartZ + (int)((long)setupDy * setupDzDy) + (int)((long)setupDx * setupDzDx));
                    long iterW = unchecked(setupStartW + setupDy * setupDwDy + setupDx * setupDwDx);
                    depthValue = ComputeMameSetupDepthValue(fbzMode, _registers[RegFbzColorPath], iterZ, iterW, zaColor);
                    int depthSource = (fbzMode & 0x100000u) == 0 ? depthValue : zaColor;
                    if (mameDepthTest && !MameDepthTest(fbzMode, _auxBuffer[pixel], depthSource))
                        continue;
                }

                float wa = e0 * invArea;
                float wb = e1 * invArea;
                float wc = e2 * invArea;
                float s;
                float t;
                ushort texel;
                byte textureAlpha = 255;
                int targetLod = triangleTargetLod;
                _lastTextureSampleValid = false;
                if (_experimentTextureMameSetupGradients)
                {
                    int dx = x - setupAx;
                    int dy = y - setupAy;
                    long iterS = unchecked(startS + dy * dSdY + dx * dSdX);
                    long iterT = unchecked(startT + dy * dTdY + dx * dTdX);
                    if (_experimentTextureMameFixedFetch)
                    {
                        long iterW = unchecked(textureStartW + dy * textureDwDy + dx * textureDwDx);
                        if (_experimentMameTwoTmuCombine)
                        {
                            long iterS1 = unchecked(startS1 + dy * dS1dY + dx * dS1dX);
                            long iterT1 = unchecked(startT1 + dy * dT1dY + dx * dT1dX);
                            long iterW1 = unchecked(textureStartW1 + dy * textureD1wDy + dx * textureD1wDx);
                            TextureRgba combined = SampleAndCombineTwoTmusMameFixed(
                                iterS,
                                iterT,
                                iterW,
                                triangleLodBase8p8,
                                iterS1,
                                iterT1,
                                iterW1,
                                triangleLodBase1_8p8,
                                x,
                                y,
                                bufferIndex);
                            texel = combined.Rgb565;
                            textureAlpha = combined.A;
                        }
                        else
                        {
                            texel = SampleTextureRgb565MameFixed(iterS, iterT, iterW, targetLod);
                        }
                        goto sampledTexel;
                    }

                    s = (float)(iterS * (1.0 / (1 << 24)) / 256.0);
                    t = (float)(iterT * (1.0 / (1 << 24)) / 256.0);
                }
                else if (_experimentTexturePerspectiveInterpolate)
                {
                    s = InterpolateTextureS(a, b, c, wa, wb, wc);
                    t = InterpolateTextureT(a, b, c, wa, wb, wc);
                    float q = InterpolateTextureQ(a, b, c, wa, wb, wc);
                    if (float.IsFinite(q) && MathF.Abs(q) > 0.000001f)
                    {
                        s /= q;
                        t /= q;
                    }
                }
                else
                {
                    s = GetTextureS(a) * wa + GetTextureS(b) * wb + GetTextureS(c) * wc;
                    t = GetTextureT(a) * wa + GetTextureT(b) * wb + GetTextureT(c) * wc;
                }
                if (remapConstantSFullrectS)
                    s = (px - minX) * remapConstantSScale;
                if (remapConstantSFullrectT)
                    t = (maxY - py) * remapConstantTScale;
                if (traceSampleSummary && float.IsFinite(s) && float.IsFinite(t))
                {
                    sampleCoordCount++;
                    sampleMinS = MathF.Min(sampleMinS, s);
                    sampleMaxS = MathF.Max(sampleMaxS, s);
                    sampleMinT = MathF.Min(sampleMinT, t);
                    sampleMaxT = MathF.Max(sampleMaxT, t);
                }
                if (_experimentTextureMamePixelLod)
                {
                    int dx = x - setupAx;
                    int dy = y - setupAy;
                    long iterW = unchecked(textureStartW + dy * textureDwDy + dx * textureDwDx);
                    targetLod = ComputeMameTexturePixelLod(
                        triangleLodBase8p8,
                        iterW,
                        x,
                        y,
                        ReadTextureSampleRegister(RegTextureMode),
                        ReadTextureSampleRegister(RegTextureLod));
                    _experimentTextureMamePixelLodCounts[targetLod]++;
                }
                texel = SampleTextureRgb565(s, t, targetLod);
sampledTexel:
                if (traceSampleSummary && _lastTextureSampleValid)
                {
                    uint address = _lastTextureSampleByteAddress & (TextureBytes - 1u);
                    sampleCount++;
                    sampleRawBuckets![_lastTextureSampleRaw & 0xffffu] =
                        sampleRawBuckets.TryGetValue(_lastTextureSampleRaw & 0xffffu, out int rawCount) ? rawCount + 1 : 1;
                    sampleColorBuckets![_lastTextureSampleResult] =
                        sampleColorBuckets.TryGetValue(_lastTextureSampleResult, out int colorCount) ? colorCount + 1 : 1;
                    sampleAddressBuckets![address >> TextureZeroSampleBucketShift] =
                        sampleAddressBuckets.TryGetValue(address >> TextureZeroSampleBucketShift, out int addressCount) ? addressCount + 1 : 1;
                    if (sampleWriterBuckets is not null)
                    {
                        TextureSampleWriterKey writerKey = GetTextureSampleWriterKey(address);
                        sampleWriterBuckets[writerKey] =
                            sampleWriterBuckets.TryGetValue(writerKey, out int writerCount) ? writerCount + 1 : 1;
                        if (writerKey.Equals(default(TextureSampleWriterKey)) && address >= 0x10000u)
                        {
                            TextureSampleWriterKey wrappedWriterKey = GetTextureSampleWriterKey(address & 0xffffu);
                            sampleWrapped64KWriterBuckets![wrappedWriterKey] =
                                sampleWrapped64KWriterBuckets.TryGetValue(wrappedWriterKey, out int wrappedWriterCount)
                                    ? wrappedWriterCount + 1
                                    : 1;
                        }
                        if (sampleLodCounts is not null && sampleLodWriterBuckets is not null && (uint)targetLod <= 8u)
                        {
                            sampleLodCounts[targetLod]++;
                            Dictionary<TextureSampleWriterKey, int> lodWriters = sampleLodWriterBuckets[targetLod];
                            lodWriters[writerKey] = lodWriters.TryGetValue(writerKey, out int lodWriterCount)
                                ? lodWriterCount + 1
                                : 1;
                        }
                    }
                    if (address < sampleFirstAddress)
                        sampleFirstAddress = address;
                    if (address > sampleLastAddress)
                        sampleLastAddress = address;
                }
                _texturedPixelCount++;
                coveredPixels++;
                if (texel == 0)
                {
                    _texturedZeroPixelCount++;
                    zeroPixels++;
                    if (_visualizeZeroTextureFallback)
                    {
                        texel = fallbackColor != 0 ? fallbackColor : (ushort)0xffff;
                        _texturedFallbackPixelCount++;
                    }
                    if (_treatZeroTextureTexelAsTransparent)
                    {
                        if (!_visualizeZeroTextureFallback)
                        {
                            coveredAny = true;
                            continue;
                        }
                    }
                }

                if (_experimentMameTwoTmuCombine && (fbzMode & 0x2000u) != 0 && (textureAlpha & 1) == 0)
                {
                    coveredAny = true;
                    continue;
                }

                if (_experimentFbzColorPathRgbCombine)
                    texel = ApplyFbzColorPathRgb(texel, fallbackColor, textureAlpha);

                if (alpha8Mask)
                {
                    int alpha = Rgb565ToGrayscale8(texel);
                    if (alpha == 0)
                    {
                        coveredAny = true;
                        continue;
                    }
                    texel = BlendRgb565(buffer[pixel], fallbackColor, alpha);
                }

                if (mameRgbMask)
                {
                    buffer[pixel] = texel;
                    TrackPixelLastWriter(bufferIndex, x, screenY, writerId);
                    _texturedRasterPixelCount++;
                    if ((uint)bufferIndex < (uint)_rasterBufferPixelCounts.Length)
                        _rasterBufferPixelCounts[bufferIndex]++;
                    _lfbWriteCount++;
                }
                if (mameAuxMask)
                    _auxBuffer[pixel] = mameAlphaPlanes ? (ushort)(texel >> 8) : (ushort)depthValue;
                coveredAny = true;
            }
        }

        if (!coveredAny)
            _texturedRejectEmptyRasterCount++;
        if (!coveredAny)
            TraceTexturedTriangleReject("empty-raster", a, b, c, fallbackColor, area, minX, maxX, minY, maxY, clipX0, clipX1, clipY0, clipY1);
        else
        {
            if (traceSampleSummary &&
                (!_traceTexturedTriangleSampleSummaryRequireWriter ||
                 HasNonDefaultTextureSampleWriter(sampleWriterBuckets)))
            {
                TraceTexturedTriangleSampleSummary(
                    a,
                    b,
                    c,
                    fallbackColor,
                    area,
                    minX,
                    maxX,
                    minY,
                    maxY,
                    coveredPixels,
                    zeroPixels,
                    sampleCount,
                    sampleFirstAddress == uint.MaxValue ? 0u : sampleFirstAddress,
                    sampleLastAddress,
                    sampleCoordCount,
                    sampleMinS,
                    sampleMaxS,
                    sampleMinT,
                    sampleMaxT,
                    sampleRawBuckets!,
                    sampleColorBuckets!,
                    sampleAddressBuckets!,
                    sampleWriterBuckets,
                    sampleWrapped64KWriterBuckets,
                    sampleLodCounts,
                    sampleLodWriterBuckets,
                    bufferIndex);
            }
            TraceTexturedTriangleCovered(a, b, c, fallbackColor, area, minX, maxX, minY, maxY, coveredPixels, zeroPixels);
        }
        return coveredAny;
    }

    private int ComputeAndTraceTexturedTriangleLod(
        SetupVertex a,
        SetupVertex b,
        SetupVertex c,
        long dSdX,
        long dSdY,
        long dTdX,
        long dTdY,
        int bufferIndex,
        out int lodBase8p8)
    {
        lodBase8p8 = int.MinValue;
        bool trace = _traceTexturedTriangleLod &&
            _texturedTriangleLodTraceCount < _traceTexturedTriangleLodLimit &&
            ShouldTraceTexturedTriangleSampleSummaryBuffer(bufferIndex);

        uint mode = ReadTextureSampleRegister(RegTextureMode);
        uint lod = ReadTextureSampleRegister(RegTextureLod);
        uint registerBase = ReadTextureSampleRegister(RegTextureBaseAddr);
        if (_traceTexturedTriangleSampleSummaryRegisterBase.HasValue &&
            registerBase != (uint)_traceTexturedTriangleSampleSummaryRegisterBase.Value)
        {
            trace = false;
        }
        if (!trace && !_experimentTextureMameTriangleLod && !_experimentTextureMamePixelLod)
        {
            return -1;
        }

        lodBase8p8 = ComputeTextureLodBase8p8(dSdX, dSdY, dTdX, dTdY);
        float centroidW = (a.Q + b.Q + c.Q) / 3.0f;
        int perspective8p8 = (mode & 1u) != 0 && float.IsFinite(centroidW) && MathF.Abs(centroidW) > 0.0f
            ? (int)Math.Round(Math.Log2(Math.Abs(centroidW)) * 256.0)
            : 0;
        int bias = (int)((lod >> 12) & 0x3fu);
        if (bias >= 32)
            bias -= 64;
        int bias8p8 = bias << 6;
        int min8p8 = (int)(lod & 0x3fu) << 6;
        int max8p8 = (int)((lod >> 6) & 0x3fu) << 6;
        int candidate8p8 = lodBase8p8 == int.MinValue
            ? int.MinValue
            : lodBase8p8 - perspective8p8 + bias8p8;
        int clamped8p8 = candidate8p8 == int.MinValue
            ? int.MinValue
            : MameClampTextureLod(candidate8p8, min8p8, max8p8);
        int targetLod = clamped8p8 == int.MinValue ? 0 : Math.Clamp(clamped8p8 >> 8, 0, 8);
        uint lodMask = ((lod >> 19) & 1u) != 0
            ? (((lod >> 18) & 1u) != 0 ? 0x0aau : 0x155u)
            : 0x1ffu;
        targetLod += (int)((~lodMask >> targetLod) & 1u);
        targetLod = Math.Clamp(targetLod, 0, 8);

        if (trace)
        {
            Console.WriteLine(
                $"[GAUNTDL:VOODOO-TRILOD] n={++_texturedTriangleLodTraceCount} buf={bufferIndex} " +
                $"mode=0x{mode:X8} lod=0x{lod:X8} regbase=0x{registerBase:X8} " +
                $"dstdx={dSdX}/{dTdX} dstdy={dSdY}/{dTdY} " +
                $"base8p8={lodBase8p8} centroidW={centroidW:F6} perspective8p8={perspective8p8} " +
                $"bias8p8={bias8p8} min8p8={min8p8} max8p8={max8p8} candidate8p8={candidate8p8} " +
                $"clamped8p8={clamped8p8} targetLod={targetLod}");
        }

        return _experimentTextureMameTriangleLod ? targetLod : -1;
    }

    private static int ComputeTextureLodBase8p8(long dSdX, long dSdY, long dTdX, long dTdY)
    {
        double texDx = (double)dSdX * dSdX + (double)dTdX * dTdX;
        double texDy = (double)dSdY * dSdY + (double)dTdY * dTdY;
        double maxDerivativeSquared = Math.Max(texDx, texDy);
        return maxDerivativeSquared > 0.0 && double.IsFinite(maxDerivativeSquared)
            ? (int)Math.Round(((Math.Log2(maxDerivativeSquared) - 64.0) * 0.5) * 256.0)
            : int.MinValue;
    }

    private static int ComputeMameTexturePixelLod(
        int lodBase8p8,
        long iterW,
        int x,
        int y,
        uint textureMode,
        uint textureLod)
    {
        int candidate8p8 = lodBase8p8;
        if ((textureMode & 1u) != 0)
            candidate8p8 -= MameFastLog2(iterW, 32);

        int bias = (int)((textureLod >> 12) & 0x3fu);
        if (bias >= 32)
            bias -= 64;
        candidate8p8 += bias << 6;

        if ((textureMode & 0x10u) != 0)
        {
            ReadOnlySpan<byte> dither4x4 =
            [
                 0,  8,  2, 10,
                12,  4, 14,  6,
                 3, 11,  1,  9,
                15,  7, 13,  5
            ];
            candidate8p8 += dither4x4[((y & 3) << 2) | (x & 3)] << 4;
        }

        int min8p8 = (int)(textureLod & 0x3fu) << 6;
        int max8p8 = (int)((textureLod >> 6) & 0x3fu) << 6;
        int clamped8p8 = MameClampTextureLod(candidate8p8, min8p8, max8p8);
        int targetLod = Math.Clamp(clamped8p8 >> 8, 0, 8);
        uint lodMask = ((textureLod >> 19) & 1u) != 0
            ? (((textureLod >> 18) & 1u) != 0 ? 0x0aau : 0x155u)
            : 0x1ffu;
        targetLod += (int)((~lodMask >> targetLod) & 1u);
        return Math.Clamp(targetLod, 0, 8);
    }

    // MAME calls std::clamp here. libstdc++ implements that as
    // min(max(value, low), high), which matters for Gauntlet's inverted
    // 0x20c6 low/high fields even though that input violates std::clamp's
    // formal precondition.
    private static int MameClampTextureLod(int value, int low, int high)
        => Math.Min(Math.Max(value, low), high);

    private static int MameFastLog2(double value, int fractionalBits)
    {
        if (value < 0.0)
            return 0;

        ReadOnlySpan<byte> fractionalLog2 =
        [
              0,   2,   5,   8,  11,  14,  16,  19,  22,  25,  27,  30,  33,  35,  38,  40,
             43,  46,  48,  51,  53,  56,  58,  61,  63,  65,  68,  70,  73,  75,  77,  80,
             82,  84,  87,  89,  91,  93,  96,  98, 100, 102, 104, 106, 109, 111, 113, 115,
            117, 119, 121, 123, 125, 127, 129, 132, 134, 136, 138, 140, 141, 143, 145, 147,
            149, 151, 153, 155, 157, 159, 161, 162, 164, 166, 168, 170, 172, 173, 175, 177,
            179, 181, 182, 184, 186, 188, 189, 191, 193, 194, 196, 198, 200, 201, 203, 205,
            206, 208, 209, 211, 213, 214, 216, 218, 219, 221, 222, 224, 225, 227, 229, 230,
            232, 233, 235, 236, 238, 239, 241, 242, 244, 245, 247, 248, 250, 251, 253, 254
        ];
        ulong bits = (ulong)BitConverter.DoubleToInt64Bits(value);
        uint exponentAndMantissa = (uint)(bits >> 45);
        int exponent = (int)(exponentAndMantissa >> 7) - 1023 - fractionalBits;
        return (exponent << 8) | fractionalLog2[(int)(exponentAndMantissa & 127u)];
    }

    private bool ShouldSuppressConstantSFullrectTextureTriangle(
        SetupVertex a,
        SetupVertex b,
        SetupVertex c,
        ushort fallbackColor,
        float area,
        int minX,
        int maxX,
        int minY,
        int maxY,
        int bufferIndex)
    {
        if (!_experimentSuppressConstantSFullrectTextureTriangles ||
            !IsConstantSFullrectTextureTriangle(a, b, c, minX, maxX, minY, maxY))
        {
            return false;
        }

        if (_constantSFullrectSuppressTraceCount++ < _experimentSuppressConstantSFullrectTextureTrianglesLimit)
        {
            uint mode = ReadTextureSampleRegister(RegTextureMode);
            uint lod = ReadTextureSampleRegister(RegTextureLod);
            uint registerBase = ReadTextureSampleRegister(RegTextureBaseAddr);
            int targetLod = GetTextureTargetLod(lod, registerBase);
            int format = (int)((mode >> 8) & 0x0fu);
            bool sixteenBit = IsTextureFormat16Bit(format);
            uint sampleBase = GetTextureBaseAddress(registerBase);
            if (_textureSampleBaseBias != 0)
                sampleBase = (uint)((sampleBase + _textureSampleBaseBias) & (TextureBytes - 1));
            uint resolvedBase = GetTextureLodOffsetFromBase(targetLod, GetTextureFormatBytesPerTexel(format), lod, sampleBase);
            ulong pc = CpuPcProvider?.Invoke() ?? 0;
            string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
            Console.WriteLine(
                $"[GAUNTDL:EXPERIMENT] suppress-constant-s-fullrect-texture-triangle " +
                $"n={_constantSFullrectSuppressTraceCount} color=0x{fallbackColor:X4} area={area:F3} " +
                $"bbox=({minX},{minY})-({maxX},{maxY}) buf={bufferIndex} " +
                $"mode=0x{mode:X8} lod=0x{lod:X8} base=0x{resolvedBase:X6} " +
                $"st=({a.S:F3},{a.T:F3})/({b.S:F3},{b.T:F3})/({c.S:F3},{c.T:F3}) " +
                $"cmd=0x{_currentCommandFifoCommand:X8}:0x{_currentCommandFifoPacketStart * 4:X8}:rd0x{_cmdFifoReadIndex * 4:X8}{pcStatus}");
        }

        return true;
    }

    private bool IsConstantSFullrectTextureTriangle(
        SetupVertex a,
        SetupVertex b,
        SetupVertex c,
        int minX,
        int maxX,
        int minY,
        int maxY)
    {
        if (_currentCommandFifoCommand != 0x0180a8cbu)
            return false;

        int width = maxX - minX;
        int height = maxY - minY;
        if (width < 480 || height < 300 || (long)width * height < 150_000L)
            return false;

        float minS = MathF.Min(a.S, MathF.Min(b.S, c.S));
        float maxS = MathF.Max(a.S, MathF.Max(b.S, c.S));
        float minT = MathF.Min(a.T, MathF.Min(b.T, c.T));
        float maxT = MathF.Max(a.T, MathF.Max(b.T, c.T));
        if (!float.IsFinite(minS) || !float.IsFinite(maxS) ||
            !float.IsFinite(minT) || !float.IsFinite(maxT) ||
            MathF.Abs(maxS - minS) > 0.001f ||
            MathF.Abs(maxT - minT) < 128.0f)
        {
            return false;
        }

        return true;
    }

    private static int ComputeMameSetupDepthValue(uint fbzMode, uint fbzColorPath, int iterZ, long iterW, ushort zaColor)
    {
        int result;
        if ((fbzMode & 0x08u) != 0)
        {
            result = (fbzMode & 0x200000u) == 0
                ? ComputeMameWFloat(iterW)
                : ComputeMameFloatDepth(iterZ);
        }
        else
        {
            result = MameClampedZ(iterZ, fbzColorPath);
        }

        if ((fbzMode & 0x10000u) != 0)
            result = Math.Clamp(result + unchecked((short)zaColor), 0, 0xffff);
        return result;
    }

    private static int ComputeMameWFloat(long iterW)
    {
        int exp = BitOperations.LeadingZeroCount(unchecked((ulong)iterW)) - 16;
        if (exp < 0)
            return 0;
        if (exp >= 16)
            return 0xffff;
        return (int)(((uint)exp << 12) | (((ulong)iterW >> (35 - exp)) ^ 0x1fffu)) + 1;
    }

    private static int ComputeMameFloatDepth(int iterZ)
    {
        if ((iterZ & unchecked((int)0xf0000000u)) != 0)
            return 0;
        if ((iterZ & 0x0ffff000) == 0)
            return 0xffff;

        int exp = BitOperations.LeadingZeroCount((uint)iterZ) - 4;
        return (int)(((uint)exp << 12) | (((uint)iterZ >> (15 - exp)) ^ 0x1fffu)) + 1;
    }

    private static int MameClampedZ(int iterZ, uint fbzColorPath)
    {
        if ((fbzColorPath & 0x10000000u) != 0)
            return Math.Clamp(iterZ >> 12, 0, 0xffff);

        uint result = (uint)iterZ >> 12;
        if (result == 0xfffffu)
            return 0;
        if (result == 0x10000u)
            return 0xffff;
        return (int)(result & 0xffffu);
    }

    private static bool MameDepthTest(uint fbzMode, int depthDest, int depthSource)
    {
        return ((fbzMode >> 5) & 0x07u) switch
        {
            0 => false,
            1 => depthSource < depthDest,
            2 => depthSource == depthDest,
            3 => depthSource <= depthDest,
            4 => depthSource > depthDest,
            5 => depthSource != depthDest,
            6 => depthSource >= depthDest,
            _ => true
        };
    }

    private static long MameFloatToInt64(uint data, int fixedBits)
    {
        int exponent = (int)((data >> 23) & 0xffu) - 127 - 23 + fixedBits;
        long result = (data & 0x7fffffu) | 0x800000u;
        if (exponent < 0)
        {
            result = exponent > -64 ? result >> -exponent : 0;
        }
        else
        {
            result = exponent < 64 ? result << exponent : long.MaxValue;
        }

        return (data & 0x80000000u) != 0 ? -result : result;
    }

    private static long MameSetupCastToInt64(double value)
    {
        if (double.IsNaN(value) || double.IsInfinity(value))
            return long.MinValue;
        if (value >= long.MaxValue)
            return long.MaxValue;
        if (value <= long.MinValue)
            return long.MinValue;
        return (long)value;
    }

    private static int MameSetupCastToInt32(double value)
    {
        if (double.IsNaN(value) || double.IsInfinity(value))
            return int.MinValue;
        if (value >= int.MaxValue)
            return int.MaxValue;
        if (value <= int.MinValue)
            return int.MinValue;
        return (int)value;
    }

    private bool FillGradientTexturedTriangle(
        float ax,
        float ay,
        float bx,
        float by,
        float cx,
        float cy,
        ushort fallbackColor)
    {
        if (!IsTextureRasterEnabled() ||
            !float.IsFinite(ax) || !float.IsFinite(ay) ||
            !float.IsFinite(bx) || !float.IsFinite(by) ||
            !float.IsFinite(cx) || !float.IsFinite(cy))
        {
            return false;
        }

        float startS = FloatFromRegister(_registers[RegFstartS]);
        float startT = FloatFromRegister(_registers[RegFstartT]);
        float dSdX = FloatFromRegister(_registers[RegFdSdX]);
        float dTdX = FloatFromRegister(_registers[RegFdTdX]);
        float dSdY = FloatFromRegister(_registers[RegFdSdY]);
        float dTdY = FloatFromRegister(_registers[RegFdTdY]);
        if (!float.IsFinite(startS) || !float.IsFinite(startT) ||
            !float.IsFinite(dSdX) || !float.IsFinite(dTdX) ||
            !float.IsFinite(dSdY) || !float.IsFinite(dTdY))
        {
            return false;
        }

        float area = Edge(ax, ay, bx, by, cx, cy);
        if (!float.IsFinite(area) || MathF.Abs(area) < 0.001f)
            return false;

        GetClip(out int clipX0, out int clipX1, out int clipY0, out int clipY1);
        int minX = Math.Clamp((int)MathF.Floor(MathF.Min(ax, MathF.Min(bx, cx))), clipX0, clipX1);
        int maxX = Math.Clamp((int)MathF.Ceiling(MathF.Max(ax, MathF.Max(bx, cx))), clipX0, clipX1);
        int minY = Math.Clamp((int)MathF.Floor(MathF.Min(ay, MathF.Min(by, cy))), clipY0, clipY1);
        int maxY = Math.Clamp((int)MathF.Ceiling(MathF.Max(ay, MathF.Max(by, cy))), clipY0, clipY1);
        if (maxX <= minX || maxY <= minY)
            return false;

        bool positive = area > 0;
        int bufferIndex = GetDrawBufferIndex();
        _lastDrawBufferIndex = bufferIndex;
        MaterializePendingClear(bufferIndex);
        InvalidateFastFillCache(bufferIndex);
        ushort[] buffer = _colorBuffers[bufferIndex];
        int writerId = GetPixelLastWriterId("tex", "direct", fallbackColor);
        bool alpha8Mask = _experimentTextureAlpha8Mask &&
            ((ReadTextureSampleRegister(RegTextureMode) >> 8) & 0x0fu) == 2u;
        bool coveredAny = false;
        int coveredPixels = 0;
        int zeroPixels = 0;
        for (int y = minY; y < maxY; y++)
        {
            float py = y + 0.5f;
            int screenY = GetRasterBufferY(y);
            int row = screenY * LfbRowPixels;
            for (int x = minX; x < maxX; x++)
            {
                float px = x + 0.5f;
                float e0 = Edge(bx, by, cx, cy, px, py);
                float e1 = Edge(cx, cy, ax, ay, px, py);
                float e2 = Edge(ax, ay, bx, by, px, py);
                if (!(positive ? e0 >= 0 && e1 >= 0 && e2 >= 0 : e0 <= 0 && e1 <= 0 && e2 <= 0))
                    continue;

                float s = startS + ((px - ax) * dSdX) + ((py - ay) * dSdY);
                float t = startT + ((px - ax) * dTdX) + ((py - ay) * dTdY);
                ushort texel = SampleTextureRgb565(s, t);
                _texturedPixelCount++;
                coveredPixels++;
                if (texel == 0)
                {
                    _texturedZeroPixelCount++;
                    zeroPixels++;
                    if (_visualizeZeroTextureFallback)
                    {
                        texel = fallbackColor != 0 ? fallbackColor : (ushort)0xffff;
                        _texturedFallbackPixelCount++;
                    }
                    else if (_treatZeroTextureTexelAsTransparent)
                    {
                        coveredAny = true;
                        continue;
                    }
                }

                if (_experimentFbzColorPathRgbCombine)
                    texel = ApplyFbzColorPathRgb(texel, fallbackColor);

                int pixel = (row + x) & (LfbPixels - 1);
                if (alpha8Mask)
                {
                    int alpha = Rgb565ToGrayscale8(texel);
                    if (alpha == 0)
                    {
                        coveredAny = true;
                        continue;
                    }
                    texel = BlendRgb565(buffer[pixel], fallbackColor, alpha);
                }

                buffer[pixel] = texel;
                TrackPixelLastWriter(bufferIndex, x, screenY, writerId);
                coveredAny = true;
                _texturedRasterPixelCount++;
                if ((uint)bufferIndex < (uint)_rasterBufferPixelCounts.Length)
                    _rasterBufferPixelCounts[bufferIndex]++;
                _lfbWriteCount++;
            }
        }

        if (coveredAny)
            _texturedTriangleCoveredCount++;
        else
            _texturedTriangleRejectedCount++;
        _texturedTriangleCount++;
        TraceGradientTexturedTriangle(
            coveredAny,
            ax,
            ay,
            bx,
            by,
            cx,
            cy,
            fallbackColor,
            area,
            minX,
            maxX,
            minY,
            maxY,
            coveredPixels,
            zeroPixels,
            startS,
            startT,
            dSdX,
            dTdX,
            dSdY,
            dTdY);
        return coveredAny;
    }

    private bool IsTextureRasterEnabled()
    {
        if (((_registers[RegFbiInit3] >> 6) & 1u) != 0)
            return false;

        if (_fixTmuRegisterBanks)
            return IsTextureRasterEnabledForTmu(0) || IsTextureRasterEnabledForTmu(1);

        return ((ReadTextureRegister(RegTextureLod) & 0x3fu) < 32u) &&
            ReadTextureRegister(RegTextureMode) != 0xffffffffu;
    }

    private bool IsTextureRasterEnabledForTmu(int tmu)
    {
        if ((uint)tmu > 1u ||
            !_tmuRegisterValid[tmu][RegTextureMode] ||
            !_tmuRegisterValid[tmu][RegTextureLod])
        {
            return false;
        }

        return (_tmuRegisters[tmu][RegTextureLod] & 0x3fu) < 32u &&
            _tmuRegisters[tmu][RegTextureMode] != 0xffffffffu;
    }

    private void TraceGradientTexturedTriangle(
        bool coveredAny,
        float ax,
        float ay,
        float bx,
        float by,
        float cx,
        float cy,
        ushort fallbackColor,
        float area,
        int minX,
        int maxX,
        int minY,
        int maxY,
        int coveredPixels,
        int zeroPixels,
        float startS,
        float startT,
        float dSdX,
        float dTdX,
        float dSdY,
        float dTdY)
    {
        if (!_traceTexturedTriangleCovered ||
            _renderFrame < _traceTextureMinRenderFrame ||
            coveredPixels < _traceTexturedTriangleCoveredMinPixels ||
            _texturedTriangleCoveredTraceCount++ >= _traceTexturedTriangleCoveredLimit)
            return;

        uint mode = ReadTextureSampleRegister(RegTextureMode);
        uint lod = ReadTextureSampleRegister(RegTextureLod);
        uint registerBase = ReadTextureSampleRegister(RegTextureBaseAddr);
        int format = ResolveTextureSampleFormat(mode, lod, registerBase);
        int targetLod = GetTextureTargetLod(lod, registerBase);
        uint sampleBase = GetTextureBaseAddress(registerBase);
        if (_textureSampleBaseBias != 0)
            sampleBase = (uint)((sampleBase + _textureSampleBaseBias) & (TextureBytes - 1));
        uint resolvedBase = GetTextureLodOffsetFromBase(targetLod, GetTextureFormatBytesPerTexel(format), lod, sampleBase);
        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-TEXCOVER] grad=1 covered={(coveredAny ? 1 : 0)} color=0x{fallbackColor:X4} area={area:F3} bbox=({minX},{minY})-({maxX},{maxY}) " +
            $"pixels={coveredPixels} zero={zeroPixels} mode=0x{mode:X8} lod=0x{lod:X8} regbase=0x{registerBase:X8} base=0x{resolvedBase:X6} " +
            $"xy=({ax:F3},{ay:F3})/({bx:F3},{by:F3})/({cx:F3},{cy:F3}) " +
            $"st=({startS:F3},{startT:F3}) dsx=({dSdX:F6},{dTdX:F6}) dsy=({dSdY:F6},{dTdY:F6}) " +
            $"setup=0x{_registers[0x98]:X8} fbz=0x{_registers[RegFbzMode]:X8} fbzcp=0x{_registers[RegFbzColorPath]:X8} " +
            $"cmd=0x{_currentCommandFifoCommand:X8}:{_currentCommandFifoWordsNeeded}:0x{_currentCommandFifoPacketStart * 4:X8}:rd0x{_cmdFifoReadIndex * 4:X8}{pcStatus}");
    }

