    private void TraceTexturedTriangleSampleSummary(
        SetupVertex a,
        SetupVertex b,
        SetupVertex c,
        ushort fallbackColor,
        float area,
        int minX,
        int maxX,
        int minY,
        int maxY,
        int coveredPixels,
        int zeroPixels,
        int sampleCount,
        uint sampleFirstAddress,
        uint sampleLastAddress,
        int sampleCoordCount,
        float sampleMinS,
        float sampleMaxS,
        float sampleMinT,
        float sampleMaxT,
        IReadOnlyDictionary<uint, int> sampleRawBuckets,
        IReadOnlyDictionary<uint, int> sampleColorBuckets,
        IReadOnlyDictionary<uint, int> sampleAddressBuckets,
        IReadOnlyDictionary<TextureSampleWriterKey, int>? sampleWriterBuckets,
        IReadOnlyDictionary<TextureSampleWriterKey, int>? sampleWrapped64KWriterBuckets,
        IReadOnlyList<int>? sampleLodCounts,
        IReadOnlyList<Dictionary<TextureSampleWriterKey, int>>? sampleLodWriterBuckets,
        int bufferIndex)
    {
        if (_texturedTriangleSampleSummaryTraceCount >= _traceTexturedTriangleSampleSummaryLimit)
            return;

        uint mode = ReadTextureSampleRegister(RegTextureMode);
        uint lod = ReadTextureSampleRegister(RegTextureLod);
        uint registerBase = ReadTextureSampleRegister(RegTextureBaseAddr);
        if ((_traceType3TextureModes.Length != 0 && !_traceType3TextureModes.Contains(mode)) ||
            (_traceType3TextureLods.Length != 0 && !_traceType3TextureLods.Contains(lod)) ||
            (_traceType3TextureBases.Length != 0 && !_traceType3TextureBases.Contains(registerBase)))
        {
            return;
        }

        _texturedTriangleSampleSummaryTraceCount++;
        int targetLod = GetTextureTargetLod(lod, registerBase);
        int format = ResolveTextureSampleFormat(mode, lod, registerBase);
        bool sixteenBit = IsTextureFormat16Bit(format);
        int width;
        int height;
        uint resolvedBase;
        if (_experimentTextureMameFetchAddressing)
        {
            TextureFetchLayout layout = GetMameTextureFetchLayout(targetLod, mode);
            width = layout.Width;
            height = layout.Height;
            resolvedBase = layout.BaseAddress;
        }
        else
        {
            width = Math.Max(1, (int)GetTextureWidth(lod) >> targetLod);
            height = Math.Max(1, (int)GetTextureHeight(lod) >> targetLod);
            uint sampleBase = GetTextureBaseAddress(registerBase);
            if (_textureSampleBaseBias != 0)
                sampleBase = (uint)((sampleBase + _textureSampleBaseBias) & (TextureBytes - 1));
            resolvedBase = GetTextureLodOffsetFromBase(targetLod, GetTextureFormatBytesPerTexel(format), lod, sampleBase);
        }

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        string gradientStatus = _traceTexturedTriangleSampleGradients ? FormatTextureGradientTraceStatus() : "";
        string sampleRangeStatus = sampleCoordCount > 0
            ? $"sampleST=({sampleMinS:F3}-{sampleMaxS:F3},{sampleMinT:F3}-{sampleMaxT:F3}) "
            : "sampleST=- ";
        string targetLodStatus = _experimentTextureMamePixelLod ? "dynamic" : targetLod.ToString(CultureInfo.InvariantCulture);
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-TEXSUMMARY] n={_texturedTriangleSampleSummaryTraceCount} color=0x{fallbackColor:X4} area={area:F3} " +
            $"bbox=({minX},{minY})-({maxX},{maxY}) pixels={coveredPixels} zero={zeroPixels} samples={sampleCount} " +
            $"buf={bufferIndex} front={_frontBufferIndex} back={_backBufferIndex} rbuf={_lastRenderBufferIndex} " +
            $"tsrc={GetTextureSampleRegisterSourceLabel()} mode=0x{mode:X8} lod=0x{lod:X8} targetLod={targetLodStatus} layoutLod={targetLod} fmt={format} b16={(sixteenBit ? 1 : 0)} " +
            $"layoutSize={width}x{height} regbase=0x{registerBase:X8} layoutBase=0x{resolvedBase:X6} addrs=0x{sampleFirstAddress:X6}-0x{sampleLastAddress:X6} " +
            sampleRangeStatus +
            $"raw={FormatTopTextureSampleBuckets(sampleRawBuckets, 4)} rgb={FormatTopTextureSampleBuckets(sampleColorBuckets, 4)} " +
            $"addr={FormatTopTextureAddressBuckets(sampleAddressBuckets)} " +
            $"writers={FormatTopTextureSampleWriterBuckets(sampleWriterBuckets)} " +
            $"wrap64writers={FormatTopTextureSampleWriterBuckets(sampleWrapped64KWriterBuckets)} " +
            $"lodwriters={FormatTextureSampleLodWriterBuckets(sampleLodCounts, sampleLodWriterBuckets)} " +
            $"regs={FormatTextureRegisterWriteStatus()} " +
            $"xy=({a.X:F3},{a.Y:F3})/({b.X:F3},{b.Y:F3})/({c.X:F3},{c.Y:F3}) " +
            $"stq=({a.S:F3},{a.T:F3},{a.Q:F6})/({b.S:F3},{b.T:F3},{b.Q:F6})/({c.S:F3},{c.T:F3},{c.Q:F6}) " +
            $"{gradientStatus}" +
            $"setup=0x{_registers[0x98]:X8} fbz=0x{_registers[RegFbzMode]:X8} fbzcp=0x{_registers[RegFbzColorPath]:X8} " +
            $"cmd=0x{_currentCommandFifoCommand:X8}:{_currentCommandFifoWordsNeeded}:0x{_currentCommandFifoPacketStart * 4:X8}:rd0x{_cmdFifoReadIndex * 4:X8}{pcStatus}");
    }

    private bool ShouldTraceTexturedTriangleSampleSummaryBuffer(int bufferIndex)
        => _traceTexturedTriangleSampleSummaryBuffers.Length == 0 ||
           _traceTexturedTriangleSampleSummaryBuffers.Contains(bufferIndex);

    private static string FormatTopTextureSampleBuckets(IReadOnlyDictionary<uint, int> buckets, int digits)
    {
        if (buckets.Count == 0)
            return "-";

        return string.Join(",", buckets
            .OrderByDescending(pair => pair.Value)
            .ThenBy(pair => pair.Key)
            .Take(4)
            .Select(pair => $"0x{pair.Key.ToString($"X{digits}", CultureInfo.InvariantCulture)}:{pair.Value}"));
    }

    private static string FormatTopTextureAddressBuckets(IReadOnlyDictionary<uint, int> buckets)
    {
        if (buckets.Count == 0)
            return "-";

        return string.Join(",", buckets
            .OrderByDescending(pair => pair.Value)
            .ThenBy(pair => pair.Key)
            .Take(4)
            .Select(pair => $"0x{pair.Key << TextureZeroSampleBucketShift:X6}:{pair.Value}"));
    }

    private static bool HasNonDefaultTextureSampleWriter(IReadOnlyDictionary<TextureSampleWriterKey, int>? buckets)
        => buckets is not null &&
           buckets.Keys.Any(key => !key.Equals(default(TextureSampleWriterKey)));

    private string FormatTextureGradientTraceStatus()
        => string.Create(
            CultureInfo.InvariantCulture,
            $"gradRaw=0x{_registers[RegFstartS]:X8}/0x{_registers[RegFstartT]:X8}/0x{_registers[RegFstartW]:X8}/0x{_registers[RegFdSdX]:X8}/0x{_registers[RegFdTdX]:X8}/0x{_registers[RegFdSdY]:X8}/0x{_registers[RegFdTdY]:X8} " +
            $"gradF=({FloatFromRegister(_registers[RegFstartS]):F6},{FloatFromRegister(_registers[RegFstartT]):F6},{FloatFromRegister(_registers[RegFstartW]):F6})/" +
            $"({FloatFromRegister(_registers[RegFdSdX]):F6},{FloatFromRegister(_registers[RegFdTdX]):F6})/" +
            $"({FloatFromRegister(_registers[RegFdSdY]):F6},{FloatFromRegister(_registers[RegFdTdY]):F6}) ");

    private TextureSampleWriterKey GetTextureSampleWriterKey(uint byteAddress)
    {
        int wordOffset = (int)((byteAddress & (TextureBytes - 1u)) >> 2);
        if (!_textureWordLastWriters.TryGetValue(wordOffset, out TextureWordLastWriter writer))
            return default;

        _textureWordSourceProvenance.TryGetValue(wordOffset, out TextureWordSourceProvenance source);
        _textureWordPreviousWriters.TryGetValue(wordOffset, out TextureWordPreviousWriter previous);

        return new TextureSampleWriterKey(
            writer.Pc,
            writer.Mode,
            writer.TexLod,
            writer.TextureBase,
            writer.Lod,
            writer.BytesPerTexel,
            writer.Seq8Downld,
            writer.Type5,
            writer.Type5Command,
            writer.Type5TargetStart,
            writer.PacketStart,
            writer.ReadIndex,
            writer.Streaming,
            source.Source,
            source.SourceBase,
            source.PacketSourceAddress,
            source.Packet,
            source.Index,
            source.Limit,
            source.RenderFrame,
            previous.Writer.Pc,
            previous.Writer.Type5TargetStart,
            previous.Source.Source,
            previous.Source.RenderFrame);
    }

    private static string FormatTopTextureSampleWriterBuckets(IReadOnlyDictionary<TextureSampleWriterKey, int>? buckets)
    {
        if (buckets is null || buckets.Count == 0)
            return "-";

        return string.Join(",", buckets
            .OrderByDescending(pair => pair.Value)
            .ThenBy(pair => pair.Key.Pc)
            .ThenBy(pair => pair.Key.TextureBase)
            .Take(4)
            .Select(pair => $"{FormatTextureSampleWriterKey(pair.Key)}:{pair.Value}"));
    }

    private static string FormatTextureSampleLodWriterBuckets(
        IReadOnlyList<int>? counts,
        IReadOnlyList<Dictionary<TextureSampleWriterKey, int>>? buckets)
    {
        if (counts is null || buckets is null)
            return "-";

        return string.Join(";", Enumerable.Range(0, Math.Min(counts.Count, buckets.Count))
            .Where(lod => counts[lod] != 0)
            .Select(lod => $"l{lod}={counts[lod]}[{FormatTopTextureSampleWriterBuckets(buckets[lod])}]"));
    }

    private static string FormatTextureSampleWriterKey(TextureSampleWriterKey key)
    {
        if (key.Equals(default(TextureSampleWriterKey)))
            return "none";

        string type5 = key.Type5
            ? $"/t5=0x{key.Type5Command:X8}@0x{key.Type5TargetStart:X6}/pkt=0x{key.PacketStart * 4:X8}/rd=0x{key.ReadIndex * 4:X8}/s={(key.Streaming ? 1 : 0)}"
            : "";
        string source = key.Source != 0
            ? $"/src=0x{key.Source:x16}/srcBase=0x{key.SourceBase:x8}/pktSrc=0x{key.PacketSourceAddress:x8}/p={key.SourcePacket}/idx={key.SourceIndex}-{key.SourceLimit}/frame={key.SourceRenderFrame}"
            : "/src=-";
        string previous = key.PreviousPc != 0
            ? $"/prev=pc{key.PreviousPc & 0xffffffffUL:x8}@0x{key.PreviousType5TargetStart:X6}:src{(key.PreviousSource != 0 ? $"0x{key.PreviousSource:x16}" : "-")}:frame{key.PreviousSourceRenderFrame}"
            : "/prev=-";
        return $"pc={key.Pc & 0xffffffffUL:x8}/m=0x{key.Mode:X8}/lod=0x{key.TexLod:X8}/base=0x{key.TextureBase:X8}/l={key.Lod}/bpp={key.BytesPerTexel}/seq={((key.Seq8Downld) ? 1 : 0)}{type5}{source}{previous}";
    }

    private void TraceTexturedTriangleReject(
        string reason,
        SetupVertex a,
        SetupVertex b,
        SetupVertex c,
        ushort fallbackColor,
        float area,
        int minX,
        int maxX,
        int minY,
        int maxY,
        int clipX0,
        int clipX1,
        int clipY0,
        int clipY1)
    {
        if (!_traceTexturedTriangleRejects || _renderFrame < _traceTextureMinRenderFrame ||
            _texturedTriangleRejectTraceCount++ >= _traceTexturedTriangleRejectsLimit)
            return;

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-TEXREJECT] reason={reason} color=0x{fallbackColor:X4} area={area:F3} " +
            $"bbox=({minX},{minY})-({maxX},{maxY}) clip=({clipX0},{clipY0})-({clipX1},{clipY1}) " +
            $"xy=({a.X:F3},{a.Y:F3})/({b.X:F3},{b.Y:F3})/({c.X:F3},{c.Y:F3}) " +
            $"stq=({a.S:F3},{a.T:F3},{a.Q:F6})/({b.S:F3},{b.T:F3},{b.Q:F6})/({c.S:F3},{c.T:F3},{c.Q:F6}) " +
            $"rawxy=0x{_registers[0x99]:X8}/0x{_registers[0x9A]:X8} setup=0x{_registers[0x98]:X8} " +
            $"cmd=0x{_currentCommandFifoCommand:X8} rd=0x{_cmdFifoReadIndex * 4:X8} fbz=0x{_registers[RegFbzMode]:X8} fbi3=0x{_registers[RegFbiInit3]:X8}{pcStatus}");
    }

    private float GetTextureS(SetupVertex vertex)
    {
        if (!float.IsFinite(vertex.S))
            return _experimentTextureNonFiniteCoordinateZero ? 0.0f : vertex.X;
        return _fixTexturePerspectiveDivide && float.IsFinite(vertex.Q) && MathF.Abs(vertex.Q) > 0.000001f
            ? vertex.S / vertex.Q
            : vertex.S;
    }

    private float GetTextureT(SetupVertex vertex)
    {
        if (!float.IsFinite(vertex.T))
            return _experimentTextureNonFiniteCoordinateZero ? 0.0f : vertex.Y;
        return _fixTexturePerspectiveDivide && float.IsFinite(vertex.Q) && MathF.Abs(vertex.Q) > 0.000001f
            ? vertex.T / vertex.Q
            : vertex.T;
    }

    private static float InterpolateTextureS(SetupVertex a, SetupVertex b, SetupVertex c, float wa, float wb, float wc)
        => TextureSOrX(a) * wa + TextureSOrX(b) * wb + TextureSOrX(c) * wc;

    private static float InterpolateTextureT(SetupVertex a, SetupVertex b, SetupVertex c, float wa, float wb, float wc)
        => TextureTOrY(a) * wa + TextureTOrY(b) * wb + TextureTOrY(c) * wc;

    private static float InterpolateTextureQ(SetupVertex a, SetupVertex b, SetupVertex c, float wa, float wb, float wc)
        => a.Q * wa + b.Q * wb + c.Q * wc;

    private static float TextureSOrX(SetupVertex vertex)
        => float.IsFinite(vertex.S) ? vertex.S : vertex.X;

    private static float TextureTOrY(SetupVertex vertex)
        => float.IsFinite(vertex.T) ? vertex.T : vertex.Y;

    private ushort SampleTextureRgb565MameFixed(long iterS, long iterT, long iterW, int targetLodOverride = -1)
    {
        if (_textureWriteCount == 0)
            return 0;

        uint mode = ReadTextureSampleRegister(RegTextureMode);
        uint textureLod = ReadTextureSampleRegister(RegTextureLod);
        uint textureBase = ReadTextureSampleRegister(RegTextureBaseAddr);
        int targetLod = targetLodOverride >= 0
            ? Math.Clamp(targetLodOverride, 0, 8)
            : GetTextureTargetLod(textureLod, textureBase);
        int format = ResolveTextureSampleFormat(mode, textureLod, textureBase);
        bool sixteenBit = IsTextureFormat16Bit(format);
        int width;
        int height;
        uint baseAddress;
        if (_experimentTextureMameFetchAddressing)
        {
            TextureFetchLayout layout = GetMameTextureFetchLayout(targetLod, mode);
            width = layout.Width;
            height = layout.Height;
            baseAddress = layout.BaseAddress;
        }
        else
        {
            width = Math.Max(1, (int)GetTextureWidth(textureLod) >> targetLod);
            height = Math.Max(1, (int)GetTextureHeight(textureLod) >> targetLod);
            uint sampleBase = GetTextureBaseAddress(textureBase);
            if (_textureSampleBaseBias != 0)
                sampleBase = (uint)((sampleBase + _textureSampleBaseBias) & (TextureBytes - 1));
            baseAddress = GetTextureLodOffsetFromBase(targetLod, GetTextureFormatBytesPerTexel(format), textureLod, sampleBase);
        }

        int s24_8;
        int t24_8;
        if ((mode & 1u) != 0 && iterW != 0)
        {
            double reciprocalW = 256.0 / iterW;
            s24_8 = MameSetupCastToInt32(iterS * reciprocalW);
            t24_8 = MameSetupCastToInt32(iterT * reciprocalW);
        }
        else
        {
            s24_8 = MameSetupCastToInt32(iterS * (1.0 / (1 << 24)));
            t24_8 = MameSetupCastToInt32(iterT * (1.0 / (1 << 24)));
        }
        if ((mode & 0x20u) != 0 && iterW < 0)
            s24_8 = t24_8 = 0;
        if (IsTextureFilteringEnabled(mode))
        {
            s24_8 -= 0x80;
            t24_8 -= 0x80;
        }

        bool clampS = !_experimentTextureCoordinateWrap &&
            (_experimentTextureMameFixedFetch ? (mode & 0x40u) != 0 : _fixTextureCoordinateClamp);
        bool clampT = !_experimentTextureCoordinateWrap &&
            (_experimentTextureMameFixedFetch ? (mode & 0x80u) != 0 : _fixTextureCoordinateClamp);
        int x = Coordinate24_8ToTexelIndex(s24_8, width, targetLod, clampS);
        int y = Coordinate24_8ToTexelIndex(t24_8, height, targetLod, clampT);
        if (_fixTextureTOriginFlip)
            y = Math.Max(0, height - 1) - y;

        ushort result;
        uint byteAddress;
        uint word;
        uint raw;
        if (IsTextureFilteringEnabled(mode))
        {
            int x1 = Coordinate24_8ToTexelIndex(s24_8 + (1 << (targetLod + 8)), width, targetLod, clampS);
            int y1 = Coordinate24_8ToTexelIndex(t24_8 + (1 << (targetLod + 8)), height, targetLod, clampT);
            if (_fixTextureTOriginFlip)
                y1 = Math.Max(0, height - 1) - y1;

            ushort c00 = ReadTextureRgb565At(x, y, width, format, sixteenBit, mode, baseAddress, out byteAddress, out word, out raw);
            ushort c10 = ReadTextureRgb565At(x1, y, width, format, sixteenBit, mode, baseAddress, out _, out _, out _);
            ushort c01 = ReadTextureRgb565At(x, y1, width, format, sixteenBit, mode, baseAddress, out _, out _, out _);
            ushort c11 = ReadTextureRgb565At(x1, y1, width, format, sixteenBit, mode, baseAddress, out _, out _, out _);
            float fx = Coordinate24_8Fraction(s24_8, targetLod);
            float fy = Coordinate24_8Fraction(t24_8, targetLod);
            result = BilinearRgb565(c00, c10, c01, c11, fx, fy);
        }
        else
        {
            result = ReadTextureRgb565At(x, y, width, format, sixteenBit, mode, baseAddress, out byteAddress, out word, out raw);
        }
        TrackZeroTextureSample(byteAddress, result);
        TrackTextureSampleDebug(byteAddress, raw, result);
        TraceTextureSample(s24_8 / 256.0f, t24_8 / 256.0f, width, height, x, y, mode, textureLod, textureBase, baseAddress, byteAddress, word, raw, result);
        return result;
    }

    private readonly record struct TextureRgba(byte R, byte G, byte B, byte A)
    {
        public ushort Rgb565 => Rgb888ToRgb565(R, G, B);
    }

    private TextureRgba SampleTextureMameFixedForTmu(int tmu, long iterS, long iterT, long iterW, int targetLodOverride)
    {
        uint mode = ReadTextureRegisterForTmu(tmu, RegTextureMode);
        uint textureLod = ReadTextureRegisterForTmu(tmu, RegTextureLod);
        uint textureBase = ReadTextureRegisterForTmu(tmu, RegTextureBaseAddr);
        int targetLod = targetLodOverride >= 0
            ? Math.Clamp(targetLodOverride, 0, 8)
            : GetTextureTargetLod(textureLod, textureBase);
        int format = ResolveTextureSampleFormat(mode, textureLod, textureBase);
        TextureFetchLayout layout = GetMameTextureFetchLayout(targetLod, mode, tmu);

        int s24_8;
        int t24_8;
        if ((mode & 1u) != 0 && iterW != 0)
        {
            double reciprocalW = 256.0 / iterW;
            s24_8 = MameSetupCastToInt32(iterS * reciprocalW);
            t24_8 = MameSetupCastToInt32(iterT * reciprocalW);
        }
        else
        {
            s24_8 = MameSetupCastToInt32(iterS * (1.0 / (1 << 24)));
            t24_8 = MameSetupCastToInt32(iterT * (1.0 / (1 << 24)));
        }
        if ((mode & 0x20u) != 0 && iterW < 0)
            s24_8 = t24_8 = 0;

        bool filtered = IsTextureFilteringEnabled(mode);
        if (filtered)
        {
            s24_8 -= 0x80;
            t24_8 -= 0x80;
        }
        bool clampS = !_experimentTextureCoordinateWrap && (mode & 0x40u) != 0;
        bool clampT = !_experimentTextureCoordinateWrap && (mode & 0x80u) != 0;
        int x0 = Coordinate24_8ToTexelIndex(s24_8, layout.Width, targetLod, clampS);
        int y0 = Coordinate24_8ToTexelIndex(t24_8, layout.Height, targetLod, clampT);
        if (_fixTextureTOriginFlip)
            y0 = layout.Height - 1 - y0;
        TextureRgba c00 = ReadTextureRgbaAt(tmu, x0, y0, layout.Width, format, mode, layout.BaseAddress);
        if (!filtered)
            return c00;

        int x1 = Coordinate24_8ToTexelIndex(s24_8 + (1 << (targetLod + 8)), layout.Width, targetLod, clampS);
        int y1 = Coordinate24_8ToTexelIndex(t24_8 + (1 << (targetLod + 8)), layout.Height, targetLod, clampT);
        if (_fixTextureTOriginFlip)
            y1 = layout.Height - 1 - y1;
        TextureRgba c10 = ReadTextureRgbaAt(tmu, x1, y0, layout.Width, format, mode, layout.BaseAddress);
        TextureRgba c01 = ReadTextureRgbaAt(tmu, x0, y1, layout.Width, format, mode, layout.BaseAddress);
        TextureRgba c11 = ReadTextureRgbaAt(tmu, x1, y1, layout.Width, format, mode, layout.BaseAddress);
        int fx = (int)(Coordinate24_8Fraction(s24_8, targetLod) * 256.0f);
        int fy = (int)(Coordinate24_8Fraction(t24_8, targetLod) * 256.0f);
        return BilinearTextureRgba(c00, c10, c01, c11, fx, fy);
    }

    private TextureRgba ReadTextureRgbaAt(int tmu, int x, int y, int width, int format, uint mode, uint baseAddress)
    {
        bool sixteenBit = IsTextureFormat16Bit(format);
        uint texelIndex = (uint)(y * width + x);
        int memoryTmu = _experimentTmu1SampleTmu0Memory && tmu == 1 ? 0 : tmu;
        uint byteAddress = MapTextureBankByteAddress(memoryTmu, baseAddress + texelIndex * (sixteenBit ? 2u : 1u));
        uint word = ReadTexture32(byteAddress & ~3u);
        ushort raw;
        if (sixteenBit)
        {
            uint laneAddress = GetTexture16BitLaneByteAddress(byteAddress);
            raw = (ushort)((word >> (int)((laneAddress & 2u) * 8u)) & 0xffffu);
            if (_experimentTexture16BitByteSwapRegisterBase.HasValue &&
                ReadTextureRegisterForTmu(tmu, RegTextureBaseAddr) == (uint)_experimentTexture16BitByteSwapRegisterBase.Value)
            {
                raw = BinaryPrimitives.ReverseEndianness(raw);
            }
        }
        else
        {
            uint lane = byteAddress & 3u;
            if (_experimentReverse8BitTextureSampleLanes)
                lane = 3u - lane;
            raw = (byte)(word >> (int)(lane * 8u));
        }

        TextureRgba result = DecodeTextureRgba(tmu, format, raw, mode);
        _lastTextureSampleByteAddress = byteAddress;
        _lastTextureSampleRaw = raw;
        _lastTextureSampleResult = result.Rgb565;
        _lastTextureSampleValid = true;
        return result;
    }

    private TextureRgba DecodeTextureRgba(int tmu, int format, ushort raw, uint mode)
    {
        byte low = (byte)raw;
        ushort rgb;
        byte alpha;
        switch (format)
        {
            case 0:
                rgb = ConvertRgb332ToRgb565(low);
                alpha = 255;
                break;
            case 1:
                rgb = ConvertNccToRgb565(tmu, low, mode);
                alpha = 255;
                break;
            case 2:
                return new TextureRgba(low, low, low, low);
            case 3:
                return new TextureRgba(low, low, low, 255);
            case 4:
            {
                byte intensity = (byte)((low & 0x0f) * 17);
                return new TextureRgba(intensity, intensity, intensity, (byte)((low >> 4) * 17));
            }
            case 8:
                rgb = ConvertRgb332ToRgb565(low);
                alpha = (byte)(raw >> 8);
                break;
            case 9:
                rgb = ConvertNccToRgb565(tmu, low, mode);
                alpha = (byte)(raw >> 8);
                break;
            case 10:
                rgb = ConvertRgb565Lane(raw, 0);
                alpha = 255;
                break;
            case 11:
                rgb = ConvertXrgb1555Lane(raw, 0, hasAlphaBit: true);
                alpha = (raw & 0x8000) != 0 ? (byte)255 : (byte)0;
                break;
            case 12:
                rgb = ConvertArgb4444ToRgb565(raw);
                alpha = (byte)(((raw >> 12) & 0x0f) * 17);
                break;
            case 13:
                return new TextureRgba(low, low, low, (byte)(raw >> 8));
            default:
                rgb = ConvertTextureFormatToRgb565(format, raw, mode);
                alpha = 255;
                break;
        }
        Rgb565ToBytes(rgb, out int r, out int g, out int b);
        return new TextureRgba((byte)r, (byte)g, (byte)b, alpha);
    }

    private static TextureRgba BilinearTextureRgba(TextureRgba c00, TextureRgba c10, TextureRgba c01, TextureRgba c11, int fx, int fy)
    {
        static byte Blend(byte a, byte b, byte c, byte d, int x, int y)
        {
            int top = a * (256 - x) + b * x;
            int bottom = c * (256 - x) + d * x;
            return (byte)Math.Clamp((top * (256 - y) + bottom * y + 0x8000) >> 16, 0, 255);
        }
        return new TextureRgba(
            Blend(c00.R, c10.R, c01.R, c11.R, fx, fy),
            Blend(c00.G, c10.G, c01.G, c11.G, fx, fy),
            Blend(c00.B, c10.B, c01.B, c11.B, fx, fy),
            Blend(c00.A, c10.A, c01.A, c11.A, fx, fy));
    }

    private static TextureRgba CombineTextureMame(uint mode, TextureRgba local, TextureRgba other, int lod8p8)
    {
        return new TextureRgba(
            CombineTextureMameChannel(mode, local.R, local.A, other.R, other.A, lod8p8, alpha: false),
            CombineTextureMameChannel(mode, local.G, local.A, other.G, other.A, lod8p8, alpha: false),
            CombineTextureMameChannel(mode, local.B, local.A, other.B, other.A, lod8p8, alpha: false),
            CombineTextureMameChannel(mode, local.A, local.A, other.A, other.A, lod8p8, alpha: true));
    }

    private static byte CombineTextureMameChannel(
        uint mode,
        int local,
        int localAlpha,
        int other,
        int otherAlpha,
        int lod8p8,
        bool alpha)
    {
        int zeroBit = alpha ? 21 : 12;
        int subtractBit = alpha ? 22 : 13;
        int selectShift = alpha ? 23 : 14;
        int reverseBit = alpha ? 26 : 17;
        int addShift = alpha ? 27 : 18;
        int invertBit = alpha ? 29 : 20;
        int value = ((mode >> zeroBit) & 1u) != 0 ? 0 : other;
        if (((mode >> subtractBit) & 1u) != 0)
            value -= local;
        int factor = ((mode >> selectShift) & 7u) switch
        {
            1 => local,
            2 => otherAlpha,
            3 => localAlpha,
            5 => lod8p8 & 0xff,
            _ => 0
        };
        if (((mode >> reverseBit) & 1u) == 0)
            factor ^= 0xff;
        factor++;
        int addSelect = alpha ? (int)((mode >> addShift) & 1u) : (int)((mode >> addShift) & 3u);
        int add = addSelect switch
        {
            1 => local,
            2 when !alpha => localAlpha,
            _ => 0
        };
        value = Math.Clamp((value * factor >> 8) + add, 0, 255);
        if (((mode >> invertBit) & 1u) != 0)
            value ^= 0xff;
        return (byte)value;
    }

    private TextureRgba SampleAndCombineTwoTmusMameFixed(
        long iterS0,
        long iterT0,
        long iterW0,
        int lodBase0_8p8,
        long iterS1,
        long iterT1,
        long iterW1,
        int lodBase1_8p8,
        int x,
        int y,
        int bufferIndex)
    {
        TextureRgba combined = default;
        bool captureTrace = _traceTwoTmuSamples &&
            _renderFrame >= _traceTwoTmuSamplesMinFrame &&
            _twoTmuSampleTraceCount < _traceTwoTmuSamplesLimit;
        int targetLod1 = -1;
        uint address1 = 0;
        ushort raw1 = 0;
        TextureRgba local1 = default;
        TextureSampleWriterKey writer1 = default;
        if (_tmuRegisterValid[1][RegTextureMode] && _tmuRegisterValid[1][RegTextureLod])
        {
            uint mode1 = ReadTextureRegisterForTmu(1, RegTextureMode);
            uint lod1 = ReadTextureRegisterForTmu(1, RegTextureLod);
            targetLod1 = lodBase1_8p8 == int.MinValue
                ? GetTextureTargetLod(lod1, ReadTextureRegisterForTmu(1, RegTextureBaseAddr))
                : ComputeMameTexturePixelLod(lodBase1_8p8, iterW1, x, y, mode1, lod1);
            local1 = SampleTextureMameFixedForTmu(1, iterS1, iterT1, iterW1, targetLod1);
            if (captureTrace)
            {
                address1 = _lastTextureSampleByteAddress;
                raw1 = (ushort)_lastTextureSampleRaw;
                writer1 = GetTextureSampleWriterKey(address1);
            }
            combined = CombineTextureMame(mode1, local1, combined, targetLod1 << 8);
        }
        int targetLod0 = -1;
        uint address0 = 0;
        ushort raw0 = 0;
        TextureRgba local0 = default;
        TextureSampleWriterKey writer0 = default;
        if (_tmuRegisterValid[0][RegTextureMode] && _tmuRegisterValid[0][RegTextureLod])
        {
            uint mode0 = ReadTextureRegisterForTmu(0, RegTextureMode);
            uint lod0 = ReadTextureRegisterForTmu(0, RegTextureLod);
            targetLod0 = lodBase0_8p8 == int.MinValue
                ? GetTextureTargetLod(lod0, ReadTextureRegisterForTmu(0, RegTextureBaseAddr))
                : ComputeMameTexturePixelLod(lodBase0_8p8, iterW0, x, y, mode0, lod0);
            local0 = SampleTextureMameFixedForTmu(0, iterS0, iterT0, iterW0, targetLod0);
            if (captureTrace)
            {
                address0 = _lastTextureSampleByteAddress;
                raw0 = (ushort)_lastTextureSampleRaw;
                writer0 = GetTextureSampleWriterKey(address0);
            }
            combined = CombineTextureMame(mode0, local0, combined, targetLod0 << 8);
        }
        if (captureTrace)
        {
            TraceTwoTmuSample(
                x,
                y,
                iterS0,
                iterT0,
                iterW0,
                targetLod0,
                address0,
                raw0,
                local0,
                writer0,
                iterS1,
                iterT1,
                iterW1,
                targetLod1,
                address1,
                raw1,
                local1,
                writer1,
                combined,
                bufferIndex);
        }
        return combined;
    }

    private void TraceTwoTmuSample(
        int x,
        int y,
        long iterS0,
        long iterT0,
        long iterW0,
        int targetLod0,
        uint address0,
        ushort raw0,
        TextureRgba local0,
        TextureSampleWriterKey writer0,
        long iterS1,
        long iterT1,
        long iterW1,
        int targetLod1,
        uint address1,
        ushort raw1,
        TextureRgba local1,
        TextureSampleWriterKey writer1,
        TextureRgba combined,
        int bufferIndex)
    {
        if (!_traceTwoTmuSamples ||
            _renderFrame < _traceTwoTmuSamplesMinFrame ||
            _twoTmuSampleTraceCount >= _traceTwoTmuSamplesLimit)
        {
            return;
        }

        uint base0 = ReadTextureRegisterForTmu(0, RegTextureBaseAddr);
        if (_traceTwoTmuSamplesTmu0Base.HasValue &&
            base0 != (uint)_traceTwoTmuSamplesTmu0Base.Value)
        {
            return;
        }

        uint mode0 = ReadTextureRegisterForTmu(0, RegTextureMode);
        uint lod0 = ReadTextureRegisterForTmu(0, RegTextureLod);
        uint mode1 = ReadTextureRegisterForTmu(1, RegTextureMode);
        uint lod1 = ReadTextureRegisterForTmu(1, RegTextureLod);
        uint base1 = ReadTextureRegisterForTmu(1, RegTextureBaseAddr);
        uint fbzMode = _registers[RegFbzMode];
        uint fbzColorPath = _registers[RegFbzColorPath];
        _twoTmuSampleTraceCount++;
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-TWO-TMU-SAMPLE] n={_twoTmuSampleTraceCount} frame={_renderFrame} buf={bufferIndex} xy={x},{y} " +
            $"fbz=0x{fbzMode:X8} colorPath=0x{fbzColorPath:X8} " +
            $"tmu0={mode0:X8}/{lod0:X8}/{base0:X8}:lod{targetLod0}:iter{iterS0}/{iterT0}/{iterW0}:addr0x{address0:X6}:raw0x{raw0:X4}:rgba{local0.R:X2}{local0.G:X2}{local0.B:X2}{local0.A:X2} " +
            $"writer0={FormatTextureSampleWriterKey(writer0)} " +
            $"tmu1={mode1:X8}/{lod1:X8}/{base1:X8}:lod{targetLod1}:iter{iterS1}/{iterT1}/{iterW1}:addr0x{address1:X6}:raw0x{raw1:X4}:rgba{local1.R:X2}{local1.G:X2}{local1.B:X2}{local1.A:X2} " +
            $"writer1={FormatTextureSampleWriterKey(writer1)} combined={combined.R:X2}{combined.G:X2}{combined.B:X2}{combined.A:X2}");
    }

    private static int Coordinate24_8ToTexelIndex(int value24_8, int size, int lod, bool clamp)
    {
        int texel = value24_8 >> (lod + 8);
        if (clamp)
            return Math.Clamp(texel, 0, Math.Max(0, size - 1));
        if (size <= 1)
            return 0;
        texel %= size;
        if (texel < 0)
            texel += size;
        return texel;
    }

    private static float Coordinate24_8Fraction(int value24_8, int lod)
    {
        int shifted = value24_8 >> Math.Clamp(lod, 0, 8);
        return (shifted & 0xff) * (1.0f / 256.0f);
    }

    private int ResolveTextureSampleFormat(uint mode, uint textureLod, uint textureBase)
    {
        if (_experimentTextureSampleFormatOverride is >= 0 and <= 15)
            return _experimentTextureSampleFormatOverride;

        if (_experimentRgb332FullrectAsRgb565 &&
            mode == 0x80000009u &&
            textureLod == 0xff802000u &&
            textureBase == 0u)
        {
            return 10;
        }

        return (int)((mode >> 8) & 0x0fu);
    }

    private int GetTextureTargetLod(uint textureLod, uint? textureBase = null)
        => _experimentTextureUseLodMin ||
           _experimentTextureLodMinBaseLevel ||
           (textureBase.HasValue &&
            _experimentTextureLodMinRegisterBase.HasValue &&
            textureBase.Value == (uint)_experimentTextureLodMinRegisterBase.Value)
            ? Math.Clamp((int)(textureLod & 0x3fu) >> 2, 0, 8)
            : Math.Clamp(_experimentTextureForceLod, 0, 8);

    private ushort SampleTextureRgb565(float s, float t, int targetLodOverride = -1)
    {
        if (_textureWriteCount == 0 || !float.IsFinite(s) || !float.IsFinite(t))
            return 0;

        uint mode = ReadTextureSampleRegister(RegTextureMode);
        uint textureLod = ReadTextureSampleRegister(RegTextureLod);
        uint textureBase = ReadTextureSampleRegister(RegTextureBaseAddr);
        int targetLod = targetLodOverride >= 0
            ? Math.Clamp(targetLodOverride, 0, 8)
            : GetTextureTargetLod(textureLod, textureBase);
        int format = ResolveTextureSampleFormat(mode, textureLod, textureBase);
        bool sixteenBit = IsTextureFormat16Bit(format);
        int width;
        int height;
        uint baseAddress;
        if (_experimentTextureMameFetchAddressing)
        {
            TextureFetchLayout layout = GetMameTextureFetchLayout(targetLod, mode);
            width = layout.Width;
            height = layout.Height;
            baseAddress = layout.BaseAddress;
        }
        else
        {
            width = Math.Max(1, (int)GetTextureWidth(textureLod) >> targetLod);
            height = Math.Max(1, (int)GetTextureHeight(textureLod) >> targetLod);
            uint sampleBase = GetTextureBaseAddress(textureBase);
            if (_textureSampleBaseBias != 0)
                sampleBase = (uint)((sampleBase + _textureSampleBaseBias) & (TextureBytes - 1));
            baseAddress = GetTextureLodOffsetFromBase(targetLod, GetTextureFormatBytesPerTexel(format), textureLod, sampleBase);
        }
        bool filtered = IsTextureFilteringEnabled(mode);
        bool scaleCoordinatesByLod = _experimentTextureScaleCoordinatesByLod ||
            (_experimentTextureLodMinRegisterBase.HasValue &&
             textureBase == (uint)_experimentTextureLodMinRegisterBase.Value);
        if (scaleCoordinatesByLod && targetLod > 0)
        {
            float lodScale = 1 << targetLod;
            s /= lodScale;
            t /= lodScale;
        }
        if (_experimentTextureFilterHalfTexel && filtered)
        {
            s -= 0.5f;
            t -= 0.5f;
        }
        bool clampS = !_experimentTextureCoordinateWrap &&
            (!_experimentTextureMameFetchAddressing || (mode & 0x40u) != 0);
        bool clampT = !_experimentTextureCoordinateWrap &&
            (!_experimentTextureMameFetchAddressing || (mode & 0x80u) != 0);
        int x = TextureCoordinateToIndex(s, width, clampS);
        int y = _fixTextureTOriginFlip
            ? TextureCoordinateToIndex((height - 1) - t, height, clampT)
            : TextureCoordinateToIndex(t, height, clampT);
        TraceTextureFetchCompare(
            s,
            t,
            mode,
            textureLod,
            targetLod,
            format,
            sixteenBit,
            filtered,
            width,
            height,
            baseAddress,
            clampS,
            clampT,
            x,
            y);
        if (_experimentFullrectSampleWriterLayout)
        {
            uint currentTexelIndex = (uint)(y * width + x);
            uint currentByteAddress = (baseAddress + currentTexelIndex * (sixteenBit ? 2u : 1u)) & (TextureBytes - 1u);
            if (TrySampleFullrectTextureFromWriterLayout(
                    s,
                    t,
                    width,
                    height,
                    clampS,
                    clampT,
                    currentByteAddress,
                    mode,
                    textureLod,
                    textureBase,
                    out ushort writerLayoutTexel))
            {
                return writerLayoutTexel;
            }
        }

        if (_fixTextureBilinearFilter && filtered)
            return SampleTextureRgb565Bilinear(s, t, width, height, mode, format, sixteenBit, baseAddress);

        return SampleTextureRgb565Nearest(s, t, width, height, x, y, clampS, clampT, mode, textureLod, textureBase, format, sixteenBit, baseAddress);
    }

    private ushort SampleTextureRgb565Nearest(
        float s,
        float t,
        int width,
        int height,
        int x,
        int y,
        bool clampS,
        bool clampT,
        uint mode,
        uint textureLod,
        uint textureBase,
        int format,
        bool sixteenBit,
        uint baseAddress)
    {
        uint texelIndex = (uint)(y * width + x);
        if (sixteenBit)
        {
            uint byteAddress = MapTextureSampleBankByteAddress(baseAddress + texelIndex * 2u);
            if (TrySampleFullrectTextureFromWriterLayout(
                    s,
                    t,
                    width,
                    height,
                    clampS,
                    clampT,
                    byteAddress,
                    mode,
                    textureLod,
                    textureBase,
                    out ushort writerLayoutResult))
            {
                return writerLayoutResult;
            }

            uint word = ReadTexture32(byteAddress & ~3u);
            uint laneByteAddress = GetTexture16BitLaneByteAddress(byteAddress);
            ushort packed = (ushort)((word >> (int)((laneByteAddress & 2u) * 8u)) & 0xffffu);
            packed = MaybeSwapTexture16BitBytes(packed);
            ushort result = ConvertTextureFormatToRgb565(format, packed, mode);
            TrackZeroTextureSample(byteAddress, result);
            TrackTextureSampleDebug(byteAddress, packed, result);
            TraceTextureSample(s, t, width, height, x, y, mode, textureLod, textureBase, baseAddress, byteAddress, word, packed, result);
            return result;
        }

        uint byteOffset = MapTextureSampleBankByteAddress(baseAddress + texelIndex);
        if (TrySampleFullrectTextureFromWriterLayout(
                s,
                t,
                width,
                height,
                clampS,
                clampT,
                byteOffset,
                mode,
                textureLod,
                textureBase,
                out ushort writerLayoutTexel))
        {
            return writerLayoutTexel;
        }

        uint source = ReadTexture32(byteOffset & ~3u);
        uint lane = byteOffset & 3u;
        if (_experimentReverse8BitTextureSampleLanes)
            lane = 3u - lane;
        byte value = (byte)(source >> (int)(lane * 8u));
        ushort texel = format switch
        {
            0 => ConvertRgb332ToRgb565(value),
            1 => ConvertNccToRgb565(value, mode),
            2 => GrayscaleToRgb565(value),
            3 => GrayscaleToRgb565(value),
            4 => GrayscaleToRgb565((byte)((value & 0x0f) * 17)),
            5 or 6 or 7 => ConvertPaletteTextureToRgb565(value, format),
            _ => PseudoPaletteToRgb565(value)
        };
        TrackZeroTextureSample(byteOffset, texel);
        TrackTextureSampleDebug(byteOffset, value, texel);
        TraceTextureSample(s, t, width, height, x, y, mode, textureLod, textureBase, baseAddress, byteOffset, source, value, texel);
        return texel;
    }

    private bool TrySampleFullrectTextureFromWriterLayout(
        float s,
        float t,
        int currentWidth,
        int currentHeight,
        bool clampS,
        bool clampT,
        uint currentByteAddress,
        uint sampleMode,
        uint sampleTextureLod,
        uint sampleTextureBase,
        out ushort result)
    {
        result = 0;
        if (!_experimentFullrectSampleWriterLayout ||
            _currentCommandFifoCommand != 0x0180a8cbu)
        {
            return false;
        }

        int currentWordOffset = (int)((currentByteAddress & (TextureBytes - 1u)) >> 2);
        if (!_textureWordLastWriters.TryGetValue(currentWordOffset, out TextureWordLastWriter writer) ||
            !writer.Type5 ||
            writer.BytesPerTexel is not (1 or 2))
        {
            return false;
        }

        int writerLod = Math.Clamp((int)writer.Lod, 0, 8);
        int writerFormat = (int)((writer.Mode >> 8) & 0x0fu);
        bool writerFormatOverridden = _experimentFullrectSampleWriterLayoutFormatOverride is >= 0 and <= 15;
        if (writerFormatOverridden)
            writerFormat = _experimentFullrectSampleWriterLayoutFormatOverride;
        int writerBytesPerTexel = IsTextureFormat16Bit(writerFormat) ? 2 : writer.BytesPerTexel;
        bool writerSixteenBit = writerBytesPerTexel == 2;
        int writerWidth = Math.Max(1, (int)GetTextureWidth(writer.TexLod) >> writerLod);
        int writerHeight = Math.Max(1, (int)GetTextureHeight(writer.TexLod) >> writerLod);
        uint writerBase = GetTextureLodOffset(writerLod, writerBytesPerTexel, writer.TexLod, writer.TextureBase);
        uint writerTargetStart = writer.Type5TargetStart;
        bool writerTargetRemapped = false;
        if (_experimentFullrectSampleWriterLayoutTargetRemap.TryGetValue(writer.Type5TargetStart, out uint remappedTargetStart))
        {
            long targetDeltaBytes = ((long)remappedTargetStart - writer.Type5TargetStart) << 2;
            writerBase = (uint)(((long)writerBase + targetDeltaBytes) & (TextureBytes - 1L));
            writerTargetStart = remappedTargetStart;
            writerTargetRemapped = true;
        }
        if (_experimentFullrectSampleWriterLayoutBaseBias != 0)
            writerBase = (uint)(((long)writerBase + _experimentFullrectSampleWriterLayoutBaseBias) & (TextureBytes - 1L));

        float writerS = s;
        float writerT = t;
        bool writerClampS = clampS;
        bool writerClampT = clampT;
        if (_experimentFullrectSampleWriterLayoutCoordMode is "wrap" or "wrapped")
        {
            writerClampS = false;
            writerClampT = false;
        }
        else if (_experimentFullrectSampleWriterLayoutCoordMode is "scale" or "scaled")
        {
            writerS = currentWidth > 0 ? s * writerWidth / currentWidth : s;
            writerT = currentHeight > 0 ? t * writerHeight / currentHeight : t;
        }
        else if (_experimentFullrectSampleWriterLayoutCoordMode is "scale-wrap" or "scaled-wrap")
        {
            writerS = currentWidth > 0 ? s * writerWidth / currentWidth : s;
            writerT = currentHeight > 0 ? t * writerHeight / currentHeight : t;
            writerClampS = false;
            writerClampT = false;
        }

        int writerX = TextureCoordinateToIndex(writerS, writerWidth, writerClampS);
        int writerY = _fixTextureTOriginFlip
            ? TextureCoordinateToIndex((writerHeight - 1) - writerT, writerHeight, writerClampT)
            : TextureCoordinateToIndex(writerT, writerHeight, writerClampT);

        float layoutS = writerS;
        float layoutT = writerT;
        int layoutX = writerX;
        int layoutY = writerY;
        int layoutWidth = writerWidth;
        int layoutHeight = writerHeight;
        uint layoutBase = writerBase;
        string relookupStatus = "-";

        result = ReadFullrectWriterLayoutTextureRgb565At(
            writerX,
            writerY,
            writerWidth,
            writerHeight,
            writerFormat,
            writerSixteenBit,
            sampleMode,
            writerBase,
            out uint writerByteAddress,
            out uint writerWord,
            out uint writerRaw);
        uint initialWriterByteAddress = writerByteAddress;
        int initialSampledWordOffset = (int)((initialWriterByteAddress & (TextureBytes - 1u)) >> 2);
        bool hasSampledOwner = _textureWordLastWriters.TryGetValue(initialSampledWordOffset, out TextureWordLastWriter sampledWriter);

        if (_experimentFullrectSampleWriterLayoutRequireArtOwner)
        {
            bool sampledTargetTranslated = TryReadFullrectSampledTargetDeltaArtOwner(
                initialWriterByteAddress,
                sampledWriter,
                hasSampledOwner,
                writerX,
                writerY,
                writerWidth,
                writerHeight,
                out writerByteAddress,
                out writerWord,
                out writerRaw,
                out result,
                out string artOwnerStatus);
            bool sampledTargetLookupMiss =
                !sampledTargetTranslated &&
                _experimentFullrectSampleWriterLayoutArtOwnerSampledTargetLookup &&
                _experimentFullrectSampleWriterLayoutArtOwnerSampledTargetLookupStrict &&
                (_experimentFullrectSampleWriterLayoutArtOwnerSampledTargetDelta != 0 ||
                 HasSampledTargetSurface()) &&
                hasSampledOwner &&
                sampledWriter.Type5;
            if (sampledTargetLookupMiss ||
                (!sampledTargetTranslated &&
                !TrySelectFullrectWriterLayoutArtOwnerCandidate(
                    writerX,
                    writerY,
                    writerWidth,
                    writerHeight,
                    writerFormat,
                    writerSixteenBit,
                    sampleMode,
                    writerBase,
                    out writerByteAddress,
                    out writerWord,
                    out writerRaw,
                    out result,
                    out artOwnerStatus)))
            {
                if (_fullrectSampleWriterLayoutArtOwnerTraceCount++ < _experimentFullrectSampleWriterLayoutArtOwnerTraceLimit)
                {
                    string sampledOwnerStatus = hasSampledOwner
                        ? FormatTextureWordWriterStatus(sampledWriter)
                        : "-";
                    Console.WriteLine(
                        $"[GAUNTDL:EXPERIMENT] fullrect-sample-writer-layout-art-owner reject " +
                        $"initialAddr=0x{initialWriterByteAddress:X6}/w{initialSampledWordOffset:X5} raw=0x{writerRaw:X4} rgb=0x{result:X4} " +
                        $"writer=pc0x{writer.Pc & 0xffffffffUL:x8}/cmd0x{writer.Type5Command:X8}@0x{writer.Type5TargetStart:X6}:0x{writer.Type5TargetWord:X6} " +
                        $"sampledOwner={sampledOwnerStatus} reason={artOwnerStatus}");
                }

                return false;
            }

            if (_fullrectSampleWriterLayoutArtOwnerTraceCount++ < _experimentFullrectSampleWriterLayoutArtOwnerTraceLimit)
            {
                int artWordOffset = (int)((writerByteAddress & (TextureBytes - 1u)) >> 2);
                Console.WriteLine(
                    $"[GAUNTDL:EXPERIMENT] fullrect-sample-writer-layout-art-owner accept " +
                    $"initialAddr=0x{initialWriterByteAddress:X6}/w{initialSampledWordOffset:X5} -> addr=0x{writerByteAddress:X6}/w{artWordOffset:X5} " +
                    $"raw=0x{writerRaw:X4} rgb=0x{result:X4} {artOwnerStatus}");
            }
        }

        if (_experimentFullrectSampleWriterLayoutRelookupSampledOwner &&
            hasSampledOwner &&
            sampledWriter.Type5 &&
            sampledWriter.BytesPerTexel is 1 or 2)
        {
            int ownerLod = Math.Clamp((int)sampledWriter.Lod, 0, 8);
            int ownerFormat = (int)((sampledWriter.Mode >> 8) & 0x0fu);
            bool ownerFormatOverridden = _experimentFullrectSampleWriterLayoutFormatOverride is >= 0 and <= 15;
            if (ownerFormatOverridden)
                ownerFormat = _experimentFullrectSampleWriterLayoutFormatOverride;
            int ownerBytesPerTexel = IsTextureFormat16Bit(ownerFormat) ? 2 : sampledWriter.BytesPerTexel;
            bool ownerSixteenBit = ownerBytesPerTexel == 2;
            int ownerWidth = Math.Max(1, (int)GetTextureWidth(sampledWriter.TexLod) >> ownerLod);
            int ownerHeight = Math.Max(1, (int)GetTextureHeight(sampledWriter.TexLod) >> ownerLod);
            uint ownerBase = GetTextureLodOffset(ownerLod, ownerBytesPerTexel, sampledWriter.TexLod, sampledWriter.TextureBase);
            if (_experimentFullrectSampleWriterLayoutBaseBias != 0)
                ownerBase = (uint)(((long)ownerBase + _experimentFullrectSampleWriterLayoutBaseBias) & (TextureBytes - 1L));

            float ownerS = s;
            float ownerT = t;
            bool ownerClampS = clampS;
            bool ownerClampT = clampT;
            if (_experimentFullrectSampleWriterLayoutCoordMode is "wrap" or "wrapped")
            {
                ownerClampS = false;
                ownerClampT = false;
            }
            else if (_experimentFullrectSampleWriterLayoutCoordMode is "scale" or "scaled")
            {
                ownerS = currentWidth > 0 ? s * ownerWidth / currentWidth : s;
                ownerT = currentHeight > 0 ? t * ownerHeight / currentHeight : t;
            }
            else if (_experimentFullrectSampleWriterLayoutCoordMode is "scale-wrap" or "scaled-wrap")
            {
                ownerS = currentWidth > 0 ? s * ownerWidth / currentWidth : s;
                ownerT = currentHeight > 0 ? t * ownerHeight / currentHeight : t;
                ownerClampS = false;
                ownerClampT = false;
            }

            int ownerX = TextureCoordinateToIndex(ownerS, ownerWidth, ownerClampS);
            int ownerY = _fixTextureTOriginFlip
                ? TextureCoordinateToIndex((ownerHeight - 1) - ownerT, ownerHeight, ownerClampT)
                : TextureCoordinateToIndex(ownerT, ownerHeight, ownerClampT);

            result = ReadFullrectWriterLayoutTextureRgb565At(
                ownerX,
                ownerY,
                ownerWidth,
                ownerHeight,
                ownerFormat,
                ownerSixteenBit,
                sampleMode,
                ownerBase,
                out writerByteAddress,
                out writerWord,
                out writerRaw);

            layoutS = ownerS;
            layoutT = ownerT;
            layoutX = ownerX;
            layoutY = ownerY;
            layoutWidth = ownerWidth;
            layoutHeight = ownerHeight;
            layoutBase = ownerBase;
            relookupStatus =
                $"sampled-owner fmt{ownerFormat}{(ownerFormatOverridden ? "*" : "")}/bpp{ownerBytesPerTexel}/l{ownerLod} " +
                $"addr=0x{writerByteAddress:X6}";
        }

        TraceFullrectWriterLayoutCandidates(
            s,
            t,
            currentWidth,
            currentHeight,
            clampS,
            clampT,
            currentByteAddress,
            currentWordOffset,
            sampleMode,
            sampleTextureLod,
            sampleTextureBase,
            writer,
            writerX,
            writerY,
            writerWidth,
            writerHeight,
            writerFormat,
            writerFormatOverridden,
            writerBytesPerTexel,
            writerSixteenBit,
            writerLod,
            writerBase,
            writerTargetStart,
            writerTargetRemapped,
            hasSampledOwner,
            sampledWriter,
            writerByteAddress,
            result);

        TrackZeroTextureSample(writerByteAddress, result);
        TrackTextureSampleDebug(writerByteAddress, writerRaw, result);
        TraceTextureSample(
            s,
            t,
            layoutWidth,
            layoutHeight,
            layoutX,
            layoutY,
            sampleMode,
            sampleTextureLod,
            sampleTextureBase,
            layoutBase,
            writerByteAddress,
            writerWord,
            writerRaw,
            result);

        if (_fullrectSampleWriterLayoutTraceCount++ < 32)
        {
            int finalWordOffset = (int)((writerByteAddress & (TextureBytes - 1u)) >> 2);
            string sampledOwner = hasSampledOwner
                ? FormatTextureWordWriterStatus(sampledWriter)
                : "-";
            string finalOwner = _textureWordLastWriters.TryGetValue(finalWordOffset, out TextureWordLastWriter finalWriter)
                ? FormatTextureWordWriterStatus(finalWriter)
                : "-";
            string finalWindow = FormatTextureWordWindow(finalWordOffset, 2);

            Console.WriteLine(
                $"[GAUNTDL:EXPERIMENT] fullrect-sample-writer-layout " +
                $"current=0x{currentByteAddress:X6}/w{currentWordOffset:X5} -> addr=0x{writerByteAddress:X6}/w{finalWordOffset:X5} " +
                $"initialAddr=0x{initialWriterByteAddress:X6}/w{initialSampledWordOffset:X5} " +
                $"mode={(_experimentFullrectSampleWriterLayoutCoordMode.Length == 0 ? "clamp" : _experimentFullrectSampleWriterLayoutCoordMode)} " +
                $"st=({s:F3},{t:F3})->({layoutS:F3},{layoutT:F3}) xy={layoutX},{layoutY} size={layoutWidth}x{layoutHeight} " +
                $"sample=mode0x{sampleMode:X8}/lod0x{sampleTextureLod:X8}/base0x{sampleTextureBase:X8} " +
                $"addrTransform={(_experimentFullrectSampleWriterLayoutAddressTransform.Length == 0 ? "-" : _experimentFullrectSampleWriterLayoutAddressTransform)} " +
                $"word=0x{writerWord:X8} raw=0x{writerRaw:X4} rgb=0x{result:X4} " +
                $"writer=pc0x{writer.Pc & 0xffffffffUL:x8}/mode0x{writer.Mode:X8}/lod0x{writer.TexLod:X8}/base0x{writer.TextureBase:X8}/l{writer.Lod}/bpp{writerBytesPerTexel}/fmt{writerFormat}{(writerFormatOverridden ? "*" : "")} " +
                $"type5=0x{writer.Type5Command:X8}@0x{writer.Type5TargetStart:X6}:0x{writer.Type5TargetWord:X6} " +
                $"targetRemap={(writerTargetRemapped ? $"0x{writer.Type5TargetStart:X6}->0x{writerTargetStart:X6}" : "-")} baseBias={_experimentFullrectSampleWriterLayoutBaseBias} " +
                $"sampledOwner={sampledOwner} finalOwner={finalOwner} finalWords={finalWindow} relookup={relookupStatus}");
        }

        return true;
    }

    private bool TryReadFullrectSampledTargetDeltaArtOwner(
        uint sampledByteAddress,
        TextureWordLastWriter sampledOwner,
        bool hasSampledOwner,
        int x,
        int y,
        int width,
        int height,
        out uint byteAddress,
        out uint word,
        out uint raw,
        out ushort result,
        out string status)
    {
        byteAddress = 0;
        word = 0;
        raw = 0;
        result = 0;
        status = "sampled-target-delta-disabled";
        int targetDelta = _experimentFullrectSampleWriterLayoutArtOwnerSampledTargetDelta;
        bool useSurface = HasSampledTargetSurface();
        if ((!useSurface && targetDelta == 0) ||
            !hasSampledOwner ||
            !sampledOwner.Type5 ||
            sampledOwner.BytesPerTexel is not (1 or 2))
        {
            return false;
        }

        if (!useSurface &&
            IsValidFullrectWriterLayoutArtOwner(sampledOwner) &&
            !IsRejectedFullrectWriterLayoutArtOwnerPayload(sampledOwner))
        {
            byteAddress = sampledByteAddress & (TextureBytes - 1u);
            int sampledFormat = (int)((sampledOwner.Mode >> 8) & 0x0fu);
            if (_experimentFullrectSampleWriterLayoutFormatOverride is >= 0 and <= 15)
                sampledFormat = _experimentFullrectSampleWriterLayoutFormatOverride;
            bool sampledSixteenBit = sampledOwner.BytesPerTexel == 2 || IsTextureFormat16Bit(sampledFormat);
            result = ReadTextureRgb565AtByteAddress(
                byteAddress,
                sampledFormat,
                sampledSixteenBit,
                sampledOwner.Mode,
                out word,
                out raw);
            status = $"transform=sampledtargetdelta delta=identity lookup=1 owner={FormatTextureWordWriterStatus(sampledOwner)}";
            return raw != 0 && result != 0;
        }

        uint translatedTargetStart;
        int translatedIndex;
        uint translatedLane;
        if (useSurface)
        {
            int surfaceWidth = _experimentFullrectSampleWriterLayoutArtOwnerSampledTargetSurfaceWidth;
            int surfaceHeight = _experimentFullrectSampleWriterLayoutArtOwnerSampledTargetSurfaceHeight;
            int surfaceX = Math.Clamp(width > 0 ? (int)((long)x * surfaceWidth / width) : x, 0, surfaceWidth - 1);
            int surfaceY = Math.Clamp(height > 0 ? (int)((long)y * surfaceHeight / height) : y, 0, surfaceHeight - 1);
            translatedTargetStart = unchecked(
                (uint)(_experimentFullrectSampleWriterLayoutArtOwnerSampledTargetSurfaceBase!.Value +
                       (ulong)surfaceY * _experimentFullrectSampleWriterLayoutArtOwnerSampledTargetSurfaceRowStride));
            translatedIndex = surfaceX >> 1;
            translatedLane = (uint)((surfaceX & 1) << 1);
        }
        else
        {
            translatedTargetStart = unchecked((uint)((long)sampledOwner.Type5TargetStart + targetDelta));
            translatedIndex = sampledOwner.Type5Index;
            uint sourceLane = sampledByteAddress & 3u;
            translatedLane = sourceLane >= 2u ? 2u : 0u;
        }

        var translatedKey = new FullrectTargetIndexKey(translatedTargetStart, translatedIndex);
        bool usedTargetLookup = false;
        int translatedWordOffset = -1;
        if (_experimentFullrectSampleWriterLayoutArtOwnerSampledTargetLookup &&
            translatedIndex >= 0 &&
            _textureTargetIndexWords.TryGetValue(translatedKey, out translatedWordOffset))
        {
            byteAddress = (uint)((translatedWordOffset << 2) | (int)translatedLane);
            usedTargetLookup = true;
        }
        else if (useSurface)
        {
            status =
                $"sampled-target-surface-no-owner key=0x{translatedKey.TargetStart:X6}:{translatedKey.Index} lookup=miss";
            TraceSampledTargetTransition(sampledOwner, translatedTargetStart, -1, false, "none", "surface-miss");
            return false;
        }
        else
        {
            long deltaBytes = (long)targetDelta << 2;
            byteAddress = (uint)(((long)sampledByteAddress + deltaBytes) & (TextureBytes - 1L));
        }
        int wordOffset = (int)(byteAddress >> 2);
        bool hasPhysicalOwner = _textureWordLastWriters.TryGetValue(wordOffset, out TextureWordLastWriter physicalOwner);
        bool hasArtOwner = TryGetFullrectWriterLayoutArtOwner(wordOffset, out TextureWordLastWriter owner);
        bool targetMismatch = usedTargetLookup && hasArtOwner &&
            (owner.Type5TargetStart != translatedTargetStart || owner.Type5Index != translatedIndex);
        bool rejectedPayload = hasArtOwner && IsRejectedFullrectWriterLayoutArtOwnerPayload(owner);
        if (!hasArtOwner || targetMismatch || rejectedPayload)
        {
            string lookupStatus = !_experimentFullrectSampleWriterLayoutArtOwnerSampledTargetLookup
                ? "off"
                : translatedIndex < 0
                    ? "invalid-index"
                    : usedTargetLookup
                        ? $"hit:w0x{translatedWordOffset:X5}"
                        : "miss";
            string physicalOwnerStatus = hasPhysicalOwner
                ? FormatTextureWordWriterStatus(physicalOwner)
                : "none";
            string failure = targetMismatch
                ? "target-mismatch"
                : rejectedPayload
                    ? "rejected-payload"
                    : hasPhysicalOwner
                        ? "owner-not-allowed"
                        : "physical-unowned";
            status =
                $"sampled-target-delta-no-owner delta=0x{targetDelta:X} " +
                $"key=0x{translatedKey.TargetStart:X6}:{translatedKey.Index} lookup={lookupStatus} " +
                $"addr=0x{byteAddress:X6}/w0x{wordOffset:X5} failure={failure} physicalOwner={physicalOwnerStatus}";
            TraceSampledTargetTransition(sampledOwner, translatedTargetStart, wordOffset, usedTargetLookup, physicalOwnerStatus, failure);
            return false;
        }

        int ownerFormat = (int)((owner.Mode >> 8) & 0x0fu);
        if (_experimentFullrectSampleWriterLayoutFormatOverride is >= 0 and <= 15)
            ownerFormat = _experimentFullrectSampleWriterLayoutFormatOverride;
        bool ownerSixteenBit = owner.BytesPerTexel == 2 || IsTextureFormat16Bit(ownerFormat);
        result = ReadTextureRgb565AtByteAddress(
            byteAddress,
            ownerFormat,
            ownerSixteenBit,
            owner.Mode,
            out word,
            out raw);
        status =
            $"transform={(useSurface ? "sampledtargetsurface" : "sampledtargetdelta")} " +
            $"delta=0x{targetDelta:X} lookup={(usedTargetLookup ? 1 : 0)} " +
            $"source={FormatTextureWordWriterStatus(sampledOwner)} owner={FormatTextureWordWriterStatus(owner)}";
        TraceSampledTargetTransition(
            sampledOwner,
            translatedTargetStart,
            wordOffset,
            usedTargetLookup,
            FormatTextureWordWriterStatus(owner),
            "accept");
        return raw != 0 && result != 0;
    }

    private bool HasSampledTargetSurface() =>
        _experimentFullrectSampleWriterLayoutArtOwnerSampledTargetSurfaceBase.HasValue &&
        _experimentFullrectSampleWriterLayoutArtOwnerSampledTargetSurfaceWidth > 0 &&
        _experimentFullrectSampleWriterLayoutArtOwnerSampledTargetSurfaceHeight > 0;

    private void TraceSampledTargetTransition(
        TextureWordLastWriter source,
        uint translatedTargetStart,
        int physicalWordOffset,
        bool usedTargetLookup,
        string ownerStatus,
        string result)
    {
        if (!_traceSampledTargetTransitions ||
            _sampledTargetTransitionKeys.Count >= _traceSampledTargetTransitionLimit)
        {
            return;
        }

        string key = $"{source.Type5TargetStart:X6}:{translatedTargetStart:X6}:{source.Type5PayloadHash:X8}:{result}";
        if (!_sampledTargetTransitionKeys.Add(key))
            return;

        Console.WriteLine(
            $"[GAUNTDL:SAMPLED-TARGET-TRANSITION] n={_sampledTargetTransitionKeys.Count} result={result} " +
            $"source=0x{source.Type5TargetStart:X6}:idx{source.Type5Index}/{source.Type5Count}:ph0x{source.Type5PayloadHash:X8} " +
            $"sourceState=mode0x{source.Mode:X8}/lod0x{source.TexLod:X8}/base0x{source.TextureBase:X8}/l{source.Lod}/bpp{source.BytesPerTexel} " +
            $"destination=0x{translatedTargetStart:X6}:w0x{physicalWordOffset:X5}:lookup={(usedTargetLookup ? 1 : 0)} owner={ownerStatus}");
    }

    private bool TrySelectFullrectWriterLayoutArtOwnerCandidate(
        int x,
        int y,
        int width,
        int height,
        int format,
        bool sixteenBit,
        uint textureMode,
        uint baseAddress,
        out uint byteAddress,
        out uint word,
        out uint raw,
        out ushort result,
        out string status)
    {
        byteAddress = 0;
        word = 0;
        raw = 0;
        result = 0;
        status = "no-art-owner";
        FullrectArtOwnerCandidate best = default;
        bool hasBest = false;
        List<string>? scoreStatuses = _experimentFullrectSampleWriterLayoutArtOwnerScoreTransforms ? new List<string>() : null;

        foreach (string transform in EnumerateFullrectWriterLayoutArtOwnerCandidateTransforms())
        {
            if (!TryReadFullrectWriterLayoutArtOwnerCandidate(
                    x,
                    y,
                    width,
                    height,
                    format,
                    sixteenBit,
                    textureMode,
                    baseAddress,
                    transform,
                    out FullrectArtOwnerCandidate candidate))
            {
                scoreStatuses?.Add($"{transform}:owner-");
                continue;
            }

            if (candidate.Raw == 0)
            {
                scoreStatuses?.Add($"{transform}:raw0");
                status = $"zero-raw transform={transform} owner={FormatTextureWordWriterStatus(candidate.Owner)}";
                continue;
            }

            if (candidate.Result == 0)
            {
                scoreStatuses?.Add($"{transform}:rgb0/raw0x{candidate.Raw:X4}");
                status = $"zero-rgb transform={transform} raw=0x{candidate.Raw:X4} owner={FormatTextureWordWriterStatus(candidate.Owner)}";
                continue;
            }

            if (!_experimentFullrectSampleWriterLayoutArtOwnerScoreTransforms)
            {
                byteAddress = candidate.ByteAddress;
                word = candidate.Word;
                raw = candidate.Raw;
                result = candidate.Result;
                status = FormatFullrectArtOwnerCandidateStatus(candidate);
                return true;
            }

            int score = ScoreFullrectWriterLayoutArtOwnerCandidate(
                x,
                y,
                width,
                height,
                format,
                sixteenBit,
                textureMode,
                baseAddress,
                transform,
                candidate.Owner.Type5TargetStart,
                out int nonZeroRgb,
                out int sameOwner,
                out int colorChanges);
            if (IsPreferredFullrectWriterLayoutArtOwner(candidate.Owner))
                score += _experimentFullrectSampleWriterLayoutArtOwnerPreferBonus;
            candidate = candidate with
            {
                Score = score,
                NonZeroRgb = nonZeroRgb,
                SameOwner = sameOwner,
                ColorChanges = colorChanges
            };
            scoreStatuses?.Add($"{transform}:{candidate.Score}/nz{candidate.NonZeroRgb}/same{candidate.SameOwner}/chg{candidate.ColorChanges}/rgb0x{candidate.Result:X4}");

            if (!hasBest || candidate.Score > best.Score)
            {
                best = candidate;
                hasBest = true;
            }
        }

        if (!hasBest)
            return false;

        byteAddress = best.ByteAddress;
        word = best.Word;
        raw = best.Raw;
        result = best.Result;
        status = FormatFullrectArtOwnerCandidateStatus(best);
        if (scoreStatuses is { Count: > 0 })
            status += $" scores=[{string.Join(",", scoreStatuses)}]";
        TraceFullrectArtOwnerSelectedCandidate(x, y, width, height, best);
        return true;
    }

    private bool TryReadFullrectWriterLayoutArtOwnerCandidate(
        int x,
        int y,
        int width,
        int height,
        int format,
        bool sixteenBit,
        uint textureMode,
        uint baseAddress,
        string transform,
        out FullrectArtOwnerCandidate candidate)
    {
        if (IsFullrectWriterLayoutPacketLocalTransform(transform))
        {
            return TryReadFullrectWriterLayoutPacketLocalArtOwnerCandidate(
                x,
                y,
                width,
                height,
                format,
                sixteenBit,
                textureMode,
                baseAddress,
                transform,
                out candidate);
        }
        if (IsFullrectWriterLayoutTargetLocalTransform(transform))
        {
            return TryReadFullrectWriterLayoutTargetLocalArtOwnerCandidate(
                x,
                y,
                width,
                height,
                format,
                sixteenBit,
                textureMode,
                baseAddress,
                transform,
                out candidate);
        }
        if (IsFullrectWriterLayoutPreferredSeedTransform(transform))
        {
            return TryReadFullrectWriterLayoutPreferredSeedArtOwnerCandidate(
                x,
                y,
                width,
                height,
                transform,
                out candidate);
        }

        ushort sampleDecoded = ReadFullrectWriterLayoutTextureRgb565At(
            x,
            y,
            width,
            height,
            format,
            sixteenBit,
            textureMode,
            baseAddress,
            transform,
            out uint candidateByteAddress,
            out uint candidateWord,
            out uint candidateRaw);
        int candidateWordOffset = (int)((candidateByteAddress & (TextureBytes - 1u)) >> 2);
        if (!TryGetFullrectWriterLayoutArtOwner(candidateWordOffset, out TextureWordLastWriter owner) ||
            IsRejectedFullrectWriterLayoutArtOwnerPayload(owner))
        {
            candidate = default;
            return false;
        }

        int ownerFormat = (int)((owner.Mode >> 8) & 0x0fu);
        bool ownerSixteenBit = owner.BytesPerTexel == 2 || IsTextureFormat16Bit(ownerFormat);
        if (_experimentFullrectSampleWriterLayoutArtOwnerRebaseToOwner)
        {
            int ownerLod = Math.Clamp((int)owner.Lod, 0, 8);
            int ownerBytesPerTexel = ownerSixteenBit ? 2 : owner.BytesPerTexel;
            int ownerWidth = Math.Max(1, (int)GetTextureWidth(owner.TexLod) >> ownerLod);
            int ownerHeight = Math.Max(1, (int)GetTextureHeight(owner.TexLod) >> ownerLod);
            uint ownerBase = GetTextureLodOffset(ownerLod, ownerBytesPerTexel, owner.TexLod, owner.TextureBase);
            if (_experimentFullrectSampleWriterLayoutBaseBias != 0)
                ownerBase = (uint)(((long)ownerBase + _experimentFullrectSampleWriterLayoutBaseBias) & (TextureBytes - 1L));

            sampleDecoded = ReadFullrectWriterLayoutTextureRgb565At(
                Math.Clamp(x, 0, Math.Max(0, ownerWidth - 1)),
                Math.Clamp(y, 0, Math.Max(0, ownerHeight - 1)),
                ownerWidth,
                ownerHeight,
                ownerFormat,
                ownerSixteenBit,
                owner.Mode,
                ownerBase,
                transform,
                out candidateByteAddress,
                out candidateWord,
                out candidateRaw);
        }

        ushort ownerDecoded = DecodeTextureRawToRgb565(candidateRaw, ownerFormat, ownerSixteenBit, owner.Mode);
        if (ownerDecoded == 0 &&
            _experimentFullrectSampleWriterLayoutArtOwnerDecodeHighByteFallback &&
            ownerSixteenBit &&
            ownerFormat is 8 or 9)
        {
            ownerDecoded = DecodeTextureRawToRgb565(candidateRaw >> 8, ownerFormat & 1, sixteenBit: false, owner.Mode);
        }
        candidate = new FullrectArtOwnerCandidate(
            transform,
            candidateByteAddress,
            candidateWord,
            candidateRaw,
            ownerDecoded,
            sampleDecoded,
            owner,
            ownerFormat,
            owner.BytesPerTexel,
            0,
            0,
            0,
            0);
        return true;
    }

    private bool TryReadFullrectWriterLayoutPreferredSeedArtOwnerCandidate(
        int x,
        int y,
        int width,
        int height,
        string transform,
        out FullrectArtOwnerCandidate candidate)
    {
        candidate = default;
        if (!_experimentFullrectSampleWriterLayoutArtOwnerPreferredSeed)
            return false;

        if (transform == "preferredatlas")
            return TryReadFullrectWriterLayoutPreferredAtlasCandidate(x, y, width, height, out candidate);

        string sourceTransform = GetFullrectWriterLayoutPreferredSeedSourceTransform(transform);
        FullrectArtOwnerCandidate best = default;
        bool hasBest = false;
        int bestRank = int.MinValue;

        foreach (TextureWordLastWriter seedOwner in GetFullrectPreferredSeedOwners())
        {
            int ownerFormat = (int)((seedOwner.Mode >> 8) & 0x0fu);
            bool ownerFormatOverridden = _experimentFullrectSampleWriterLayoutFormatOverride is >= 0 and <= 15;
            if (ownerFormatOverridden)
                ownerFormat = _experimentFullrectSampleWriterLayoutFormatOverride;

            bool ownerSixteenBit = seedOwner.BytesPerTexel == 2 || IsTextureFormat16Bit(ownerFormat);
            int ownerBytesPerTexel = ownerSixteenBit ? 2 : seedOwner.BytesPerTexel;
            int ownerLod = Math.Clamp((int)seedOwner.Lod, 0, 8);
            int ownerWidth = Math.Max(1, (int)GetTextureWidth(seedOwner.TexLod) >> ownerLod);
            int ownerHeight = Math.Max(1, (int)GetTextureHeight(seedOwner.TexLod) >> ownerLod);
            uint ownerBase = GetTextureLodOffset(ownerLod, ownerBytesPerTexel, seedOwner.TexLod, seedOwner.TextureBase);
            if (_experimentFullrectSampleWriterLayoutBaseBias != 0)
                ownerBase = (uint)(((long)ownerBase + _experimentFullrectSampleWriterLayoutBaseBias) & (TextureBytes - 1L));

            int ownerX = Math.Clamp(width > 0 ? x * ownerWidth / width : x, 0, Math.Max(0, ownerWidth - 1));
            int ownerY = Math.Clamp(height > 0 ? y * ownerHeight / height : y, 0, Math.Max(0, ownerHeight - 1));
            ushort sampleDecoded = ReadFullrectWriterLayoutTextureRgb565At(
                ownerX,
                ownerY,
                ownerWidth,
                ownerHeight,
                ownerFormat,
                ownerSixteenBit,
                seedOwner.Mode,
                ownerBase,
                sourceTransform,
                out uint candidateByteAddress,
                out uint candidateWord,
                out uint candidateRaw);

            int candidateWordOffset = (int)((candidateByteAddress & (TextureBytes - 1u)) >> 2);
            if (!TryGetFullrectWriterLayoutArtOwner(candidateWordOffset, out TextureWordLastWriter owner) ||
                !IsPreferredFullrectWriterLayoutArtOwner(owner) ||
                IsRejectedFullrectWriterLayoutArtOwnerPayload(owner))
            {
                continue;
            }

            int candidateOwnerFormat = (int)((owner.Mode >> 8) & 0x0fu);
            if (ownerFormatOverridden)
                candidateOwnerFormat = _experimentFullrectSampleWriterLayoutFormatOverride;
            bool candidateOwnerSixteenBit = owner.BytesPerTexel == 2 || IsTextureFormat16Bit(candidateOwnerFormat);
            ushort ownerDecoded = DecodeTextureRawToRgb565(candidateRaw, candidateOwnerFormat, candidateOwnerSixteenBit, owner.Mode);
            if (ownerDecoded == 0 &&
                _experimentFullrectSampleWriterLayoutArtOwnerDecodeHighByteFallback &&
                candidateOwnerSixteenBit &&
                candidateOwnerFormat is 8 or 9)
            {
                ownerDecoded = DecodeTextureRawToRgb565(candidateRaw >> 8, candidateOwnerFormat & 1, sixteenBit: false, owner.Mode);
            }

            int rank = 0;
            if (candidateRaw != 0)
                rank += 1000;
            if (ownerDecoded != 0)
                rank += 1000;
            if (owner.Type5PayloadNonZeroWords > 0)
                rank += Math.Min(owner.Type5PayloadNonZeroWords, 255);
            if (_experimentFullrectSampleWriterLayoutArtOwnerPreferPcs.Contains(owner.Pc & 0xffffffffUL))
                rank += 100;
            if (_experimentFullrectSampleWriterLayoutArtOwnerPreferTargetStarts.Contains(owner.Type5TargetStart))
                rank += 50;

            if (!hasBest || rank > bestRank)
            {
                best = new FullrectArtOwnerCandidate(
                    transform,
                    candidateByteAddress,
                    candidateWord,
                    candidateRaw,
                    ownerDecoded,
                    sampleDecoded,
                    owner,
                    candidateOwnerFormat,
                    owner.BytesPerTexel,
                    0,
                    0,
                    0,
                    0);
                bestRank = rank;
                hasBest = true;
            }
        }

        candidate = best;
        return hasBest;
    }

    private bool TryReadFullrectWriterLayoutPreferredAtlasCandidate(
        int x,
        int y,
        int width,
        int height,
        out FullrectArtOwnerCandidate candidate)
    {
        candidate = default;
        int atlasWidth = Math.Clamp(_experimentFullrectSampleWriterLayoutArtOwnerPreferredAtlasWidth, 0, 4096);
        int atlasHeight = Math.Clamp(_experimentFullrectSampleWriterLayoutArtOwnerPreferredAtlasHeight, 0, 4096);
        if (atlasWidth == 0 || atlasHeight == 0)
            return false;

        int atlasX = Math.Clamp(width > 0 ? (int)((long)x * atlasWidth / width) : x, 0, atlasWidth - 1);
        int atlasY = Math.Clamp(height > 0 ? (int)((long)y * atlasHeight / height) : y, 0, atlasHeight - 1);
        uint byteAddress = (uint)(
            (_experimentFullrectSampleWriterLayoutArtOwnerPreferredAtlasBase +
             ((ulong)(atlasY * atlasWidth + atlasX) * 2UL)) &
            (TextureBytes - 1u));
        int wordOffset = (int)(byteAddress >> 2);
        TextureWordLastWriter owner;
        if (_experimentFullrectSampleWriterLayoutArtOwnerPreferredAtlasTrustRetainedRange)
        {
            IReadOnlyList<TextureWordLastWriter> seeds = GetFullrectPreferredSeedOwners();
            if (seeds.Count == 0)
                return false;
            owner = seeds[0];
        }
        else if (!TryGetFullrectWriterLayoutArtOwner(wordOffset, out owner) ||
                 !IsPreferredFullrectWriterLayoutArtOwner(owner) ||
                 IsRejectedFullrectWriterLayoutArtOwnerPayload(owner))
        {
            return false;
        }

        int ownerFormat = (int)((owner.Mode >> 8) & 0x0fu);
        if (_experimentFullrectSampleWriterLayoutFormatOverride is >= 0 and <= 15)
            ownerFormat = _experimentFullrectSampleWriterLayoutFormatOverride;
        bool ownerSixteenBit = owner.BytesPerTexel == 2 || IsTextureFormat16Bit(ownerFormat);
        ushort decoded = ReadTextureRgb565AtByteAddress(
            byteAddress,
            ownerFormat,
            ownerSixteenBit,
            owner.Mode,
            out uint word,
            out uint raw);

        candidate = new FullrectArtOwnerCandidate(
            "preferredatlas",
            byteAddress,
            word,
            raw,
            decoded,
            decoded,
            owner,
            ownerFormat,
            owner.BytesPerTexel,
            0,
            0,
            0,
            0);
        return true;
    }

    private IReadOnlyList<TextureWordLastWriter> GetFullrectPreferredSeedOwners()
    {
        if (_fullrectPreferredSeedOwnersVersion == _textureWordLastWriterVersion)
            return _fullrectPreferredSeedOwners;

        _fullrectPreferredSeedOwners.Clear();
        HashSet<FullrectPreferredSeedKey> seen = [];
        foreach (TextureWordLastWriter owner in _textureWordLastWriters.Values)
        {
            if (!IsPreferredFullrectWriterLayoutArtOwner(owner) ||
                !IsValidFullrectWriterLayoutArtOwner(owner) ||
                IsRejectedFullrectWriterLayoutArtOwnerPayload(owner))
            {
                continue;
            }

            var key = new FullrectPreferredSeedKey(
                owner.Pc,
                owner.Mode,
                owner.TexLod,
                owner.TextureBase,
                owner.Lod,
                owner.BytesPerTexel,
                owner.Type5TargetStart,
                owner.Type5PayloadHash,
                owner.Type5Count);
            if (seen.Add(key))
                _fullrectPreferredSeedOwners.Add(owner);
        }

        _fullrectPreferredSeedOwners.Sort((left, right) => GetFullrectPreferredSeedRank(right).CompareTo(GetFullrectPreferredSeedRank(left)));
        int seedLimit = Math.Clamp(_experimentFullrectSampleWriterLayoutArtOwnerPreferredSeedLimit, 1, 512);
        if (_fullrectPreferredSeedOwners.Count > seedLimit)
            _fullrectPreferredSeedOwners.RemoveRange(seedLimit, _fullrectPreferredSeedOwners.Count - seedLimit);

        _fullrectPreferredSeedOwnersVersion = _textureWordLastWriterVersion;
        return _fullrectPreferredSeedOwners;
    }

    private int GetFullrectPreferredSeedRank(TextureWordLastWriter owner)
    {
        int rank = Math.Min(owner.Type5PayloadNonZeroWords, 255);
        if (_experimentFullrectSampleWriterLayoutArtOwnerPreferPcs.Contains(owner.Pc & 0xffffffffUL))
            rank += 1000;
        if (_experimentFullrectSampleWriterLayoutArtOwnerPreferTargetStarts.Contains(owner.Type5TargetStart))
            rank += 500;
        if (owner.Type5TargetStart >= 0x8000)
            rank += 250;
        return rank;
    }

    private bool TryReadFullrectWriterLayoutTargetLocalArtOwnerCandidate(
        int x,
        int y,
        int width,
        int height,
        int format,
        bool sixteenBit,
        uint textureMode,
        uint baseAddress,
        string transform,
        out FullrectArtOwnerCandidate candidate)
    {
        if (!_experimentFullrectSampleWriterLayoutArtOwnerTargetLocal)
        {
            candidate = default;
            return false;
        }

        ushort probeDecoded = ReadFullrectWriterLayoutTextureRgb565At(
            x,
            y,
            width,
            height,
            format,
            sixteenBit,
            textureMode,
            baseAddress,
            "row4x",
            out uint probeByteAddress,
            out _,
            out _);
        int probeWordOffset = (int)((probeByteAddress & (TextureBytes - 1u)) >> 2);
        if (!TryGetFullrectWriterLayoutArtOwner(probeWordOffset, out TextureWordLastWriter seedOwner) ||
            IsRejectedFullrectWriterLayoutArtOwnerPayload(seedOwner) ||
            seedOwner.Type5Count <= 0)
        {
            candidate = default;
            return false;
        }

        int packetCount = Math.Clamp(seedOwner.Type5Count, 1, 256);
        int packetIndex = GetFullrectWriterLayoutTargetLocalIndex(x, y, width, height, transform, packetCount);
        uint targetWord = transform == "targetword"
            ? seedOwner.Type5TargetWord
            : (seedOwner.Type5TargetStart + (uint)packetIndex);
        uint lane = sixteenBit ? (probeByteAddress & 2u) : (probeByteAddress & 3u);
        uint candidateByteAddress = ((targetWord << 2) | lane) & (TextureBytes - 1u);
        ushort sampleDecoded = ReadTextureRgb565AtByteAddress(
            candidateByteAddress,
            format,
            sixteenBit,
            textureMode,
            out uint candidateWord,
            out uint candidateRaw);

        TextureWordLastWriter owner = seedOwner;
        int candidateWordOffset = (int)((candidateByteAddress & (TextureBytes - 1u)) >> 2);
        if (TryGetFullrectWriterLayoutArtOwner(candidateWordOffset, out TextureWordLastWriter targetOwner) &&
            !IsRejectedFullrectWriterLayoutArtOwnerPayload(targetOwner))
        {
            owner = targetOwner;
        }

        int ownerFormat = (int)((owner.Mode >> 8) & 0x0fu);
        bool ownerSixteenBit = owner.BytesPerTexel == 2 || IsTextureFormat16Bit(ownerFormat);
        ushort ownerDecoded = DecodeTextureRawToRgb565(candidateRaw, ownerFormat, ownerSixteenBit, owner.Mode);
        if (ownerDecoded == 0 &&
            _experimentFullrectSampleWriterLayoutArtOwnerDecodeHighByteFallback &&
            ownerSixteenBit &&
            ownerFormat is 8 or 9)
        {
            ownerDecoded = DecodeTextureRawToRgb565(candidateRaw >> 8, ownerFormat & 1, sixteenBit: false, owner.Mode);
        }

        candidate = new FullrectArtOwnerCandidate(
            transform,
            candidateByteAddress,
            candidateWord,
            candidateRaw,
            ownerDecoded,
            sampleDecoded == 0 ? probeDecoded : sampleDecoded,
            owner,
            ownerFormat,
            owner.BytesPerTexel,
            0,
            0,
            0,
            0);
        return true;
    }

    private bool TryReadFullrectWriterLayoutPacketLocalArtOwnerCandidate(
        int x,
        int y,
        int width,
        int height,
        int format,
        bool sixteenBit,
        uint textureMode,
        uint baseAddress,
        string transform,
        out FullrectArtOwnerCandidate candidate)
    {
        if (!_experimentFullrectSampleWriterLayoutArtOwnerPacketLocal)
        {
            candidate = default;
            return false;
        }

        ushort probeDecoded = ReadFullrectWriterLayoutTextureRgb565At(
            x,
            y,
            width,
            height,
            format,
            sixteenBit,
            textureMode,
            baseAddress,
            "row4x",
            out uint probeByteAddress,
            out _,
            out _);
        int probeWordOffset = (int)((probeByteAddress & (TextureBytes - 1u)) >> 2);
        if (!TryGetFullrectWriterLayoutArtOwner(probeWordOffset, out TextureWordLastWriter owner) ||
            IsRejectedFullrectWriterLayoutArtOwnerPayload(owner) ||
            owner.Type5Index < 0 ||
            owner.Type5Count <= 0)
        {
            candidate = default;
            return false;
        }

        int packetCount = Math.Clamp(owner.Type5Count, 1, 256);
        int packetBaseWord = (probeWordOffset - owner.Type5Index) & (TextureWords - 1);
        int packetIndex = GetFullrectWriterLayoutPacketLocalIndex(x, y, transform, packetCount);
        int candidateWordOffset = (packetBaseWord + packetIndex) & (TextureWords - 1);
        uint candidateByteAddress = (uint)(((candidateWordOffset << 2) | (int)(probeByteAddress & 2u)) & (TextureBytes - 1));
        ushort sampleDecoded = ReadTextureRgb565AtByteAddress(
            candidateByteAddress,
            format,
            sixteenBit,
            textureMode,
            out uint candidateWord,
            out uint candidateRaw);

        int ownerFormat = (int)((owner.Mode >> 8) & 0x0fu);
        bool ownerSixteenBit = owner.BytesPerTexel == 2 || IsTextureFormat16Bit(ownerFormat);
        ushort ownerDecoded = DecodeTextureRawToRgb565(candidateRaw, ownerFormat, ownerSixteenBit, owner.Mode);
        if (ownerDecoded == 0 &&
            _experimentFullrectSampleWriterLayoutArtOwnerDecodeHighByteFallback &&
            ownerSixteenBit &&
            ownerFormat is 8 or 9)
        {
            ownerDecoded = DecodeTextureRawToRgb565(candidateRaw >> 8, ownerFormat & 1, sixteenBit: false, owner.Mode);
        }

        candidate = new FullrectArtOwnerCandidate(
            transform,
            candidateByteAddress,
            candidateWord,
            candidateRaw,
            ownerDecoded,
            sampleDecoded == 0 ? probeDecoded : sampleDecoded,
            owner,
            ownerFormat,
            owner.BytesPerTexel,
            0,
            0,
            0,
            0);
        return true;
    }

    private static int GetFullrectWriterLayoutPacketLocalIndex(int x, int y, string transform, int packetCount)
    {
        int packetMask = Math.Max(0, packetCount - 1);
        int localX = x & 7;
        int localY = y & 7;
        int index = transform switch
        {
            "packet8x8" => (localY * 8) + localX,
            "packet8x8t" => (localX * 8) + localY,
            "packet64x" => x & 63,
            "packet64y" => y & 63,
            _ => 0
        };

        return index & packetMask;
    }

    private static int GetFullrectWriterLayoutTargetLocalIndex(int x, int y, int width, int height, string transform, int packetCount)
    {
        uint texelIndex = transform switch
        {
            "targetword" => 0u,
            "targetlinear" => GetFullrectWriterLayoutTexelIndex(x, y, width, height, "linear"),
            "targetrow2x" => GetFullrectWriterLayoutTexelIndex(x, y, width, height, "row2x"),
            "targetrow4x" => GetFullrectWriterLayoutTexelIndex(x, y, width, height, "row4x"),
            "targettile4" => GetFullrectWriterLayoutTexelIndex(x, y, width, height, "tile4"),
            "targettile8" => GetFullrectWriterLayoutTexelIndex(x, y, width, height, "tile8"),
            _ => 0u
        };

        return (int)(texelIndex % (uint)Math.Max(1, packetCount));
    }

    private int ScoreFullrectWriterLayoutArtOwnerCandidate(
        int x,
        int y,
        int width,
        int height,
        int format,
        bool sixteenBit,
        uint textureMode,
        uint baseAddress,
        string transform,
        uint ownerTargetStart,
        out int nonZeroRgb,
        out int sameOwner,
        out int colorChanges)
    {
        nonZeroRgb = 0;
        sameOwner = 0;
        colorChanges = 0;
        ushort previous = 0;
        bool hasPrevious = false;
        int radius = Math.Clamp(_experimentFullrectSampleWriterLayoutArtOwnerScoreRadius, 1, 4);

        for (int dy = -radius; dy <= radius; dy++)
        {
            int sampleY = Math.Clamp(y + dy, 0, Math.Max(0, height - 1));
            for (int dx = -radius; dx <= radius; dx++)
            {
                int sampleX = Math.Clamp(x + dx, 0, Math.Max(0, width - 1));
                if (!TryReadFullrectWriterLayoutArtOwnerCandidate(
                        sampleX,
                        sampleY,
                        width,
                        height,
                        format,
                        sixteenBit,
                        textureMode,
                        baseAddress,
                        transform,
                        out FullrectArtOwnerCandidate neighbor))
                {
                    continue;
                }

                if (neighbor.Result != 0)
                    nonZeroRgb++;
                if (neighbor.Owner.Type5TargetStart == ownerTargetStart)
                    sameOwner++;
                if (hasPrevious && neighbor.Result != previous)
                    colorChanges++;
                previous = neighbor.Result;
                hasPrevious = true;
            }
        }

        return (nonZeroRgb * 100) + (sameOwner * 10) - (colorChanges * 8);
    }

    private IEnumerable<string> EnumerateFullrectWriterLayoutArtOwnerCandidateTransforms()
    {
        if (_experimentFullrectSampleWriterLayoutArtOwnerTransform.Length > 0)
        {
            yield return _experimentFullrectSampleWriterLayoutArtOwnerTransform;
            yield break;
        }

        foreach (string transform in FullrectWriterLayoutCandidateTransforms)
            yield return transform;

        if (_experimentFullrectSampleWriterLayoutArtOwnerPacketLocal)
        {
            foreach (string transform in FullrectWriterLayoutPacketLocalCandidateTransforms)
                yield return transform;
        }

        if (_experimentFullrectSampleWriterLayoutArtOwnerTargetLocal)
        {
            foreach (string transform in FullrectWriterLayoutTargetLocalCandidateTransforms)
                yield return transform;
        }

        if (_experimentFullrectSampleWriterLayoutArtOwnerPreferredSeed)
        {
            foreach (string transform in FullrectWriterLayoutPreferredSeedCandidateTransforms)
                yield return transform;
        }
    }

    private static bool IsFullrectWriterLayoutPacketLocalTransform(string transform) =>
        transform is "packet8x8" or "packet8x8t" or "packet64x" or "packet64y";

    private static bool IsFullrectWriterLayoutTargetLocalTransform(string transform) =>
        transform is "targetword" or "targetlinear" or "targetrow2x" or "targetrow4x" or "targettile4" or "targettile8";

    private static bool IsFullrectWriterLayoutPreferredSeedTransform(string transform) =>
        transform is "preferredlinear" or "preferredrow2x" or "preferredrow4x" or "preferredtile4" or "preferredtile8" or "preferredatlas";

    private static string GetFullrectWriterLayoutPreferredSeedSourceTransform(string transform) =>
        transform switch
        {
            "preferredrow2x" => "row2x",
            "preferredrow4x" => "row4x",
            "preferredtile4" => "tile4",
            "preferredtile8" => "tile8",
            _ => "linear"
        };

    private bool IsRejectedFullrectWriterLayoutArtOwnerPayload(TextureWordLastWriter owner) =>
        (_experimentFullrectSampleWriterLayoutArtOwnerAllowPcs.Length != 0 &&
         !_experimentFullrectSampleWriterLayoutArtOwnerAllowPcs.Contains(owner.Pc & 0xffffffffUL)) ||
        (_experimentFullrectSampleWriterLayoutArtOwnerAllowTargetStarts.Length != 0 &&
         !_experimentFullrectSampleWriterLayoutArtOwnerAllowTargetStarts.Contains(owner.Type5TargetStart)) ||
        (_experimentFullrectSampleWriterLayoutArtOwnerRejectPayloadHashes.Length != 0 &&
         _experimentFullrectSampleWriterLayoutArtOwnerRejectPayloadHashes.Contains(owner.Type5PayloadHash)) ||
        (_experimentFullrectSampleWriterLayoutArtOwnerRejectTargetStarts.Length != 0 &&
         _experimentFullrectSampleWriterLayoutArtOwnerRejectTargetStarts.Contains(owner.Type5TargetStart)) ||
        (_experimentFullrectSampleWriterLayoutArtOwnerRejectFloatLikePayloads &&
         IsFloatLikeFullrectWriterLayoutArtOwnerPayload(owner));

    private static bool IsFloatLikeFullrectWriterLayoutArtOwnerPayload(TextureWordLastWriter owner)
    {
        if (owner.Type5Count < 16 || owner.Type5PayloadNonZeroWords < 8)
            return false;

        int threshold = Math.Max(8, owner.Type5Count / 3);
        return owner.Type5PayloadFloatLikeWords >= threshold;
    }

    private static bool IsValidFullrectWriterLayoutArtOwner(TextureWordLastWriter owner) =>
        owner.Type5 &&
        owner.Type5Space == 3 &&
        owner.Type5Command == 0xc0000205u &&
        owner.BytesPerTexel is 1 or 2;

    private bool IsPreferredFullrectWriterLayoutArtOwner(uint ownerTargetStart)
        => _experimentFullrectSampleWriterLayoutArtOwnerPreferTargetStarts.Length != 0 &&
           _experimentFullrectSampleWriterLayoutArtOwnerPreferTargetStarts.Contains(ownerTargetStart);

    private bool IsPreferredFullrectWriterLayoutArtOwner(TextureWordLastWriter owner)
        => (_experimentFullrectSampleWriterLayoutArtOwnerPreferPcs.Length != 0 &&
            _experimentFullrectSampleWriterLayoutArtOwnerPreferPcs.Contains(owner.Pc & 0xffffffffUL)) ||
           IsPreferredFullrectWriterLayoutArtOwner(owner.Type5TargetStart);

    private string FormatFullrectArtOwnerCandidateStatus(FullrectArtOwnerCandidate candidate) =>
        $"transform={candidate.Transform} ownerFmt{candidate.OwnerFormat}/ownerBpp{candidate.OwnerBytesPerTexel} " +
        $"sampleRgb=0x{candidate.SampleResult:X4} score={candidate.Score}/nz{candidate.NonZeroRgb}/same{candidate.SameOwner}/chg{candidate.ColorChanges} " +
        $"preferred={(IsPreferredFullrectWriterLayoutArtOwner(candidate.Owner) ? 1 : 0)} " +
        $"owner={FormatTextureWordWriterStatus(candidate.Owner)}{FormatFullrectArtOwnerUploadWindow(candidate)}";

    private string FormatFullrectArtOwnerUploadWindow(FullrectArtOwnerCandidate candidate)
    {
        if (!_traceFullrectSampleWriterLayoutArtOwnerUploadWindow)
            return "";

        TextureWordLastWriter center = candidate.Owner;
        int radius = Math.Clamp(_traceFullrectSampleWriterLayoutArtOwnerUploadWindowRadius, 1, 64);
        int centerWordOffset = (int)((candidate.ByteAddress & (TextureBytes - 1u)) >> 2);
        int nonZero = 0;
        int sameCommand = 0;
        int sameTargetStart = 0;
        int samePacket = 0;
        int minIndex = int.MaxValue;
        int maxIndex = int.MinValue;
        List<string> words = [];

        for (int delta = -radius; delta <= radius; delta++)
        {
            int wordOffset = (centerWordOffset + delta) & (TextureWords - 1);
            uint value = _textureMemory[wordOffset];
            if (value != 0)
                nonZero++;

            string ownerStatus = "-";
            if (_textureWordLastWriters.TryGetValue(wordOffset, out TextureWordLastWriter owner))
            {
                if (owner.Type5Command == center.Type5Command)
                    sameCommand++;
                if (owner.Type5TargetStart == center.Type5TargetStart)
                    sameTargetStart++;
                if (owner.PacketStart == center.PacketStart)
                    samePacket++;
                minIndex = Math.Min(minIndex, owner.Type5Index);
                maxIndex = Math.Max(maxIndex, owner.Type5Index);
                ownerStatus = $"{owner.Type5Index}/{owner.Type5Count}:0x{owner.Type5TargetWord:X5}:fmt{(int)((owner.Mode >> 8) & 0x0fu)}";
            }

            if (words.Count < 9 && (delta == 0 || value != 0))
                words.Add($"{delta:+#;-#;0}=0x{value:X8}/{ownerStatus}");
        }

        string indexSpan = minIndex == int.MaxValue ? "-" : $"{minIndex}-{maxIndex}";
        return $" uploadWindow=w0x{centerWordOffset:X5}/target0x{center.Type5TargetWord:X5}/r{radius}/nz{nonZero}/sameCmd{sameCommand}/sameStart{sameTargetStart}/samePkt{samePacket}/idx{indexSpan}/words[{string.Join(";", words)}]";
    }

    private void TraceFullrectArtOwnerSelectedCandidate(
        int x,
        int y,
        int width,
        int height,
        FullrectArtOwnerCandidate candidate)
    {
        if (!_traceFullrectSampleWriterLayoutArtOwnerSelected ||
            _fullrectSampleWriterLayoutArtOwnerSelectedTraceCount >= _traceFullrectSampleWriterLayoutArtOwnerSelectedLimit)
        {
            return;
        }

        _fullrectSampleWriterLayoutArtOwnerSelectedTraceCount++;

        TextureWordLastWriter owner = candidate.Owner;
        int wordOffset = (int)((candidate.ByteAddress & (TextureBytes - 1u)) >> 2);
        int lane = (int)(candidate.ByteAddress & 3u);
        int packetStart = owner.PacketStart;
        int targetIndex = packetStart + 1;
        int payloadIndex = packetStart + 2 + owner.Type5Index;
        int packetBaseWord = owner.Type5Index >= 0
            ? (wordOffset - owner.Type5Index) & (TextureWords - 1)
            : -1;

        string fifoStorage = owner.Type5
            ? $" fifo=hdr[{FormatCommandFifoStorageWordDebug(packetStart)}] target[{FormatCommandFifoStorageWordDebug(targetIndex)}] payload[{FormatCommandFifoStorageWordDebug(payloadIndex)}]"
            : "";
        string textureWindow = FormatTextureWordWindow(wordOffset, 2);
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-FULLRECT-ART-SELECTED] n={_fullrectSampleWriterLayoutArtOwnerSelectedTraceCount} frame={_renderFrame} " +
            $"xy={x},{y}/{width}x{height} transform={candidate.Transform} addr=0x{candidate.ByteAddress:X6}/w0x{wordOffset:X5}/lane{lane} " +
            $"word=0x{candidate.Word:X8} raw=0x{candidate.Raw:X4} rgb=0x{candidate.Result:X4} sampleRgb=0x{candidate.SampleResult:X4} " +
            $"fmt{candidate.OwnerFormat}/bpp{candidate.OwnerBytesPerTexel} score={candidate.Score}/nz{candidate.NonZeroRgb}/same{candidate.SameOwner}/chg{candidate.ColorChanges} " +
            $"type5=cmd0x{owner.Type5Command:X8}/space{owner.Type5Space}/targetStart=0x{owner.Type5TargetStart:X6}/target=0x{owner.Type5TargetWord:X6} " +
            $"idx={owner.Type5Index}/{owner.Type5Count}/packetBaseW0x{packetBaseWord:X5}/payloadHash=0x{owner.Type5PayloadHash:X8}/pnz{owner.Type5PayloadNonZeroWords}/pflt{owner.Type5PayloadFloatLikeWords} " +
            $"pc=0x{owner.Pc:x16}/packet=0x{packetStart * 4:X8}/rd=0x{owner.ReadIndex * 4:X8}/stream={(owner.Streaming ? 1 : 0)}{fifoStorage} texWords={textureWindow}");
    }

    private string FormatTextureWordWindow(int centerWordOffset, int radius)
    {
        if (centerWordOffset < 0)
            return "-";

        radius = Math.Clamp(radius, 0, 8);
        List<string> words = [];
        for (int delta = -radius; delta <= radius; delta++)
        {
            int wordOffset = (centerWordOffset + delta) & (TextureWords - 1);
            uint value = _textureMemory[wordOffset];
            string ownerStatus = "-";
            if (_textureWordLastWriters.TryGetValue(wordOffset, out TextureWordLastWriter owner))
                ownerStatus = $"{owner.Type5Index}/{owner.Type5Count}:0x{owner.Type5TargetWord:X5}:ph0x{owner.Type5PayloadHash:X8}";
            words.Add($"{delta:+#;-#;0}=0x{value:X8}/{ownerStatus}");
        }

        return $"[{string.Join(";", words)}]";
    }

    private ushort DecodeTextureRawToRgb565(uint raw, int format, bool sixteenBit, uint textureMode)
    {
        if (sixteenBit)
            return ConvertTextureFormatToRgb565(format, (ushort)raw, textureMode);

        byte value = (byte)raw;
        return format switch
        {
            0 => ConvertRgb332ToRgb565(value),
            1 => ConvertNccToRgb565(value, textureMode),
            2 => GrayscaleToRgb565(value),
            3 => GrayscaleToRgb565(value),
            4 => GrayscaleToRgb565((byte)((value & 0x0f) * 17)),
            5 or 6 or 7 => ConvertPaletteTextureToRgb565(value, format),
            _ => PseudoPaletteToRgb565(value)
        };
    }

    private bool TryGetFullrectWriterLayoutArtOwner(int wordOffset, out TextureWordLastWriter owner)
    {
        if (!_textureWordLastWriters.TryGetValue(wordOffset, out owner))
            return false;

        return IsValidFullrectWriterLayoutArtOwner(owner);
    }

    private static string FormatTextureWordWriterStatus(TextureWordLastWriter writer) =>
        $"pc0x{writer.Pc & 0xffffffffUL:x8}/mode0x{writer.Mode:X8}/lod0x{writer.TexLod:X8}/base0x{writer.TextureBase:X8}/l{writer.Lod}/bpp{writer.BytesPerTexel}/type5={(writer.Type5 ? 1 : 0)}/cmd0x{writer.Type5Command:X8}@0x{writer.Type5TargetStart:X6}:0x{writer.Type5TargetWord:X6}/ph0x{writer.Type5PayloadHash:X8}/pnz{writer.Type5PayloadNonZeroWords}/pflt{writer.Type5PayloadFloatLikeWords}";

    private void TraceFullrectWriterLayoutCandidates(
        float s,
        float t,
        int currentWidth,
        int currentHeight,
        bool clampS,
        bool clampT,
        uint currentByteAddress,
        int currentWordOffset,
        uint sampleMode,
        uint sampleTextureLod,
        uint sampleTextureBase,
        TextureWordLastWriter writer,
        int writerX,
        int writerY,
        int writerWidth,
        int writerHeight,
        int writerFormat,
        bool writerFormatOverridden,
        int writerBytesPerTexel,
        bool writerSixteenBit,
        int writerLod,
        uint writerBase,
        uint writerTargetStart,
        bool writerTargetRemapped,
        bool hasSampledOwner,
        TextureWordLastWriter sampledWriter,
        uint activeByteAddress,
        ushort activeResult)
    {
        if (!_traceFullrectWriterLayoutCandidates ||
            _fullrectSampleWriterLayoutCandidateTraceCount >= _traceFullrectWriterLayoutCandidatesLimit)
        {
            return;
        }

        _fullrectSampleWriterLayoutCandidateTraceCount++;

        var writerSource = new FullrectWriterLayoutTraceSource(
            writer,
            s,
            t,
            writerX,
            writerY,
            writerWidth,
            writerHeight,
            writerFormat,
            writerFormatOverridden,
            writerBytesPerTexel,
            writerSixteenBit,
            writerLod,
            writerBase,
            writerTargetStart,
            writerTargetRemapped);

        string writerCandidates = FormatFullrectWriterLayoutCandidateSet(
            "writer",
            writerSource,
            sampleMode,
            writer,
            hasSampledOwner,
            sampledWriter);

        string sampledCandidates = "-";
        if (hasSampledOwner &&
            TryResolveFullrectWriterLayoutTraceSource(
                sampledWriter,
                s,
                t,
                currentWidth,
                currentHeight,
                clampS,
                clampT,
                allowTargetRemap: false,
                out FullrectWriterLayoutTraceSource sampledSource))
        {
            sampledCandidates = FormatFullrectWriterLayoutCandidateSet(
                "sampled",
                sampledSource,
                sampleMode,
                writer,
                hasSampledOwner,
                sampledWriter);
        }

        int activeWordOffset = (int)((activeByteAddress & (TextureBytes - 1u)) >> 2);
        string activeTransform = _experimentFullrectSampleWriterLayoutAddressTransform.Length == 0
            ? "linear"
            : _experimentFullrectSampleWriterLayoutAddressTransform;
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-FULLRECT-CANDIDATES] n={_fullrectSampleWriterLayoutCandidateTraceCount} frame={_renderFrame} " +
            $"current=0x{currentByteAddress:X6}/w{currentWordOffset:X5} active={activeTransform}:0x{activeByteAddress:X6}/w{activeWordOffset:X5}/rgb0x{activeResult:X4} " +
            $"sample=mode0x{sampleMode:X8}/lod0x{sampleTextureLod:X8}/base0x{sampleTextureBase:X8} " +
            $"writer=pc0x{writer.Pc & 0xffffffffUL:x8}/fmt{writerFormat}{(writerFormatOverridden ? "*" : "")}/l{writerLod}/bpp{writerBytesPerTexel}/base0x{writerBase:X6}/target0x{writerTargetStart:X6}/remap{(writerTargetRemapped ? 1 : 0)} " +
            $"st=({s:F3},{t:F3}) writerXY={writerX},{writerY}/{writerWidth}x{writerHeight} " +
            $"candidates={writerCandidates} sampled={sampledCandidates}");
    }

    private bool TryResolveFullrectWriterLayoutTraceSource(
        TextureWordLastWriter sourceWriter,
        float s,
        float t,
        int currentWidth,
        int currentHeight,
        bool clampS,
        bool clampT,
        bool allowTargetRemap,
        out FullrectWriterLayoutTraceSource source)
    {
        source = default;
        if (!sourceWriter.Type5 || sourceWriter.BytesPerTexel is not (1 or 2))
            return false;

        int lod = Math.Clamp((int)sourceWriter.Lod, 0, 8);
        int format = (int)((sourceWriter.Mode >> 8) & 0x0fu);
        bool formatOverridden = _experimentFullrectSampleWriterLayoutFormatOverride is >= 0 and <= 15;
        if (formatOverridden)
            format = _experimentFullrectSampleWriterLayoutFormatOverride;

        int bytesPerTexel = IsTextureFormat16Bit(format) ? 2 : sourceWriter.BytesPerTexel;
        bool sixteenBit = bytesPerTexel == 2;
        int width = Math.Max(1, (int)GetTextureWidth(sourceWriter.TexLod) >> lod);
        int height = Math.Max(1, (int)GetTextureHeight(sourceWriter.TexLod) >> lod);
        uint sourceBase = GetTextureLodOffset(lod, bytesPerTexel, sourceWriter.TexLod, sourceWriter.TextureBase);
        uint targetStart = sourceWriter.Type5TargetStart;
        bool targetRemapped = false;
        if (allowTargetRemap &&
            _experimentFullrectSampleWriterLayoutTargetRemap.TryGetValue(sourceWriter.Type5TargetStart, out uint remappedTargetStart))
        {
            long targetDeltaBytes = ((long)remappedTargetStart - sourceWriter.Type5TargetStart) << 2;
            sourceBase = (uint)(((long)sourceBase + targetDeltaBytes) & (TextureBytes - 1L));
            targetStart = remappedTargetStart;
            targetRemapped = true;
        }
        if (_experimentFullrectSampleWriterLayoutBaseBias != 0)
            sourceBase = (uint)(((long)sourceBase + _experimentFullrectSampleWriterLayoutBaseBias) & (TextureBytes - 1L));

        float sourceS = s;
        float sourceT = t;
        bool sourceClampS = clampS;
        bool sourceClampT = clampT;
        if (_experimentFullrectSampleWriterLayoutCoordMode is "wrap" or "wrapped")
        {
            sourceClampS = false;
            sourceClampT = false;
        }
        else if (_experimentFullrectSampleWriterLayoutCoordMode is "scale" or "scaled")
        {
            sourceS = currentWidth > 0 ? s * width / currentWidth : s;
            sourceT = currentHeight > 0 ? t * height / currentHeight : t;
        }
        else if (_experimentFullrectSampleWriterLayoutCoordMode is "scale-wrap" or "scaled-wrap")
        {
            sourceS = currentWidth > 0 ? s * width / currentWidth : s;
            sourceT = currentHeight > 0 ? t * height / currentHeight : t;
            sourceClampS = false;
            sourceClampT = false;
        }

        int x = TextureCoordinateToIndex(sourceS, width, sourceClampS);
        int y = _fixTextureTOriginFlip
            ? TextureCoordinateToIndex((height - 1) - sourceT, height, sourceClampT)
            : TextureCoordinateToIndex(sourceT, height, sourceClampT);

        source = new FullrectWriterLayoutTraceSource(
            sourceWriter,
            sourceS,
            sourceT,
            x,
            y,
            width,
            height,
            format,
            formatOverridden,
            bytesPerTexel,
            sixteenBit,
            lod,
            sourceBase,
            targetStart,
            targetRemapped);
        return true;
    }

    private string FormatFullrectWriterLayoutCandidateSet(
        string label,
        FullrectWriterLayoutTraceSource source,
        uint sampleMode,
        TextureWordLastWriter writer,
        bool hasSampledOwner,
        TextureWordLastWriter sampledWriter)
    {
        return $"{label}[xy={source.X},{source.Y}/{source.Width}x{source.Height}/fmt{source.Format}{(source.FormatOverridden ? "*" : "")}/l{source.Lod}/bpp{source.BytesPerTexel}/base0x{source.Base:X6}/target0x{source.TargetStart:X6}/remap{(source.TargetRemapped ? 1 : 0)} " +
            string.Join(";", FullrectWriterLayoutCandidateTransforms.Select(transform =>
                FormatFullrectWriterLayoutCandidate(transform, source, sampleMode, writer, hasSampledOwner, sampledWriter))) +
            "]";
    }

    private string FormatFullrectWriterLayoutCandidate(
        string transform,
        FullrectWriterLayoutTraceSource source,
        uint sampleMode,
        TextureWordLastWriter writer,
        bool hasSampledOwner,
        TextureWordLastWriter sampledWriter)
    {
        ushort texel = ReadFullrectWriterLayoutTextureRgb565At(
            source.X,
            source.Y,
            source.Width,
            source.Height,
            source.Format,
            source.SixteenBit,
            sampleMode,
            source.Base,
            transform,
            out uint byteAddress,
            out uint word,
            out uint raw);
        int wordOffset = (int)((byteAddress & (TextureBytes - 1u)) >> 2);
        string owner = FormatFullrectWriterLayoutCandidateOwner(wordOffset, writer, hasSampledOwner, sampledWriter);
        return $"{transform}:0x{byteAddress:X6}/w{wordOffset:X5}/word0x{word:X8}/raw0x{raw:X4}/rgb0x{texel:X4}/{owner}";
    }

    private string FormatFullrectWriterLayoutCandidateOwner(
        int wordOffset,
        TextureWordLastWriter writer,
        bool hasSampledOwner,
        TextureWordLastWriter sampledWriter)
    {
        if (!_textureWordLastWriters.TryGetValue(wordOffset, out TextureWordLastWriter owner))
            return "owner=-";

        string relation = "other";
        if (hasSampledOwner && owner.Type5 && sampledWriter.Type5 && owner.Type5TargetStart == sampledWriter.Type5TargetStart)
            relation = "sampled-target";
        else if (owner.Type5 && writer.Type5 && owner.Type5TargetStart == writer.Type5TargetStart)
            relation = "writer-target";
        else if (hasSampledOwner && owner.Pc == sampledWriter.Pc && owner.Type5Command == sampledWriter.Type5Command)
            relation = "sampled-pc";
        else if (owner.Pc == writer.Pc && owner.Type5Command == writer.Type5Command)
            relation = "writer-pc";

        return $"owner={relation}:{FormatTextureWordWriterCompactStatus(owner)}";
    }

    private static string FormatTextureWordWriterCompactStatus(TextureWordLastWriter writer)
    {
        int format = (int)((writer.Mode >> 8) & 0x0fu);
        return $"pc0x{writer.Pc & 0xffffffffUL:x8}/fmt{format}/l{writer.Lod}/bpp{writer.BytesPerTexel}/t5{(writer.Type5 ? 1 : 0)}@0x{writer.Type5TargetStart:X6}:0x{writer.Type5TargetWord:X6}";
    }

    private ushort ReadFullrectWriterLayoutTextureRgb565At(
        int x,
        int y,
        int width,
        int height,
        int format,
        bool sixteenBit,
        uint textureMode,
        uint baseAddress,
        out uint byteAddress,
        out uint word,
        out uint raw)
    {
        uint texelIndex = GetFullrectWriterLayoutTexelIndex(x, y, width, height);
        return ReadTextureRgb565AtIndex(texelIndex, format, sixteenBit, textureMode, baseAddress, out byteAddress, out word, out raw);
    }

    private ushort ReadFullrectWriterLayoutTextureRgb565At(
        int x,
        int y,
        int width,
        int height,
        int format,
        bool sixteenBit,
        uint textureMode,
        uint baseAddress,
        string addressTransform,
        out uint byteAddress,
        out uint word,
        out uint raw)
    {
        uint texelIndex = GetFullrectWriterLayoutTexelIndex(x, y, width, height, addressTransform);
        return ReadTextureRgb565AtIndex(texelIndex, format, sixteenBit, textureMode, baseAddress, out byteAddress, out word, out raw);
    }

    private uint GetFullrectWriterLayoutTexelIndex(int x, int y, int width, int height)
        => GetFullrectWriterLayoutTexelIndex(x, y, width, height, _experimentFullrectSampleWriterLayoutAddressTransform);

    private static uint GetFullrectWriterLayoutTexelIndex(int x, int y, int width, int height, string addressTransform)
    {
        ulong safeWidth = (uint)Math.Max(1, width);
        ulong safeX = (uint)Math.Clamp(x, 0, Math.Max(0, width - 1));
        ulong safeY = (uint)Math.Clamp(y, 0, Math.Max(0, height - 1));

        return addressTransform switch
        {
            "" or "linear" => (uint)(safeY * safeWidth + safeX),
            "row2x" or "row-stride-2x" => (uint)(safeY * safeWidth * 2ul + safeX),
            "row4x" or "row-stride-4x" => (uint)(safeY * safeWidth * 4ul + safeX),
            "tile4" or "tile-4x4" => GetTiledTextureIndex(safeX, safeY, safeWidth, 4),
            "tile8" or "tile-8x8" => GetTiledTextureIndex(safeX, safeY, safeWidth, 8),
            _ => (uint)(safeY * safeWidth + safeX)
        };
    }

    private static uint GetTiledTextureIndex(ulong x, ulong y, ulong width, ulong tileSize)
    {
        ulong tilesPerRow = Math.Max(1ul, (width + tileSize - 1ul) / tileSize);
        ulong tileX = x / tileSize;
        ulong tileY = y / tileSize;
        ulong inTileX = x % tileSize;
        ulong inTileY = y % tileSize;
        return (uint)(((tileY * tilesPerRow + tileX) * tileSize * tileSize) + (inTileY * tileSize) + inTileX);
    }

    private ushort ReadTextureRgb565AtByteAddress(
        uint byteAddress,
        int format,
        bool sixteenBit,
        uint textureMode,
        out uint word,
        out uint raw)
    {
        byteAddress = MapTextureSampleBankByteAddress(byteAddress);
        if (_experimentTextureSample64KPageWrap)
            byteAddress = MapTextureSampleBankByteAddress(byteAddress & 0xffffu);
        if (sixteenBit)
        {
            word = ReadTexture32(byteAddress & ~3u);
            uint laneByteAddress = GetTexture16BitLaneByteAddress(byteAddress);
            ushort packed = (ushort)((word >> (int)((laneByteAddress & 2u) * 8u)) & 0xffffu);
            packed = MaybeSwapTexture16BitBytes(packed);
            raw = packed;
            return ConvertTextureFormatToRgb565(format, packed, textureMode);
        }

        word = ReadTexture32(byteAddress & ~3u);
        uint lane = byteAddress & 3u;
        if (_experimentReverse8BitTextureSampleLanes)
            lane = 3u - lane;
        byte value = (byte)(word >> (int)(lane * 8u));
        raw = value;
        return format switch
        {
            0 => ConvertRgb332ToRgb565(value),
            1 => ConvertNccToRgb565(value, textureMode),
            2 => GrayscaleToRgb565(value),
            3 => GrayscaleToRgb565(value),
            4 => GrayscaleToRgb565((byte)((value & 0x0f) * 17)),
            5 or 6 or 7 => ConvertPaletteTextureToRgb565(value, format),
            _ => PseudoPaletteToRgb565(value)
        };
    }

    private ushort SampleTextureRgb565Bilinear(
        float s,
        float t,
        int width,
        int height,
        uint mode,
        int format,
        bool sixteenBit,
        uint baseAddress)
    {
        float u = s - 0.5f;
        float v = t - 0.5f;
        bool clampS = !_experimentTextureCoordinateWrap &&
            (!_experimentTextureMameFetchAddressing || (mode & 0x40u) != 0);
        bool clampT = !_experimentTextureCoordinateWrap &&
            (!_experimentTextureMameFetchAddressing || (mode & 0x80u) != 0);
        int x0 = TextureCoordinateToIndex(u, width, clampS);
        int y0 = _fixTextureTOriginFlip
            ? TextureCoordinateToIndex((height - 1) - v, height, clampT)
            : TextureCoordinateToIndex(v, height, clampT);
        int x1 = TextureCoordinateToIndex(u + 1.0f, width, clampS);
        int y1 = _fixTextureTOriginFlip
            ? TextureCoordinateToIndex((height - 1) - (v + 1.0f), height, clampT)
            : TextureCoordinateToIndex(v + 1.0f, height, clampT);
        float fx = Math.Clamp(u - MathF.Floor(u), 0.0f, 1.0f);
        float fy = Math.Clamp(v - MathF.Floor(v), 0.0f, 1.0f);

        ushort c00 = ReadTextureRgb565At(x0, y0, width, format, sixteenBit, mode, baseAddress, out uint byteAddress00, out uint word00, out uint raw00);
        ushort c10 = ReadTextureRgb565At(x1, y0, width, format, sixteenBit, mode, baseAddress, out _, out _, out _);
        ushort c01 = ReadTextureRgb565At(x0, y1, width, format, sixteenBit, mode, baseAddress, out _, out _, out _);
        ushort c11 = ReadTextureRgb565At(x1, y1, width, format, sixteenBit, mode, baseAddress, out _, out _, out _);
        ushort result = BilinearRgb565(c00, c10, c01, c11, fx, fy);
        TrackZeroTextureSample(byteAddress00, result);
        TrackTextureSampleDebug(byteAddress00, raw00, result);
        TraceTextureSample(s, t, width, height, x0, y0, mode, ReadTextureSampleRegister(RegTextureLod), ReadTextureSampleRegister(RegTextureBaseAddr), baseAddress, byteAddress00, word00, raw00, result);
        return result;
    }

    private void TrackZeroTextureSample(uint byteAddress, ushort result)
    {
        if (!_debugTextureZeroSampleBuckets || result != 0)
            return;

        uint address = byteAddress & (TextureBytes - 1u);
        _textureZeroSampleBucketTotal++;
        _textureZeroSampleBuckets[address >> TextureZeroSampleBucketShift]++;
        if (address < _textureZeroSampleFirstAddress)
            _textureZeroSampleFirstAddress = address;
        if (address > _textureZeroSampleLastAddress)
            _textureZeroSampleLastAddress = address;
    }

    private void TrackTextureSampleDebug(uint byteAddress, uint raw, ushort result)
    {
        _lastTextureSampleValid = true;
        _lastTextureSampleByteAddress = byteAddress & (TextureBytes - 1u);
        _lastTextureSampleRaw = raw;
        _lastTextureSampleResult = result;

        if (!_debugTextureSamples)
            return;

        uint address = _lastTextureSampleByteAddress;
        _textureSampleDebugTotal++;
        _textureSampleRawBuckets[raw & 0xffffu]++;
        _textureSampleColorBuckets[result]++;
        _textureSampleAddressBuckets[address >> TextureZeroSampleBucketShift]++;
        if (address < _textureSampleFirstAddress)
            _textureSampleFirstAddress = address;
        if (address > _textureSampleLastAddress)
            _textureSampleLastAddress = address;
    }

    private ushort ReadTextureRgb565At(
        int x,
        int y,
        int width,
        int format,
        bool sixteenBit,
        uint textureMode,
        uint baseAddress,
        out uint byteAddress,
        out uint word,
        out uint raw)
    {
        uint texelIndex = (uint)(y * width + x);
        return ReadTextureRgb565AtIndex(texelIndex, format, sixteenBit, textureMode, baseAddress, out byteAddress, out word, out raw);
    }

    private ushort ReadTextureRgb565AtIndex(
        uint texelIndex,
        int format,
        bool sixteenBit,
        uint textureMode,
        uint baseAddress,
        out uint byteAddress,
        out uint word,
        out uint raw)
    {
        if (sixteenBit)
        {
            byteAddress = MapTextureSampleBankByteAddress(baseAddress + texelIndex * 2u);
            if (_experimentTextureSample64KPageWrap)
                byteAddress = MapTextureSampleBankByteAddress(byteAddress & 0xffffu);
            word = ReadTexture32(byteAddress & ~3u);
            uint laneByteAddress = GetTexture16BitLaneByteAddress(byteAddress);
            ushort packed = (ushort)((word >> (int)((laneByteAddress & 2u) * 8u)) & 0xffffu);
            packed = MaybeSwapTexture16BitBytes(packed);
            raw = packed;
            return ConvertTextureFormatToRgb565(format, packed, textureMode);
        }

        byteAddress = MapTextureSampleBankByteAddress(baseAddress + texelIndex);
        if (_experimentTextureSample64KPageWrap)
            byteAddress = MapTextureSampleBankByteAddress(byteAddress & 0xffffu);
        word = ReadTexture32(byteAddress & ~3u);
        uint lane = byteAddress & 3u;
        if (_experimentReverse8BitTextureSampleLanes)
            lane = 3u - lane;
        byte value = (byte)(word >> (int)(lane * 8u));
        raw = value;
        return format switch
        {
            0 => ConvertRgb332ToRgb565(value),
            1 => ConvertNccToRgb565(value, textureMode),
            2 => GrayscaleToRgb565(value),
            3 => GrayscaleToRgb565(value),
            4 => GrayscaleToRgb565((byte)((value & 0x0f) * 17)),
            5 or 6 or 7 => ConvertPaletteTextureToRgb565(value, format),
            _ => PseudoPaletteToRgb565(value)
        };
    }

    private static ushort BilinearRgb565(ushort c00, ushort c10, ushort c01, ushort c11, float fx, float fy)
    {
        float w00 = (1.0f - fx) * (1.0f - fy);
        float w10 = fx * (1.0f - fy);
        float w01 = (1.0f - fx) * fy;
        float w11 = fx * fy;
        int r = (int)MathF.Round((((c00 >> 11) & 0x1f) * w00) + (((c10 >> 11) & 0x1f) * w10) + (((c01 >> 11) & 0x1f) * w01) + (((c11 >> 11) & 0x1f) * w11));
        int g = (int)MathF.Round((((c00 >> 5) & 0x3f) * w00) + (((c10 >> 5) & 0x3f) * w10) + (((c01 >> 5) & 0x3f) * w01) + (((c11 >> 5) & 0x3f) * w11));
        int b = (int)MathF.Round(((c00 & 0x1f) * w00) + ((c10 & 0x1f) * w10) + ((c01 & 0x1f) * w01) + ((c11 & 0x1f) * w11));
        return (ushort)((Math.Clamp(r, 0, 31) << 11) | (Math.Clamp(g, 0, 63) << 5) | Math.Clamp(b, 0, 31));
    }

    private static int WrapTextureCoordinate(float value, int size)
    {
        if (size <= 1)
            return 0;

        int coordinate = (int)MathF.Floor(value);
        coordinate %= size;
        if (coordinate < 0)
            coordinate += size;
        return coordinate;
    }

    private int TextureCoordinateToIndex(float value, int size)
        => TextureCoordinateToIndex(value, size, _fixTextureCoordinateClamp);

    private static int TextureCoordinateToIndex(float value, int size, bool clamp)
        => clamp
            ? Math.Clamp((int)MathF.Floor(value), 0, Math.Max(0, size - 1))
            : WrapTextureCoordinate(value, size);

    private static bool IsTextureFilteringEnabled(uint textureMode)
        => (textureMode & 0x6u) != 0;

    private uint GetTexture16BitLaneByteAddress(uint byteAddress)
        => _experimentReverse16BitTextureSampleLanes ? (byteAddress ^ 2u) : byteAddress;

    private ushort MaybeSwapTexture16BitBytes(ushort packed)
        => _experimentTexture16BitByteSwapRegisterBase.HasValue &&
           ReadTextureSampleRegister(RegTextureBaseAddr) == (uint)_experimentTexture16BitByteSwapRegisterBase.Value
            ? BinaryPrimitives.ReverseEndianness(packed)
            : packed;

    private static bool IsTextureFormat16Bit(int format)
        => format >= 8;

    private static int GetTextureFormatBytesPerTexel(int format)
        => IsTextureFormat16Bit(format) ? 2 : 1;

    private ushort ConvertTextureFormatToRgb565(int format, ushort packed, uint textureMode)
        => format switch
        {
            0 or 8 => ConvertRgb332ToRgb565((byte)packed),
            1 or 9 => ConvertNccToRgb565((byte)packed, textureMode),
            10 => ConvertRgb565Lane(packed, 0),
            11 => ConvertXrgb1555Lane(packed, 0, hasAlphaBit: true),
            12 => ConvertArgb4444ToRgb565(packed),
            13 => GrayscaleToRgb565((byte)packed),
            14 or 15 => ConvertPaletteTextureToRgb565((byte)packed, format),
            _ => packed
        };

    private ushort ConvertPaletteTextureToRgb565(byte value, int format)
    {
        int palette = format == 6 ? 1 : 0;
        int tmu = GetTextureSampleRegisterSourceTmu();
        return TryReadTmuPaletteRgb565(tmu, palette, value, out ushort rgb565)
            ? rgb565
            : PseudoPaletteToRgb565(value);
    }

    private bool TryReadTmuPaletteRgb565(int tmu, int palette, byte index, out ushort rgb565)
    {
        if ((uint)palette > 1u)
        {
            rgb565 = 0;
            return false;
        }

        if ((uint)tmu <= 1u)
            return TryReadTmuPaletteRgb565Direct(tmu, palette, index, out rgb565);

        if (TryReadTmuPaletteRgb565Direct(0, palette, index, out rgb565))
            return true;

        return TryReadTmuPaletteRgb565Direct(1, palette, index, out rgb565);
    }

    private bool TryReadTmuPaletteRgb565Direct(int tmu, int palette, byte index, out ushort rgb565)
    {
        int offset = palette * 256 + index;
        if (_tmuPaletteValid[tmu][offset])
        {
            rgb565 = _tmuPaletteRgb565[tmu][offset];
            return true;
        }

        rgb565 = 0;
        return false;
    }

    private uint GetTextureWidth()
        => GetTextureWidth(ReadTextureRegister(RegTextureLod));

    private static uint GetTextureWidth(uint lod)
    {
        int aspect = (int)((lod >> 21) & 0x03u);
        return ((lod >> 20) & 1u) != 0 ? 256u : Math.Max(1u, 256u >> aspect);
    }

    private uint GetTextureHeight()
        => GetTextureHeight(ReadTextureRegister(RegTextureLod));

    private static uint GetTextureHeight(uint lod)
    {
        int aspect = (int)((lod >> 21) & 0x03u);
        return ((lod >> 20) & 1u) != 0 ? Math.Max(1u, 256u >> aspect) : 256u;
    }

    private uint GetTextureLodOffset(int targetLod, int bytesPerTexel, bool applySampleBias = false)
    {
        uint textureLod = ReadTextureRegister(RegTextureLod);
        uint baseAddress = GetTextureBaseAddress(ReadTextureRegister(RegTextureBaseAddr));
        if (applySampleBias && _textureSampleBaseBias != 0)
            baseAddress = (uint)((baseAddress + _textureSampleBaseBias) & (TextureBytes - 1));
        return GetTextureLodOffsetFromBase(targetLod, bytesPerTexel, textureLod, baseAddress);
    }

    private uint GetTextureLodOffset(int targetLod, int bytesPerTexel, uint textureLod, uint textureBaseRegister)
        => GetTextureLodOffsetFromBase(targetLod, bytesPerTexel, textureLod, GetTextureBaseAddress(textureBaseRegister));

    private uint GetTextureLodOffsetFromBase(int targetLod, int bytesPerTexel, uint textureLod, uint baseAddress)
    {
        uint width = GetTextureWidth(textureLod);
        uint height = GetTextureHeight(textureLod);
        uint lodMask = ((textureLod >> 19) & 1u) != 0
            ? (((textureLod >> 18) & 1u) != 0 ? 0x0aau : 0x155u)
            : 0x1ffu;
        int firstStoredLod = _experimentTextureLodMinBaseLevel
            ? Math.Clamp((int)(textureLod & 0x3fu) >> 2, 0, 8)
            : 0;

        for (int lod = firstStoredLod; lod < targetLod; lod++)
        {
            if (((lodMask >> lod) & 1u) == 0)
                continue;

            uint lodWidth = Math.Max(1u, width >> lod);
            uint lodHeight = Math.Max(1u, height >> lod);
            uint size = lodWidth * lodHeight;
            if (lod >= 4 && size < 4u)
                size = 4u;
            baseAddress = (baseAddress + size * (uint)bytesPerTexel) & (TextureBytes - 1u);
        }

        return baseAddress;
    }

    private readonly record struct TextureFetchLayout(int Width, int Height, uint BaseAddress);

    private TextureFetchLayout GetMameTextureFetchLayout(int targetLod, uint textureMode)
        => GetMameTextureFetchLayout(targetLod, textureMode, -1);

    private TextureFetchLayout GetMameTextureFetchLayout(int targetLod, uint textureMode, int tmu)
    {
        uint textureLod = tmu >= 0
            ? ReadTextureRegisterForTmu(tmu, RegTextureLod)
            : ReadTextureSampleRegister(RegTextureLod);
        uint widthMask = 0xffu;
        uint heightMask = 0xffu;
        int aspect = (int)((textureLod >> 21) & 0x03u);
        if (((textureLod >> 20) & 1u) != 0)
            heightMask >>= aspect;
        else
            widthMask >>= aspect;

        uint lodMask = 0x1ffu;
        if (((textureLod >> 19) & 1u) != 0)
            lodMask = ((textureLod >> 18) & 1u) != 0 ? 0x0aau : 0x155u;

        int bppShift = (int)(((textureMode >> 8) & 0x0fu) >> 3);
        int lodLimit = Math.Clamp(targetLod, 0, 8);
        uint baseAddress = GetTextureBaseAddress(tmu >= 0
            ? ReadTextureRegisterForTmu(tmu, RegTextureBaseAddr)
            : ReadTextureSampleRegister(RegTextureBaseAddr));
        bool multiBase = ((textureLod >> 24) & 1u) != 0 && ((textureLod >> 28) & 0x0fu) == 0;
        if (multiBase && lodLimit != 0)
        {
            baseAddress = lodLimit switch
            {
                1 => GetTextureBaseAddress(tmu >= 0 ? ReadTextureRegisterForTmu(tmu, RegTextureBaseAddr1) : ReadTextureSampleRegister(RegTextureBaseAddr1)),
                2 => GetTextureBaseAddress(tmu >= 0 ? ReadTextureRegisterForTmu(tmu, RegTextureBaseAddr2) : ReadTextureSampleRegister(RegTextureBaseAddr2)),
                _ => GetTextureBaseAddress(tmu >= 0 ? ReadTextureRegisterForTmu(tmu, RegTextureBaseAddr38) : ReadTextureSampleRegister(RegTextureBaseAddr38))
            };

            if (lodLimit > 3)
            {
                for (int lod = 4; lod <= lodLimit; lod++)
                {
                    int previousLod = lod - 1;
                    if (((lodMask >> previousLod) & 1u) == 0)
                        continue;
                    uint size = ((widthMask >> previousLod) + 1u) * ((heightMask >> previousLod) + 1u);
                    if (size < 4u)
                        size = 4u;
                    baseAddress = (baseAddress + (size << bppShift)) & (TextureBytes - 1u);
                }
            }
        }
        else
        {
            for (int lod = 1; lod <= lodLimit; lod++)
            {
                int previousLod = lod - 1;
                if (((lodMask >> previousLod) & 1u) != 0)
                {
                    uint size = ((widthMask >> previousLod) + 1u) * ((heightMask >> previousLod) + 1u);
                    if (previousLod >= 4 && size < 4u)
                        size = 4u;
                    baseAddress = (baseAddress + (size << bppShift)) & (TextureBytes - 1u);
                }
            }
        }
        if (_textureSampleBaseBias != 0)
            baseAddress = (uint)((baseAddress + _textureSampleBaseBias) & (TextureBytes - 1));

        int ownedLod = lodLimit;
        if (((lodMask >> ownedLod) & 1u) == 0 && ownedLod < 8)
            ownedLod++;

        int width = Math.Max(1, (int)((widthMask >> ownedLod) + 1u));
        int height = Math.Max(1, (int)((heightMask >> ownedLod) + 1u));
        return new TextureFetchLayout(width, height, baseAddress);
    }

    private uint GetTextureBaseAddress()
        => GetTextureBaseAddress(ReadTextureRegister(RegTextureBaseAddr));

    private uint GetTextureBaseAddress(uint rawBaseAddress)
    {
        uint baseAddress = rawBaseAddress;
        if (_fixTextureBaseAddressShift)
            baseAddress = (baseAddress & 0xfffffu) << 3;
        return baseAddress & (TextureBytes - 1u);
    }

    private void DrawLfbLine(float ax, float ay, float bx, float by, ushort color)
    {
        if (!float.IsFinite(ax) || !float.IsFinite(ay) || !float.IsFinite(bx) || !float.IsFinite(by))
            return;

        if (ax < int.MinValue || ax > int.MaxValue ||
            ay < int.MinValue || ay > int.MaxValue ||
            bx < int.MinValue || bx > int.MaxValue ||
            by < int.MinValue || by > int.MaxValue)
        {
            return;
        }

        int x0 = (int)MathF.Round(ax);
        int y0 = (int)MathF.Round(ay);
        int x1 = (int)MathF.Round(bx);
        int y1 = (int)MathF.Round(by);
        long deltaX = (long)x1 - x0;
        long deltaY = (long)y1 - y0;
        if (Math.Abs(deltaX) > 4096 || Math.Abs(deltaY) > 4096)
            return;

        int dx = (int)Math.Abs(deltaX);
        int sx = x0 < x1 ? 1 : -1;
        int dy = -(int)Math.Abs(deltaY);
        int sy = y0 < y1 ? 1 : -1;
        int error = dx + dy;
        int guard = 0;

        while (guard++ < 4096)
        {
            PlotLfbPixel(x0, y0, color);
            if (x0 == x1 && y0 == y1)
                break;

            int e2 = error * 2;
            if (e2 >= dy)
            {
                error += dy;
                x0 += sx;
            }
            if (e2 <= dx)
            {
                error += dx;
                y0 += sy;
            }
        }
    }

    private void PlotLfbPixel(int x, int y, ushort color)
    {
        GetClip(out int x0, out int x1, out int y0, out int y1);
        if (x < x0 || x >= x1 || y < y0 || y >= y1 || x < 0 || x >= LfbRowPixels || y < 0 || y >= LfbRows)
            return;

        int bufferIndex = GetDrawBufferIndex();
        MaterializePendingClear(bufferIndex);
        InvalidateFastFillCache(bufferIndex);
        _colorBuffers[bufferIndex][(y * LfbRowPixels + x) & (LfbPixels - 1)] = color;
        TrackPixelLastWriter(bufferIndex, x, y, GetPixelLastWriterId("lfb", "line", color));
        _lfbWriteCount++;
    }

    private void GetClip(out int x0, out int x1, out int y0, out int y1)
    {
        if (_experimentForceVisibleClip)
        {
            x0 = 0;
            x1 = 640;
            y0 = 0;
            y1 = 480;
            return;
        }

        uint clipX = _registers[RegClipLeftRight];
        uint clipY = _registers[RegClipLowYHighY];
        x0 = Math.Clamp((int)((clipX >> 16) & 0x3ff), 0, 1024);
        x1 = Math.Clamp((int)(clipX & 0x3ff), 0, 1024);
        y0 = Math.Clamp((int)((clipY >> 16) & 0x3ff), 0, LfbRows);
        y1 = Math.Clamp((int)(clipY & 0x3ff), 0, LfbRows);
        if (x1 <= x0)
        {
            x0 = 0;
            x1 = 640;
        }
        if (y1 <= y0)
        {
            y0 = 0;
            y1 = 480;
        }
    }

    private void TraceDraw(string message)
    {
        if (_traceDraw && _drawTraceCount++ < _drawTraceLimit)
        {
            ulong pc = CpuPcProvider?.Invoke() ?? 0;
            string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
            Console.WriteLine($"[GAUNTDL:VOODOO-DRAW] {message}{pcStatus}");
        }
    }

    private void TraceSetupTriangle(ushort color, bool textured)
    {
        if (!_traceSetupTriangles || _setupTriangleTraceCount++ >= 160)
            return;

        GetClip(out int clipX0, out int clipX1, out int clipY0, out int clipY1);
        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-SETUP] color=0x{color:X4} tex={(textured ? 1 : 0)} " +
            $"xy=({_setupVertices[0].X:F3},{_setupVertices[0].Y:F3})/({_setupVertices[1].X:F3},{_setupVertices[1].Y:F3})/({_setupVertices[2].X:F3},{_setupVertices[2].Y:F3}) " +
            $"st=({_setupVertices[0].S:F3},{_setupVertices[0].T:F3})/({_setupVertices[1].S:F3},{_setupVertices[1].T:F3})/({_setupVertices[2].S:F3},{_setupVertices[2].T:F3}) " +
            $"rawxy=0x{_registers[0x99]:X8}/0x{_registers[0x9A]:X8} rawfloat=({FloatFromRegister(_registers[0x99]):F3},{FloatFromRegister(_registers[0x9A]):F3}) " +
            $"wrapped=({SetupVertexCoordinate(_registers[0x99]):F3},{SetupVertexCoordinate(_registers[0x9A]):F3}) " +
            $"clip=({clipX0},{clipY0})-({clipX1},{clipY1}) setup=0x{_registers[0x98]:X8} fbz=0x{_registers[RegFbzMode]:X8} fbi3=0x{_registers[RegFbiInit3]:X8}{pcStatus}");
    }

    private void TraceTextureSample(
        float s,
        float t,
        int width,
        int height,
        int x,
        int y,
        uint mode,
        uint lod,
        uint registerBase,
        uint resolvedBase,
        uint byteAddress,
        uint word,
        uint raw,
        ushort result)
    {
        TraceTextureSampleWriterCorrelation(s, t, width, height, x, y, mode, lod, registerBase, resolvedBase, byteAddress, word, raw, result);
        if (!_traceTextureSamples ||
            (_traceTextureSampleRegisterBase.HasValue &&
             registerBase != (uint)_traceTextureSampleRegisterBase.Value) ||
            _textureSampleTraceCount++ >= 160)
        {
            return;
        }

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        string nearbyStatus = result == 0 ? $" {GetNearbyTextureWordStatus(byteAddress)}" : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-TEXSAMPLE] st=({s:F3},{t:F3}) xy=({x},{y}) size={width}x{height} " +
            $"mode=0x{mode:X8} lod=0x{lod:X8} regbase=0x{registerBase:X8} base=0x{resolvedBase:X6} addr=0x{byteAddress:X6} " +
            $"word=0x{word:X8} raw=0x{raw:X4} result=0x{result:X4}{nearbyStatus}{pcStatus}");
    }

    private void TraceTextureSampleWriterCorrelation(
        float s,
        float t,
        int width,
        int height,
        int x,
        int y,
        uint mode,
        uint lod,
        uint registerBase,
        uint resolvedBase,
        uint byteAddress,
        uint word,
        uint raw,
        ushort result)
    {
        if (!_traceTextureSampleWriters ||
            _renderFrame < _traceTextureMinRenderFrame)
        {
            return;
        }

        int wordOffset = (int)((byteAddress & (TextureBytes - 1u)) >> 2);
        bool hasWriter = _textureWordLastWriters.TryGetValue(wordOffset, out TextureWordLastWriter writer);
        if (_traceTextureSampleWritersRequireWriter && !hasWriter)
            return;

        if (_textureSampleWriterTraceCount >= _traceTextureSampleWritersLimit)
            return;

        _textureSampleWriterTraceCount++;

        string writerStatus = hasWriter
            ? FormatTextureWordWriterStatus(writer)
            : "-";
        string fifoOwnerStatus = hasWriter
            ? FormatTextureSampleFifoOwnerStatus(writer)
            : "";
        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-TEXSAMPLE-WRITER] n={_textureSampleWriterTraceCount} frame={_renderFrame} " +
            $"st=({s:F3},{t:F3}) xy=({x},{y}) size={width}x{height} " +
            $"mode=0x{mode:X8} lod=0x{lod:X8} regbase=0x{registerBase:X8} base=0x{resolvedBase:X6} " +
            $"addr=0x{byteAddress:X6}/w{wordOffset:X5} word=0x{word:X8} raw=0x{raw:X4} result=0x{result:X4} " +
            $"writer={writerStatus}{fifoOwnerStatus} cmd=0x{_currentCommandFifoCommand:X8}:0x{_currentCommandFifoPacketStart * 4:X8}:rd0x{_cmdFifoReadIndex * 4:X8} " +
            $"draws={_fifoDrawPacketCount} texWrites={_textureWriteCount} buf={GetDrawBufferIndex()}{pcStatus}");
    }

    private string FormatTextureSampleFifoOwnerStatus(TextureWordLastWriter writer)
    {
        if (!_traceTextureSampleFifoOwners || !writer.Type5)
            return "";

        int packetStart = writer.PacketStart;
        int targetIndex = packetStart + 1;
        int payloadIndex = packetStart + 2 + writer.Type5Index;
        return
            $" fifoOwner=hdr[{FormatCommandFifoStorageWordDebug(packetStart)}] " +
            $"target[{FormatCommandFifoStorageWordDebug(targetIndex)}] " +
            $"payload[{FormatCommandFifoStorageWordDebug(payloadIndex)}]";
    }

    private void TraceTextureFetchCompare(
        float s,
        float t,
        uint mode,
        uint lod,
        int targetLod,
        int format,
        bool sixteenBit,
        bool filtered,
        int currentWidth,
        int currentHeight,
        uint currentBase,
        bool currentClampS,
        bool currentClampT,
        int currentX,
        int currentY)
    {
        if (!_traceTextureFetchCompare ||
            _renderFrame < _traceTextureMinRenderFrame ||
            _textureFetchCompareTraceCount++ >= _traceTextureFetchCompareLimit)
        {
            return;
        }

        TextureFetchLayout mameLayout = GetMameTextureFetchLayout(targetLod, mode);
        bool mameClampS = (mode & 0x40u) != 0;
        bool mameClampT = (mode & 0x80u) != 0;
        int mameX = TextureCoordinateToIndex(s, mameLayout.Width, mameClampS);
        int mameY = _fixTextureTOriginFlip
            ? TextureCoordinateToIndex((mameLayout.Height - 1) - t, mameLayout.Height, mameClampT)
            : TextureCoordinateToIndex(t, mameLayout.Height, mameClampT);

        ushort currentRgb = ReadTextureRgb565At(
            currentX,
            currentY,
            currentWidth,
            format,
            sixteenBit,
            mode,
            currentBase,
            out uint currentAddress,
            out uint currentWord,
            out uint currentRaw);
        ushort mameRgb = ReadTextureRgb565At(
            mameX,
            mameY,
            mameLayout.Width,
            format,
            sixteenBit,
            mode,
            mameLayout.BaseAddress,
            out uint mameAddress,
            out uint mameWord,
            out uint mameRaw);

        ulong pc = CpuPcProvider?.Invoke() ?? 0;
        string pcStatus = pc != 0 ? $" pc=0x{pc:x16}" : "";
        long baseDelta = (long)mameLayout.BaseAddress - currentBase;
        long addressDelta = (long)mameAddress - currentAddress;
        Console.WriteLine(
            $"[GAUNTDL:VOODOO-TEXFETCH] st=({s:F3},{t:F3}) mode=0x{mode:X8} lod=0x{lod:X8} targetLod={targetLod} " +
            $"fmt={format} b16={(sixteenBit ? 1 : 0)} filt={(filtered ? 1 : 0)} " +
            $"cur=size={currentWidth}x{currentHeight}:base=0x{currentBase:X6}:clamp={(currentClampS ? 1 : 0)}/{(currentClampT ? 1 : 0)}:" +
            $"xy={currentX},{currentY}:addr=0x{currentAddress:X6}:word=0x{currentWord:X8}:raw=0x{currentRaw:X4}:rgb=0x{currentRgb:X4} " +
            $"mame=size={mameLayout.Width}x{mameLayout.Height}:base=0x{mameLayout.BaseAddress:X6}:clamp={(mameClampS ? 1 : 0)}/{(mameClampT ? 1 : 0)}:" +
            $"xy={mameX},{mameY}:addr=0x{mameAddress:X6}:word=0x{mameWord:X8}:raw=0x{mameRaw:X4}:rgb=0x{mameRgb:X4} " +
            $"deltaBase={baseDelta} deltaAddr={addressDelta}{pcStatus}");
    }

    private string GetNearbyTextureWordStatus(uint byteAddress)
    {
        int center = (int)((byteAddress >> 2) & (TextureWords - 1));
        for (int distance = 1; distance <= 4096; distance++)
        {
            int low = (center - distance) & (TextureWords - 1);
            uint lowWord = _textureMemory[low];
            if (lowWord != 0)
                return $"near=-{distance}:0x{low * 4:X6}=0x{lowWord:X8}";

            int high = (center + distance) & (TextureWords - 1);
            uint highWord = _textureMemory[high];
            if (highWord != 0)
                return $"near=+{distance}:0x{high * 4:X6}=0x{highWord:X8}";
        }

        return "near=none";
    }

    private static int ParseDrawTraceLimit(string name, int fallback)
        => int.TryParse(Environment.GetEnvironmentVariable(name), out int value) && value >= 0 ? value : fallback;

    private int GetLfbPixelOffset(uint byteOffset, bool twoPixels, uint lfbMode)
    {
        uint wordOffset = (byteOffset & (LfbBytes - 1u)) >> 2;
        uint pixelOffset = twoPixels ? wordOffset << 1 : wordOffset;
        int x = (int)(pixelOffset & (LfbRowPixels - 1));
        int y = (int)((pixelOffset >> 10) & 0x3ff);
        if (((lfbMode >> 13) & 1u) != 0)
            y = GetLfbYOrigin() - y;
        y = Math.Clamp(y, 0, LfbRows - 1);
        return y * LfbRowPixels + x;
    }

    private int GetLfbYOrigin()
    {
        int origin = (int)((_registers[RegFbiInit3] >> 22) & 0x3ff);
        return origin > 0 ? Math.Min(origin, LfbRows - 1) : 479;
    }

    private ushort[] GetDrawBuffer()
        => _colorBuffers[GetDrawBufferIndex()];

    private int GetDrawBufferIndex()
    {
        int select = (int)((_registers[RegFbzMode] >> 14) & 0x03u);
        return MapDrawBufferSelect(select);
    }

    private ushort[] GetLfbReadBuffer(uint lfbMode)
    {
        int select = (int)((lfbMode >> 6) & 0x03u);
        if (select == 2)
            return _auxBuffer;

        int bufferIndex = MapLfbBufferSelect(select);
        MaterializePendingClear(bufferIndex);
        return _colorBuffers[bufferIndex];
    }

    private ushort[] GetLfbWriteBuffer(uint lfbMode)
    {
        int bufferIndex = GetLfbWriteBufferIndex(lfbMode);
        MaterializePendingClear(bufferIndex);
        return _colorBuffers[bufferIndex];
    }

    private int GetLfbWriteBufferIndex(uint lfbMode)
        => MapLfbWriteBufferSelect((int)((lfbMode >> 4) & 0x03u));

    private int MapDrawBufferSelect(int select)
        => select switch
        {
            0 => _frontBufferIndex,
            1 => _backBufferIndex,
            2 => GetAuxBufferIndex(),
            _ => _backBufferIndex
        };

    private int MapLfbBufferSelect(int select)
        => select switch
        {
            0 => _frontBufferIndex,
            1 => _backBufferIndex,
            2 => GetAuxBufferIndex(),
            _ => _frontBufferIndex
        };

    private int MapLfbWriteBufferSelect(int select)
        => select switch
        {
            0 => _frontBufferIndex,
            1 => _backBufferIndex,
            _ => _frontBufferIndex
        };

    private int GetAuxBufferIndex()
    {
        int count = GetColorBufferCount();
        if (count < 3)
            return _backBufferIndex;

        for (int i = 0; i < 3; i++)
        {
            if (i != _frontBufferIndex && i != _backBufferIndex)
                return i;
        }

        return 2;
    }

    private void WriteLfbDepth(uint value, int format, int pixel)
    {
        switch (format)
        {
            case 12:
            case 13:
            case 14:
                _auxBuffer[pixel & (LfbPixels - 1)] = (ushort)(value >> 16);
                break;
            case 15:
                _auxBuffer[pixel & (LfbPixels - 1)] = (ushort)value;
                _auxBuffer[(pixel + 1) & (LfbPixels - 1)] = (ushort)(value >> 16);
                break;
        }
    }

    private int GetColorBufferCount()
        => ((_registers[RegFbiInit2] >> 4) & 1u) != 0 ? 3 : 2;

    private string GetBufferCountDebugStatus()
        => _debugBufferCounts
            ? $"bnnz={GetBufferNonZeroCount(0)}/{GetBufferNonZeroCount(1)}/{GetBufferNonZeroCount(2)} " +
              $"bact={GetBufferActiveColorCount(0)}/{GetBufferActiveColorCount(1)}/{GetBufferActiveColorCount(2)} " +
              $"bvact={GetVisibleBufferActiveColorCount(0)}/{GetVisibleBufferActiveColorCount(1)}/{GetVisibleBufferActiveColorCount(2)} " +
              $"rbuf={_lastRenderBufferIndex} dbuf={(_fixDisplayBufferSelection ? 1 : 0)} "
            : "";

    private string GetTmuDebugStatus()
    {
        if (!_fixTmuRegisterBanks)
            return "";

        bool tmu0Valid = HasTmuRegister(0);
        bool tmu1Valid = HasTmuRegister(1);
        if (!tmu0Valid && !tmu1Valid)
            return "";

        return $"tmu0={FormatTmuDebugStatus(0)} tmu1={FormatTmuDebugStatus(1)} ";
    }

    private string GetTextureZeroSampleBucketDebugStatus()
    {
        if (!_debugTextureZeroSampleBuckets)
            return "";

        Span<int> topBuckets = stackalloc int[3] { -1, -1, -1 };
        Span<int> topCounts = stackalloc int[3];
        for (int i = 0; i < _textureZeroSampleBuckets.Length; i++)
        {
            int count = _textureZeroSampleBuckets[i];
            if (count <= topCounts[2])
                continue;

            if (count > topCounts[0])
            {
                topCounts[2] = topCounts[1];
                topBuckets[2] = topBuckets[1];
                topCounts[1] = topCounts[0];
                topBuckets[1] = topBuckets[0];
                topCounts[0] = count;
                topBuckets[0] = i;
            }
            else if (count > topCounts[1])
            {
                topCounts[2] = topCounts[1];
                topBuckets[2] = topBuckets[1];
                topCounts[1] = count;
                topBuckets[1] = i;
            }
            else
            {
                topCounts[2] = count;
                topBuckets[2] = i;
            }
        }

        uint first = _textureZeroSampleFirstAddress == uint.MaxValue ? 0u : _textureZeroSampleFirstAddress;
        return $"texzero={_textureZeroSampleBucketTotal}/0x{first:X6}/0x{_textureZeroSampleLastAddress:X6}/" +
               FormatTextureZeroSampleBucket(topBuckets[0], topCounts[0]) + "/" +
               FormatTextureZeroSampleBucket(topBuckets[1], topCounts[1]) + "/" +
               FormatTextureZeroSampleBucket(topBuckets[2], topCounts[2]) + " ";
    }

    private string GetTextureSampleDebugStatus()
    {
        if (!_debugTextureSamples)
            return "";

        Span<int> rawIndexes = stackalloc int[4] { -1, -1, -1, -1 };
        Span<int> rawCounts = stackalloc int[4];
        Span<int> colorIndexes = stackalloc int[4] { -1, -1, -1, -1 };
        Span<int> colorCounts = stackalloc int[4];
        Span<int> addressBuckets = stackalloc int[4] { -1, -1, -1, -1 };
        Span<int> addressCounts = stackalloc int[4];
        CollectTopBuckets(_textureSampleRawBuckets, rawIndexes, rawCounts);
        CollectTopBuckets(_textureSampleColorBuckets, colorIndexes, colorCounts);
        CollectTopBuckets(_textureSampleAddressBuckets, addressBuckets, addressCounts);

        uint first = _textureSampleFirstAddress == uint.MaxValue ? 0u : _textureSampleFirstAddress;
        return $"texsamp={_textureSampleDebugTotal}/0x{first:X6}/0x{_textureSampleLastAddress:X6}" +
               $"/raw{FormatTopHexBuckets(rawIndexes, rawCounts, 4)}" +
               $"/rgb{FormatTopHexBuckets(colorIndexes, colorCounts, 4)}" +
               $"/addr{FormatTopAddressBuckets(addressBuckets, addressCounts)} ";
    }

    private static void CollectTopBuckets(ReadOnlySpan<int> buckets, Span<int> topIndexes, Span<int> topCounts)
    {
        for (int i = 0; i < buckets.Length; i++)
        {
            int count = buckets[i];
            for (int slot = 0; slot < topCounts.Length; slot++)
            {
                if (count <= topCounts[slot])
                    continue;

                for (int move = topCounts.Length - 1; move > slot; move--)
                {
                    topCounts[move] = topCounts[move - 1];
                    topIndexes[move] = topIndexes[move - 1];
                }

                topCounts[slot] = count;
                topIndexes[slot] = i;
                break;
            }
        }
    }

    private static string FormatTopHexBuckets(ReadOnlySpan<int> indexes, ReadOnlySpan<int> counts, int digits)
    {
        string[] parts = new string[indexes.Length];
        for (int i = 0; i < indexes.Length; i++)
            parts[i] = indexes[i] < 0 ? "-" : $"0x{indexes[i].ToString($"X{digits}")}:{counts[i]}";
        return string.Join(",", parts);
    }

    private static string FormatTopAddressBuckets(ReadOnlySpan<int> buckets, ReadOnlySpan<int> counts)
    {
        string[] parts = new string[buckets.Length];
        for (int i = 0; i < buckets.Length; i++)
            parts[i] = buckets[i] < 0 ? "-" : $"0x{(buckets[i] << TextureZeroSampleBucketShift):X6}:{counts[i]}";
        return string.Join(",", parts);
    }

    private string FormatTextureZeroSampleBucket(int bucket, int count)
    {
        if (bucket < 0)
            return "-";

        int firstWord = bucket << (TextureZeroSampleBucketShift - 2);
        int wordCount = 1 << (TextureZeroSampleBucketShift - 2);
        int nonZeroWords = 0;
        int touchedWords = 0;
        for (int i = 0; i < wordCount; i++)
        {
            int index = firstWord + i;
            if ((uint)index >= TextureWords)
                break;
            if (_textureMemory[index] != 0)
                nonZeroWords++;
            if (_textureTouchedWords[index])
                touchedWords++;
        }

        int zeroWrites = _textureZeroWriteBuckets[bucket];
        int nonZeroWrites = _textureNonZeroWriteBuckets[bucket];
        return $"0x{bucket << TextureZeroSampleBucketShift:X6}:{count}:nz{nonZeroWords}:tw{touchedWords}:w{nonZeroWrites}/{zeroWrites}";
    }

    private bool HasTmuRegister(int tmu)
        => _tmuRegisterValid[tmu][RegTextureMode] ||
           _tmuRegisterValid[tmu][RegTextureLod] ||
           _tmuRegisterValid[tmu][RegTextureBaseAddr] ||
           HasTmuNccTable(tmu, 0) ||
           HasTmuNccTable(tmu, 1) ||
           HasTmuPalette(tmu, 0) ||
           HasTmuPalette(tmu, 1);

    private string FormatTmuDebugStatus(int tmu)
    {
        string mode = _tmuRegisterValid[tmu][RegTextureMode] ? _tmuRegisters[tmu][RegTextureMode].ToString("X8") : "--------";
        string lod = _tmuRegisterValid[tmu][RegTextureLod] ? _tmuRegisters[tmu][RegTextureLod].ToString("X8") : "--------";
        string baseAddress = _tmuRegisterValid[tmu][RegTextureBaseAddr] ? _tmuRegisters[tmu][RegTextureBaseAddr].ToString("X8") : "--------";
        int palette0 = GetTmuPaletteValidCount(tmu, 0);
        int palette1 = GetTmuPaletteValidCount(tmu, 1);
        string paletteStatus = palette0 != 0 || palette1 != 0 ? $"/pal{palette0}/{palette1}" : "";
        return $"{mode}/{lod}/{baseAddress}/ncc{GetTmuNccNonZeroCount(tmu, 0)}/{GetTmuNccNonZeroCount(tmu, 1)}{paletteStatus}";
    }

    private bool HasTmuNccTable(int tmu, int table)
    {
        int start = RegNccTable + table * 12;
        for (int i = 0; i < 12; i++)
        {
            if (_tmuRegisterValid[tmu][start + i])
                return true;
        }

        return false;
    }

    private bool HasTmuPalette(int tmu, int palette)
        => GetTmuPaletteValidCount(tmu, palette) != 0;

    private int GetTmuNccNonZeroCount(int tmu, int table)
    {
        int start = RegNccTable + table * 12;
        int count = 0;
        for (int i = 0; i < 12; i++)
        {
            if (_tmuRegisterValid[tmu][start + i] && _tmuRegisters[tmu][start + i] != 0)
                count++;
        }

        return count;
    }

    private int GetTmuPaletteValidCount(int tmu, int palette)
    {
        int start = palette * 256;
        int count = 0;
        for (int i = 0; i < 256; i++)
        {
            if (_tmuPaletteValid[tmu][start + i])
                count++;
        }

        return count;
    }

    private int GetBufferNonZeroCount(int index)
    {
        if ((uint)index >= (uint)_colorBuffers.Length)
            return 0;

        int count = 0;
        ushort[] buffer = _colorBuffers[index];
        for (int i = 0; i < buffer.Length; i++)
        {
            if (buffer[i] != 0)
                count++;
        }

        return count;
    }

    private int GetBufferActiveColorCount(int index)
    {
        if ((uint)index >= (uint)_colorBuffers.Length)
            return 0;

        int count = 0;
        ushort[] buffer = _colorBuffers[index];
        for (int i = 0; i < buffer.Length; i++)
        {
            ushort pixel = buffer[i];
            if (pixel != 0 && pixel != 0xffff)
                count++;
        }

        return count;
    }

    private int GetVisibleBufferActiveColorCount(int index)
    {
        if ((uint)index >= (uint)_colorBuffers.Length)
            return 0;

        int count = 0;
        ushort[] buffer = _colorBuffers[index];
        for (int y = 0; y < 480; y++)
        {
            int row = y * 1024;
            for (int x = 0; x < 640; x++)
            {
                ushort pixel = buffer[(row + x) & (LfbPixels - 1)];
                if (pixel != 0 && pixel != 0xffff)
                    count++;
            }
        }

        return count;
    }

    private int GetVisibleBufferWhiteCount(int index)
    {
        if ((uint)index >= (uint)_colorBuffers.Length)
            return 0;

        int count = 0;
        ushort[] buffer = _colorBuffers[index];
        for (int y = 0; y < 480; y++)
        {
            int row = y * 1024;
            for (int x = 0; x < 640; x++)
            {
                if (buffer[(row + x) & (LfbPixels - 1)] == 0xffff)
                    count++;
            }
        }

        return count;
    }

    private int GetVisibleBufferUniqueColorCount(int index, int stopAfter)
    {
        if ((uint)index >= (uint)_colorBuffers.Length)
            return 0;

        HashSet<ushort> colors = [];
        ushort[] buffer = _colorBuffers[index];
        for (int y = 0; y < 480; y += 4)
        {
            int row = y * 1024;
            for (int x = 0; x < 640; x += 4)
            {
                ushort pixel = buffer[(row + x) & (LfbPixels - 1)];
                if (pixel == 0)
                    continue;

                colors.Add(pixel);
                if (colors.Count >= stopAfter)
                    return colors.Count;
            }
        }

        return colors.Count;
    }

    private void SwapBuffers(uint command)
    {
        if ((command & 1u) != 0)
        {
            TraceFastFillSwapOrder(
                "swap-pending",
                RegSwapbufferCommand,
                command,
                $"pendingBefore={_pendingSwapCount} vblankWait={(command >> 1) & 0xffu}");
            if (_pendingSwapCount < _pendingSwapCommands.Length)
                _pendingSwapCommands[_pendingSwapCount++] = command;
            return;
        }

        ExecuteSwapBuffers(command);
    }

    private void ExecuteSwapBuffers(uint command)
    {
        _swapBufferCount++;
        _lastSwapCommand = command;

        int previousFront = _frontBufferIndex;
        int previousBack = _backBufferIndex;
        // Gauntlet's Voodoo 2 implements swapbufferCMD bit 9 regardless of
        // which command-FIFO bringup model is selected.
        bool dontSwap = ((command >> 9) & 1u) != 0;
        // swapbufferCMD bits 1-8 are the vertical-retrace wait count. They do
        // not request a back-buffer clear; clearing here destroyed the frame
        // that had just rotated from front to back.
        int vblankSwap = (int)((command >> 1) & 0xffu);
        TraceFastFillSwapOrder(
            "swap",
            RegSwapbufferCommand,
            command,
            $"preFront={previousFront} preBack={previousBack} dont={(dontSwap ? 1 : 0)} vblankWait={vblankSwap}");
        CountSwapPc(command, dontSwap, clearBackBuffer: false);
        if (dontSwap)
        {
            _swapDontSwapCount++;
        }
        else
        {
            int count = GetColorBufferCount();
            if (count >= 3)
            {
                _frontBufferIndex = (_frontBufferIndex + 1) % 3;
                _backBufferIndex = (_frontBufferIndex + 1) % 3;
            }
            else
            {
                _frontBufferIndex = _backBufferIndex == 0 ? 0 : 1;
                _backBufferIndex = 1 - _frontBufferIndex;
            }
        }

        TraceFastFillSwapOrder(
            "swap-result",
            RegSwapbufferCommand,
            command,
            $"preFront={previousFront} preBack={previousBack} dont={(dontSwap ? 1 : 0)} vblankWait={vblankSwap}");
    }

    private void SetPendingClear(int bufferIndex, int x0, int x1, int y0, int y1, ushort color)
    {
        if ((uint)bufferIndex >= (uint)_pendingClearValid.Length)
            return;

        if (_pendingClearValid[bufferIndex] &&
            (_pendingClearX0[bufferIndex] != x0 ||
             _pendingClearX1[bufferIndex] != x1 ||
             _pendingClearY0[bufferIndex] != y0 ||
             _pendingClearY1[bufferIndex] != y1))
        {
            MaterializePendingClear(bufferIndex);
        }

        _pendingClearValid[bufferIndex] = true;
        _pendingClearX0[bufferIndex] = x0;
        _pendingClearX1[bufferIndex] = x1;
        _pendingClearY0[bufferIndex] = y0;
        _pendingClearY1[bufferIndex] = y1;
        _pendingClearColor[bufferIndex] = color;
    }

    private void MaterializePendingClear(int bufferIndex)
    {
        if ((uint)bufferIndex >= (uint)_pendingClearValid.Length || !_pendingClearValid[bufferIndex])
            return;

        int x0 = _pendingClearX0[bufferIndex];
        int x1 = _pendingClearX1[bufferIndex];
        int y0 = _pendingClearY0[bufferIndex];
        int y1 = _pendingClearY1[bufferIndex];
        ushort color = _pendingClearColor[bufferIndex];
        ushort[] buffer = _colorBuffers[bufferIndex];
        int width = x1 - x0;
        for (int y = y0; y < y1; y++)
        {
            int offset = y * LfbRowPixels + x0;
            buffer.AsSpan(offset, width).Fill(color);
        }

        _pendingClearValid[bufferIndex] = false;
    }

    private bool IsCachedFastFill(int bufferIndex, int x0, int x1, int y0, int y1, ushort color)
        => (uint)bufferIndex < (uint)_lastFastFillValid.Length &&
           _lastFastFillValid[bufferIndex] &&
           _lastFastFillX0[bufferIndex] == x0 &&
           _lastFastFillX1[bufferIndex] == x1 &&
           _lastFastFillY0[bufferIndex] == y0 &&
           _lastFastFillY1[bufferIndex] == y1 &&
           _lastFastFillColor[bufferIndex] == color;

    private void CacheFastFill(int bufferIndex, int x0, int x1, int y0, int y1, ushort color)
    {
        if ((uint)bufferIndex >= (uint)_lastFastFillValid.Length)
            return;

        _lastFastFillValid[bufferIndex] = true;
        _lastFastFillX0[bufferIndex] = x0;
        _lastFastFillX1[bufferIndex] = x1;
        _lastFastFillY0[bufferIndex] = y0;
        _lastFastFillY1[bufferIndex] = y1;
        _lastFastFillColor[bufferIndex] = color;
    }

    private void InvalidateFastFillCache(int bufferIndex)
    {
        if ((uint)bufferIndex < (uint)_lastFastFillValid.Length)
            _lastFastFillValid[bufferIndex] = false;
    }

    private static bool IsTwoPixelLfbFormat(int format)
        => format is 0 or 1 or 2 or 15;

    private static bool TryExpandLfbPixel(uint value, int format, int rgbaLanes, bool highHalf, out ushort rgb565)
    {
        int shift = highHalf ? 16 : 0;
        rgb565 = 0;
        switch (format)
        {
            case 0:
                rgb565 = ConvertRgb565Lane((ushort)(value >> shift), rgbaLanes);
                return true;
            case 1:
                rgb565 = ConvertXrgb1555Lane((ushort)(value >> shift), rgbaLanes, hasAlphaBit: false);
                return true;
            case 2:
                rgb565 = ConvertXrgb1555Lane((ushort)(value >> shift), rgbaLanes, hasAlphaBit: true);
                return true;
            case 4:
            case 5:
                if (highHalf)
                    return false;
                rgb565 = Convert8888Lane(value, rgbaLanes, hasAlpha: format == 5);
                return true;
            case 12:
                if (highHalf)
                    return false;
                rgb565 = ConvertRgb565Lane((ushort)value, rgbaLanes);
                return true;
            case 13:
                if (highHalf)
                    return false;
                rgb565 = ConvertXrgb1555Lane((ushort)value, rgbaLanes, hasAlphaBit: false);
                return true;
            case 14:
                if (highHalf)
                    return false;
                rgb565 = ConvertXrgb1555Lane((ushort)value, rgbaLanes, hasAlphaBit: true);
                return true;
            default:
                return false;
        }
    }

    private static ushort ConvertRgb565Lane(ushort packed, int rgbaLanes)
    {
        int r = (rgbaLanes is 1 or 3) ? packed & 0x1f : (packed >> 11) & 0x1f;
        int g = (packed >> 5) & 0x3f;
        int b = (rgbaLanes is 1 or 3) ? (packed >> 11) & 0x1f : packed & 0x1f;
        return (ushort)((r << 11) | (g << 5) | b);
    }

    private static ushort ConvertXrgb1555Lane(ushort packed, int rgbaLanes, bool hasAlphaBit)
    {
        int rShift;
        int gShift;
        int bShift;
        if (rgbaLanes == 2)
        {
            rShift = 11;
            gShift = 6;
            bShift = 1;
        }
        else if (rgbaLanes == 3)
        {
            rShift = 1;
            gShift = 6;
            bShift = 11;
        }
        else if (rgbaLanes == 1)
        {
            rShift = 0;
            gShift = 5;
            bShift = 10;
        }
        else
        {
            rShift = 10;
            gShift = 5;
            bShift = 0;
        }

        if (hasAlphaBit)
        {
            // The alpha bit does not affect the bringup color buffer, but keeping
            // the branch here mirrors the Voodoo format split and documents it.
        }

        int r = (packed >> rShift) & 0x1f;
        int g = (packed >> gShift) & 0x1f;
        int b = (packed >> bShift) & 0x1f;
        return (ushort)((r << 11) | ((g << 1 | g >> 4) << 5) | b);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static ushort ConvertXrgb1555Lane0(ushort packed)
    {
        int r = (packed >> 10) & 0x1f;
        int g = (packed >> 5) & 0x1f;
        int b = packed & 0x1f;
        return (ushort)((r << 11) | ((g << 1 | g >> 4) << 5) | b);
    }

    private static ushort Convert8888Lane(uint packed, int rgbaLanes, bool hasAlpha)
    {
        int r;
        int g;
        int b;
        if (rgbaLanes == 2)
        {
            r = (int)((packed >> 24) & 0xff);
            g = (int)((packed >> 16) & 0xff);
            b = (int)((packed >> 8) & 0xff);
        }
        else if (rgbaLanes == 3)
        {
            r = (int)((packed >> 8) & 0xff);
            g = (int)((packed >> 16) & 0xff);
            b = (int)((packed >> 24) & 0xff);
        }
        else if (rgbaLanes == 1)
        {
            r = (int)(packed & 0xff);
            g = (int)((packed >> 8) & 0xff);
            b = (int)((packed >> 16) & 0xff);
        }
        else
        {
            r = (int)((packed >> 16) & 0xff);
            g = (int)((packed >> 8) & 0xff);
            b = (int)(packed & 0xff);
        }

        if (hasAlpha)
        {
            // Alpha is consumed by the real pixel pipeline; the bringup backend
            // stores only the visible RGB surface for now.
        }

        return (ushort)(((r >> 3) << 11) | ((g >> 2) << 5) | (b >> 3));
    }

    private ushort GetDrawColor()
    {
        ushort color = GetFloatDrawColorOrZero();
        if (color != 0)
            return color;

        color = GetIntegerDrawColorOrZero();
        if (color != 0)
            return color;

        color = ArgbToRgb565(_registers[RegColor1]);
        if (color == 0)
            color = ArgbToRgb565(_registers[RegColor0]);
        if (color == 0)
            color = (ushort)_registers[RegZaColor];
        return color == 0 ? (ushort)0xffff : color;
    }

    private ushort ApplyFbzColorPathRgb(ushort texel, ushort iteratedColor, byte textureAlpha = 255)
        => _experimentMameTwoTmuCombine
            ? ApplyFbzColorPathRgbMame(texel, iteratedColor, textureAlpha)
            : ApplyFbzColorPathRgbLegacy(texel, iteratedColor);

    private ushort ApplyFbzColorPathRgbLegacy(ushort texel, ushort iteratedColor)
    {
        uint fbzcp = _registers[RegFbzColorPath];
        ushort color0 = ArgbToRgb565(_registers[RegColor0]);
        ushort color1 = ArgbToRgb565(_registers[RegColor1]);
        ushort other = ((fbzcp >> 0) & 0x03u) switch
        {
            0 => iteratedColor,
            1 => texel,
            2 => color1,
            _ => 0
        };
        ushort local = ((fbzcp >> 7) & 1u) != 0
            ? (((texel >> 15) & 1) != 0 ? color0 : iteratedColor)
            : (((fbzcp >> 4) & 1u) == 0 ? iteratedColor : color0);

        Rgb565ToBytes(other, out int or, out int og, out int ob);
        Rgb565ToBytes(local, out int lr, out int lg, out int lb);
        Rgb565ToBytes(texel, out int tr, out int tg, out int tb);
        int r = ((fbzcp >> 8) & 1u) == 0 ? or : 0;
        int g = ((fbzcp >> 8) & 1u) == 0 ? og : 0;
        int b = ((fbzcp >> 8) & 1u) == 0 ? ob : 0;
        if (((fbzcp >> 9) & 1u) != 0)
        {
            r -= lr;
            g -= lg;
            b -= lb;
        }
        (int mr, int mg, int mb) = ((fbzcp >> 10) & 0x07u) switch
        {
            1 => (lr, lg, lb),
            5 => (tr, tg, tb),
            _ => (255, 255, 255)
        };
        if (((fbzcp >> 13) & 1u) == 0)
        {
            mr = 255 - mr;
            mg = 255 - mg;
            mb = 255 - mb;
        }
        r = r * mr / 255;
        g = g * mg / 255;
        b = b * mb / 255;
        if (((fbzcp >> 14) & 0x03u) == 1)
        {
            r += lr;
            g += lg;
            b += lb;
        }
        if (((fbzcp >> 16) & 1u) != 0)
        {
            r = 255 - r;
            g = 255 - g;
            b = 255 - b;
        }
        return BytesToRgb565(r, g, b);
    }

    private ushort ApplyFbzColorPathRgbMame(ushort texel, ushort iteratedColor, byte textureAlpha)
    {
        uint fbzcp = _registers[RegFbzColorPath];
        ushort color0 = ArgbToRgb565(_registers[RegColor0]);
        ushort color1 = ArgbToRgb565(_registers[RegColor1]);
        int color0Alpha = (int)(_registers[RegColor0] >> 24);
        int color1Alpha = (int)(_registers[RegColor1] >> 24);
        int otherAlpha = ((fbzcp >> 2) & 0x03u) switch
        {
            0 => 255,
            1 => textureAlpha,
            2 => color1Alpha,
            _ => 0
        };
        ushort other = ((fbzcp >> 0) & 0x03u) switch
        {
            0 => iteratedColor,
            1 => texel,
            2 => color1,
            _ => 0
        };
        ushort local = ((fbzcp >> 7) & 1u) != 0
            ? ((textureAlpha & 0x80) != 0 ? color0 : iteratedColor)
            : (((fbzcp >> 4) & 1u) == 0 ? iteratedColor : color0);
        int localAlpha = ((fbzcp >> 5) & 0x03u) switch
        {
            0 => 255,
            1 => color0Alpha,
            _ => 255
        };

        Rgb565ToBytes(other, out int or, out int og, out int ob);
        Rgb565ToBytes(local, out int lr, out int lg, out int lb);
        Rgb565ToBytes(texel, out int tr, out int tg, out int tb);
        int r = ((fbzcp >> 8) & 1u) == 0 ? or : 0;
        int g = ((fbzcp >> 8) & 1u) == 0 ? og : 0;
        int b = ((fbzcp >> 8) & 1u) == 0 ? ob : 0;

        if (((fbzcp >> 9) & 1u) != 0)
        {
            r -= lr;
            g -= lg;
            b -= lb;
        }

        (int mr, int mg, int mb) = ((fbzcp >> 10) & 0x07u) switch
        {
            1 => (lr, lg, lb),
            2 => (otherAlpha, otherAlpha, otherAlpha),
            3 => (localAlpha, localAlpha, localAlpha),
            4 => (textureAlpha, textureAlpha, textureAlpha),
            5 => (tr, tg, tb),
            _ => (0, 0, 0)
        };
        if (((fbzcp >> 13) & 1u) == 0)
        {
            mr = 255 - mr;
            mg = 255 - mg;
            mb = 255 - mb;
        }

        r = r * (mr + 1) / 256;
        g = g * (mg + 1) / 256;
        b = b * (mb + 1) / 256;
        switch ((fbzcp >> 14) & 0x03u)
        {
            case 1:
                r += lr;
                g += lg;
                b += lb;
                break;
            case 2:
                r += localAlpha;
                g += localAlpha;
                b += localAlpha;
                break;
        }

        if (((fbzcp >> 16) & 1u) != 0)
        {
            r = 255 - r;
            g = 255 - g;
            b = 255 - b;
        }

        return BytesToRgb565(r, g, b);
    }

    private static int Rgb565ToGrayscale8(ushort color)
    {
        Rgb565ToBytes(color, out int r, out int g, out int b);
        return (r + g + b) / 3;
    }

    private static ushort BlendRgb565(ushort destination, ushort source, int alpha)
    {
        int clampedAlpha = Math.Clamp(alpha, 0, 255);
        Rgb565ToBytes(destination, out int dr, out int dg, out int db);
        Rgb565ToBytes(source, out int sr, out int sg, out int sb);
        int inverseAlpha = 255 - clampedAlpha;
        return BytesToRgb565(
            (sr * clampedAlpha + dr * inverseAlpha + 127) / 255,
            (sg * clampedAlpha + dg * inverseAlpha + 127) / 255,
            (sb * clampedAlpha + db * inverseAlpha + 127) / 255);
    }

    private ushort GetIntegerDrawColor()
    {
        ushort color = GetIntegerDrawColorOrZero();
        return color == 0 ? GetDrawColor() : color;
    }

    private ushort GetFloatDrawColor()
    {
        ushort color = GetFloatDrawColorOrZero();
        return color == 0 ? GetDrawColor() : color;
    }

    private ushort GetIntegerDrawColorOrZero()
        => FixedColorToRgb565(_registers[0x08], _registers[0x09], _registers[0x0a]);

    private ushort GetFloatDrawColorOrZero()
        => FloatColorToRgb565(
            FloatFromRegister(_registers[0x28]),
            FloatFromRegister(_registers[0x29]),
            FloatFromRegister(_registers[0x2a]));

    private bool IsSetupFanMode()
        => ((_registers[0x98] >> 16) & 1u) != 0;

    private static float FixedVertexCoordinate(uint value)
        => unchecked((short)value) / 16.0f;

    private bool TryReadWord(int wordsNeeded, ref int source, out uint value)
    {
        if (_fixMameCommandFifoModel && ShouldStreamCommandFifoPacketWords(_currentCommandFifoCommand))
        {
            if (source >= wordsNeeded)
            {
                value = 0;
                return false;
            }

            value = ReadCommandFifoStreamingWord();
            source++;
            return true;
        }

        if (source >= wordsNeeded || source >= _fifoBuffer.Count)
        {
            value = 0;
            return false;
        }

        value = _fifoBuffer[source++];
        return true;
    }

    private bool TryReadFloat(int wordsNeeded, ref int source, out float value)
    {
        if (!TryReadWord(wordsNeeded, ref source, out uint word))
        {
            value = 0;
            return false;
        }

        value = FloatFromRegister(word);
        return true;
    }

    private bool SkipWord(int wordsNeeded, ref int source)
    {
        if (_fixMameCommandFifoModel && ShouldStreamCommandFifoPacketWords(_currentCommandFifoCommand))
        {
            if (source >= wordsNeeded)
                return false;
            _ = ReadCommandFifoStreamingWord();
            source++;
            return true;
        }

        if (source >= wordsNeeded || source >= _fifoBuffer.Count)
            return false;
        source++;
        return true;
    }

    private static int GetFifoPacketWordsNeeded(uint command)
    {
        return (command & 7u) switch
        {
            0 => ((command >> 3) & 7u) == 4u ? 2 : 1,
            1 => 1 + (int)(command >> 16),
            2 => 1 + PopCount(command >> 3),
            3 => GetFifoType3WordsNeeded(command),
            4 => 1 + PopCount((command >> 15) & 0x3fffu) + (int)(command >> 29),
            5 => 2 + (int)((command >> 3) & 0x7ffffu),
            _ => 1
        };
    }

    private static int GetFifoType3WordsNeeded(uint command)
    {
        int wordsPerVertex = 2;
        if (((command >> 28) & 1u) != 0)
        {
            if (((command >> 10) & 3u) != 0)
                wordsPerVertex++;
        }
        else
        {
            if (((command >> 10) & 1u) != 0)
                wordsPerVertex += 3;
            if (((command >> 11) & 1u) != 0)
                wordsPerVertex++;
        }

        if (((command >> 12) & 1u) != 0)
            wordsPerVertex++;
        if (((command >> 13) & 1u) != 0)
            wordsPerVertex++;
        if (((command >> 14) & 1u) != 0)
            wordsPerVertex++;
        if (((command >> 15) & 1u) != 0)
            wordsPerVertex += 2;
        if (((command >> 16) & 1u) != 0)
            wordsPerVertex++;
        if (((command >> 17) & 1u) != 0)
            wordsPerVertex += 2;

        int vertices = (int)((command >> 6) & 0xfu);
        int dummyWords = (int)(command >> 29);
        return 1 + wordsPerVertex * vertices + dummyWords;
    }

    private static int PopCount(uint value)
    {
        int count = 0;
        while (value != 0)
        {
            count += (int)(value & 1u);
            value >>= 1;
        }
        return count;
    }

    private static uint Rgb565ToBgra(ushort value)
    {
        uint r = (uint)((value >> 11) & 0x1f);
        uint g = (uint)((value >> 5) & 0x3f);
        uint b = (uint)(value & 0x1f);
        r = (r << 3) | (r >> 2);
        g = (g << 2) | (g >> 4);
        b = (b << 3) | (b >> 2);
        return 0xff000000u | (r << 16) | (g << 8) | b;
    }

    private static void Rgb565ToBytes(ushort value, out int r, out int g, out int b)
    {
        r = ((value >> 11) & 0x1f) * 255 / 31;
        g = ((value >> 5) & 0x3f) * 255 / 63;
        b = (value & 0x1f) * 255 / 31;
    }

    private static ushort BytesToRgb565(int r, int g, int b)
    {
        r = Math.Clamp(r, 0, 255);
        g = Math.Clamp(g, 0, 255);
        b = Math.Clamp(b, 0, 255);
        return (ushort)(((r >> 3) << 11) | ((g >> 2) << 5) | (b >> 3));
    }

    private static ushort ArgbToRgb565(uint value)
    {
        uint r = (value >> 16) & 0xff;
        uint g = (value >> 8) & 0xff;
        uint b = value & 0xff;
        return (ushort)(((r >> 3) << 11) | ((g >> 2) << 5) | (b >> 3));
    }

    private static ushort PackedColorToRgb565(uint value)
        => ArgbToRgb565(value);

    private static ushort FixedColorToRgb565(uint r, uint g, uint b)
    {
        int rb = FixedColorByte(r);
        int gb = FixedColorByte(g);
        int bb = FixedColorByte(b);
        return (ushort)(((rb >> 3) << 11) | ((gb >> 2) << 5) | (bb >> 3));
    }

    private static int FixedColorByte(uint value)
        => Math.Clamp(SignExtend24(value) >> 12, 0, 255);

    private static int SignExtend24(uint value)
    {
        int raw = (int)(value & 0x00ff_ffffu);
        return (raw & 0x0080_0000) != 0 ? raw | unchecked((int)0xff00_0000u) : raw;
    }

    private static ushort FloatColorToRgb565(float r, float g, float b)
    {
        if (!float.IsFinite(r) || !float.IsFinite(g) || !float.IsFinite(b))
            return 0;

        byte rb = FloatColorByte(r);
        byte gb = FloatColorByte(g);
        byte bb = FloatColorByte(b);
        return (ushort)(((rb >> 3) << 11) | ((gb >> 2) << 5) | (bb >> 3));
    }

    private static byte FloatColorByte(float value)
    {
        if (value <= 1.0f)
            value *= 255.0f;
        return (byte)Math.Clamp((int)MathF.Round(value), 0, 255);
    }

    private static float FloatFromRegister(uint value)
        => BitConverter.Int32BitsToSingle(unchecked((int)value));

    private static ushort ConvertArgb4444ToRgb565(ushort packed)
    {
        int r = ((packed >> 8) & 0x0f) * 17;
        int g = ((packed >> 4) & 0x0f) * 17;
        int b = (packed & 0x0f) * 17;
        return (ushort)(((r >> 3) << 11) | ((g >> 2) << 5) | (b >> 3));
    }

    private static ushort ConvertRgb332ToRgb565(byte value)
    {
        int r = ((value >> 5) & 0x07) * 255 / 7;
        int g = ((value >> 2) & 0x07) * 255 / 7;
        int b = (value & 0x03) * 255 / 3;
        return Rgb888ToRgb565((byte)r, (byte)g, (byte)b);
    }

    private static ushort GrayscaleToRgb565(byte value)
        => Rgb888ToRgb565(value, value, value);

    private static ushort Rgb888ToRgb565(byte r, byte g, byte b)
        => (ushort)(((r >> 3) << 11) | ((g >> 2) << 5) | (b >> 3));

    private static byte Expand6To8(int value)
    {
        int six = value & 0x3f;
        return (byte)((six << 2) | (six >> 4));
    }

    private ushort ConvertNccToRgb565(byte value, uint textureMode)
    {
        int tmu = GetTextureSampleRegisterSourceTmu();
        return ConvertNccToRgb565(tmu, value, textureMode);
    }

    private ushort ConvertNccToRgb565(int tmu, byte value, uint textureMode)
    {
        int table = (int)((textureMode >> 5) & 1u);
        int start = RegNccTable + table * 12;
        int yIndex = (value >> 4) & 0x0f;
        uint yWord = ReadTmuOrFbiRegister(tmu, start + (yIndex >> 2));
        int y = (int)((yWord >> ((yIndex & 3) * 8)) & 0xffu);
        uint iWord = ReadTmuOrFbiRegister(tmu, start + 4 + ((value >> 2) & 3));
        uint qWord = ReadTmuOrFbiRegister(tmu, start + 8 + (value & 3));
        int r = Math.Clamp(y + SignExtend9((int)(iWord >> 18)) + SignExtend9((int)(qWord >> 18)), 0, 255);
        int g = Math.Clamp(y + SignExtend9((int)(iWord >> 9)) + SignExtend9((int)(qWord >> 9)), 0, 255);
        int b = Math.Clamp(y + SignExtend9((int)iWord) + SignExtend9((int)qWord), 0, 255);
        return (ushort)(((r >> 3) << 11) | ((g >> 2) << 5) | (b >> 3));
    }

    private int GetTextureRegisterSourceTmu()
    {
        if (!_fixTmuRegisterBanks)
            return -1;
        if (_tmuRegisterValid[0][RegTextureMode])
            return 0;
        if (_tmuRegisterValid[1][RegTextureMode])
            return 1;
        return -1;
    }

    private int GetTextureSampleRegisterSourceTmu()
    {
        if ((uint)_experimentTextureSampleTmu <= 1u)
            return _experimentTextureSampleTmu;
        return GetTextureRegisterSourceTmu();
    }

    private uint ReadTmuOrFbiRegister(int tmu, int register)
    {
        if ((uint)tmu <= 1u && _tmuRegisterValid[tmu][register])
            return _tmuRegisters[tmu][register];
        return _registers[register];
    }

    private static int SignExtend9(int value)
    {
        value &= 0x1ff;
        return (value & 0x100) != 0 ? value - 0x200 : value;
    }

    private static ushort PseudoPaletteToRgb565(byte value)
    {
        int r = (value * 37 + 53) & 0xff;
        int g = (value * 73 + 97) & 0xff;
        int b = (value * 17 + 193) & 0xff;
        return (ushort)(((r >> 3) << 11) | ((g >> 2) << 5) | (b >> 3));
    }

    private readonly record struct SetupVertex(
        float X,
        float Y,
        ushort Color,
        float S,
        float T,
        float Q,
        float S1,
        float T1,
        float Q1,
        bool HasTexture)
    {
        public SetupVertex(float x, float y, ushort color, float s, float t, float q, bool hasTexture)
            : this(x, y, color, s, t, q, s, t, q, hasTexture)
        {
        }
    }

    private static void Clear(EutherFrameTarget target, uint bgra)
        => FillRect(target, 0, 0, target.Width, target.Height, bgra);

    private static void DrawRect(EutherFrameTarget target, int x, int y, int width, int height, uint bgra)
    {
        FillRect(target, x, y, width, 2, bgra);
        FillRect(target, x, y + height - 2, width, 2, bgra);
        FillRect(target, x, y, 2, height, bgra);
        FillRect(target, x + width - 2, y, 2, height, bgra);
    }

    private static void FillRect(EutherFrameTarget target, int x, int y, int width, int height, uint bgra)
    {
        int x0 = Math.Clamp(x, 0, target.Width);
        int y0 = Math.Clamp(y, 0, target.Height);
        int x1 = Math.Clamp(x + width, 0, target.Width);
        int y1 = Math.Clamp(y + height, 0, target.Height);

        for (int py = y0; py < y1; py++)
        {
            int offset = py * target.Stride + x0 * 4;
            for (int px = x0; px < x1; px++)
            {
                target.Buffer[offset + 0] = (byte)(bgra & 0xff);
                target.Buffer[offset + 1] = (byte)((bgra >> 8) & 0xff);
                target.Buffer[offset + 2] = (byte)((bgra >> 16) & 0xff);
                target.Buffer[offset + 3] = (byte)((bgra >> 24) & 0xff);
                offset += 4;
            }
        }
    }
}

internal sealed class VoodooTraceBackend : VoodooBringupBackend
{
    private readonly bool _traceRegisters = Environment.GetEnvironmentVariable("EUTHERDRIVE_GAUNTDL_TRACE_VOODOO") == "1";
    private readonly bool _traceFifo = Environment.GetEnvironmentVariable("EUTHERDRIVE_GAUNTDL_TRACE_VOODOO_FIFO") == "1";
    private readonly bool _traceInterestingFifo = Environment.GetEnvironmentVariable("EUTHERDRIVE_GAUNTDL_TRACE_VOODOO_FIFO_INTERESTING") == "1";
    private readonly bool _traceLfb = Environment.GetEnvironmentVariable("EUTHERDRIVE_GAUNTDL_TRACE_VOODOO_LFB") == "1";
    private readonly bool _traceTexture = Environment.GetEnvironmentVariable("EUTHERDRIVE_GAUNTDL_TRACE_VOODOO_TEX") == "1";
    private readonly int _registerTraceLimit = ParseTraceLimit("EUTHERDRIVE_GAUNTDL_TRACE_VOODOO_REG_LIMIT", 256);
    private readonly int _fifoTraceLimit = ParseTraceLimit("EUTHERDRIVE_GAUNTDL_TRACE_VOODOO_FIFO_LIMIT", 64);
    private readonly int _lfbTraceLimit = ParseTraceLimit("EUTHERDRIVE_GAUNTDL_TRACE_VOODOO_LFB_LIMIT", 64);
    private readonly int _textureTraceLimit = ParseTraceLimit("EUTHERDRIVE_GAUNTDL_TRACE_VOODOO_TEX_LIMIT", 64);
    private int _registerTraceCount;
    private int _fifoTraceCount;
    private int _lfbTraceCount;
    private int _textureTraceCount;

    public static bool IsEnabled()
        => Environment.GetEnvironmentVariable("EUTHERDRIVE_GAUNTDL_TRACE_VOODOO") == "1" ||
           Environment.GetEnvironmentVariable("EUTHERDRIVE_GAUNTDL_TRACE_VOODOO_FIFO") == "1" ||
           Environment.GetEnvironmentVariable("EUTHERDRIVE_GAUNTDL_TRACE_VOODOO_FIFO_INTERESTING") == "1" ||
           Environment.GetEnvironmentVariable("EUTHERDRIVE_GAUNTDL_TRACE_VOODOO_LFB") == "1" ||
           Environment.GetEnvironmentVariable("EUTHERDRIVE_GAUNTDL_TRACE_VOODOO_TEX") == "1";

    public override void WriteRegister(uint address, uint value)
    {
        base.WriteRegister(address, value);
        if (_traceRegisters && _registerTraceCount++ < _registerTraceLimit)
            Console.WriteLine($"[GAUNTDL:VOODOO] reg[{address:x8}:{DescribeRegister(address)}]={value:x8}");
    }

    public override void WriteFifo(uint wordOffset, uint value)
    {
        base.WriteFifo(wordOffset, value);
        if (_traceRegisters)
            Console.WriteLine($"[GAUNTDL:VOODOO] fifo[{wordOffset:x4}]={value:x8}");
        else if (_traceFifo && _fifoTraceCount++ < _fifoTraceLimit)
        {
            Console.WriteLine($"[GAUNTDL:VOODOO] fifo[{wordOffset:x4}]={value:x8}");
        }
        else if (_traceInterestingFifo && _fifoTraceCount < _fifoTraceLimit)
        {
            if (IsInterestingFifoWord(value, out string description))
                Console.WriteLine($"[GAUNTDL:VOODOO] fifoInteresting[{_fifoTraceCount++:x6}]@{wordOffset:x4}={value:x8} {description}");
        }
    }

    public override void WriteLfb32(uint offset, uint value)
    {
        base.WriteLfb32(offset, value);
        if ((_traceRegisters || _traceLfb) && _lfbTraceCount++ < _lfbTraceLimit)
            Console.WriteLine($"[GAUNTDL:VOODOO] lfb[{offset:x6}]={value:x8}");
    }

    public override uint ReadLfb32(uint offset)
    {
        uint value = base.ReadLfb32(offset);
        if ((_traceRegisters || _traceLfb) && _lfbTraceCount++ < _lfbTraceLimit)
            Console.WriteLine($"[GAUNTDL:VOODOO] lfbr[{offset:x6}]={value:x8}");
        return value;
    }

    public override void WriteTexture32(uint offset, uint value)
    {
        base.WriteTexture32(offset, value);
        if ((_traceRegisters || _traceTexture) && _textureTraceCount++ < _textureTraceLimit)
            Console.WriteLine($"[GAUNTDL:VOODOO] tex[{offset:x6}]={value:x8}");
    }

    public override uint ReadTexture32(uint offset)
    {
        uint value = base.ReadTexture32(offset);
        if ((_traceRegisters || _traceTexture) && _textureTraceCount++ < _textureTraceLimit)
            Console.WriteLine($"[GAUNTDL:VOODOO] texr[{offset:x6}]={value:x8}");
        return value;
    }

    private static int ParseTraceLimit(string name, int fallback)
        => int.TryParse(Environment.GetEnvironmentVariable(name), out int value) && value >= 0 ? value : fallback;

    private static string DescribeRegister(uint address)
    {
        uint register = (address >> 2) & 0x3ffu;
        return register switch
        {
            0x20 => "triangleCMD",
            0x40 => "ftriangleCMD",
            0x41 => "fbzColorPath",
            0x42 => "fogMode",
            0x43 => "alphaMode",
            0x44 => "fbzMode",
            0x45 => "lfbMode",
            0x46 => "clipLeftRight",
            0x47 => "clipLowYHighY",
            0x49 => "fastfillCMD",
            0x4a => "swapbufferCMD",
            0x4c => "zaColor",
            0x51 => "color0",
            0x52 => "color1",
            0x80 => "fbiInit4",
            0x81 => "vRetrace",
            0x83 => "videoDimensions",
            0x84 => "fbiInit0",
            0x85 => "fbiInit1",
            0x86 => "fbiInit2",
            0x87 => "fbiInit3",
            0xc0 => "textureMode",
            0xc1 => "textureLod",
            0xc3 => "textureBaseAddr",
            _ => $"0x{register:x3}"
        };
    }

    private static bool IsInterestingFifoWord(uint word, out string description)
    {
        uint type = word & 7u;
        description = "";
        switch (type)
        {
            case 1:
            {
                int count = (int)(word >> 16);
                uint target = (word >> 3) & 0xfffu;
                description = $"type1 count={count} target=0x{target:x3}";
                return count is > 0 and <= 64 && TouchesInterestingRegister(target, (uint)count);
            }
            case 3:
                description = $"type3 count={(word >> 6) & 0xfu} code={(word >> 3) & 7u}";
                return true;
            case 4:
            {
                uint target = (word >> 3) & 0xfffu;
                uint mask = (word >> 15) & 0x3fffu;
                description = $"type4 target=0x{target:x3} mask=0x{mask:x4}";
                for (uint bit = 0; bit < 14; bit++)
                {
                    if (((mask >> (int)bit) & 1u) != 0 && IsInterestingRegister(target + bit))
                        return true;
                }
                return false;
            }
            case 5:
                description = $"type5 count={(word >> 3) & 0x7ffffu} space={word >> 30}";
                return true;
            default:
                return false;
        }
    }

    private static bool TouchesInterestingRegister(uint target, uint count)
    {
        for (uint i = 0; i < count; i++)
        {
            if (IsInterestingRegister(target + i))
                return true;
        }

        return false;
    }

    private static bool IsInterestingRegister(uint register)
        => register is 0x20u or 0x40u or 0x98u or 0xa8u or 0xa9u or 0xc0u or 0xc1u or 0xc3u;
}
